import{i as e}from"./jsx-runtime-D3jfb0Ew.js";import{a as t}from"./course-CkXDBoez.js";import{n}from"./week01-DCu9Fpl2.js";var r=e({default:()=>i}),i={week:2,drivingQuestion:`AeroLink sells a door-to-door air trip, but most of what that trip depends on — vertiports, airspace, grid power, emergency response — belongs to someone else. Is AeroLink a system, an enterprise or a system of systems, whose concerns collide, and at which life-cycle decisions do those collisions have to be settled?`,blocks:[{id:`w2-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcome B-CLO1. Week 1 drew a boundary around AeroLink and showed that its behaviour emerges from interactions. Week 2 asks what kind of thing AeroLink is, who has a stake in it, where their concerns collide, and how its life is divided into stages separated by decisions. Graduate students are expected to complete the Maier analysis and the conflict analysis, not only the foundations.`],bullets:[`B2.1 (Analyse) Classify AeroLink as system, enterprise and/or system of systems (SoS), and justify the classification against stated criteria.`,`B2.2 (Apply) Identify and categorise stakeholders with interests, influence and relationships.`,`B2.3 (Analyse) Analyse conflicts between stakeholder concerns.`,`B2.4 (Understand) Explain life-cycle stages, decision gates and the purpose of technical reviews.`,`Graduate expectation: apply Maier’s definition (SEBoK v2.14, “The Enterprise as a System”, p. 832–834) to AeroLink and two real transport enterprises, with a stated boundary, cited public evidence and a reasoned verdict on each principal characteristic.`],citations:[],provenance:`instructor-authored`},{id:`w2-intuition`,kind:`intuition`,title:`Intuition: nobody owns the passenger’s journey through an airport`,paragraphs:[`Follow one passenger through a large airport. The airline sells the ticket, the airport authority owns the terminal, a security agency screens the bag, a ground-handling company loads it, air traffic control sequences the departure and a fuel company fuels the aircraft. Each organisation runs its own system with its own budget, managers and priorities, and each would keep operating if the others changed. Yet the passenger experiences one journey — and when it goes wrong, nobody is fully in charge of fixing it.`,`AeroLink sits in exactly this position. It owns aircraft and an operations centre, but a trip also needs a vertiport someone else runs, airspace someone else manages, electricity someone else supplies and, on a bad day, emergency responders someone else commands. This week gives you the vocabulary to say precisely which parts AeroLink controls, which it can only influence, and why that difference changes how the engineering must be done.`],citations:[],provenance:`instructor-authored`},{id:`w2-enterprise`,kind:`concept`,title:`What an enterprise is — and why it is not just an organisation`,paragraphs:[`SEBoK defines an enterprise as a purposeful combination — for example a network — of interdependent resources such as people, processes, organisations, supporting technologies and funding. Those resources interact with each other to coordinate functions, share information, allocate funding, create workflows and make decisions, and with their environment to achieve business and operational goals through a complex web of interactions distributed across geography and time. SEBoK then lists four further definitions; one of them (from the UK MOD) is useful for AeroLink because it allows two forms: an entity tightly bounded and directed by a single executive function, or one whose organisational boundaries are less well defined and which may have multiple owners directing the resources. Both exist to achieve specified outcomes.`,`An enterprise is not the same as an organisation, and SEBoK calls the confusion a frequent misuse of the term. An enterprise includes the organisations that take part in it but also people, knowledge and other assets — processes, policies, practices, facilities, land and intellectual property. SEBoK makes two further, separate observations: some enterprises have no readily identifiable “organisations” in them, and some enterprises are self-organising (these are not said to be the same class). Giachetti’s resolution, reported by SEBoK, is that an organisation is a view of the enterprise: the view that defines the structure and relationships of its units and actors.`,`Two further ideas matter immediately. First, an enterprise must both develop things (offerings, or internal mechanisms that enable operations) and transform itself so that it can operate effectively and survive in a competitive and constrained environment. Second, it is sometimes wise to analyse the extended enterprise: upstream suppliers, downstream consumers, end-user organisations and even “sidestream” partners and key stakeholders who collaborate, formally or informally, in delivering the product or service. AeroLink’s aircraft manufacturer (STK-011), vertiport operators (STK-005) and electric utility (STK-010) belong to its extended enterprise even though AeroLink does not own them.`,`Enterprise systems engineering (ESE) is the application of SE principles, concepts and methods to the planning, design, improvement and operation of an enterprise. SEBoK’s practical advice for ESE (after Rebovich and White) is notably different from product engineering: use enterprise fitness as the key measure of success, deal with uncertainty and conflict through adaptation and experimentation, use layered architectures with loose couplers, and shape the political, operational, economic and technical (POET) landscape rather than trying to control the enterprise as one would a project.`],quote:{text:`Some enterprises are organizations, but not all enterprises are organizations.`,cite:{reading:`R07`,pages:`815`}},citations:[{reading:`R07`,pages:`814–816`},{reading:`R07`,pages:`818`}],provenance:`mixed`},{id:`w2-sos`,kind:`concept`,title:`Systems of systems: Maier’s two independences and five characteristics; the four SoS types`,paragraphs:[`Every element of a system can itself be regarded as a system, so SEBoK points out that “system of systems” could be applied to anything and would then be a superfluous term. Maier (1998) gave it a sharper meaning: an SoS is an assemblage of components that may individually be regarded as systems and that have two additional properties. Operational independence: if the SoS were taken apart, the component systems must be able to operate usefully on their own, fulfilling customer-operator purposes. Managerial independence: the components not only can but do operate independently — they are separately acquired and integrated and keep a continuing operational existence independent of the SoS. Note the plural: the test applies to every component system, so an argument that shows only some components to be independent is incomplete.`,`SEBoK’s SoS knowledge area lists Maier’s five key characteristics — operational independence, managerial independence, geographical distribution, emergent behaviour and evolutionary development processes — and stresses that they are characteristics, not criteria. SEBoK v2.14, “The Enterprise as a System” uses the word “criteria” for the first two: it reserves the term SoS for systems that “meet the criteria of operational and managerial independence” (SEBoK v2.14, “The Enterprise as a System”, p. 833). The two statements are consistent — the two independences are the classifying criteria; the five-item list is a set of characteristics. Only the first two distinguish an SoS: a system without both is not an SoS, however complex or geographically spread its components are. Maier himself is quoted as saying that complexity and geographic distribution are “not the appropriate taxonomic classifiers”. Emergence is noted as common in SoS, particularly those built from several large existing systems, given the challenge in time and resources of exercising every logical thread across their functions, capabilities and data; unintended interactions become serious when, for example, safety is threatened.`,`The ISO/IEC/IEEE 21839 definition quoted in SEBoK puts the emphasis on purpose: an SoS is a set of systems or system elements that interact to provide a unique capability that none of the constituent systems can accomplish on its own; each constituent is a useful system by itself, with its own development, management goals and resources. SEBoK adds that forming an SoS is not necessarily permanent — it can be a matter of necessity for specific goals.`,`When an SoS is recognised and treated as a system in its own right, it can be described as one of four types. The taxonomy is not Maier’s alone: SEBoK v2.14, “The Enterprise as a System” credits the four kinds of SoS to Dahmann, Lane and Rebovich (2008), and SEBoK v2.14, “Systems of Systems (SoS)” cites Maier (1998), Dahmann and Baldwin (2008) and ISO/IEC/IEEE 21839 for it, noting that it is now presented in ISO 21841. The types differ in the degree of independence of the constituents and in where the SoS objectives come from. In a directed SoS the constituents keep the ability to operate independently but their normal operational mode is subordinated to the centrally managed purpose. An acknowledged SoS has recognised objectives, a designated manager and resources, while the constituents keep their own ownership, objectives, funding and development, and changes rest on cooperative agreements. In a collaborative SoS the constituents interact more or less voluntarily to fulfil agreed central purposes. A virtual SoS has neither a central management authority nor a centrally agreed purpose; large-scale behaviour emerges and is maintained by relatively invisible mechanisms. Real SoS usually combine types and change type over time, and many exist unrecognised until something makes them significant — SEBoK calls these “discovered” SoS.`],citations:[{reading:`R08`,pages:`832–833`},{reading:`R09`,pages:`866–869`}],provenance:`mixed`},{id:`w2-lifecycle`,kind:`concept`,title:`Life cycles, stages and decision gates`,paragraphs:[`A life cycle is the evolution of a system, product, service, project or other human-made entity from conception through retirement. A life-cycle model is a framework of processes and activities, organised into stages, that acts as a common reference for communication and understanding. SEBoK names six generic stages and their primary goals: concept (identify stakeholders’ needs, explore concepts, propose viable solutions); development (refine system requirements, create the solution description, build the system, perform verification and validation); production (produce systems, inspect and test); utilization (operate the system to satisfy users’ needs); support (provide sustained capability); and retirement (store, archive or dispose).`,`Stages are not a calendar. Some life-cycle models permit iteration and concurrency of stages and some do not, and a system of interest can be in several stages at once. SEBoK’s example makes this concrete: for a product made in many units, utilization and support begin with the first unit; software support begins during development; retirement begins when the first unit is retired or lost; and a planned mid-life upgrade restarts the concept, development and production stages while the fleet keeps flying. Different elements may also follow different models: DevOps and DevSecOps draw the life cycle as an infinity loop in which development and support are not distinguished and the work is never “done”. Some published models are project models (phases of a project), not life-cycle models (stages of a system).`,`Movement between stages is a milestone or decision point with specific entry and exit criteria. Decision-making reviews, or gates, inform progression between stages to reduce risk and enable satisfactory progress. At a gate the actual progress is evaluated against the criteria for that stage — or for an increment that can proceed independently — and the review generally looks two ways: backwards at progress to date and forwards at preparedness to continue. Not every part of a system of interest reaches the same maturity at the same time, so interim maturity reviews are needed, and entry and exit criteria must be tailored: one size does not fit all. Criteria can be met before, with, after or never relative to the decision, and SEBoK notes that decision criteria can include an assessment of technical debt, which can accumulate in any stage.`,`A gate has five possible outcomes: begin another stage or stages; continue this stage; go to or restart another stage; pause activity; or terminate. Two of the five stop or suspend work. A gate whose only acceptable outcome is “proceed” is a ceremony, not a decision. In two-party acquisitions, joint stakeholder reviews between the parties to the agreement can support the gates.`],citations:[{reading:`R06a`,pages:`380–382`},{reading:`R06b`,pages:`384–385`}],provenance:`mixed`},{id:`w2-reviews`,kind:`concept`,title:`Technical reviews and audits: what they are for and how they go wrong`,paragraphs:[`SEBoK describes technical reviews and audits as a mechanism by which sufficiently independent and knowledgeable stakeholders analyse the current state of a system or work products against pre-established criteria, to support programmatic and technical decisions. A technical review is a series of SE activities at logical transition points in the life cycle that assesses a project’s progress against its technical requirements using mutually agreed criteria; an audit is an independent examination of work products for compliance with specifications, standards, agreements or other criteria. Organisations use these and other terms differently.`,`Reviews serve three processes. In project assessment and control they give visibility of technical progress and risk and support gates by establishing readiness to proceed. In configuration management they help establish, revise and verify baselines. In validation, involving the right stakeholders — including end users — lets requirements and designs be validated early. Reviews can be applied to a whole system, to an element, or recursively to constituents, and can also authorise risky activities such as tests with safety or security concerns.`,`Preparation balances the business case or mission, the budget and technical maturity including risk. Because the proceed decision can carry great uncertainty, assumptions and identified risks should be documented. Entry and exit criteria should be defined and the entry criteria confirmed before the review is held. Boehm and Lane distinguish three types of review by their trigger: schedule-based (explicit dates; early, frequent feedback but the risk of too little information), event-based (end of a phase with defined artefacts delivered; more complete information but the risk of insufficient analysis and unresolved issues), and evidence-based (reaching a specific technical risk level shown by evidence; higher chance of stakeholder commitment but the risk of late feedback on latent defects). Any of them can be undermined when schedule or cost pressure forces a review to be held unprepared.`,`Choosing reviewers is a real design decision. People “too close” to the project may be biased; people “too far away” may miss the critical issues. SEBoK recommends a mix of both. Reviews should be tailored to the organisation, domain and life cycle; SEBoK points to the US DoD Systems Engineering Guidebook, NATO AAP-48, NASA NPR 7123.1D and the Incremental Commitment Spiral Model as examples. In this course you will hold an SRR-style review in Week 5 and a PDR-style review in Week 10; those names come from the course plan, and the readings this week do not define them.`],citations:[{reading:`R06c`,pages:`386–388`}],provenance:`mixed`},{id:`w2-stakeholders`,kind:`concept`,title:`Identifying and assessing stakeholders`,paragraphs:[`MITRE frames stakeholder management as identifying stakeholder groups, the interests they represent and the power they possess, and determining whether they inhibit or support the change; its objective is to decide who the stakeholders are and how they should be dealt with. Engineers are expected to identify both directly and indirectly affected stakeholders, assess the impact of change on people and organisations, identify and rank the risks of the change and recommend mitigations.`,`Identification must be deliberately wide. MITRE lists the key groups for a change: decision makers; change sponsors and agents responsible for executing it; employees and contractors directly affected; the “customers” of the change agents; and representatives of every group, at headquarters and in the field. Geographic distribution of stakeholder groups matters if the full range of perspectives is to be heard. The sponsor’s list is only a starting point: interviewees should be asked for further names and organisations, and the assessment should actively seek supporters, skeptics and rivals of the initiative. (Course note: a customer-only list is scored at the bottom level of RB-1.2.)`,`Data come from one-on-one interviews, focus groups and surveys, with open-ended and Likert-scaled questions. Likert scales assign a quantitative value to qualitative information; MITRE acknowledges the inherent variance but finds them useful. The analysis produces stakeholder maps that show the relative influence and the level of support of each group — on a scale from awareness through understanding and buy-in to commitment — and compares the current with the required level. MITRE’s maps carry a pointed message: stakeholders with high influence must be moved toward commitment, because high influencers must be committed advocates. Findings should highlight differences across groups rather than generalise, ground themes in specific evidence, and end with recommendations or next steps.`,`One observation from MITRE’s practice deserves to be remembered. MITRE is writing about a sponsor’s own organisation: before an assessment, sponsors may perceive a group of their people as resistant; afterwards they may realise the perceived resistance was really a lack of understanding of the rationale for the change and how to put it into practice. Extending this to an external group is this course’s application, not MITRE’s guidance: for AeroLink, a community objection (STK-004) should first be analysed — is it a genuine conflict of concerns, or missing information? — before it is treated as opposition.`],citations:[{reading:`R63`,pages:`234–238`}],provenance:`mixed`},{id:`w2-worked-maier`,kind:`worked-example`,title:`Worked example (graduate): applying Maier’s definition to three AeroLink boundaries and two comparison cases`,paragraphs:[`The question is not “is AeroLink big and complicated?” but “do its components have operational and managerial independence?”. The method: (1) fix the boundary first, because the verdict depends on it; (2) rate the two principal characteristics with evidence, testing operational independence in both directions — every component system, including AeroLink’s own, must be able to operate usefully on its own (SEBoK v2.14, “The Enterprise as a System”, p. 832); (3) rate the other three, knowing they cannot change the verdict; (4) if it is an SoS, find where its objectives come from and who manages it, to choose a type. The source supplies the rule (SEBoK v2.14, “The Enterprise as a System”, p. 832–833; SEBoK v2.14, “Systems of Systems (SoS)”, p. 866) and the type definitions (SEBoK v2.14, “Systems of Systems (SoS)”, p. 868–869); the ratings below are the instructor’s engineering judgement on FICTIONAL case descriptions, they are arguable where marked “partly”, and where a rating rests on a FICTIONAL premise the premise is stated.`,`Boundary A — AeroLink’s own operation: fleet, operations centre, maintenance facility and booking app, all acquired and managed by AeroLink. This is deliberately narrower than Week 1’s ENT-001, which also contains the partner-owned vertiports and chargers; boundary A is drawn for this week’s question (“who acquires and manages each component?”), not for Week 1’s waiting-time question. Operational independence is at best partial: an aircraft could fly a useful trip alone, but the dispatch software and booking app have no use without the fleet. Managerial independence is absent: nothing in this boundary has an operational existence outside AeroLink. Verdict: not an SoS. Geographic distribution across six vertiports and emergent throughput (Week 1) are present but, as SEBoK v2.14, “The Enterprise as a System”, p. 833 says, not taxonomic classifiers. SEBoK goes further: a key purpose of an enterprise is to establish operational dependence between the systems it owns and operates, so it is more proper to treat an enterprise and an SoS as different kinds of thing (SEBoK v2.14, “The Enterprise as a System”, p. 833). Inside boundary A, AeroLink is a system and an enterprise.`,`Week 1’s ENT-001, unchanged — fleet, vertiports and chargers, operations centre and demand — gives a different answer, and that is the point of fixing the boundary first. The vertiports are owned and run by independent operators (STK-005): they could host other operators and they keep an existence outside AeroLink, so for that one kind of component both independences hold, while for everything else they do not. Both principal characteristics are therefore “partly”, and Maier’s rule gives a borderline case that has to be argued. The instructor’s argument: ENT-001 is an enterprise that has drawn one independent partner inside its boundary precisely to create operational dependence on it (SEBoK v2.14, “The Enterprise as a System”, p. 833), so “not an SoS — an enterprise with an independently owned partner” is the better-supported conclusion; “borderline” with that argument earns the same credit.`,`Boundary B — the regional urban-air-mobility service: AeroLink plus independently owned vertiports (STK-005), the air navigation service provider’s airspace system (STK-007), the electric grid (STK-010) and emergency response (STK-006). Operational independence must hold both ways. The partners are useful without AeroLink: the grid serves the city, the airspace system serves every airspace user, emergency services serve everyone, and — a FICTIONAL premise — the vertiports also host helicopter and medical-transport flights by other operators. AeroLink must also be useful without the partners, and the observation that dispatch software is useless without the fleet does not settle that, because the constituent here is AeroLink’s whole operation. The case therefore states a second FICTIONAL premise: AeroLink holds its own operating approval and a base pad at its maintenance facility, from which it flies charter and medical-cargo work that uses no partner vertiport. Disassembling the SoS removes its integration, not the ordinary air-traffic and grid services that any operator buys. With both premises, operational independence holds; without the base-pad premise the honest rating is “partly” and the case is borderline. Each constituent is separately owned, funded and managed, so managerial independence holds. The end-to-end trip is a capability none of them provides alone — the ISO 21839 notion of an SoS. Verdict: an SoS. The parties have signed a memorandum agreeing a common purpose but coordinate through a working group with no budget or authority (FICTIONAL), so it is collaborative. If the city funded a mobility office with a designated manager while the constituents kept their own ownership and funding, it would become acknowledged — and SEBoK v2.14, “Systems of Systems (SoS)”, p. 869 warns that types combine and change over time.`,`The comparison cases complete the argument. A single-operator metro line is large, distributed and full of emergent behaviour, yet nothing in it is managerially independent: not an SoS — the counter-example to “every big system is an SoS”. An open multimodal travel ecosystem of independent bus, bike-share and ride-hail firms and general-purpose map apps has both independences — each operator runs a useful service, and the map apps (FICTIONAL premise) give walking and driving directions without any operator’s data, whereas journey-planner apps with no use beyond the operators’ timetables would fail the test — but it has no central authority and no agreed purpose: a virtual SoS, held together by invisible mechanisms such as shared data formats. These cases are FICTIONAL teaching cases; they may not be used as either of the two real enterprises in the memo. The engineering consequence is the point of the exercise: AeroLink can apply traditional SE inside boundary A, but the capability it sells exists only in boundary B, which it does not control (SEBoK v2.14, “The Enterprise as a System”, p. 834).`],table:{caption:`Maier analysis of five cases (instructor key; case descriptions and the premises they rest on are FICTIONAL). OI = operational independence, MI = managerial independence.`,header:[`Characteristic`,`A: AeroLink’s own operation`,`ENT-001 (Week 1 boundary)`,`B: Regional UAM service`,`Metro line (single operator)`,`Multimodal ecosystem`],rows:[[`OI (principal)`,`Partly — aircraft yes, dispatch and booking no`,`Partly — vertiports yes, AeroLink’s dispatch and booking no`,`Yes, both ways — partners useful without AeroLink; AeroLink useful without partner vertiports (base-pad premise)`,`No`,`Yes — operators and map apps each useful alone (map-app premise)`],[`MI (principal)`,`No — all acquired and managed by AeroLink`,`Partly — only the vertiports are separately managed`,`Yes — separately owned, funded, managed`,`No`,`Yes`],[`Geographic distribution`,`Yes`,`Yes`,`Yes`,`Yes`,`Yes`],[`Emergent behaviour`,`Yes (throughput, waiting)`,`Yes (waiting time)`,`Yes (end-to-end trip)`,`Yes (line capacity)`,`Yes (door-to-door journeys)`],[`Evolutionary development`,`Partly — one owner’s plan`,`Partly`,`Yes — constituents change on own cycles`,`Partly`,`Yes`],[`Verdict`,`Not an SoS: system and enterprise`,`Borderline; best argued as an enterprise, not an SoS`,`SoS`,`Not an SoS: system`,`SoS`],[`Type (SEBoK v2.14, “Systems of Systems (SoS)”, p. 868–869)`,`—`,`—`,`Collaborative (agreed purpose, no manager)`,`—`,`Virtual (no agreed purpose, no authority)`]]},citations:[{reading:`R08`,pages:`832–834`},{reading:`R09`,pages:`866–869`}],provenance:`mixed`},{id:`w2-worked-conflicts`,kind:`worked-example`,title:`Worked example: deriving and ranking stakeholder conflicts for AeroLink`,paragraphs:[`A conflict list written from intuition tends to name the obvious pair (communities versus noise) and miss the rest. A more rigorous method derives conflicts from structure. Step 1: choose decision variables the enterprise actually controls or negotiates — here daily operating hours (16 h, Data Sheet), departures per pad per hour (6, a new FICTIONAL value that is not on the Data Sheet), chargers per vertiport, which sets the peak power drawn from the grid (2, Data Sheet), ticket price, and the number of vertiport sites in residential districts (2 of 6, FICTIONAL). Step 2: choose the stakeholders and say which you left out. The matrix uses nine of the fourteen reference stakeholders, including the influence-5 air navigation service provider (STK-007), whose capacity limits gate schedule density; it leaves out the FAA (STK-002), whose concern sets safety limits on every variable rather than a preferred direction, and four stakeholders whose concerns bear mainly on other variables (STK-009, 011, 012, 014). Step 3: read each concern in the reference map and record whether the stakeholder wants each variable raised (↑), lowered (↓) or has no direct stake. Step 4: every ↑/↓ pair on the same variable is a conflict. Step 5: rank conflicts by a conflict weight, the product of the two influence ratings (1–5) from the reference map. This is a course measure, not stakeholder “salience” in the established sense of Mitchell, Agle and Wood (1997; listed among The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”’s references, p.238), which rests on power, legitimacy and urgency. Steps 4 and 5 are mechanical; steps 1–3 are judgement and must be defended from the concern text. The method is instructor-authored; The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management” supplies the idea of mapping influence and support and of highlighting differences across groups rather than generalising (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 236–237).`,`Within that scope, the instructor key yields 28 conflicts. Two tie for the highest weight, 25: Investors (STK-003, influence 5) want more departures per pad-hour while the ANSP (STK-007, influence 5) wants fewer, and Investors want more residential sites while the City planning authority (STK-013, influence 5) wants fewer. Six conflicts follow at 20. Grouping by stakeholder pair is more revealing than any single row: Investors and Communities (STK-004) conflict on four of the five variables — hours, departures, price and siting — for a total weight of 80. That is not a disagreement about one parameter that a trade can settle; it is a structural conflict between a throughput-driven business model and the neighbourhood that absorbs its externalities. Communities appear in the top three pairs (80, 48, 36), so within this selection STK-004 is the hub of the conflict network; a matrix with other stakeholders or variables could move the hub, and the claim must be reported with its scope.`,`Two checks keep the analysis honest. Sensitivity: the influence ratings are FICTIONAL and ordinal, so test whether the conclusion survives a change. If Communities’ influence were 3 rather than 4, the Investors–Communities total falls to 60 but remains first (the next pair falls to 36). The ranking is robust to that change; a conclusion that flipped would have to be reported as fragile. Evidence: before treating STK-004 as opposed, ask whether the objection is a genuine incompatibility of concerns or an information gap — the course’s application of MITRE’s observation that perceived resistance may turn out to be a lack of understanding (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 238); the L2 lab asks you to record which conflicts are which.`,`The output feeds directly forward. Each conflict becomes a pair of CON items that Week 3 turns into competing need statements, Week 7 turns into trade-study criteria and Week 6 records as risks. The reference model already carries one such risk from the noise conflict, R-003 (pad-edge noise above the agreed limit), and the L2 answer key adds a siting risk under the next free ID, R-009, written in condition–if–then form. Resolving a conflict is a design and governance task, not a vote: options include quieter approach paths, curfews traded against more sites, and early engagement through the existing planning-consultation relationship (REL-007, City planning authority and Communities).`],table:{caption:`Highest-weight conflicts and pairs from the instructor key (nine-stakeholder scope; influence ratings are FICTIONAL reference values; weight = influence × influence)`,header:[`Rank`,`Variable or pair`,`Wants more (↑)`,`Wants less (↓)`,`Conflict weight`],rows:[[`1=`,`V2 departures per pad-hour`,`STK-003 Investors (5)`,`STK-007 ANSP (5)`,`25`],[`1=`,`V5 residential sites`,`STK-003 Investors (5)`,`STK-013 City planning (5)`,`25`],[`3=`,`V1, V2, V4, V5 (four rows)`,`STK-003 Investors (5)`,`STK-004 Communities (4)`,`20 each`],[`3=`,`V5 residential sites`,`STK-005 Vertiport operators (4)`,`STK-013 City planning (5)`,`20`],[`3=`,`V2 departures per pad-hour`,`STK-005 Vertiport operators (4)`,`STK-007 ANSP (5)`,`20`],[`Pair 1`,`STK-003 ↔ STK-004 on 4 of 5 variables`,`—`,`—`,`80 total`],[`Pair 2`,`STK-004 ↔ STK-005 on V1, V2, V5`,`—`,`—`,`48 total`],[`Pair 3`,`STK-001 ↔ STK-004 on V1, V2, V5`,`—`,`—`,`36 total`],[`Pair 4`,`STK-003 ↔ STK-008 on V1, V2`,`—`,`—`,`30 total`]]},citations:[{reading:`R63`,pages:`236–238`}],provenance:`mixed`},{id:`w2-advanced`,kind:`advanced`,title:`Advanced analysis: engineering a capability you do not control`,paragraphs:[`SEBoK describes the situation AeroLink is in. An enterprise may need an operational capability that only a chain of systems can provide; no single system in the chain can provide it, so the capability is an emergent property of the chain — sometimes called an SoS. The enterprise that needs the capability rarely has direct control over all the systems in the chain. Traditional SE can be applied to each system, but it must be augmented with activities that handle SoS and enterprise issues (SEBoK v2.14, “The Enterprise as a System”, p. 834).`,`SEBoK v2.14, “Systems of Systems (SoS)” makes the augmentation concrete by showing how SE processes change for an SoS and by cataloguing the INCOSE SoS working group’s pain points. There is often no top-level SoS authority, so effective agreements among the systems may be key to success. Leadership must come from influence and incentives rather than structured control. Constituents were often built for other purposes and keep commitments to other users, so they may support the SoS only partly and may drift away from it over time. SoS capability needs may not match the constituents’ own requirements, which effectively asks them to take on new requirements with the SoS acting as the “user”. Independent change and interdependence produce unexpected SoS-level behaviour even when each constituent is well understood. End-to-end testing may lack funding or authority and be impossible across asynchronous development cycles, so performance often has to be measured from operations or estimated by modelling, simulation and analysis (SEBoK v2.14, “Systems of Systems (SoS)”, p. 867–868).`,`Applied to AeroLink (instructor analysis): the electric utility (STK-010) has its own peak-load concern and other customers, so “enough charging power at 07:30” is a requirement AeroLink can only negotiate, not impose; the air navigation service provider (STK-007) belongs to the air traffic management SoS, which SEBoK cites as an example of a persistent SoS acquired and qualified in a well-defined environment, where any evolution implies formal SE evolution and re-qualification (SEBoK v2.14, “Systems of Systems (SoS)”, p. 869). AeroLink’s schedule density is therefore gated by someone else’s life cycle. This is why the Week 2 stakeholder map records relationships and conflicts and not just names, why Week 6 treats partner commitments as AROU items, and why the Week 13 impact analysis must follow links that leave AeroLink’s own boundary.`,`Two further lenses sharpen the analysis. SEBoK’s federation of systems — a “coalition of the willing” with very limited central control, rated high on autonomy, heterogeneity and dispersion — warns that an enterprise is not necessarily an FoS, because an enterprise can have components that are tightly coupled, homogeneous and close together (SEBoK v2.14, “The Enterprise as a System”, p. 833). And ESE practice advises shaping the political, operational, economic and technical landscape rather than trying to control the enterprise as a project would (SEBoK v2.14, “Enterprise Systems Engineering”, p. 818). For an engineer the practical rule is: inside boundary A, specify; across boundary B, negotiate, instrument and monitor.`],citations:[{reading:`R08`,pages:`833–834`},{reading:`R09`,pages:`867–869`},{reading:`R07`,pages:`818`}],provenance:`mixed`},{id:`w2-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`SoS engineering began in space systems and defence and now extends across civil and commercial domains; SEBoK reports a review of IEEE SoS papers from 2021–2023 in which transportation was the most frequent named application area after defence (22 papers, 13.1 %). Three ISO/IEC/IEEE standards now address SoS: 21839 sets out considerations at key life-cycle stages for a constituent system that will interact in an SoS (treating that constituent as the system of interest); 21840 gives guidance on applying ISO/IEC/IEEE 15288 to SoS and is not a self-contained replacement for it; 21841 defines a normalised SoS taxonomy for communication among stakeholders (SEBoK v2.14, “Systems of Systems (SoS)”, p. 870–872).`,`For AeroLink, 21839’s framing is the useful one: AeroLink’s aircraft and operations centre are constituents that must be engineered for an SoS they will join, so SoS considerations belong at each AeroLink life-cycle gate, not only at the end. Life-cycle models can also differ by element: AeroLink’s booking and dispatch software may follow a DevSecOps loop while its aircraft follow a staged model with a mid-life upgrade (SEBoK v2.14, “Life Cycle Models”, p. 381–382). Reviews and gates must be tailored to that mix; SEBoK lists DoD, NATO and NASA guidance and the Incremental Commitment Spiral Model as examples to tailor from, never to copy unchanged (SEBoK v2.14, “Technical Reviews and Audits”, p. 388).`],citations:[{reading:`R09`,pages:`870–872`},{reading:`R06a`,pages:`381–382`},{reading:`R06c`,pages:`388`}],provenance:`mixed`},{id:`w2-lab`,kind:`lab`,title:`Lab L2 — stakeholder ecosystem map and AROU v0`,paragraphs:[`In teams, in the stakeholder editor: start from the six external entities named in the lab sheet (STK-001..006) and your L1 EXT list; brainstorm further stakeholders (AI suggestions allowed, tagged AI-suggested-reviewed); classify them so that all six S04 classes are covered; give every stakeholder a specific concern, interest and influence ratings and a rationale; record at least five stakeholder-to-stakeholder relationships including at least one conflict; explain at least one feedback or emergent effect across stakeholders with a causal argument; then record concerns and AROU v0 (at least four entries) with the recorder below, which writes them into your engineering workspace with a provenance tag. Use the conflict matrix above to derive your conflicts rather than guess them.`],citations:[],provenance:`instructor-authored`},{id:`w2-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: the L2 record (stakeholder map export, concerns, relationship list, conflict analysis, causal argument, AROU v0), scored formatively against RB-1.2–1.5 now and summatively at CP1 in Week 3. Individual: readiness quiz Q2, review-notebook entry 2 with a time log, and the graduate Maier memo (one page plus an evidence table), which the instructor always reads and scores on RB-1.1 (boundary and context, B-CLO1).`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w2-act-sos`,title:`SoS classifier: Maier’s characteristics and SoS types`,component:`w02-sos-classifier`,purpose:`Classify AeroLink under three boundaries (its own operation, Week 1’s ENT-001, the regional service) and two comparison cases against Maier’s definition and the four SoS types, and see whether your verdict follows from your own ratings.`,instructions:[`For each case, rate the five characteristics before reading the instructor key. Test operational independence in both directions: could every component, AeroLink’s included, operate usefully on its own?`,`State your verdict. The tool tells you what Maier’s rule implies from your own ratings — a verdict that does not follow is flagged, and a “partly” rating argued down to “not an SoS” is accepted only with an explicit argument.`,`If you call a case an SoS, answer the three governance questions and choose a type.`,`Record one rating you disagree with in your memo, with the evidence that would change it.`],objectives:[`B2.1`],inBlock:`w2-worked-maier`},{id:`w2-act-lifecycle`,title:`Life-cycle stages, gate decisions and review triggers`,component:`w02-lifecycle-gates`,purpose:`Place AeroLink activities in life-cycle stages, make five gate decisions, and classify three reviews by trigger.`,instructions:[`Part A: choose the stage whose primary goal each activity serves; note which items show stages running concurrently.`,`Part B: for each gate, decide using one of SEBoK’s five options, and write in the box what evidence would change your decision.`,`Part C: classify each review as schedule-, event- or evidence-based and write the risk you would guard against; the Boehm and Lane risks appear after you check.`,`Your written answers are kept in this browser only: copy them into your review notebook entry.`],objectives:[`B2.4`],inBlock:`w2-reviews`},{id:`w2-act-conflicts`,title:`Stakeholder-conflict matrix and support gap`,component:`w02-conflict-matrix`,purpose:`Derive conflicts between nine reference stakeholders from their concerns, rank them by conflict weight, and find the stakeholders whose support most needs to move.`,instructions:[`Read the scope line first: which stakeholders are in the matrix, which are left out and why.`,`Fill each cell from the stakeholder’s concern text: wants more, wants less, or no direct stake.`,`Read the computed conflicts and the pair summary. Which pair is structural, and which single conflicts are sharpest?`,`Compare with the instructor key and justify, in your L2 record, any cell where you disagree.`,`Part B: estimate current support and read off the engagement priorities.`],objectives:[`B2.2`,`B2.3`],inBlock:`w2-worked-conflicts`},{id:`w2-act-register`,title:`Concern and AROU v0 recorder`,component:`w02-concern-arou`,purpose:`Record each stakeholder’s concern (CON) and the AROU v0 entries in the shared AeroLink workspace with stable IDs, trace links and a provenance tag, checked against the L2 acceptance rules.`,instructions:[`Create your stakeholders in the stakeholder editor first; they appear here automatically.`,`Record at least one specific concern per stakeholder. The recorder rejects concerns that name nothing beyond a general quality (“The community is concerned about noise.”); a reviewer still judges whether an accepted concern is specific enough.`,`Record at least four AROU entries, each affecting a stakeholder or a concern. Write risks as condition–if–then (“Given …, if …, then …”): the recorder checks that a condition clause comes before the if–then, not whether the condition is true.`,`Give every entry its owner’s initials and a provenance tag (team-derived, team assumption, AI-suggested-reviewed or cited); for an AI-suggested entry, record in the AI usage statement what the tool suggested and what you changed or rejected.`,`Use the coverage line as your L2 checklist.`],objectives:[`B2.2`],inBlock:`w2-lab`}],lab:{id:`L2`,title:`Stakeholder ecosystem map; AROU v0`,setting:`team`,durationMinutes:75,objectives:[`B2.2`,`B2.3`],inputs:[`L1 record: ENT-001 boundary statement, EXT list and the two Week 1 loops`,`Stakeholder ecosystem editor, pre-seeded with the six external entities of S04 Lab 2A (STK-001..006)`,`AeroLink Data Sheet (FICTIONAL values)`,`Conflict-matrix activity (this week)`],steps:[{title:`Brainstorm`,detail:`Starting from STK-001..006 and every organisation on your L1 EXT list, brainstorm stakeholders. Ask “who is affected but not consulted?” and “who could stop us?” (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 235: supporters, skeptics and rivals). AI suggestions are allowed; tag each AI-suggested-reviewed (in the editor, start the rationale with “AI-suggested-reviewed:”) and record what you rejected.`},{title:`Classify`,detail:`Enter at least 12 stakeholders in the editor across at least four categories (the L2 minimum). For the top level of RB-1.2, cover all six S04 classes — the categories of the six S04 Lab 2A entities: customers and users, regulators and authorities, investors and finance, community and public, infrastructure and partners, emergency and public safety — and include non-obvious stakeholders (maintainers, emergency responders, community groups) with a one-line reason for inclusion.`},{title:`Characterise`,detail:`For each stakeholder: a specific concern (not “wants safety”), interest and influence ratings (1–5) and a rationale for the ratings. Record each concern as a CON item with the concern-and-AROU recorder in this lab block; it derives each CON from its STK and rejects concerns that name only a general quality.`},{title:`Relationships and conflicts`,detail:`Add at least five stakeholder-to-stakeholder relationships in the editor, including at least one “has conflicting concerns with”. Use the conflict matrix to derive conflicts, and add any stakeholder you judge relevant that the matrix leaves out; for the top two conflicts, state whether each is a genuine incompatibility of concerns or an information gap.`},{title:`Causal argument`,detail:`For the top level of RB-1.4, explain at least one feedback or emergent effect that runs across stakeholders, as a causal chain with link polarities. Start from one of your Week 1 loops and extend it through at least two stakeholders from your map (for example, how a change in departures reaches residents, the planning authority and investors, and back). Say whether the loop is reinforcing or balancing and why.`},{title:`AROU v0`,detail:`Record at least four assumption, risk, opportunity or unknown entries (A-, R-, O-, U-nnn) with the recorder, each linked by “affects” to a stakeholder or concern and tagged with its provenance. Write risks as condition–if–then; the recorder checks that the statement has a condition clause before “if … then”, and a reviewer checks the content.`},{title:`Check and export`,detail:`Run the editor’s acceptance checks until all pass, export the map (JSON), confirm the recorder’s coverage line (every STK has a CON; ≥ 4 AROU entries, all linked to a stakeholder or concern) and add the export, both lists and the causal argument to the L2 record.`}],artefacts:[{idPrefix:`STK`,description:`Stakeholders with category, concern, interest, influence and rationale`,minimum:`≥ 12 STK in ≥ 4 categories, including STK-001..006 (all six S04 classes for RB-1.2 level 4)`},{idPrefix:`CON`,description:`Stakeholder concerns, each derived from an STK`,minimum:`≥ 1 CON per STK`},{idPrefix:`REL`,description:`Stakeholder-to-stakeholder relationships (editor-local IDs: REL and the editor’s relationship types, such as conflicts-with, regulates and funds, are not part of the course ID scheme or its relationship list)`,minimum:`≥ 5, including ≥ 1 conflict`},{idPrefix:`A/R/O/U`,description:`AROU v0 entries linked to stakeholders or concerns, each with a provenance tag`,minimum:`≥ 4 entries`}],continuity:`STK and CON items are the roots of the digital thread: Week 3 needs (NEED) must each trace to at least one STK or CON, and CP1 at the end of Week 3 scores this map with RB-1. Conflicts become competing needs in Week 3 and trade-study criteria in Week 7; AROU v0 grows to AROU v2 by Week 6; in Week 9 stakeholders and concerns become SysML v2 stakeholder and concern usages in the model.`,tools:[{label:`Stakeholder ecosystem editor`,to:`/workspace/stakeholders`},{label:`Air Taxi Enterprise workspace (case brief and Data Sheet)`,to:`/workspace/aerolink`}]},assignment:{id:`W2-A`,title:`L2 record and graduate Maier memo`,mode:`individual`,due:`Before the first session of Week 3`,weight:`Mixed submission: the L2 record is a team deliverable (formative now, scored at CP1, 7 %, RB-1 45 %) and the memo is individual. The memo is review-notebook entry 2 (RB-16, 5 %): as a graduate weekly task it is a required entry that is always read, not sampled (RB-16 note), and it receives formative feedback on RB-1.1 (boundary and context, B-CLO1), returned before CP1.`,instructions:[`Team: submit the L2 record (editor export with all acceptance checks passing, CON list, relationship list, conflict analysis, causal argument, AROU v0).`,`Individual: write a one-page memo plus an evidence table applying Maier’s definition (SEBoK v2.14, “The Enterprise as a System”, p. 832–834; SEBoK v2.14, “Systems of Systems (SoS)”, p. 866) to AeroLink and to two real transport enterprises of your choice (for example a metro or rail operator, an airport, an airline alliance or a city’s shared-mobility scheme). The instructor reads every memo.`,`For each real enterprise, find and cite public evidence (the organisation’s own reports or website, regulator or government documents) for its boundary and for both principal characteristics: at least one cited fact per rating. The course collection contains no sources on real operators, so every claim about them must carry your citation; unsupported claims lose credit. The FICTIONAL comparison cases in the worked example may not be used as either enterprise.`,`State the boundary before each verdict; test operational independence in both directions (could every component, not only the partners, operate usefully alone?); give a type for any SoS (SEBoK v2.14, “Systems of Systems (SoS)”, p. 868–869).`,`For AeroLink, say which boundary you classify (boundary A, ENT-001 or boundary B) and analyse all five characteristics. For the real enterprises, the evidence table covers the boundary, the two principal characteristics, the verdict and the type.`,`Close with one life-cycle implication: at which gate would AeroLink’s dependence on systems it does not control be decided, and what criterion would you add (SEBoK v2.14, “Life Cycle Stages”, p. 384–385)?`,`Log your hours for the week in the review notebook (workload pilot).`],template:[{heading:`1. Boundaries`,guidance:`For AeroLink and each real enterprise, state the boundary you classify in one sentence, and say why the verdict depends on it (RB-1.1).`},{heading:`2. Evidence table (real enterprises)`,guidance:`One row per enterprise: boundary; operational independence in both directions, with a cited fact; managerial independence (who acquires, funds and manages each component), with a cited fact; verdict; type and the governance evidence for it. Cite every fact.`},{heading:`3. AeroLink analysis`,guidance:`All five characteristics for the AeroLink boundary you chose, rated yes / partly / no with evidence; an explicit statement of why the three non-principal characteristics do not decide the verdict (SEBoK v2.14, “The Enterprise as a System”, p. 833); verdict, type, and how the type could change.`},{heading:`4. Engineering and life-cycle consequence`,guidance:`What changes for AeroLink because part of its capability lies in an SoS it does not control (SEBoK v2.14, “The Enterprise as a System”, p. 834; SEBoK v2.14, “Systems of Systems (SoS)”, p. 867–868)? Name at least two stakeholders by STK ID. Then the gate and the entry or exit criterion you would add, and which of the five decision options you expect if it is not met.`},{heading:`5. AI usage statement`,guidance:`Tool, purpose, prompts, what you accepted or rejected and why (RB-12). Any AI-supplied fact about a real enterprise must be traced to a source you checked, or removed.`}],rubrics:[`RB-1`,`RB-16`,`RB-12`],rubricScope:`L2 record (team): RB-1.2–1.5 (formative feedback now; RB-1 in full at CP1). Graduate memo (individual): a required review-notebook entry under RB-16, always read and not sampled (RB-16 graduate-task note); scored formatively on RB-1.1 boundary and context (B-CLO1), applied to the boundaries the memo classifies, with the answer key’s level descriptors for the Maier argument; the set of graduate tasks informs RB-16.1. AI statement: RB-12.1–12.3, including RB-12.3 for every AI-suggested STK, CON or AROU entry (tagged AI-suggested-reviewed: a provenance option in the recorder; in the stakeholder editor, which has no AI tag yet, start the stakeholder’s rationale with “AI-suggested-reviewed:”).`,aiUse:`AI tools may be used to brainstorm stakeholders and to critique a draft memo. Every AI-suggested stakeholder, concern or AROU entry is tagged AI-suggested-reviewed and individually checked (RB-12.3): in the recorder choose that provenance; in the stakeholder editor, which has no AI tag yet, start the rationale with “AI-suggested-reviewed:”. AI-generated claims about real enterprises must be verified against a source you cite, or removed.`,objectives:[`B2.1`,`B2.2`,`B2.3`,`B2.4`]},quiz:[{id:`q2-1`,bloom:`Analyse`,objective:`B2.1`,prompt:`A team argues that a national parcel carrier’s own network — its aircraft, trucks, sorting hubs and tracking software, all acquired, owned and managed by the carrier — is a system of systems because it is spread over 40 hubs and its throughput is emergent (FICTIONAL). Which is the strongest rebuttal under Maier’s definition?`,options:[{id:`a`,text:`An SoS requires operational and managerial independence of its components; the carrier’s components are acquired and managed by one owner and have no independent operational existence, and geographic distribution is not a taxonomic classifier`,correct:!0,explanation:`Correct. Maier’s definition rests on the two independences; SEBoK v2.14, “The Enterprise as a System”, p. 833 quotes Maier that geographic distribution and complexity are not the appropriate classifiers.`},{id:`b`,text:`The network is too small to be an SoS: 40 hubs is below any reasonable SoS threshold`,correct:!1,explanation:`Size is not a criterion in Maier’s definition; a large single-owner system is still not an SoS, and a small set of independent systems can be one.`},{id:`c`,text:`Emergent behaviour occurs only in natural systems, so the team’s premise is false`,correct:!1,explanation:`Emergence occurs in engineered systems too (Week 1). The flaw is that emergence does not decide the classification, not that it is absent.`},{id:`d`,text:`There is no rebuttal: every element of a system is itself a system, so the network is an SoS by definition`,correct:!1,explanation:`SEBoK v2.14, “The Enterprise as a System”, p. 832 notes that this reading would make the term superfluous; Maier’s definition adds the two independence properties precisely to avoid it.`}],cite:{reading:`R08`,pages:`832–833`}},{id:`q2-2`,bloom:`Analyse`,objective:`B2.1`,prompt:`During a declared regional emergency (FICTIONAL), the state emergency-management agency takes operational control for two weeks: AeroLink’s aircraft, the partner vertiports and the hospitals’ helipads are tasked only by the agency’s coordination centre, and normal commercial service is suspended. Each organisation keeps its ability to operate on its own and resumes normal service when the emergency ends. Which SoS type best describes the arrangement during the emergency?`,options:[{id:`a`,text:`Directed`,correct:!0,explanation:`Correct. The constituents keep the ability to operate independently, but their normal operational mode is subordinated to a centrally managed purpose. SEBoK v2.14, “Systems of Systems (SoS)”, p. 867 also notes that forming an SoS is not necessarily permanent.`},{id:`b`,text:`Acknowledged`,correct:!1,explanation:`In an acknowledged SoS the constituents keep their own objectives and changes rest on cooperative agreements. Here their normal operation is suspended and tasked centrally.`},{id:`c`,text:`Collaborative`,correct:!1,explanation:`A collaborative SoS rests on more or less voluntary interaction towards agreed purposes, without central tasking. Here an agency tasks every constituent.`},{id:`d`,text:`Virtual`,correct:!1,explanation:`A virtual SoS has neither a central management authority nor a centrally agreed purpose; this arrangement has both.`}],cite:{reading:`R09`,pages:`866–869`}},{id:`q2-3`,bloom:`Apply`,objective:`B2.1`,prompt:`In a FICTIONAL city, an independent bus company, a bike-share firm and two ride-hail firms agree a common purpose (one-ticket door-to-door travel). The city transport authority then funds a Mobility Integration Office with a designated manager and its own budget; each firm keeps its own ownership, objectives and funding, and changes are made through cooperative agreements. How should this SoS be classified now?`,options:[{id:`a`,text:`It is now an acknowledged SoS; SoS types can change over time`,correct:!0,explanation:`Correct. Recognised objectives, a designated manager and resources, with constituents keeping independent ownership and agreements-based change, define an acknowledged SoS; SEBoK v2.14, “Systems of Systems (SoS)”, p. 869 notes types combine and change over time.`},{id:`b`,text:`It is now a directed SoS because someone is in charge`,correct:!1,explanation:`Directed requires the constituents’ normal operational mode to be subordinated to the central purpose. Here they keep their own objectives and funding.`},{id:`c`,text:`It is no longer an SoS because it now has a manager`,correct:!1,explanation:`Operational and managerial independence of the constituents still hold, so it remains an SoS; the manager changes the type, not the classification.`},{id:`d`,text:`It is still collaborative, because the type is fixed when the firms first agree their purpose`,correct:!1,explanation:`SEBoK states that in most actual cases an SoS reflects a combination of types that may change over time; a funded, designated manager is the mark of an acknowledged SoS.`}],cite:{reading:`R09`,pages:`868–869`}},{id:`q2-4`,bloom:`Understand`,objective:`B2.1`,prompt:`AeroLink’s chief financial officer says: “Our enterprise is simply the company on our organisation chart.” Which reply is consistent with SEBoK?`,options:[{id:`a`,text:`Agreed: “enterprise” and “organisation” are synonyms, so the organisation chart is the enterprise`,correct:!1,explanation:`SEBoK calls equating them a frequent misuse of the term (SEBoK v2.14, “Enterprise Systems Engineering”, p. 815).`},{id:`b`,text:`Not quite: the enterprise also includes people, knowledge, processes, policies, facilities and other assets, and partners such as the vertiport operators may take part in it; the organisation chart is one view of it`,correct:!0,explanation:`Correct. In SEBoK’s Enterprise vs Organization discussion an enterprise includes participating organisations plus people, knowledge and other assets (SEBoK v2.14, “Enterprise Systems Engineering”, p. 815), and Giachetti treats an organisation as a view of the enterprise (p.816).`},{id:`c`,text:`Agreed, because an enterprise must be tightly bounded and directed by a single executive function`,correct:!1,explanation:`The MOD definition quoted by SEBoK allows a second form with less defined boundaries and multiple owners.`},{id:`d`,text:`Not quite: the enterprise is the information system the company uses to run its business`,correct:!1,explanation:`These pages do not discuss the information-technology sense of “enterprise system”. The nearest statement asks for the enterprise to be viewed as a system “rather than merely as a collection of functions connected solely by information systems” (SEBoK v2.14, “Enterprise Systems Engineering”, p. 816); the enterprise includes people, processes and assets.`}],cite:{reading:`R07`,pages:`815–816`}},{id:`q2-5`,bloom:`Understand`,objective:`B2.1`,prompt:`A FICTIONAL regional hospital group wants a 30-minute blood-sample delivery capability. It owns the delivery drones, but the capability also needs air-traffic services, rooftop pads owned by other hospitals and a mobile-network operator’s data link. What does SEBoK’s discussion of enterprises and SoS imply for how the hospital group engineers this capability?`,options:[{id:`a`,text:`Apply traditional SE to the whole delivery capability exactly as it would to one drone`,correct:!1,explanation:`SEBoK says traditional SE applies to the individual systems but must be augmented for SoS and enterprise issues.`},{id:`b`,text:`The capability is an emergent property of a chain of systems the group does not fully control, so traditional SE of its own drones must be augmented with SoS and enterprise activities`,correct:!0,explanation:`Correct. This is the relationship between an enterprise and an SoS described in SEBoK v2.14, “The Enterprise as a System”, p. 834; the same reasoning applies to AeroLink’s trip.`},{id:`c`,text:`Because the group lacks control, the capability cannot be engineered and should be left to its partners`,correct:!1,explanation:`Lack of control changes the means (agreements, influence, monitoring), not whether engineering applies.`},{id:`d`,text:`Acquire the other hospitals’ pads, the data link and the air-traffic system so that the chain becomes a single system`,correct:!1,explanation:`Neither feasible (air-traffic services and the mobile network serve others) nor implied by the source; the point is to engineer under partial control.`}],cite:{reading:`R08`,pages:`834`}},{id:`q2-6`,bloom:`Apply`,objective:`B2.2`,prompt:`AeroLink’s sponsor hands the team a stakeholder list: passengers, investors and the FAA. Following MITRE’s guidance, what should the team do next to identify stakeholders?`,options:[{id:`a`,text:`Treat the sponsor’s list as authoritative and move on to rating influence`,correct:!1,explanation:`MITRE treats the sponsor’s list as a starting point only.`},{id:`b`,text:`Ask interviewees for further names and organisations, and actively seek supporters, skeptics and rivals of the initiative`,correct:!0,explanation:`Correct. This snowball approach, including skeptics and rivals, is MITRE’s recommended practice (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 235).`},{id:`c`,text:`Survey passengers, because customers are the stakeholders who matter most`,correct:!1,explanation:`Equating stakeholders with customers is this week’s target misconception; regulators, communities and partners may matter as much to whether AeroLink can operate.`},{id:`d`,text:`Limit the list to organisations that will sign contracts with AeroLink`,correct:!1,explanation:`MITRE asks for directly and indirectly affected stakeholders (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 234); communities and emergency responders sign no contract but are affected.`}],cite:{reading:`R63`,pages:`235`}},{id:`q2-7`,bloom:`Apply`,objective:`B2.2`,prompt:`AeroLink will introduce automated dispatch. The draft stakeholder list names the chief operating officer (decision maker), the dispatch project team (change agents) and passengers (customers). Which of MITRE’s key stakeholder groups is missing?`,options:[{id:`a`,text:`Employees and contractors directly affected by the change — pilots/remote operators (STK-008) and maintenance technicians (STK-009)`,correct:!0,explanation:`Correct. MITRE lists employees and contractors directly impacted by the change as a key group; dispatch automation changes their work directly.`},{id:`b`,text:`Investors, because they fund everything`,correct:!1,explanation:`Investors may matter, but they are not the MITRE group missing from this list; the directly affected workforce is.`},{id:`c`,text:`Nobody: decision makers, change agents and customers are a complete set`,correct:!1,explanation:`MITRE’s list also includes directly affected employees and contractors, and representatives of groups in headquarters and the field.`},{id:`d`,text:`The aircraft manufacturer, because it built the aircraft`,correct:!1,explanation:`The OEM may have an interest, but it is not directly affected by a dispatch-process change in the way operators and technicians are.`}],cite:{reading:`R63`,pages:`235`}},{id:`q2-8`,bloom:`Understand`,objective:`B2.2`,prompt:`The team collects 1–5 Likert ratings from interviews with five vertiport operators. How should these data be used in the stakeholder assessment?`,options:[{id:`a`,text:`As precise measurements that settle disagreements between groups`,correct:!1,explanation:`MITRE notes the inherent variance in Likert responses; they add a quantitative measure, not precision.`},{id:`b`,text:`To give a quantitative value to qualitative interview information and overlay it on the stakeholder map to see similarities and differences across groups`,correct:!0,explanation:`Correct. This is how MITRE uses Likert data (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 236).`},{id:`c`,text:`Averaged with all other groups into one support score for the whole programme`,correct:!1,explanation:`MITRE advises highlighting differences across stakeholder groups and avoiding generalisations (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 237).`},{id:`d`,text:`Instead of interviews, because surveys are faster`,correct:!1,explanation:`MITRE combines interviews, focus groups and surveys and stresses dialogue and follow-up questions.`}],cite:{reading:`R63`,pages:`236`}},{id:`q2-9`,bloom:`Analyse`,objective:`B2.3`,prompt:`A team’s conflict matrix gives (influence in brackets): V1 operating hours — Investors STK-003 (5) ↑, Vertiport operators STK-005 (4) ↑, Pilots STK-008 (3) ↓. V2 departures per pad-hour — STK-003 ↑, STK-005 ↑, STK-008 ↓. V5 residential sites — STK-003 ↑, City planning STK-013 (5) ↓. Using the course’s conflict weight (influence × influence) and grouping conflicts by stakeholder pair, which conclusion is correct?`,options:[{id:`a`,text:`Investors ↔ City planning is the heaviest pair, because its single conflict (25) is the heaviest conflict`,correct:!1,explanation:`The heaviest single conflict is not the heaviest pair: Investors ↔ Pilots conflict on two variables, 15 + 15 = 30 > 25.`},{id:`b`,text:`Investors ↔ Pilots is the heaviest pair (15 on hours + 15 on departures = 30), a recurring conflict over operating tempo, while siting (25) is the sharpest single conflict`,correct:!0,explanation:`Correct. The conflicts are 003–008: 15 + 15 = 30; 003–013: 25; 005–008: 12 + 12 = 24. Grouping by pair exposes the recurring conflict that a ranking of single rows hides. The weight rule is the course’s; The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 237 supplies the advice to highlight differences across groups.`},{id:`c`,text:`Vertiport operators ↔ Pilots is the heaviest pair, because it spans the most variables`,correct:!1,explanation:`It spans the same two variables as Investors ↔ Pilots but weighs 4 × 3 = 12 on each, total 24 < 30.`},{id:`d`,text:`Investors ↔ Pilots and Vertiport operators ↔ Pilots tie, because both conflict on the same two variables`,correct:!1,explanation:`The weights differ: 5 × 3 = 15 against 4 × 3 = 12 per variable, so 30 against 24.`}],cite:{reading:`R63`,pages:`237`}},{id:`q2-10`,bloom:`Apply`,objective:`B2.3`,prompt:`AeroLink’s executives describe the community groups near two proposed vertiports as “resistant”. The support map shows the City planning authority (high influence) at awareness and the communities at understanding. Which response best reflects MITRE’s guidance and the course’s application of it?`,options:[{id:`a`,text:`Prioritise moving the City planning authority toward commitment, and test whether the communities’ “resistance” is really a lack of understanding of the rationale and how it will work`,correct:!0,explanation:`Correct. High influencers must be moved toward commitment (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 237). MITRE reports that sponsors may realise that perceived resistance was really a lack of understanding (p.238); MITRE says this about a sponsor’s own organisation, and applying it to external communities is the course’s extension.`},{id:`b`,text:`Remove the community groups from the map, since they oppose the plan`,correct:!1,explanation:`MITRE asks assessments to seek out skeptics and rivals, not remove them.`},{id:`c`,text:`Treat both groups the same, because all stakeholders are equal`,correct:!1,explanation:`The map exists to distinguish groups by influence and support; equal treatment ignores the gap analysis.`},{id:`d`,text:`Wait for the communities to reach commitment before engaging the planning authority`,correct:!1,explanation:`This reverses the priority: the high-influence group with the larger gap comes first (course convention: priority = influence × gap, here 5 × 3 = 15 against 4 × 2 = 8).`}],cite:{reading:`R63`,pages:`237–238`}},{id:`q2-11`,bloom:`Understand`,objective:`B2.4`,prompt:`The draft agenda for AeroLink’s development-to-production gate has one item: “Confirm that the gate date has arrived.” Which revision best matches what SEBoK says a gate review generally considers?`,options:[{id:`a`,text:`Keep the agenda: reaching the date is what the gate checks`,correct:!1,explanation:`A gate evaluates progress against criteria, not dates alone; schedule-based triggering is one review type with known risks.`},{id:`b`,text:`Add a look back at progress against the development stage’s exit criteria and a look forward at preparedness to begin production`,correct:!0,explanation:`Correct. SEBoK describes the two elements of the review at a gate (SEBoK v2.14, “Life Cycle Stages”, p. 384).`},{id:`c`,text:`Replace it with a check that every part of the system has reached the same maturity`,correct:!1,explanation:`SEBoK notes that parts will not all reach the same maturity at the same time; interim maturity reviews handle this.`},{id:`d`,text:`Replace it with a review of the cost to date only`,correct:!1,explanation:`Business case, budget and technical maturity including risk are balanced together.`}],cite:{reading:`R06b`,pages:`384`}},{id:`q2-12`,bloom:`Apply`,objective:`B2.4`,prompt:`AeroLink’s aircraft follow a staged life cycle, while its dispatch software follows a DevSecOps loop in which development and support are not distinguished. At the aircraft’s development-to-production gate, the software lead asks that the gate wait until the dispatch software “is finished”. Which response is best supported by SEBoK?`,options:[{id:`a`,text:`Wait: a gate can be passed only when every part of the system of interest has reached the same maturity`,correct:!1,explanation:`SEBoK notes that not all parts of a system of interest reach the same maturity, and therefore the same gate, at the same time; interim maturity reviews exist for this (SEBoK v2.14, “Life Cycle Stages”, p. 384).`},{id:`b`,text:`Evaluate the aircraft against the criteria for its own stage or independent increment, review the software increment it depends on against tailored criteria, and use interim maturity reviews rather than waiting for the software to be “finished”`,correct:!0,explanation:`Correct. Gates evaluate progress against criteria for a stage or for an increment that can be independent of others, with tailored entry and exit criteria (SEBoK v2.14, “Life Cycle Stages”, p. 384); in a DevSecOps loop the work is never “done” (SEBoK v2.14, “Life Cycle Models”, p. 382).`},{id:`c`,text:`Terminate the software effort, because a life cycle without an end cannot be gated`,correct:!1,explanation:`SEBoK presents the DevSecOps loop as a legitimate life-cycle model; different elements may follow different models.`},{id:`d`,text:`Treat the software as already in the retirement stage, since its development never ends`,correct:!1,explanation:`Retirement is storing, archiving or disposing of a system; continuous development and support is the opposite.`}],cite:{reading:`R06b`,pages:`384`}},{id:`q2-13`,bloom:`Apply`,objective:`B2.4`,prompt:`The vertiport-integration review was planned for the date on which the vertiport operator delivers the agreed integration artefacts. To fit an investor meeting, the programme manager fixes it for 3 March instead, although the artefacts will not arrive until May (FICTIONAL). In Boehm and Lane’s terms, what has changed, and which risk now needs guarding against?`,options:[{id:`a`,text:`The trigger has moved from event-based to schedule-based; the risk is insufficient information to meet the review objectives`,correct:!0,explanation:`Correct. A review set by an explicit date is schedule-based, and its characteristic risk is insufficient information (SEBoK v2.14, “Technical Reviews and Audits”, p. 387).`},{id:`b`,text:`The trigger has moved from event-based to evidence-based; the risk is late feedback on latent defects`,correct:!1,explanation:`An evidence-based review is triggered by reaching a specific technical risk level shown by evidence, not by a date.`},{id:`c`,text:`Nothing has changed: the review is still event-based because artefacts will eventually be delivered`,correct:!1,explanation:`The trigger is now a date, independent of the artefacts.`},{id:`d`,text:`The trigger has moved from schedule-based to event-based; the risk is insufficient analysis and unresolved issues`,correct:!1,explanation:`This reverses the change: the original trigger (delivery of agreed artefacts) was the event; the new one is a date.`}],cite:{reading:`R06c`,pages:`387`}},{id:`q2-14`,bloom:`Apply`,objective:`B2.4`,prompt:`Four review panels are proposed for AeroLink’s concept-exit review. Which best follows SEBoK’s guidance on selecting reviewers?`,options:[{id:`a`,text:`The five members of the AeroLink concept team who wrote the concept`,correct:!1,explanation:`People too close to the project may be biased.`},{id:`b`,text:`Three external academics who have never seen the project or the air-taxi domain`,correct:!1,explanation:`People too far from the project may miss the critical issues.`},{id:`c`,text:`Two concept-team leads, an operations-safety engineer from another AeroLink programme and an external battery-safety specialist`,correct:!0,explanation:`Correct. SEBoK recommends this combination (SEBoK v2.14, “Technical Reviews and Audits”, p. 388) and asks that independence and specialty expertise be considered when selecting participants (p.387).`},{id:`d`,text:`The investors’ board, because the gate is a funding decision`,correct:!1,explanation:`Gates balance business case, budget and technical maturity; a technical review needs technical assessors.`}],cite:{reading:`R06c`,pages:`387–388`}},{id:`q2-15`,bloom:`Analyse`,objective:`B2.3`,prompt:`Emergency responders (STK-006) object to AeroLink’s plan to raise departures per pad-hour. Interviews show they believe a busier pad leaves no clear access lane during turnarounds. AeroLink’s pad layout keeps a dedicated access lane open at all times, but the layout has never been shared with them (FICTIONAL). How should the team record and treat this conflict in its L2 analysis?`,options:[{id:`a`,text:`As a possible information gap: share the layout, then re-assess their position, keeping the conflict on the map until the re-assessment shows whether a genuine incompatibility remains`,correct:!0,explanation:`Correct. The evidence points to missing information, not to incompatible concerns, but only the responders can confirm that the lane meets their need. This is the course’s application of MITRE’s observation that perceived resistance may be a lack of understanding (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 238), together with grounding themes in evidence (p.237).`},{id:`b`,text:`As a genuine incompatibility, to be settled by a trade study of departures against emergency access`,correct:!1,explanation:`Premature: the interview evidence suggests a misunderstanding. A trade study built on it would trade against a constraint that may already be met.`},{id:`c`,text:`Delete the conflict, because the layout already solves the problem`,correct:!1,explanation:`Whether the lane meets the responders’ concern is for them to confirm. Deleting the conflict hides an unverified assumption.`},{id:`d`,text:`Lower the responders’ influence rating so that the conflict weighs less`,correct:!1,explanation:`Influence describes their ability to affect AeroLink, not whether they are right; adjusting ratings to fit a conclusion defeats the analysis.`}],cite:{reading:`R63`,pages:`237–238`}},{id:`q2-16`,bloom:`Analyse`,objective:`B2.3`,prompt:`In the instructor key, Investors (influence 5) and Communities (influence 4) conflict on four variables (weight 20 each, total 80); Communities and Vertiport operators (influence 4) conflict on three (16 each, total 48); and the strongest pair not involving Communities is Investors–Pilots (15 on each of two variables, total 30). A reviewer argues that Communities’ influence should be 2, not 4. What does the sensitivity check show?`,options:[{id:`a`,text:`Investors–Communities falls to 40 but still ranks first, ahead of Investors–Pilots (30); the structural-conflict conclusion survives the change`,correct:!0,explanation:`Correct. Each Investors–Communities conflict becomes 5 × 2 = 10, so 4 × 10 = 40; Communities–Vertiport operators becomes 3 × 8 = 24; Investors–Pilots is unchanged at 30. Ordinal ratings carry variance (The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management”, p. 236), so the course reports conclusions with a sensitivity check like this one.`},{id:`b`,text:`Investors–Communities falls to 40 and is overtaken by Communities–Vertiport operators, which stays at 48`,correct:!1,explanation:`That pair also involves Communities, so it falls too: 3 × (4 × 2) = 24.`},{id:`c`,text:`Investors–Communities stays at 80, because the number of shared variables, not influence, decides the ranking`,correct:!1,explanation:`The weight of every conflict is the product of the two influence ratings, so the total halves.`},{id:`d`,text:`Investors–Communities falls below Investors–Pilots, so the conclusion is fragile and must be withdrawn`,correct:!1,explanation:`40 is still above 30; the conclusion survives this change.`}],cite:{reading:`R63`,pages:`236`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min; the SoS classifier and conflict matrix are done in class)`,hours:2.5},{activity:`Online direct instruction and the life-cycle activity with its written prompts (four interactive activities in all; the recorder is counted with L2)`,hours:.4},{activity:`Readings SEBoK v2.14, “Enterprise Systems Engineering”, SEBoK v2.14, “Systems of Systems (SoS)”, SEBoK v2.14, “Life Cycle Models”, “Life Cycle Stages” and “Technical Reviews and Audits”, The MITRE Systems Engineering Guide, “Stakeholder Assessment and Management” (≈ 25 pp at ≈ 15 pp/h)`,hours:1.6},{activity:`Readiness quiz Q2 / knowledge check (16 items)`,hours:.2},{activity:`L2 completion, causal argument and AROU v0 (team share, out of class)`,hours:2.5},{activity:`Graduate Maier memo: SEBoK v2.14, “The Enterprise as a System”, p. 832–834 (≈ 0.2 h; p.829–831 repeat SEBoK v2.14, “Enterprise Systems Engineering”), finding and citing public evidence for two real enterprises (≈ 0.4 h), writing one page and the evidence table (≈ 0.6 h)`,hours:1.2},{activity:`Review notebook time log (the memo is notebook entry 2 and contains the AI statement)`,hours:.1}],references:[{reading:`R08`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes (blocker W2-S01 fixed by the lead exactly as the reviewer specified, 2026-10-11)`,date:`2026-10-11`,report:``,openIssues:[]}},a=e({default:()=>o}),o={week:3,drivingQuestion:`Before anyone designs an aircraft, a charger or an app: why does AeroLink exist, what do its stakeholders actually need — stated so that no solution is assumed — what must the enterprise be able to do to meet those needs, and what happens, step by step, on the afternoon the weather closes a vertiport?`,blocks:[{id:`w3-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcome B-CLO2 and closes the first capstone checkpoint (CP1). Week 2 identified who has a stake in AeroLink and what each of them is concerned about. Week 3 turns those concerns into the problem definition that every later artefact traces to: why AeroLink exists and how its success will be measured (mission, goals and objectives), what its stakeholders need without saying how it will be done (need statements), what the enterprise must be able to do to meet those needs (capabilities), and how it will actually be used on a good day and on a bad one (ConOps scenarios).`],bullets:[`B3.1 (Apply) State the mission, goals and objectives in measurable form.`,`B3.2 (Apply) Transform stakeholder concerns into solution-free need statements.`,`B3.3 (Analyse) Derive and decompose capabilities from needs.`,`B3.4 (Create) Construct three ConOps scenarios (nominal, weather disruption, charging/maintenance).`,`Graduate expectation: a capability-gap analysis over near-, mid- and far-term horizons (SEBoK v2.14, “Enterprise Capability Management”, p. 862), with the arithmetic shown and the conclusion tested against its assumptions.`],citations:[],provenance:`instructor-authored`},{id:`w3-intuition`,kind:`intuition`,title:`Intuition: a diner’s wish is not a recipe`,paragraphs:[`A diner tells the waiter: “I’d like the salmon with lemon-butter sauce.” That is a solution. Ask why, and the real need appears: something light, ready in twenty minutes, because there is a train to catch at eight. If the kitchen has run out of salmon, the stated wish fails — but the need can still be met by the trout, or by a different dish altogether. A good kitchen hears the need and keeps its options open; the recipe, which is the kitchen’s business, comes later.`,`Engineering has the same structure, with higher stakes. “AeroLink needs a mobile app that books a ride in three taps” and “communities need sound barriers around each vertiport” are recipes dressed up as wishes. Each one closes off alternatives before anyone has compared them, and each hides the need that should be measured later: a short, predictable wait; noise kept within an agreed limit at the hours people sleep. This week you learn to hear the need behind the wish, to name the abilities the enterprise must have to meet it, and to tell the story of the service in operation — including the evening the oven breaks, which for AeroLink is the afternoon a gust front crosses a vertiport.`],citations:[],provenance:`instructor-authored`},{id:`w3-mission`,kind:`concept`,title:`Business or mission analysis: problem, mission, goals, objectives and measures`,paragraphs:[`SEBoK places Business or Mission Analysis first in Concept Definition. Its purpose is to understand a mission or market problem, threat or opportunity and to establish the goals, objectives and measures of success of a potential solution class. The solution need not be a new system: it could be a change to an existing system, a service, or an operational change. Success depends on the team understanding the purpose of the system of interest (why), what would make a solution acceptable or desirable (what), the measures (how well), and the operating environment (in what conditions). Business or Mission Analysis is often performed iteratively with Stakeholder Needs Definition.`,`The problem, threat or opportunity is defined in four steps: identify the strategic and business-operations stakeholders who are affected or would benefit; work with them to understand how; state the problem clearly; and obtain their concurrence with the statement. From that statement come the MGOs. The mission states why the project exists, why the system is needed and what value it brings. Goals are elaborated from the mission and divide it into manageable pieces that the team and the business stakeholders understand in the same way. Objectives are elaborated from the goals and say in more detail what must be done for the goals and the mission to be achieved. Measures are quantitative metrics, expressed as measures of effectiveness (MOE), used to validate the system against the objectives and to manage development across the life cycle. These are four levels, not three: in SEBoK’s own example the consumer objective is qualitative (“receive finished home brew coffee within minutes upon request”) and the number sits in a separate consumer-focused measure (“finished home brew provided within 2 minutes of activation”); the business objective “increase market share” is likewise paired with the measure “improve current market share by 20 %” (SEBoK v2.14, “Business or Mission Analysis”, p. 546).`,`SEBoK lists the questions to ask: how do the stakeholders define success, what measures would they use, what is the intended use and environment, what capabilities and performance do they need, what quality and compliance do they expect, and what outcome do they expect on delivery? For a system that does not yet exist, a common approach is to describe the “as is” state in terms of the problem and the “to be” state in terms of its resolution. Perspectives matter: the user does not necessarily care about the developing organisation’s profit, time to market or market share, so there may be separate business and user sets of MGOs and measures, and their conflicts (price versus profitability versus market share) are prioritised according to the enterprise strategy.`,`The outputs are the major stakeholders, the problem statement, the MGOs and measures, preliminary life-cycle concepts and preferred solution classes, traceability among them, and confirmation of organisational support. Preliminary life-cycle concepts include the operational concept: high-level modes or states, operational scenarios, use cases, misuse cases and loss scenarios. Candidate solution classes — a new system, a modified one, several existing systems combined, or an operational change — are assessed for feasibility in cost, schedule, technology and legal, ethical, environmental and sustainability terms.`,`Applied to AeroLink (instructor reference, numbers FICTIONAL). Course convention, not SEBoK’s: so that RB-2.1 (“measurable objectives traced to stakeholder concerns”) can be checked, the course records each objective together with its measure (SEBoK’s MOE), a numeric target, a unit and a horizon, and traces it to a concern either directly or through its goal. The horizon and the concern trace are course rules; SEBoK v2.14, “Business or Mission Analysis” states neither. The table shows the mission, its four goals and the four objectives with their measures. MGO-005 is a user-perspective objective and MGO-007 a business-perspective one, the two sets SEBoK says must both be addressed. The reference statements fold the target into the objective’s wording; written in SEBoK’s form, MGO-006 would read “take-offs and landings stay within the noise limit agreed with the city”, with the measure “events above 65 dBA at a pad edge per quarter, target 0”. The reference itself shows why the parent link matters: its first version hung MGO-008 directly from the mission, skipping a goal, and the course’s own review caught it. Before showing the fix, cover the MGO-009 row and ask the class which goal is missing; the answer in the reference is MGO-009 “every flight within approved limits”, derived from the mission and from the FAA’s concern CON-004, and MGO-008 now answers CON-004 through it.`],table:{caption:`AeroLink MGOs from the reference baseline (targets FICTIONAL). Measure, target and horizon are recorded with each objective by course convention; “traces to” lists the parent MGO and the concern (directly, or inherited through the goal)`,header:[`ID`,`Level`,`Statement (abridged)`,`Measure (MOE), target, horizon`,`Traces to`],rows:[[`MGO-001`,`Mission`,`Safe, quiet, on-demand air trips between six vertiports, at predictable waits and a cost that lets the network grow`,`— (measured through its objectives)`,`CON-001, CON-004, CON-005, CON-012`],[`MGO-002`,`Goal`,`Passengers board soon after confirming, and the quoted wait is the wait they get`,`—`,`MGO-001, CON-001`],[`MGO-003`,`Goal`,`Vertiport operations stay within what neighbouring communities have agreed to accept`,`—`,`MGO-001, CON-012`],[`MGO-004`,`Goal`,`Capacity is added when and where demand needs it, without stranding capital`,`—`,`MGO-001, CON-005`],[`MGO-009`,`Goal`,`Every flight is planned, dispatched and flown within the approved weather, energy-reserve and airworthiness limits`,`—`,`MGO-001, CON-004`],[`MGO-005`,`Objective (user)`,`≥ 90 % of passengers each month board within 15 min of confirming, from month 6`,`90th-percentile wait; ≤ 15 min; month 6 onward`,`MGO-002 (→ CON-001)`],[`MGO-006`,`Objective (community)`,`No take-off or landing above the pad-edge limit in any quarter`,`Events above 65 dBA LAmax at a pad edge; 0 per quarter; each quarter from the start of service`,`MGO-003 (→ CON-012)`],[`MGO-007`,`Objective (business)`,`By month 24, serve 240 trips/day at ≤ 80 % utilisation`,`Capacity; ≥ 300 trips/day; month 24`,`MGO-004 (→ CON-005)`],[`MGO-008`,`Objective (safety)`,`No flight dispatched outside weather, energy-reserve or airworthiness limits`,`Dispatches outside limits; 0 per quarter; each quarter from the start of service`,`MGO-009 (→ CON-004)`]]},citations:[{reading:`R10`,pages:`543–547`}],provenance:`mixed`},{id:`w3-needs`,kind:`concept`,title:`Stakeholder needs: an integrated set, written as needs, free of solutions`,paragraphs:[`Stakeholder Needs Definition explores what capabilities stakeholders need for the system to accomplish the mission. Stakeholder needs express the perspective of users, acquirers, customers and other stakeholders; system requirements, written later, express the developer’s perspective. SEBoK stresses that the process is much more than collecting statements: stakeholder needs are combined with the results of analysing risks, drivers and constraints and with maturing life-cycle concepts, to give an integrated set of needs that is correct, consistent, complete and feasible. That integrated set defines the scope the organisation agrees to resource, it is transformed into design-input requirements, and the requirements, the design and the realised system are validated against it. SEBoK deliberately avoids the label “stakeholder requirements” for this set, because guides that treat expectations, needs and requirements as the same thing cause confusion.`,`Elicitation uses several techniques — structured brainstorming, interviews and questionnaires, workshops and focus groups, visual material, documentation review and feedback from verification and validation. The topics are broad: feedback on the mission analysis outputs, the life-cycle stages each stakeholder represents, expected and off-nominal use cases, misuse cases and loss scenarios, desired capabilities, interactions with external systems, the “ilities”, risks and hazards, and the rationale and priority of every need. Rationale earns its place: SEBoK notes that asking why often reveals the real need, especially when a stakeholder has expressed the need as an implementation. Elicited needs are recorded with trace to the stakeholder register; in an MBSE effort they are traced to stakeholders in the model.`,`The integrated set states expected functionality (what the stakeholders need the system to do), performance and quality (how well), the conditions of action — triggering events, system states and operating environments — and compliance with standards and regulations. Needs are written in structured natural language from the stakeholders’ perspective and, to keep them distinct from requirements, they do not use “shall” or any other word that marks a requirement; SEBoK recommends a form such as “The stakeholders need the system to …”.`,`MITRE’s operational needs assessment adds the attributes a need statement should have: an enterprise context; a complete, end-to-end need (detect, identify and defeat rather than detect alone); the conditions or scenario under which the need exists; attributes and metrics where they can be stated, tied to mission goals; expected growth; and independence of solution approach, because a need stated as a particular solution can eliminate more effective approaches. Needs should describe a successful operation or mission, not a proposed solution.`,`Two cautions keep this honest. First, the readings do not agree on quantification, and the module will not pretend they do. MITRE’s ConOps article lets users state a need for a “highly reliable” system without producing a testable requirement, leaving the quantification to the buyer or developer (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 302). MITRE’s operational-needs-assessment article, written for a different purpose, says operational needs must be described and quantified so that decision makers can assess them and compare cost-effective alternatives (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295). The course reading: in a ConOps a stakeholder may state a need qualitatively; in a needs assessment the team quantifies it where it can, with an evidence basis. Measurability is required of objectives through their measures (B3.1) and, next week, of requirements. Second, SEBoK’s own example need table includes statements at feature level (two temperature settings, four colours, SEBoK v2.14, “Stakeholder Needs Definition”, p. 555). Whether a statement is “solution-laden” depends on the level of the system of interest and on genuine constraints; this course holds AeroLink’s enterprise-level needs to MITRE’s stricter standard (RB-2.2), and a team that keeps a design term must justify it as a constraint.`],quote:{text:`Beware solutions masquerading as needs.`,cite:{reading:`R53`,pages:`296`}},citations:[{reading:`R11`,pages:`549–556`},{reading:`R53`,pages:`294–297`},{reading:`R52`,pages:`302`}],provenance:`mixed`},{id:`w3-capabilities`,kind:`concept`,title:`Capabilities: what the enterprise must be able to do, and where it falls short`,paragraphs:[`SEBoK distinguishes three kinds of capability in an enterprise: organisational capability, system capability and operational capability; enterprise capability management deals with the operational kind. It also separates two kinds of need. An operational need is something desirable in direct support of the enterprise’s end-user activities — SEBoK’s example is “provide transportation services to commuters in the metropolitan area of London”. An enterprise need relates to the enabling assets (personnel, facilities, networks, funding, partnerships, equipment) that let the mission be accomplished, and aims at efficient use of those assets.`,`The capabilities of an enterprise should exist for the sole purpose of meeting mission and enterprise needs, so both kinds of capability are identified and assessed against the needs. SEBoK’s examples are worth copying in form: an operational capability “transport 150,000 passengers per hour among 27 nodes in the network”, and a supporting enterprise capability “process 200,000 tickets per hour during peak loading”. Each states an ability and, where it can, how much of it. The desired levels of capability, from the needs assessment, are compared with the baseline — what exists plus what is already planned — to find capability gaps, and also points of excess capability. Gaps should be filled and excesses eliminated. Projected gaps and excesses are sometimes mapped into near-, mid- and far-term time buckets; for long-lasting capabilities these might be five, ten and twenty years, for fast-changing ones one, two and three years.`,`MITRE defines an operational needs assessment as identifying and characterising gaps in existing capabilities that are significant impediments to achieving the mission-area objectives. In the US DoD process it describes, a capabilities-based assessment identifies the mission, the capabilities required with their operational characteristics and attributes, the capability gaps, potential solutions and operational risks; if changes to doctrine, organisation, training, logistics, personnel or facilities can meet the need cost-effectively, a new materiel solution may not be necessary (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295).`,`In this course (an instructor-authored convention for the teaching model, not a SysML construct): a capability is phrased as an ability of the enterprise (“return arriving aircraft to a dispatch-ready energy state within the turnaround time”), every capability derives from at least one need, and decomposition is recorded by a constituent capability that refines its parent. A need with no capability is a coverage gap in the derivation; a capability with no need is unjustified scope. Both are different from a capability gap in SEBoK’s sense: a shortfall of the baseline — what exists plus what is already planned — against the desired level, including a capability that is absent altogether (SEBoK v2.14, “Enterprise Capability Management”, p. 862).`],citations:[{reading:`R12`,pages:`860–862`},{reading:`R53`,pages:`293–295`},{reading:`R10`,pages:`543`}],provenance:`mixed`},{id:`w3-conops`,kind:`concept`,title:`Concept of operations, use cases and mission threads`,paragraphs:[`MITRE defines a CONOPS as a user-oriented document that describes a proposed system’s characteristics from the user’s perspective, together with the user organisation, mission and objectives, and that communicates its quantitative and qualitative characteristics to stakeholders. Its purpose is to describe the user’s operational needs, desires, visions and expectations without being overly technical or formal, and to build a common understanding of ideas, challenges and possible solution strategies without addressing the technical solution or implementation; it is often a first step towards system requirements. It should include a conceptual view of the system that shows the top-level functional threads, define critical top-level performance objectives with their rationale, cover the full range of factors needed to support the mission (doctrine, organisation, training, leadership, materiel, personnel, facilities and resources), and be updated after developmental and operational testing to show how the system will actually be used.`,`MITRE lists the critical components that any CONOPS should keep when tailoring IEEE Std 1362-1998: the existing system the user wants to replace, the justification for a new or modified system (including its restrictions), a description of the proposed system, and scenarios highlighting its use in the user’s environment, including internal and external factors. Among the further objectives are end-to-end traceability between operational needs and source requirements, a high-level basis for test planning, a basis for computing system capacity, and the validation and discovery of implicit requirements. The best practices are plain: the user’s perspective and language, simplicity, graphics, a detailed description of the operational and physical environment, and the safety, security and privacy aspects that influence operation.`,`Scenarios are where a ConOps becomes analysable. In MITRE’s use-case article a use case is a goal-oriented set of interactions between external actors and the system. Actors are parties outside the system: classes of users, roles users play, or other systems. The primary actor has a goal that needs the system’s help; a secondary actor is one from which the system needs help. A use case records a set of paths from a trigger event to the goal (success scenarios) and paths that fall short of the goal (failure scenarios), as a sequence of simple steps in the user’s language. A mission thread is one path through a use case; threads serve as drivers for the architecture and as the basis for test cases. Use cases specify intent, not user-interface design or implementation detail.`,`MITRE also gives the review questions (is the use case complete; will the actor’s goal be met; are actors or goals missing?), a stopping rule (you have enough use cases when users, sponsor and other stakeholders cannot think of any more), the common pitfalls (vague goals, ambiguous scope, interface details in the text, too few use cases, wishful thinking beyond the operational user’s needs), and a practical technique for completeness: keep a list of the ways the system may be parameterised — the importance of actors, the types of input, future modes of operation, situations in which good actors do bad things, exceptional circumstances — and iterate through the use cases to see whether they cover them all. Applied to the target misconception: a brochure describes a product; a ConOps describes operations, from the user’s side, through scenarios that include the off-nominal ones (instructor synthesis of The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301 and The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 453–456).`],citations:[{reading:`R52`,pages:`298–302`},{reading:`R59`,pages:`452–457`}],provenance:`mixed`},{id:`w3-worked-needs`,kind:`worked-example`,title:`Worked example (a): from stakeholder concerns to solution-free needs — before and after`,paragraphs:[`Method (instructor-authored, built on SEBoK v2.14, “Stakeholder Needs Definition”, p. 553–555 and The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 296): (1) start from the concern, not from a proposed feature — for AeroLink, the Week 2 CON items; (2) ask why until the answer describes an outcome for the stakeholder rather than a mechanism; (3) strip any design term and any requirement wording; (4) attribute the need to a stakeholder in the form “<stakeholder> need(s) …”; (5) state the condition — when, where, under what operating conditions — so that the need can later be checked in the right situation; (6) record the rationale and the derives-from trace to the STK and CON it came from.`,`The table applies the method to five draft statements of the kind teams write in their first hour. The “before” column is deliberately bad; the “after” column is the reference need. Look at what each rewrite gains. NEED-001 replaces an app with the outcome the app was supposed to serve, so the Week 7 trade study can still compare an app, a kiosk, a public-transport ticketing link (O-001) or better dispatch. NEED-003 replaces one mitigation (barriers) with the agreed limit and the hours, which keeps quieter approach paths, curfews and siting in play. NEED-004 drops battery swapping, which is a solution class to be traded, and drops the 10-minute figure, which is a candidate requirement value with no evidence yet.`,`Two subtler points. First, NEED-002 is attributed to the FAA, an approving authority; SEBoK warns that the customer cannot be assumed to be the only approving authority, and highly regulated systems have external ones (SEBoK v2.14, “Stakeholder Needs Definition”, p. 553). Second, NEED-001 and NEED-003 pull in opposite directions — more departures shorten waits, and more departures make more noise. The integrated set must be consistent, but consistency does not mean deleting one of them: both needs stay, the conflict is recorded (Week 2 found it), and it is resolved by a trade and by stakeholder agreement, not by an editor. A set that contains no tension is usually a set that left a stakeholder out.`],table:{caption:`Before/after critique (before statements are instructor-authored teaching examples; after statements are reference NEEDs)`,header:[`Before (solution-laden)`,`What is wrong`,`After (solution-free need)`,`Derives from`],rows:[[`AeroLink shall provide a mobile app that books a ride in three taps.`,`Requirement wording (“shall”); a design (app, taps); no stakeholder; no condition`,`NEED-001: Passengers need to board within a short and predictable time after confirming a ride, throughout operating hours.`,`STK-001, CON-001`],[`Communities need sound barriers around each vertiport.`,`One mitigation named as the need; no limit, no hours`,`NEED-003: Communities near vertiports need take-off and landing noise kept within the limit agreed with the city, at every pad, at all operating hours.`,`STK-004, CON-012`],[`The FAA needs a weather radar on every aircraft during flight.`,`Sensor named; the regulator’s real need is assurance about limits`,`NEED-002: The FAA needs assurance that every flight is conducted within the approved airworthiness, energy and weather limits, including when weather changes during the day.`,`STK-002, CON-004, CON-002`],[`Vertiport operators need battery-swapping robots so turnaround takes under 10 minutes.`,`Solution class named; an unsupported number; no condition`,`NEED-004: Vertiport operators need arriving aircraft to be ready to depart again quickly enough that pad turnaround does not become the throughput limit (condition to add: at peak hours).`,`STK-005, CON-006`],[`There is a need for a smart grid controller that must cap charging.`,`No stakeholder; “must”; a device named`,`NEED-010: The electric utility needs the power drawn by each vertiport to stay within the agreed connection capacity at all times.`,`STK-010, CON-011`]]},citations:[{reading:`R11`,pages:`553–555`},{reading:`R53`,pages:`296`}],provenance:`mixed`},{id:`w3-worked-caps`,kind:`worked-example`,title:`Worked example (b): deriving and decomposing capabilities, with a gap analysis`,paragraphs:[`Derivation reads each need and asks: what must the enterprise be able to do for this need to be met, in every condition the need states? The answer is an ability, not a box. NEED-004 (pads not limited by turnaround) and NEED-010 (charging load within the grid connection) yield CAP-003 Fleet charging management — return arriving aircraft to a dispatch-ready energy state within the turnaround time at hub vertiports — and its constituent CAP-010 Charging power control — schedule and limit charging power so that each vertiport stays within its connection. The mapping is many-to-many: NEED-002 (assurance of flight within limits) is served by CAP-004 flight operations, CAP-005 weather-aware operations and CAP-006 fleet health management, while CAP-001 on-demand transport serves both NEED-001 and NEED-008 (step-free travel). A coverage check over the reference shows eleven needs (NEED-011 was discovered by writing SCN-005, worked example (c)), ten capabilities, every capability derived from at least one need and every need met by at least one capability: CAP-005 weather-aware operations also serves NEED-011, because recovering held and diverted flights includes getting their passengers onward.`,`Decomposition is where the analysis earns its keep. The reference decomposes three parents, but each has only one recorded constituent (CAP-001 → CAP-002, CAP-003 → CAP-010, CAP-004 → CAP-005). A single constituent rarely covers its parent, and asking “what else must be true for CAP-003 to work?” finds the missing ones: allocating turnaround chargers to arriving aircraft and managing the queue (A1 of SCN-003), and monitoring battery condition during charging so that an over-temperature cell is caught (A3 of SCN-003, NEED-006). These two are instructor suggestions for teams to add, not reference elements; they also illustrate that scenarios discover capabilities, not only the other way round.`,`Gap analysis (graduate task; method from SEBoK v2.14, “Enterprise Capability Management”, p. 862, all numbers FICTIONAL). Desired capacity follows from demand and the 80 % utilisation ceiling of MGO-007: planning demand of 160, 240 and 320 trips/day in years 1–3 needs 200, 300 and 400 trips/day of capacity (demand ÷ 0.8). The baseline for CAP-001 is the current plan: 12 aircraft × 20 trips per aircraft per day (the reference figure, net of availability) = 240 trips/day, with no further aircraft on order. The baseline for CAP-003 depends on an assumption that must be stated: how long one aircraft holds a turnaround charger. The course convention is reference assumption A-007: the 25 min hub turnaround of Week 4’s REQ-STK-005 is 5 min of pad work (rotor stop, safety check, connection) plus 20 min of charging (REQ-SYS-001), and each hub has two pads per turnaround charger, so a charger is busy only for the 20 min charge of each turnaround — the reading the Week 1 dynamics model and the Week 7 trade study also use. That gives 6 turnaround chargers (A-002) × 960 min ÷ 20 min = 6 × 48 = 288 charges/day. Since every trip ends in one turnaround charge in the reference cycle, the same desired levels apply. The sensitivity row tests the assumption: if the charger were held for the whole 25 min turnaround (boarding on the charger), each charger gives 38.4 charges a day and the baseline is 230. Both charging baselines are upper bounds, because they assume every charger is in use back-to-back for the whole 16 h day. Balanced means within ±5 % of desired (a course convention); a shortfall inside the band against an upper-bound baseline is a probable gap.`,`Reading the table: year 1 shows excess in both capabilities — start-up headroom that SEBoK v2.14, “Enterprise Capability Management” would have the enterprise question, though some of it is the price of being ready for growth. Under the convention the chargers (288) exceed the fleet (240), so the network’s year-1 capacity is 240 trips/day and aircraft bind first; in the 25 min sensitivity case the chargers (230) fall below the fleet and charging would bind first. In year 2 the fleet is short by 60 trips/day, which at 20 trips per aircraft per day is 3 more aircraft. Charging shows 288 against 300 (−12, −4 %): inside the band, but against an upper bound, so a probable gap, closed by 1 more turnaround charger (12 ÷ 48 = 0.25, rounded up). In the sensitivity case charging is short by 70 charges/day (−23 %), about 2 more chargers (70 ÷ 38.4 = 1.8, rounded up). The assumption test is therefore decisive and robust: under either reading charging is short by year 2, and buying three aircraft alone would move the bottleneck to the chargers (R-001, the Week 1 Limits-to-Growth (charging limit) structure). By year 3 the fleet needs 8 more aircraft (160 ÷ 20) and charging 3 more turnaround chargers under the convention (112 ÷ 48 = 2.3, rounded up), or 5 in the sensitivity case (170 ÷ 38.4 = 4.4, rounded up): the occupancy assumption changes the size of the order, not the conclusion. Before anyone orders hardware, MITRE’s advice applies: test non-materiel options first — schedule shaping, pricing that moves demand off the peak, overnight charging at spokes (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295).`],table:{caption:`Capability-gap analysis (ALL VALUES FICTIONAL). Delta = baseline − desired; negative is a gap.`,header:[`Capability (unit)`,`Year 1: baseline / desired`,`Year 2: baseline / desired`,`Year 3: baseline / desired`,`First gap`],rows:[[`CAP-001 On-demand passenger transport (trips/day)`,`240 / 200 → excess +40`,`240 / 300 → GAP −60 (≈ 3 aircraft)`,`240 / 400 → GAP −160 (8 aircraft)`,`Year 2`],[`CAP-003 Fleet charging management, 20 min per charge (A-007 convention; upper bound) (charges/day)`,`288 / 200 → excess +88`,`288 / 300 → −12, inside ±5 % of an upper bound: PROBABLE GAP (≈ 1 charger)`,`288 / 400 → GAP −112 (3 chargers)`,`Year 2 (probable)`],[`CAP-003 sensitivity, 25 min per charge (charger held for the whole turnaround; upper bound)`,`230 / 200 → excess +30`,`230 / 300 → GAP −70 (≈ 2 chargers)`,`230 / 400 → GAP −170 (5 chargers)`,`Year 2`]]},citations:[{reading:`R12`,pages:`862`},{reading:`R53`,pages:`294–295`}],provenance:`mixed`},{id:`w3-worked-scn`,kind:`worked-example`,title:`Worked example (c): a complete ConOps scenario — SCN-005 Weather Disruption`,paragraphs:[`First fix the boundary and the actor. MITRE defines actors as parties outside the system that interact with it: classes of users, roles users play, or other systems (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 453). So the course draws the scenario boundary round AeroLink’s operational system — aircraft, booking, scheduling and dispatch systems and the operations-support tools — and treats the people who use it, operations-centre staff included, as users outside it (a course choice; MITRE does not discuss operations staff). The operations-centre duty manager is then the primary actor: the scenario serves that user’s goal of keeping every flight within limits while recovering service. Weather (EXT-003) is listed but does not act: it is an environmental factor that affects the scenario, so no step is given to it. Choosing passengers as the primary actor would give a different and also valid use case about re-accommodation; the team must say which it wrote. The scenario exercises CAP-005 Weather-aware operations, and its success is measured against MGO-008 (no dispatch outside limits).`,`The flow has seven steps and three alternate flows, each branching from a named step with a stated condition and a stated outcome. The table is the reference SCN-005 itself, so the model answer and the worked example cannot drift apart, and every reference scenario passes the builder’s ten checks (test-asserted). Notice what the scenario does not say: it names no forecast provider, no screen, no message channel — those are design choices for Week 8 — and it does not quantify the gust limit, which is unknown (U-001, held as TBD-01) and must stay visibly unknown rather than be invented. What it does say is testable in operation: who decides, on what trigger, what happens to the airborne aircraft, and what the passengers experience.`,`Writing the scenario discovers things. Step 5 reveals that passengers need to be told promptly, with a usable alternative, when their flight is disrupted — a need that is not in NEED-001..010. That is MITRE’s “validate and discover implicit requirements” objective in action (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301); the reference records it as NEED-011, derived from STK-001 and CON-001 and met by CAP-005. A2 reveals a dependency on the public transport network (EXT-005) for which there is no agreement — an assumption, recorded in the reference AROU v1 as A-008 (public-transport fallback is available during weather holds), which affects SCN-005. And step 3 depends on alternates being reachable within the 20 % energy reserve, which links the scenario to the Week 4 energy-planning requirement and to the Week 6 risk on reserve margins.`],table:{caption:`SCN-005 Weather Disruption (official S04 Lab 7 scenario; values FICTIONAL)`,header:[`Part`,`Content`],rows:[[`Capability and objective`,`Derives from CAP-005 Weather-aware operations; success measured against MGO-008`],[`Primary actor`,`Operations-centre duty manager (a user of the operational system): keep every flight within limits while recovering service`],[`Other actors`,`Passengers (STK-001); pilot or remote operator (STK-008); ANSP (EXT-001). Environmental factor (affects, does not act): weather (EXT-003)`],[`Trigger`,`The forecast for a vertiport crosses a weather limit within the next 30 min (limits TBD-01, U-001)`],[`Preconditions`,`Flights scheduled, some airborne; weather data received for all six vertiports; alternates and the 20 % energy-reserve policy in force`],[`Main flow`,`1 AeroLink: flags V3 as approaching its weather limits and lists affected departures, arrivals and airborne flights. 2 Duty manager: declares a hold — no departures to or from V3. 3 Pilot/remote operator (STK-008): diverts each airborne flight bound for V3 to its planned alternate within the reserve. 4 ANSP: accepts the revised flight intents. 5 AeroLink: notifies affected passengers of a new time, an alternate vertiport or a refund. 6 Passengers: each accepts a new time or vertiport, or takes the refund. 7 Duty manager: lifts the hold when the forecast has been back inside limits for 30 min; the backlog is re-timed`],[`A1 (step 3)`,`The alternate also approaches limits while airborne → divert to the nearest open vertiport within the reserve; if none is reachable, declare a priority landing with the ANSP → rejoin at step 5`],[`A2 (step 2)`,`Two or more vertiports reach limits (region-wide) → suspend all departures; land airborne flights at the nearest open vertiport; offer public transport (EXT-005) → scenario ends`],[`A3 (step 7)`,`The hold lasts more than 2 h → cancel the day’s remaining bookings to V3 and refund; reposition aircraft for the next morning → scenario ends`],[`Success end state`,`All aircraft on the ground or safely diverted; no flight dispatched outside limits; backlog flown within the day`],[`Failure / degraded end state`,`Service at V3 suspended for the day; every affected passenger re-accommodated or refunded; still no flight outside limits`],[`Environment and constraints`,`Gust, crosswind and visibility limits unknown (TBD-01); 20 % energy reserve; ANSP acceptance needed for every diversion`]]},citations:[{reading:`R59`,pages:`453–455`},{reading:`R52`,pages:`301`}],provenance:`mixed`},{id:`w3-advanced`,kind:`advanced`,title:`Advanced analysis: is the integrated set of needs consistent and complete?`,paragraphs:[`SEBoK asks for an integrated set of needs that is correct, consistent, complete and feasible (SEBoK v2.14, “Stakeholder Needs Definition”, p. 551). It names the aids — models and diagrams are key to correctness, completeness and consistency (SEBoK v2.14, “Stakeholder Needs Definition”, p. 554), and stakeholders confirm the set through traceability (SEBoK v2.14, “Stakeholder Needs Definition”, p. 556) — but it gives no pass/fail test. Three analytical moves make the four characteristics checkable for AeroLink. Consistency: lay the needs against the Week 2 conflict matrix. NEED-001 (short waits), NEED-003 (noise within the agreement) and NEED-005 (capacity in step with demand) share decision variables — departures per pad-hour, operating hours, residential sites — and pull in different directions. SEBoK says business and user MGOs may conflict and must be prioritised by enterprise strategy (SEBoK v2.14, “Business or Mission Analysis”, p. 546); applied to needs, an inconsistency is resolved by stating the priority and the trade, not by weakening the wording until the conflict disappears.`,`Completeness: a needs set derived only from interviews reflects whoever was interviewed. MITRE warns that operational needs can be driven by a subset of stakeholders and miss key needs (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 297), and SEBoK asks elicitation to cover off-nominal use cases, misuse cases and loss scenarios for every life-cycle stage (SEBoK v2.14, “Stakeholder Needs Definition”, p. 553). Run MITRE’s parameterisation list (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 456) against the needs: “good actors doing bad things” suggests a passenger who books every peak slot and cancels late; “exceptional circumstances” suggests a battery fire, which NEED-006 covers, and a region-wide power cut, which no reference need covers. SEBoK’s own misuse example — someone hacking an aircraft to use it as a weapon (SEBoK v2.14, “Stakeholder Needs Definition”, p. 554) — is a reminder that security needs have stakeholders too.`,`Feasibility and level: the capability-gap analysis is a feasibility test of the needs at a horizon. If no plausible combination of fleet, chargers and schedule closes the year-3 gap, the honest response is to revisit the objective (MGO-007) with the stakeholders, not to keep a need nobody can meet. And the solution class is still open: MITRE notes that a gap may be met by changes to doctrine, organisation, training, logistics, personnel or facilities rather than new materiel (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295), and SEBoK lists operational change as a solution class alongside new or modified systems (SEBoK v2.14, “Business or Mission Analysis”, p. 547). MITRE’s “one size may not fit all” lesson completes the picture: the union of all needs may lead to a solution too cumbersome to build, and several solutions to subsets of needs, or iterative augmentation, may be more practical (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 297).`,`The loop that ties the week together is iterative, as SEBoK says of mission analysis and needs definition (SEBoK v2.14, “Business or Mission Analysis”, p. 543). Scenarios discover needs (step 5 of SCN-005); needs generate capabilities; capability gaps test the objectives; objectives constrain the scenarios. A CP1 package in which this loop has visibly run at least once — a need added because a scenario exposed it, an objective revised because a gap could not be closed — is stronger evidence of systems thinking than a longer list.`],citations:[{reading:`R11`,pages:`551–556`},{reading:`R10`,pages:`543–547`},{reading:`R53`,pages:`294–297`},{reading:`R59`,pages:`456`}],provenance:`mixed`},{id:`w3-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`The sequence from need to capability to acquisition is formalised in defence acquisition. MITRE describes the DoD JCIDS process: a capabilities-based assessment identifies the mission, required capabilities and their attributes, gaps, potential solutions and operational risks; if a materiel solution is needed, an initial capabilities document records the capability needs with their attributes and metrics; an analysis of alternatives then trades cost and effectiveness, and its results shape the solution-specific capability development document (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 295). MITRE notes that such assessments are typically required by formal programmes run by organisations such as the DoD and the Federal Aviation Administration (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294). Capability management is no longer seen as only a defence and aerospace concern; SEBoK reports that it is increasingly recognised in commercial and civil government work (SEBoK v2.14, “Enterprise Capability Management”, p. 863).`,`For ConOps, IEEE Std 1362-1998 is the commonly used guideline MITRE cites, with the caution that each organisation should develop its own practices and procedures for applying it (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 300). MITRE recommends that the ConOps written at the start of an acquisition be updated after developmental and operational testing, because fielded systems gain capabilities not envisioned at the start and lose some to trade-offs (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 299). Mission threads are used as drivers for architecture and as the basis of test cases (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 453), and MITRE recommends feeding them with simulated inputs and outputs (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 457). For AeroLink this sets the path for the rest of the course: the scenarios become the operational view and functional threads in Week 8, SCN-001 becomes a SysML v2 action flow in Week 11, and the scenarios’ success and failure end states become the starting point for verification cases in Week 12.`],citations:[{reading:`R53`,pages:`294–295`},{reading:`R12`,pages:`863`},{reading:`R52`,pages:`299–300`},{reading:`R59`,pages:`453–457`}],provenance:`mixed`},{id:`w3-lab`,kind:`lab`,title:`Lab L3 — needs → capabilities; three scenarios`,paragraphs:[`In teams, starting from your L2 stakeholders and concerns: record the mission, at least two goals and at least three measurable objectives with the MGO recorder; write at least eight solution-free needs with the need-statement studio, each derived from a stakeholder or concern and accepted by the studio’s screen and a team review; derive at least five capabilities, at least two of them decomposed, with the capability builder until every need is covered; then build the three required scenarios (nominal SCN-002, weather SCN-005, and charging SCN-003 or maintenance SCN-004) with the scenario builder. All four tools write to your AeroLink workspace with the course ID scheme, and each records the owner’s initials and a provenance tag (including AI-suggested-reviewed).`],citations:[],provenance:`instructor-authored`},{id:`w3-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: CP1 Problem Definition & ConOps, due at the end of Week 3 — 7 % of the course grade, scored RB-1 45 % · RB-2 45 % · RB-12 10 %, with written feedback. It integrates the L1 context, the L2 stakeholder map and AROU, and this week’s MGOs, needs, capabilities and scenarios. Individual: readiness quiz Q3 and review-notebook entry 3 with a time log.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w3-act-mgo`,title:`Mission, goals and objectives recorder`,component:`w03-mgo-recorder`,purpose:`Record AeroLink’s mission, goals and objectives as a hierarchy. SEBoK keeps objectives and measures as separate levels; by course convention each objective is recorded with its measure (MOE), target, unit and horizon and traced to a concern directly or through its goal.`,instructions:[`Record the mission first and trace it to the concerns it answers.`,`Record at least two goals, each elaborated from the mission.`,`Record at least three objectives, each elaborated from a goal, with its measure (MOE), numeric target, unit and horizon (targets are FICTIONAL team values). The objective statement may stay qualitative, as in SEBoK’s example; the measure carries the number.`,`Enter the owner’s initials and the provenance for every item; tag anything an AI tool suggested AI-suggested-reviewed.`,`Note which objectives take the user’s perspective and which the business’s (SEBoK v2.14, “Business or Mission Analysis”, p. 546).`],objectives:[`B3.1`],inBlock:`w3-mission`},{id:`w3-act-needs`,title:`Need-statement studio`,component:`w03-need-studio`,purpose:`Diagnose solution-laden “needs”, then write need statements that pass six source-cited criteria and record them as NEED items traced to stakeholders and concerns.`,instructions:[`Part A: tick the flaws in each draft statement and write your own rewrite before checking; argue any disagreement with the key from the criteria.`,`Part B: write each need as “<stakeholder> need(s) …”, with a condition and a rationale; choose the STK and CON it derives from.`,`Fix every criterion marked “Fix”; the screen is lexical, so also read your statement for solutions in plain words. L3 accepts a need that passes the screen and a team review.`,`Record at least eight needs for L3.`],objectives:[`B3.2`],inBlock:`w3-worked-needs`},{id:`w3-act-caps`,title:`Capability tree and gap builder`,component:`w03-capability-tree`,purpose:`Derive capabilities from needs, decompose them, see coverage gaps computed from the workspace, and run a near/mid/far capability-gap analysis.`,instructions:[`Record each capability as an ability of the enterprise, derived from the needs it serves.`,`Decompose at least two capabilities by recording constituents with a parent; respond to any single-constituent advisory.`,`Work until every L3 check passes and no need is uncovered.`,`Part B (graduate): load the worked example, check its arithmetic, then enter your own capability with baseline and desired levels per horizon, mark any upper-bound baseline, test one assumption by changing the value it drives, and interpret the first gap.`],objectives:[`B3.3`],inBlock:`w3-worked-caps`},{id:`w3-act-scn`,title:`ConOps scenario builder`,component:`w03-scenario-builder`,purpose:`Construct operational scenarios with actors, trigger, preconditions, main flow, alternate flows and end states, checked against the L3 acceptance criteria and MITRE’s use-case guidance.`,instructions:[`Load the SCN-005 worked example and read why each check passes; then clear it and build your own.`,`Choose the official S04 Lab 7 scenario you are writing; record SCN-002, SCN-003/004 and SCN-005 for L3.`,`Every step names an actor; every alternate flow branches from a step, states its condition and says whether it rejoins or ends. Mark natural factors such as weather as environmental: they affect the scenario but do not act.`,`Keep interface and implementation detail out of the steps.`],objectives:[`B3.4`],inBlock:`w3-worked-scn`}],lab:{id:`L3`,title:`Needs → capabilities; three scenarios`,setting:`team`,durationMinutes:75,objectives:[`B3.1`,`B3.2`,`B3.3`,`B3.4`],inputs:[`L2 record: STK map (≥ 12 STK), CON list, relationships and conflict analysis, AROU v0 (A-001, A-002, A-007, R-001, O-001, U-001 in the reference)`,`L1 record: ENT-001 boundary and EXT list`,`AeroLink Data Sheet (FICTIONAL values)`,`This week’s four activities (MGO recorder, need studio, capability builder, scenario builder)`],steps:[{title:`Mission, goals, objectives`,detail:`Write the problem/opportunity statement and obtain stakeholder concurrence with it (SEBoK v2.14, “Business or Mission Analysis”, p. 545, step 4); in the lab, another team role-plays the stakeholders and the instructor plays the approving authority (a course simplification). Record the mission, ≥ 2 goals and ≥ 3 objectives with the MGO recorder; every objective carries its measure, target, unit and horizon (course convention) and traces to a concern directly or through its goal. Label one user-perspective and one business-perspective objective.`},{title:`Needs`,detail:`For each STK, turn its concerns into needs with the need studio: ≥ 8 NEED, each passing the studio’s screen and a team review (the screen is lexical and cannot see every solution) and derived from ≥ 1 STK/CON. Include at least one need of an approving authority (STK-002) and one of a non-customer stakeholder (community, responder or utility).`},{title:`Capabilities and decomposition`,detail:`Derive ≥ 5 CAP with the capability builder, ≥ 2 decomposed into constituents. Work until the builder reports no untraced capability and no uncovered need. Record why each single-constituent decomposition is complete, or add the missing constituents.`},{title:`Instructor checkpoint`,detail:`Each team reads out one before/after need and its capability tree; the instructor challenges one need for a hidden solution and one capability for a missing constituent.`},{title:`Three scenarios`,detail:`Build SCN-002 (nominal transport), SCN-005 (weather disruption) and SCN-003 (charging) or SCN-004 (maintenance) with the scenario builder: actors, trigger, preconditions, ≥ 3 steps with actors, ≥ 1 alternate flow each, success and failure end states, traced to a CAP. Record any need or AROU entry the scenarios expose.`},{title:`AROU v1 and record`,detail:`Bring AROU to v1 (≥ 4 entries, at least one new from the scenarios, e.g. the public-transport fallback assumption). Confirm the coverage lines in all four tools, export the workspace model (JSON) from the model workspace, and add it to the lab record.`}],artefacts:[{idPrefix:`MGO`,description:`Mission, goals and measurable objectives, traced to concerns`,minimum:`1 mission, ≥ 2 goals, ≥ 3 objectives with measure, target, unit, horizon`},{idPrefix:`NEED`,description:`Solution-free need statements with condition and rationale`,minimum:`≥ 8, each derived from ≥ 1 STK/CON`},{idPrefix:`CAP`,description:`Capabilities derived from needs, with decomposition (refines)`,minimum:`≥ 5, ≥ 2 decomposed; every NEED covered`},{idPrefix:`SCN`,description:`Operational scenarios with actors, preconditions, steps, alternates and end states`,minimum:`3: nominal (SCN-002), weather (SCN-005), charging (SCN-003) or maintenance (SCN-004)`},{idPrefix:`A/R/O/U`,description:`AROU v1`,minimum:`≥ 4 entries, ≥ 1 exposed by a scenario`}],continuity:`NEED items become the parents of Week 4 stakeholder requirements (REQ-STK derives-from NEED) and CAP items the parents of system requirements; MGO objectives become MOEs in Week 5; the capability-gap result and the Week 2 conflicts become trade-study criteria in Week 7; scenarios become the operational view and the source of functions (FN from CAP) in Week 8; in Week 10 needs map to SysML v2 requirements and in Week 11 scenarios map to use cases, with SCN-001 becoming an action flow. CP1 at the end of this week scores the whole chain with RB-1 and RB-2.`,tools:[{label:`Engineering model workspace (export, links)`,to:`/workspace/model`},{label:`Stakeholder ecosystem editor`,to:`/workspace/stakeholders`},{label:`Air Taxi Enterprise workspace (case brief and Data Sheet)`,to:`/workspace/aerolink`}]},assignment:{id:`CP1`,title:`CP1 Problem Definition & ConOps (team)`,mode:`team`,due:`End of Week 3 (course calendar)`,weight:`CP1: 7 % of the course grade (team): RB-1 45 % · RB-2 45 % · RB-12 10 %. Graduate gap analysis: review-notebook entry 3 (RB-16, 5 %), always read, formative on RB-2.3`,instructions:[`Submit one integrated package (document plus the workspace model export) covering the CP1 minimum scope in syllabus §11.`,`Every NEED traces to ≥ 1 STK or CON and every CAP to ≥ 1 NEED; the export must show these links (RB-2.5).`,`Use the official S04 Lab 7 scenario names and IDs for the three required scenarios.`,`Label every AeroLink number as FICTIONAL or cite its source; the course collection contains no real operator data.`,`Graduate students (individual): the capability-gap analysis over near/mid/far horizons (SEBoK v2.14, “Enterprise Capability Management”, p. 862) for at least two capabilities, with the arithmetic shown, every baseline assumption stated (including what the baseline already plans) and one assumption tested by recomputing with a changed value. Submit it as review-notebook entry 3; the team may also include it in CP1 §5.`,`Each member logs hours for the week in the review notebook (workload pilot).`],template:[{heading:`1. System context`,guidance:`System of interest and boundary with justification, including at least one rejected boundary option; ≥ 6 external systems (EXT) with the interactions that the three scenarios use (RB-1.1).`},{heading:`2. Stakeholders`,guidance:`≥ 12 STK in ≥ 4 classes, including the 6 external entities of S04 Lab 2A; each with a specific concern, interest and influence ratings with rationale; relationships and at least one conflict with its causal explanation (RB-1.2–1.4).`},{heading:`3. Problem statement and MGOs`,guidance:`The problem/opportunity statement and how stakeholders concurred; the mission, goals, objectives and measures as a hierarchy (SEBoK’s four levels); by course convention each objective is shown with its measure (MOE), target, unit and horizon and traced to a concern directly or through its goal; user and business perspectives identified and any conflict prioritised (RB-2.1).`},{heading:`4. Need statements`,guidance:`≥ 8 NEED in a table: ID, name, statement, condition, rationale, derives-from. No “shall”, no named solution; attribute each to a stakeholder. Include two before/after rewrites showing a solution removed (RB-2.2).`},{heading:`5. Capability analysis`,guidance:`≥ 5 CAP derived from needs, ≥ 2 decomposed, shown as a tree with a text equivalent; the coverage result (no uncovered need, no untraced capability); identified gaps and how they would be closed, including non-materiel options (RB-2.3). Graduate: the near/mid/far gap table and its interpretation.`},{heading:`6. ConOps and scenarios`,guidance:`MITRE’s critical components (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301), in order: (a) the existing situation (as-is) — for a new service, how passengers make these trips today (ground transport, EXT-005) and what limits it; (b) the justification for AeroLink, including its restrictions; (c) a description of the proposed AeroLink service (to-be) with its operational environment and constraints; (d) the scenarios: SCN-002, SCN-005 and SCN-003 or SCN-004, each with actors (primary marked), trigger, preconditions, main flow with an actor per step, ≥ 1 alternate flow, success and failure end states, and the capability it exercises. Note any need or assumption the scenarios exposed (RB-2.4).`},{heading:`7. Traceability and AROU v1`,guidance:`Trace table NEED → STK/CON and CAP → NEED (or the model export); AROU v1 with ≥ 4 entries linked to stakeholders, concerns or scenarios, risks in condition–if–then form (RB-1.5, RB-2.5).`},{heading:`8. AI usage statement`,guidance:`Tool, purpose, example prompts, outputs, your evaluation (specific errors found and corrected, with accept/reject reasons), and how every AI-suggested stakeholder, need or scenario step was reviewed and tagged AI-suggested-reviewed (RB-12.1–12.3).`}],rubrics:[`RB-1`,`RB-2`,`RB-12`],rubricScope:`CP1 (team): RB-1.1–1.5 in full (45 % of CP1), RB-2.1–2.5 in full (45 %), RB-12.1–12.3 (10 %), per syllabus §12. RB-2.2 counts needs with embedded solutions: ≤ 2 caps the criterion at level 3. RB-2.4 level 4 requires the four ConOps components of template §6. Graduate gap analysis (individual): a required review-notebook entry under RB-16, always read and not sampled (RB-16 graduate-task note); scored formatively on RB-2.3 (“gaps identified”) with these level descriptors — 4: table for ≥ 2 capabilities with correct arithmetic, every baseline assumption stated (including planned capability), one assumption tested by recomputation and the conclusion said to hold or flip, and a non-materiel option weighed; 3: correct table and interpretation but no assumption tested; 2: table without interpretation or with arithmetic errors; 1: missing. The set of graduate tasks informs RB-16.1; the team’s CP1 grade does not depend on it.`,aiUse:`AI tools may be used to brainstorm candidate needs, capabilities and off-nominal scenario conditions and to critique drafts. Every AI-suggested item is tagged AI-suggested-reviewed and individually checked against this week’s criteria (RB-12.3); AI drafts often slip solutions and “shall” into needs, so run each through the need studio. AI-generated numbers must be replaced by labelled FICTIONAL team values or cited.`,objectives:[`B3.1`,`B3.2`,`B3.3`,`B3.4`]},quiz:[{id:`q3-1`,bloom:`Apply`,objective:`B3.1`,prompt:`A team’s CP1 draft lists “Objective: give passengers an excellent boarding experience.” Which revision best keeps SEBoK’s levels and meets the course’s objective rule (RB-2.1: each objective recorded with its measure, target, unit and horizon, traced to a concern)?`,options:[{id:`a`,text:`“Objective: passengers board soon after confirming, and the quoted wait holds. Measure (MOE): at least 90 % of passengers in each month board within 15 min of confirming, from month 6.” Elaborated from goal MGO-002, which traces to CON-001`,correct:!0,explanation:`Correct. The objective is stated in SEBoK’s form and its measure is a quantitative MOE that validates it (SEBoK v2.14, “Business or Mission Analysis”, p. 544, 546); the course records the two together with target, unit and horizon, and the trace runs through the goal.`},{id:`b`,text:`“Objective: provide world-class boarding.”`,correct:!1,explanation:`Still unobservable puffery with no measure: rewording the adjective does not make it an objective.`},{id:`c`,text:`“Objective: the booking app shall assign an aircraft within 60 s.”`,correct:!1,explanation:`This is a design-level requirement (an app, “shall”), not a mission-level objective; it belongs, if anywhere, in Week 4.`},{id:`d`,text:`“Objective: minimise waiting.”`,correct:!1,explanation:`Close to SEBoK’s form of an objective — qualitative and directional, like its business objective “increase market share” — but no measure is attached. SEBoK pairs each objective with a measure (MOE), and the course rule records them together, so as it stands it is incomplete.`}],cite:{reading:`R10`,pages:`544–546`}},{id:`q3-2`,bloom:`Apply`,objective:`B3.1`,prompt:`Which statement is correctly placed at the level of a goal in AeroLink’s MGO hierarchy?`,options:[{id:`a`,text:`AeroLink provides safe, quiet, on-demand air trips between the six vertiports of one region`,correct:!1,explanation:`This states why AeroLink exists — the mission, not a goal.`},{id:`b`,text:`Vertiport operations stay within what neighbouring communities have agreed to accept`,correct:!0,explanation:`Correct. It divides the mission into a manageable piece without yet stating the measure; MGO-006 then makes it measurable (SEBoK v2.14, “Business or Mission Analysis”, p. 543).`},{id:`c`,text:`Zero take-off or landing events above 65 dBA at any pad edge in each quarter`,correct:!1,explanation:`In SEBoK’s terms this is a measure (MOE) with its target, which validates an objective such as “take-offs and landings stay within the agreed limit”; the course records it with that objective as MGO-006. Either way it sits below the goal.`},{id:`d`,text:`Install quieter rotors on all aircraft`,correct:!1,explanation:`This is a solution, not part of the MGO hierarchy at all.`}],cite:{reading:`R10`,pages:`543`}},{id:`q3-3`,bloom:`Analyse`,objective:`B3.1`,prompt:`Investors propose raising the utilisation ceiling in MGO-007 from 80 % to 95 % so that fewer aircraft are bought. The 80 % ceiling exists to protect the waiting-time objective MGO-005. How does SEBoK’s mission-analysis guidance frame this?`,options:[{id:`a`,text:`Business objectives take precedence over user objectives, so raise the ceiling`,correct:!1,explanation:`SEBoK says both business and user perspectives must be addressed; neither automatically wins.`},{id:`b`,text:`There may be separate business and user MGO sets whose conflicts must be prioritised according to the enterprise strategy; the trade between fleet cost and the wait objective has to be made explicitly`,correct:!0,explanation:`Correct. SEBoK v2.14, “Business or Mission Analysis”, p. 546 describes exactly this: different perspectives, conflicting MGOs, prioritised by enterprise strategy.`},{id:`c`,text:`User objectives are fixed once stated; the investors’ proposal is out of scope`,correct:!1,explanation:`MGOs are agreed with stakeholders and can be revisited; refusing to analyse a business objective is not what SEBoK recommends.`},{id:`d`,text:`Merge the two objectives into one averaged target`,correct:!1,explanation:`Averaging hides the conflict instead of prioritising it; the wait objective would silently degrade.`}],cite:{reading:`R10`,pages:`546`}},{id:`q3-4`,bloom:`Apply`,objective:`B3.2`,prompt:`An insurer (STK-012) says in an interview: “We need a flight-data recorder in every aircraft so we can price your policy.” Which is the best need statement to record?`,options:[{id:`a`,text:`Insurers need a flight-data recorder in every aircraft, at all operating hours`,correct:!1,explanation:`Adding a condition does not remove the solution: a recorder is one way to evidence risk, alongside operational logs, maintenance records or incident reporting.`},{id:`b`,text:`The system shall record all flight data for insurers`,correct:!1,explanation:`“Shall” makes it a requirement, the system is not the stakeholder, and “all flight data” is a scope stated with no evidence basis (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 296).`},{id:`c`,text:`Insurers need AeroLink’s operational risk to be recorded and measurable throughout each policy period, so that premiums can be set on evidence`,correct:!0,explanation:`Correct. Attributed to the stakeholder, solution-free and with a condition; recorders, logs or reporting schemes all remain open (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 296; CON-014).`},{id:`d`,text:`There is a need for better data about risk`,correct:!1,explanation:`No stakeholder, no condition, and “better” than what is undefined.`}],cite:{reading:`R53`,pages:`296`}},{id:`q3-5`,bloom:`Analyse`,objective:`B3.2`,prompt:`In an interview a passenger representative says: “We need an app that shows our aircraft on a live map.” What is the best next step in elicitation?`,options:[{id:`a`,text:`Record it as NEED-011 exactly as stated, because the stakeholder said it`,correct:!1,explanation:`Recording an implementation as a need closes off alternatives; SEBoK asks for rationale precisely in this case.`},{id:`b`,text:`Ask why — what the map would let passengers do — and record the need that emerges (for example, knowing reliably when to leave for the vertiport), with the map kept as a candidate solution`,correct:!0,explanation:`Correct. Rationale often reveals the real need when a stakeholder expresses it as an implementation (SEBoK v2.14, “Stakeholder Needs Definition”, p. 553).`},{id:`c`,text:`Reject it, because stakeholders are not allowed to mention solutions`,correct:!1,explanation:`Stakeholders may mention solutions; the engineer’s job is to find the need behind them, and a ConOps can record acceptable solution strategies (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 302).`},{id:`d`,text:`Convert it to a requirement: “The app shall display aircraft positions”`,correct:!1,explanation:`This skips the need entirely and fixes a design before the trade study.`}],cite:{reading:`R11`,pages:`553`}},{id:`q3-6`,bloom:`Understand`,objective:`B3.2`,prompt:`Why does SEBoK recommend that need statements avoid the word “shall”?`,options:[{id:`a`,text:`Because needs are less important than requirements`,correct:!1,explanation:`Needs are the basis against which requirements, design and the realised system are validated; they are not less important.`},{id:`b`,text:`To keep needs, which express the stakeholders’ perspective, distinct from the design-input requirements they are later transformed into`,correct:!0,explanation:`Correct. SEBoK v2.14, “Stakeholder Needs Definition”, p. 555 recommends a different format, such as “The stakeholders need the system to …”, for exactly this reason.`},{id:`c`,text:`Because “shall” is legally binding and needs are not`,correct:!1,explanation:`SEBoK’s reason is the distinction between needs and requirements, not legal force.`},{id:`d`,text:`Because needs must be quantified and “shall” statements cannot be`,correct:!1,explanation:`Requirements with “shall” are routinely quantified, and the readings differ on quantifying needs — a ConOps may state them qualitatively (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 302), a needs assessment quantifies them where possible (The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295). Neither ties the no-“shall” rule to quantification.`}],cite:{reading:`R11`,pages:`555`}},{id:`q3-7`,bloom:`Analyse`,objective:`B3.3`,prompt:`A team analyses CAP-002 Ride booking and dispatch (FICTIONAL). Desired capacity in peak-hour requests handled: 60 / 90 / 120 in years 1–3. Today the dispatch desk handles 100 per peak hour, and an upgrade already funded for year 2 adds 20. What is the soundest reading?`,options:[{id:`a`,text:`A gap in year 2, because the upgrade is not in service today`,correct:!1,explanation:`SEBoK’s baseline is what exists plus what is already planned (SEBoK v2.14, “Enterprise Capability Management”, p. 862), so the year-2 baseline is 120, not 100.`},{id:`b`,text:`No gap through year 3 (baselines 100 / 120 / 120 against 60 / 90 / 120), but year 3 is exactly balanced only because of the planned upgrade, so its delivery is the assumption to test: if it slips, year 3 becomes a gap of 20`,correct:!0,explanation:`Correct. Desired levels are compared with the baseline including planned capability, per time bucket (SEBoK v2.14, “Enterprise Capability Management”, p. 862), and a conclusion that rests on one planned item must be tested against it.`},{id:`c`,text:`Excess in every year, so cancel the upgrade`,correct:!1,explanation:`Without the upgrade year 3 falls 20 short; the excess in years 1–2 is start-up headroom, not a reason to drop the year-3 capability.`},{id:`d`,text:`A gap cannot be judged until the upgrade’s cost is known`,correct:!1,explanation:`Cost matters when choosing how to close a gap, not when identifying it.`}],cite:{reading:`R12`,pages:`862`}},{id:`q3-8`,bloom:`Apply`,objective:`B3.3`,prompt:`CAP-006 Fleet health management (“know the condition of each aircraft and its battery, and withhold unfit aircraft from dispatch”) has no recorded constituent. Which is the best constituent capability to add?`,options:[{id:`a`,text:`Install vibration sensors on every rotor and stream the data to the cloud`,correct:!1,explanation:`A design choice (sensors, cloud), not an ability; it may be one way to provide the capability after the Week 7 trade study.`},{id:`b`,text:`Forecast component wear from operating data so that maintenance is planned before a no-go fault occurs`,correct:!0,explanation:`Correct. A distinct ability that, with withholding unfit aircraft, makes up the parent; it says what, not how, and links to SCN-004’s predicted faults.`},{id:`c`,text:`Know the condition of each aircraft and its battery`,correct:!1,explanation:`This restates the parent rather than decomposing it; a constituent must be a part of the ability, not the whole of it again.`},{id:`d`,text:`Keep fleet availability as high as possible`,correct:!1,explanation:`An unmeasured aspiration at the level of an objective; it names no ability and has no level to compare with a baseline.`}],cite:{reading:`R12`,pages:`862`}},{id:`q3-9`,bloom:`Apply`,objective:`B3.3`,prompt:`After a team deletes CAP-009 Incident response support, the capability builder reports “Needs with no capability: NEED-006”. What is this finding and the right response?`,options:[{id:`a`,text:`An untraced capability; delete NEED-006 as well`,correct:!1,explanation:`An untraced capability is a CAP with no NEED. Here it is the opposite, and deleting a stakeholder’s need to fix coverage is not acceptable.`},{id:`b`,text:`A coverage gap in the derivation: the emergency responders’ need has no capability, so derive one (or restore CAP-009) and trace it to NEED-006`,correct:!0,explanation:`Correct. Capabilities exist to meet needs (SEBoK v2.14, “Enterprise Capability Management”, p. 862); every need must be met by at least one capability in the L3 acceptance check.`},{id:`c`,text:`A capability gap in SEBoK’s sense, to be filled by buying fire engines`,correct:!1,explanation:`A SEBoK capability gap compares the desired level with the baseline (existing plus planned), and an absent capability is a gap too (SEBoK v2.14, “Enterprise Capability Management”, p. 862) — but the finding here is a missing derivation in the team’s model, and “buying fire engines” names a solution before any gap has been analysed.`},{id:`d`,text:`Not a problem, because NEED-006 belongs to an external stakeholder`,correct:!1,explanation:`External stakeholders’ needs are part of the integrated set; emergency responders can impose operating conditions.`}],cite:{reading:`R12`,pages:`862`}},{id:`q3-10`,bloom:`Analyse`,objective:`B3.4`,prompt:`Which alternate flow for SCN-003 Aircraft Charging is best formed?`,options:[{id:`a`,text:`“A3: cell over-temperature alarm — the charging system shuts down.”`,correct:!1,explanation:`A real condition, but no branch step and no outcome: the reader cannot tell where it starts or whether the scenario rejoins or ends, and the aircraft’s fate is missing.`},{id:`b`,text:`“A3 (step 3): cell over-temperature alarm during charging — stop charging, isolate the aircraft, start the fire-response procedure; scenario ends with the aircraft withdrawn from service.”`,correct:!0,explanation:`Correct. It branches from a named step under a stated condition and ends in a stated failure end state (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 453–454).`},{id:`c`,text:`“A3 (step 3): the operator presses the red Stop button on the charger screen.”`,correct:!1,explanation:`A branch step but interface detail and no condition or outcome; use cases specify intent, not the interface (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 454).`},{id:`d`,text:`“A3 (step 3): charging takes longer than 20 min — notify scheduling.”`,correct:!1,explanation:`Branch step and condition, but a symptom rather than a cause, and no outcome: does the aircraft rejoin at release or is it withdrawn?`}],cite:{reading:`R59`,pages:`453–454`}},{id:`q3-11`,bloom:`Analyse`,objective:`B3.4`,prompt:`A team’s SCN-005 step reads: “Passenger taps ‘Rebook’ on the app home screen and selects a new slot from the dropdown.” What is the best critique?`,options:[{id:`a`,text:`Fine: the more detail, the better the scenario`,correct:!1,explanation:`MITRE lists “too much detail too early” and interface details in use-case text among the common mistakes (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 455).`},{id:`b`,text:`It specifies the interface rather than the intent; rewrite as “AeroLink offers each affected passenger a new boarding time, an alternate vertiport or a refund”, leaving the interface to design`,correct:!0,explanation:`Correct. Use cases specify intent, not interface design or implementation detail (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 454).`},{id:`c`,text:`Keep the wording but move the step into an alternate flow, so the main flow stays readable`,correct:!1,explanation:`Relocating it keeps the interface detail in the use case; the pitfall is the content, not where it sits (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 455).`},{id:`d`,text:`Remove the passenger: scenarios should only contain system steps`,correct:!1,explanation:`Use cases are interactions between actors and the system; actors’ steps belong in them (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 453).`}],cite:{reading:`R59`,pages:`454–455`}},{id:`q3-12`,bloom:`Apply`,objective:`B3.4`,prompt:`A team submits only the nominal transport scenario, arguing that “off-nominal cases will be handled in the requirements”. Which response is best supported?`,options:[{id:`a`,text:`Accept it: only the nominal scenario matters for a ConOps`,correct:!1,explanation:`This is the target misconception; RB-2.4 scores “nominal only” at level 2.`},{id:`b`,text:`Reject it: a use case records paths that fall short of the goal as well as success paths, ConOps scenarios include internal and external factors, and L3 requires weather and charging/maintenance scenarios, each with an alternate flow`,correct:!0,explanation:`Correct. Failure scenarios are part of a use case (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 454), scenarios in the user’s environment are a critical ConOps component (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301), and L3 sets the minimum.`},{id:`c`,text:`Accept it if the requirements are long enough`,correct:!1,explanation:`Off-nominal scenarios are how many requirements are discovered; deferring them loses the discovery (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301).`},{id:`d`,text:`Ask them to add more nominal scenarios instead`,correct:!1,explanation:`More of the same does not cover exceptional circumstances (The MITRE Systems Engineering Guide, “Use Cases and Mission Threads”, p. 456).`}],cite:{reading:`R59`,pages:`453–454`}},{id:`q3-13`,bloom:`Understand`,objective:`B3.4`,prompt:`A stakeholder says the ConOps is “just a brochure for the city council”. Which statement about a CONOPS is consistent with MITRE?`,options:[{id:`a`,text:`It is a marketing summary of the product’s features`,correct:!1,explanation:`MITRE describes a user-oriented document about operations; a feature brochure lacks the scenarios and justification.`},{id:`b`,text:`It describes the system from the user’s perspective, in the user’s language, and always keeps critical components including the existing system, the justification, a description of the proposed system and scenarios of its use in the user’s environment`,correct:!0,explanation:`Correct (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 298–302).`},{id:`c`,text:`It is a technical specification with quantified, testable requirements`,correct:!1,explanation:`MITRE says a ConOps lets users state needs without testable specifications; quantification comes later (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 302).`},{id:`d`,text:`It is written once at the start and then archived`,correct:!1,explanation:`MITRE recommends updating it after developmental and operational testing (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 299).`}],cite:{reading:`R52`,pages:`299–302`}},{id:`q3-14`,bloom:`Apply`,objective:`B3.4`,prompt:`While writing SCN-004’s alternate “part not in stock”, a team realises that investors need early notice when aircraft out of service will push capacity below plan — and no existing need covers it. What should they do?`,options:[{id:`a`,text:`Ignore it: scenarios may only use needs already recorded`,correct:!1,explanation:`Discovering implicit needs and requirements is one of the stated objectives of a ConOps (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301).`},{id:`b`,text:`Add a new solution-free need derived from STK-003 (and CON-005), then check whether a capability such as CAP-008 capacity planning covers it`,correct:!0,explanation:`Correct. Mission analysis and needs definition are iterative (SEBoK v2.14, “Business or Mission Analysis”, p. 543), and the ConOps exists partly to validate and discover implicit requirements (The MITRE Systems Engineering Guide, “Concept of Operations”, p. 301).`},{id:`c`,text:`Record it only as a risk in AROU v1, because it is about capacity`,correct:!1,explanation:`A risk entry may also be right, but it does not record the stakeholder’s need, so nothing derives a capability or later a requirement from it.`},{id:`d`,text:`Write “The fleet system shall e-mail investors weekly” into the alternate flow`,correct:!1,explanation:`That inserts a design and a requirement into the scenario and skips the need.`}],cite:{reading:`R52`,pages:`301`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min)`,hours:2.5},{activity:`Online direct instruction and the four interactive activities (the recorders are started in Session 2)`,hours:.7},{activity:`Readings SEBoK v2.14, “Business or Mission Analysis”, SEBoK v2.14, “Stakeholder Needs Definition”, The MITRE Systems Engineering Guide, “Concept of Operations”, The MITRE Systems Engineering Guide, “Use Cases and Mission Threads” (≈ 26 pp at ≈ 15 pp/h)`,hours:1.7},{activity:`Readiness quiz Q3 / knowledge check`,hours:.3},{activity:`L3 completion out of class (team share)`,hours:2.4},{activity:`CP1 integration into the 8-section package and AI statement (team share; tight, see cautions)`,hours:1},{activity:`Graduate gap analysis (notebook entry 3): SEBoK v2.14, “Enterprise Capability Management”, p. 862 and The MITRE Systems Engineering Guide, “Operational Needs Assessment”, p. 294–295 (≈ 0.2 h), table for two capabilities with one assumption tested (≈ 1.0 h)`,hours:1.2},{activity:`Review notebook time log`,hours:.2}],references:[{reading:`R12`},{reading:`R53`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},s=[{id:`F1`,flawed:`The aircraft shall be quiet and shall be safe to operate near homes.`,type:`performance`,findings:[{flaw:`Two “shall”s: two obligations that will be verified, allocated and changed separately.`,characteristic:`Singular`,cite:{reading:`R48`,pages:`144`}},{flaw:`“Quiet” and “safe” have no measurable criterion; residents, the OEM and the regulator would each read them differently.`,characteristic:`Unambiguous; measurable/quantifiable`,cite:{reading:`R54`,pages:`329`}}],heuristics:[`single-shall`,`vague`,`measurable`],reviewOnly:`“Safe” is not one requirement but many: it has to be decomposed into specific hazards (battery fire, energy reserve, weather) that become their own requirements.`,rewriteId:`REQ-SYS-002`,rewrite:`The eVTOL aircraft shall produce no more than 65 dBA LAmax at the pad edge during take-off and landing on the published vertiport procedures.`},{id:`F2`,flawed:`The booking app should respond quickly to ride requests.`,type:`performance`,method:`demonstration`,findings:[{flaw:`“Should” is not binding in a specification.`,characteristic:`Uses “shall” for binding provisions`,cite:{reading:`R54`,pages:`330`}},{flaw:`“Quickly” cannot be tested: no value, no unit, no starting event.`,characteristic:`Testable (vague statements avoided)`,cite:{reading:`R54`,pages:`329`}},{flaw:`Demonstration cannot give the quantitative assurance a response-time requirement needs.`,characteristic:`Verification method appropriate`,cite:{reading:`R49`,pages:`149`}}],heuristics:[`single-shall`,`binding`,`vague`,`measurable`,`method-fit`],reviewOnly:`“The booking app” names one implementation. The obligation belongs to the scheduling function, whatever software or people perform it.`,rewriteId:`REQ-SYS-005`,rewrite:`The scheduling function shall assign a dispatch-ready aircraft to at least 99 % of confirmed ride requests within 60 s of confirmation.`},{id:`F3`,flawed:`The charging system shall charge each aircraft using two 350 kW DC fast chargers per hub pad.`,type:`performance`,method:`inspection`,findings:[{flaw:`States how (charger type, rating and count), not what (the charge time the turnaround needs). It removes the designer’s white space and fixes a cost.`,characteristic:`Design-free`,cite:{reading:`R54`,pages:`330`}},{flaw:`Inspection would confirm the chargers exist, not that the turnaround is met.`,characteristic:`Verifiable`,cite:{reading:`R48`,pages:`144`}}],heuristics:[`design-free`,`method-fit`],reviewOnly:`The heuristics accept “350 kW” as a measurable value, and they flag the design only through word patterns (“using”, a count or rating in front of “chargers”). A variant such as “shall have enough charging hardware at each hub for a 350 kW draw” passes them; only a reviewer sees that the number constrains the design rather than the performance the stakeholder needs.`,rewriteId:`REQ-SYS-001`,rewrite:`The charging system shall charge an aircraft from any landing state of charge at or above the 20 % reserve to the dispatch threshold within 20 min.`},{id:`F4`,flawed:`The fleet shall maximize availability.`,type:`performance`,method:`analysis`,findings:[{flaw:`“Maximize” forces an engineer to judge when the design is good enough, and invites a contractual argument.`,characteristic:`Avoid “maximize”/“minimize”`,cite:{reading:`R55`,pages:`370`}},{flaw:`No threshold or measurement period, so no verification can pass or fail.`,characteristic:`Measurable/quantifiable`,cite:{reading:`R48`,pages:`144`}}],heuristics:[`vague`,`measurable`],rewriteId:`REQ-SYS-006`,rewrite:`The fleet shall achieve an availability of at least 90 % of scheduled aircraft-hours in each calendar month.`},{id:`F5`,flawed:`The operations system shall not dispatch flights in unsafe weather.`,type:`functional`,method:`demonstration`,findings:[{flaw:`A prohibition is very difficult to prove.`,characteristic:`Avoid “shall not”`,cite:{reading:`R55`,pages:`370`}},{flaw:`“Unsafe weather” hides an unknown: the aircraft weather limits are not yet published.`,characteristic:`Unambiguous; TBX management`,cite:{reading:`R13`,pages:`565`}}],heuristics:[`negative`,`vague`],reviewOnly:`Seeing that the real problem is a missing value (TBD-01, tracked by U-001) rather than a wording slip takes engineering knowledge of the case.`,rewriteId:`REQ-SYS-004`,rewrite:`The operations system shall place a dispatch hold on any vertiport whose forecast wind or gust within the next 30 min exceeds the aircraft limit (TBD-01).`},{id:`F6`,flawed:`The vertiport fire detection system shall send a battery-fire alarm to the emergency services dispatch centre in 30 s.`,type:`interface`,method:`test`,findings:[{flaw:`“In 30 s” is a single point: is 29 s a failure? It also omits the event the time is measured from.`,characteristic:`Avoid one-point values; unambiguous`,cite:{reading:`R55`,pages:`370`}}],heuristics:[`range`],reviewOnly:`The missing start event (“of detection”) cannot be found by any word-level check; a reviewer has to ask “30 s from what?”.`,rewriteId:`REQ-SYS-009`,rewrite:`The vertiport fire detection system shall transmit a battery-fire alarm to the emergency services dispatch centre within 30 s of detection.`}];function c(e){return{level:`SYS`,name:`Critique ${e.id}`,text:e.flawed,type:e.type,method:e.method,criterion:``,rationale:``,parents:[],arou:[]}}var l=e({default:()=>u}),u={week:4,drivingQuestion:`Communities want AeroLink to be quiet, passengers want short waits, and the regulator wants every flight within limits. How do these needs become binding, verifiable obligations on the right part of the system, each with a reason, a parent and a way to prove it has been met, without writing the design into the requirement?`,blocks:[{id:`w4-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcome B-CLO2. In Week 3 you wrote solution-free need statements and capabilities for AeroLink. This week turns them into binding, verifiable requirements at two levels. Each requirement gets a rationale, a parent and a verification method, and is classified by type. The L4 set you write is the requirements baseline that the peer audit (Week 5), the SRR-style review (CP2, Week 6), the SysML v2 model (Weeks 9–11) and the verification plan (Week 12) all build on.`],bullets:[`B4.1 (Understand) Distinguish needs, stakeholder requirements and system requirements.`,`B4.2 (Create) Write well-formed requirements with rationale, parent and verification method.`,`B4.3 (Analyse) Classify requirements by type.`,`Graduate expectation: apply the MITRE system-level requirements checklist (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368–370) to your team’s set and argue each finding from the checklist item it rests on.`],citations:[],provenance:`instructor-authored`},{id:`w4-intuition`,kind:`intuition`,title:`Intuition: a contract clause you can, or cannot, dispute`,paragraphs:[`Suppose you hire a builder to “renovate the kitchen to a high standard, quickly”. When the work is finished you think it is poor and late, and the builder thinks it is excellent and on time. Neither of you can prove the other wrong, because the clause gives no test that both of you would accept. Now suppose the clause says “wall cabinets shall be level to within 2 mm over 1 m, and the work shall be complete within 15 working days of the start date”. You may still argue, but the argument ends when someone fetches a spirit level and a calendar.`,`A requirement is that kind of clause. It is an agreed obligation that a designer must meet and a verifier must be able to check. Two failures matter. The clause can be unverifiable, like “quiet” or “quickly”. Or the clause can dictate the solution, like “install brand-X cabinets”, which removes choices without saying what the owner actually needs. AeroLink’s communities need noise kept within the local agreement. “The aircraft shall be quiet” turns that need into an argument. “The eVTOL aircraft shall produce no more than 65 dBA LAmax at the pad edge” turns it into a measurement (65 dBA is a FICTIONAL Data Sheet value). This week is about writing the second kind of clause, and about knowing why each word is there.`],citations:[],provenance:`instructor-authored`},{id:`w4-levels`,kind:`concept`,title:`Needs, stakeholder requirements and system requirements`,paragraphs:[`SEBoK describes System Requirements Definition as the process that transforms the stakeholder view of desired capabilities into a technical, developer view of how the system of interest (SoI) can achieve them. Its outputs are the basis of architecture and design and of integration and verification, and they are also a means of communication within the project team (SEBoK v2.14, “System Requirements Definition”, p. 557). Needs express the stakeholders’ perspective, an external “black box” view of what they need the SoI to do. Requirements express the developer’s perspective, an internal “white box” view of what the SoI must do to meet those needs (SEBoK v2.14, “System Requirements Definition”, p. 558). SEBoK’s coffee-maker pair shows the change of voice. The user needs the coffee maker to stop heating once the selected temperature is reached. The coffee maker shall stop the heating function once the selected brew temperature has been achieved.`,`The change is not grammatical. SEBoK insists that generating a requirement is more than changing the subject of the need statement. It is an analysis of what the system must do to achieve what is needed, using functional, interface, data-flow and performance analysis or a needs-to-requirements transformation matrix. One need may therefore produce several requirements, including measurable performance criteria (SEBoK v2.14, “System Requirements Definition”, p. 558–559). SEBoK quotes the INCOSE Needs and Requirements Manual definition. A requirement statement is the result of a formal transformation of one or more needs or parent requirements into an agreed obligation for an entity to perform a function or possess a quality, within specified constraints and with acceptable risk (SEBoK v2.14, “System Requirements Definition”, p. 558). Each part of that definition does work. “Transformation” implies a parent to trace to. “Agreed” implies stakeholders. “Obligation for an entity” implies a named subject and a binding verb. “Within constraints with acceptable risk” implies conditions and limits.`,`The DoD Systems Engineering Guidebook splits the same territory into two processes. Stakeholder Requirements Definition translates stakeholder capability needs into a set of technical requirements, from the acquisition perspective. The Guidebook warns that doing this incompletely leads to requirements creep, rework from misunderstood user needs, unexpected contract modifications, cost growth and schedule slip (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 141). Its activities include defining constraints and the operational environment, and analysing requirements for specificity, completeness, consistency, measurability, testability and feasibility (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 142). Requirements Analysis then decomposes end-user needs, usually stated in operational terms, into clear, achievable and verifiable requirements. It derives and allocates them down to system elements and supplies the rationale for each decomposition. The three processes are applied recursively at each level of the specification (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 141–143).`,`Course convention (applying the sources to L4). A NEED is the stakeholder’s statement from Week 3 and contains no “shall”. A stakeholder requirement (REQ-STK) is a binding obligation on the AeroLink service as a whole; it corresponds to the DoD’s stakeholder requirements. A system requirement (REQ-SYS) is an obligation on an element of the service, such as the aircraft, the charging system or the scheduling function, produced by requirements analysis and allocation. These levels are relative, not absolute. SEBoK notes that the SoI can sit at any level of an architecture, and that design-input requirements are defined iteratively and recursively as the system is decomposed (SEBoK v2.14, “System Requirements Definition”, p. 558). Allocation then creates child requirements beneath a parent (SEBoK v2.14, “System Requirements Definition”, p. 562). If AeroLink’s aircraft supplier were the developer, REQ-SYS-002 would be one of its stakeholder requirements.`],quote:{text:`Defining requirements is not only an exercise in writing it is also an exercise in engineering.`,cite:{reading:`R13`,pages:`557`}},citations:[{reading:`R13`,pages:`557–559`},{reading:`R13`,pages:`562`},{reading:`R48`,pages:`141–143`}],provenance:`mixed`},{id:`w4-wellformed`,kind:`concept`,title:`What makes a requirement well formed`,paragraphs:[`The DoD Guidebook gives a list of attributes of good requirements. A good requirement is necessary, unique, unambiguous, clear and concise, complete, consistent, technically feasible (achievable, obtainable), traceable, measurable (quantifiable), verifiable (for example testable), able to be validated, operationally effective and survivable, and singular. Using these attributes early, it says, reduces development time and raises the quality of the final system (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144). The preceding page explains why this matters. Poorly written requirements cause schedule, cost or performance problems and so increase programme risk (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 143). The course audit in Week 5 uses this list as its checklist.`,`MITRE’s list overlaps but explains several items in more operational terms (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 329–330). Traceable: every requirement traces to a source such as a system-level requirement, which in turn traces to an operational need and to an authoritative person or document, and every requirement carries a unique identifier. Unambiguous: test the wording from the perspective of different stakeholders to see whether it can be read in more than one way. Specific and singular: each requirement is one atomic thought. Testable: specific, unambiguous and quantitative whenever possible, with vague, general statements avoided. Consistent: no requirement conflicts with another, which can only be checked across the set. Design-free: a requirement reflects “what” the system shall accomplish, and the design reflects “how”. Uses “shall”: in a specification “shall” marks a binding provision, “should” and “may” mark non-binding ones, and “will” declares purpose or future tense.`,`Some of these characteristics belong to a single statement: singular, unambiguous, measurable, verifiable, design-free. Others belong only to the set: complete, consistent, unique. That split is the instructor’s; it is consistent with SEBoK, which asks whether individual requirements and sets of requirements have the characteristics the organisation defines (SEBoK v2.14, “System Requirements Definition”, p. 566), but SEBoK does not assign the characteristics to either. This has a practical consequence for this week’s tools. A text heuristic can count the word “shall” or find “quickly”. It cannot decide whether a requirement is necessary, or whether two requirements conflict. One further subtlety: MITRE also observes that selective use of “shall”, with “should” to show preference, can help where needs will evolve, and that exhaustive use of “shall” can be constricting and costly (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 367). The course rule for L4 is one “shall” per binding requirement. Record preferences and goals separately, and label them as such.`],citations:[{reading:`R48`,pages:`143–144`},{reading:`R54`,pages:`329–330`},{reading:`R13`,pages:`566`},{reading:`R55`,pages:`367`}],provenance:`mixed`},{id:`w4-attributes`,kind:`concept`,title:`Rationale, parent and verification method`,paragraphs:[`SEBoK recommends recording attributes with each requirement: rationale, trace to source or parent, system verification success criteria, owner, category, status, criticality and priority (SEBoK v2.14, “System Requirements Definition”, p. 559). The rationale says why the requirement is needed, which assumptions were made, where its numbers came from and which design studies support it. That information is what later decomposition needs, and it lets anyone find the source of a value. Writing the verification success criterion helps ensure the requirement is well formed and verifiable, and it feeds the verification plan (SEBoK v2.14, “System Requirements Definition”, p. 559). SEBoK calls early planning of verification a best practice. Defining the success criteria, strategy and method when the requirement is written helps ensure that the statement is worded properly and is within the scope of the project plans. It also shows that the requirement has the characteristic “verifiable” (SEBoK v2.14, “System Requirements Definition”, p. 566).`,`The verification method is one of four. The DoD Guidebook defines them as follows (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150). Demonstration is operating the system with visual observation as the primary means of verification; it is used when quantitative assurance is not required. Examination, which the course calls inspection, is the visual inspection of equipment and the evaluation of drawings and design data, used for characteristics such as physical properties, materials, marking and workmanship. Analysis uses recognised analytic techniques, including computer models, to interpret or explain behaviour or performance. Test is an activity under fully controlled and traceable conditions whose data are used to evaluate quantitative characteristics. MITRE’s requirements article states that “all requirements must be testable to demonstrate that the end product satisfies the requirements”, and explains testable as specific, unambiguous and quantitative whenever possible (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 329). Read with the method definitions, “testable” there means verifiable by some objective means; it does not mean that the Test method must be used. MITRE’s checklist adds two rules. Every requirement must have a verification method identified. If a requirement cannot easily be verified by direct inspection, measurement or a one-time demonstration, add an expanded test-criteria description: the number of trials, the statistical criteria and the test conditions (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370). “Every requirement needs a test” is therefore wrong (the instructor’s reading of the two sources together). Every requirement needs a method that can produce the evidence it requires, and must be worded so that some method can. This block gives everything the quiz needs about the four methods; OUSD(R&E) Systems Engineering Guidebook, “Verification Process” itself is optional reading.`,`The parent is the other half of traceability. MITRE describes tracing as two-way. You cross-reference the source requirement that a system-level requirement is based on, and you reverse-reference which system requirements implement each source requirement. Tracing this way ensures that every requirement has a user basis and that every user requirement is carried into development. MITRE also advises recording the assumptions, constraints and analyses behind derived requirements (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 371). Finally, SEBoK separates two kinds of check on the requirements themselves. Requirement verification asks whether the requirements are well formed. Requirement validation asks whether they are the right requirements, that is, whether they communicate the intent of their parent needs clearly, correctly and achievably. Neither is the same as verifying or validating the built system (SEBoK v2.14, “System Requirements Definition”, p. 566).`],citations:[{reading:`R13`,pages:`559`},{reading:`R13`,pages:`566`},{reading:`R49`,pages:`149–150`},{reading:`R54`,pages:`329`},{reading:`R55`,pages:`370–371`}],provenance:`mixed`},{id:`w4-types`,kind:`concept`,title:`Requirement types, categories and interface requirements`,paragraphs:[`The course classifies requirements into four types, adapted from MITRE’s system-level checklist. Each system requirement should describe something relevant: a function the system must perform, the performance a function must provide, a constraint on the design, or a reference such as to an interface definition (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368). MITRE’s fourth item is a reference, not a type; the course turns it into an interface type. In practice: functional means what the entity must do; performance means how well, how much or how fast; interface means an interaction across a boundary with another system; constraint means a limit imposed on every acceptable solution, often from outside the project. RB-3.5 asks for a set that is balanced across the four types.`,`SEBoK offers a second, complementary scheme, taken from the INCOSE Needs and Requirements Manual (SEBoK v2.14, “System Requirements Definition”, p. 560, Table 1). Function/Performance covers the primary functions and how well they are performed. Fit/Operational covers enabling functions and interactions with the macro system, including human–system interaction, the induced and natural environments, safety, security, power, maintenance and disposal. Form covers physical characteristics. Quality covers the “-ilities”, such as reliability, availability and maintainability. Compliance covers conformance with standards and regulations. SEBoK says that organisations categorise differently, but that every category topic must be addressed for a set to be complete. The two schemes answer different questions. The course type tells you what kind of obligation a requirement is and so what kind of verification evidence it needs. The SEBoK category tells you whether the set has a gap. A requirement such as fleet availability of at least 90 % is a performance requirement in the course scheme and a Quality requirement in SEBoK’s.`,`SEBoK calls an interface requirement a specific form of functional requirement, one that deals with an interaction of a system across an interface boundary with another system. It describes writing one as a three-step process: identify the interface boundaries and the interactions across them; define what crosses each boundary and the media involved; then write the requirement, often by reference to an interface control document (SEBoK v2.14, “System Requirements Definition”, p. 563). MITRE asks for special attention to interface requirements and warns about hidden external interfaces. These arise when internal subsystems communicate through a medium that is not part of the system, such as radio or an external network (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 331; The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 369). Type can also change with level. For the AeroLink service the 65 dBA limit is a constraint imposed by the city agreement. Allocated to the aircraft, the noise source, the same number becomes a performance requirement on that element. SEBoK calls this kind of allocation budgeting: a system-level value is divided among lower-level elements, and the budgeted requirements then depend on each other, so a change to one forces a change to another (SEBoK v2.14, “System Requirements Definition”, p. 562).`],citations:[{reading:`R55`,pages:`368–369`},{reading:`R13`,pages:`560`},{reading:`R13`,pages:`562–563`},{reading:`R54`,pages:`331`}],provenance:`mixed`},{id:`w4-worked-chain`,kind:`worked-example`,title:`Worked example (a): two AeroLink chains, from need to system requirement`,paragraphs:[`Chain 1, charging. NEED-004 (vertiport operators, STK-005) says that arriving aircraft must be ready to depart again quickly enough that pad turnaround does not become the throughput limit. That is a need. It has no “shall”, no number and no subject other than the operators’ expectation. The analysis step asks what “quickly enough” means. A pad’s departures per hour are set by how long an aircraft occupies it. The Data Sheet gives 20 min to charge to the dispatch threshold. Rotor stop, the safety check, and connecting and disconnecting the charger add 5 min, while deplaning and boarding overlap the charge (FICTIONAL values). The result is REQ-STK-005, a stakeholder requirement on the service: return an arriving aircraft to dispatch-ready status within 25 min of its arrival on the pad. It is a performance requirement, verified by test.`,`The turnaround is then allocated. Only the charging system can deliver the 20 min share, and it must do so from the worst planned arrival state, which is the 20 % energy reserve that every flight plan protects (REQ-SYS-003). “Planned” matters: the reserve exists to be spent on a hold or a diversion (SCN-002 A1, SCN-005 A1), so a diverted aircraft can land below 20 %, outside REQ-SYS-001. The reference leaves that case to an extended turnaround that no requirement yet states — a gap worth a graduate argument. This gives REQ-SYS-001: the charging system shall charge an aircraft from any landing state of charge at or above the 20 % reserve to the dispatch threshold within 20 min. This is budgeting in SEBoK’s sense (SEBoK v2.14, “System Requirements Definition”, p. 562): 25 min = 20 min charge + 5 min handling. The dependency is real. If a new safety check made handling 7 min (a FICTIONAL what-if), either the charge budget would fall to 18 min or REQ-STK-005 would have to be renegotiated with the vertiport operators. The rationale records the arithmetic so that the next engineer can redo it.`,`Chain 2, waiting. NEED-001 (passengers, STK-001) asks for a short and predictable wait to board. REQ-STK-001 makes “short and predictable” measurable. At least 90 % of passengers in each calendar month shall board within 15 min of confirming their ride. The 15 min comes from assumption A-001 (attraction to the service halves at a 15 min wait), and the 90th percentile protects the passengers most likely to leave the service, not just the average one. Its method is analysis, not test. A monthly percentile over live operations cannot be produced under fully controlled conditions before service begins, so it is estimated with models and confirmed from operational data (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150). REQ-SYS-005 then allocates one slice of the 15 min budget to the scheduling function: assign a dispatch-ready aircraft to at least 99 % of confirmed ride requests within 60 s of confirmation. That is 6.7 % of the budget, so the rest of the wait is set by aircraft and charger availability, which other requirements address. Its criterion (≤ 60 s for at least 99 % of at least 200 requests in a replayed peak-hour profile) is quantitative, so the method is test. An earlier draft said “to each confirmed ride request” while its criterion accepted 99 %: a scheduler that missed 1 % would have passed verification while violating the statement — exactly the later disagreement MITRE’s expanded test criteria exist to prevent (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370). Statement and criterion must say the same thing; check the pair, not each half.`],table:{caption:`The two chains in the reference baseline (src/model/reference/week04.ts; all values FICTIONAL)`,header:[`ID`,`Level`,`Statement (abridged)`,`Type`,`Parent`,`Method`,`Rationale (abridged)`],rows:[[`NEED-004`,`Need`,`Operators need arriving aircraft ready to depart quickly enough that turnaround is not the throughput limit`,`—`,`STK-005, CON-006`,`—`,`—`],[`REQ-STK-005`,`Stakeholder`,`The AeroLink service shall return an arriving aircraft to dispatch-ready status within 25 min of pad arrival`,`Performance`,`NEED-004, CAP-003`,`Test`,`20 min charge + 5 min handling; turnaround sets pad throughput`],[`REQ-SYS-001`,`System`,`The charging system shall charge from ≥ 20 % reserve to the dispatch threshold within 20 min`,`Performance`,`REQ-STK-005`,`Test`,`Worst planned arrival state is the 20 % reserve; keeps the 25 min turnaround achievable (diverted arrivals below 20 % are not covered)`],[`NEED-001`,`Need`,`Passengers need a short and predictable wait to board after confirming a ride`,`—`,`STK-001, CON-001`,`—`,`—`],[`REQ-STK-001`,`Stakeholder`,`The AeroLink service shall board ≥ 90 % of passengers each month within 15 min of confirmation`,`Performance`,`NEED-001, CAP-001`,`Analysis`,`Attraction halves at 15 min (A-001); the 90th percentile protects likely churners`],[`REQ-SYS-005`,`System`,`The scheduling function shall assign a dispatch-ready aircraft to ≥ 99 % of confirmed requests within 60 s of confirmation`,`Performance`,`REQ-STK-001, CAP-002`,`Test`,`Assignment must be a negligible slice (6.7 %) of the 15 min budget`]]},citations:[{reading:`R13`,pages:`558–559`},{reading:`R13`,pages:`562`},{reading:`R49`,pages:`149–150`},{reading:`R55`,pages:`370`}],provenance:`mixed`},{id:`w4-worked-critique`,kind:`worked-example`,title:`Worked example (b): critique and rewrite six flawed requirements`,paragraphs:[`Each draft below was written by a well-meaning team. Treat it as a reviewer would. Name each defect and the quality characteristic it violates, cite the page, and then rewrite. The rewrites are the reference requirements. Two lessons come out of the set. First, most defects are of a few kinds: more than one obligation, words that cannot be measured, a solution stated as a requirement, a negative, a single-point value, and an unknown hidden behind an adjective. Second, the quality lab’s heuristics flag the word-level defects in all six drafts: the extra “shall”, “should”, “quickly”, “maximize”, “shall not”, “using” and the single-point value. They miss the ones that need engineering judgement: “safe” must be decomposed into hazards (F1); the subject names an implementation (F2); a number can dictate design rather than performance (F3); and a time needs a start event (F6). That is why requirement verification is a review activity and not a script (SEBoK v2.14, “System Requirements Definition”, p. 566).`,`Read F3 carefully, because it is the most instructive. “The charging system shall charge each aircraft using two 350 kW DC fast chargers per hub pad” (a FICTIONAL rating) contains a number and a unit, so it looks measurable. But the number constrains the design: it fixes the charger type, rating and count. It never says what the stakeholder needs, which is a turnaround short enough for the pad. MITRE’s advice is to give designers what they must know and to leave as much white space as possible for them to explore options (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 367). A charger specification may well appear later, as a derived requirement that comes from a solution decision. The DoD Guidebook expects such derived requirements to be identified and kept traceable (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 146). It does not belong at system level, before any trade study.`],table:{caption:`Critique and rewrite (instructor key). F-numbers match the examples loadable in the quality lab.`,header:[`#`,`Flawed draft`,`Findings (characteristic, source)`,`Rewrite (reference)`],rows:s.map(e=>[e.id,e.flawed,e.findings.map(e=>`${e.flaw} [${e.characteristic}; ${e.cite.reading} p.${e.cite.pages}]`).join(` `)+(e.reviewOnly?` Reviewer-only finding: ${e.reviewOnly}`:``),`${e.rewriteId}: ${e.rewrite}`])},citations:[{reading:`R48`,pages:`144`},{reading:`R54`,pages:`329–330`},{reading:`R55`,pages:`367`},{reading:`R55`,pages:`370`},{reading:`R13`,pages:`565–566`},{reading:`R48`,pages:`146`},{reading:`R49`,pages:`149`}],provenance:`mixed`},{id:`w4-worked-tbd`,kind:`worked-example`,title:`Worked example (c): handling a TBD through an AROU item`,paragraphs:[`The operations system must hold departures when the weather is beyond the aircraft limits. In the fictional case the OEM has not yet published the crosswind, gust and visibility limits. The team has three options. It could invent a number, which is unfounded and will silently become the baseline. It could write “unsafe weather”, which is unverifiable (F5). Or it could record the unknown. SEBoK describes the third option (SEBoK v2.14, “System Requirements Definition”, p. 565). When a value is unknown, put a “To Be Determined” (TBD) placeholder in the statement. When a value is known but confidence in it is low, for example because feasibility has not been assessed, mark it “To Be Resolved” (TBR). Together these are TBXs. Tracking them shows how mature the requirement set is. TBXs can become risks if they are not closed before significant design work. TBX management means identifying each TBX, defining the work needed to close it, naming an owner, and working systematically until the placeholders can be removed.`,`The reference requirement is REQ-SYS-004: the operations system shall place a dispatch hold on any vertiport whose forecast wind or gust within the next 30 min exceeds the aircraft limit (TBD-01). The TBD is not left floating. Unknown U-001, recorded in the Week 2 AROU v0, owns it. Its owner is the Director of Flight Operations, its resolution is to obtain the limits from the OEM flight-manual draft, and its need-by date is the CP2 requirements baseline in Week 6. U-001 is linked by “affects” to both REQ-STK-003 and REQ-SYS-004, so when the value arrives the trace shows every statement that must change. The requirement still has a full set of attributes: the type is functional; the method is demonstration (inject a forecast above the limit and observe the hold); the criterion is “hold placed for every injected forecast above TBD-01”. A TBD leaves a parameter open. It does not leave the verification undefined.`,`Week 4 adds a second case. The utility has not confirmed the grid connection capacity at each vertiport, so REQ-STK-010 and REQ-SYS-010 carry TBD-02. A new Unknown, U-002, is created with them. Its owner is the Vertiport Infrastructure Manager, its resolution is a signed connection agreement for each vertiport, and it is needed before the Week 7 trade study. The quality lab does the same thing atomically: a requirement containing a TBD or TBR cannot be recorded until every token is owned — by the existing Unknown that records it, by an Assumption only for a TBR (a doubted value), or by a new Unknown created with an owner, the resolution work and a need-by date. Two FICTIONAL indicators show the maturity of the reference set. Four of its 20 requirements carry a TBX (20 %), and each TBX has an owner and a need-by date. A graduate-level refinement follows from SEBoK’s definitions. If your team doubted that the 20 min charge of REQ-SYS-001 is feasible, the right marking would be “20 min (TBR)”, with an assumption recording the doubt. Deleting the number would be wrong, because a TBR keeps the best current value visible while flagging that it may change.`],table:{caption:`TBX register in the reference baseline (values FICTIONAL)`,header:[`TBX`,`Requirements`,`AROU item`,`Owner`,`Resolution`,`Need by`],rows:[[`TBD-01`,`REQ-STK-003, REQ-SYS-004`,`U-001 Aircraft weather limits not yet published`,`Director of Flight Operations`,`Limits from the OEM flight-manual draft`,`CP2 requirements baseline (Week 6)`],[`TBD-02`,`REQ-STK-010, REQ-SYS-010`,`U-002 Vertiport grid connection limit not agreed`,`Vertiport Infrastructure Manager`,`Connection agreement with the utility for each vertiport`,`Before the Week 7 trade study`]]},citations:[{reading:`R13`,pages:`565`}],provenance:`mixed`},{id:`w4-advanced`,kind:`advanced`,title:`Advanced analysis: the right level of detail, negatives, and arguments about words`,paragraphs:[`The hardest judgement in requirements work is not grammar but level of detail. MITRE puts it this way: give enough detail to implement the right system, but not so much that designers are restricted unnecessarily. With too little detail the designer has to guess; MITRE’s example is a car specification that forgets cargo space and is met by a car with too little of it. With too much detail the design is artificially constrained, often because someone has seen a feature they like and wants it written in (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 371–372). The costs are concrete. Every system requirement has to be documented, allocated, tracked and formally tested, contractors will bid that work, and detailed requirements become a permanent part of the top-level requirements for all future upgrades until someone explicitly changes them (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 372). Applied to AeroLink: “two 350 kW chargers per pad” (F3) would bind every future charging upgrade, while “charge to the dispatch threshold within 20 min” leaves the charger technology to the Week 7 trade study.`,`User language hides engineering work. MITRE’s radar example, “detect airborne objects out to a range of 100 miles”, looks complete. A radar engineer immediately asks: detect what, and how well? No sensor can guarantee detection 100 % of the time, so the systems engineer must derive further requirements or verification criteria: the smallest object size, and the probability of detecting a given object within range (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368). REQ-STK-001 shows the same move. “Board within 15 min” becomes a statistic (the 90th percentile), a population (passengers each calendar month) and a starting event (ride confirmation). Without all three a verifier cannot say whether the requirement passed.`,`Two cautions concern the reference set itself. First, MITRE advises avoiding “shall not”, because a negative is very difficult to prove (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370). Yet REQ-STK-003 says that the service “shall not dispatch a flight” beyond the weather limits. The instructor’s position is that at stakeholder level the regulator’s concern really is a prohibition. It is verified only over a finite, stated set of demonstrated cases, and its child, REQ-SYS-004, restates it positively as a hold that can be observed. Graduate students should decide whether they agree and rewrite REQ-STK-003 if they do not. Second, MITRE asks that single-point values be replaced by ranges (“minimum of”, “within”, “up to and including”), and that objective or goal values be clearly separated from threshold values (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370). For example, “at least 300 trips per day, with a goal of 360” keeps the binding threshold and makes the aspiration visible without making it binding (the 360 is FICTIONAL).`,`Finally, expect arguments. MITRE lists the recurring disputes: what a word means, whether a requirement should be included, whether it specifies too much or too little, and whether it directs design. It traces their sources to helpful experience, fear of how someone else will interpret the requirement, a preferred competing technical approach, or insistence on a particular feature. Resolving them takes negotiation, technical expertise and an understanding of the root cause of the other person’s concern; clear and consistent wording is the starting point (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 372–373). This is why each L4 requirement has an owner and a rationale. In the Week 5 audit the owner must defend the requirement with reasons, not with taste.`],citations:[{reading:`R55`,pages:`368`},{reading:`R55`,pages:`370–373`}],provenance:`mixed`},{id:`w4-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`In US defence acquisition the authoritative sources for stakeholder requirements are documents produced through the Joint Capabilities Integration and Development System, such as the initial capabilities document and the capability development document (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 142). The requirements that come out of requirements analysis become contracting language and the system performance specification, and they are revisited at technical reviews and audits throughout the life cycle (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 142). MITRE notes that in a contract “shall” is legally enforceable, whereas “will”, “may”, “should” and “must” can show intent but are not binding (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 369). For a team writing requirements for an operator like AeroLink, that is a reminder that every “shall” is a promise someone will be held to. It also settles the word “must” across the two weeks: in Week 3 it was kept out of need statements because it signals an intent to oblige; here it is kept out of requirements because it does not bind. Needs use “need”, binding requirements use “shall”, and “must” belongs in neither.`,`Requirements are also increasingly held as model elements rather than paragraphs. SEBoK notes that models help with completeness (functions, inputs, sources, outputs and destinations), with communication, with capturing dependencies on needs, architecture and tests, and with quantitative analysis and simulation. In MBSE a requirement is a model element that carries a well-formed textual statement and can be shown in a diagram or a table (SEBoK v2.14, “System Requirements Definition”, p. 564). SEBoK also lists the artefacts of this process: well-formed requirements, a requirement tree, traceability, defined interactions across boundaries, performance budgets and initial verification plans (SEBoK v2.14, “System Requirements Definition”, p. 567). The L4 set produces each of these for AeroLink. In Week 10 the same requirements become SysML v2 requirement elements whose short names are their IDs (course plan, lab §C.2), so careful IDs, parents and attributes now save rework then.`],citations:[{reading:`R48`,pages:`142`},{reading:`R55`,pages:`369`},{reading:`R13`,pages:`564`},{reading:`R13`,pages:`567`}],provenance:`mixed`},{id:`w4-lab`,kind:`lab`,title:`Lab L4: requirements writing studio`,paragraphs:[`In teams, starting from your CP1 needs and capabilities, write 15–20 requirements at two levels: stakeholder requirements derived from NEED and CAP items, and system requirements derived from them. Give each one rationale, a verification method, a parent and a type. Use the quality lab below to draft and record each requirement in your workspace, with its owner and provenance. The lab refuses a requirement with a failing check, but passing every check is necessary, not sufficient: a heuristic cannot judge necessity, feasibility or correctness, so each requirement still needs a team review. Then audit the whole set with the trace checker and draw an RB-3 sample to rehearse the grader’s audit. Every TBD or TBR must be tied to an AROU item with an owner.`],citations:[],provenance:`instructor-authored`},{id:`w4-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: the L4 requirements table (exported from the workspace) is scored formatively now with RB-3.1–3.5, on a random sample of 10, and summatively at CP2 in Week 6. Individual: readiness quiz Q4, review-notebook entry 4 with a time log and AI statement, and the graduate checklist memo applying The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368–370 to the team set.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w4-act-quality`,title:`Requirements quality lab`,component:`w04-quality-lab`,purpose:`Draft or repair a requirement, see which quality characteristics its wording and attributes satisfy (each check cites its source), and record it, with its parent links and any TBX Unknown, in your AeroLink workspace.`,instructions:[`Load F1–F6 one at a time. Predict which checks will fail before you look, then repair each example until no check fails.`,`For each advisory, decide whether it applies, and write the reason in your team’s notes.`,`Write your own L4 requirements here, each with a success criterion (L4 requires one for every requirement), its owner’s initials and its provenance. A requirement with a failing check cannot be recorded; one with a TBD/TBR must name the AROU item that owns it, or create a new Unknown with an owner, resolution work and a need-by date.`,`Remember the banner: the heuristics test words and attributes, not engineering truth. Every requirement still needs a team review.`],objectives:[`B4.2`],inBlock:`w4-worked-critique`},{id:`w4-act-classify`,title:`Requirement level and type classifier`,component:`w04-type-classifier`,purpose:`Classify twelve AeroLink statements by level (need, stakeholder requirement, system requirement) and by type, then compare with the key and its reasoning, including SEBoK’s category for each.`,instructions:[`Decide level and type for every statement before you check.`,`Where your answer is marked “defensible”, write the argument for it in one sentence.`,`Note the pairs that show type changing with level (REQ-STK-002 / REQ-SYS-002).`],objectives:[`B4.1`,`B4.3`],inBlock:`w4-types`},{id:`w4-act-trace`,title:`Parent-trace and set checker with an RB-3 rehearsal`,component:`w04-trace-checker`,purpose:`Audit your recorded set for orphans, inverted traces, missing types, duplicates and failing checks, and rehearse the grader’s RB-3 audit on a random sample of 10.`,instructions:[`Run the checker on the instructor reference first, to calibrate: all 20 should pass.`,`Switch to your workspace. Fix every orphan and every failing check; explain each remaining advisory.`,`Draw a sample with a seed of your choice and record the proxy levels in your lab record. The grader draws a different sample.`],objectives:[`B4.2`,`B4.3`],inBlock:`w4-lab`}],lab:{id:`L4`,title:`Requirements writing studio`,setting:`team`,durationMinutes:75,objectives:[`B4.1`,`B4.2`,`B4.3`],inputs:[`CP1 record: NEED, CAP, MGO and SCN items with their STK/CON parents (Week 3)`,`AROU v1 from CP1 (U-, A- items available for TBX links)`,`AeroLink Data Sheet (FICTIONAL values)`,`Requirements quality lab, classifier and trace checker (this week)`],steps:[{title:`Stakeholder requirements from needs`,detail:`For each NEED, decide what the AeroLink service must do or be. Analyse; do not just change the subject (SEBoK v2.14, “System Requirements Definition”, p. 558). Write REQ-STK items, usually 6–10, each derived from at least one NEED or CAP.`},{title:`System requirements`,detail:`Allocate each REQ-STK to the elements that implement it, and write REQ-SYS items that derive from it. Where a value is divided between elements, write the budget arithmetic in the rationale (SEBoK v2.14, “System Requirements Definition”, p. 562). Total set: 15–20 REQ.`},{title:`Rationale, method, criterion and parent`,detail:`For each requirement give a rationale that says why and where the number comes from (SEBoK v2.14, “System Requirements Definition”, p. 559), a verification method that fits the evidence (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150), a success criterion that agrees with the statement, its parent and its owner. Record each requirement through the quality lab with the owner’s initials and provenance (AI-suggested-reviewed where it applies); resolve every failing check and decide on every advisory.`},{title:`TBX handling`,detail:`Any value you do not know is TBD; any value you doubt is TBR (SEBoK v2.14, “System Requirements Definition”, p. 565). Link each one to an existing U-/A- item, or create a new Unknown with an owner, the resolution work and a need-by date.`},{title:`Type classification and balance`,detail:`Type every requirement functional, performance, interface or constraint (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368). Check the set against SEBoK’s categories (SEBoK v2.14, “System Requirements Definition”, p. 560) for gaps, especially external interfaces and externally imposed constraints.`},{title:`Self-audit and record`,detail:`Run the trace checker until there are no orphans, no failing checks and all four types are present. Draw an RB-3 sample and record the proxy levels. Export the requirements table and add it to the L4 record with your advisory decisions.`}],artefacts:[{idPrefix:`REQ-STK`,description:`Stakeholder requirements on the AeroLink service, each derived from NEED/CAP`,minimum:`≥ 6, each with type, rationale, method, criterion and parent`},{idPrefix:`REQ-SYS`,description:`System requirements on AeroLink elements, each derived from a REQ-STK (or a CAP, with justification)`,minimum:`≥ 8; set total 15–20 REQ`},{idPrefix:`U / A`,description:`AROU items that own each TBD/TBR`,minimum:`One per distinct TBX, with owner and need-by date`}],continuity:`The L4 set is the input to the Week 5 peer audit (RB-3.6 audit responses, OUSD(R&E) Systems Engineering Guidebook, p. 144 checklist) and to the MOE → MOP → TPM hierarchy, whose MOPs must each link to a REQ. It is baselined at CP2 (Week 6, SRR-style review). It becomes SysML v2 requirement elements with short-name IDs in Week 10, with satisfy links from design elements. It is verified through VER items in Week 12. TBX items are tracked in the AROU register until closed (U-001 by CP2, U-002 before the Week 7 trade study).`,tools:[{label:`AeroLink model workspace (export, import, reference baseline)`,to:`/workspace/model`},{label:`Air Taxi Enterprise workspace (case brief and Data Sheet)`,to:`/workspace/aerolink`}]},assignment:{id:`W4-A`,title:`L4 requirements set (team) and graduate checklist memo (individual)`,mode:`team`,due:`Before the first session of Week 5`,weight:`L4 set (team): formative RB-3 now, summative at CP2 (10 %, RB-3 40 %) · graduate memo (individual): review-notebook entry 4 (RB-16, 5 %), always read, formative on RB-3.5`,instructions:[`Team: submit the L4 requirements table (15–20 REQ, exported from the workspace) with the trace-checker summary, your RB-3 sample rehearsal and a list of advisory decisions (accepted or rejected, with a reason).`,`The grader draws 10 requirements at random and scores RB-3.1–3.4 as the percentage of the sample that meets each condition; RB-3.5 is judged on the whole set. This week the score is formative.`,`Individual (graduate): apply six items of the MITRE system-level requirements checklist (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368–370) to your team’s set — the four below plus two of your choice: traceable to user requirements; all external interfaces included; performance statements quantifiable and verifiable (including “shall not” and single-point values); verification approaches complete and appropriate. For each item give a verdict (met / partly / not met), the requirement IDs that are evidence, and one proposed change. Choose at least one item where you disagree with your team, and argue it. The memo is review-notebook entry 4 and is always read.`,`Individual: log your hours for the week in the review notebook (workload pilot) with an AI usage statement.`],template:[{heading:`1. Requirements table`,guidance:`ID, level, statement, type, method, success criterion, rationale, parent(s), owner, TBX and AROU link. One “shall” per requirement; 15–20 rows.`},{heading:`2. Two traced chains`,guidance:`Two NEED → REQ-STK → REQ-SYS chains written out with the analysis between levels, including any budget arithmetic (as in worked example (a)).`},{heading:`3. TBX register`,guidance:`Every TBD/TBR: requirement IDs, the AROU item, owner, resolution work and need-by date (SEBoK v2.14, “System Requirements Definition”, p. 565).`},{heading:`4. Set audit`,guidance:`Trace-checker summary (orphans, types, duplicates), the RB-3 sample rehearsal with its seed, and the advisory decisions with reasons.`},{heading:`5. Graduate checklist memo (individual)`,guidance:`One row for each of the six The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements” Table 1 items you apply (p.368–370; the four named in the instructions plus two of your choice): verdict, evidence IDs, proposed change. Then one paragraph on the item you disagree with your team about, argued from the checklist text with its page.`},{heading:`6. AI usage statement`,guidance:`Tool, purpose, prompts, what you accepted or rejected and why (RB-12). Requirements suggested by AI are recorded in the quality lab with the provenance AI-suggested-reviewed and the initials of the team member who owns them.`}],rubrics:[`RB-3`,`RB-16`,`RB-12`],rubricScope:`L4 set (team): RB-3.1–3.5, formative, on a random sample of 10 (RB-3.6 begins with the Week 5 audit responses). Graduate memo (individual): a required review-notebook entry under RB-16, always read and not sampled (RB-16 graduate-task note); scored formatively on RB-3.5 (set quality) as the memo applies it — 4: six checklist items each with a correct verdict, evidence IDs and a workable change, and the disagreement argued from the checklist text with its page; 3: all items covered but evidence or changes thin; 2: items listed without evidence IDs; 1: missing. The set of graduate tasks informs RB-16.1. AI statement: RB-12.1–12.3, including RB-12.3 for every AI-suggested requirement (provenance AI-suggested-reviewed in the quality lab).`,aiUse:`AI tools may be used to critique draft requirements and to suggest missing ones. Every AI suggestion that is kept is tagged AI-suggested-reviewed, owned by a named member, and passed through the quality lab and a team review. AI must not invent AeroLink values: any number must come from the Data Sheet, the reference baseline or a labelled assumption.`,objectives:[`B4.1`,`B4.2`,`B4.3`]},quiz:[{id:`q4-1`,bloom:`Understand`,objective:`B4.1`,prompt:`According to SEBoK, what distinguishes a need from a requirement?`,options:[{id:`a`,text:`A need expresses the stakeholder’s external, black-box view of what they need the SoI to do; a requirement expresses the developer’s internal, white-box view of what the SoI must do to meet it`,correct:!0,explanation:`Correct. This is SEBoK’s contrast (SEBoK v2.14, “System Requirements Definition”, p. 558), illustrated by the coffee-maker pair.`},{id:`b`,text:`A need is informal and a requirement is the same statement rewritten with “shall”`,correct:!1,explanation:`SEBoK says that generating a requirement is more than changing the subject of the need. It is an analysis of what the system must do.`},{id:`c`,text:`Needs are written by engineers and requirements by stakeholders`,correct:!1,explanation:`It is the other way round. Needs carry the stakeholder perspective, and requirements carry the technical, developer perspective.`},{id:`d`,text:`Needs are always quantitative and requirements are always qualitative`,correct:!1,explanation:`Requirements carry the measurable criteria. A need such as “a short and predictable wait” is legitimately qualitative.`}],cite:{reading:`R13`,pages:`558`}},{id:`q4-2`,bloom:`Apply`,objective:`B4.1`,prompt:`A team converts NEED-004 (“Vertiport operators need arriving aircraft to be ready to depart again quickly enough that pad turnaround does not become the throughput limit”) into: “The AeroLink service shall make arriving aircraft ready to depart again quickly enough that turnaround does not limit throughput.” What is the main problem?`,options:[{id:`a`,text:`Nothing: it has a subject, one “shall” and a parent`,correct:!1,explanation:`Form is not enough. The statement has no criterion a verifier could check.`},{id:`b`,text:`Only the subject has changed. The analysis that turns “quickly enough” into a measurable obligation (turnaround ≤ 25 min from pad arrival, from charge time plus handling) is missing`,correct:!0,explanation:`Correct. SEBoK says a requirement is more than the need with a new subject; analysis must produce measurable performance criteria (SEBoK v2.14, “System Requirements Definition”, p. 558–559).`},{id:`c`,text:`Stakeholder requirements must never mention the AeroLink service`,correct:!1,explanation:`At stakeholder level the subject is the service as a whole; that part is right.`},{id:`d`,text:`It should be written as a need, because operators are stakeholders`,correct:!1,explanation:`The need already exists. The task is to transform it into a binding obligation.`}],cite:{reading:`R13`,pages:`558–559`}},{id:`q4-3`,bloom:`Apply`,objective:`B4.1`,prompt:`REQ-STK-005 gives a 25 min hub turnaround: 20 min charge (REQ-SYS-001) + 5 min handling. A new safety check raises handling to 8 min (FICTIONAL). Which consequence follows from SEBoK’s account of allocation and budgeting?`,options:[{id:`a`,text:`None: REQ-SYS-001 is a separate requirement and is unaffected`,correct:!1,explanation:`Budgeted requirements depend on each other. A change in one forces a change in another (SEBoK v2.14, “System Requirements Definition”, p. 562).`},{id:`b`,text:`Either the charge budget must fall to 17 min (a new REQ-SYS-001 value, with feasibility to be checked) or REQ-STK-005 must be renegotiated with the vertiport operators`,correct:!0,explanation:`Correct. The 25 min is a system-level budget divided among elements; 25 − 8 = 17 min is left for charging.`},{id:`c`,text:`The handling time should be deleted from the rationale so the numbers still add up`,correct:!1,explanation:`The rationale records the source of the numbers precisely so that this change can be traced (SEBoK v2.14, “System Requirements Definition”, p. 559).`},{id:`d`,text:`REQ-SYS-001 becomes a stakeholder requirement`,correct:!1,explanation:`Its level does not change. It is still the charging system’s allocated share.`}],cite:{reading:`R13`,pages:`562`}},{id:`q4-4`,bloom:`Apply`,objective:`B4.2`,prompt:`Which is the best rewrite of “The booking app should respond quickly to ride requests”?`,options:[{id:`a`,text:`The booking app shall respond quickly and reliably to ride requests`,correct:!1,explanation:`“Shall” is now binding, but “quickly” and “reliably” are still vague, and the subject still names an implementation.`},{id:`b`,text:`The scheduling function shall assign a dispatch-ready aircraft to at least 99 % of confirmed ride requests within 60 s of confirmation`,correct:!0,explanation:`Correct. It is binding, singular and measurable with a start event and a stated share of requests, and it is design-free because it names the function rather than the app (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 329–330).`},{id:`c`,text:`The booking app should respond within 60 s`,correct:!1,explanation:`“Should” is non-binding in a specification (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 330), and “respond” does not say what must happen.`},{id:`d`,text:`The system shall use a cloud database so that responses are fast`,correct:!1,explanation:`This dictates a solution and keeps the vague term “fast”.`}],cite:{reading:`R54`,pages:`329–330`}},{id:`q4-5`,bloom:`Understand`,objective:`B4.2`,prompt:`“The aircraft shall be quiet and shall be safe to operate near homes.” Which characteristics from the DoD list of attributes of good requirements does it violate most directly?`,options:[{id:`a`,text:`Singular, because there are two obligations; and unambiguous and measurable, because “quiet” and “safe” have no criterion`,correct:!0,explanation:`Correct. Both defects appear in the OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144 list. The rewrite splits the statement and gives the noise obligation a value (REQ-SYS-002).`},{id:`b`,text:`Traceable only`,correct:!1,explanation:`A parent could easily be found (NEED-003). The defects are in the statement itself.`},{id:`c`,text:`Technically feasible only`,correct:!1,explanation:`Feasibility cannot even be judged until the statement says how quiet.`},{id:`d`,text:`None: safety and quietness are important to the community`,correct:!1,explanation:`Importance is not well-formedness. “Safe” is a goal that must be decomposed into specific requirements.`}],cite:{reading:`R48`,pages:`144`}},{id:`q4-6`,bloom:`Apply`,objective:`B4.2`,prompt:`REQ-STK-001 requires at least 90 % of passengers each calendar month to board within 15 min of confirmation. Which verification method fits best before service begins?`,options:[{id:`a`,text:`Test, because every performance requirement must be tested`,correct:!1,explanation:`A monthly percentile over live operations cannot be produced under fully controlled, traceable conditions before service. The method must fit the evidence (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150).`},{id:`b`,text:`Analysis: use recognised analytic techniques, such as a queueing or simulation model, to estimate the percentile, and confirm it later from operational data`,correct:!0,explanation:`Correct. Analysis interprets or explains performance with analytic techniques including computer models (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149). The reference uses analysis for REQ-STK-001.`},{id:`c`,text:`Inspection of the booking app screens`,correct:!1,explanation:`Inspection checks physical characteristics and design data, not a performance statistic.`},{id:`d`,text:`Demonstration of one ride`,correct:!1,explanation:`Demonstration is for cases where quantitative assurance is not required (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149); a single ride says nothing about a monthly percentile.`}],cite:{reading:`R49`,pages:`149–150`}},{id:`q4-7`,bloom:`Evaluate`,objective:`B4.2`,prompt:`Which rationale for REQ-SYS-005 (“The scheduling function shall assign a dispatch-ready aircraft to at least 99 % of confirmed ride requests within 60 s of confirmation”) is best?`,options:[{id:`a`,text:`The scheduling function must assign an aircraft to nearly every confirmed request within 60 s`,correct:!1,explanation:`This restates the requirement. A rationale must say why it is needed (RB-3.3; SEBoK v2.14, “System Requirements Definition”, p. 559).`},{id:`b`,text:`Passengers like fast service`,correct:!1,explanation:`Vague, and it gives no source for the 60 s.`},{id:`c`,text:`Assignment must be a negligible part (about 7 %) of the 15 min wait budget of REQ-STK-001, so that the remaining time is set by aircraft and charger availability`,correct:!0,explanation:`Correct. It explains why the requirement exists, where the number comes from and which parent budget it protects (SEBoK v2.14, “System Requirements Definition”, p. 559).`},{id:`d`,text:`Required by the customer`,correct:!1,explanation:`It names an authority but no reason, assumption or source of value.`}],cite:{reading:`R13`,pages:`559`}},{id:`q4-8`,bloom:`Apply`,objective:`B4.2`,prompt:`The aircraft weather limits needed for REQ-SYS-004 are not yet published by the OEM. What does SEBoK’s guidance on unknowns imply the team should do?`,options:[{id:`a`,text:`Use a plausible number now and correct it later`,correct:!1,explanation:`An invented value silently becomes the baseline and hides the open issue.`},{id:`b`,text:`Write “in unsafe weather” until the limits are known`,correct:!1,explanation:`“Unsafe” is unverifiable and hides the fact that a value is missing.`},{id:`c`,text:`Put a TBD in the statement and manage it: record the work needed to close it and an owner (here U-001, owned by the Director of Flight Operations, needed by CP2), and close it systematically`,correct:!0,explanation:`Correct. This is TBX management (SEBoK v2.14, “System Requirements Definition”, p. 565). The course ties every TBX to an AROU item.`},{id:`d`,text:`Mark the value TBR, because it is unknown`,correct:!1,explanation:`TBR is for a value that is known but held with low confidence. An unknown value is TBD (SEBoK v2.14, “System Requirements Definition”, p. 565).`}],cite:{reading:`R13`,pages:`565`}},{id:`q4-9`,bloom:`Apply`,objective:`B4.2`,prompt:`“The maintenance management function shall diagnose reported faults using a machine-learning engine supplied by Vendor-Y.” A teammate says it is fine because it has a subject and exactly one “shall”. Which response is best?`,options:[{id:`a`,text:`Agree: subject, one “shall” and a named supplier make it precise`,correct:!1,explanation:`Form is not enough. Precision about the means is not precision about the need; the statement fixes the design.`},{id:`b`,text:`It is not design-free. It states how (a machine-learning engine from one vendor) instead of what the stakeholder needs — for example, every reported fault classified go or no-go within a stated time — and it removes the designer’s white space before any trade study`,correct:!0,explanation:`Correct. A requirement reflects what, the design how (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 330); give designers what they must know and leave white space (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 367).`},{id:`c`,text:`Change “shall” to “should” so that it is only a preference`,correct:!1,explanation:`This keeps the solution in the requirement and makes it non-binding as well.`},{id:`d`,text:`Add “or equivalent” after “Vendor-Y”`,correct:!1,explanation:`The decision is still at the wrong level, and “equivalent” is undefined, so verification would become an argument.`}],cite:{reading:`R54`,pages:`330`}},{id:`q4-10`,bloom:`Apply`,objective:`B4.2`,prompt:`“The operations system shall send each flight intent to the ANSP 5 min before take-off.” (FICTIONAL value.) Which revision best follows MITRE’s checklist?`,options:[{id:`a`,text:`… no later than 5 min before take-off`,correct:!0,explanation:`Correct. A bound replaces the single point, so an intent sent 7 min early is compliant and one sent 3 min before is not (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370: use ranges such as “minimum of”, “maximum of”, “within”).`},{id:`b`,text:`… exactly 5 min before take-off`,correct:!1,explanation:`A single-point value invites dispute when a test result differs slightly from it (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370).`},{id:`c`,text:`… as early as possible before take-off`,correct:!1,explanation:`Unmeasurable, like “minimize” and “maximize” (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 370).`},{id:`d`,text:`… 5 min before take-off, verified by inspection`,correct:!1,explanation:`The single point remains, and inspection of drawings cannot measure when a message was sent.`}],cite:{reading:`R55`,pages:`370`}},{id:`q4-11`,bloom:`Analyse`,objective:`B4.3`,prompt:`How should this requirement be typed, and why? “The maintenance management function shall send each aircraft’s fault records to the aircraft manufacturer (EXT-004) in the format defined in the maintenance-data interface control document.”`,options:[{id:`a`,text:`Constraint, because the format is imposed from outside`,correct:!1,explanation:`The format is defined by reference to the interface definition, but the obligation is the exchange with an external system; that is what verification will check.`},{id:`b`,text:`Interface: the obligation is an exchange across the boundary with an external system, written by reference to an interface definition; SEBoK treats an interface requirement as a specific form of functional requirement`,correct:!0,explanation:`Correct. This follows SEBoK v2.14, “System Requirements Definition”, p. 563 and the reference item of The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368; the course types boundary exchanges as interface requirements to keep them visible (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 331).`},{id:`c`,text:`Performance, because the records must be complete`,correct:!1,explanation:`Nothing in the statement says how well, how much or how fast; completeness here is set by the interface definition.`},{id:`d`,text:`Not a requirement, because the manufacturer is not part of AeroLink`,correct:!1,explanation:`Interactions with external systems are exactly what interface requirements capture.`}],cite:{reading:`R13`,pages:`563`}},{id:`q4-12`,bloom:`Analyse`,objective:`B4.3`,prompt:`REQ-STK-010 (keep charging power within the connection agreed with the utility) is a constraint. A team allocates it as: “The charging system shall reduce total charger power to the curtailed level within 2 s of a curtailment signal from the utility” (FICTIONAL). How should the allocated requirement be typed?`,options:[{id:`a`,text:`Constraint, because its parent is a constraint`,correct:!1,explanation:`Type describes the obligation on the entity that carries it, not the type of its parent; allocation can change it.`},{id:`b`,text:`Performance: it obliges the charging system to respond within a time, so how fast is what verification measures; the utility’s signal may also deserve its own interface requirement`,correct:!0,explanation:`Correct. In MITRE’s terms (The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 368) the parent is a constraint on the design and the child is the performance a function must provide; the exchange with the utility is a separate interface concern.`},{id:`c`,text:`Interface only, because the utility is named`,correct:!1,explanation:`The signal does cross a boundary, but the obligation stated here is the 2 s response, not the content or format of the exchange.`},{id:`d`,text:`Functional, because reducing power is a function`,correct:!1,explanation:`The function is implied, but the statement’s obligation, and the evidence a verifier must produce, is the 2 s; a number with a bound on a function’s response is performance.`}],cite:{reading:`R55`,pages:`368`}},{id:`q4-13`,bloom:`Evaluate`,objective:`B4.3`,prompt:`A team’s L4 set has 16 requirements: 13 functional, 3 performance, no interface and no constraint requirements. Which judgement is best supported?`,options:[{id:`a`,text:`Fine: functional requirements are the most important, so a set dominated by them is complete`,correct:!1,explanation:`SEBoK says each category topic must be addressed for a set to be complete (SEBoK v2.14, “System Requirements Definition”, p. 560).`},{id:`b`,text:`The set is probably incomplete. Nothing covers interactions with the ANSP, utility or emergency services, nor externally imposed limits such as noise and grid capacity, so the team should check its context and scenarios for missing interface and constraint requirements`,correct:!0,explanation:`Correct. Imbalance is a symptom of a gap. SEBoK’s categories (Fit/Operational, Compliance) and MITRE’s focus on external interfaces (The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements”, p. 331) point to what is missing.`},{id:`c`,text:`Reclassify three functional requirements as interface requirements to balance the counts`,correct:!1,explanation:`Relabelling hides the gap rather than closing it.`},{id:`d`,text:`Delete functional requirements until the types are equal`,correct:!1,explanation:`Balance is a check on coverage, not a quota.`}],cite:{reading:`R13`,pages:`560`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min)`,hours:2.5},{activity:`Online direct instruction and the three interactive activities (the F1–F6 practice is done in Session 1)`,hours:.7},{activity:`Readings SEBoK v2.14, “System Requirements Definition”, OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, The MITRE Systems Engineering Guide, “Analyzing and Defining Requirements” (≈ 23 pp at ≈ 15 pp/h)`,hours:1.5},{activity:`Readiness quiz Q4 / knowledge check`,hours:.25},{activity:`L4 completion: requirements set and self-audit (team share, out of class)`,hours:2.6},{activity:`Graduate The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements” memo (notebook entry 4): The MITRE Systems Engineering Guide, “Develop System-Level Technical Requirements”, p. 367–372 (≈ 0.4 h), six checklist items against the team set and one argued disagreement (≈ 0.9 h)`,hours:1.3},{activity:`Review notebook time log and AI statement`,hours:.15}],references:[{reading:`R55`,pages:`365–374`},{reading:`R49`,pages:`149–150`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},d=e({default:()=>f}),f={week:5,drivingQuestion:`AeroLink now has a first set of requirements. Are they the right requirements, written well enough to verify, does every one of them trace to a need and every need to a requirement — and how will the team know, months before the first flight, whether the design is drifting towards a threshold it cannot meet?`,blocks:[{id:`w5-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcomes B-CLO2 (a traceable set of well-formed requirements linked to MOE/MOP) and B-CLO4 (reading and building SysML v2 models). In Week 4 your team wrote its first requirements. This week another team audits them, you audit theirs, and both sets are revised. You then build the bidirectional trace that shows every requirement has a reason and every need has a requirement, and define the measures — MOE, MOP and TPM — that will tell AeroLink whether the requirements are being met and whether the design is drifting towards a threshold. The last 20 minutes of the lab are the first SysML reading micro-lab: you read, but do not yet write, a small validated SysML v2 model of the AeroLink fleet.`],bullets:[`B5.1 (Evaluate) Evaluate a peer team’s requirements against quality characteristics.`,`B5.2 (Analyse) Build a bidirectional trace; identify orphans and childless parents.`,`B5.3 (Create) Define an MOE → MOP → TPM hierarchy with thresholds and margins.`,`B5.4 (Understand) Read a SysML v2 package and part fragment and identify its elements.`,`Graduate expectation: design leading indicators for one TPM (SEBoK v2.14, “Measurement”, p. 531–532) and justify the contingency you apply to its current estimate (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117).`],citations:[],provenance:`instructor-authored`},{id:`w5-intuition`,kind:`intuition`,title:`Intuition: “I want to feel healthier” is not something you can put on a scale`,paragraphs:[`Suppose your goal is to feel healthier by the summer. Nobody can measure “feel healthier” directly every morning, so you choose something you can measure that you believe drives it — say, resting heart rate below 60 beats per minute. That number is still a single snapshot, and a snapshot does not tell you whether you will make it. What tells you is the trend: the weekly average has fallen from 72 to 66 in six weeks, and if it keeps falling at that rate you will cross 60 with time to spare. If it stalls at 64 in week eight you know early, while there is still time to change your training.`,`Those three layers are the structure of this week. “Feel healthier” is the effectiveness the user cares about (an MOE). Resting heart rate is a characteristic of the system that you believe produces it (an MOP). The weekly trend of a design-dependent parameter, read against a threshold with a margin and an alert before trouble arrives, is a technical performance measure (TPM). And the whole thing only works if every link is traceable: if you cannot say which goal the heart-rate target serves, nobody can tell whether dropping it is safe. AeroLink’s version is passenger wait, charge time and the month-by-month estimate of charge time as the charger design matures.`],citations:[],provenance:`instructor-authored`},{id:`w5-quality`,kind:`concept`,title:`Requirement quality: the attributes of a good requirement and how an audit uses them`,paragraphs:[`The DoD Systems Engineering Guidebook (Requirements Analysis process) lists thirteen attributes of good requirements: necessary; unique; unambiguous; clear and concise; complete; consistent; technically feasible, achievable and obtainable; traceable; measurable or quantifiable; verifiable (for example testable); able to be validated; operationally effective and survivable; and singular. The same passage explains why this matters: poorly written requirements can cause significant problems in schedule, cost or performance and so raise program risk, while defining requirements early with these attributes reduces development time and improves the quality of the final system (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 143–144). This list is the checklist for this week’s peer audit.`,`SEBoK separates two questions an assessment of requirements must answer, and warns that they are not the same as system verification and validation. Requirement verification asks whether the requirements are well-formed — whether each requirement and the set have the characteristics and follow the rules of the organisation’s criteria. Requirement validation asks whether these are the right requirements — whether they communicate the intent of the needs and parent requirements they were transformed from, are correct and are achievable. Peer review and comparison of each requirement against a set of characteristics and the integrated set of needs are named methods for both (SEBoK v2.14, “System Requirements Definition”, p. 566). A peer audit therefore has two halves: a line-by-line check against the attributes, and a check against the parents.`,`MITRE adds the practitioner’s warnings. Poorly written requirements make traceability difficult because the real meaning is lost; ambiguous terminology such as “may” or “will” makes requirements hard to scope, decompose and test. Requirements that are difficult or impossible to test cannot be traced to results, a problem that systems-of-systems efforts make much worse. Excessive reliance on derived requirements can dilute the true nature of the need, and requirements creep runs both ways — requirements diluted to make goals easier, or “gold-plated” beyond scope (The MITRE Systems Engineering Guide, “Assess the Design”, p. 389–390).`,`Applying this to an audit (course practice, instructor-authored): a finding must name the attribute it relies on, quote the words that violate it, and propose a revision; a finding that names no attribute is an opinion. Be equally careful about false findings. A requirement that carries a TBD tied to an owned AROU entry is a deliberate, managed incompleteness, not a defect; and a solution-specific requirement such as “shall have a carbon-fibre airframe” is perfectly verifiable by inspection — its defect is that it is not shown to be necessary or traceable. The rubric (RB-3.6) rewards the team being audited for accepting or rejecting each finding with a reason, so a vague finding wastes both teams’ time.`],quote:{text:`Poorly written requirements make traceability difficult because the real meaning is often lost.`,cite:{reading:`R56`,pages:`389`}},citations:[{reading:`R48`,pages:`143–144`},{reading:`R13`,pages:`566`},{reading:`R56`,pages:`389–390`}],provenance:`mixed`},{id:`w5-trace`,kind:`concept`,title:`Bidirectional traceability, orphans and childless parents`,paragraphs:[`The DoD Requirements Management process maintains a current, approved set of requirements across the life cycle. Through it the systems engineer tracks requirement changes and maintains traceability from end-user needs to the system performance specification and ultimately the delivered capability, tracing high-level requirements down to system elements at the lowest level of the design. It also provides bottom-up traceability from any derived lower-level requirement to the source from which it originates. The Guidebook calls this bidirectional traceability the key to effective requirements management: it allows the system-wide effects of a change to be understood, ensures an approved change leaves no “orphaned” lower-level requirement (every bottom-up relationship remains valid), and ensures there is no “childless parent” — every high-level requirement is ultimately addressed by lower-level requirements and system element designs (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 118).`,`The systems engineer keeps a Requirements Traceability Matrix (RTM) that captures every requirement in the specification, its decomposition, derivation and allocation history, and the rationale for all entries and changes. Requirements should be traceable to and from end-user needs; correctly allocated, with the effects of proposed changes investigated and communicated; and feasibly allocated — a lower-level element cannot have the same or a wider tolerance band than the higher-level element it is part of. The RTM pays off in trade-off analysis because it captures the system-wide effects of a proposed change (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 119).`,`MITRE defines requirements traceability as the process of creating and understanding the bidirectional linkage between requirements (operational need), organisational goals and solutions (performance). A requirement should flow two ways: towards larger organisational goals and towards the solution that delivers the capability. Traceability is also the foundation of the change process — without end-to-end trace the impact of a change cannot be evaluated. MITRE’s example is a ship built for 32 knots: there must be a trail of requirements, tied to verification, that justifies the extra engineering, construction and sustainment cost of that speed (The MITRE Systems Engineering Guide, “Assess the Design”, p. 384–385). The RTM typically links functional requirements, system requirements and the design components meant to meet them, and can be extended to the tests that check each component (The MITRE Systems Engineering Guide, “Assess the Design”, p. 387–388).`,`In this course the trace is held in the AeroLink workspace with the course relationship names (derives-from, refines, satisfies, verifies, measures); this is a teaching representation, not SysML v2 syntax. An orphan is an active requirement with no derives-from or refines link to a NEED, CAP or higher REQ. The trace explorer runs two childless-parent checks and reports them side by side, with equal weight. Check 1 is OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”’s own case: a high-level requirement — here a stakeholder requirement (REQ-STK) — not yet addressed by a lower-level requirement or a satisfying design element. Check 2 extends the same idea one level up, which is a course convention rather than OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”’s wording: an active NEED or CAP with no requirement derived from or refining it. OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process” says high-level requirements must “ultimately” be addressed, so a check-1 finding early in the project is an open item to track, not yet an error. SEBoK recommends defining the traceability relationship model at the start of the project so everyone knows which relationships will be kept (SEBoK v2.14, “System Requirements Definition”, p. 565).`],quote:{text:`This bi-directional traceability is the key to effective management of system requirements.`,cite:{reading:`R45`,pages:`118`}},citations:[{reading:`R45`,pages:`118–119`},{reading:`R56`,pages:`384–388`},{reading:`R13`,pages:`565`}],provenance:`mixed`},{id:`w5-measures`,kind:`concept`,title:`Technical measurement: MOE, MOP and TPM, thresholds, contingency and margin`,paragraphs:[`SEBoK describes technical measurement as the measurement activities that give information about progress in defining and developing the technical solution, the associated risks and issues, and the likelihood of meeting the acquirer’s critical objectives; that insight is also used in trade-off decisions when performance is not within thresholds or goals. Technical measurement includes measures of effectiveness (MOEs), measures of performance (MOPs) and technical performance measures (TPMs); their relationships are drawn in SEBoK’s Figure 3 (credited to Roedler et al. 2010; the text cites Roedler and Jones 2005 for the three kinds of measure), and the measures can be planned early and then performed with increasing fidelity as the solution develops (SEBoK v2.14, “Measurement”, p. 532–533). The figure is not reproduced here. The course uses the definitions in rubric RB-4.1: an MOE measures mission or user effectiveness; an MOP measures a system characteristic that contributes to an MOE; a TPM is a tracked design parameter with a threshold and a margin. Linkage is part of the definition (RB-4.2): every MOP traces to an MOE, which traces to a need, and to at least one requirement, and TPMs are tied to risky requirements.`,`The DoD Guidebook defines TPMs as measures collected over time to see trends and forecast progress to plan. They cover quantifiable attributes of both the development process and the product’s performance and maturity. Early in the life cycle they are estimated from assumptions and modelling and simulation; as the program proceeds, demonstrated data replaces the estimates. If there is enough margin, TPMs help identify trade space, and they provide leading indicators of performance deficiencies or system risk (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 113). Reporting should show actual against planned values, plotted over time and aligned with reviews, and a good metric has four attributes: it is quantifiable with defined criteria and a consistent method; it is collected at a routine interval; there is a planned curve, goal, control limits or threshold to measure against (at minimum a planned value at each review); and it is strongly relevant to a program risk, decision, incentive, key process or predictor of required performance (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 116).`,`The Guidebook then makes the arithmetic precise. TPM reporting should account for uncertainty such as measurement error and the immaturity of the item measured. The allowance for that uncertainty is called contingency; it is added to the Current Best Estimate (CBE) to give a Worst Case Estimate (WCE) that is compared with the planned profile, thresholds and goals. A surrogate test article warrants more contingency than the real end item, and contingency usually falls as the system and its measurements mature. Margin is different: it is not allocated, and it is the growth that can be accommodated while remaining within the threshold — the threshold minus the WCE. Margin is the trade space the program manager can use to offset under-achieving measures (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117). For a lower-is-better measure, margin = threshold − (CBE + contingency); for a higher-is-better measure the course applies the same logic in the opposite direction, margin = (CBE − contingency) − threshold, so a positive margin is always good.`,`Two consequences matter for AeroLink. First, the instructor reference records margin against the CBE (threshold − estimate), which overstates the trade space whenever the estimate is immature; this week you compute both and report the WCE margin. Second, TPMs can be decomposed: the Guidebook’s TPM hierarchy allocates a management-level TPM to subsystem assemblies along the work breakdown structure, for example a system weight TPM allocated to separate subassemblies (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 115). The same is true of AeroLink’s charge-time TPM, which could be split between charger power delivery and battery acceptance rate.`],quote:{text:`TPMs provide leading indicators of performance deficiencies or system risk.`,cite:{reading:`R44`,pages:`113`}},citations:[{reading:`R15`,pages:`532–533`},{reading:`R44`,pages:`113`},{reading:`R44`,pages:`115–117`}],provenance:`mixed`},{id:`w5-worked-audit`,kind:`worked-example`,title:`Worked example (a): a peer audit of three requirements`,paragraphs:[`Team Kestrel (a FICTIONAL peer team) submitted an L4 extract. Its needs and capabilities are the instructor reference’s (same IDs and meanings), but its requirements are its own, so they are numbered in the 900s (REQ-STK-9xx, REQ-SYS-9xx) and can never be confused with a reference requirement. The audit below applies the method from the concept block: for each requirement, name the attribute (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144), quote the offending words, and propose a revision with a parent. The attribute list is the source’s; the judgements and revisions are the instructor’s.`,`REQ-SYS-903 “The booking app shall be user-friendly and should load quickly.” Three problems. “User-friendly” and “quickly” are not measurable, so the requirement cannot be verified — no test can fail it. “Shall … and should …” combines two statements of different force, so it is not singular. And the trace table gives it no parent: it is an orphan (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 118), so nobody can tell which need it serves or whether deleting it is safe. Revision: “The booking app shall display the confirmed pick-up time within 5 s of the passenger confirming a ride, for 95 % of confirmations in a calendar month” (values FICTIONAL), derived from REQ-STK-901 and CAP-002.`,`REQ-SYS-905 “The aircraft shall have a carbon-fibre airframe.” A tempting finding is “not verifiable” — but inspection verifies it trivially, so that finding would be false and Team Kestrel would rightly reject it. The real defects are that it is not shown to be necessary and not traceable: no need, capability or higher requirement motivates carbon fibre; it is a design solution written as a requirement. Revision: ask what need lies behind it. If it is mass, and through mass the energy left on landing, write the mass or energy requirement, derive it from CAP-004 (flight operations within safety limits) — which, as example (b) shows, has no requirement at all in Kestrel’s set — and record carbon fibre as a design decision.`,`REQ-STK-903 “The AeroLink service will turn aircraft around quickly at hubs, and the charging system shall charge aircraft in 20 min.” “Will” is the ambiguous force MITRE warns about (The MITRE Systems Engineering Guide, “Assess the Design”, p. 389) and “quickly” is not measurable; two subjects and two statements make it non-singular; and it is inconsistent with its own child REQ-SYS-901, which states the 20 min charge from the 20 % reserve while the parent gives no starting state. Revision: split into the stakeholder requirement “The AeroLink service shall return an aircraft arriving at a hub vertiport to dispatch-ready status within 25 min of its arrival on the pad” (the text of the instructor reference’s REQ-STK-005) and leave the charge time to REQ-SYS-901, which already carries it.`],table:{caption:`Audit findings (instructor key; peer texts and 9xx IDs FICTIONAL). Attributes are from OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144.`,header:[`Requirement`,`Attributes violated`,`Evidence (words)`,`Action`],rows:[[`REQ-SYS-903`,`Unambiguous; Measurable; Verifiable; Singular; Traceable`,`“user-friendly”, “quickly”, “shall … and should …”; no parent`,`Rewrite with a criterion; derive from REQ-STK-901 / CAP-002`],[`REQ-SYS-905`,`Necessary; Traceable (not “Verifiable”)`,`“carbon-fibre airframe”; no parent`,`Delete or replace by the underlying performance need under CAP-004; record a design decision`],[`REQ-STK-903`,`Unambiguous; Measurable; Singular; Consistent`,`“will”, “quickly”, two subjects; conflicts with REQ-SYS-901`,`Split; 25 min turnaround at stakeholder level`]]},citations:[{reading:`R48`,pages:`144`},{reading:`R45`,pages:`118`},{reading:`R56`,pages:`389`}],provenance:`mixed`},{id:`w5-worked-trace`,kind:`worked-example`,title:`Worked example (b): a bidirectional trace with orphans and childless parents computed`,paragraphs:[`Team Kestrel’s extract has four needs (NEED-001..004), five capabilities (CAP-001, 002, 003, 004, 007) and eight requirements, with nine derives-from links. The method: (1) for every requirement, list its parents (backward trace); (2) for every need, capability and stakeholder requirement, list its children (forward trace); (3) a requirement with an empty backward list is an orphan; (4) a stakeholder requirement with no child requirement and no satisfying design element (check 1, OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”) or a NEED or CAP with an empty forward list (check 2, course convention) is a childless parent; (5) compute parent coverage as requirements with a parent divided by all requirements. Step 5 is a course measure, not a source definition; SEBoK v2.14, “Requirements Management” lists “needs and requirements not traced to a source” as one of the metrics used to monitor and control requirements (SEBoK v2.14, “Requirements Management”, p. 478).`,`Result: 6 of 8 requirements have a parent (75 %). The orphans are REQ-SYS-903 and REQ-SYS-905 — the two requirements the audit already flagged, which is no coincidence: a requirement that cannot be traced is usually one nobody needed. Check 1 finds nothing: each of Kestrel’s three stakeholder requirements has a REQ-SYS child. Check 2 finds three childless parents: NEED-002 (assurance of flight within safety limits), CAP-002 (ride booking and dispatch) and CAP-004 (flight operations within safety limits). The first and third are the serious ones: the team has written nothing about energy reserve or weather limits, so a safety need would pass the review with no requirement behind it. CAP-002 is childless only because REQ-SYS-904 (assignment within 60 s; the same text as the reference’s REQ-SYS-005) was traced to REQ-STK-901 and not also to CAP-002; the fix is one link, not a new requirement — which is why the explorer shows the forward and backward lists side by side.`,`Run the same checks on the instructor reference at the end of Week 5. It reports 20 of 20 requirements with a parent and no orphans, but check 2 finds one childless need: NEED-011 (prompt notice and a way onward when a trip is disrupted). The weather scenario SCN-005 exposed that need in Week 3, and CAP-005 meets it, yet none of the 20 requirements derives from it. This is a missing requirement, not a missing link: no existing requirement is about notifying disrupted passengers, so linking one to NEED-011 would hide the gap instead of closing it. It is exactly what this audit exists to find — the instructor’s own baseline has it — and it stays on the open-items list until a stakeholder requirement for disruption notice is written. Check 1 finds two stakeholder requirements with no lower-level requirement or design yet: REQ-STK-007 (step-free boarding) and REQ-STK-009 (flight intent to the ANSP). That is not an error at Week 5 — OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process” says each high-level requirement is “ultimately” addressed by lower-level requirements and designs — but they must stay on the open-items list until Week 8 allocates them to design elements or a REQ-SYS is written.`],table:{caption:`Trace table for the Team Kestrel extract (computed by the trace explorer; FICTIONAL; NEED/CAP are the reference’s, requirements are Kestrel’s 9xx)`,header:[`Requirement`,`Backward: parents`,`Forward: children`,`Finding`],rows:[[`REQ-STK-901 Passenger wait`,`NEED-001, CAP-001`,`REQ-SYS-904`,`—`],[`REQ-STK-902 Pad-edge noise`,`NEED-003, CAP-007`,`REQ-SYS-902`,`—`],[`REQ-STK-903 Hub turnaround`,`NEED-004, CAP-003`,`REQ-SYS-901`,`Quality defects (example a)`],[`REQ-SYS-901 Charge time`,`REQ-STK-903`,`—`,`—`],[`REQ-SYS-902 Aircraft noise`,`REQ-STK-902`,`—`,`—`],[`REQ-SYS-903 Booking app`,`none`,`—`,`Orphan`],[`REQ-SYS-904 Assignment time`,`REQ-STK-901`,`—`,`Add CAP-002 as a parent`],[`REQ-SYS-905 Airframe`,`none`,`—`,`Orphan`],[`Childless parents, check 1 (REQ-STK)`,`—`,`—`,`none`],[`Childless parents, check 2 (NEED/CAP)`,`—`,`—`,`NEED-002, CAP-002, CAP-004`]]},citations:[{reading:`R45`,pages:`118`},{reading:`R14`,pages:`478`}],provenance:`mixed`},{id:`w5-worked-tpm`,kind:`worked-example`,title:`Worked example (c): an MOE → MOP → TPM hierarchy with the margin arithmetic`,paragraphs:[`Start from effectiveness and work down. MOE-001 is the monthly 90th-percentile time from ride confirmation to boarding (threshold 15 min), measured from booking and boarding timestamps; it measures NEED-001 and MGO-005. One system characteristic that drives it is MOP-002, the charge time from the 20 % reserve to the dispatch threshold (threshold 20 min), which measures MOE-001 and the requirement REQ-SYS-001. Charge time depends on a charger and battery design that is still maturing, and REQ-SYS-001 is risky, so it becomes TPM-001, which derives from MOP-002. The same pattern gives MOE-003 noise compliance → MOP-004 pad-edge LAmax → TPM-002, and MOE-004 dispatches outside approved limits → MOP-005 landing energy remaining → TPM-003. All IDs are the instructor reference; all values are FICTIONAL.`,`The margin arithmetic for month 9. TPM-001 (lower is better): threshold 20 min, CBE 18.0 min, so the margin against the CBE — the value the reference records — is 20 − 18.0 = 2.0 min. The month-9 estimate comes from a full-pack charge test on a production-representative pack — the end item, where month 6 rested on a bench test of one module, a surrogate — so the contingency falls from 0.8 to 0.6 min: WCE = 18.0 + 0.6 = 18.6 min and the DoD margin is 20 − 18.6 = 1.4 min (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117). TPM-002 (lower is better): 65 − 63.5 = 1.5 dBA against the CBE, but the estimate is a prediction with no measurement yet, so the contingency is 1.0 dBA: WCE = 64.5 dBA, margin 0.5 dBA. TPM-003 (higher is better): 23.0 − 20 = 3.0 percentage points against the CBE; contingency 1.5 for end-of-life cell uncertainty gives WCE = 21.5 % and margin 1.5 points. None of the three meets its objective yet (15 min, 62 dBA, 25 %).`,`Status needs an explicit rule, or two engineers will read the same chart differently. The tracker uses three instructor-authored rules, applied in order: R1 breach if the WCE margin is below zero; R2 at risk if it is below the TPM’s alert floor (1 min, 0.5 dBA, 1 percentage point; FICTIONAL, the last matching the R-002 trigger in Week 6); R3 at risk if a straight-line projection of the margin to the next review falls below the floor. TPM-002’s margin has fallen from 1.0 to 0.9, 0.8 and 0.5 dBA over four quarterly reviews. It is exactly at the floor, so R2 does not fire, but the next projected value is 0.5 + (0.5 − 0.8) = 0.2 dBA, so R3 flags it at risk now — one review before a floor-only rule would. TPM-001 shows the opposite: it was at risk for the first three reviews (margins 0, 0.5, 0.9 min) and is now on track at 1.4 min as the contingency falls with the evidence behind it (datasheet, analysis, surrogate module test, end-item pack test), the pattern OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117 describes. The tracker shows the contingency and its basis for every review, so you can check that a falling contingency always has better evidence behind it. TPM-003 is on track (1.5, projected 1.1) but declining and should be watched.`],table:{caption:`TPM margins at month 9 (all values FICTIONAL; computed by the TPM tracker and asserted in tests)`,header:[`TPM (MOP, REQ)`,`Sense`,`Threshold / objective`,`CBE`,`Margin vs CBE`,`Contingency → WCE`,`Margin vs WCE`,`Projected next`,`Status`],rows:[[`TPM-001 charge time (MOP-002, REQ-SYS-001)`,`lower`,`20 / 15 min`,`18.0`,`2.0`,`+0.6 → 18.6`,`1.4`,`1.9`,`On track`],[`TPM-002 pad-edge noise (MOP-004, REQ-SYS-002)`,`lower`,`65 / 62 dBA`,`63.5`,`1.5`,`+1.0 → 64.5`,`0.5`,`0.2`,`At risk (R3)`],[`TPM-003 landing reserve (MOP-005, REQ-SYS-003)`,`higher`,`20 / 25 %`,`23.0`,`3.0`,`−1.5 → 21.5`,`1.5`,`1.1`,`On track`]]},citations:[{reading:`R44`,pages:`116–117`}],provenance:`mixed`},{id:`w5-sysml`,kind:`concept`,title:`SysML reading micro-lab 1: packages, definitions, usages, features, types and units`,paragraphs:[`The listings in this block are written in the SysML v2 textual notation as taught by the training material for pilot release 2026-08 (Seidewitz, Intro to the SysML v2 Language: Textual Notation) and described in the SysML v2.1 Beta 2 specification (OMG SysML v2.1 Beta 2, Part 1). Both are pre-final texts; the reference implementation used to check the listings is the 2026-08 pilot. Four ideas let you read them.`,`Packages and imports. A package is a namespace for its members and a container for its owned members; an import adds one member, or all members, of another package, and a name containing spaces is written in single quotes (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 5). Members are public by default; visibility must be shown on imports, and the training material advises private imports unless re-export is needed (sl.6). Every AeroLink listing therefore starts with private imports of ISQ (quantities), SI (units) and, where needed, ScalarValues (primitive types).`,`Definitions and usages. A definition classifies a kind of thing; a usage is a use of a definition in a context, and every usage is defined by at least one definition — explicitly after the colon, or implicitly by the most general library definition. Usages nested in a definition are its features (OMG SysML v2.1 Beta 2, Part 1, p. 63). A part definition defines a class of systems or parts that exist in space and time; a part usage is a composite feature; an attribute usage is a usage of an attribute definition and is always referential (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 9; OMG SysML v2.1 Beta 2, Part 1, p. 77). Definitions are declared with the kind keyword followed by def; usages with the kind keyword alone, and typing, subsetting and redefinition are written :, :> and :>> or the keywords defined by, subsets and redefines (OMG SysML v2.1 Beta 2, Part 1, p. 72). Multiplicity is written in square brackets. When none is written, a usage inherits the multiplicity of any usage it subsets or redefines, and otherwise the default is the most general [0..*]; the tighter default of exactly one [1..1] applies only to an attribute, item (including part) or port usage that is owned by a definition or another usage, not by a package, and that has no explicit subsetting or redefinition of its own (OMG SysML v2.1 Beta 2, Part 1, p. 73). Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 12 states the 1..1 default for parts.`,`Quantities and units. Only the kind of unit is associated with an attribute’s type; the specific unit is given only with an actual value, so a model is independent of the unit chosen and values can be converted (OMG SysML v2.1 Beta 2, Part 1, p. 77). In the listing, chargeTimeToDispatch : DurationValue fixes the quantity kind; 20 [min] supplies the value and the unit. ISQ provides the quantity value types such as LengthValue; SI declares units such as metre with their symbols, prefixed units such as kilogram, and derived units defined by arithmetic on other units (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 167–168). The SI library package also declares units that are not SI units but are accepted for use with them, such as min and h, and units built from those, such as km/h (defined as km divided by h, so a unit of speed but not a coherent SI unit, which would be m/s). That classification comes from the library file SI.sysml in the pilot release, not from the slides, which elide those lines. A redefinition in a usage can bind an inherited attribute to a value, as in attribute :>> massReqd = 2000[kg] (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 89).`,`Short names. Any element can have a short name written in angle brackets before its name, such as <'1.1'> (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87, sl.89; OMG SysML v2.1 Beta 2, Part 1, p. 49). The course uses this to carry its stable IDs into the model; listing 2 below gives the TPM attribute the short name TPM-001. The invalid listing below is the same charger fragment with one line missing. Before reading the commentary, find the error: what does the file import, and where does the symbol min come from?`],sysml:[{file:`week05/aerolink_fleet.sysml`,caption:`AeroLink fleet — definitions, then a configured network usage (FICTIONAL Data Sheet values)`,intent:`conformant`},{file:`week05/invalid_missing_unit_import.sysml`,caption:`Teaching listing: find the error (imports ISQ but not SI)`,intent:`intentionally-invalid`}],citations:[{reading:`R70`,pages:`5–6`},{reading:`R70`,pages:`9`},{reading:`R70`,pages:`12`},{reading:`R80`,pages:`49`},{reading:`R80`,pages:`63–64`},{reading:`R80`,pages:`72–74`},{reading:`R80`,pages:`77`},{reading:`R79`,pages:`167–168`},{reading:`R74`,pages:`87–89`}],provenance:`source-paraphrase`},{id:`w5-worked-sysml`,kind:`worked-example`,title:`Worked example (d): reading the AeroLink listings line by line`,paragraphs:[`Read aerolink_fleet.sysml from the top. Line 5 opens package AeroLinkFleet; lines 7–9 privately import ISQ, SI and ScalarValues. Lines 12–37 hold five part definitions — Battery, EVTOLAircraft, Charger, Vertiport and AeroLinkNetwork. Inside them, each attribute line is an attribute usage that is a feature of its definition, typed after the colon: usableEnergy by EnergyValue, seats by Integer, cruiseSpeed by SpeedValue. Each nested part line is a part usage: battery : Battery is a composite feature of EVTOLAircraft, chargers : Charger[1..*] says a vertiport has at least one charger. Notice what the definitions do not say: no speed value, no number of aircraft, no unit.`,`Lines 40–55 are usages. part aerolink : AeroLinkNetwork is a part usage at package level, defined by AeroLinkNetwork, and inside it every line redefines an inherited feature for this context (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 12, sl.15). part redefines fleet[12] narrows the fleet’s multiplicity from [*] to exactly 12; attribute redefines cruiseSpeed = 150 [km/h] binds the inherited attribute to a value with its unit; part redefines chargers[2] narrows [1..*] to 2 per vertiport. Multiplicity defaults need care here (OMG SysML v2.1 Beta 2, Part 1, p. 73). part battery : Battery on line 20 has no brackets, is owned by a definition and redefines nothing, so it is exactly one. part redefines battery on line 45 has no brackets either, but it is a redefinition, so the [1..1] default does not apply to it directly: it inherits the multiplicity of the battery feature it redefines, which is again exactly one. The numbers are the AeroLink Data Sheet (FICTIONAL): 12 aircraft, 4 seats, 150 km/h, 20 % reserve, 6 vertiports with 2 chargers, 65 dBA, 20 min charge, 16 h day. The dB unit is a teaching moment: the Data Sheet value is A-weighted (dBA) and the unit does not carry the weighting, so the doc comment on Vertiport records it. Reading a model includes noticing what the notation cannot say.`,`The invalid listing imports ISQ but not SI. DurationValue resolves, because it is a quantity value type from ISQ, but min does not, because units live in SI. The reference implementation reports “Couldn’t resolve reference to Element ‘min’” at line 11, with two follow-on warnings (the bracket expression is not a unit, so the bound value does not conform). It is the clearest possible demonstration of the OMG SysML v2.1 Beta 2, Part 1 principle: the type fixes the kind of quantity, the value supplies the unit.`,`Listing 2, aerolink_tpm.sysml, connects the micro-lab to this week’s measures. LowerIsBetterTimeMeasure is an attribute definition with four duration-valued features; margin is bound to the expression threshold − currentEstimate. ChargingSystem has an attribute usage chargeTimeToDispatch with the short name TPM-001 — named for what it measures, the charge time to the dispatch threshold, not the 25 min turnaround that contains it — and hubChargingSystem redefines its threshold, objective value and current estimate (20, 15 and 18 min). Two reading points. First, this is a course teaching representation — SysML v2 has no built-in MOE, MOP or TPM construct, and the margin here is the CBE margin, not the WCE margin. Second, the feature is called objectiveValue because objective is a reserved word in SysML v2 (an analysis case’s objective is a requirement on its result, Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 92); the first draft of this listing used objective and the reference implementation rejected it.`],sysml:[{file:`week05/aerolink_tpm.sysml`,caption:`TPM-001 as typed attributes with a short name (course teaching representation; FICTIONAL values)`,intent:`conformant`}],table:{caption:`Reading key for selected elements of aerolink_fleet.sysml (the SysML reading activity uses 14 such elements)`,header:[`Line`,`Text`,`Element`,`Why`],rows:[[`12`,`part def Battery`,`Definition`,`Kind keyword followed by def`],[`13`,`usableEnergy : EnergyValue`,`Attribute usage : type`,`Feature of Battery typed by an ISQ quantity value type`],[`20`,`part battery : Battery`,`Part usage`,`Composite feature typed by a part definition`],[`40`,`part aerolink : AeroLinkNetwork`,`Part usage`,`Package-level usage of a definition`],[`41`,`operatingDay = 16 [h]`,`Attribute usage, value, unit`,`Redefinition binds the inherited feature; h is declared in the SI library package as a unit accepted for use with the SI (not an SI unit)`],[`42`,`part redefines fleet[12]`,`Part usage (redefinition)`,`Narrows multiplicity [*] to 12`]]},citations:[{reading:`R70`,pages:`9`},{reading:`R70`,pages:`12`},{reading:`R70`,pages:`15`},{reading:`R80`,pages:`73`},{reading:`R80`,pages:`77`},{reading:`R75`,pages:`92`},{reading:`R74`,pages:`89`}],provenance:`mixed`},{id:`w5-advanced`,kind:`advanced`,title:`Advanced analysis: from lagging margins to leading indicators`,paragraphs:[`A margin is a snapshot; by the time it goes negative the cheap options are gone. SEBoK defines a systems engineering leading indicator as a measure for evaluating how effectively a specific activity is applied on a project, in a way that gives information about impacts likely to affect the system performance objectives. Leading indicators can be single measures or collections of measures with their analysis, and they give visibility into expected performance and potential future states. Each is composed of characteristics, a condition and a predicted behaviour; characteristics and conditions are analysed periodically to predict behaviour within a confidence level and a time range (SEBoK v2.14, “Measurement”, p. 531–532). Rule R3 in the tracker is a crude example: a characteristic (WCE margin), a condition (its change per review) and a predicted behaviour (the margin at the next review).`,`For the graduate task, go one level deeper, applying SEBoK v2.14, “Measurement” to AeroLink (instructor analysis). TPM-002 is at risk because its estimate rests on prediction alone. What activities drive the noise estimate, and which of them can be measured before the aircraft flies? Candidates: the share of the noise-prediction model validated against measured rotor data; take-off mass growth per review (more mass needs more thrust, and rotor noise depends on it); the number of open changes to published approach procedures. Each must state the condition that signals trouble and the predicted effect on TPM-002, with the time range. A leading indicator that cannot change a decision is “measurement for measurement’s sake”, one of the SEBoK pitfalls, along with the search for golden measures, treating measurement as a single pass, and using measures to judge individuals or out of context (SEBoK v2.14, “Measurement”, p. 535).`,`Two further tensions are worth arguing in the memo. Contingency is a judgement, and it changes the status: with 0.5 dBA instead of 1.0 dBA of contingency at month 9, TPM-002’s WCE would be 64.0 dBA, its WCE margin would be 1.0 dBA and, by rule R3, its projection 1.2 dBA (1.0 + (1.0 − 0.8)) — on track, and apparently improving, although nothing in the design or the evidence has changed. A program can make any TPM look healthy by shrinking contingency, so the Guidebook ties it to evidence, more for surrogate data and less as measurement matures (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117). And margins interact with allocation. The Guidebook asks that requirements be correctly and feasibly allocated, and illustrates feasibility with tolerance bands: a lower-level element cannot have the same or a wider tolerance band than the higher-level element it is part of (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 119). Carrying that idea over to budgets is the course’s reasoning, not the Guidebook’s words: if TPM-001’s 20 min were split into sequential sub-budgets (say, connection and ramp-up, then the main charge), the sub-budgets must add up to no more than 20 min, and the sub-TPM margins can never add up to more trade space than TPM-001 itself has; otherwise the system-level margin is fictional. SEBoK’s good practices close the loop: measures should be action-driven and timely enough to allow corrective action, with results presented to decision makers in a form they can act on (SEBoK v2.14, “Measurement”, p. 536).`],citations:[{reading:`R15`,pages:`531–532`},{reading:`R15`,pages:`535–536`},{reading:`R44`,pages:`117`},{reading:`R45`,pages:`119`}],provenance:`mixed`},{id:`w5-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`The DoD Guidebook lists fifteen core TPM categories that matter across acquisition programs and calls having TPMs in each of them best practice. They include Mission (end-to-end) performance — the overall ability of a system to accomplish a mission with representative personnel and external systems, related to the measures of effectiveness used by operational test agencies; System performance, with multiple TPMs forecasting each key performance parameter and key system attribute; Reliability, availability and maintainability; and Requirements management, which evaluates the stability and adequacy of the requirements, including their growth, change, completeness and correctness (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 113–115). Requirement quality and traceability are themselves measured, not just checked once.`,`SEBoK’s Requirements Management article (extension reading) gives the monitoring metrics a requirements manager would publish: the numbers of needs and requirements, those with TBDs or TBRs, those not traced to a source, and the status of system verification and validation, supported by attributes such as rationale, status, criticality, priority, stability and owner (SEBoK v2.14, “Requirements Management”, p. 478). For AeroLink this means the trace explorer’s orphan count and the number of open TBDs (TBD-01, TBD-02) belong on the dashboard at every review alongside the three TPMs, and the Week 6 SRR-style review will ask for them. In Week 10 the same requirements become SysML v2 requirement usages with these IDs as short names, and in Week 12 the MOPs and TPMs are linked to verification activities.`],citations:[{reading:`R44`,pages:`113–115`},{reading:`R14`,pages:`478`}],provenance:`mixed`},{id:`w5-lab`,kind:`lab`,title:`Lab L5 — peer audit, measures and trace; SysML reading micro-lab 1`,paragraphs:[`In teams. Exchange your L4 requirements with your assigned peer team. Audit a sample of ten of theirs against the OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process” attribute list with the audit activity as a calibration first; every finding names the attribute and the words. AI critique is allowed if each AI finding is recorded with your accept or reject reason. Revise your own set from the findings you receive. Define at least three MOE, five MOP and two TPM, each with threshold, data source and collection method, and for each TPM an objective, a current estimate, a contingency and the margin arithmetic. Build the trace table with the trace explorer on your workspace and resolve every orphan and childless parent or record why it remains. In the last 20 minutes, complete the SysML reading activity individually and annotate the two listings.`],citations:[],provenance:`instructor-authored`},{id:`w5-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: the L5 record — peer audit report, revised requirement set, MOE/MOP/TPM table and trace table — scored formatively against RB-3 and RB-4 now and summatively at CP2 in Week 6. Individual: readiness quiz Q5, the annotated SysML listings, review-notebook entry 5 with a time log, and the graduate leading-indicator memo for one TPM.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w5-act-audit`,title:`Peer audit calibration: attributes of a good requirement`,component:`w05-quality-audit`,purpose:`Audit six FICTIONAL peer requirements against the DoD attribute list and compare your findings — including false findings — with the instructor key before auditing your peer team.`,instructions:[`For each requirement, select every attribute it violates; select none if it is sound.`,`Check the finding. Read the key’s evidence and suggested revision, and the mechanical lint signals.`,`Where you disagree with the key, write down the words that justify your finding; use the same discipline in your L5 audit.`],objectives:[`B5.1`],inBlock:`w5-worked-audit`},{id:`w5-act-trace`,title:`Trace matrix explorer: coverage, orphans and childless parents`,component:`w05-trace-explorer`,purpose:`Predict, then compute, the bidirectional trace of the peer sample, your own workspace or the instructor reference.`,instructions:[`Start with the peer-team sample. Tick the requirements you expect to be orphans, the stakeholder requirements you expect to have no lower-level requirement or design element (check 1), and the needs and capabilities you expect to be childless (check 2).`,`Compute the trace and compare. For each childless parent decide: missing requirement or missing link? Then do the same for the instructor reference, which has one childless need.`,`Switch to your team’s workspace and resolve every finding before you submit the L5 trace table.`],objectives:[`B5.2`],inBlock:`w5-worked-trace`},{id:`w5-act-tpm`,title:`TPM tracker: margin over time with explicit status rules`,component:`w05-tpm-tracker`,purpose:`Read the margin history of the three reference TPMs, see which rule sets each status, and add your own next estimate to see when a TPM becomes at risk or breaches.`,instructions:[`Select TPM-002 and explain, using the table, why it is at risk although its margin is not below the floor.`,`Add a month-12 estimate that keeps TPM-002 on track. What would have to be true of the design for that estimate to be credible?`,`Repeat for TPM-003 with an estimate that breaches. Enter the contingency with its basis (analysis, surrogate test or end-item test), and check that it does not fall unless the evidence improved (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117).`],objectives:[`B5.3`],inBlock:`w5-worked-tpm`},{id:`w5-act-sysml`,title:`SysML reading micro-lab 1: classify the elements of a validated listing`,component:`w05-sysml-reading`,purpose:`Select elements in the validated AeroLink fleet listing and classify each as a definition, part usage, attribute usage, type or unit, with feedback citing the training material.`,instructions:[`Select each highlighted element (numbered in reading order) and choose its class.`,`Check your classifications and read the explanation for every one you missed.`,`Annotate a printed copy of both listings with the same five classes for your L5 record.`],objectives:[`B5.4`],inBlock:`w5-worked-sysml`}],lab:{id:`L5`,title:`Peer audit; measures; SysML reading micro-lab 1`,setting:`team`,durationMinutes:75,objectives:[`B5.1`,`B5.2`,`B5.3`,`B5.4`],inputs:[`L4 record: your REQ-STK / REQ-SYS set with rationale, method and parent, in the AeroLink workspace`,`The assigned peer team’s L4 requirements (exchanged at the start of the lab)`,`OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144 attribute list (checklist) and the audit-calibration activity`,`AeroLink Data Sheet and the Week 3 MGO/NEED/CAP (FICTIONAL values)`,`SysML listings sysml/week05/aerolink_fleet.sysml and aerolink_tpm.sysml (validated, read-only)`],steps:[{title:`Calibrate (before the swap)`,detail:`Each member completes the audit-calibration activity individually; the team compares disagreements in five minutes so that everyone uses the attributes the same way.`},{title:`Peer audit`,detail:`Draw ten of the peer team’s requirements at random (not chosen by either team). For each, record the attribute(s) violated (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144), the offending words and a suggested revision. AI critique is allowed: record each AI finding and your accept/reject reason; tag it AI-suggested-reviewed.`},{title:`Respond and revise`,detail:`For every finding on your own set, accept or reject it with a reason (RB-3.6) and revise the set in the workspace. Retire, do not delete, a requirement you drop, and give the reason.`},{title:`Measures`,detail:`Define at least 3 MOE, 5 MOP and 2 TPM. Each measure has a unit, threshold, sense, data source and collection timing; each MOP measures an MOE and at least one REQ; each TPM derives from a MOP, measures the risky REQ it tracks, and has objective, CBE, contingency (with its basis), WCE margin and alert floor.`},{title:`Trace`,detail:`Run the trace explorer on your workspace. Resolve each orphan (add a parent or retire it) and each childless parent (add a link or a requirement, or record it as a gap with an owner). Export the trace table.`},{title:`Micro-lab 1 (last 20 minutes, individual)`,detail:`Complete the SysML reading activity. Annotate both listings: mark every definition, part usage, attribute usage, type and unit, and answer in two sentences why the invalid listing fails.`}],artefacts:[{idPrefix:`REQ`,description:`Revised requirement set with audit responses`,minimum:`Every finding accepted or rejected with a reason; no orphans without a recorded reason`},{idPrefix:`MOE`,description:`Measures of effectiveness, each measuring a NEED/MGO/CAP`,minimum:`≥ 3`},{idPrefix:`MOP`,description:`Measures of performance, each measuring an MOE and ≥ 1 REQ`,minimum:`≥ 5`},{idPrefix:`TPM`,description:`Technical performance measures with threshold, objective, CBE, contingency and margin`,minimum:`≥ 2, each tied to a risky REQ`}],continuity:`The revised REQ set, the MOE/MOP/TPM table and the trace table are the CP2 Requirements Baseline reviewed live in the Week 6 SRR-style review. Week 6 turns at-risk TPMs into risks with triggers (for example R-002 watches TPM-003); Week 7 trade-study criteria derive from the MOEs; Week 10 converts the requirements into SysML v2 requirement usages with their IDs as short names, building on the reading skills from this micro-lab; Week 12 links verification activities to REQ, MOP and TPM.`,tools:[{label:`Air Taxi Enterprise workspace (requirements, measures and links)`,to:`/workspace/aerolink`},{label:`Stakeholder ecosystem editor (parents of needs)`,to:`/workspace/stakeholders`}]},assignment:{id:`W5-A`,title:`L5 record: peer audit report, revised set, measures and trace table; graduate leading-indicator memo`,mode:`team`,due:`Before the first session of Week 6 (CP2 review)`,weight:`L5 record (team): formative now, scored at CP2 (10 %; RB-3 40, RB-4 20) · graduate memo counts toward the review notebook (RB-16, 5 %)`,instructions:[`Team: submit the audit report on the peer team’s ten sampled requirements, your responses to the findings on your set, the revised set, the MOE/MOP/TPM table and the exported trace table.`,`Every audit finding cites the attribute it relies on (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144) and quotes the words; every response accepts or rejects with a reason.`,`Show the margin arithmetic for each TPM: threshold, objective, CBE, contingency with its basis, WCE and margin (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117). State the status rule you apply.`,`Report parent coverage, orphans and childless parents before and after revision.`,`Individual (graduate): a one-page memo designing two leading indicators for one of your TPMs, each with characteristic, condition and predicted behaviour (SEBoK v2.14, “Measurement”, p. 531–532), and saying what decision each could change. Extension reading SEBoK v2.14, “Requirements Management”. Budget about 1 h: 20 min for SEBoK v2.14, “Requirements Management”, 40 min to design and write. The memo is a required notebook entry that is always read.`,`Log your hours for the week in the review notebook.`],template:[{heading:`1. Peer audit report`,guidance:`Table: REQ ID, attribute(s) violated (OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144), quoted words, suggested revision, AI-suggested? (Y/N). Ten requirements drawn at random; say how they were drawn.`},{heading:`2. Response to findings on our set`,guidance:`Each finding received: accepted or rejected, with a reason. Rejections must cite the requirement text or a managed TBD/AROU entry (RB-3.6).`},{heading:`3. Revised requirement set`,guidance:`Workspace export. Mark changed, split and retired requirements; give the reason for each retirement.`},{heading:`4. MOE → MOP → TPM table`,guidance:`For each measure: ID, definition, unit, sense, threshold (with justification), data source, collection timing, links (MOP → MOE → NEED; MOP → REQ; TPM → MOP and REQ). For each TPM: objective, CBE, contingency and basis, WCE, margin, alert floor, status and rule.`},{heading:`5. Trace table and findings`,guidance:`Exported trace table; parent coverage before and after; every orphan and childless parent with its resolution or an owner and date.`},{heading:`6. Graduate: leading indicators for one TPM`,guidance:`Two indicators, each with characteristic, condition, predicted behaviour and time range (SEBoK v2.14, “Measurement”, p. 531–532); the decision it informs; one pitfall from SEBoK v2.14, “Measurement”, p. 535 you avoided and how.`},{heading:`7. AI usage statement`,guidance:`Tool, purpose, prompts, what you accepted or rejected and why (RB-12).`}],rubrics:[`RB-3`,`RB-4`,`RB-16`,`RB-12`],rubricScope:`Requirements: RB-3.1–3.6 (3.1–3.4 on the grader’s sample of 10; 3.5–3.6 on the whole set and the audit responses). Measures: RB-4.1–4.3 in full. Graduate memo (individual): a required review-notebook entry under RB-16, always read and not sampled (RB-16 graduate-task note); scored formatively on RB-4.3 (measurement rationale) as the memo applies it — 4: two indicators, each with characteristic, condition, predicted behaviour, time range, the data and timing that feed it and the decision it could change, plus one SEBoK v2.14, “Measurement”, p. 535 pitfall avoided; 3: both indicators complete but the data or the decision thin; 2: indicators that restate the TPM or a lagging test result; 1: missing. The set of graduate tasks informs RB-16.1. AI statement: RB-12.1–12.3.`,aiUse:`AI tools may critique requirements during the audit and suggest candidate measures. Every AI finding is recorded with an accept/reject reason and tagged AI-suggested-reviewed; AI-proposed thresholds or contingencies must be justified from the case data or labelled as assumptions. AI must not be used to classify the SysML listing elements in the micro-lab.`,objectives:[`B5.1`,`B5.2`,`B5.3`,`B5.4`]},quiz:[{id:`q5-1`,bloom:`Evaluate`,objective:`B5.1`,prompt:`An auditor flags the reference requirement REQ-STK-007 (“The AeroLink service shall allow a passenger using a wheelchair to board and alight at every vertiport without being lifted.”) as “not measurable and not verifiable: it contains no number”. How should the audited team respond?`,options:[{id:`a`,text:`Accept, and add a number such as “within 5 min” so that the requirement becomes measurable`,correct:!1,explanation:`That adds a criterion the need does not ask for and changes the requirement; the existing criterion can already pass or fail.`},{id:`b`,text:`Reject with a reason: the criterion is pass/fail at each of the six vertiports — a step-free route exists or it does not — so inspection or demonstration verifies it without a number`,correct:!0,explanation:`Correct. Verifiable is an attribute in OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 144, and a pass/fail criterion checked at every vertiport meets it; the reference assigns inspection. A finding has to quote words that fail an attribute, and “no number” is not such a defect. RB-3.6 rewards the reasoned rejection.`},{id:`c`,text:`Accept, and rewrite it as “Boarding shall be accessible to all passengers”`,correct:!1,explanation:`“Accessible to all” is vaguer than the original, which names the user, the action and the condition (without being lifted).`},{id:`d`,text:`Reject, because stakeholder requirements do not need to be verifiable`,correct:!1,explanation:`The OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process” attribute list applies to stakeholder requirements too; the reason to reject is that this one is verifiable, not that it need not be.`}],cite:{reading:`R48`,pages:`144`}},{id:`q5-2`,bloom:`Evaluate`,objective:`B5.1`,prompt:`A peer team’s requirement reads “The aircraft shall operate in crosswinds up to TBD kt.” Their AROU register has no entry for this TBD: no owner, no way of resolving it and no need-by date. You flag it as violating “Complete”. They reject the finding: “a TBD is managed incompleteness, not a defect”. Whose position is better supported?`,options:[{id:`a`,text:`Theirs: any requirement that says TBD is acceptable at this stage`,correct:!1,explanation:`What makes a TBD acceptable is that it is managed — tracked with an owner and a date — not the letters TBD.`},{id:`b`,text:`Yours: this TBD is not managed, so nobody will resolve it; the finding stands, and the fix is to open an AROU unknown with an owner and a need-by date (or to set the value)`,correct:!0,explanation:`Correct. SEBoK treats resolving TBDs and TBRs as part of requirements monitoring and control and counts them as a metric (SEBoK v2.14, “Requirements Management”, p. 478); an untracked TBD escapes both. The same words with an owned AROU entry would make their rejection the right one.`},{id:`c`,text:`Neither: the requirement should be deleted until the value is known`,correct:!1,explanation:`Deleting it loses the constraint and any trace to its parent; the gap would reappear later without a record.`},{id:`d`,text:`Theirs: completeness is only checked at the critical design review`,correct:!1,explanation:`Nothing in the readings defers completeness to one review; the peer audit is exactly where an unmanaged TBD should be caught.`}],cite:{reading:`R14`,pages:`478`}},{id:`q5-3`,bloom:`Analyse`,objective:`B5.1`,prompt:`SEBoK distinguishes requirement verification from requirement validation. Which audit question is a requirement-validation question?`,options:[{id:`a`,text:`Does each requirement have exactly one “shall” and a measurable criterion?`,correct:!1,explanation:`That checks well-formedness against criteria: requirement verification.`},{id:`b`,text:`Does REQ-SYS-001’s 20 min charge actually serve the intent of NEED-004 and REQ-STK-005’s 25 min turnaround?`,correct:!0,explanation:`Correct. Validation asks whether these are the right requirements, communicating the intent of the needs and parents they came from (SEBoK v2.14, “System Requirements Definition”, p. 566).`},{id:`c`,text:`Has the charging system passed its acceptance test?`,correct:!1,explanation:`That is system verification, which SEBoK says is a different concept from requirement verification and validation.`},{id:`d`,text:`Are the requirement IDs in the REQ-SYS-nnn format?`,correct:!1,explanation:`A format rule is part of well-formedness, not validation.`}],cite:{reading:`R13`,pages:`566`}},{id:`q5-4`,bloom:`Analyse`,objective:`B5.2`,prompt:`Another team’s trace shows two findings. (1) An orphan: “The vertiport shall provide covered seating for at least 12 waiting passengers”, whose recorded rationale says it serves their need “Sheltered wait at the vertiport” — a need that is in their set but has no link to it. (2) A childless capability, “Lost-property handling”: no requirement in their set mentions lost property, items or claims. What is the most economical correct action?`,options:[{id:`a`,text:`Delete the orphan, and link the capability to the closest existing requirement`,correct:!1,explanation:`The orphan has a real parent named in its own rationale, and linking an unrelated requirement to the capability would hide the gap instead of closing it.`},{id:`b`,text:`Add the missing derives-from link from the orphan to the need its rationale names; for the capability, write a requirement (or record the gap with an owner), because no existing requirement serves it`,correct:!0,explanation:`Correct. Each finding is resolved by what is actually missing: a link in the first case, a requirement in the second. Bidirectional trace requires both no orphans and no childless parents (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 118).`},{id:`c`,text:`Link any requirement to the capability so that the checker stops reporting it, and leave the orphan for later`,correct:!1,explanation:`A link that does not reflect a real derivation makes the trace lie; the checker’s count improves while the gap remains.`},{id:`d`,text:`Write a new need for the orphan, and leave the capability, because childless capabilities are allowed until design`,correct:!1,explanation:`A suitable need already exists; and a childless capability is a gap to resolve or record, not something that can wait silently.`}],cite:{reading:`R45`,pages:`118`}},{id:`q5-5`,bloom:`Apply`,objective:`B5.2`,prompt:`REQ-STK-005 allows 25 min from pad arrival to dispatch-ready. A team allocates 20 min to charging (REQ-SYS-001) and 8 min to passenger handling and positioning, done in sequence with the charge. Which judgement is best supported?`,options:[{id:`a`,text:`It is correctly allocated because each child requirement is individually achievable`,correct:!1,explanation:`Individual achievability is not enough; the children together must fit inside the parent.`},{id:`b`,text:`The allocation does not fit: in sequence the children need 28 min against the parent’s 25 min, so it is not feasibly allocated; change the budgets or overlap the steps`,correct:!0,explanation:`Correct. OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 119 asks that requirements be correctly and feasibly allocated and illustrates feasibility with tolerance bands; adding up sequential time budgets against the parent is the course’s way of applying that to a time budget (instructor reasoning, not the source’s words).`},{id:`c`,text:`It is fine as long as both children trace to REQ-STK-005`,correct:!1,explanation:`Trace links show derivation, not that the allocation is feasible.`},{id:`d`,text:`Allocation is a design matter and is outside requirements management`,correct:!1,explanation:`OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 119 lists correct and feasible allocation as properties the RTM must support.`}],cite:{reading:`R45`,pages:`119`}},{id:`q5-6`,bloom:`Analyse`,objective:`B5.2`,prompt:`AeroLink’s city partner asks for the noise limit to drop from 65 to 63 dBA. Why does MITRE call traceability the foundation of the change process?`,options:[{id:`a`,text:`Because a trace lets you find every requirement, design element and test affected by the change and evaluate its end-to-end impact`,correct:!0,explanation:`Correct. Without end-to-end trace the impact of a change cannot be effectively evaluated (The MITRE Systems Engineering Guide, “Assess the Design”, p. 385); here REQ-STK-002, REQ-SYS-002, MOP-004 and TPM-002 would all move.`},{id:`b`,text:`Because a trace proves the new limit can be met`,correct:!1,explanation:`Trace identifies what is affected; feasibility needs analysis — TPM-002 would have a negative margin at 63 dBA.`},{id:`c`,text:`Because changes are only allowed to requirements that have no children`,correct:!1,explanation:`Nothing restricts changes to leaf requirements; trace tells you the cost of changing a parent.`},{id:`d`,text:`Because the RTM is a contractual deliverable`,correct:!1,explanation:`It may be, but MITRE’s point is about evaluating impact, not paperwork.`}],cite:{reading:`R56`,pages:`385`}},{id:`q5-7`,bloom:`Apply`,objective:`B5.3`,prompt:`Which set correctly classifies three AeroLink measures as MOE, MOP and TPM (course definitions, RB-4.1)?`,options:[{id:`a`,text:`MOE: pad-edge LAmax per movement; MOP: share of movements compliant with the city agreement; TPM: daily trips served`,correct:!1,explanation:`Reversed: compliance is the effectiveness the city cares about; LAmax is the system characteristic; trips served is an MOE, not a tracked design parameter.`},{id:`b`,text:`MOE: 90th-percentile passenger wait; MOP: charge time from 20 % reserve; TPM: month-by-month estimate of charge time against its 20 min threshold with margin`,correct:!0,explanation:`Correct. Wait is user effectiveness, charge time is a system characteristic that drives it, and the tracked estimate with threshold and margin is the TPM (worked example c).`},{id:`c`,text:`MOE: charger power in kW; MOP: passenger satisfaction; TPM: number of vertiports`,correct:!1,explanation:`Charger power is a design parameter, satisfaction is effectiveness, and the number of vertiports is a configuration choice, not a tracked parameter.`},{id:`d`,text:`All three are MOPs because they are all numbers`,correct:!1,explanation:`Being quantitative does not decide the class; what is measured and why does.`}],cite:{reading:`R15`,pages:`532`}},{id:`q5-8`,bloom:`Apply`,objective:`B5.3`,prompt:`A team tracks hover power at maximum take-off mass as a TPM (lower is better): threshold 220 kW, current best estimate 205 kW from a surrogate rotor-rig test, contingency 9 kW (values FICTIONAL). Using the DoD definitions, what is the margin?`,options:[{id:`a`,text:`15 kW (220 − 205)`,correct:!1,explanation:`That is the margin against the current best estimate; the DoD margin is measured against the worst case estimate.`},{id:`b`,text:`6 kW (220 − (205 + 9))`,correct:!0,explanation:`Correct. For a lower-is-better measure the contingency is added to the CBE: WCE = 214 kW, and the margin is the remainder of threshold minus WCE (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117).`},{id:`c`,text:`24 kW (220 − (205 − 9))`,correct:!1,explanation:`Contingency moves the estimate towards the threshold, never away from it.`},{id:`d`,text:`9 kW, because the contingency is the margin`,correct:!1,explanation:`Contingency is allocated to each estimate; margin is not allocated and is what remains below the threshold (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 117).`}],cite:{reading:`R44`,pages:`117`}},{id:`q5-9`,bloom:`Evaluate`,objective:`B5.3`,prompt:`A team tracks range on the design mission at end of battery life (higher is better; threshold 50 km; alert floor 2 km; status rules R1–R3 as in the TPM tracker). Its WCE margin over four reviews is 6.0, 5.0, 4.0 and 3.5 km. The team lead reports it “at risk — the margin has almost halved”. Which judgement is best supported? (values FICTIONAL)`,options:[{id:`a`,text:`Agree: a margin that has fallen by 40 % is at risk`,correct:!1,explanation:`No stated rule uses the relative fall since the first review; two engineers applying different unstated rules would report different statuses.`},{id:`b`,text:`Disagree under the stated rules: 3.5 km is above the 2 km floor and the projection to the next review is 3.0 km (3.5 + (3.5 − 4.0)), so it is on track — but the erosion should stay on the watch list`,correct:!0,explanation:`Correct. TPMs exist to show trends and forecast progress (OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process”, p. 113), and rule R3 projects the last change; it stays above the floor, and the decline is slowing.`},{id:`c`,text:`Agree: projecting the whole fall since the first review (−2.5 km) gives 1.0 km, below the floor`,correct:!1,explanation:`R3 projects the change over the last interval to the next review, not the whole history over one interval; mixing rules is how statuses become arguable.`},{id:`d`,text:`It is a breach, because the margin is below the objective`,correct:!1,explanation:`Margin is measured against the threshold; a breach means the worst case is beyond the threshold, and the margin here is still positive.`}],cite:{reading:`R44`,pages:`113`}},{id:`q5-10`,bloom:`Create`,objective:`B5.3`,prompt:`You are designing a leading indicator for TPM-002 (pad-edge noise). Which proposal has all the parts SEBoK describes for a leading indicator?`,options:[{id:`a`,text:`“Track noise closely.”`,correct:!1,explanation:`No characteristic, condition or predicted behaviour; it is not a measure.`},{id:`b`,text:`Characteristic: rotor tip speed in the current design, per review; condition: an increase of more than 3 % since the last review; predicted behaviour: TPM-002 WCE margin below 0.5 dBA within two reviews (values FICTIONAL)`,correct:!0,explanation:`Correct. A leading indicator is composed of characteristics, a condition and a predicted behaviour within a time range (SEBoK v2.14, “Measurement”, p. 531–532); tip speed is a design activity output that drives rotor noise and can be read long before a flight test.`},{id:`c`,text:`The measured LAmax at the first flight test`,correct:!1,explanation:`Useful, but it is a lagging measurement taken when it is too late to change the design cheaply.`},{id:`d`,text:`A single golden noise measure used for every vertiport and every program`,correct:!1,explanation:`SEBoK lists the search for golden measures as a pitfall (SEBoK v2.14, “Measurement”, p. 535).`}],cite:{reading:`R15`,pages:`531–532`}},{id:`q5-11`,bloom:`Apply`,objective:`B5.4`,prompt:`In aerolink_fleet.sysml, part def Battery declares attribute reserveShare : Real; and the usage binds it with attribute redefines reserveShare = 0.20; — with no unit in brackets. The listing passes the reference implementation. Why is no unit needed, and what does 0.20 mean?`,options:[{id:`a`,text:`A unit is needed; the tool simply did not check this line`,correct:!1,explanation:`The tool checks every line against the library; this one is valid because of the type, not because it was skipped.`},{id:`b`,text:`Real is a primitive data type, not a quantity value type, so its values are plain numbers; 0.20 is the fraction 20 %, and its meaning (share of usable energy) lives in the name, not in a unit`,correct:!0,explanation:`Correct. Attribute usages can be typed by primitive data types such as Integer and Real, while quantities with units are typed from the Quantities and Units library (OMG SysML v2.1 Beta 2, Part 1, p. 77); only the second kind takes a unit with its value.`},{id:`c`,text:`The unit defaults to percent, so 0.20 means 0.20 %`,correct:!1,explanation:`There is no default unit; a Real carries no unit at all, which is why the name must say what the number is.`},{id:`d`,text:`The unit is inherited from usableEnergy in the same definition, so 0.20 is an energy`,correct:!1,explanation:`Features do not share units; each attribute is typed on its own, and reserveShare is typed by Real.`}],cite:{reading:`R80`,pages:`77`}},{id:`q5-12`,bloom:`Apply`,objective:`B5.4`,prompt:`Inside part aerolink : AeroLinkNetwork, line 49 reads part redefines vertiports[6] { … } and, nested inside it, line 51 reads part redefines chargers[2] { … }. Vertiport declares part chargers : Charger[1..*];. How many chargers does the usage aerolink have?`,options:[{id:`a`,text:`2: the multiplicity on line 51 is the total for the network`,correct:!1,explanation:`Line 51 is nested in the vertiports redefinition, so it constrains the chargers of each vertiport, not of the network.`},{id:`b`,text:`12: each of the 6 vertiports has exactly 2 chargers, because the chargers redefinition is nested inside the vertiports redefinition`,correct:!0,explanation:`Correct. Redefinition can constrain multiplicity (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 12), and chargers is a feature of each vertiport that the nested redefinition narrows from [1..*] to [2] (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 15). 6 × 2 = 12 matches the Data Sheet.`},{id:`c`,text:`At least 6, because Vertiport only requires [1..*] chargers`,correct:!1,explanation:`That is what the definition alone allows; the usage narrows it to exactly 2 per vertiport.`},{id:`d`,text:`Unknown: redefinition inside a usage changes the definition Vertiport, so the count is set elsewhere`,correct:!1,explanation:`Redefinition in a usage constrains only that usage; the definition Vertiport is unchanged.`}],cite:{reading:`R70`,pages:`12`}},{id:`q5-13`,bloom:`Analyse`,objective:`B5.4`,prompt:`Suppose line 9 of aerolink_fleet.sysml (private import ScalarValues::*;) is deleted and the file is checked again. Which names on lines 12–21 stop resolving?`,options:[{id:`a`,text:`The units h, km/h and dB, because units are declared in ScalarValues`,correct:!1,explanation:`Units are declared in the SI package, which is still imported (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 168).`},{id:`b`,text:`Only Real (line 14) and Integer (line 18), the primitive types; EnergyValue and SpeedValue still resolve through ISQ`,correct:!0,explanation:`Correct. The course ran this variant through the reference implementation: it reported “Couldn’t resolve reference to Type ‘Real’” and “… ‘Integer’”, plus follow-on errors on the attributes typed by them and their redefinitions, and nothing else. Quantity value types come from ISQ and units from SI (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 167–168).`},{id:`c`,text:`EnergyValue and SpeedValue, because every value type comes from ScalarValues`,correct:!1,explanation:`Quantity value types such as EnergyValue are ISQ types; ScalarValues supplies only primitive types such as Integer and Real.`},{id:`d`,text:`Nothing: the standard library is visible without imports`,correct:!1,explanation:`Library names must be imported; that is why the invalid listing, which omits SI, fails on min.`}],cite:{reading:`R79`,pages:`167–168`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min)`,hours:2.5},{activity:`Readings OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, The MITRE Systems Engineering Guide, “Assess the Design”, SEBoK v2.14, “Measurement”, OUSD(R&E) Systems Engineering Guidebook, “Technical Assessment Process” and OUSD(R&E) Systems Engineering Guidebook, “Stakeholder Requirements Definition Process”, p. 143–146 (≈ 31 pp at ≈ 15 pp/h)`,hours:2.1},{activity:`Online direct instruction (≈ 5,800 words) and the four interactive activities`,hours:1.2},{activity:`Readiness quiz Q5 / knowledge check`,hours:.2},{activity:`L5 completion: audit report, revision, measures and trace (team share, out of class; tight — see cautions)`,hours:1.8},{activity:`Graduate leading-indicator memo: extension reading SEBoK v2.14, “Requirements Management” (5 pp, ≈ 20 min) and designing and writing two indicators (≈ 40 min)`,hours:1},{activity:`Review notebook entry, time log and AI statement`,hours:.2}],references:[{reading:`R13`,pages:`565–566`},{reading:`R14`,pages:`478–479`},{reading:`R70`},{reading:`R74`,pages:`87–89`},{reading:`R75`,pages:`92`},{reading:`R79`},{reading:`R80`,pages:`49–77`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},p=e({default:()=>m}),m={week:6,drivingQuestion:`AeroLink’s requirements baseline promises a 20-minute charge, a 20 % landing reserve and a capacity target at month 24. Are the technologies under those promises mature enough, what could stop them being met, what are we only assuming — and would an independent reviewer let the baseline proceed?`,blocks:[{id:`w6-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcomes B-CLO3 (evaluate under uncertainty), B-CLO6 (professional review) and B-CLO4 (reading SysML v2 models). Weeks 4 and 5 produced a requirements set, a trace table and a measures hierarchy. Week 6 asks whether that baseline can actually be met: are the technologies it depends on mature enough, what could go wrong, what is merely assumed, and would an independent reviewer accept it? The week ends with CP2, the Requirements Baseline, defended in a live SRR-style review in which every team is both reviewed and a reviewer. Online, SysML micro-lab 2 takes the reading skills of Week 5 one step further: specialization, subsetting and attributes whose units must match their quantity types.`],bullets:[`B6.1 (Evaluate) Assess the readiness of three enabling technologies on the TRL scale, citing evidence or labelling assumptions.`,`B6.2 (Evaluate) Write condition–if–then risk statements, rate them on the 5×5 matrix and select and justify a handling option.`,`B6.3 (Apply) Maintain an AROU register that distinguishes assumptions, risks, opportunities and unknowns, each owned and linked, and keep issues apart from risks.`,`B6.4 (Evaluate) Review another team’s baseline against adapted SRR criteria and write actionable findings.`,`B6.5 (Understand) Explain definition versus usage, and attributes with units, in a SysML v2 fragment (micro-lab 2, online).`,`Graduate expectation: quantify one risk with an explicit probability model, compare the result with its ordinal 5×5 rating, and state what the comparison changes in your register.`],citations:[],provenance:`instructor-authored`},{id:`w6-intuition`,kind:`intuition`,title:`Intuition: a forecast is not a sprained ankle`,paragraphs:[`A weather forecast that gives a 30 % chance of a storm on the day of your race is a risk: the storm has not happened, it may not happen, and you can still act — move the start, pack a rain shell, buy event insurance. A sprained ankle the morning of the race is an issue: it has happened, its probability is one, and the only questions left are how bad it is and what you do now. Mixing the two produces bad decisions. Teams that log issues as risks report a “likely” event that is already costing them, and teams that log risks as issues spend money fixing things that may never occur.`,`Two more ideas complete the picture. Your plan rests on things you have not checked — that the course is the advertised length, that the shoe you ordered will arrive. Those are assumptions, and they quietly become risks when nobody checks them. And there are things you know you do not know yet — the start time has not been published. Those are unknowns, with a date by which you need the answer. AeroLink’s baseline is full of all four: an assumed charger maturity (A-003), a battery whose fade rate may erode the energy reserve (R-002), idle overnight chargers that could earn money (O-002), and aircraft weather limits nobody has published (U-001). This week turns those into a register an engineer can manage and a reviewer can check.`],citations:[],provenance:`instructor-authored`},{id:`w6-trl`,kind:`concept`,title:`Technology readiness levels: what they measure and what they do not`,paragraphs:[`SEBoK places technology readiness assessment (TRA) among the special activities of product systems engineering: as a system is developed, it must be shown to be mature enough for release, and TRAs qualify technology development and inform investment decisions so that technology reaches the user in time. The notion was formalised by NASA (Mankins 1995) and later adapted by the DoD, the Air Force Research Laboratory, the Department of Energy and a growing number of non-governmental organisations. A TRL summarises the degree of maturity of a technology on nine levels, from basic principles observed and reported (TRL 1) to an actual system proven through successful mission operations (TRL 9). The table below lists the nine level names of SEBoK Table 1 (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767).`,`SEBoK is explicit about the limits. TRLs help structure the life cycle and manage the risk, cost and schedule of technology, but they do not assess the programmatic influence on a TRL, technology criticality and priority, software aging or readiness context; and although they show how a technology performs in the laboratory or a test environment, they do not say whether it can be produced affordably — the reason manufacturing readiness levels (MRL) were added. TRLs apply to critical enabling technologies, usually at subsystem, assembly or component level; integration readiness levels (IRL) address interface maturity, and system readiness levels (SRL) are a function of the individual TRLs and their integration points. For commercial off-the-shelf products the TRL assessment changes dramatically if the operational environment or requirements exceed the product’s design limits, for example very high or low temperatures, shock or vibration (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767–768).`,`MITRE adds the practitioner’s view. Technology maturity follows an s-curve (new, improving, mature, aging), and the TRL scale is the most widely accepted way of assessing its upward slope; all versions rate a technology by the development, prototyping and testing completed across environments from the laboratory to operationally relevant. It is critical that stakeholders share a detailed understanding of terms such as “simulated environment”, “relevant environment” and “operational mission conditions”, which must be interpreted for the system under development, and the TRL scale does not address how well the technology fits the architecture that will absorb it. MITRE also warns against the hype cycle: a technology that attracts attention should be objectively assessed for maturity before significant investment is committed (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 524–525).`,`Maturity becomes a decision criterion when requirements depend on it. MITRE reports that DoD acquisition programs must assess threshold capabilities for maturity, and those that could only be met with immature technology — a TRL below six — are not considered further as threshold and may jeopardise the milestone decision; programs that deliberately inject developing technology must evaluate the risks carefully. In technology planning, technologies assessed as immature should be assigned appropriate risk with mitigation plans, and SEBoK notes that immature, risky technologies need risk-reduction activities — prototyping, development and test — that quantify their capabilities and risks (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 526, p.530; SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 770). The course turns this into a rule you will be graded on (RB-5.2): every TRL cites evidence or an explicitly labelled assumption, and every critical technology below TRL 6 has a maturity risk in the register.`],table:{caption:`The nine TRLs (level names from SEBoK Table 1, SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767) and the environment each implies (course reading of the names)`,header:[`TRL`,`Level name`,`Environment demonstrated`],rows:[[`1`,`Basic principles observed and reported`,`Paper study`],[`2`,`Technology concept and/or application formulated`,`Paper study`],[`3`,`Analytical and experimental critical function and/or characteristic proof of concept`,`Analysis and experiment`],[`4`,`Component validation in laboratory environment`,`Laboratory`],[`5`,`Component validation in relevant environment`,`Relevant (component)`],[`6`,`Prototype demonstration in a relevant environment`,`Relevant (prototype)`],[`7`,`Prototype demonstration in an operational environment`,`Operational (prototype)`],[`8`,`System qualified through test and demonstration`,`Qualification`],[`9`,`System proven through successful mission operations`,`Mission operations`]]},citations:[{reading:`R16`,pages:`766–770`},{reading:`R60`,pages:`524–526`},{reading:`R60`,pages:`530`}],provenance:`mixed`},{id:`w6-risk`,kind:`concept`,title:`Risk: definition, statement form and rating`,paragraphs:[`SEBoK defines risk as a measure of the potential inability to achieve overall program objectives within defined cost, schedule and technical constraints, and reports two internationally accepted definitions: the effect of uncertainty on objectives (where effects may be negative or positive), and the combination of the probability of occurrence of harm and the severity of that harm, which admits only negative effects and is used extensively in safety engineering. The long-established practice is to manage a set of individual risks, each characterised by the probability of failing to achieve a particular outcome and the consequence of that failure; the SE community refers to positive effects as opportunities. The DoD guidebook says the same in acquisition terms: risks are potential future events or conditions that may harm cost, schedule or performance objectives, defined by the undesired event or condition, its probability and its consequence; risk and issue management are closely related and use similar processes, and opportunity management is complementary (SEBoK v2.14, “Risk Management”, p. 481–482; OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 120, p.123).`,`A risk must be stated before it can be rated. SEBoK recommends structured descriptions — the if–then format (if an event occurs, then an outcome follows) or a condition that leads to a potential consequence. DoD asks for two elements, the potential event and its consequence, plus a third, the contributing circumstance or cause, when it is known. MITRE’s best practice combines them as condition–if–then. The condition is what is known today: the root cause, which has occurred, is occurring or will occur with certainty. The if is the uncertain risk event and carries the probability; the then is the consequence for the project if it occurs. Treating the condition and the if as a pair helps engineers see where to intervene on the root cause. MITRE adds two warnings: do not write the mitigation into the risk statement, and do not jump to a mitigation before probability and impact are assessed; statements are refined as understanding grows, for example by adding a need-by date (SEBoK v2.14, “Risk Management”, p. 483; OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 125; The MITRE Systems Engineering Guide, “Risk Identification”, p. 630–633).`,`Risk analysis estimates the likelihood and consequence of each risk and converts them into a risk level. SEBoK states that there is no best analysis approach: risk scales with a matrix, simulation and probabilistic risk assessment are used for technical risk, and a structured, repeatable method reduces uncertainty over time. Prioritisation is usually by risk level (low, medium, high), by the pair of probability and consequence values, and by time frame, frequency and interrelationships. DoD measures consequence as a deviation from the program’s performance, schedule or cost baseline, tailored to the program’s own thresholds, and enters approved risks into a register and a risk reporting matrix. Its Figure 4-9 example gives five likelihood levels with probability bands — not likely (> 1 % to ≤ 20 %), low likelihood (> 20 % to ≤ 40 %), likely (> 40 % to ≤ 60 %), highly likely (> 60 % to ≤ 80 %), near certainty (> 80 % to ≤ 99 %) — five consequence levels described for cost, schedule and performance, and a 5×5 matrix divided into low, moderate and high cells (SEBoK v2.14, “Risk Management”, p. 483–484; OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 125–126).`,`MITRE explains why the scales need care. Probabilities are often subjective because objective evaluation is not possible; the rationale for every impact and probability rating should be documented, because conditions change and the rationale communicates the risk’s significance; and criteria should be tailored to the decision. MITRE’s sample probability scale translates verbal phrases into probability ranges and puts a probability of exactly one in a separate category — an issue, certain to occur (The MITRE Systems Engineering Guide, “Risk Identification”, p. 635–637, p.639). The course adopts the DoD likelihood bands unchanged and a five-level AeroLink consequence scale adapted from the Figure 4-9 performance and schedule descriptions (shown in the risk-register activity); the probability horizon is the CP2 planning horizon, to month 24.`],table:{caption:`5×5 risk matrix as drawn in DoD Figure 4-9 (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126); MITRE’s handling-option figure uses the identical layout (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642). L = low, M = moderate, H = high.`,header:[`Likelihood (probability band)`,`C1`,`C2`,`C3`,`C4`,`C5`],rows:[[`5 Near certainty (> 80 % to ≤ 99 %)`,`L`,`M`,`H`,`H`,`H`],[`4 Highly likely (> 60 % to ≤ 80 %)`,`L`,`M`,`M`,`H`,`H`],[`3 Likely (> 40 % to ≤ 60 %)`,`L`,`L`,`M`,`M`,`H`],[`2 Low likelihood (> 20 % to ≤ 40 %)`,`L`,`L`,`L`,`M`,`M`],[`1 Not likely (> 1 % to ≤ 20 %)`,`L`,`L`,`L`,`L`,`M`]]},quote:{text:`The Condition reflects what is known today.`,cite:{reading:`R61`,pages:`630`}},citations:[{reading:`R17`,pages:`481–484`},{reading:`R46`,pages:`120–126`},{reading:`R61`,pages:`630–639`}],provenance:`mixed`},{id:`w6-treatment`,kind:`concept`,title:`Handling risks, monitoring them, and the AROU register`,paragraphs:[`SEBoK defines risk treatment as identifying, selecting and implementing the option that reduces a risk to an acceptable level within program constraints. The four options are assumption, avoidance, control (mitigation) and transfer; all four should be evaluated and the best chosen for each risk, a hybrid can combine options under one implementation approach, and a contingent strategy can be prepared to start when a trigger event occurs. When probabilities and impacts are too uncertain to choose, buying information — prototypes, benchmarking, surveys, modelling — clarifies the decision. DoD uses the same four (accepted and monitored, avoided, transferred or controlled), notes that control usually reduces likelihood while design or architecture changes can reduce consequence, lists mitigation examples such as risk-reduction prototyping, deferring capability, limiting the number of critical technologies and identifying off-ramps to mature technology, and asks the program manager to alert the next level of management when a high risk exceeds their authority or resources (SEBoK v2.14, “Risk Management”, p. 484; OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126).`,`MITRE adds watch/monitor as a fifth handling option and a general guideline keyed to the matrix: low cells suggest watch or assume, moderate and high cells suggest avoid, control or transfer — appropriate for many but not all programs. Accepting a risk is a deliberate decision that needs the approval of project or program leaders; avoiding it means adjusting requirements or constraints; transferring it reassigns accountability to another stakeholder willing to accept it, and MITRE calls transfer a double-edged sword because it creates dependencies and loss of control. Not every risk needs a mitigation plan: medium and high risks do, while some low risks can sit on a watch list. Every plan needs a risk manager with the knowledge, authority and resources to carry it out, actions with real exit criteria, and, for any high risk, a contingency plan with triggers and decision dates (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642–646).`,`Monitoring closes the loop. SEBoK describes risk monitoring as evaluating treatment effectiveness against established metrics, including technical performance measures, and lists pitfalls that this course will look for in your CP2: automatic mitigation selection without evaluating the alternatives; a “sea of green” in which treatment-plan activities look on track while the risk itself is untouched; band-aid treatment of symptoms rather than root causes; and risk management done only to satisfy reviews. Good practice is to understand the limitations of analysis tools, to try to reduce both probability and consequence, and to update the risk register at a regular interval and after major changes (SEBoK v2.14, “Risk Management”, p. 484–486).`,`The course register is broader than a risk list, and the sources support each of its parts. Assumptions: SEBoK lists key ground rules and assumptions as part of a risk management plan, and MITRE advises periodically revisiting the basic assumptions and premises of a risk (SEBoK v2.14, “Risk Management”, p. 482–483; The MITRE Systems Engineering Guide, “Risk Identification”, p. 644). Opportunities: SEBoK treats opportunity management as the dual of risk management — the probability and impact of an improved outcome — while warning that opportunities can carry risks of their own (SEBoK v2.14, “Risk Management”, p. 484–485). Unknowns are a course category, not a source term: an acknowledged information gap, such as a TBD in a requirement, with an owner, a resolution route and a need-by date (U-001, U-002). Issues are kept out of the register’s risk list because their probability is one (The MITRE Systems Engineering Guide, “Risk Identification”, p. 637); DoD manages risks and issues with related but separate processes (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 120). In this course an issue goes into the issue log of the register activity, with an owner role, the element it affects and the action being taken now, and CP2 lists the issues in their own table; any further, uncertain consequence of an issue becomes a separate risk that the issue log points to. In AeroLink’s register every entry has an owner and an affects link to the requirement, technology, capability, scenario or measure it threatens — the linkage RB-5.5 scores and the digital thread needs in Week 12.`],citations:[{reading:`R17`,pages:`482–486`},{reading:`R46`,pages:`120`},{reading:`R46`,pages:`126`},{reading:`R61`,pages:`637`},{reading:`R61`,pages:`642–646`}],provenance:`mixed`},{id:`w6-srr`,kind:`concept`,title:`The System Requirements Review and the course’s adapted criteria`,paragraphs:[`The DoD guidebook describes the SRR as a multi-disciplined technical review that ensures the developer understands the system requirements and is ready to proceed to initial system design. It assesses whether the requirements in the system performance specification are consistent with the preferred solution and with technology maturation plans, adequately consider the maturity of interdependent systems, and are clearly stated, measurable and testable; it also seeks a mutual understanding of the technical risk inherent in the specification. The systems engineer must ensure that requirements are traceable in both directions, that verification methods are identified for all of them, that risk items associated with them are identified and analysed with mitigation plans in place, and that interfaces to the system of systems are documented (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 69–70).`,`SRR criteria are developed to suit the program’s technical scope and risk and are tailored by the chief engineer; the system-level review should not begin until those criteria are met and earlier reviews’ action items are closed. The guidebook’s Table 3-2 groups the products and criteria under cost estimate, risk assessment, system performance specification and technical plans. Among them: technical risks identified and mitigation plans in place; requirements verifiable and achievable given the technology maturation plans; external and system-of-systems interfaces documented; bidirectional traceability documented; the specification approved with stakeholder concurrence and requirements conservative enough to allow design trade space; key technology elements identified, readiness assessed and maturation plans developed; and certifying agencies identified with certification requirements understood (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70–72).`,`Applying this to CP2 (course adaptation): AeroLink has no contract, cost estimate or developer, so the course keeps the criteria that test a requirements baseline and drops the rest, each for a stated reason. Dropped because CP2 has no cost estimate, contract or budget: the cost analysis, software development estimates and budget fit (p.71), the contractor’s engineering management plan, staffing, critical path, executable schedule, configuration management, manufacturing and production strategy, prototyping work requirements, draft test plans, sustainment, HSI and product-support plans (p.71–72), and the software criteria — component identification, development strategy, languages and sizing (p.71–72). Deferred to later weeks of the course rather than dropped: reliability and maintainability feasibility and R&M plans (p.71–72) to the architecture and verification weeks, the initial mission-based cyber risk assessment and its hazard review (p.71–72) to resilience in Week 13 (previewed in Session 1), and planning for models, simulation and a digital engineering ecosystem (p.72) to the SysML model of Weeks 9–12. Kept, because it is a requirements-baseline question and this week’s flagship risk is a battery fire: system safety hazards reviewed with mitigating courses of action allocated within the design (p.72), as criterion S9. The nine adapted criteria below are what reviewing teams score in the SRR-style checklist. Entry criteria for the course review mirror the guidebook: the CP2 package is posted 48 hours before Session 2 and the L5 audit response log shows every earlier finding closed or rejected with a reason. Week 2 showed that a gate can end in “continue this stage” as legitimately as “proceed” (SEBoK v2.14, “Life Cycle Stages”, p. 385); the checklist recommends one of proceed, proceed with actions, or not ready.`],bullets:[`S1 Requirements clear, measurable and testable (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 69, p.71).`,`S2 A verification method for every requirement (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70, p.72).`,`S3 Bidirectional traceability documented (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70–71).`,`S4 Requirements achievable given technology maturation; key technologies assessed (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 69, p.71–72).`,`S5 Technical risks identified, analysed and treated (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70–71).`,`S6 Interdependent systems and external interfaces considered (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 69–71).`,`S7 Certifying agencies and certification requirements identified (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 72).`,`S8 Measures and trade space: stakeholder concurrence, margins for design trade (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 71).`,`S9 Safety hazards reviewed and mitigating actions allocated within the design (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 72).`],citations:[{reading:`R40`,pages:`69–72`},{reading:`R06b`,pages:`385`}],provenance:`mixed`},{id:`w6-worked-trl`,kind:`worked-example`,title:`Worked example: TRL assessment of TECH-001..003, evidence versus assumption, and the lowest critical TRL`,paragraphs:[`Method (instructor-authored, built on SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767–768 and The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 525–526): (1) find the technologies the requirements actually depend on and mark them critical; (2) define what “relevant” and “operational” environment mean for each at AeroLink, because the TRL names are meaningless until those terms are fixed; (3) walk the scale from TRL 1 and stop at the first level that is not met — a level counts only when every lower level is also met; (4) record the basis: cited evidence, or a labelled assumption with an A-nnn ID, an owner and a validation action; (5) give every critical technology below TRL 6 a maturity risk; (6) report the lowest critical TRL and what it means for the baseline. The TRLs below are FICTIONAL reference values; none rests on evidence, because the course sources hold no supplier test data.`,`TECH-001, high-power charging, sets the 20-minute charge of REQ-SYS-001 and the hub turnaround capacity (CAP-003). Relevant environment: an operating vertiport with a representative grid connection and the hub’s ambient temperature range; operational environment: AeroLink revenue service at its own hubs. Assumption A-003 states that the supplier has demonstrated a prototype at an operating vertiport, so TRL 6 (prototype demonstration in a relevant environment); it is not TRL 7 because nothing has run in AeroLink’s operational environment. Two cautions apply. A-003 is owned by the Vertiport Infrastructure Manager and must be confirmed by the supplier test report before the charger order. And if AeroLink’s hubs are hotter than the charger’s design limits, SEBoK’s COTS warning applies and the TRL must be reassessed (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 768). At TRL 6 the course rule asks for no maturity risk. R-005 (a grid connection below charging demand) threatens the same capability, but it is an external-dependency risk about the utility, not about charger maturity; listing it as TECH-001’s “maturity risk” would let any related risk satisfy the rule.`,`TECH-002, battery cell technology, carries the landing energy reserve of REQ-SYS-003 and the block time of REQ-SYS-007. Assumption A-004 states that the cell has been validated at pack level under fast-charge cycling in a relevant environment: a component validation, so TRL 5. It is not TRL 6, because no prototype — an aircraft pack in representative service — has been demonstrated. Because TECH-002 is critical and below 6, it needs a maturity risk: R-002 (capacity fade erodes the 20 % reserve), watched through TPM-003. TECH-003, detect-and-avoid, rests on A-005 (laboratory validation only), so TRL 4. It is not critical to CP2, because the baseline operation is piloted; its maturity risk R-006 is accepted and reviewed at the Week 14 evolution decision.`,`The lowest critical TRL is therefore 5, held by TECH-002, not 4: TECH-003 is immature but nothing in the baseline depends on it. This is the number the reviewers should look at. An average of 6, 5 and 4 (5.0) would hide both facts — that one critical technology is below 6 and that the least mature one is irrelevant to the baseline. The engineering reasoning (instructor’s, consistent with SEBoK’s statement that SRL depends on the individual TRLs and their integration, SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 768) is that the system cannot be more ready than its least mature critical element. The consequences follow from the sources: requirements that rest on TRL 5 technology cannot yet be called achievable on demonstrated maturity (compare The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 526), the SRR expects a maturation plan for key technologies (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 72), and risk-reduction prototyping and test, or an off-ramp to a more mature cell, are the treatments DoD names (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126). One more finding belongs in AeroLink’s own SRR record: all three TRLs are assumed and none is evidenced.`],table:{caption:`Reference TRL assessment (FICTIONAL values; every TRL rests on a labelled assumption)`,header:[`Technology`,`Requirements that depend on it`,`TRL`,`Basis`,`Critical?`,`Maturity risk`,`What would raise it`],rows:[[`TECH-001 High-power charging`,`REQ-SYS-001, CAP-003`,`6`,`Assumption A-003`,`Yes`,`— (TRL ≥ 6; external dependency R-005)`,`Operation at an AeroLink hub (TRL 7)`],[`TECH-002 Battery cells`,`REQ-SYS-003, REQ-SYS-007`,`5`,`Assumption A-004`,`Yes`,`R-002 (capacity fade)`,`Prototype pack demonstrated in representative service (TRL 6)`],[`TECH-003 Detect-and-avoid`,`CAP-004 (autonomy increment only)`,`4`,`Assumption A-005`,`No`,`R-006 (accepted)`,`Component validation in a relevant environment (TRL 5)`],[`Summary`,`—`,`Lowest critical: 5`,`0 of 3 evidenced`,`2 critical`,`—`,`Confirm A-003 and A-004 before the fleet and charger orders`]]},citations:[{reading:`R16`,pages:`767–768`},{reading:`R60`,pages:`525–526`},{reading:`R40`,pages:`72`},{reading:`R46`,pages:`126`}],provenance:`mixed`},{id:`w6-worked-risks`,kind:`worked-example`,title:`Worked example: writing, rating and treating two risks (R-008 and R-004)`,paragraphs:[`Risk R-008 starts as a worry: “batteries might catch fire”. That sentence has no condition, no event that can be assigned a probability and no consequence that can be rated. Rewritten as condition–if–then (The MITRE Systems Engineering Guide, “Risk Identification”, p. 630–631): Condition — aircraft batteries are charged at high power on hub pads next to passengers and other aircraft (a fact today). If — a cell enters thermal runaway during charging (the uncertain event). Then — a fire can spread on the pad, injure people and close the vertiport (the consequence). Check the statement: the condition is certain, the if is uncertain, the then is a consequence for AeroLink, and no mitigation is written into it (The MITRE Systems Engineering Guide, “Risk Identification”, p. 633). R-008 is a safety risk in the sense of SEBoK’s second definition — the probability of harm combined with its severity (SEBoK v2.14, “Risk Management”, p. 481) — so the consequence is rated at its credible worst: C5 on the course scale (injury or vertiport closure), which matches the top performance level of DoD Figure 4-9, where the program’s success is in jeopardy (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126).`,`The reference register rates R-008 at likelihood 2 (20–40 % over the planning horizon) by judgement; the graduate example below shows why that number deserves a challenge. With L2 × C5 the cell is moderate, and MITRE’s guideline points to avoid, control or transfer (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642). All options were evaluated, as SEBoK asks (SEBoK v2.14, “Risk Management”, p. 484–485). Avoid: stop high-power charging at passenger pads — this removes the hazard from the passenger area but breaks the 20-minute charge of REQ-SYS-001 and the hub capacity, a trade Week 7 can examine. Transfer: insurance shifts the financial loss but not the injury or AeroLink’s accountability for safety, so transfer alone is inadequate. Control, chosen: cell-temperature monitoring stops charging before propagation (lowers the likelihood of escalation), pad fire detection alerts responders within 60 s (REQ-STK-008, REQ-SYS-009) and pad separation and suppression limit spread (lower the consequence) — SEBoK’s good practice of reducing both terms (SEBoK v2.14, “Risk Management”, p. 486). Owner: Vertiport Safety Manager. Trigger: a cell over-temperature alarm.`,`Risk R-004 is different in kind. Condition — the aircraft weather limits are unpublished (U-001). If — the approved limits are lower than the planning values — then weather holds exceed the planned 5 % of operating hours and delivered capacity falls below REQ-STK-004. Apply the course consequence scale literally: REQ-STK-004 is a stakeholder requirement on network capacity, and the C4 anchor reads “a stakeholder requirement … is missed; network capacity or service level is impaired”, so the consequence is C4, not the C3 of a system requirement missed at times. Rated L3 × C4 (likely; significant), the cell is moderate — the same level as R-005, whose missed turnaround (REQ-STK-005) is also C4, so the register is consistent. Avoid would mean relaxing REQ-STK-004, which the investors (STK-003) will not accept. Control here is mostly buying information — obtaining the OEM’s draft flight manual — which is the resolution action of U-001 rather than a treatment of R-004. Transfer, chosen: the aircraft purchase contract carries a performance guarantee on the weather envelope with compensation per lost operating hour, placing the financial consequence on the party able to manage the aircraft design. MITRE’s caution applies (The MITRE Systems Engineering Guide, “Risk Identification”, p. 644): transfer creates a dependency on the OEM and does not restore capacity for passengers, so the residual operational risk is recorded together with a contingent strategy — if the OEM’s draft limits fall below the planning values (the trigger), start a weather-routing study (contingent strategies, SEBoK v2.14, “Risk Management”, p. 484).`,`A third reference risk shows the remaining option. R-006 (detect-and-avoid will not reach TRL 6 before the autonomy increment) is rated L3 × C2, a low cell, where the guideline suggests watch or assume. It is accepted, because the piloted baseline does not depend on TECH-003; acceptance is a deliberate decision that needs approval by the program leaders (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642), so the register records who approved it and when it is re-examined (the Week 14 evolution decision). A register in which every risk is “mitigate” is the pitfall SEBoK calls automatic mitigation selection (SEBoK v2.14, “Risk Management”, p. 485).`],table:{caption:`Three reference risks rated and treated (ratings FICTIONAL)`,header:[`Risk`,`L`,`C`,`Cell`,`Options evaluated`,`Chosen`,`Why`],rows:[[`R-008 Thermal runaway during charging`,`2`,`5`,`Moderate`,`Avoid · transfer · control`,`Control`,`Only control reduces both the likelihood and the consequence of a safety risk without breaking REQ-SYS-001`],[`R-004 Weather limits lower than planned`,`3`,`4`,`Moderate`,`Avoid · control (information) · transfer`,`Transfer + contingent strategy`,`The OEM controls the envelope; residual capacity loss is watched through a trigger`],[`R-006 Detect-and-avoid not mature`,`3`,`2`,`Low`,`Accept · watch`,`Accept`,`The baseline does not depend on TECH-003; approved and re-examined in Week 14`]]},citations:[{reading:`R61`,pages:`630–633`},{reading:`R61`,pages:`642–644`},{reading:`R17`,pages:`481`},{reading:`R17`,pages:`484–486`},{reading:`R46`,pages:`126`}],provenance:`mixed`},{id:`w6-worked-quant`,kind:`worked-example`,title:`Worked example (graduate): an explicit probability model for R-008 compared with its 5×5 cell`,paragraphs:[`SEBoK names probabilistic risk assessment, decision trees and modelling and simulation among the quantitative methods and warns that their results are only as good as the model structure and the probability estimates (SEBoK v2.14, “Risk Management”, p. 483–484); MITRE lists probability distributions, expected-value analysis and modelling and simulation among the quantitative prioritisation techniques (The MITRE Systems Engineering Guide, “Risk Identification”, p. 636–637). The model below is deliberately simple — an exposure count, an initiating probability and an event tree — so that every assumption is visible. All rates are FICTIONAL. Exposure: 12 aircraft × 20 fast charges per aircraft per day × 360 operating days = 86,400 charging sessions a year, or 172,800 over the 24-month horizon. Initiation: each session independently starts a thermal runaway with probability p0 = 1 × 10⁻⁶. The number of initiations is then binomial, closely approximated by a Poisson count with mean λ = 172,800 × 10⁻⁶ = 0.1728, so P(at least one initiation in two years) = 1 − e^(−0.1728) = 0.159 (the exact binomial agrees to five decimal places).`,`Event tree: barrier B1, cell-temperature monitoring that stops charging before the runaway propagates, fails with probability 0.10; barrier B2, pad fire detection with responder alert within 60 s and suppression that contains the fire to the aircraft, fails with probability 0.20. Each initiation therefore ends in one of three outcomes: contained in the pack (0.90; one aircraft out of service, C3), aircraft fire contained (0.10 × 0.80 = 0.08; aircraft lost and pad closed for hours, C4), or fire spreading on the pad (0.10 × 0.20 = 0.02; possible injury and vertiport closure, C5). Over two years the expected numbers are 0.1555, 0.0138 and 0.00346, and the probabilities of at least one are 14.4 %, 1.37 % and 0.345 %.`,`Now compare with the ordinal rating. The reference register gives R-008 likelihood 2, which under the DoD bands means > 20 % to ≤ 40 % (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126). The model puts the C5 outcome at 0.35 % — below the lowest band, which starts above 1 % — and even “any thermal runaway at all” at 15.9 %, inside L1. Three lessons follow. First, the ordinal rating had silently mixed two events: the initiation (likely enough to feel like an L2) and the C5 outcome that set the consequence. Once the event and the horizon are explicit, the honest statement is that the C5 outcome lies below the scale: no DoD level contains 0.35 %. The register must still show a cell, so rate at the scale floor, L1, by convention, and record in the rationale that the model puts the event below the scale — L1 × C5 is still a moderate cell, so the report does not change, but the rationale does, and MITRE asks for the rationale to be documented (The MITRE Systems Engineering Guide, “Risk Identification”, p. 639). Second, resolution: improving B1 from 0.10 to 0.01 cuts the C5 frequency tenfold, to 0.035 %, yet the cell stays at the floor, L1 × C5; the matrix cannot show the value of that treatment, and the model can. Third, sensitivity: if p0 is ten times higher, any-initiation rises to 82 % (L5) while the C5 outcome reaches only 3.4 % (still L1). The rating of the initiating event is fragile; the rating of the outcome that matters is robust. That is the kind of challenge SEBoK asks analysts to put to their results (SEBoK v2.14, “Risk Management”, p. 486).`],table:{caption:`R-008 event tree over 24 months (all rates FICTIONAL); bands from DoD Figure 4-9 (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126)`,header:[`Outcome`,`Fraction of initiations`,`Expected events`,`P(at least one)`,`DoD band`,`Course consequence`],rows:[[`Any initiation`,`1`,`0.1728`,`15.9 %`,`L1 (> 1 % to ≤ 20 %)`,`—`],[`B1 holds: contained in the pack`,`0.90`,`0.1555`,`14.4 %`,`L1`,`C3`],[`B1 fails, B2 holds: aircraft fire contained`,`0.08`,`0.0138`,`1.37 %`,`L1`,`C4`],[`B1 and B2 fail: fire spreads on the pad`,`0.02`,`0.00346`,`0.345 %`,`Below the scale (≤ 1 %); floor L1 by convention`,`C5`],[`Same, with B1 improved to 0.01`,`0.002`,`0.000346`,`0.035 %`,`Below L1`,`C5`],[`Same as row 4, with p0 × 10`,`0.02`,`0.0346`,`3.40 %`,`L1`,`C5`]]},citations:[{reading:`R17`,pages:`483–486`},{reading:`R61`,pages:`636–639`},{reading:`R46`,pages:`126`}],provenance:`mixed`},{id:`w6-advanced`,kind:`advanced`,title:`Advanced analysis: what an ordinal matrix can and cannot tell you, and uncertainty beyond the register`,paragraphs:[`What the sources say about the matrix. SEBoK values the probability–consequence approach because it supports simple risk metrics and familiar visual aids such as the risk matrix, but adds that in practice a combination of methods is usually needed; there is no best analysis approach; a structured, repeatable methodology improves accuracy over time; and prioritisation uses the risk level or the pair of probability and consequence values together with time frame, frequency and interrelationships between risks (SEBoK v2.14, “Risk Management”, p. 482–483). Its good practices tell analysts to understand the limitations of their tools and to challenge results because input uncertainty and errors may be considerable (SEBoK v2.14, “Risk Management”, p. 486). DoD presents Figure 4-9 as an example and asks programs to tailor consequence criteria to their own thresholds (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 125–126), and MITRE calls its handling guideline appropriate for many but not all programs and asks for the rationale of every rating (The MITRE Systems Engineering Guide, “Risk Identification”, p. 639, p.642).`,`Instructor analysis, building on those statements. First, a matrix cell is an ordinal category: L3 is more likely than L2, but the numbers carry order, not magnitude. Multiplying them (2 × 5 = 10 against 3 × 3 = 9) produces a ranking the figure itself never claims — DoD and MITRE assign each cell a level, SEBoK describes prioritisation by level or by the pair of values, and none of these sources multiplies ordinal levels. Second, the DoD likelihood bands are each about 20 percentage points wide and the lowest starts above 1 %, so the scale cannot separate a 0.5 % catastrophic risk from a 0.005 % one; safety risks such as R-008 live exactly there, which is why the graduate model above found the matrix blind to a tenfold treatment benefit. Third, the bands only mean something once the event and the horizon are fixed; the Session 1 cross-team rating exercise usually shows that most disagreement comes from teams rating different events, not from different judgements about the same event.`,`Uncertainty is wider than the register. MITRE distinguishes external uncertainty (markets, operating environments, business processes, threats) from internal uncertainty (execution, design, implementation and performance), and contrasts classical systems engineering — “watchmaking” for bounded, well-understood problems — with engineering for the enterprise, which draws on adaptation and must increase the likelihood of favourable outcomes in environments that change unpredictably (The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 50–51). Its strategies map onto AeroLink: where a project is dominated by new technology, a “portfolio of small bets”; where requirements are evolving, “staged commitments”; a hybrid where both apply (The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 56); building options into designs (The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 53); and modelling and simulation to explore interactions people predict poorly (The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 55). MITRE adds that where “what to build” is fuzzy, it should be tightened in time or scope, and that a point of logical branching is an opportunity for real options, which suits interfaces whose details can be deferred (The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 56). Applied by the instructor: TECH-003 is small-bets territory — fund laboratory and relevant-environment trials without committing the baseline to them. The evolving requirement in AeroLink’s baseline is the capacity target REQ-STK-004, which will be revised as demand data arrive; that is where MITRE’s staged commitments fit, by adding aircraft and hub chargers in stages tied to each confirmed revision of the target. The unconfirmed grid connection (U-002, R-005) is not an evolving requirement but an external interface whose details can be deferred, so the closer source fit is the real-options advice; R-005’s avoid treatment — commit to a hub only when the utility confirms capacity — is consistent with it by analogy, not an application of the staged-commitment strategy itself.`,`Finally, maturity is wider than TRL. TRL says nothing about producibility (MRL), interface maturity (IRL) or system readiness (SRL), nor about how well a technology fits the architecture that absorbs it (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767–768; The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 525). The charging chain shows why this matters: TECH-001 at TRL 6, a grid connection that is still a U item, and a battery at TRL 5 that must accept the charger’s power are three separate maturity questions about one capability (CAP-003). Treat interrelated risks such as R-001, R-002 and R-005 together when prioritising, as SEBoK suggests, rather than as three independent cells.`],quote:{text:`Risk analysis results should be challenged because considerable input uncertainty and/or potential errors may exist.`,cite:{reading:`R17`,pages:`486`}},citations:[{reading:`R17`,pages:`482–486`},{reading:`R46`,pages:`125–126`},{reading:`R61`,pages:`639–642`},{reading:`R51`,pages:`50–56`},{reading:`R16`,pages:`767–768`},{reading:`R60`,pages:`525`}],provenance:`mixed`},{id:`w6-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`Defence acquisition makes maturity and risk explicit at every decision. The DoD guidebook requires program managers to present top program risks and their mitigation plans at all relevant decision points; independent technical risk assessments are conducted before Milestone A, Milestone B and production decisions; and the program’s risk profile is the dominant consideration in choosing a contract type — cost-plus when inherent technical risk is high, fixed-price only when requirements are stable and technical and technology risks are understood and minimal. A risk management board chaired by the program manager reviews risks, and government and contractor are encouraged to share one risk register. Where technology maturity, manufacturing maturity or requirements stability risks exist, programs enter the life cycle early to conduct technology maturation and risk reduction, for example with competitive prototypes (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 120–123).`,`For a commercial operator such as AeroLink, the same logic appears in different clothes (instructor application). R-004’s performance guarantee is a contract-type decision driven by risk: it only works if the OEM’s own technology risk is understood. Certification is the other aerospace constant: SEBoK names airworthiness certification as the best-known product certification, says certification agencies must be involved early so that certification is in the requirements, plan and funding, and that changes may require re-certification (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 769) — which is why the SRR asks whether certifying agencies are identified (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 72), why the regulator (STK-002) and the weather limits (U-001) sit in AeroLink’s register, and why TECH-003’s autonomy increment needs a certification basis before it can be planned. Technology planning ties it together: MITRE describes the technology plan as a living roadmap of maturation and insertion points, and asks that technologies in R&D for more than five years be assessed for their maturation trend before further investment (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 529–530). TECH-003’s insertion point is the Week 14 evolution decision.`],citations:[{reading:`R46`,pages:`120–123`},{reading:`R16`,pages:`769`},{reading:`R40`,pages:`72`},{reading:`R60`,pages:`529–530`}],provenance:`mixed`},{id:`w6-sysml`,kind:`concept`,title:`SysML micro-lab 2 (online): definition versus usage, specialization, and attributes with units`,paragraphs:[`Micro-lab 1 in Week 5 taught you to tell a definition from a usage and to find the type and the unit in a line. Micro-lab 2 asks you to explain them, on a fragment of AeroLink’s charging system adapted from the Physical package of the instructor reference skeleton. The listing aerolink_charging.sysml is written in the SysML v2 textual notation of the 2026-08 training material (Seidewitz, Intro to the SysML v2 Language: Textual Notation) and the SysML v2.1 Beta 2 specification (OMG SysML v2.1 Beta 2, Part 1), both pre-final texts, and the reference implementation (pilot release 2026-08) accepts it. Its values are FICTIONAL; the charger power and the pack energy are instructor values, not Data Sheet values.`,`Definition and usage. A definition classifies a certain kind of element; a usage is a usage of a definition in a certain context, and every usage is defined by at least one definition — explicitly after the colon, or implicitly by the most general library definition of its kind. Usages nested in a definition or usage are its features, and a usage placed directly in a package is a generic feature that can be specialized in specific contexts (OMG SysML v2.1 Beta 2, Part 1, p. 63–64). In the listing, Charger, HighPowerCharger, StandardCharger, BatteryPack, HubVertiport and ReadinessAssessment are definitions; hub1 and aircraftPack are package-level usages; chargers and turnaroundChargers are part usages nested in a definition and in a usage. A usage inherits the features of its definition in the same way that a specialized definition inherits from a general one, and it can add, subset or redefine them, so that each usage can be modified for its context (OMG SysML v2.1 Beta 2, Part 1, p. 64).`,`Three relationships look alike in the text and mean different things. Specialization of a definition is written :> or specializes: the specialized definition defines a subset of the classification of its general definition, inherits its features and can add its own; an abstract definition is one whose instances must be members of some specialization (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 10). Subsetting asserts that, in any common context, the values of one feature are a subset of the values of another (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 11). Redefinition, written :>> or redefines, replaces an inherited feature, for example to specialize its type, constrain its multiplicity (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 12) or bind it to a specific value (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 13, sl.15). In the listing, HighPowerCharger :> Charger is specialization; turnaroundChargers : HighPowerCharger[2] subsets chargers says that two of hub1’s chargers are high-power chargers; and attribute redefines ratedPower = 350 [kW] binds an inherited attribute for this one usage. Because Charger is abstract, every charger at a hub must belong to some specialization — in this listing, a high-power or a standard charger.`,`Attributes with units. An attribute definition defines a set of data values — numbers, quantitative values with units, text or structures of such values — and an attribute usage is always referential. Attribute usages can be typed by primitive data types such as Natural, String and Real, or by the quantity value types of the Quantities and Units library. The principle the micro-lab turns on is that only the kind of unit is associated with an attribute’s type, while the specific unit is given only with an actual value, so a model is independent of the unit chosen and values can be converted (OMG SysML v2.1 Beta 2, Part 1, p. 77). In the training material, a length value is a quantity value with a real magnitude and a length-unit scale, ISQ defines the quantity kinds, and SI declares units with their symbols, prefixed units such as kilogram, and derived units defined by arithmetic on other units, such as newton = kg * m / s ^ 2 (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 167–168). So ratedPower : PowerValue accepts 350 [kW] or 350000 [W], and usableEnergy : EnergyValue accepts 160 [kW * h] — kilowatt times hour, an energy — or 576 [MJ]. The TRL attribute trl : Natural takes no unit at all: a readiness level is an ordinal category, not a measured quantity, which is the same point the risk matrix made about likelihood levels.`,`Reading the listing and its limits (instructor commentary). Three reading points matter for engineering. First, connectionLimit is redefined in hub1 but deliberately left unbound, with a doc comment pointing to TBD-02 and U-002: the definition guarantees every hub has the feature; the usage records honestly that its value is not yet known. Second, the course’s check of a probe file found that the 2026-08 pilot implementation accepted ratedPower = 160 [kW * h] — an energy unit bound to a power type — with no diagnostic. Passing the tool shows the names resolve; it does not prove that the units match the quantity, so the reader still has to check. Third, the invalid listing below is the same charger fragment with one wrong line. Before reading on, find the error. The reference implementation reports “Couldn’t resolve reference to Feature ‘usableEnergy’” at line 16: spokeCharger is a usage of StandardCharger, which inherits only ratedPower and chargeTimeToDispatch from Charger, and a usage can redefine only features it has. Energy belongs to BatteryPack.`],sysml:[{file:`week06/aerolink_charging.sysml`,caption:`AeroLink charging — specialized charger definitions, a hub usage that subsets and redefines, and attributes with units (FICTIONAL values)`,intent:`conformant`},{file:`week06/invalid_usage_redefines_missing_feature.sysml`,caption:`Teaching listing: find the error (a usage redefines a feature its definition does not have)`,intent:`intentionally-invalid`}],citations:[{reading:`R80`,pages:`63–64`},{reading:`R80`,pages:`77`},{reading:`R70`,pages:`9–13`},{reading:`R70`,pages:`15`},{reading:`R79`,pages:`167–168`}],provenance:`mixed`},{id:`w6-lab`,kind:`lab`,title:`Lab L6 — TRL and AROU v2 (before class); live SRR-style review (in class)`,paragraphs:[`Before class, in teams: assess the three technologies with the TRL assessor and record them in your workspace; bring your AROU register to v2 with the register below (at least eight entries, at least four risks, at least one each of A, O and U, every risk condition–if–then, rated, owned, handled, treated and linked, and every element recorded with your initials and its provenance; issues go in the issue log, not in the risk list); post your CP2 package 48 hours before Session 2; then review the package of the team you are assigned with the SRR checklist. In class: each team has seven minutes — its baseline at a glance, the reviewers’ findings, and its response. Afterwards, disposition every finding you received and submit CP2.`],citations:[],provenance:`instructor-authored`},{id:`w6-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: CP2 Requirements Baseline (10 % of the course grade: RB-3 40 · RB-4 20 · RB-5 30 · RB-12 10), including the SRR review record you gave and the one you received with your responses. Individual: readiness quiz Q6, SysML micro-lab 2 (online: the reading activity and quiz items q6-16 to q6-18, B6.5), the review-notebook entry with a time log, and the graduate risk-quantification annex.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w6-act-trl`,title:`TRL assessor: walk the scale, state the basis, find the lowest critical TRL`,component:`w06-trl-assessor`,purpose:`Assess TECH-001..003 against the SEBoK TRL definitions with evidence or a labelled assumption, and see which technology bounds the baseline’s readiness.`,instructions:[`For each technology, answer the nine ladder questions from what is actually known; the tool computes the level your answers support.`,`Assign a TRL, state its basis (cited evidence, or an assumption with an A-nnn ID and its validation), and define “relevant environment” for AeroLink.`,`Mark whether the technology is critical to the baseline and give a maturity risk for any critical technology below TRL 6.`,`Check, compare with the instructor key, then record the assessment in your workspace with your initials and its provenance (AI-suggested-reviewed if an AI tool drafted the basis).`],objectives:[`B6.1`],inBlock:`w6-worked-trl`},{id:`w6-act-quant`,title:`Risk quantifier (graduate): event tree versus the 5×5 cell`,component:`w06-risk-quantifier`,purpose:`Build an explicit probability model for one risk, map its outcomes to the DoD likelihood bands and compare them with your ordinal rating.`,instructions:[`Start from the R-008 example, then replace it with the risk you chose for the graduate annex.`,`State exposures, initiating probability, horizon and up to three barriers; every number is FICTIONAL and must be labelled so.`,`Read the comparison line: does your ordinal likelihood match the model for the event that carries the consequence?`,`Use the sensitivity table to say which conclusion is robust and which is fragile.`],objectives:[`B6.2`],inBlock:`w6-worked-quant`},{id:`w6-act-srr`,title:`SRR-style review checklist`,component:`w06-srr-checklist`,purpose:`Review another team’s CP2 package against nine adapted SRR criteria and produce a review record with actionable findings and a recommendation.`,instructions:[`Rate each criterion met, partly met or not met from the evidence in the package.`,`For every rating below “met”, name the artefact by ID, state the defect against the criterion and request a specific change. The tool flags findings with no ID or no change, and common non-actionable patterns such as preferences (“we would …”) or “change everything”; it is a heuristic, so read each finding as a reviewer would.`,`Prioritise your three most important findings for the seven-minute slot.`,`Copy the review record into both teams’ CP2 packages.`],objectives:[`B6.4`],inBlock:`w6-srr`},{id:`w6-act-register`,title:`5×5 risk matrix and AROU register`,component:`w06-risk-register`,purpose:`Record and edit A/R/O/U entries in the shared AeroLink workspace, plot the risks on the 5×5 matrix with a table equivalent, and check the register against the CP2 minimums.`,instructions:[`Write risks as condition–if–then. The tool flags statements without a condition, an if and a then; statements that contain their own mitigation, including an “if” that is only the absence of a treatment; an “if” or “then” that has already happened (an issue — use the issue log); an “if” with no specific event; and a “then” that names nothing harmed. These are heuristics: a statement that passes can still be a poor risk.`,`Rate likelihood and consequence, read the cell level, and choose a handling option; a choice outside MITRE’s guideline is allowed but must be justified in the treatment.`,`Give every entry an owner role (the risk manager) and link it to the element it affects; record your own initials and the provenance (tag AI-drafted entries AI-suggested-reviewed).`,`Record anything that has already happened in the issue log below the register, not as a risk.`,`Use the completeness list as your L6 checklist; compare with the read-only reference register.`],objectives:[`B6.2`,`B6.3`],inBlock:`w6-lab`},{id:`w6-act-sysml`,title:`SysML micro-lab 2: explain definitions, usages, specialization and units in a validated listing`,component:`w06-sysml-microlab2`,purpose:`Classify the elements of aerolink_charging.sysml — including specialization, subsetting and types without units — and judge whether proposed value bindings use a unit of the right kind.`,instructions:[`Select each highlighted element in the listing and classify it; the feedback explains the answer from Seidewitz, Intro to the SysML v2 Language: Textual Notation and OMG SysML v2.1 Beta 2, Part 1.`,`Judge each proposed edit to the usages: does the unit belong to the kind of quantity the attribute is typed by, or is the attribute not a quantity at all?`,`Read the invalid listing in the lesson and name its error before reading the commentary.`],objectives:[`B6.5`],inBlock:`w6-sysml`}],lab:{id:`L6`,title:`TRL & AROU; SRR-style review`,setting:`team`,durationMinutes:75,objectives:[`B6.1`,`B6.2`,`B6.3`,`B6.4`],inputs:[`L5 record: requirements set (REQ-STK, REQ-SYS), audit response log, MOE/MOP/TPM hierarchy, trace table`,`AROU v1 from CP1 and the TBD/U items raised in Week 4`,`Technology descriptions TECH-001..003 (reference baseline; FICTIONAL)`,`TRL assessor, risk register and SRR checklist (this week)`,`Review assignment: team k reviews team k + 1 (team 8 reviews team 1)`],steps:[{title:`Before class — critical technologies`,detail:`List the requirements that depend on each of TECH-001..003 and mark which technologies are critical to the CP2 baseline. Define “relevant” and “operational” environment for each at AeroLink (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 525).`},{title:`Before class — TRL assessment`,detail:`Walk the TRL scale for each technology in the TRL assessor. Assign a TRL with cited evidence or a labelled assumption (A-nnn, owner, validation, need-by). Give every critical technology below TRL 6 a maturity risk. Record the three TECH items in the workspace and report the lowest critical TRL.`},{title:`Before class — AROU v2`,detail:`In the register: at least eight entries, at least four of them risks, at least one each of A, O and U. Every risk condition–if–then, rated on the 5×5 scales with a one-line rationale, owned, handled (all options considered) and treated with a trigger; every entry linked to the element it affects and recorded with the owner’s initials and its provenance. Record any issue (something that has already happened) in the issue log, not as a risk, and link any future consequence of it as a separate risk.`},{title:`Before class — post and prepare`,detail:`Post the CP2 package 48 h before Session 2 (entry criterion). Review the assigned team’s package with the SRR checklist; select your three most important findings and make each actionable (ID + requested change).`},{title:`In class — SRR-style review (8 × 7 min)`,detail:`Per slot: presenting team, baseline at a glance (2.5 min: REQ count, lowest critical TRL, top three risks, open U items); reviewing team, top findings against S1–S9 (3 min); presenting team, accept or reject each finding with a reason (1 min); instructor records the recommendation and changes over (0.5 min).`},{title:`After class — disposition and submit`,detail:`Disposition every finding received (accepted with change, or rejected with reason) in the audit response log, update the baseline and register, and submit CP2 with both review records.`}],artefacts:[{idPrefix:`TECH`,description:`Technology assessments with TRL, basis (evidence or A-nnn), relevant-environment definition, criticality and maturity risk`,minimum:`3 TECH, each citing evidence or an assumption ID`},{idPrefix:`A/R/O/U`,description:`AROU register v2: condition–if–then risks rated 5×5 with owner, handling, treatment and trigger; assumptions with validation; opportunities with action; unknowns with need-by`,minimum:`≥ 8 entries, ≥ 4 risks, ≥ 1 each of A, O and U; every entry owned and linked`},{idPrefix:`Review record`,description:`SRR-style review record given and received, with responses`,minimum:`9 criteria rated; every rating below “met” has an actionable finding`}],continuity:`CP2 is the baseline the rest of the course builds on. In Week 7 the trade study (DEC-001) uses the assumptions and unknowns as sensitivity drivers (A-006, U-002) and must say how each alternative changes the top risks (R-001, R-005). Week 8 allocates the requirements to an architecture whose interfaces inherit the external-interface findings of the SRR. In Weeks 9–12 the AROU entries become model elements and every complete digital thread ends in a risk that affects, or is mitigated by, an element of the thread (step 11); Week 13 revisits risks as SysML risk metadata in the impact analysis, and the Week 14 evolution decision reopens TECH-003 and the accepted risk R-006.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`CP2`,title:`CP2 Requirements Baseline (with SRR-style review record)`,mode:`team`,due:`Review package posted 48 h before Week 6 Session 2; final CP2 with both review records and responses by the end of Week 6`,weight:`CP2: 10 % of the course grade (team) — RB-3 40 · RB-4 20 · RB-5 30 · RB-12 10 (syllabus §12). Graduate annex: review notebook (RB-16, 5 %)`,instructions:[`Assemble the baseline from Weeks 4–6 into one package using the template below; every element keeps its course ID.`,`Minimum scope (syllabus §11): 15–20 REQ at stakeholder and system level, each with rationale, verification method and parent; ≥ 3 MOE, ≥ 5 MOP, ≥ 2 TPM with threshold and margin; a trace table; TRL for 3 TECH with evidence or a labelled assumption; AROU v2 with ≥ 8 entries, ≥ 4 of them risks, ≥ 1 each of A, O and U, rated on the 5×5 matrix.`,`Use the course scales: DoD likelihood bands (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126) and the AeroLink consequence scale in the risk-register activity; state the horizon (to month 24).`,`Take part in the live SRR-style review as presenting team and as reviewing team; include the record you gave and the record you received, and disposition every finding you received.`,`Graduate students (individually): add the risk-quantification annex — one risk of your choice, an explicit probability model with labelled FICTIONAL inputs, the comparison with its 5×5 rating, a sensitivity check, and what you changed in the register as a result.`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Baseline summary`,guidance:`One page: system of interest, number of requirements by level and type, lowest critical TRL, the top three risks by level, open TBD/U items with need-by dates, and what changed since CP1 and L5.`},{heading:`2. Requirements set (RB-3.1–3.5)`,guidance:`Table: ID, statement (one “shall”), type, rationale (why, not a restatement), verification method, parent (NEED/CAP or higher REQ), TBD with its U item where applicable. 15–20 requirements.`},{heading:`3. Audit response log (RB-3.6)`,guidance:`Every L5 audit finding and every SRR finding received: accepted (with the change made) or rejected (with the reason).`},{heading:`4. Trace table (RB-3.4)`,guidance:`Parent → child in both directions; list any orphan requirement and any childless NEED or CAP, with the action taken.`},{heading:`5. Measures hierarchy (RB-4.1–4.3)`,guidance:`MOE → MOP → TPM with linked NEED and REQ; for each TPM the threshold, current estimate, margin, and how and when it is measured. Say which TPMs watch which risks.`},{heading:`6. Technology maturity (RB-5.1–5.2)`,guidance:`For each TECH: description, benefits and limitations specific to AeroLink, requirements that depend on it, relevant-environment definition, TRL with cited evidence or a labelled assumption (A-nnn), criticality, maturity risk. State the lowest critical TRL and what it means for the baseline.`},{heading:`7. AROU register v2 and 5×5 matrix (RB-5.3–5.5)`,guidance:`Register table (ID, type, statement, owner, affects, L, C, cell level, handling, treatment, trigger / validation / action / need-by) and the matrix with its table equivalent. Risks condition–if–then with a one-line rating rationale; issues listed separately in their own table (copy the issue log); at least one handling choice other than control, justified.`},{heading:`8. SRR-style review records (B6.4)`,guidance:`The record you gave (nine criteria, actionable findings, recommendation) and the record you received, with your response to each finding cross-referenced to section 3.`},{heading:`9. Graduate annex: risk quantification (individual)`,guidance:`Model structure and assumptions; inputs labelled FICTIONAL with their basis; the calculation; mapping to the DoD bands; comparison with the ordinal rating; sensitivity; the register change you make. One to two pages.`},{heading:`10. AI usage statement (RB-12)`,guidance:`Tool, purpose, example prompts, outputs, your evaluation (what you accepted or rejected and why), and your own contribution; every AI-suggested requirement, risk or TRL basis individually reviewed and tagged AI-suggested-reviewed.`}],rubrics:[`RB-3`,`RB-4`,`RB-5`,`RB-12`,`RB-16`],rubricScope:`RB-3 in full (3.1–3.4 on a random sample of 10 requirements; 3.5 on the set; 3.6 on the L5 and SRR finding responses) · RB-4 in full · RB-5 in full (5.1–5.5) · RB-12.1–12.3 · graduate annex RB-16.1 (scored in the review notebook, not in CP2).`,aiUse:`AI tools may be used to critique requirement wording, suggest candidate risks or draft a first condition–if–then statement. Every AI-suggested entry is tagged AI-suggested-reviewed and individually checked (RB-12.3). AI output may not be cited as evidence for a TRL: a TRL needs a cited source document or a labelled assumption owned by a team member. The graduate model and its comparison must be the student’s own work.`,objectives:[`B6.1`,`B6.2`,`B6.3`,`B6.4`]},quiz:[{id:`q6-1`,bloom:`Apply`,objective:`B6.1`,prompt:`A charger supplier reports that a complete prototype charger passed all tests in its factory laboratory. AeroLink defines “relevant environment” as an operating vertiport with a representative grid connection. No other test is reported. What TRL can AeroLink assign, and on what basis?`,options:[{id:`a`,text:`TRL 6, because a prototype exists and has passed its tests`,correct:!1,explanation:`TRL 6 is prototype demonstration in a relevant environment. A factory laboratory is not the relevant environment AeroLink defined.`},{id:`b`,text:`TRL 4 (component validation in a laboratory environment), citing the supplier’s laboratory report as evidence; TRL 5 and 6 need validation in the relevant environment`,correct:!0,explanation:`Correct. The scale climbs by environment (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767), and the meaning of “relevant environment” must be fixed for the system (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 525). The laboratory report is evidence for TRL 4 only.`},{id:`c`,text:`TRL 7, because the prototype is the final design`,correct:!1,explanation:`TRL 7 requires prototype demonstration in an operational environment, which has not happened.`},{id:`d`,text:`No TRL can be assigned until the charger is in service`,correct:!1,explanation:`TRLs exist precisely to rate technologies before service; waiting for service would make the scale useless for planning.`}],cite:{reading:`R16`,pages:`767`}},{id:`q6-2`,bloom:`Evaluate`,objective:`B6.1`,prompt:`A team proposes a cargo-pod variant of the AeroLink aircraft. Its package rates four technologies: automated pad docking at TRL 7, pod latching at TRL 6, a rotor noise shield at TRL 5 and solid-state cells at TRL 3. The variant’s requirements depend on the first three; the solid-state cells are a research option for a later increment. The team concludes: “average TRL 5.25 — ready for SRR”. Which review comment is best?`,options:[{id:`a`,text:`Accept: an average above 5 shows the variant is past component validation`,correct:!1,explanation:`An average hides the least mature critical element, and the variant cannot be more ready than that element.`},{id:`b`,text:`Report the lowest critical TRL instead: 5, the noise shield. It needs a maturity risk and a maturation plan before the requirements that depend on it can be called achievable; the solid-state cells do not bound the variant’s readiness`,correct:!0,explanation:`Correct. MITRE reports that threshold capabilities resting on technology below TRL 6 are not treated as threshold (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 526), and immature technologies need assigned risk and mitigation plans (The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, p. 530). The TRL 3 cells are not critical to this variant.`},{id:`c`,text:`Reject the package because the solid-state cells are at TRL 3`,correct:!1,explanation:`The cells are a research option that no requirement of the variant depends on, so their low TRL does not set its readiness.`},{id:`d`,text:`Replace the average with the median (TRL 5.5), which is less sensitive to the research option`,correct:!1,explanation:`Any central value still hides the weakest critical technology; the question is which critical technology is least mature, not what is typical.`}],cite:{reading:`R60`,pages:`526`}},{id:`q6-3`,bloom:`Apply`,objective:`B6.1`,prompt:`AeroLink considers an off-the-shelf charger that has been in service for years in a temperate city (assessed at TRL 9 there). AeroLink’s southern hub regularly exceeds the charger’s rated ambient temperature. What should the assessment say?`,options:[{id:`a`,text:`TRL 9 carries over: the product is proven in operations`,correct:!1,explanation:`SEBoK warns that a COTS TRL changes dramatically if the operational environment exceeds the product’s design limits.`},{id:`b`,text:`Reassess the TRL for AeroLink’s environment, because operation beyond the design limits (e.g. very high temperatures) invalidates the earlier rating; record the gap as a maturity risk or an assumption to be tested`,correct:!0,explanation:`Correct. This is SEBoK’s COTS caution (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 768); the earlier evidence was gathered in a different environment.`},{id:`c`,text:`Lower the TRL to 1, because nothing is known`,correct:!1,explanation:`Much is known; the principles, concept and component validation still hold. The question is which environment-dependent levels remain evidenced.`},{id:`d`,text:`Ignore temperature; TRL concerns technology, not environment`,correct:!1,explanation:`Environment is the axis the TRL scale climbs along (laboratory, relevant, operational).`}],cite:{reading:`R16`,pages:`768`}},{id:`q6-4`,bloom:`Understand`,objective:`B6.1`,prompt:`Which question does a TRL assessment of the battery cell (TECH-002) NOT answer, according to SEBoK?`,options:[{id:`a`,text:`Whether the cell has been validated in a relevant environment`,correct:!1,explanation:`That is exactly what TRL 5 rates.`},{id:`b`,text:`Whether the cell can be produced affordably at the volume AeroLink needs`,correct:!0,explanation:`Correct. TRLs do not say whether a technology can be produced affordably; manufacturing readiness levels were introduced for producibility (SEBoK v2.14, “Product Systems Engineering Special Activities”, p. 767).`},{id:`c`,text:`How far the cell has progressed from concept to demonstration`,correct:!1,explanation:`That progression is what the nine levels summarise.`},{id:`d`,text:`Whether a prototype has been demonstrated`,correct:!1,explanation:`TRL 6 and 7 rate prototype demonstration.`}],cite:{reading:`R16`,pages:`767`}},{id:`q6-5`,bloom:`Apply`,objective:`B6.2`,prompt:`Which statement is a well-formed condition–if–then risk about winter operations at AeroLink’s hubs?`,options:[{id:`a`,text:`“Icing risk in winter.”`,correct:!1,explanation:`A title, not a statement: no condition, no uncertain event, no consequence.`},{id:`b`,text:`“Condition: winter departures are planned before sunrise. If we do not buy rotor heaters, then ice will form.”`,correct:!1,explanation:`The “if” is the absence of a treatment, so the mitigation has been written into the statement (The MITRE Systems Engineering Guide, “Risk Identification”, p. 633). The uncertain event is the weather, not the purchase.`},{id:`c`,text:`“Condition: the winter timetable schedules the first departures before sunrise, when hub temperatures are often near freezing, and the aircraft is not approved for flight in icing. If freezing fog forms at a hub on more than 10 mornings in the season, then the first departure wave is held on those mornings and the morning capacity required by REQ-STK-004 is not delivered.”`,correct:!0,explanation:`Correct. The condition is a present fact (the root cause), the “if” is an uncertain event that can be given a probability, and the “then” names the consequence for AeroLink (The MITRE Systems Engineering Guide, “Risk Identification”, p. 630–631).`},{id:`d`,text:`“Two departures were held for frost on Monday and the first wave ran 40 min late.”`,correct:!1,explanation:`This has already happened: probability one, so it is an issue to manage now (The MITRE Systems Engineering Guide, “Risk Identification”, p. 637), not a risk.`}],cite:{reading:`R61`,pages:`630–633`}},{id:`q6-6`,bloom:`Apply`,objective:`B6.2`,prompt:`The team estimates a 30 % chance, before month 24, that a charger firmware update will lengthen the charge to dispatch beyond the 20 min of a system requirement on some days. A second charger can be used as a workaround, and no stakeholder requirement or milestone would be missed. Using the DoD likelihood bands and the course consequence scale, which rating and cell are correct?`,options:[{id:`a`,text:`L2 × C3 — low`,correct:!0,explanation:`Correct. 30 % lies in the “low likelihood” band (> 20 % to ≤ 40 %, OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126). A system requirement missed at times with a workaround is C3 on the course scale. Row L2 of Figure 4-9 reads L L L M M, so L2 × C3 is low, where MITRE’s guideline suggests watch or assume (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642).`},{id:`b`,text:`L2 × C4 — moderate`,correct:!1,explanation:`C4 on the course scale is a stakeholder requirement or a milestone missed, or network capacity impaired; the prompt rules these out.`},{id:`c`,text:`L3 × C3 — moderate`,correct:!1,explanation:`30 % is not in the “likely” band, which is > 40 % to ≤ 60 %.`},{id:`d`,text:`L2 × C3 — score 6, moderate`,correct:!1,explanation:`Figure 4-9 assigns a level to each cell; it does not multiply ordinal numbers, and L2 × C3 is a low cell.`}],cite:{reading:`R46`,pages:`126`}},{id:`q6-7`,bloom:`Evaluate`,objective:`B6.2`,prompt:`A team’s risk reads: “Condition: spoke vertiport 5 stands on leased land. If the landlord does not renew the lease at month 18, then the vertiport closes and its routes stop.” It is rated L2 × C5, a moderate cell, and handled “accept” with no further text. What is the best review comment?`,options:[{id:`a`,text:`Fine: a 20–40 % chance is low, and low risks may be accepted`,correct:!1,explanation:`The likelihood is low, but the cell is moderate. For moderate cells MITRE’s guideline is avoid, control or transfer (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642).`},{id:`b`,text:`For a moderate cell the guideline points to avoid, control or transfer. If the team still accepts, the register must show a deliberate decision approved by the program leaders and its rationale, and the other options — for example negotiating a longer lease now, or preparing an alternative site with a trigger date — should be evaluated and recorded`,correct:!0,explanation:`Correct. Acceptance is a deliberate decision that needs leadership approval (The MITRE Systems Engineering Guide, “Risk Identification”, p. 642), and all options should be evaluated rather than one chosen by default (SEBoK v2.14, “Risk Management”, p. 484).`},{id:`c`,text:`Lower the consequence to C4 so that acceptance fits the guideline`,correct:!1,explanation:`Changing a rating to fit a preferred handling option reverses the process; ratings follow evidence and a documented rationale (The MITRE Systems Engineering Guide, “Risk Identification”, p. 639).`},{id:`d`,text:`Transfer is always best for property risks`,correct:!1,explanation:`No option is always best; MITRE calls transfer double-edged because it creates dependencies and loss of control (The MITRE Systems Engineering Guide, “Risk Identification”, p. 644).`}],cite:{reading:`R61`,pages:`642`}},{id:`q6-8`,bloom:`Evaluate`,objective:`B6.2`,prompt:`Graduate model for a different risk: a bird strike on approach damages a rotor. FICTIONAL inputs: 30,000 approaches a year at the spoke vertiports over a 2-year horizon; each approach initiates a strike with probability 5 × 10⁻⁶; a rotor-damage detection barrier fails with probability 0.05, and only then is the outcome severe (C5). The register rates the risk L3 × C5, a high cell. Which conclusion is best?`,options:[{id:`a`,text:`Any strike has a 25.9 % chance over the horizon, so rate the risk L2 × C5`,correct:!1,explanation:`This mixes two events: 25.9 % is the chance of any strike, but C5 belongs only to the severe outcome, whose expected count is 60,000 × 5 × 10⁻⁶ × 0.05 = 0.015.`},{id:`b`,text:`L3 (> 40 % to ≤ 60 %) is not supported. Any strike is about 26 % (L2), and the severe outcome that carries C5 is about 1.5 % (L1). Rate the event that carries the consequence — L1 × C5, a moderate cell rather than a high one — document the rationale, and challenge the inputs before the report changes`,correct:!0,explanation:`Correct. λ = 60,000 × 5 × 10⁻⁶ = 0.3, so P(any) = 1 − e^(−0.3) ≈ 25.9 %; the severe λ is 0.015, so P ≈ 1.49 %, inside L1 (> 1 % to ≤ 20 %, OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 126). The cell changes, so the rationale must be documented (The MITRE Systems Engineering Guide, “Risk Identification”, p. 639) and the inputs challenged (SEBoK v2.14, “Risk Management”, p. 486).`},{id:`c`,text:`Keep L3 × C5: an ordinal rating reflects expert judgement, and a model cannot override it`,correct:!1,explanation:`SEBoK asks for analysis results to be challenged (SEBoK v2.14, “Risk Management”, p. 486); neither the rating nor the model is right by definition, and here the rating does not match any stated event.`},{id:`d`,text:`Delete the risk: 1.5 % is negligible`,correct:!1,explanation:`A severe outcome with a non-zero probability stays in the register; the model only changes its rating and rationale.`}],cite:{reading:`R17`,pages:`484`}},{id:`q6-9`,bloom:`Analyse`,objective:`B6.2`,prompt:`AeroLink transfers the risk of hub charger downtime to the charger supplier: a service-level agreement pays AeroLink a penalty for every hour a hub charger is unavailable. What does this transfer leave unresolved?`,options:[{id:`a`,text:`Nothing: the supplier now owns the risk`,correct:!1,explanation:`Transfer reassigns accountability only for what is transferred; MITRE calls it a double-edged sword (The MITRE Systems Engineering Guide, “Risk Identification”, p. 644).`},{id:`b`,text:`A dependency on the supplier, and the operational consequence: penalty payments do not restore turnaround capacity for passengers, so the residual risk stays in the register with a trigger (for example hub charger availability below a threshold) and a contingent action`,correct:!0,explanation:`Correct. Transfer creates dependencies and loss of control (The MITRE Systems Engineering Guide, “Risk Identification”, p. 644), and a contingent strategy can be prepared to start on a trigger (SEBoK v2.14, “Risk Management”, p. 484).`},{id:`c`,text:`The likelihood, which a penalty clause always increases`,correct:!1,explanation:`A penalty changes who bears the financial consequence; it does not by itself change how likely a charger is to fail.`},{id:`d`,text:`The consequence scale, which must now be measured in money only`,correct:!1,explanation:`Compensation changes who pays, not what passengers experience; the consequence is still rated on the course’s performance and service anchors.`}],cite:{reading:`R61`,pages:`644`}},{id:`q6-10`,bloom:`Apply`,objective:`B6.3`,prompt:`Classify the four entries for AeroLink’s register: (1) “Hub chargers are idle about 8 h a night; if leased to municipal fleets, then charger capital is recovered faster.” (2) “The utility has not confirmed the connection capacity at the hubs; needed before the Week 7 trade study.” (3) “The supplier has demonstrated a prototype charger at an operating vertiport; to be confirmed by its test report.” (4) “Condition: the cells are fast-charged 20 times a day. If capacity fades more than 10 % before pack replacement, then the reserve cannot be held.”`,options:[{id:`a`,text:`(1) opportunity, (2) unknown, (3) assumption, (4) risk`,correct:!0,explanation:`Correct. (1) is a possible improved outcome — the dual of a risk (SEBoK v2.14, “Risk Management”, p. 484); (2) is an acknowledged gap with a need-by; (3) is believed but unconfirmed — an assumption to validate; (4) is condition–if–then with an adverse consequence.`},{id:`b`,text:`All four are risks`,correct:!1,explanation:`This is the “AROU = a risk list” misconception: (1) is positive, (2) is missing information, (3) is a premise that needs validation.`},{id:`c`,text:`(1) risk, (2) issue, (3) evidence, (4) risk`,correct:!1,explanation:`(2) has not occurred and is not certain to harm the project; (3) is unconfirmed, so it cannot count as evidence.`},{id:`d`,text:`(1) opportunity, (2) risk, (3) evidence, (4) issue`,correct:!1,explanation:`(3) is explicitly “to be confirmed”, so it is an assumption; (4) has not occurred, so it is a risk, not an issue.`}],cite:{reading:`R17`,pages:`484`}},{id:`q6-11`,bloom:`Analyse`,objective:`B6.3`,prompt:`A team’s AROU v2 has nine entries, all of them risks, every one handled “mitigate”. Its TRLs rest on “supplier statements” with no IDs. What is the most important register finding?`,options:[{id:`a`,text:`None: nine risks exceed the minimum of four`,correct:!1,explanation:`Counts are met but the register lacks the other three types and the assumptions behind the TRLs.`},{id:`b`,text:`The register is a risk list: the assumptions under the TRLs must be recorded as A items with owners and validation, at least one opportunity and one unknown are missing, and “mitigate” for every risk suggests automatic mitigation selection`,correct:!0,explanation:`Correct. Key assumptions belong in risk management planning (SEBoK v2.14, “Risk Management”, p. 482–483), MITRE asks for assumptions to be revisited (The MITRE Systems Engineering Guide, “Risk Identification”, p. 644), and SEBoK names automatic mitigation selection as a pitfall (SEBoK v2.14, “Risk Management”, p. 485).`},{id:`c`,text:`The register should drop risks below the moderate level`,correct:!1,explanation:`Low risks can stay on a watch list (The MITRE Systems Engineering Guide, “Risk Identification”, p. 645); deleting them loses visibility.`},{id:`d`,text:`Assumptions should be kept out of the register because they are not uncertain`,correct:!1,explanation:`Assumptions are uncertain by definition — they are believed, not verified — and become risks when nobody checks them.`}],cite:{reading:`R17`,pages:`482–485`}},{id:`q6-12`,bloom:`Apply`,objective:`B6.3`,prompt:`During trial operations the charger at hub 2 has tripped three times and turnaround has already exceeded 25 min on two days. How should this be entered?`,options:[{id:`a`,text:`As a risk rated L5 (near certainty)`,correct:!1,explanation:`L5 is > 80 % to ≤ 99 %. Something that has happened has probability one.`},{id:`b`,text:`As an issue (probability one), managed now with a root-cause analysis; any future consequence it creates, such as a capacity shortfall at peak, can be written as a separate risk`,correct:!0,explanation:`Correct. MITRE’s probability scale puts “certain to occur” (1.00) in a separate category, the issue (The MITRE Systems Engineering Guide, “Risk Identification”, p. 637); DoD manages risks and issues with related but separate processes (OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 120).`},{id:`c`,text:`As an opportunity to learn`,correct:!1,explanation:`Learning is welcome, but the event is a present problem with consequences.`},{id:`d`,text:`It need not be recorded until a third day exceeds 25 min`,correct:!1,explanation:`An issue affecting a requirement (REQ-STK-005) must be recorded and owned now, in the issue log.`}],cite:{reading:`R61`,pages:`637`}},{id:`q6-13`,bloom:`Evaluate`,objective:`B6.4`,prompt:`Which SRR finding is actionable for the team that receives it?`,options:[{id:`a`,text:`“Requirements need more work.”`,correct:!1,explanation:`No artefact, no criterion, no requested change.`},{id:`b`,text:`“Risk management looks weak overall.”`,correct:!1,explanation:`A judgement without evidence or a requested change.`},{id:`c`,text:`“S2 partly met: REQ-SYS-003 has no verification method. Add analysis of the energy budget with end-of-life capacity, and link it to TPM-003.”`,correct:!0,explanation:`Correct. It names the criterion, the artefact by ID and a specific change, matching the SRR expectation that verification methods are identified for all requirements (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70).`},{id:`d`,text:`“We would have done it differently.”`,correct:!1,explanation:`Preference is not a finding; findings test the baseline against agreed criteria.`}],cite:{reading:`R40`,pages:`70`}},{id:`q6-14`,bloom:`Evaluate`,objective:`B6.4`,prompt:`In the review, a team’s requirement that the operations centre assign an aircraft to 99 % of ride requests within 60 s depends on an AI dispatch optimiser. The team marks the optimiser critical and assesses it at an assumed TRL 4. The package has no maturity risk and no maturation plan for it. Which adapted SRR criterion is not met, and what recommendation fits?`,options:[{id:`a`,text:`S2 (verification) — proceed`,correct:!1,explanation:`The defect is achievability given technology maturity, not the verification method.`},{id:`b`,text:`S4 (requirements achievable given technology maturation) — not met; recommend “not ready” for this criterion until a maturity risk and a maturation plan for the optimiser are added, or the requirement is re-based on a mature dispatch method`,correct:!0,explanation:`Correct. The SRR asks whether requirements can be met given the plans for technology maturation, and whether key technology elements have readiness assessed and maturation plans developed (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 71–72).`},{id:`c`,text:`S9 (hazards) — proceed with actions`,correct:!1,explanation:`Nothing in the finding concerns a safety hazard; the gap is technology maturity.`},{id:`d`,text:`No criterion applies: software maturity is assessed only at design reviews`,correct:!1,explanation:`Key technology elements, readiness and maturation plans are explicitly SRR criteria in the DoD table (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 72).`}],cite:{reading:`R40`,pages:`71–72`}},{id:`q6-15`,bloom:`Apply`,objective:`B6.4`,prompt:`Two days before Session 2 a team has not closed four L5 audit findings and its CP2 package is not yet posted. Following the DoD guidance on SRR entry, what should happen?`,options:[{id:`a`,text:`Hold the review anyway; the schedule is fixed`,correct:!1,explanation:`The guidebook says the review should not begin until its criteria are met and earlier action items are closed.`},{id:`b`,text:`Entry criteria are not met: the team must post the package and close or disposition the L5 findings before its slot; otherwise its review is recorded as not ready and rescheduled`,correct:!0,explanation:`Correct. The system-level SRR should not begin until the criteria are met and prior technical reviews are complete with action items closed (OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review”, p. 70).`},{id:`c`,text:`Skip the L5 findings; the SRR replaces the audit`,correct:!1,explanation:`The audit response log is part of CP2 (RB-3.6); open findings are exactly what entry criteria guard against.`},{id:`d`,text:`Let the reviewing team review the L5 version instead`,correct:!1,explanation:`Reviewing an outdated baseline wastes the review and produces findings that may already be closed.`}],cite:{reading:`R40`,pages:`70`}},{id:`q6-16`,bloom:`Understand`,objective:`B6.5`,prompt:`Read this fragment (same notation as the micro-lab listing; FICTIONAL value): part def Aircraft { attribute cruiseSpeed : SpeedValue; }  part def CargoAircraft :> Aircraft { attribute payloadMass : MassValue; }  part freighter1 : CargoAircraft { attribute redefines payloadMass = 350 [kg]; }. Which explanation is correct?`,options:[{id:`a`,text:`CargoAircraft is a specialized definition: it inherits cruiseSpeed from Aircraft and adds payloadMass. freighter1 is a usage defined by CargoAircraft, so it has both features, and in this usage payloadMass is bound to a value with a unit`,correct:!0,explanation:`Correct. A specialized definition inherits the features of its general definition and can add its own (OMG SysML v2.1 Beta 2, Part 1, p. 64; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 10); a usage inherits the features of its definition and can redefine them for its context (OMG SysML v2.1 Beta 2, Part 1, p. 64).`},{id:`b`,text:`freighter1 is a third definition, because it has a body in braces`,correct:!1,explanation:`A definition is declared with the def keyword; freighter1 has none. Usages can have bodies too.`},{id:`c`,text:`freighter1 has payloadMass but not cruiseSpeed, because cruiseSpeed is declared only in Aircraft`,correct:!1,explanation:`CargoAircraft inherits cruiseSpeed through specialization, and freighter1 inherits it from CargoAircraft.`},{id:`d`,text:`Every CargoAircraft now carries 350 kg, because the value is bound in the model`,correct:!1,explanation:`The binding is a redefinition inside the usage freighter1; the definition CargoAircraft still says only that payload is a mass.`}],cite:{reading:`R80`,pages:`63–64`}},{id:`q6-17`,bloom:`Understand`,objective:`B6.5`,prompt:`BatteryPack declares attribute maxChargePower : PowerValue;. A teammate edits a pack usage to read attribute redefines maxChargePower = 90 [kW * h]; and says: “the SysML check passed, so the units are fine”. Which explanation is best?`,options:[{id:`a`,text:`The teammate is right: a file that passes the reference implementation has consistent units`,correct:!1,explanation:`The course’s check found that the 2026-08 pilot implementation accepts an energy unit bound to a PowerValue attribute without a diagnostic. Passing shows that names resolve; it does not prove that units fit.`},{id:`b`,text:`PowerValue fixes the kind of quantity, power; kW × h is an energy, so the value carries a unit of the wrong kind even though the file passes. The unit is given only with the value, so the reader must check it against the type`,correct:!0,explanation:`Correct. Only the kind of unit is associated with the type; the specific unit comes with the value (OMG SysML v2.1 Beta 2, Part 1, p. 77), and kW * h is a derived unit of energy (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 168).`},{id:`c`,text:`The type should become EnergyValue, because the unit decides the type`,correct:!1,explanation:`The type states what the attribute means (a charge power); the value, not the type, is wrong here.`},{id:`d`,text:`The error is that a unit may not be written as an expression of other units`,correct:!1,explanation:`Derived units can be defined by arithmetic on other units (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 168); kW * h is a legitimate energy unit.`}],cite:{reading:`R80`,pages:`77`}},{id:`q6-18`,bloom:`Understand`,objective:`B6.5`,prompt:`A cabin model reads: abstract part def Seat;  part def CrewSeat :> Seat;  part def PassengerSeat :> Seat;  part def Cabin { part seats : Seat[5]; }. What does abstract tell you about the five seats of every cabin?`,options:[{id:`a`,text:`Each of the five seats must belong to some specialization of Seat — in this model, a crew seat or a passenger seat`,correct:!0,explanation:`Correct. An abstract definition is one whose instances must be members of some specialization (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 10).`},{id:`b`,text:`A cabin may have no seats, because an abstract part cannot exist`,correct:!1,explanation:`The multiplicity [5] requires five seats; abstract constrains what kind of seat each one is, not whether it exists.`},{id:`c`,text:`Seat has no features, because abstract definitions cannot own attributes`,correct:!1,explanation:`Abstract definitions can own features, which their specializations inherit.`},{id:`d`,text:`The seats are only drawn on diagrams and are not part of the model`,correct:!1,explanation:`Abstract is about classification; the seats are part usages of Cabin like any other.`}],cite:{reading:`R70`,pages:`10`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min: concept studio; live SRR-style review and debrief)`,hours:2.5},{activity:`Online direct instruction and the four TRL, risk and review activities`,hours:.8},{activity:`Core readings SEBoK v2.14, “Product Systems Engineering Special Activities”, The MITRE Systems Engineering Guide, “Assessing Technical Maturity”, SEBoK v2.14, “Risk Management”, OUSD(R&E) Systems Engineering Guidebook, “Risk Management Process”, p. 120–126, OUSD(R&E) Systems Engineering Guidebook, “3.2 System Requirements Review” and The MITRE Systems Engineering Guide, “Risk Identification”, p. 630–646 (48 pp at ≈ 15 pp/h)`,hours:3.2},{activity:`Readiness quiz Q6 / knowledge check (18 items)`,hours:.3},{activity:`SysML micro-lab 2, online: Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 9–13 and 167–168 with the listings, and the reading activity (B6.5)`,hours:.5},{activity:`L6 before class: TRL, AROU v2, CP2 assembly and review preparation (team share; under-budgeted, see cautions)`,hours:1.4},{activity:`Graduate risk-quantification annex: The MITRE Systems Engineering Guide, “Uncertainty and Complexity”, p. 50–56 (≈ 0.5 h), model, sensitivity and the 1–2 page write-up`,hours:2},{activity:`Review notebook entry, time log and AI statement`,hours:.3}],references:[{reading:`R61`,pages:`630–646`},{reading:`R51`,pages:`50–56`},{reading:`R06b`,pages:`385`},{reading:`R70`,pages:`9–15`},{reading:`R79`,pages:`167–168`},{reading:`R80`,pages:`63–64`},{reading:`R80`,pages:`77`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},h=e({default:()=>g}),g={week:7,drivingQuestion:`AeroLink must reach 300 trips a day by month 24. More aircraft, more vertiports, or both? How do you turn minutes, dollars, percentages and community noise into one defensible recommendation — and how do you show the board exactly how far its own judgements would have to move before the answer changed?`,blocks:[{id:`w7-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcome B-CLO3 (evaluate alternatives under uncertainty) and, through the recommendation, to B-CLO6. It closes Part I of the course: the stakeholders, needs, requirements, measures and risks you built in Weeks 1–6 now become the inputs to a decision. Session 2 is Exam 1 (Weeks 1–6), so Lab L7 is completed out of class.`],bullets:[`B7.1 (Apply) Structure a trade study: a decision statement, alternatives including a baseline, criteria traced to MOEs, and value scales.`,`B7.2 (Apply) Elicit swing weights and compute additive value.`,`B7.3 (Analyse) Test the sensitivity of the ranking to the top two weights and interpret rank reversal.`,`B7.4 (Evaluate) Recommend and justify a decision, including residual uncertainty.`,`Graduate expectation: a Monte Carlo analysis of uncertain scores (SEBoK v2.14, “Decision Management”, p. 471–472) and a comparison of the point-based trade with set-based design (SEBoK v2.14, “Set-Based Design”).`],citations:[],provenance:`instructor-authored`},{id:`w7-intuition`,kind:`intuition`,title:`Intuition: choosing an apartment with a spreadsheet you can defend`,paragraphs:[`Suppose you are choosing between three apartments. One is cheap but far from campus, one is close but small, one is quiet but expensive. A common first attempt is to write the rent in dollars, the commute in minutes and the floor area in square metres in one row each and add them up. The total means nothing: dollars, minutes and square metres are not on a common scale, and the sum would change if you measured the commute in hours. The second attempt is to give each attribute an “importance” out of ten by feel. That fails too, because how much you care about rent depends on how different the rents are. If every apartment costs within USD 20 of the others, rent should barely matter however “important” money is to you.`,`A trade study fixes both problems. Each attribute is converted from its own units into value on a common 0–1 scale, using a value function anchored at the worst level you would accept and the best level worth having. Weights are then judged by asking which swing — from worst to best — you would most like to have, and by how much. Finally, you ask how much the answer depends on the judgements you made: would a friend who weighted rent a little more choose differently? SEBoK’s Decision Management article opens its discussion of objectives with the same tension, quoting Keeney (see the quotation below).`,`AeroLink faces the same structure on a larger scale: the Year-2 capacity decision (S04 Lab 11, “additional aircraft vs additional vertiports”) trades passenger wait against capital, resilience and community noise exposure. This week you will build the decision model, compute it, break it on purpose with a sensitivity analysis, and write a recommendation that says when it would stop being true.`],quote:{text:`Most important decisions involve multiple objectives, and usually with multiple-objective decisions, you can't have it all.`,cite:{reading:`R18`,pages:`465`}},citations:[{reading:`R18`,pages:`465`}],provenance:`mixed`},{id:`w7-process`,kind:`concept`,title:`Concept: decision management and the trade study`,paragraphs:[`SEBoK states the purpose of the decision management process, quoting ISO/IEC/IEEE 15288, as providing a structured, analytical framework for objectively identifying, characterising and evaluating a set of alternatives for a decision at any point in the life cycle and selecting the most beneficial course of action. Decisions need a formal process when they involve many stakeholders, competing objectives, substantial uncertainty and significant consequences. The trade study is the method systems engineers use most; it decomposes the decision into parts that experts can assess within their own expertise and then synthesises the parts, so the decision maker can work within human cognitive limits without oversimplifying the problem (SEBoK v2.14, “Decision Management”, p. 463).`,`The process SEBoK describes is iterative and rests on four best practices: sound decision-analysis mathematics; one master decision model that is refined and reused through the life cycle; value-focused thinking (Keeney) to create better alternatives; and identifying uncertainty and assessing risk for each decision (SEBoK v2.14, “Decision Management”, p. 464). It begins with framing: describe the system baseline, boundaries and interfaces, the life-cycle stage, decision milestones, decision makers, stakeholders and resources, and write a decision problem statement in terms of the life cycle (SEBoK v2.14, “Decision Management”, p. 465). Your Week 1 boundary, Week 2 stakeholder map and Week 6 AROU register are exactly these inputs.`,`The DoD Systems Engineering Guidebook describes decision analysis as transforming a broadly stated decision opportunity into a traceable, defendable and actionable plan, integrated with technical planning, technical assessment, stakeholder requirements definition, requirements analysis and architecture design (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 109). Its step list runs from identifying the problem and reviewing requirements and assumptions, through developing criteria, weights and their rationale and recording assumptions, to analysing alternatives, synthesising results, analysing sensitivities, and making a recommendation with an action plan. The breadth and depth of the analysis should be scaled to the decision. Crucially, the guidebook states that the decision maker has full responsibility, authority and accountability for the decision (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110). A trade study informs a decision; it does not make it.`,`SEBoK’s System Analysis article adds the analyst’s checklist: assessment criteria are based on the requirements and must include at least the stakeholders’ cost and time constraints; trade studies must deal with objective and subjective criteria; and care must be taken to assess the sensitivity of the overall assessment to particular criteria (SEBoK v2.14, “System Analysis”, p. 608–609). It also warns that analytical modelling is an aid, not a decision tool (SEBoK v2.14, “System Analysis”, p. 614).`],citations:[{reading:`R18`,pages:`463–465`},{reading:`R43`,pages:`109–110`},{reading:`R34`,pages:`608–609, 614`}],provenance:`source-paraphrase`},{id:`w7-value`,kind:`concept`,title:`Concept: objectives and measures, value functions, swing weights and the additive value model`,paragraphs:[`Objectives and measures. Objectives are developed with subject-matter experts and stakeholders; for systems trade-offs they typically include performance, schedule, unit cost, support cost and growth potential. The set of fundamental objectives should be checked: each objective essential and controllable, and the set complete, non-redundant, concise, specific and understandable. Each objective then needs a measure that is unambiguous, comprehensive, direct, operational and understandable (SEBoK v2.14, “Decision Management”, p. 465). In this course a criterion (CRIT) is the measure for one objective, and it derives from an MOE defined in Week 5.`,`Value functions. The defining step of multi-objective decision analysis is the move from measure space to value space. A value function shows the returns to scale over the measure’s range. Its walk-away point — the score at which the decision maker would reject an alternative however well it does elsewhere — maps to value 0; its stretch goal — the level beyond which more adds no value — maps to the top of the value scale (SEBoK uses 1, 10 or 100). The rationale for the shape must be documented for traceability and defensibility (SEBoK v2.14, “Decision Management”, p. 465–466). In the AeroLink reference, CRIT-001 (wait) is worth 0 at 60 min or more and 1 at 5 min, so a 30 min wait is worth (60 − 30) / (60 − 5) = 0.545.`,`Swing weights. The weights must depend on both the importance of the measure and its range from walk-away point to stretch goal. SEBoK recommends the swing weight matrix: place each measure by importance (defining, critical or enabling) and by the gap between current and desired capability; the top-left cell receives an unnormalised weight of 100, values decrease to the right and downwards, other swings are assessed against the most important one, and the swing weights are normalised to sum to one for the additive value model (SEBoK v2.14, “Decision Management”, p. 466–467). This is why “cost is the most important thing” is not a weight: the question is how much the swing from USD 20 M to USD 0 M is worth compared with the swing from a 60-minute to a 5-minute wait.`,`Scoring and synthesis. Experts score each alternative on each measure using data, tests, simulations and models, recording source and rationale on scoring sheets; the score matrix also includes an ideal alternative as a tool for value-focused thinking (SEBoK v2.14, “Decision Management”, p. 468). Scores are transformed into a value table with the value functions, and a heat map shows where alternatives need improvement (SEBoK v2.14, “Decision Management”, p. 469). The additive value model then computes each alternative’s value as v(a) = Σᵢ wᵢ vᵢ(xᵢ(a)), the weighted sum of its single-measure values (SEBoK v2.14, “Decision Management”, p. 469; the equation is an image in the source PDF, so the notation here is the course’s). A value component chart shows each total split into weighted contributions (SEBoK v2.14, “Decision Management”, p. 470).`,`SEBoK v2.14, “System Analysis” outlines the analyst’s side of the same task, with one difference to notice. Its selection-criteria model selects criteria from the non-functional requirements, sorts them, establishes a comparison scale for each and weights each according to its level of relative importance (SEBoK v2.14, “System Analysis”, p. 611). That is an importance weight: it does not ask about the range between the walk-away point and the stretch goal, which is exactly what SEBoK v2.14, “Decision Management”’s swing weights add (SEBoK v2.14, “Decision Management”, p. 466). This course uses SEBoK v2.14, “System Analysis” as the process outline and SEBoK v2.14, “Decision Management”’s swing weights for the weights themselves; an “importance out of ten” is the RB-6.3 level-2 error. SEBoK v2.14, “System Analysis” also lists the sensitivity of solutions’ scores to the criteria weights among the items to check before results can be trusted (SEBoK v2.14, “System Analysis”, p. 612).`],citations:[{reading:`R18`,pages:`465–470`},{reading:`R34`,pages:`611–612`}],provenance:`source-paraphrase`},{id:`w7-uncertainty`,kind:`concept`,title:`Concept: sensitivity, uncertainty, improving alternatives and communicating the decision`,paragraphs:[`SEBoK asks subject-matter experts to discuss the uncertainty of the independent variables — the variables that drive one or more scores. Often an expert can give a lower, nominal and upper bound by assuming low, moderate and high performance. A Monte Carlo simulation then summarises the impact of these uncertainties and can identify the ones that matter most to the decision (SEBoK v2.14, “Decision Management”, p. 471). Decision analysis uses several forms of sensitivity analysis — line diagrams, tornado diagrams and waterfall diagrams — and several forms of uncertainty analysis, including Monte Carlo simulation, decision trees and influence diagrams; a line diagram is used to show sensitivity to the swing-weight judgement (SEBoK v2.14, “Decision Management”, p. 472).`,`Two further activities turn analysis into a better decision. Mining the results usually reveals ways to modify an alternative to capture untapped value or reduce risk, which moves the team from alternative-focused to value-focused thinking. Then the team identifies the key trade-offs, uncertainties and risks and presents the recommendation as a clearly worded, actionable task list, in a report that preserves the rationale for future decisions (SEBoK v2.14, “Decision Management”, p. 472–473).`,`Finally, SEBoK warns that cognitive bias can seriously distort decisions and that self-mitigation by the decision maker is not feasible for most biases. It names confirmation bias as the best known, and rankism, complacency and optimism as typical. Mitigations include an independent review body that is organisationally and financially independent of the programme, crew resource management, and Kahneman’s premortem, in which trusted experts are asked to argue the case against the decision before it is made (SEBoK v2.14, “Decision Management”, p. 473–474).`,`Applied to AeroLink (instructor reasoning): one-way weight sensitivity answers “how far would a weight judgement have to move to change the decision?”, and Monte Carlo answers “how likely is the recommended alternative to stay first, given what we do not know about the scores?”. They are complementary. A recommendation that survives both is robust; one that survives only the deterministic analysis is fragile, and the report must say so.`],citations:[{reading:`R18`,pages:`471–474`}],provenance:`mixed`},{id:`w7-worked-frame`,kind:`worked-example`,title:`Worked example (a): structuring the AeroLink Year-2 capacity trade`,paragraphs:[`Decision statement (DEC-001): “How should AeroLink provide the Year-2 capacity objective (MGO-007, REQ-STK-004: at least 300 trips/day by month 24) — by adding aircraft, adding vertiports, or both?” The life-cycle point is the end of concept definition, before aircraft and site commitments; the decision maker is the AeroLink board, with investors (STK-003), vertiport operators and the electric utility as stakeholders. Year-2 planning demand is 240 trips/day (assumption A-006), so 300 trips/day keeps utilisation at or below 80 %. All values are FICTIONAL.`,`Alternatives. Capacity follows the Week 1 model: min(aircraft × 20, turnaround chargers × 48) trips/day, because each aircraft flies 20 trips a day and each hub charger gives 48 twenty-minute charges in a 16-hour day. Four alternatives span the space, including the baseline that RB-6.1 requires. Note the systems-thinking point: buying aircraft alone moves the binding constraint to charging (the Week 1 limits-to-growth structure, R-001), and adding a vertiport alone leaves the network fleet-limited.`,`Criteria traced to MOEs: CRIT-001 wait at Year-2 demand (minutes, lower is better) derives from MOE-001; CRIT-002 capital over months 0–24 (USD M) from MOE-005 — strictly a cost measure, not a measure of mission effectiveness, which the course baseline files with the MOEs so that cost is handled explicitly as RB-6.2 asks (a course convention); CRIT-003 capacity retained after loss of one hub (%) from MOE-006; CRIT-004 community noise exposure at the busiest vertiport (movements per hour) from MOE-003. Check them against SEBoK v2.14, “Decision Management”, p. 465: each is essential and controllable; together they cover service, cost, resilience and community; none double-counts another. “Capacity” itself is not a criterion — it would double-count wait — and it is screened against REQ-STK-004 instead. CRIT-001 is computed from the Week 1 wait approximation 2 / (1 − u), extended for this trade (a course extension) with a cap at u = 0.97 and 120 min per unit of overload: w(u) = 2 / (1 − min(u, 0.97)) + max(0, u − 1) × 120 min at u = 240 / capacity; it is a proxy for MOE-001’s 90th-percentile wait, and the proxy is recorded in the criterion text.`],table:{caption:`AeroLink alternatives and raw scores (FICTIONAL). Capacity in trips/day; binding constraint in brackets.`,header:[`ID`,`Alternative`,`Aircraft / hub chargers / sites`,`Capacity`,`Meets REQ-STK-004?`,`CRIT-001 wait (min)`,`CRIT-002 capital (USD M)`,`CRIT-003 retained (%)`,`CRIT-004 movements/h`],rows:[[`ALT-001`,`Baseline: no added capacity`,`12 / 6 / 6`,`240 (fleet)`,`No`,`66.7`,`0`,`80`,`8`],[`ALT-002`,`Additional aircraft only (+6)`,`18 / 6 / 6`,`288 (charging)`,`No`,`12`,`18`,`66.7`,`8`],[`ALT-003`,`Additional vertiport only (fourth hub)`,`12 / 8 / 7`,`240 (fleet)`,`No`,`66.7`,`6`,`100`,`6.86`],[`ALT-004`,`Balanced: +4 aircraft, convert a spoke to a hub`,`16 / 8 / 6`,`320 (fleet)`,`Yes`,`8`,`12.8`,`90`,`8`]]},citations:[{reading:`R18`,pages:`465–468`}],provenance:`mixed`},{id:`w7-worked-value`,kind:`worked-example`,title:`Worked example (b): value functions, swing weights and the additive calculation`,paragraphs:[`Value functions (linear, recorded rationale in each CRIT): CRIT-001 v = (60 − x) / 55 between 60 min (walk-away: passengers leave, A-001) and 5 min (stretch goal); CRIT-002 v = (20 − x) / 20 between USD 20 M and USD 0 M; CRIT-003 v = (x − 50) / 50 between 50 % and 100 %; CRIT-004 v = (10 − x) / 5 between 10 and 5 movements/h. Values are clamped to [0, 1]: ALT-001’s 66.7 min wait is past the walk-away point and is worth 0, not a negative number.`,`Swing weights. Starting from an alternative at every walk-away point, the team asks which single swing it would take first. Wait (60 → 5 min) is ranked first and anchored at 100 points; the investors’ capital swing (USD 20 M → 0) is judged worth 75 % of it; the resilience swing (50 → 100 % retained) 40 %; the noise-exposure swing (10 → 5 movements/h) 35 %, because every movement already meets the 65 dBA limit (REQ-STK-002). Normalising by the total of 250 points gives w = 100/250 = 0.40, 75/250 = 0.30, 40/250 = 0.16 and 35/250 = 0.14 (SEBoK v2.14, “Decision Management”, p. 466). Each rationale names the range, not just the criterion.`,`The additive calculation is shown cell by cell in the table: single-attribute value, then weighted contribution wᵢvᵢ, then the sum. For ALT-004: 0.40 × 0.945 + 0.30 × 0.360 + 0.16 × 0.800 + 0.14 × 0.400 = 0.378 + 0.108 + 0.128 + 0.056 = 0.670. ALT-004 leads ALT-002 by 0.182. Its largest weighted gap to the ideal alternative (1.000) is on capital (0.30 × 0.64 = 0.192): that is where value-focused thinking would look for a better alternative — for example the overnight charger-leasing opportunity O-002, which would lower its net capital.`,`Use the swing-weight walkthrough below to elicit your own team’s weights, and the range probes to test whether your weights respond to ranges as they should.`],table:{caption:`Additive value v(a) = Σ wᵢ vᵢ, step by step (each cell: raw score → value → weighted contribution). Recomputed in src/activities/week07/trade.test.ts.`,header:[`Alternative`,`CRIT-001 (w 0.40)`,`CRIT-002 (w 0.30)`,`CRIT-003 (w 0.16)`,`CRIT-004 (w 0.14)`,`Total`,`Rank`],rows:[[`ALT-004`,`8 → 0.945 → 0.378`,`12.8 → 0.360 → 0.108`,`90 → 0.800 → 0.128`,`8 → 0.400 → 0.056`,`0.670`,`1`],[`ALT-002`,`12 → 0.873 → 0.349`,`18 → 0.100 → 0.030`,`66.7 → 0.334 → 0.053`,`8 → 0.400 → 0.056`,`0.489`,`2`],[`ALT-003`,`66.7 → 0 → 0`,`6 → 0.700 → 0.210`,`100 → 1.000 → 0.160`,`6.86 → 0.628 → 0.088`,`0.458`,`3`],[`ALT-001`,`66.7 → 0 → 0`,`0 → 1.000 → 0.300`,`80 → 0.600 → 0.096`,`8 → 0.400 → 0.056`,`0.452`,`4`],[`Ideal`,`5 → 1 → 0.400`,`0 → 1 → 0.300`,`100 → 1 → 0.160`,`5 → 1 → 0.140`,`1.000`,`—`]]},citations:[{reading:`R18`,pages:`466–469`}],provenance:`mixed`},{id:`w7-worked-sensitivity`,kind:`worked-example`,title:`Worked example (c): sensitivity and the rank-reversal point, derived and checked`,paragraphs:[`Method (course convention). Vary one weight wₖ from its base value and rescale the others in proportion so that the weights still sum to one. Then every alternative’s total is a straight line in wₖ: V_a(w) = w · v_ak + (1 − w) · S_a, where S_a = (V_a − wₖ v_ak) / (1 − wₖ) is the alternative’s value on the other criteria, renormalised. Two alternatives a and b tie where w* = (S_b − S_a) / ((v_ak − S_a) − (v_bk − S_b)). Plotting these lines is SEBoK’s line diagram for swing-weight sensitivity (SEBoK v2.14, “Decision Management”, p. 472). The proportional-rescaling rule is not stated in SEBoK v2.14, “Decision Management”; it is the convention L7 uses so that results are comparable between teams.`,`Cost weight (CRIT-002, base 0.30). For ALT-004: S = (0.670 − 0.30 × 0.36) / 0.70 = 0.562 / 0.70 = 0.803, so V(w) = 0.803 − 0.443w. For ALT-001: S = (0.452 − 0.30 × 1.00) / 0.70 = 0.217, so V(w) = 0.217 + 0.783w. They tie at w* = (0.803 − 0.217) / (0.783 + 0.443) = 0.586 / 1.226 = 0.478, where both are worth 0.591. Checks: at w = 0.30 the lines return the base totals 0.670 and 0.452; ALT-003 crosses ALT-004 only at 0.569 and ALT-002’s line falls, so ALT-001 is the first to overtake. Numerically, at w = 0.47 ALT-004 still leads (0.595 vs 0.585); at w = 0.49 ALT-001 leads (0.601 vs 0.586).`,`Wait weight (CRIT-001, base 0.40). For ALT-004 S = 0.292 / 0.60 = 0.487 and v = 0.945, so V(w) = 0.487 + 0.459w; for ALT-003 S = 0.458 / 0.60 = 0.763 and v = 0, so V(w) = 0.763 − 0.763w. They tie at w* = 0.277 / 1.222 = 0.226. The baseline crosses ALT-004 at 0.220, slightly lower, so ALT-003 is the first to overtake as the wait weight falls.`,`Interpretation. The decision survives a cost weight rising by 0.178 (to 0.478, a 59 % relative increase) and a wait weight falling by 0.174 (to 0.226). The other two weights would have to rise past 0.592 (resilience) or 0.555 (noise) before ALT-003 ranked first. The tornado for ±0.1 shows the base margin of 0.182 shrinking to 0.090 at worst (wait weight 0.30) and to 0.096 on the cost bar (cost weight 0.40), without a flip; widen the range to ±0.2 and the cost and wait bars both cross zero. Crucially, the alternatives that win after a reversal — the baseline and the vertiport-only option — both fail REQ-STK-004. A board that weights capital above 0.478 is not choosing a better way to meet MGO-007; it is choosing not to meet it. That is the sentence the recommendation must contain.`],table:{caption:`Rank-reversal points for each weight (others rescaled in proportion); reference trade study, FICTIONAL values`,header:[`Weight varied`,`Base`,`Reversal`,`Change needed`,`New first`,`New first meets REQ-STK-004?`],rows:[[`CRIT-002 capital`,`0.30`,`above 0.478`,`+0.178`,`ALT-001 baseline`,`No`],[`CRIT-001 wait`,`0.40`,`below 0.226`,`−0.174`,`ALT-003 vertiport only`,`No`],[`CRIT-003 resilience`,`0.16`,`above 0.592`,`+0.432`,`ALT-003 vertiport only`,`No`],[`CRIT-004 noise exposure`,`0.14`,`above 0.555`,`+0.415`,`ALT-003 vertiport only`,`No`]]},citations:[{reading:`R18`,pages:`472`}],provenance:`mixed`},{id:`w7-worked-recommendation`,kind:`worked-example`,title:`Worked example (d): a recommendation with residual uncertainty`,paragraphs:[`Recommendation (DEC-001). Buy four aircraft and convert one spoke vertiport into a fourth hub by upgrading its two chargers to high-power units (ALT-004). It is the only alternative that meets REQ-STK-004 (320 ≥ 300 trips/day) and it scores 0.670 against 0.489 for the next best. Adding aircraft alone (ALT-002) moves the bottleneck to charging; adding a vertiport alone (ALT-003) leaves the network fleet-limited.`,`Conditions. The recommendation holds while the board weights capital below 0.478, Year-2 demand stays near 240 trips/day (A-006), and the spoke site’s grid connection supports two high-power chargers (U-002, R-005). Aircraft unit cost alone cannot reverse it at the base weights: with zero value on capital ALT-004 still scores 0.562, above every other alternative’s total.`,`Residual risk. R-001 (charging lags fleet growth) is reduced but not removed; R-005 (grid connection) now sits at the converted hub; R-002 (battery fade) rises with more fast-charge cycles. Uncertainty in the scores themselves is quantified by the Monte Carlo in the advanced section: with one draw of each uncertain driver (demand, unit prices, noise peaking) feeding every alternative, ALT-004 ranks first in about 94 % of 10,000 trials (seed 2026), and it loses only when demand falls below 232 trips/day.`,`What would change it. A demand forecast of 192 trips/day or less (MGO-007’s 80 % utilisation rule would then re-derive REQ-STK-004 as 192 / 0.8 = 240 trips/day, which the baseline already provides; REQ-STK-004 as written, 300 trips/day, would still exclude it), a capital weight above 0.478, or a connection limit (TBD-02) that rules out a fourth hub. Action list (SEBoK v2.14, “Decision Management”, p. 473): order the high-power charger upgrade only after the supplier test report confirms TRL 6 (A-003); order the four aircraft; request the connection study for the candidate spoke; re-run the trade when the quarterly demand re-forecast arrives. The decision maker — the board — owns the decision (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110); the analysis gives it the reasons and the boundaries.`],citations:[{reading:`R18`,pages:`472–473`},{reading:`R43`,pages:`110`}],provenance:`mixed`},{id:`w7-advanced`,kind:`advanced`,title:`Advanced analysis: Monte Carlo on uncertain scores, and set-based design`,paragraphs:[`Monte Carlo (graduate task; SEBoK v2.14, “Decision Management”, p. 471–472). SEBoK v2.14, “Decision Management” asks experts for a lower, nominal and upper bound on the independent variables that drive the scores. The course tool therefore separates drivers from scores (a course method): each uncertain driver gets its own distribution, and every score that depends on a driver is computed from it through the model that produced the nominal score. In the reference (FICTIONAL): Year-2 demand 216–240–264 trips/day (A-006 ± 10 %), pushed through the wait model, gives ALT-004 a wait of 6.2–8–11.4 min, ALT-002 8–12–24 min, and ALT-001 and ALT-003 20–66.7–78.7 min; capital follows from an aircraft price of USD 2.7–3.0–3.6 M (six aircraft for ALT-002, four for ALT-004), a high-power charger upgrade of USD 0.3–0.4–0.8 M each (two for ALT-004) and a new vertiport of USD 4.8–6.0–9.0 M (ALT-003); noise exposure scales with a peaking factor of 1.44–1.60–1.76. Each trial draws each driver once, so one demand value sets all four waits and one aircraft price sets both fleet purchases. Drivers are sampled from triangular distributions with a seeded generator, so a run is reproducible.`,`Results, 10,000 trials, seed 2026: ALT-004 ranks first in 93.8 % of trials (Monte Carlo standard error ±0.24 percentage points; an independent re-implementation with 200,000 trials gives 94.1 %), ALT-003 in 3.1 % and ALT-001 in 3.1 %. ALT-002 never ranks first, and cannot: its best possible total (0.567) is below ALT-004’s worst (0.575). ALT-004’s value lies between 0.632 and 0.687 in 90 % of trials. Three findings are worth more than the headline. First, mean value and mean rank tell different stories: ALT-002 has the lowest mean value (0.477, below its nominal 0.489, because its wait and capital are skewed towards the bad end) yet the best mean rank of the three challengers (2.72), because it is a steady second; the baseline and the vertiport-only option are bimodal, near their nominal values in most trials but up to about 0.68 when demand is low (the baseline’s 5th–95th percentile range is 0.438–0.679). Second, every loss happens when demand is below 232 trips/day, the only case in which the baseline’s or the vertiport-only option’s wait drops under the 60-minute walk-away point (22 % of trials for this demand triangle); without any wait value those two options cannot exceed 0.474 and 0.495 even at their best capital and noise scores, and even in the low-demand trials ALT-004 still wins about 73 % of the time. Demand is therefore the uncertainty that matters most, which is what SEBoK v2.14, “Decision Management”, p. 471 says the simulation should reveal. Third, the dependence assumption matters: if every alternative’s wait and capital were drawn from its own forecast (independent draws), the probability would fall to 87.5 %. Independence is wrong here, because a single forecast drives all four waits and one aircraft price drives both fleet purchases; the report should state the dependence assumption it used. A tempting shortcut — fit a triangle to each alternative’s own wait range and draw them all at the same quantile — is not equivalent: it gives 96.1 %, about ten standard errors away, because a triangle fitted to the endpoints is not the image of the demand triangle (it puts the baseline’s wait under 60 minutes in 58 % of trials instead of 22 %). The standard error measures the precision of the simulation given its model, not the correctness of the model.`,`Limits of the additive model (instructor reasoning, beyond the sources). The additive form assumes that the value of a change in one measure does not depend on the levels of the others, and the linear value functions assume constant returns to scale over each range. Neither is free: a wait of 8 minutes is probably worth less to a passenger if the vertiport is closed by weather. When such an interaction matters, change the criteria rather than the arithmetic — for example, make CRIT-001 the wait under a stated disruption scenario.`,`Set-based design (extension SEBoK v2.14, “Set-Based Design”). SBD analyses sets of alternatives rather than single points, establishes feasibility before decisions, and lets experts converge by intersecting their feasible sets; it suits early design with many coupled variables, conflicting requirements and requirements that can still be traded (SEBoK v2.14, “Set-Based Design”, p. 1396). Systems engineers separate design factors into set drivers — fundamental decisions that define the system — and set modifiers that can be added on and changed later (SEBoK v2.14, “Set-Based Design”, p. 1396). The analyst’s process treats each design decision as a uniform random variable, evaluates the generated alternatives with an integrated model (Monte Carlo is one method), screens out infeasible ones, classifies the rest into sets, uses dominance analysis, and carries one or more sets into the next stage (SEBoK v2.14, “Set-Based Design”, p. 1399). A one-requirement-at-a-time tornado shows which requirement most constrains the feasible tradespace (SEBoK v2.14, “Set-Based Design”, p. 1397).`,`Applied to AeroLink (instructor analysis, FICTIONAL): with fleet size {12, 14, 16, 18, 20} and hub count {3, 4, 5} there are 15 design points. Three hubs can never reach 300 trips/day (at most 288, charging-limited), so REQ-STK-004 removes the whole three-hub set before any weighting — including both the baseline and ALT-002. Six points are feasible and none dominates another on capital, capacity and capacity retained. Hub count is the set driver (sites and grid connections are slow, hard-to-reverse commitments tied to U-002), while fleet size is a set modifier (aircraft can be added later). An SBD recommendation would therefore keep the four-hub and five-hub sets open until the connection study closes TBD-02, and defer the fleet number — a different and arguably better-hedged answer than choosing the single point ALT-004 now.`],table:{caption:`Feasible set-based tradespace (FICTIONAL; capital relative to the baseline; retained = capacity after loss of one hub). Recomputed in trade.test.ts.`,header:[`Aircraft / hubs`,`Capacity (trips/day)`,`Capital (USD M)`,`Retained after hub loss`,`Note`],rows:[[`16 / 4`,`320`,`12.8`,`90 %`,`= ALT-004`],[`18 / 4`,`360`,`18.8`,`80 %`,`more headroom, charging-limited after a hub loss`],[`20 / 4`,`384`,`24.8`,`75 %`,`beyond the CRIT-002 walk-away point`],[`16 / 5`,`320`,`13.6`,`100 %`,`needs a second spoke conversion (U-002)`],[`18 / 5`,`360`,`19.6`,`100 %`,``],[`20 / 5`,`400`,`25.6`,`96 %`,`beyond the CRIT-002 walk-away point`]]},citations:[{reading:`R18`,pages:`471–472`},{reading:`R35`,pages:`1396–1399`}],provenance:`mixed`},{id:`w7-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`SEBoK illustrates every step of its decision management process with a hypothetical unmanned aerial vehicle decision (SEBoK v2.14, “Decision Management”, p. 464), and its trade space has five objectives: performance, growth potential, schedule, development and procurement costs, and sustainment costs (SEBoK v2.14, “Decision Management”, p. 464). Its stakeholder value scatter plot shows unit cost against performance value for every alternative, with development risk and growth potential encoded on each marker (SEBoK v2.14, “Decision Management”, p. 470–471). The lesson for AeroLink is to separate cost from value when presenting results, so that the board can see what each increment of value costs. The DoD guidebook places decision analysis at the centre of technical planning, requirements analysis and architecture design, and expects decision makers to be able to drill down from the overall trade-space view to the detailed analyses behind it (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 109–110).`,`Two cautions carry over to industrial practice. First, SEBoK v2.14, “System Analysis”’s cost analysis considers full life-cycle cost — development, manufacturing or service realisation, sales and after-sales, customer utilisation, supply chain, maintenance and disposal (SEBoK v2.14, “System Analysis”, p. 609–610). The AeroLink CRIT-002 measures capital only; a five-year operating-cost view would penalise ALT-002’s extra aircraft further and credit O-002’s charger leasing, and a CP3 team that adds it should say whether the ranking changes. Second, SEBoK v2.14, “System Analysis”’s good practice is to keep results in their modelling context — tool, assumptions, parameters and output variance (SEBoK v2.14, “System Analysis”, p. 614). In the L7 workbook this means recording the value functions, the rescaling convention, the Monte Carlo seed and the distributions alongside the scores.`],citations:[{reading:`R18`,pages:`464, 470–471`},{reading:`R43`,pages:`109–110`},{reading:`R34`,pages:`609–610, 614`}],provenance:`mixed`},{id:`w7-lab`,kind:`lab`,title:`Lab L7 — trade study: aircraft vs vertiports (out of class)`,paragraphs:[`Teams complete L7 out of class (≈ 3.5 h each; there is no in-class lab time because Session 2 is Exam 1) after the 30-minute kick-off in Session 1, with an office-hour checkpoint. Use the trade-study simulator in Worked example (c): load your own ALT and CRIT elements from the workspace or start from the reference, compute, test sensitivity on the top two weights, then save the study and record your DEC. While you explore, the simulator blocks computation only for structural errors (fewer than 3 alternatives or 4 criteria, missing scores, non-positive swing points, undefined value functions) and warns about the rest. Saving to the workspace enforces the L7 minimums: exactly one alternative marked as the baseline in the Baseline column, every criterion traced to an MOE that exists in your workspace, and owner initials and provenance on every CRIT, ALT and DEC it writes. It cannot judge whether your alternatives are genuinely different or your rationales name the ranges; the instructor does (RB-6.1, RB-6.3).`],citations:[],provenance:`instructor-authored`},{id:`w7-deliverable`,kind:`deliverable`,title:`Deliverable, assessment and Exam 1`,paragraphs:[`Team: the L7 trade-study workbook (decision statement, alternatives, criteria with MOE traces, value scales, swing weights with rationale, scores, sensitivity with the reversal points, DEC recommendation), scored formatively against RB-6 now and summatively in CP3 at the end of Week 8; the Week 9 defence informs RB-6.6. Individual (graduate): a two-page memo with the Monte Carlo analysis and the set-based design comparison.`,`Exam 1 (Session 2; 75 minutes; individual; closed-AI) covers Weeks 1–6. Part A (25 %) systems thinking, SoS, life cycle and stakeholders; Part B (40 %) needs, ConOps, requirements and measures; Part C (35 %) technology readiness, risk and AROU. Most items are applied analysis of a short AeroLink-variant scenario: expect to classify a stakeholder set, explain a causal loop, critique and rewrite flawed requirements, classify measures, identify a missing scenario, assign a TRL from a description, write and rate risks, and distinguish an assumption from a risk.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w7-act-swing`,title:`Swing-weight elicitation walkthrough`,component:`w07-swing-elicitation`,purpose:`Elicit swing weights for the current criteria by ranking swings and scoring them against a 100-point anchor, check the elicitation for consistency, and test your understanding that weights depend on ranges.`,instructions:[`Rank the swings: from an alternative at every walk-away point, which single move to the stretch goal would you take first?`,`Give the first swing 100 points and score the others relative to it; check the elicitation and fix any inconsistency it reports.`,`Answer the three range probes before you check them.`,`Send consistent points to the simulator and see how the totals and reversal points move. Record the rationale for each swing in your L7 workbook.`],objectives:[`B7.2`],inBlock:`w7-worked-value`},{id:`w7-act-simulator`,title:`Trade-study simulator: additive value, ranking, line diagram, tornado and DEC`,component:`w07-trade-simulator`,purpose:`Build or load a trade study, compute value and ranking, find the rank-reversal points on any weight (by hand first, then checked), read the tornado, and record the recommendation as a DEC in the workspace.`,instructions:[`Load the reference trade study and confirm the totals (0.670, 0.489, 0.458, 0.452) against Worked example (b).`,`Choose CRIT-001 and derive its reversal point by hand from the line equations; enter it and check it. Repeat for CRIT-002.`,`Mutation exercise: change one raw score (for example ALT-004’s capital to USD 16 M) and explain why the reversal point moves the way it does.`,`Lab L7: load your own ALT/CRIT from the workspace (or enter them), save the study to the workspace and record your DEC with conditions, residual risk and what would change it.`],objectives:[`B7.1`,`B7.2`,`B7.3`,`B7.4`],inBlock:`w7-worked-sensitivity`},{id:`w7-act-mc`,title:`Monte Carlo on uncertain scores`,component:`w07-monte-carlo`,purpose:`Quantify how likely each alternative is to rank first when the drivers of the scores are uncertain, and how the answer depends on whether alternatives share a driver.`,instructions:[`Load the reference uncertainty, read how each derived score follows from the drivers, and run 10,000 trials with seed 2026; confirm P(ALT-004 first) = 0.938 ± 0.002.`,`Run the comparison with independent draws and explain the difference in one paragraph.`,`Change one driver (for example widen the demand range to 192–240–288) and identify which uncertainty matters most to the decision.`,`Graduate task: repeat on your own L7 trade and report the drivers and their sources, how each score depends on them (or, where you have no model, which elicited distributions you drew at the same quantile and why), the number of trials, the seed and P(first) with its standard error.`],objectives:[`B7.3`,`B7.4`],inBlock:`w7-advanced`}],lab:{id:`L7`,title:`Trade study (aircraft vs vertiports)`,setting:`team`,durationMinutes:210,objectives:[`B7.1`,`B7.2`,`B7.3`,`B7.4`],inputs:[`S04 Lab 11 decision (“additional aircraft vs additional vertiports”) or an instructor-approved alternative decision`,`CP2 baseline: MGO, REQ-STK (incl. REQ-STK-004), MOE-001..006, TECH, AROU v2 (A-, R-, O-, U-)`,`AeroLink Data Sheet and the Week 1 dynamics model (capacity and wait); all values FICTIONAL`,`Trade-study simulator, swing-weight walkthrough and Monte Carlo activities (this week)`],steps:[{title:`Decision statement`,detail:`Write the decision statement: objective (with MGO/REQ IDs), decision maker, life-cycle point and the assumptions it rests on (A-006 or yours) (SEBoK v2.14, “Decision Management”, p. 465). Record it as the DEC decision attribute.`},{title:`Alternatives`,detail:`Define at least 3 genuinely different ALT including the baseline/status quo. For each, give the design (aircraft, chargers, sites) and its capacity from min(aircraft × 20, chargers × 48); state which constraint binds. Strawman alternatives lose RB-6.1 credit.`},{title:`Criteria traced to MOEs`,detail:`Define at least 4 CRIT, each derived from an MOE (create the derives-from link). Check the set: essential, controllable, non-redundant, with cost and risk handled explicitly (SEBoK v2.14, “Decision Management”, p. 465; RB-6.2). Use requirements such as REQ-STK-004 as feasibility screens rather than as criteria.`},{title:`Value scales`,detail:`For each CRIT give the walk-away point (value 0), the stretch goal (value 1), the shape (linear unless you can justify another) and a one-line rationale (SEBoK v2.14, “Decision Management”, p. 465–466).`},{title:`Swing weights`,detail:`Elicit swing points with the walkthrough (anchor 100), normalise, and record a rationale for each swing that names its range (SEBoK v2.14, “Decision Management”, p. 466; RB-6.3).`},{title:`Scores`,detail:`Score every ALT on every CRIT from the Data Sheet or the dynamics model, citing the source of each number on a scoring sheet (SEBoK v2.14, “Decision Management”, p. 468). Compute the additive value in the simulator and reproduce one alternative’s total by hand in the workbook.`},{title:`Sensitivity`,detail:`For the two largest weights, report the rank-reversal point (direction, value, distance from base, new winner and whether it is feasible), the line diagram and the ±0.1 tornado (RB-6.5). Graduate teams add the Monte Carlo on score uncertainty.`},{title:`Recommendation (DEC)`,detail:`Save the study to the workspace and record the DEC with conditions, residual risk (by R- ID) and what would change it, plus an action list (SEBoK v2.14, “Decision Management”, p. 473; RB-6.6). Book the office-hour checkpoint before submitting.`}],artefacts:[{idPrefix:`ALT`,description:`Trade alternatives with design parameters and raw scores per CRIT`,minimum:`≥ 3, including a baseline/status quo`},{idPrefix:`CRIT`,description:`Trade criteria with unit, walk-away point, stretch goal, value function, swing points, weight and rationale; each derives from an MOE`,minimum:`≥ 4, all traced to MOE`},{idPrefix:`DEC`,description:`Decision record: decision statement, recommended ALT, scores, reversal points, conditions, residual risk, what would change it; affects the chosen ALT`,minimum:`1`}],continuity:`L7 is the trade-study half of CP3 (due end of Week 8; RB-6 45 % of CP3), defended in the 5-minute CP3 defences at the start of Week 9 (RB-6.6). The chosen ALT fixes the physical scope for the Week 8 architecture (for the reference, a fourth hub with high-power chargers becomes PHY and IF elements); CRIT become analysis cases in the SysML v2 model from Week 10; DEC links are traversed in the Week 13 impact analysis when an assumption such as A-006 changes.`,tools:[{label:`Trade-study simulator (this week, Worked example c)`,to:`/week/7`},{label:`AeroLink engineering model workspace (ALT, CRIT, DEC)`,to:`/workspace/model`},{label:`Air Taxi Enterprise workspace (case brief and Data Sheet)`,to:`/workspace/aerolink`}]},assignment:{id:`W7-A`,title:`L7 trade-study workbook (team) and graduate uncertainty memo (individual)`,mode:`team`,due:`Workbook: before the first session of Week 8 (formative feedback), then in CP3 at the end of Week 8 · Memo: end of Week 8`,weight:`L7 workbook: formative now, scored in CP3 (9 %, RB-6 45 %) · graduate memo counts toward the review notebook (RB-16, 5 %)`,instructions:[`Team: submit the L7 workbook with the eight sections below, the workspace export containing your ALT, CRIT and DEC elements, and the simulator outputs (value table, line diagrams for the top two weights, tornado).`,`Reproduce one alternative’s additive total by hand in the workbook; the instructor spot-checks the computation (RB-6.4).`,`Individual (graduate): write a two-page memo. Part 1: Monte Carlo on uncertain scores for your team’s trade (SEBoK v2.14, “Decision Management”, p. 471–472) — distributions with their source, the correlation assumption, number of trials, seed, P(first) with standard error, and which uncertainty matters most. Part 2: compare your point-based trade with a set-based treatment (SEBoK v2.14, “Set-Based Design”, p. 1396–1399): identify set drivers and set modifiers, the feasible sets after the requirement screen, and whether SBD would change or defer your recommendation.`,`Log your hours in the review notebook (workload pilot).`],template:[{heading:`1. Decision statement and context`,guidance:`Objective with MGO/REQ IDs, decision maker, life-cycle point, assumptions (A- IDs) and resources (SEBoK v2.14, “Decision Management”, p. 465; OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110).`},{heading:`2. Alternatives`,guidance:`≥ 3 ALT including the baseline; design parameters, capacity and binding constraint; why they are genuinely different (RB-6.1).`},{heading:`3. Criteria and traces`,guidance:`≥ 4 CRIT with MOE trace, unit and direction; show the set is non-redundant and that cost and risk are explicit; list requirements used as screens (RB-6.2).`},{heading:`4. Value functions and swing weights`,guidance:`Walk-away point, stretch goal and shape with rationale; swing points with a range-based rationale; normalised weights (RB-6.3).`},{heading:`5. Scores and additive value`,guidance:`Scoring sheet with the source of every number; value table; one total reproduced by hand (RB-6.4).`},{heading:`6. Sensitivity`,guidance:`Reversal points for the top two weights (direction, value, distance from base, new winner, feasibility), line diagrams, tornado; graduate: Monte Carlo summary (RB-6.5).`},{heading:`7. Recommendation (DEC)`,guidance:`Recommended ALT, conditions, residual risk by R- ID, what would change it, action list (SEBoK v2.14, “Decision Management”, p. 473; RB-6.6).`},{heading:`8. AI usage statement`,guidance:`Tool, purpose, prompts, what you accepted or rejected and why; AI-suggested alternatives or scores individually checked and tagged (RB-12).`}],rubrics:[`RB-6`,`RB-16`,`RB-12`],rubricScope:`Workbook: RB-6.1–6.6 (formative now; summative in CP3, with RB-6.6 informed by the Week 9 defence). Graduate memo: RB-16.1 engineering reasoning. AI statement: RB-12.1–12.3.`,aiUse:`AI tools may be used to brainstorm alternatives and to critique a draft recommendation. Every AI-suggested alternative, criterion or score is tagged AI-suggested-reviewed and checked against the Data Sheet or the model (RB-12.3). AI tools may not choose the weights: swing weights are the team’s value judgement and must carry the team’s rationale. Exam 1 is closed-AI.`,objectives:[`B7.1`,`B7.2`,`B7.3`,`B7.4`]},quiz:[{id:`q7-1`,bloom:`Apply`,objective:`B7.1`,prompt:`Which decision statement best frames the AeroLink capacity trade in the way SEBoK recommends?`,options:[{id:`a`,text:`“Should AeroLink buy the new 6-seat aircraft?”`,correct:!1,explanation:`This names one solution and asks yes/no; it hides the alternatives (chargers, vertiports, both) and says nothing about the objective or life-cycle point.`},{id:`b`,text:`“How should AeroLink provide at least 300 trips/day by month 24 (MGO-007, REQ-STK-004) — more aircraft, more vertiports or both — decided by the board before concept exit?”`,correct:!0,explanation:`Correct. It states the objective, admits several alternatives, names the decision maker and places the decision in the life cycle, as SEBoK v2.14, “Decision Management”, p. 465 asks of a decision problem statement.`},{id:`c`,text:`“Find the cheapest way to expand AeroLink.”`,correct:!1,explanation:`This pre-judges the weighting (cost only) and omits the performance objective, so it would make the baseline win by construction.`},{id:`d`,text:`“Rank all possible AeroLink investments.”`,correct:!1,explanation:`Too broad to be decided; it has no objective, no decision maker and no life-cycle point, so no criteria can be derived from it.`}],cite:{reading:`R18`,pages:`465`}},{id:`q7-2`,bloom:`Analyse`,objective:`B7.1`,prompt:`A different decision: a team is choosing the supplier of high-power hub chargers and proposes five criteria: (1) rated charger power (kW), (2) time to recharge an aircraft from reserve to the dispatch threshold (min), (3) installed price per charger (USD), (4) number of chargers to buy, (5) the supplier’s evidence of maturity (TRL with its basis). Which critique is best supported by SEBoK v2.14, “Decision Management”’s tests for objectives and measures?`,options:[{id:`a`,text:`The set is fine: five criteria cover more of the decision than four`,correct:!1,explanation:`SEBoK v2.14, “Decision Management” asks for a set that is complete but also non-redundant and concise; overlapping criteria double-count.`},{id:`b`,text:`The number of chargers is a design choice, not a measure of an objective, and rated power overlaps recharge time (power is what drives the time); drop (4), keep the direct measure (2) rather than its proxy (1), and keep (3) and (5)`,correct:!0,explanation:`Correct. A measure should be direct and the set non-redundant (SEBoK v2.14, “Decision Management”, p. 465): recharge time is what the turnaround objective cares about, and rated power only predicts it. How many chargers to buy is a design variable of the alternatives, not a criterion.`},{id:`c`,text:`Drop maturity (5): technology risk belongs in the risk register, not in a trade study`,correct:!1,explanation:`RB-6.2 asks for cost and risk to be handled explicitly in the trade; a supplier at TRL 4 is a different decision from one at TRL 7.`},{id:`d`,text:`Keep (1) and drop (2), because rated power is on the data sheet and recharge time has to be tested`,correct:!1,explanation:`Ease of measurement does not make a proxy direct; SEBoK v2.14, “Decision Management” asks for measures that are direct and operational, and the recharge time can be scored from the supplier’s test report.`}],cite:{reading:`R18`,pages:`463–465`}},{id:`q7-3`,bloom:`Apply`,objective:`B7.2`,prompt:`In the charger-supplier trade, a criterion “charger availability” (share of scheduled hours a charger is serviceable, higher is better) has a linear value function from 85 % (walk-away, value 0) to 99 % (stretch goal, value 1). What is the value of a supplier offering 95 %, and of one offering 80 %?`,options:[{id:`a`,text:`0.714 and −0.357`,correct:!1,explanation:`The first value is right, but the value scale stops at the walk-away point; a negative value would let an unacceptable availability be bought back by other criteria without limit.`},{id:`b`,text:`0.714 and 0`,correct:!0,explanation:`Correct. v = (95 − 85) / (99 − 85) = 10/14 = 0.714. Below the walk-away point the value is 0: the decision maker would reject that supplier however well it did elsewhere (SEBoK v2.14, “Decision Management”, p. 465–466).`},{id:`c`,text:`0.286 and 0`,correct:!1,explanation:`0.286 is (99 − 95)/14, which treats lower availability as better — the direction is reversed for a higher-is-better measure.`},{id:`d`,text:`0.960 and 0.808`,correct:!1,explanation:`These are the raw percentages divided by the stretch goal; the value function is anchored at the walk-away point, not at zero availability.`}],cite:{reading:`R18`,pages:`465–466`}},{id:`q7-4`,bloom:`Apply`,objective:`B7.2`,prompt:`After community workshops the team revises the noise-exposure swing from 35 to 60 points; the other swings stay at 100 (wait), 75 (capital) and 40 (resilience). What is the new normalised weight of CRIT-001 (wait)?`,options:[{id:`a`,text:`0.400`,correct:!1,explanation:`That is the old weight, 100/250. Changing one swing changes the total, so every normalised weight changes.`},{id:`b`,text:`0.364`,correct:!0,explanation:`Correct. The new total is 100 + 75 + 40 + 60 = 275, so w = 100/275 = 0.364 (normalised to sum to one, SEBoK v2.14, “Decision Management”, p. 466).`},{id:`c`,text:`0.250`,correct:!1,explanation:`That is an equal weight over four criteria; swing points are not equal here.`},{id:`d`,text:`1.000`,correct:!1,explanation:`100 points is the unnormalised anchor; the additive model needs weights that sum to one.`}],cite:{reading:`R18`,pages:`466`}},{id:`q7-5`,bloom:`Analyse`,objective:`B7.2`,prompt:`An investor says: “Cost is the most important criterion, so give it 100 points.” Which question correctly elicits the cost swing weight?`,options:[{id:`a`,text:`“On a scale of 1 to 10, how important is cost to you?”`,correct:!1,explanation:`This is an importance rating without a range, the RB-6.3 level-2 error; it cannot be combined meaningfully with 0–1 values.`},{id:`b`,text:`“How much is moving capital from the USD 20 M walk-away point to USD 0 M worth to you, compared with moving the wait from 60 min to 5 min?”`,correct:!0,explanation:`Correct. Swing weights depend on importance and on the range from walk-away point to stretch goal, and are assessed against the most important swing (SEBoK v2.14, “Decision Management”, p. 466).`},{id:`c`,text:`“Which alternative do you prefer?”`,correct:!1,explanation:`This asks for the answer, not a weight, and invites the stakeholder’s preferred alternative to drive the weights (confirmation bias, SEBoK v2.14, “Decision Management”, p. 473).`},{id:`d`,text:`“What percentage of the budget is capital?”`,correct:!1,explanation:`Budget shares describe spending, not how much the decision maker values the swing on this criterion.`}],cite:{reading:`R18`,pages:`466`}},{id:`q7-6`,bloom:`Apply`,objective:`B7.2`,prompt:`A new alternative ALT-005 scores: wait 10 min, capital USD 15 M, 90 % capacity retained, 7 movements/h. With the reference value functions and weights (0.40 / 0.30 / 0.16 / 0.14), what is its additive value and where does it rank against ALT-004 (0.670)?`,options:[{id:`a`,text:`0.651, second behind ALT-004`,correct:!0,explanation:`Correct. Values 50/55 = 0.909, 5/20 = 0.25, 0.8, 3/5 = 0.6; total 0.364 + 0.075 + 0.128 + 0.084 = 0.651 < 0.670.`},{id:`b`,text:`0.702, first`,correct:!1,explanation:`This uses the raw resilience score or a wrong cost value; recheck v = (20 − 15)/20 = 0.25 for capital.`},{id:`c`,text:`0.651, first`,correct:!1,explanation:`The arithmetic is right but 0.651 is below ALT-004’s 0.670.`},{id:`d`,text:`It cannot be computed without re-eliciting the weights`,correct:!1,explanation:`Adding an alternative inside the existing ranges does not change the swings, so the weights stand (see the range probes).`}],cite:{reading:`R18`,pages:`469`}},{id:`q7-7`,bloom:`Analyse`,objective:`B7.3`,prompt:`Two alternatives’ totals, as the weight w of one criterion varies with the others rescaled in proportion, are V_A(w) = 0.80 − 0.40w and V_B(w) = 0.20 + 0.80w. The base weight is 0.25. Where is the rank-reversal point, and in which direction?`,options:[{id:`a`,text:`w = 0.50; B overtakes A when the weight rises above 0.50`,correct:!0,explanation:`Correct. 0.80 − 0.40w = 0.20 + 0.80w gives w = 0.60 / 1.20 = 0.50. At the base (0.25) A leads 0.70 to 0.40; B gains as w rises.`},{id:`b`,text:`w = 0.33; B overtakes A when the weight rises above 0.33`,correct:!1,explanation:`This divides 0.40 by 1.20; the difference of intercepts is 0.60.`},{id:`c`,text:`w = 0.50; A overtakes B when the weight falls below 0.50`,correct:!1,explanation:`A already leads at the base weight; the reversal happens when the weight rises, not falls.`},{id:`d`,text:`There is no reversal because both lines are straight`,correct:!1,explanation:`Straight lines with different slopes cross once; the question is only whether the crossing lies in [0, 1].`}],cite:{reading:`R18`,pages:`472`}},{id:`q7-8`,bloom:`Analyse`,objective:`B7.3`,prompt:`In a team’s charger-supplier trade (FICTIONAL), supplier S2 ranks first. Supplier S1 would overtake if the price weight rose from 0.25 to above 0.61; supplier S3 would overtake if the availability weight fell from 0.35 to below 0.31. All three suppliers meet every charger requirement. What is the best interpretation?`,options:[{id:`a`,text:`The recommendation is robust: the price reversal is 0.36 away, so S2 can be recommended without qualification`,correct:!1,explanation:`Robustness is judged on the nearest reversal, not the farthest. A 0.04 change in the availability weight is well within ordinary disagreement between stakeholders.`},{id:`b`,text:`The recommendation is fragile on availability: a change of only −0.04 makes S3 first, and S3 is a feasible alternative, so the report must say so, re-check the availability swing judgement and scores with the stakeholders, and present S2 and S3 as close`,correct:!0,explanation:`Correct. Distance to the nearest reversal plus the meaning of the new winner is the interpretation RB-6.5 and RB-6.6 ask for; here the new winner meets every requirement, so the reversal is a real alternative, not a choice to abandon an objective (SEBoK v2.14, “Decision Management”, p. 472).`},{id:`c`,text:`Raise the availability weight to 0.45 so that the reversal is further away, then report the result`,correct:!1,explanation:`Moving a weight to make a reversal disappear is reverse-engineering the answer, a cognitive-bias failure (SEBoK v2.14, “Decision Management”, p. 473).`},{id:`d`,text:`The trade study is unreliable because two reversals exist inside [0, 1]`,correct:!1,explanation:`Almost every trade has reversals somewhere in [0, 1]; what matters is how far they are from the base values and what they mean.`}],cite:{reading:`R18`,pages:`472–473`}},{id:`q7-9`,bloom:`Analyse`,objective:`B7.3`,prompt:`A ±0.1 tornado on the charger-supplier trade shows the winner’s margin on the price bar going from +0.05 at the low end to −0.02 at the high end; every other bar stays positive. What should the team do next?`,options:[{id:`a`,text:`Narrow the tornado to ±0.05 so that no bar crosses zero, and report that the decision is robust`,correct:!1,explanation:`Choosing the range to hide a crossing is reverse-engineering the result (SEBoK v2.14, “Decision Management”, p. 473); the range should reflect real disagreement about the weight.`},{id:`b`,text:`Find the price-weight reversal point exactly, report its distance from the base weight, the new winner and whether it meets the requirements, and take the price swing judgement back to the decision maker`,correct:!0,explanation:`Correct. The tornado shows which judgement matters; the reversal point says how much disagreement the decision tolerates, and the meaning of the new winner says what crossing it would mean (SEBoK v2.14, “Decision Management”, p. 472; SEBoK v2.14, “System Analysis”, p. 612 lists weight sensitivity among the checks).`},{id:`c`,text:`Remove price from the criteria because it makes the answer unstable`,correct:!1,explanation:`The bar that crosses belongs to a criterion that matters; removing it removes part of the decision, and SEBoK v2.14, “System Analysis”, p. 609 requires the stakeholders’ cost constraints among the criteria.`},{id:`d`,text:`Declare the trade inconclusive and recommend nothing`,correct:!1,explanation:`A crossing within ±0.1 is information for the decision maker, not a reason to withhold a recommendation (RB-6.6).`}],cite:{reading:`R18`,pages:`472`}},{id:`q7-10`,bloom:`Evaluate`,objective:`B7.4`,prompt:`For the charger-supplier trade of the previous items (S2 first at 0.64, S3 second at 0.61; S3 overtakes if the availability weight falls below 0.31), which recommendation best meets the standard of a defensible, actionable recommendation (RB-6.6)?`,options:[{id:`a`,text:`“S2 scored highest (0.64), so S2 is the answer.”`,correct:!1,explanation:`This restates the computation; it has no conditions, residual risk or statement of what would change it, and hides how close S3 is.`},{id:`b`,text:`“Recommend S2, narrowly ahead of S3 (0.64 vs 0.61). Holds while the board values the availability swing at least as stated (weight above 0.31) and S2’s 97 % availability is confirmed by its fleet data. Residual: S2’s firmware reaches TRL 6 on its supplier’s evidence alone, so an action to confirm that evidence on AeroLink hardware stays in the register. Re-decide if S2’s availability evidence comes in below 94 % or the board lowers the availability weight. Actions: request S2’s fleet availability records; negotiate a price option with S3 as the fallback.”`,correct:!0,explanation:`Correct. It states the margin, the conditions tied to the nearest reversal, the residual risk, what would change it and an actionable task list, as SEBoK v2.14, “Decision Management”, p. 473 recommends.`},{id:`c`,text:`“S2 and S3 are too close to call; more study is needed before any recommendation.”`,correct:!1,explanation:`No recommendation is made, which fails RB-6.6. Closeness is something to report with the recommendation, together with what would separate the two.`},{id:`d`,text:`“The model has selected S2; the purchase order goes out on Monday.”`,correct:!1,explanation:`Models aid decisions (SEBoK v2.14, “System Analysis”, p. 614); the decision maker holds responsibility and authority (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110).`}],cite:{reading:`R18`,pages:`473`}},{id:`q7-11`,bloom:`Evaluate`,objective:`B7.4`,prompt:`In the charger-supplier trade every supplier’s installed price depends on one copper-price index. A Monte Carlo with 8,000 trials gives P(S2 first) = 0.71 ± 0.005 when one index draw sets every supplier’s price through each price model, and 0.64 when each supplier’s price is drawn independently. A teammate also fitted a triangle to each supplier’s price range and drew all three at the same quantile, which gave 0.74. What should the team report?`,options:[{id:`a`,text:`0.74, because the same-quantile run also makes the prices move together and it gives the clearest answer`,correct:!1,explanation:`Equal quantiles of separately fitted triangles do not correspond to one value of the index unless each triangle is the exact image of the index distribution; it is an approximation, and here it disagrees with the model by about six standard errors.`},{id:`b`,text:`0.71 from the shared-index model, with the dependence assumption stated and justified, the independent result as a sensitivity, the trials, seed and standard error, and which uncertainty drives the trials S2 loses`,correct:!0,explanation:`Correct. SEBoK v2.14, “Decision Management”, p. 471 asks the simulation to identify the uncertainties that matter, and the dependence assumption is part of the modelling context to report (SEBoK v2.14, “System Analysis”, p. 614). The ±0.005 is precision given the model, not proof that the model is right.`},{id:`c`,text:`0.64, because independence is always the conservative assumption`,correct:!1,explanation:`Independence is not generally conservative; it is simply wrong for prices that share a driver.`},{id:`d`,text:`The average of the three runs, 0.70, because it balances the methods`,correct:!1,explanation:`Averaging models with different assumptions produces a number that corresponds to none of them.`}],cite:{reading:`R18`,pages:`471–472`}},{id:`q7-12`,bloom:`Apply`,objective:`B7.4`,prompt:`The sponsor favoured buying aircraft (ALT-002) from the start, and the team’s early scoring sheets cite only data that support it. Which mitigation does SEBoK’s discussion of cognitive bias support?`,options:[{id:`a`,text:`Ask the sponsor to try harder to be objective`,correct:!1,explanation:`SEBoK reports general agreement that self-mitigation by the decision maker is not feasible for most biases.`},{id:`b`,text:`Run a premortem with trusted experts tasked to argue against the preferred option, and have the scores reviewed by someone independent of the sponsor`,correct:!0,explanation:`Correct. This is confirmation bias; the premortem and independent review are the mitigations SEBoK v2.14, “Decision Management”, p. 473–474 describes.`},{id:`c`,text:`Give ALT-002 extra weight so the result matches the sponsor’s expectation`,correct:!1,explanation:`That institutionalises the bias rather than mitigating it.`},{id:`d`,text:`Remove the scoring rationale so that reviewers judge only the numbers`,correct:!1,explanation:`SEBoK v2.14, “Decision Management”, p. 468 asks for scoring sheets that document source and rationale — the very evidence a reviewer needs.`}],cite:{reading:`R18`,pages:`473–474`}},{id:`q7-13`,bloom:`Analyse`,objective:`B7.1`,prompt:`In a set-based view of the hub charging installation, two design factors are the voltage class of the hub’s grid connection (agreed with the utility; changing it later means new switchgear and a new connection agreement) and the charger power-sharing software (which allocates the connection’s power among the chargers and can be updated remotely). Which classification follows SEBoK v2.14, “Set-Based Design”?`,options:[{id:`a`,text:`Both are set modifiers, because both can be changed in principle`,correct:!1,explanation:`SEBoK v2.14, “Set-Based Design” reserves “set modifier” for decisions that can be added on and changed to adapt; a connection agreement and its switchgear are fundamental and slow to reverse.`},{id:`b`,text:`The connection voltage class is a set driver (it fixes what the installation can ever deliver and is hard to reverse); the power-sharing software is a set modifier (it can be changed later to adapt)`,correct:!0,explanation:`Correct. Set drivers are fundamental design decisions that define system characteristics; set modifiers are added on and can be modified (SEBoK v2.14, “Set-Based Design”, p. 1396).`},{id:`c`,text:`The software is the set driver, because it decides how fast each aircraft charges`,correct:!1,explanation:`The software only shares out what the connection provides; the distinction is how fundamental and reversible a decision is, not which one acts last.`},{id:`d`,text:`Neither: set-based design applies only to vehicle design, not to ground infrastructure`,correct:!1,explanation:`SEBoK v2.14, “Set-Based Design” applies SBD to early-stage design problems with many coupled variables and requirements that can still be traded.`}],cite:{reading:`R35`,pages:`1396`}},{id:`q7-14`,bloom:`Apply`,objective:`B7.4`,prompt:`A team member says: “The spreadsheet says ALT-004, so the decision is made.” Which response reflects the DoD guidebook and SEBoK?`,options:[{id:`a`,text:`Agree: the purpose of the analysis is to remove judgement from the decision`,correct:!1,explanation:`The analysis structures judgement (weights, value functions) and exposes it; it does not remove it.`},{id:`b`,text:`Disagree: the decision maker has full responsibility, authority and accountability; the analysis provides a traceable, defendable basis and the conditions under which the recommendation holds`,correct:!0,explanation:`Correct (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 109–110). SEBoK v2.14, “System Analysis”, p. 614 adds that analytical modelling is an aid, not a decision tool.`},{id:`c`,text:`Agree, provided the sensitivity analysis shows no reversal`,correct:!1,explanation:`Even a robust result is a recommendation to a decision maker, not a decision.`},{id:`d`,text:`Disagree: trade studies are only for documenting decisions already taken`,correct:!1,explanation:`That reverses the purpose; OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process” describes decision analysis as the basis for selecting an alternative.`}],cite:{reading:`R43`,pages:`109–110`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class: Session 1 concept studio and L7 kick-off (75 min) and Exam 1 (75 min)`,hours:2.5},{activity:`Online direct instruction and the three interactive activities (realistic ≈ 1.0 h; see cautions)`,hours:.7},{activity:`Readings SEBoK v2.14, “Decision Management”, OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process” (≈ 14 pp at ≈ 15 pp/h)`,hours:.9},{activity:`Knowledge check`,hours:.2},{activity:`Exam 1 preparation, a structured review of Weeks 1–6 (realistic ≥ 1.5 h; see cautions)`,hours:.5},{activity:`L7 trade study (team share, out of class)`,hours:3.5},{activity:`Graduate memo Part 1: Monte Carlo runs on the team trade (Part 2, SEBoK v2.14, “Set-Based Design” and writing, ≈ 1.1 h, fall in Week 8 before the due date)`,hours:.4},{activity:`Review notebook entry, time log and AI statement`,hours:.3}],references:[{reading:`R34`},{reading:`R35`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes (blockers W7-S01 and W7-C01 fixed by the lead exactly as the reviewer specified, with regression and mutation tests, 2026-10-11)`,date:`2026-10-11`,report:``,openIssues:[]}},_=e({default:()=>v}),v={week:8,drivingQuestion:`The trade study said what AeroLink should buy. Now: what must the enterprise do, which elements do it, what crosses between them, and which information reaches which decision — and how will a model state, unambiguously, which part of the design claims to meet which requirement?`,blocks:[{id:`w8-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to course outcome B-CLO4 (construct a multi-viewpoint architecture and represent it in a SysML v2 model) and, through the recorded architecture decisions, to B-CLO6. It opens Part II of the course. Until now your team has described AeroLink in documents and tables: stakeholders, needs, requirements, measures, risks and a trade study. This week you give the chosen alternative an architecture — functions, the elements that perform them, the interfaces between those elements and the information that flows across them — and you read your first SysML v2 requirement and satisfy relationship. From Week 9 the same content moves into a model. CP3 (trade study and architecture concept) is due at the end of the week and is defended in five minutes at the start of Week 9.`],bullets:[`B8.1 (Apply) Describe AeroLink through operational, functional and physical viewpoints and state the purpose of each view.`,`B8.2 (Analyse) Decompose functions from capabilities and allocate them to physical elements, with a justification that names its criterion.`,`B8.3 (Analyse) Identify physical, information and organisational interfaces with an N² matrix and count them.`,`B8.4 (Analyse) Trace each information item from producer to consumer to the decision it supports, distinguishing data from information.`,`B8.5 (Understand) Read a SysML v2 requirement and satisfy fragment and state what it asserts (micro-lab 3).`,`Graduate expectation: compare two allocation alternatives with an explicitly defined N² coupling metric, and say what the metric cannot see.`],citations:[],provenance:`instructor-authored`},{id:`w8-intuition`,kind:`intuition`,title:`Intuition: a restaurant has functions, staff and a ticket rail`,paragraphs:[`Think about a busy restaurant. Some things must happen for every table: take the order, cook the dishes, plate them, serve them and take payment. Those are functions. They are true of any restaurant, whether the order is taken by a waiter, a tablet or a QR code. Then there are the people and equipment who perform the functions: waiters, chefs, the grill, the till. That is the physical arrangement, and one restaurant differs from another mainly here. Between them run the hand-offs. The ticket rail carries orders from the dining room to the kitchen; the pass carries plates the other way; the till talks to the card terminal. Each hand-off is an interface, and most of the trouble in a restaurant happens at them: a ticket lost on the rail, a dish waiting at the pass, a waiter who does not know the kitchen has run out of fish.`,`Now notice three things. First, the owner, the head chef and the health inspector each need a different picture of the same restaurant, because each has a different question. Second, deciding who does what is a choice with consequences: if waiters also plate desserts, the kitchen has one fewer hand-off but the dining room loses a waiter at the busiest moment. Third, the ticket is not the decision. It carries data (“table 5: two soups, one fish”); the decision is the chef’s “fire table 5 now”. A ticket that nobody acts on is noise.`,`SEBoK describes a system in exactly these terms: interacting elements exchanging data, energy or mass, whose exchanges change the state of the elements they cooperate with (SEBoK v2.14, “System Architecture Design Definition”, p. 569). This week you draw AeroLink’s restaurant: the views each stakeholder needs, the functions every trip requires, the elements that perform them, the interfaces between those elements, and the information that reaches a decision.`],citations:[{reading:`R19`,pages:`569`}],provenance:`mixed`},{id:`w8-viewpoints`,kind:`concept`,title:`Concept: architecture, models, views and viewpoints — and why Part II moves them into a model`,paragraphs:[`From documents to models. SEBoK’s System Architecture Design Definition article starts from the weakness of document-based practice. Design information is spread across many documents that use their own notation without formal semantics, so every change must be synchronised by hand, which causes consistency problems as well as cost and schedule losses (SEBoK v2.14, “System Architecture Design Definition”, p. 569–570). The model-based approach it describes uses SysML, which has graphical and (from SysML v2) textual notations with formal semantics. The design model becomes an authoritative source of truth for the technical baseline. It holds the requirement, functional, logical and physical representations at every level of the system, with traceability to the requirements (SEBoK v2.14, “System Architecture Design Definition”, p. 570, 572). That is the bridge from Part I to Part II. This week you still work in tables and diagrams, but you organise them the way the model will: by viewpoint, with IDs that will become model elements in Week 9.`,`Definitions. MITRE defines an architecture framework as a minimum set of practices and requirements for the artefacts that describe an architecture. Models represent how objects in a system fit structurally and behave as part of it. A view is a partial expression of the system from a particular perspective. A viewpoint is a set of representations (views and models) that covers a stakeholder’s issues (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341). Because systems have many stakeholders with different concerns, their descriptions are multidimensional too, and frameworks let teams create views that are directly relevant to those concerns (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 342). SEBoK says the same of the design model: it contains multiple views of the design with the information needed to address each stakeholder’s viewpoint and concerns, and the typical set of views can be tailored by a project (SEBoK v2.14, “System Architecture Design Definition”, p. 573).`,`Good practice. MITRE’s lessons are blunt. Purpose is paramount: decide what the architecting effort is for and generate only the views and models that purpose needs. Each view should help a stakeholder reason about the structure and behaviour of the system and conclude whether their objectives will be met (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 344). Know the relationships: views that relate to each other must be consistent and concordant, and the data they share should be identified and managed centrally (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345). Keep it simple: avoid node-connectivity diagrams with many nodes and edges early on, and start from the operational concepts that users already understand. State the requirements for your architecture as well — which decisions it supports and what it will help stakeholders reason about (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345). MITRE also recommends a reference implementation of the needed models and views, so that construction is standardised and model elements trace clearly to the concepts and requirements they derive from (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 343). The course’s instructor reference model plays that role.`,`Which viewpoints? The sources do not use one fixed set, and the course does not merge them. MITRE notes that architecture definition usually produces operational, system and technical views (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341). SEBoK treats functional, logical and physical architecture as complementary views. It calls the functional architecture a view or perspective rather than a standalone part of the architecture, and says the three together give a fairly comprehensive picture (SEBoK v2.14, “Functional Architecture”, p. 580–581). The course convention for CP3 (RB-7.1) is three viewpoints: operational (how the enterprise is used, by whom, in which scenarios), functional (what transformations must happen, independent of who or what performs them) and physical (which elements perform them and how they are connected). The logical elements LOG-001..007 from S04 Lab 5 sit between the functional and physical views. They correspond to SEBoK’s logical configuration items, which have allocated functions but no specific implementation (SEBoK v2.14, “System Architecture Design Definition”, p. 571).`],quote:{text:`Views are a partial expression of the system from a particular perspective.`,cite:{reading:`R62`,pages:`341`}},citations:[{reading:`R19`,pages:`569–573`},{reading:`R62`,pages:`341–345`},{reading:`R20a`,pages:`580–581`}],provenance:`mixed`},{id:`w8-decomposition`,kind:`concept`,title:`Concept: functions, decomposition and allocation with a stated criterion`,paragraphs:[`What a function is. SEBoK’s architecture approach defines functional hierarchies of functions and sub-functions in which each function is an input-to-output transformation that satisfies one or more allocated requirements (SEBoK v2.14, “System Architecture Design Definition”, p. 571). The Logical Architecture article is more precise. A function is an action that transforms inputs into outputs; inputs and outputs may be data, materials or energy, and they are the flow items exchanged between functions (SEBoK v2.14, “Logical Architecture”, p. 587). Some functions follow directly from functional and interface requirements. Others appear only once a physical solution has been chosen. The Functional Architecture article adds that “function” here is close to its mathematical sense (y is a function of x), so a functional view has to define inputs and outputs as well as actions (SEBoK v2.14, “Functional Architecture”, p. 580).`,`Decomposition. A hierarchy starts from the system’s mission as one black-box function and breaks it into sub-functions, level by level, until the leaf functions are ones for which a physical solution is known or can be imagined. SEBoK warns that such a hierarchy is usually populated over several iterations rather than in a single top-down pass (SEBoK v2.14, “Logical Architecture”, p. 587). Its pitfalls table names the errors students make most often: decomposing too deeply, decomposing actions while forgetting their inputs and outputs, and building a logical architecture that does not relate back to the operational scenarios from mission analysis. The same table warns against a static decomposition on its own: the decomposition tree only helps to manage and navigate the list of functions, and it should be established only when scenarios have been created. The matching proven practice is to model the behaviour first — establish scenarios of functions — before constituting the decomposition tree (SEBoK v2.14, “Logical Architecture”, p. 594). In AeroLink terms, a function is found by walking a scenario (SCN) step by step, derives from a capability (CAP), and only then takes its place in a tree.`,`Allocation. A physical architecture is built by first identifying system elements that can perform the functions of the logical architecture, and interfaces that can carry the input-output and control flows (SEBoK v2.14, “Physical Architecture”, p. 598). Partitioning and allocation use criteria to find affinities between functions. SEBoK lists similar transformations within the same technology, similar efficiency, exchange of the same type of flow (information, energy, materials), centralised or distributed control, execution at a similar frequency, dependability conditions, resistance to the environment and other enterprise constraints (SEBoK v2.14, “Physical Architecture”, p. 598–599). A candidate architecture may also aim at fewer physical interfaces, elements that can be tested separately, modularity or resilience (SEBoK v2.14, “Physical Architecture”, p. 599). Among the outputs of the process are an allocation matrix of functional to physical elements and a traceability matrix to the system requirements (SEBoK v2.14, “Physical Architecture”, p. 600). Requirements are allocated to both the logical and the physical architecture (SEBoK v2.14, “Physical Architecture”, p. 596).`,`Two pitfalls matter at CP3. The first is skipping the logical architecture and going straight from requirements to physical elements. The second is allocating functions directly to technologies — hardware or software products — at a high level of abstraction, instead of alternating logical and physical levels before reaching the technology level (SEBoK v2.14, “Physical Architecture”, p. 602). The course turns these rules into one discipline (instructor convention): every FN → PHY allocation carries a sentence that names its criterion — one of the affinity criteria above, or an aim such as fewer interfaces — and cites the ID it rests on: the requirement the allocation serves, or the interface or information item the criterion is about. “Because it fits there” is not a justification, and neither is “it is the safest place” with nothing behind it; “the charge-state handshake and the energy both cross IF-005, so FN-006 stays with the chargers (REQ-SYS-001)” is.`],citations:[{reading:`R19`,pages:`571`},{reading:`R20a`,pages:`580`},{reading:`R20b`,pages:`587, 594`},{reading:`R20c`,pages:`596–602`}],provenance:`mixed`},{id:`w8-interfaces`,kind:`concept`,title:`Concept: interfaces, interface management and the N² matrix`,paragraphs:[`What an interface is. MITRE defines interface management as defining, controlling and communicating the information needed to let unrelated objects — systems, services, equipment, software and data — work together. Most new systems need external interfaces, and interface management starts at design and continues through operations (The MITRE Systems Engineering Guide, “Interface Management”, p. 410). MITRE writes about ICT: interfaces are the functional and physical connections at the boundaries of ICT systems designed to interoperate with other systems. There are many kinds: communications, signalling, service, data, hardware and software interfaces, and APIs. The purpose of managing them is to provide all the design information needed for separately designed items to work together, and to use the interface’s performance, functional and physical attributes as constraints on design changes (The MITRE Systems Engineering Guide, “Interface Management”, p. 411). SEBoK’s physical-architecture definition is broader still. A physical interface binds two system elements, like a link or connector. In service and enterprise systems the interface may be a protocol, a procedure or a document rather than a piece of hardware (SEBoK v2.14, “Physical Architecture”, p. 597).`,`Typing interfaces. The course types every IF by what it exchanges. A physical interface carries energy, mass or mechanical load (IF-005, aircraft ↔ charger power). An information interface carries data (IF-008, booking platform ↔ operations centre). An organisational interface is an agreed procedure or responsibility between organisations or teams (IF-004, the operations ↔ maintenance work-order handover). Interfaces to EXT elements are also flagged as external (RB-7.3). This three-way typing is the course’s convention. It is not a SEBoK or MITRE taxonomy: in SEBoK all three are “physical interfaces” in the sense of binding two elements (SEBoK v2.14, “Physical Architecture”, p. 597). The typing matters because each type is managed differently (instructor guidance): energy interfaces are qualified by test; information interfaces need a data definition and a service level; organisational interfaces need an agreement with an owner on each side. It also decides what an interface can carry. Course coverage rule (instructor-defined; the N² tool and the tracer apply it): an information flow is carried only by an information interface, and an energy or material flow only by a physical one. An organisational interface carries no flow by itself — it fixes who does what and when, not how the data get across — so a report produced under a procedure still needs an information interface, or a recorded relay path over information interfaces. MITRE’s advice is written for ICT interfaces; the course applies it to all three types (instructor extension). Establish the interface-description framework early, during design. Describe every interface with the same set of attributes, including the business process or data flow it supports and not only its technical details. Agree service levels for interface performance (The MITRE Systems Engineering Guide, “Interface Management”, p. 413). Use an interface control working group for issues that engineer-to-engineer contact cannot resolve (The MITRE Systems Engineering Guide, “Interface Management”, p. 414). MITRE also warns that loosely coupled architectures need more governance, not less, because interfaces sprawl (The MITRE Systems Engineering Guide, “Interface Management”, p. 412).`,`The N² matrix. As a design aim, SEBoK’s physical-architecture article says a candidate architecture may aim at reducing the number of physical interfaces (SEBoK v2.14, “Physical Architecture”, p. 599). Its practices table adds that modularity means maximum consistency inside an element and a minimum of physical interfaces with the outside, and recommends focusing on interfaces rather than on elements at abstract levels (SEBoK v2.14, “Physical Architecture”, p. 603). The N² matrix is the tool that makes interfaces countable. SEBoK’s System Integration article (required extract SEBoK v2.14, “System Integration”, p. 630–631) names the N-squared diagram as one of the most basic methods for defining integration aggregates and the order of integration. In the integration context the coupling matrix is reorganised to group implemented elements into aggregates so that the number of interfaces to be verified between aggregates is minimised, and the matrix then helps locate faults (SEBoK v2.14, “System Integration”, p. 630–631). That is the integration analogue of the design aim, not the design aim itself: SEBoK v2.14, “System Integration” is about elements that already exist.`,`Course N² conventions (instructor-defined). Elements sit on the diagonal. In the interface N², an off-diagonal cell lists the IF IDs joining two elements, with the type. Interfaces are two-ended, so each IF is written once, above the diagonal, and the matrix is read as symmetric. In the functional N² the matrix is directed: row = producing function, column = consuming function, and the cell lists the flow. Counting an interface N² gives the number of interfaces, the number of each type, and the number per element (its degree). Each interface has two ends, so the degrees always sum to twice the number of interfaces — a useful arithmetic check.`],citations:[{reading:`R57`,pages:`410–414`},{reading:`R20c`,pages:`597, 599, 603`},{reading:`R22`,pages:`630–631`}],provenance:`mixed`},{id:`w8-information`,kind:`concept`,title:`Concept: information management, data versus information, and the decision an item serves`,paragraphs:[`SEBoK describes information management as helping teams access and manage information over its life cycle, so that it is relevant, complete, verified, protected, distributed and managed. Quoting ISO/IEC/IEEE 15288, its purpose is to generate, obtain, confirm, transform, retain, retrieve, disseminate and dispose of information to designated stakeholders. The INCOSE handbook adds that the information provided should be unambiguous, complete, verifiable, consistent, traceable and presentable (SEBoK v2.14, “Information Management”, p. 510). Among the business objectives the article lists is support for analytics and decision-making (SEBoK v2.14, “Information Management”, p. 511).`,`Data versus information. The terms are often used interchangeably, and the standards SEBoK cites distinguish them in slightly different ways (SEBoK v2.14, “Information Management”, p. 511). The article synthesises a working definition. Data are raw, unstructured values; information is structured data in context that has been analysed and interpreted (SEBoK v2.14, “Information Management”, p. 512). An information asset is any piece or collection of information that has to be managed on its own. Metadata — data about data, such as title, author, provenance and status — organise the information base and support its governance (SEBoK v2.14, “Information Management”, p. 512–513). The owner and provenance tags you have attached to every AeroLink element since Week 2 are metadata in exactly this sense. Information security is part of the same process. It starts by defining sensitive information, such as information that identifies an individual (SEBoK v2.14, “Information Management”, p. 514), and AeroLink’s passenger information (INFO-001) is such an item.`,`Producer → consumer → decision (course method, instructor-authored). An information item belongs in the architecture only if someone uses it to decide something. For each INFO the course records a producer, a consumer and the decision supported. The producer is the element that generates or obtains it. The consumer is the element or person who receives it. The decision is the choice that changes because of it, ideally naming the REQ or DEC it serves. This is how RB-7.5 separates flows from flows-without-decisions. It also turns SEBoK v2.14, “Information Management”’s “designated stakeholders” and “decision-making” into something you can check. If you cannot name the decision, either the item is data that has not yet been turned into information, or nobody needs it.`,`Information flows also check the physical view. Data flowing from PHY-001 to PHY-004 must cross an information interface (the course coverage rule above). If no information IF joins the producer and the consumer — none at all, or only an organisational agreement or a physical connection — either an interface is missing or the flow is relayed through other elements over information interfaces, and the route should be recorded. The tracer this week flags exactly that.`],citations:[{reading:`R21`,pages:`510–514`}],provenance:`mixed`},{id:`w8-worked-viewpoints`,kind:`worked-example`,title:`Worked example (a): three viewpoints of AeroLink and what each is for`,paragraphs:[`Start from the concerns, not the diagrams (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 344). Three stakeholders ask three different questions of the same architecture. A vertiport operator (STK-005) asks how an arriving aircraft gets back into service. A system designer asks which transformations every trip needs, whoever performs them. The board and the investors (STK-003) ask what must be bought and connected. Each question defines a viewpoint, and the table shows the view the reference builds for it. The rows are consistent with each other: the operational view’s steps are realised by the functional view’s FNs, which are allocated to the physical view’s PHYs. MITRE’s advice to identify the information views share and to manage it centrally (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345) is what the IDs make possible.`,`Reading the table across one row shows why a single picture fails. The operational view of SCN-003 (aircraft charging) has a vertiport operator, an arriving aircraft and a turnaround clock. It does not care that charging is controlled by LOG-002. The functional view has FN-006 Charge aircraft and FN-007 Control vertiport charging power, linked by a flow of power share. It does not care which building hosts them. The physical view has PHY-001, PHY-003 and EXT-002, joined by IF-005 and IF-006. A diagram that tries to show all three at once shows none of them clearly. The logical view (LOG-001..007, the S04 Lab 5 elements) is the bridge between the functional and physical views. It names the responsibilities — Fleet Management performs FN-006, FN-007 and FN-009 — without choosing the hardware.`],table:{caption:`AeroLink viewpoints (course convention, RB-7.1), reference content; all values FICTIONAL`,header:[`Viewpoint`,`Main concern and stakeholders`,`View content (reference IDs)`,`Purpose: what it lets the stakeholder conclude`,`Source anchor`],rows:[[`Operational`,`How a trip, a turnaround or a disruption unfolds; STK-001 passengers, STK-005 vertiport operators, STK-007 ANSP`,`SCN-002 nominal mission, SCN-003 charging, SCN-005 weather disruption; actors EXT-001..006`,`Whether the service works for its users and partners, step by step, including alternate flows`,`The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341, 345 (operational views; start from operational concepts)`],[`Functional`,`Which transformations every trip needs, independent of the solution; systems engineers`,`FN-001..014 derived from CAP-001..010, with their input-output flows`,`Whether every capability is covered by functions with defined inputs and outputs`,`SEBoK v2.14, “Functional Architecture”, p. 580–581; SEBoK v2.14, “System Architecture Design Definition”, p. 571`],[`Logical (bridge)`,`Which responsibilities exist, without choosing hardware; architects`,`LOG-001..007 performing the FNs (e.g. LOG-002 performs FN-006, FN-007, FN-009)`,`Whether responsibilities are coherent before technologies are chosen`,`SEBoK v2.14, “System Architecture Design Definition”, p. 571 (logical configuration items)`],[`Physical`,`What is bought, built and connected; STK-003 investors, integrators`,`PHY-001..008 with IF-001..014, FN → PHY allocation matrix`,`Whether the elements and interfaces can implement the functions within the requirements`,`SEBoK v2.14, “Physical Architecture”, p. 597–598; SEBoK v2.14, “System Architecture Design Definition”, p. 571`]]},citations:[{reading:`R62`,pages:`341–345`},{reading:`R20a`,pages:`580–581`},{reading:`R19`,pages:`571`},{reading:`R20c`,pages:`597–598`}],provenance:`mixed`},{id:`w8-worked-allocation`,kind:`worked-example`,title:`Worked example (b): decomposing from capabilities and allocating FN → LOG → PHY with justification`,paragraphs:[`Scenarios first, then the tree. Following SEBoK’s proven practice (SEBoK v2.14, “Logical Architecture”, p. 594), start from behaviour, not from a tree. Walk SCN-002 Passenger Transport Mission step by step and ask what must be transformed at each step, input to output. Step 1 needs FN-003 Plan flight (assigned trip → route and energy plan). Steps 2–3 need FN-012 Coordinate flight intent (route and time → ANSP acceptance). Step 4 needs FN-014 Board and alight passengers. Steps 5–6 need FN-005 Fly passenger trip (release, passengers, energy → completed trip). The scenario’s precondition, “forecast weather within limits”, comes from SCN-005, which adds FN-004 Assess dispatch weather (forecasts → holds). Its other precondition, “aircraft dispatch-ready”, needs FN-011 Dispatch aircraft (assignment, plan, holds, go/no-go → release). Only now group the flight-related functions under an unnumbered teaching parent, “Manage flight operations” (the F0 of this branch). Each leaf is a verb with an object, each has inputs and outputs, and none names who performs it (SEBoK v2.14, “Logical Architecture”, p. 587, 594). The decomposition stops here because a physical solution for each leaf can be imagined. Splitting FN-005 into take-off, cruise and landing would add depth without changing any allocation, which is the “decomposition too deep” pitfall (SEBoK v2.14, “Logical Architecture”, p. 594).`,`A tree is not a derivation. A function’s place under a teaching parent and its derives-from links are different relationships, so copy the reference links, not the tree. In the reference, FN-003 and FN-012 derive from CAP-004 Flight operations within safety limits, and FN-004 from its child CAP-005 Weather-aware operations. FN-011 derives from CAP-002 Ride booking and dispatch and from CAP-004. FN-005 derives from CAP-001 On-demand passenger transport and CAP-007 Noise-managed vertiport operations, not from CAP-004: it sits under “Manage flight operations” because flying is a step of every flight, but it realises those two capabilities. In the editor, record each function’s capability and the scenario it was found in; RB-7.2 asks for functions “derived from capabilities and scenarios”. The reference now records both: FN-003, FN-005, FN-011, FN-012 and FN-014 derive from SCN-002, FN-004 from SCN-005, and so on for every function except FN-013 Forecast demand. No operational scenario exercises FN-013; it is a planning function, and the reference says so rather than inventing a link, so its “no scenario” advisory is explained, not ignored.`,`The worked chain FN-006 → LOG-002 → PHY-003. FN-006 Charge aircraft derives from CAP-003 Fleet charging management, and REQ-SYS-001 (charge to the dispatch threshold within 20 min) is allocated to it. The logical element LOG-002 Fleet Management performs it. LOG-002 is allocated to PHY-003 Charging Systems and PHY-004 Operations Center, because fleet management has both a field part (the chargers) and a planning part (availability, FN-009). FN-006 itself is allocated to PHY-003. The justification names two criteria from SEBoK v2.14, “Physical Architecture”, p. 598–599. First, the same flows: its inputs and outputs are energy and charge-state data that cross the aircraft ↔ charger interface IF-005, so the transformation sits where the flow is. Second, execution frequency: the charge-control loop runs in seconds at the charger and must not depend on the datalink to the operations centre. The course reads SEBoK v2.14, “Physical Architecture”’s “execution with close frequency level” as a response-time argument; that reading is the course’s, not SEBoK’s wording. The 20 minutes of REQ-SYS-001 is the performance allocated to FN-006, not the latency of that loop. The table gives six allocations of the reference with the criterion each one names and the ID it rests on.`,`One row of the table was a finding, and the reference was corrected because of it. FN-008’s allocation to the maintenance facility is well justified by dependability, but look at what crosses the boundary. REQ-SYS-008 requires the no-go flag within 2 min. In the first version of the reference, FN-008’s output, the go/no-go status that dispatch needs for the REQ-STK-006 interlock, reached the operations centre only across IF-004, an organisational work-order procedure, and the fault reports that feed FN-008 crossed no interface at all. A 2-minute safety interlock that rides on a procedure is as weak as a seconds-critical charger loop routed through the operations centre. The independent review reported both as gaps under the course coverage rule, and the reference now closes them with two information interfaces. IF-012 (maintenance ↔ operations centre data) carries the go/no-go and maintenance status; IF-004 stays as the agreed procedure. IF-013 (aircraft ↔ maintenance health data link) carries the fault reports directly, so that flagging a no-go fault does not depend on the dispatch platform being up (R-007). The review also found that AI-001, which performs part of FN-008, was hosted at the operations centre. It is now allocated to the maintenance facility with FN-008, and its charge-session input reaches it by a recorded relay over IF-010 and IF-012 (worked example d). The lesson for your own model: a well-justified allocation is still incomplete until every flow it creates has a carrier of the right type.`,`Use the architecture editor below to record your team’s functions (with capability and scenario), allocations, function-to-function flows, interfaces and information items. It screens function names that name a solution element or a performer (“Charging system control”, “Technician repairs aircraft”) and justifications that name no criterion or cite no ID. Screening catches common errors; it cannot judge whether a well-formed argument is right. The editor records owner and provenance on every element and shows the L8 completeness checks and the allocation matrix. Switch the check view to the instructor reference. It passes every required check and raises two advisories, each explained in the model: PHY-006 Communications Infrastructure has no interface of its own (taken up in worked example c), and FN-013 records no scenario because it is a planning function. The first version raised two more, FN-008 (its performer AI-001 hosted on another element) and all 14 functions (no scenario recorded); both were corrected. Record yours.`],table:{caption:`Reference allocations FN → LOG → PHY with the named criterion (SEBoK v2.14, “Physical Architecture”, p. 598–599); FICTIONAL`,header:[`FN (derived from)`,`Performed by`,`Allocated to`,`Requirement allocated to the FN`,`Justification: criterion named and the ID it rests on`],rows:[[`FN-006 Charge aircraft (CAP-003)`,`LOG-002 Fleet Management`,`PHY-003 Charging Systems`,`REQ-SYS-001`,`Same flows: energy and charge-state data cross IF-005 at the pad. Close execution frequency: the charge-control loop runs in seconds at the charger and must not depend on the datalink (REQ-SYS-001 is the allocated 20-min performance).`],[`FN-002 Match request to aircraft (CAP-002)`,`LOG-005 Scheduling`,`PHY-004 Operations Center`,`REQ-SYS-005`,`Centralised control: one network-wide assignment meets the 60-s assignment time (REQ-SYS-005, DEC-002).`],[`FN-008 Assess aircraft health (CAP-006)`,`LOG-003 Maintenance Management`,`PHY-005 Maintenance Facility`,`REQ-SYS-008`,`Dependability: certifying technicians and diagnostic tools are at the facility, and release to service is their decision (REQ-SYS-008). Its go/no-go output reaches dispatch over information interface IF-012, added after the review found only organisational IF-004 (see text).`],[`FN-010 Detect and report pad fire (CAP-009)`,`LOG-007 Vertiport Operations`,`PHY-008 Pad fire detection and alarm system`,`REQ-SYS-009`,`Dependability (safety): detection must be at every pad and must not depend on the operations centre being up; the alarm leaves over IF-007 (REQ-SYS-009).`],[`FN-001 Accept ride request (CAP-002)`,`LOG-004 Customer Services`,`PHY-007 Passenger booking platform`,`REQ-STK-001`,`Same flows: passenger-facing information exchange over IF-008; similar technology (app and back end) (REQ-STK-001).`],[`FN-014 Board and alight passengers (CAP-001)`,`LOG-007 Vertiport Operations`,`PHY-002 Vertiports`,`REQ-STK-007`,`Same flows (material) and proximity: passengers move between terminal and cabin at the vertiport on the step-free route (REQ-STK-007).`]]},citations:[{reading:`R20b`,pages:`587, 594`},{reading:`R20c`,pages:`598–599`}],provenance:`mixed`},{id:`w8-worked-n2`,kind:`worked-example`,title:`Worked example (c): the N² of AeroLink’s physical interfaces, typed and counted`,paragraphs:[`The reference has eight physical elements (PHY-001..008) and fourteen interfaces (IF-001..014). IF-010 to IF-014 were added after the Week 8 review (worked examples b and d). Four of the interfaces reach external elements: EXT-001 ANSP, EXT-002 utility grid, EXT-003 weather and EXT-006 emergency services. The N² therefore has 12 elements on its diagonal. Each interface is entered once, in the cell above the diagonal, with its type. The table lists every element’s row of the matrix as the interfaces it takes part in; the N² tool below draws the full 12 × 12 grid.`,`Arithmetic (pinned by the module’s tests). By type: physical IF-001, IF-005 and IF-006 (3); information IF-002, IF-003, IF-007, IF-008 and IF-010 to IF-014 (9); organisational IF-004 and IF-009 (2); total 3 + 9 + 2 = 14. External: IF-003, IF-006, IF-007 and IF-011 (4); internal: 10. Degrees: PHY-004 9, PHY-001 4, PHY-002 3, PHY-003 3, PHY-005 3, PHY-007 1, PHY-008 1, EXT-001 1, EXT-002 1, EXT-003 1, EXT-006 1 and PHY-006 0. The sum is 28 = 2 × 14, which checks the count. Two pairs are joined twice: PHY-004–PHY-005 by IF-004 (organisational) and IF-012 (information), and PHY-002–PHY-004 by IF-009 (organisational) and IF-014 (information). So 12 of the 12 × 11 / 2 = 66 possible element pairs are joined, and the matrix density is 12 / 66 = 18.2 %. (The first version, IF-001..009, had 9 interfaces, PHY-004 degree 5 and density 9 / 55 = 16.4 %.)`,`Interpretation. First, the operations centre is the hub: PHY-004 takes part in 9 of the 14 interfaces (64 %). It is therefore the element whose failure or change touches most of the architecture, which is exactly the single point of failure that DEC-002’s hot standby addresses (R-007). The review’s corrections made the hub busier: four of the five added interfaces end at PHY-004, and the fifth, IF-013, was added partly so that the no-go path does not depend on it. Second, a pair joined twice is not redundancy. IF-004 says who withdraws and returns aircraft; IF-012 carries the data. Each needs different management: an agreement with an owner on each side, and a data definition with a service level. Third, PHY-006 Communications Infrastructure has degree 0. The reference describes IF-002, IF-010, IF-012, IF-013 and IF-014 as running over the communications infrastructure, but the N² records each as a direct interface between the elements that exchange, so the medium is invisible. That is a modelling choice, and the N² exposes it. Either each of those interfaces is split through PHY-006 (PHY-001 ↔ PHY-006 and PHY-006 ↔ PHY-004, and so on), or PHY-006 is treated as the medium of the interfaces rather than as an end. The reference chose the second and records the reason in PHY-006’s own description, so its “no interface” advisory is explained rather than ignored. A team should make the choice deliberately and record it. Fourth, IF-005 is typed physical although it also carries charge-state data. The course types an interface by its primary exchange (energy here) and lists everything it carries. The coverage rule used by the tools is stricter: it counts an information flow as carried only by an information interface. A team that wants the charge-state handshake to count as carried should split it into its own information interface, which is also the right choice if the two are managed by different parties.`],table:{caption:`Reference interface N², written row by row (each IF once; P physical, I information, O organisational). FICTIONAL`,header:[`Element`,`Interfaces (partner, type)`,`Degree`],rows:[[`PHY-001 eVTOL Aircraft`,`IF-001 PHY-002 (P); IF-002 PHY-004 (I); IF-005 PHY-003 (P); IF-013 PHY-005 (I)`,`4`],[`PHY-002 Vertiports`,`IF-001 PHY-001 (P); IF-009 PHY-004 (O); IF-014 PHY-004 (I)`,`3`],[`PHY-003 Charging Systems`,`IF-005 PHY-001 (P); IF-006 EXT-002 (P, external); IF-010 PHY-004 (I)`,`3`],[`PHY-004 Operations Center`,`IF-002 PHY-001 (I); IF-003 EXT-001 (I, external); IF-004 PHY-005 (O); IF-008 PHY-007 (I); IF-009 PHY-002 (O); IF-010 PHY-003 (I); IF-011 EXT-003 (I, external); IF-012 PHY-005 (I); IF-014 PHY-002 (I)`,`9`],[`PHY-005 Maintenance Facility`,`IF-004 PHY-004 (O); IF-012 PHY-004 (I); IF-013 PHY-001 (I)`,`3`],[`PHY-006 Communications Infrastructure`,`— (the medium of IF-002, IF-010, IF-012, IF-013 and IF-014; no interface of its own)`,`0`],[`PHY-007 Passenger booking platform`,`IF-008 PHY-004 (I)`,`1`],[`PHY-008 Pad fire detection and alarm system`,`IF-007 EXT-006 (I, external)`,`1`],[`EXT-001 ANSP · EXT-002 Utility grid · EXT-003 Weather · EXT-006 Emergency services`,`IF-003 (I) · IF-006 (P) · IF-011 (I) · IF-007 (I)`,`1 each`]]},citations:[{reading:`R22`,pages:`630–631`},{reading:`R20c`,pages:`599`}],provenance:`mixed`},{id:`w8-worked-info`,kind:`worked-example`,title:`Worked example (d): information flows from producer to consumer to decision`,paragraphs:[`The five reference information items are the S04 Lab 8 list. For each one the table records the producer, the consumer, the decision supported and the interface the flow crosses. Read INFO-003 Maintenance Data from left to right. The maintenance facility (PHY-005) and the chargers’ charge-session records (PHY-003) produce it. Dispatch at the operations centre (PHY-004) and the predictive-maintenance capability AI-001, hosted at the maintenance facility, consume it. The decision it supports is release or withhold an aircraft, which is what REQ-STK-006 and REQ-SYS-008 constrain. In SEBoK v2.14, “Information Management”’s terms (p.512), the raw fault codes and cell temperatures are data. The go/no-go status and AI-001’s ranked list of at-risk packs are information, because they have been analysed and interpreted for the release decision.`,`Tracing finds gaps that neither a function list nor an element list would show. When the review traced the first version of the reference (IF-001..009), five producer–consumer pairs had no information interface joining them. Three had no interface at all: INFO-002 PHY-001 → PHY-005 (flight data and fault reports to maintenance), INFO-003 PHY-003 → PHY-004 (charge-session records to dispatch) and INFO-004 EXT-003 → PHY-004 (weather to decision support). Two were joined only by an organisational agreement: INFO-001’s boarding timestamps PHY-002 → PHY-004 across IF-009, the pad-slot agreement, and INFO-003’s maintenance records PHY-005 → PHY-004 across IF-004, the work-order handover. An agreement says who reports what; it does not carry the data. Each gap needed an information interface of its own or a recorded relay over information interfaces. The reference now has an interface for each, IF-014, IF-013, IF-010, IF-011 and IF-012, and the tracer reports no advisory on it. Two of the choices are worth copying. INFO-002’s fault reports could have been relayed (aircraft to operations centre over IF-002, then on to maintenance over IF-012), but the direct IF-013 keeps the no-go path off the dispatch platform (R-007). INFO-003’s charge-session records for AI-001 do take a relay, PHY-003 → PHY-004 → PHY-005 over IF-010 and IF-012, and the relay is recorded on INFO-003 so that a reviewer can check every hop. The tracer checks element-to-element pairs only, so the recorded relay is what makes that route reviewable: an unrecorded relay cannot be told apart from a gap. INFO-005 Financial Data is the opposite case: its consumer is a decision record (DEC-001), not an element, which is legitimate for an item that feeds the board’s capacity decision.`,`Use the information-flow tracer below. Its practice set is a peer team’s information view with seeded defects. Predict which items fail before you trace, then trace your own workspace and the reference. Part 2 asks you to classify six AeroLink statements as data or information.`],table:{caption:`Reference information items: producer → consumer → decision (FICTIONAL)`,header:[`INFO`,`Producer`,`Consumer`,`Decision supported`,`Information interface crossed (course coverage rule)`],rows:[[`INFO-001 Passenger Information`,`PHY-007 booking platform; PHY-002 boarding gates`,`PHY-004 scheduling; AI-002`,`Which aircraft to assign to a request, and when (REQ-SYS-005); wait monitoring (MOE-001)`,`From PHY-007: IF-008. From PHY-002: IF-014 (added; before the review only organisational IF-009 — gap)`],[`INFO-002 Flight Data`,`PHY-001 aircraft`,`PHY-004 flight following; PHY-005 maintenance (health and fault reports)`,`Whether the next leg can be dispatched with the energy reserve (REQ-SYS-003)`,`To PHY-004: IF-002. To PHY-005: IF-013 (added; none before — gap)`],[`INFO-003 Maintenance Data`,`PHY-005; PHY-003 charge-session records`,`PHY-004 dispatch; AI-001 (at PHY-005)`,`Release or withhold an aircraft (REQ-STK-006, REQ-SYS-008)`,`From PHY-005: IF-012 (added; before, only organisational IF-004 — gap). From PHY-003: IF-010 (added; none before — gap). To AI-001: recorded relay PHY-003 → PHY-004 → PHY-005 over IF-010 and IF-012`],[`INFO-004 Weather Data`,`EXT-003 weather`,`PHY-004 decision support`,`Place or lift a vertiport dispatch hold (REQ-SYS-004)`,`IF-011 (added; none before — gap)`],[`INFO-005 Financial Data`,`PHY-007 fare revenue; LOG-002 operating cost`,`DEC-001 capacity investment`,`How much capacity to add and when (DEC-001)`,`not applicable (decision record)`]]},citations:[{reading:`R21`,pages:`510–512`}],provenance:`mixed`},{id:`w8-sysml`,kind:`worked-example`,title:`Worked example (e) and micro-lab 3: from the architecture to SysML v2 — requirement, subject, constraint and satisfy`,paragraphs:[`From Week 9 every Week 8 artefact becomes a model element. The course reference model realises them as follows. An FN becomes an action usage. LOG and PHY elements become part usages carrying their IDs as short names. An IF becomes an interface usage that connects two compatible ports. An INFO becomes an item definition carried by ports. The course link “LOG performs FN” becomes perform: perform identifies its owner as the performer of an action (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 41). “FN allocated-to PHY” becomes an allocation … allocate. “PHY satisfies REQ” becomes satisfy. Two definitions from the training material matter here. A port definition defines the features a part makes available through a port, and two ports are compatible for connection if their directed features match with inverse directions; the ~ prefix uses the conjugate port definition, which reverses inputs and outputs (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 20–21). An interface definition is a connection definition whose ends are ports, and an interface usage connects two compatible ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22). Listing 2 (aerolink_if005_allocation.sysml) shows the worked chain FN-006 → LOG-002 → PHY-003 and IF-005 in exactly these terms. ChargingPort has an out item energy. The aircraft’s chargeInlet is typed ~ChargingPort, so its energy feature is an input.`,`Reading listing 1 (aerolink_charge_requirement.sysml). Read the micro-lab extract first: Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–91 (six slides) and OMG SysML v2.1 Beta 2, Part 1, p. 168. Lines 20–26 declare REQ-SYS-001 as a requirement usage. A requirement is a kind of constraint, and its doc comment carries the informal “shall” text. The short name <'REQ-SYS-001'> is also its requirement ID (OMG SysML v2.1 Beta 2, Part 1, p. 165). Line 23 declares the subject. A requirement is always about some subject, here the charging system, and features of the subject can be used in the requirement (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87; OMG SysML v2.1 Beta 2, Part 1, p. 166). That is a permission, not a restriction: line 25 also uses maxChargeTime, the requirement’s own parameter, which is not a feature of the subject — just as the slide’s own example uses massReqd. Line 24 binds that parameter to 20 [min], as a requirement usage typically binds its parameters to specific values (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 89). Line 25 is the required constraint. Formally, a requirement is satisfied for a subject if, whenever all its assumed constraints are true, all its required constraints are true too (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 91; OMG SysML v2.1 Beta 2, Part 1, p. 165). This requirement has no assumptions.`,`Now do micro-lab 3 below, before you open the commentary that follows it. Classify the marked elements, answer what line 28 asserts, and then look at the teaching listing invalid_wrong_subject.sysml: it is listing 1 with one decision changed. Find the error yourself, and write down both what the checker catches and what it would not catch.`],sysml:[{file:`week08/aerolink_charge_requirement.sysml`,caption:`Listing 1 — REQ-SYS-001 with subject, required constraint and satisfy by PHY-003 (FICTIONAL values)`,intent:`conformant`},{file:`week08/aerolink_if005_allocation.sysml`,caption:`Listing 2 — the worked chain FN-006 → LOG-002 → PHY-003 with ports and interface IF-005`,intent:`conformant`},{file:`week08/invalid_wrong_subject.sysml`,caption:`Teaching listing — find the error (the requirement’s subject is the aircraft)`,intent:`intentionally-invalid`}],citations:[{reading:`R74`,pages:`86–91`},{reading:`R83`,pages:`165–166`},{reading:`R71`,pages:`20–22`},{reading:`R72`,pages:`41`}],provenance:`mixed`},{id:`w8-sysml-commentary`,kind:`worked-example`,title:`Worked example (e), continued: commentary on micro-lab 3 — read after the activity`,paragraphs:[`What line 28 asserts. satisfy 'REQ-SYS-001' by aeroLink.'PHY-003'; is a satisfy requirement usage. Its subject is bound to the satisfying feature PHY-003, and it is a kind of assert constraint usage. So it asserts that the requirement is satisfied, that is, that the constraint evaluates to true when the subject is PHY-003 (OMG SysML v2.1 Beta 2, Part 1, p. 168; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 91). It is not a wish, a plan or a test result. It is the model claiming that the design meets the requirement. The claim rests on PHY-003’s current estimate of 18 [min] (line 16, TPM-001, FICTIONAL). The evidence will come from verification (VER-001, Week 12). The reference implementation checks syntax, name resolution and its own validation rules; it does not evaluate constraints. When the author changed 18 [min] to 22 [min] in a scratch copy, the checker still reported PASS with no diagnostic. A model can therefore assert something false and still be “valid”, and review and verification exist to catch exactly that. SysML v2 also lets you write not satisfy, which asserts that a requirement is not satisfied by a feature (OMG SysML v2.1 Beta 2, Part 1, p. 168). You will not need it at CP4, but it shows that satisfy is a truth claim.`,`The invalid listing. invalid_wrong_subject.sysml is listing 1 with the subject changed to the aircraft. The reference implementation reports “Couldn’t resolve reference to Element ‘chargeTimeToDispatch’” at line 17, column 33. The reason is name resolution and nothing more: the feature chain aircraft.chargeTimeToDispatch does not resolve, because EVTOLAircraft has no feature of that name. There is no rule that a constraint may use only features of its subject — Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87 grants a permission, and listing 1 itself uses the requirement parameter maxChargeTime. A requirement’s constraint is normally written over its subject’s features so that the satisfy binding means something: when line 28 binds the subject to PHY-003, the constraint then reads PHY-003’s charge time.`,`What the checker would not catch. The checker does not enforce the choice of subject or of satisfier. Three probes by the author (scratch files run with the course checker, 2026-10-11; not course listings) show it. (1) Give EVTOLAircraft an attribute that happens to be called chargeTimeToDispatch, and the wrong-subject requirement PASSes with no diagnostic. (2) Keep the aircraft as subject but write the constraint around it, on aeroLink.'PHY-003'.chargeTimeToDispatch, and satisfy it by the aircraft: PASS, no diagnostic, although the satisfy now asserts nothing about the aircraft at all. (3) Keep listing 1 but write satisfy 'REQ-SYS-001' by aeroLink.'PHY-001' — an aircraft, not a charger — and the checker reports PASS with one WARNING, “Bound features should have conforming types”, because a subject typed ChargingSystems is bound to an EVTOLAircraft. The architecture lesson is therefore about review, not enforcement. Choosing a requirement’s subject and its satisfier is an allocation decision that the team must justify and a reviewer must check. A warning is not a pass to ignore: in Week 10, RB-8.1 asks for zero warnings or warnings explained. These are the course’s SysML v2 texts: SysML v2.1 Beta 2 (OMG SysML v2.1 Beta 2, Part 1) and the pilot-release 2026-08 training material (Seidewitz, Intro to the SysML v2 Language: Textual Notation), not a final standard.`],citations:[{reading:`R83`,pages:`168`},{reading:`R74`,pages:`87, 91`}],provenance:`mixed`},{id:`w8-advanced`,kind:`advanced`,title:`Advanced analysis: comparing two allocation alternatives with an explicit coupling metric`,paragraphs:[`The question. DEC-002 records one architecture decision. It hosts scheduling and dispatch on one operations platform with a hot standby, rather than distributing dispatch to the vertiports. (Its first version also named booking, although the reference allocates FN-001 Accept ride request to the booking platform PHY-007; the review reported the mismatch, and the text now names scheduling and dispatch only.) The rationale is qualitative: one network-wide assignment for REQ-SYS-005, with the standby removing the single point of failure (R-007). Can the N² make that comparison quantitative? SEBoK v2.14, “Physical Architecture” lists reducing the number of physical interfaces among the aims of a candidate physical architecture, and modularity among its practices (SEBoK v2.14, “Physical Architecture”, p. 599, 603). SEBoK v2.14, “System Integration” later uses the same coupling matrix in integration, to group implemented elements so that the interfaces to be verified between aggregates are minimised (SEBoK v2.14, “System Integration”, p. 631) — the integration analogue of the design aim. Neither source defines a numerical metric, so the course defines one and labels it as the course’s.`,`Metric (instructor-defined). Take the directed functional N² over the function-to-function flows. The teaching set has 19 flows, F01–F19, over 13 of the reference functions; FN-010’s flows go only to an external element. The set is instructor-defined and FICTIONAL, and the N² tool lists it. Given an allocation, a flow is internal if both its functions sit on the same PHY and crossing otherwise. A crossing flow is one that some interface must carry. Then E = flows counted; X = crossing flows; κ = X / E, the share of the functional traffic that crosses a physical boundary; P = the number of PHY pairs joined by at least one crossing flow, each of which needs a direct interface or a recorded relay path — so P is an upper bound on the direct interfaces the allocation needs, not a minimum; and D_max = the largest number of such partners of any one PHY. The same tool computes these numbers from your own recorded functions, physical elements and function-to-function flows (“My workspace”).`,`Results (pinned by tests). Alternative A is the reference allocation. Ten flows cross (F01, F02, F10, F11, F12, F13, F14, F15, F17, F18) and nine stay internal, so κ = 10 / 19 = 0.526. P = 7 pairs, and D_max = 4, shared by PHY-001 and PHY-004. Alternative B is distributed dispatch, the option DEC-002 rejected: FN-002 Match and FN-011 Dispatch move to the vertiports (PHY-002). Now 16 flows cross and 3 stay internal, so κ = 16 / 19 = 0.842. P = 8 pairs and D_max = 5, at PHY-002. The six flows F03, F04, F05, F07, F08 and F09 now all cross the new PHY-002 ↔ PHY-004 boundary, because dispatch still needs the plan, the holds, the forecast and the flight-intent acceptance produced centrally. On every count A is less coupled, which supports DEC-002 with a number rather than an adjective. The two moves contribute equally: moving only FN-011 back to the operations centre gives κ = 14 / 19 = 0.737, and so does moving only FN-002 back, so each function adds four crossing flows when it is moved to the vertiports. Checked against the reference interfaces with the course coverage rule, every crossing pair of A has an interface of the matching type, and four of B’s eight pairs have none. Against the first version (IF-001..009) the counts were three and seven. The five interfaces added after the review were designed for A, which is one more reason why this comparison favours A.`,`What the metric cannot see (graduate analysis). First, it counts flows, not their criticality. F10, the go/no-go status, is one flow, but it carries a safety interlock (REQ-STK-006); a flow-weighted or criticality-weighted κ could rank the alternatives differently. Second, PHY-002 aggregates six sites. Distributed dispatch would also need site-to-site coordination to keep one network-wide assignment, and those flows are invisible when the six sites are one element. The metric therefore flatters alternative B. Third, a lower κ concentrates traffic in one element. Alternative A’s hub, PHY-004, is exactly where the availability risk R-007 sits. SEBoK lists modularity (low interdependence) and resilience (highly reliable, maintainable or replaceable elements) as separate aims (SEBoK v2.14, “Physical Architecture”, p. 599); that they can pull in different directions here is the course’s reasoning, not SEBoK’s statement. Fourth, crossing flows are not yet interfaces. In the first version of the reference, three crossing pairs of A had flows that no interface of the matching type carried: PHY-001–PHY-005 (F17, no interface), PHY-003–PHY-004 (F11, no interface) and PHY-004–PHY-005 (F10 and F18, only the organisational IF-004). The third is the go/no-go gap of worked example (b). The same gaps appeared in the information trace, and the reference was corrected with IF-013, IF-010 and IF-012. Alternative B still has four such pairs: PHY-001–PHY-002 (F12, the flight release, over the physical IF-001 only), PHY-002–PHY-003 (F11), PHY-002–PHY-005 (F10) and PHY-002–PHY-007 (F01, F02). B would need its own interface design before the two could be compared fairly. Fifth, the flow set itself is not neutral. The 19 flows were written over the functions of the central-dispatch reference (for example F19, assignment from FN-002 to FN-011, and F04, the availability list), so comparing A and B on that set favours A. A genuinely different alternative may need different functions and flows, and DEC-002’s own rationale (REQ-SYS-005, R-007) is not what κ measures. The graduate task asks you to run this comparison on your own team’s two alternatives, state the metric before the numbers, and say which of these five limits could change your conclusion.`],table:{caption:`Coupling of two allocation alternatives over the 19 instructor-defined flows (metric and flows instructor-defined; FICTIONAL)`,header:[`Metric`,`A — reference (central dispatch)`,`B — distributed dispatch`,`Arithmetic`],rows:[[`E flows counted`,`19`,`19`,`All 13 functions allocated in both`],[`X crossing flows`,`10`,`16`,`A: F01, F02, F10–F15, F17, F18; B: all except F06, F16, F19`],[`κ = X / E`,`0.526`,`0.842`,`10 / 19; 16 / 19`],[`P element pairs joined by a crossing flow (direct interface or relay needed)`,`7`,`8`,`A: 007–004, 005–004, 003–004, 001–004, 001–002, 001–003, 001–005`],[`D_max most partners`,`4 (PHY-001, PHY-004)`,`5 (PHY-002)`,`Partners counted over the P pairs`],[`Crossing pairs with flows no interface of the matching type carries`,`0 (3 against the first version IF-001..009: PHY-001–PHY-005, PHY-003–PHY-004, PHY-004–PHY-005)`,`4 of 8: PHY-001–PHY-002 (only physical IF-001), PHY-002–PHY-003, PHY-002–PHY-005, PHY-002–PHY-007 (7 of 8 against IF-001..009)`,`Course coverage rule against IF-001..014, which were designed for A`]]},citations:[{reading:`R22`,pages:`631`},{reading:`R20c`,pages:`599, 603`}],provenance:`mixed`},{id:`w8-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`SEBoK’s worked example of model-based architecture is an automobile powertrain (SEBoK v2.14, “System Architecture Design Definition”, p. 576–577). A stakeholder capability need, “Drive Vehicle”, contains a function, “Control Vehicle Acceleration”. That function is allocated to a logical and a physical powertrain subsystem made of the engine, drivetrain and wheel assemblies, each interacting with its neighbours by exchanging torque. The context includes external interfaces to the driver, the road environment, a mechanic’s diagnostic tool and a fuel or charging station (SEBoK v2.14, “System Architecture Design Definition”, p. 577). AeroLink’s structure is the same. CAP-003 contains FN-006, which is allocated to LOG-002 and to PHY-003. The charging station of the car example is AeroLink’s IF-005 to the aircraft and IF-006 to the grid. In the course’s reading, the example also shows what a design model is for: decomposition and allocation are how a team checks that every capability is implemented and every interface is identified.`,`Interface standards are one of the strongest drivers of a physical architecture when several systems must share it. SEBoK’s examples run from nuts and bolts and rail gauges to TCP/IP and modular defence and space systems (SEBoK v2.14, “Physical Architecture”, p. 596). For an urban air-mobility operator, the aircraft ↔ charger interface (IF-005) is the obvious candidate. A team that adopts an interface standard there gains suppliers and fleet flexibility. It also inherits a constraint that should appear as an interface requirement. MITRE’s interface-management practices — set up the framework early, adopt standards, publish interface information in one accessible place, and run an interface control working group with the partners (The MITRE Systems Engineering Guide, “Interface Management”, p. 413–415) — are written for ICT interfaces. They apply directly to the data interfaces with the ANSP (IF-003) and the emergency services (IF-007); applying them to the utility’s power connection (IF-006) is the course’s extension.`,`Finally, the N² is not only a design tool. In integration it is used to choose aggregates and the order of integration, and to help locate faults when an aggregate fails a test (SEBoK v2.14, “System Integration”, p. 630–631). AeroLink’s PHY-004 hub, with nine of the fourteen reference interfaces, is the obvious aggregate to integrate and verify early — a point that will return in Week 12 (verification). MITRE’s advice that architectures help judge alternatives and as-is versus to-be migration paths (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345) is the use your CP3 defence will make of this week’s views.`],citations:[{reading:`R19`,pages:`576–577`},{reading:`R20c`,pages:`596`},{reading:`R57`,pages:`413–415`},{reading:`R22`,pages:`630–631`},{reading:`R62`,pages:`345`}],provenance:`mixed`},{id:`w8-lab`,kind:`lab`,title:`Lab L8 — architecture concept, and SysML reading micro-lab 3`,paragraphs:[`Session 2 gives 55 minutes to L8 and 20 minutes to micro-lab 3; the rest of L8 is done out of class (≈ 3.5 h each). Start from your CP2 baseline and the alternative your L7 trade study recommended: that alternative fixes the physical scope. Record your PHY, FN (with capability and scenario), function-to-function flows, IF, INFO and AI elements with the architecture editor (worked example b), using the stable ID scheme and with an owner and provenance on each. Use the N² tool to type and count your interfaces, and the tracer to check that every INFO names its decision and crosses an information interface. Micro-lab 3 is individual, closed-AI and read-only: complete the SysML reading activity in worked example (e), write the two answers it asks for, and copy them into your review notebook as the entry “Micro-lab 3”.`],citations:[],provenance:`instructor-authored`},{id:`w8-deliverable`,kind:`deliverable`,title:`Deliverable and assessment: CP3 Trade Study & Architecture Concept`,paragraphs:[`CP3 (team, 9 % of the course grade: RB-6 45 · RB-7 45 · RB-12 10) combines your revised L7 trade study with the L8 architecture concept. It is due at the end of Week 8, and each team defends it in five minutes at the start of Week 9; the defence informs RB-6.6 and RB-7.4. Graduate students also submit an individual coupling memo, a required review-notebook entry that is always read, and the set-based half of the Week 7 graduate memo is due at the same time. Readiness quiz Q7 is the knowledge check below.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w8-act-editor`,title:`Architecture and allocation editor with L8 completeness checks`,component:`w08-architecture-editor`,purpose:`Record PHY, FN (derived from a CAP, found in a SCN, and allocated with a justification that names its criterion and the ID it rests on), function-to-function flows, IF (typed, both ends), INFO (producer, consumer, decision) and AI elements in the workspace with owner and provenance, and see the L8 acceptance checks and the FN → PHY allocation matrix.`,instructions:[`Record your physical elements first (at least six, including the six S04 Lab 6 elements).`,`Walk your scenarios first, then record at least six functions, each derived from a capability, linked to the scenario it was found in, and allocated to a PHY. Write a justification that names its criterion and cites an ID; the editor screens out one that does not, but it cannot judge whether the argument is right.`,`Record the main function-to-function flows between your functions (kind and item); the N² tool and the graduate memo compute coupling from them.`,`Record at least five interfaces covering all three types, and at least three information items with their decisions. Record the two AI capabilities with inputs, outputs, oversight and failure considerations.`,`Switch the checks to the instructor reference and compare: which two advisories does the reference raise, how does the reference explain each, and do you agree?`],objectives:[`B8.2`,`B8.3`,`B8.4`],inBlock:`w8-worked-allocation`},{id:`w8-act-n2`,title:`N² matrix and coupling of two allocation alternatives`,component:`w08-n2-coupling`,purpose:`Build the typed interface N² of the reference or of your workspace, count interfaces by type and per element, and compare two FN → PHY allocations with the course coupling metric (κ, P, D_max).`,instructions:[`Part 1: confirm the reference counts (14 interfaces: 3 physical, 9 information, 2 organisational) and identify the element with no interface. Then switch to your workspace.`,`Part 2: predict which alternative is less coupled, then compute. Explain the difference by naming the flows that cross in one alternative but not the other, and read the typed gap list for each alternative: why does A have no gap on PHY-004–PHY-005 while it would have one if IF-012 were removed, although IF-004 joins the same two elements?`,`Mutation: move one function and predict how κ and P change before you recompute.`,`Graduate task: switch to “My workspace”. Alternative A is your recorded allocation; set B to your second candidate. The tool computes both from your own recorded flows and checks crossings against your own typed interfaces. Use the results in your memo.`],objectives:[`B8.2`,`B8.3`],inBlock:`w8-worked-n2`},{id:`w8-act-info`,title:`Information-flow tracer and data-or-information classifier`,component:`w08-info-tracer`,purpose:`Trace each information item from producer to consumer to decision, predict which items fail the L8 rule, and classify AeroLink statements as data or information.`,instructions:[`On the peer sample, tick the items you expect to fail, then trace. Explain each miss.`,`Trace your own workspace and fix every ✗ before submitting CP3. For each “!” advisory, add an information interface or record the relay path over information interfaces.`,`Classify the six statements in Part 2 and check.`],objectives:[`B8.4`],inBlock:`w8-worked-info`},{id:`w8-act-sysml`,title:`Micro-lab 3: reading a requirement and what satisfy asserts`,component:`w08-satisfy-reading`,purpose:`Classify the roles of nine marked elements in the validated listing (requirement, ID, subject, parameter, constraint, satisfy, satisfying feature, design value) and state what the satisfy asserts.`,instructions:[`Read the extract first: Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–91 and OMG SysML v2.1 Beta 2, Part 1, p. 168 (about 10 minutes).`,`Classify every marked element, then check.`,`Answer “What does line 28 assert?” before opening the commentary block that follows this activity.`,`Explain in two sentences why invalid_wrong_subject.sysml is rejected and what the checker would not have caught. Write both answers in the activity and copy them into your review notebook (entry “Micro-lab 3”).`],objectives:[`B8.5`],inBlock:`w8-sysml`}],lab:{id:`L8`,title:`Architecture concept; SysML reading micro-lab 3`,setting:`team`,durationMinutes:75,objectives:[`B8.1`,`B8.2`,`B8.3`,`B8.4`,`B8.5`],inputs:[`CP2 baseline (REQ-STK/REQ-SYS with parents, MOE/MOP/TPM, AROU v2) and the CAP and SCN elements from CP1`,`The L7 recommendation (DEC) that fixes the physical scope of the architecture`,`S04 Lab 5 logical elements, Lab 6 physical elements and Lab 8 information items (official names)`,`Architecture editor, N² tool and information-flow tracer (this week); validated SysML listings in sysml/week08/`],steps:[{title:`Operational view`,detail:`From your scenarios (SCN), draw the operational view of the nominal mission and one disruption: actors, sequence and the external elements involved. State its purpose and the stakeholder concern it serves (RB-7.1; The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341, 344).`},{title:`Functional decomposition`,detail:`Walk your scenarios (SCN) step by step first and list the function each step needs; build the decomposition tree only afterwards (SEBoK v2.14, “Logical Architecture”, p. 594: scenarios of functions before the tree). Record at least 6 FN, each derived from a capability (derives-from CAP) and linked to the scenario it was found in (derives-from SCN). Verb + object, inputs and outputs stated, no performer named; stop where a physical solution can be imagined (SEBoK v2.14, “Logical Architecture”, p. 587, 594; RB-7.2 “derived from capabilities and scenarios”).`},{title:`Physical elements`,detail:`Record at least 6 PHY, including the six S04 Lab 6 elements, plus the elements your L7 decision adds.`},{title:`Allocation matrix`,detail:`Allocate every FN to a PHY with a justification that names its criterion and cites the ID it rests on (SEBoK v2.14, “Physical Architecture”, p. 598–599). Show the FN → PHY matrix; every row has an allocation (L8 acceptance). Record the main FN → FN flows (kind and item).`},{title:`N² and interfaces`,detail:`Record at least 5 IF covering physical, information and organisational types, each with both ends and what it carries. Build the N², count by type and per element, and state one finding (a hub, an isolated element, a missing interface, or a flow that only an organisational agreement “carries”).`},{title:`Information flows`,detail:`For at least 3 INFO record producer, consumer and the decision supported (with its REQ or DEC ID). Run the tracer and resolve every ✗; for each “!” declare an information interface or record the relay path over information interfaces (RB-7.5).`},{title:`AI capabilities and decisions`,detail:`Record at least 2 AI capabilities with inputs, outputs, human oversight and failure considerations (RB-7.6), and at least one architecture DEC with the alternatives considered (RB-7.4).`},{title:`Micro-lab 3 (20 min, individual, closed-AI)`,detail:`Before the session read Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–91 and OMG SysML v2.1 Beta 2, Part 1, p. 168. Complete the SysML reading activity, write one sentence on what the satisfy asserts, and explain the invalid listing in two sentences (why it is rejected, and what the checker would not have caught). Copy both into your review notebook as the entry “Micro-lab 3” (formative). Read-only: no modelling tool is used this week.`}],artefacts:[{idPrefix:`FN`,description:`Functions derived from capabilities and found in scenarios, allocated to PHY with a justification naming the criterion and the ID it rests on; FN → FN flows recorded`,minimum:`≥ 6, every one allocated`},{idPrefix:`PHY`,description:`Physical elements, including the six S04 Lab 6 elements`,minimum:`≥ 6`},{idPrefix:`IF`,description:`Interfaces typed physical / information / organisational, with both ends and what they carry`,minimum:`≥ 5, all three types`},{idPrefix:`INFO`,description:`Information items with producer, consumer and the decision supported`,minimum:`≥ 3, each with a decision`},{idPrefix:`AI`,description:`AI-enabled capabilities with inputs, outputs, human oversight and failure considerations`,minimum:`≥ 2`},{idPrefix:`DEC`,description:`Architecture decision with alternatives considered and rationale`,minimum:`≥ 1 (besides the L7 DEC)`}],continuity:`L8 is the architecture half of CP3 (due end of Week 8; RB-7 45 % of CP3), defended at the start of Week 9 (RB-7.4). In Week 9 every FN, LOG, PHY, IF and INFO is mapped by ID to a model package (L9). In Week 10 the FN → PHY matrix becomes allocate relationships, the IFs become port and interface definitions, and each REQ-SYS gets a satisfy (L10, CP4). The INFO decisions feed the digital-thread audit in Week 12, and the N² hub and its interfaces are the starting points of the Week 13 impact analysis.`,tools:[{label:`Architecture editor, N² tool and tracer (this week)`,to:`/week/8`},{label:`AeroLink engineering model workspace (FN, PHY, IF, INFO, AI)`,to:`/workspace/model`},{label:`Air Taxi Enterprise workspace (case brief and Data Sheet)`,to:`/workspace/aerolink`}]},assignment:{id:`CP3`,title:`CP3 Trade Study & Architecture Concept (team) and graduate coupling memo (individual)`,mode:`team`,due:`CP3: end of Week 8; 5-minute team defence at the start of Week 9 · Graduate memo: end of Week 8`,weight:`CP3 9 % of the course grade (RB-6 45 · RB-7 45 · RB-12 10) · Graduate memo: required review-notebook entry, always read (RB-16)`,instructions:[`Team: submit one CP3 package with the sections below. Part A is your L7 trade study, revised in response to the Week 7 formative feedback. Part B is the L8 architecture concept. Include the workspace export with your FN, PHY, IF, INFO, AI and DEC elements, each with an owner and a provenance tag.`,`Minimum scope (syllabus §11). Trade study: ≥ 3 ALT including a baseline; ≥ 4 CRIT traced to MOE; value scales; swing weights; sensitivity on the top 2 weights; recommendation. Architecture: operational, functional and physical views; ≥ 6 FN; ≥ 6 PHY; allocation matrix; N² with ≥ 5 IF; information flows for ≥ 3 INFO; ≥ 2 AI capabilities.`,`Defence (Week 9, 5 minutes per team, 8 teams): 2 minutes on the recommendation and the condition that would reverse it, 2 minutes on the architecture (one view, the N² finding, one architecture DEC), and 1 minute of questions. The defence informs RB-6.6 and RB-7.4.`,`Graduate (individual, about one page plus a table): compare two allocation alternatives for your team’s architecture with an explicitly defined N² coupling metric. Define the metric before giving numbers, and label which parts are your own definitions and which are taken from the course (the κ, P and D_max definitions and the flow set are instructor-defined). Compute both alternatives with the N² tool in “My workspace” mode — it reads your recorded functions, physical elements, typed interfaces and FN → FN flows, takes your recorded allocation as A and lets you set B — or by hand from the same flow list. Interpret the difference by naming the flows responsible, and state which limitation of the metric — criticality, aggregation, concentration, crossings without a matching interface, or a flow set written for one alternative — could change the conclusion.`,`Graduate (individual, carried over from Week 7): Part 2 of the Week 7 memo — compare your point-based trade with a set-based treatment (SEBoK v2.14, “Set-Based Design”, p. 1396–1399: set drivers and set modifiers, the feasible sets after the requirement screen, and whether set-based design would change or defer your recommendation) — is due at the end of Week 8 with the coupling memo. Its time is budgeted in this week.`,`Individual (all students): micro-lab 3 notebook entry, closed-AI — one sentence on what line 28 of listing 1 asserts and two sentences on the invalid listing (formative; feedback before Week 10).`,`Log your hours in the review notebook (workload pilot).`],template:[{heading:`A1. Trade study summary (revised L7)`,guidance:`Decision statement, ≥ 3 ALT including the baseline, ≥ 4 CRIT with MOE traces, value functions, swing weights with range-based rationale, value table, and what you changed after the Week 7 feedback (RB-6.1–6.4).`},{heading:`A2. Sensitivity and recommendation`,guidance:`Reversal points for the top two weights with new winner and feasibility; recommendation with conditions, residual risk by R- ID and what would change it (RB-6.5–6.6).`},{heading:`B1. Viewpoints`,guidance:`Operational, functional and physical views, each with its purpose and the stakeholder concern it answers; state the course convention you follow (RB-7.1; The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341–345).`},{heading:`B2. Functional decomposition`,guidance:`The scenario walk-through first (which SCN steps produced which FN), then ≥ 6 FN derived from CAP, each with the SCN it was found in; verb + object, inputs and outputs, no physical names; one decomposition shown from a parent function to leaves, built after the scenarios (RB-7.2 “derived from capabilities and scenarios”; SEBoK v2.14, “Logical Architecture”, p. 587, 594).`},{heading:`B3. Allocation matrix and justification`,guidance:`FN → PHY matrix with every FN allocated; for each allocation the criterion named (shared flows, technology, control, execution frequency, dependability, proximity, interfaces) and the ID it rests on (REQ served, IF or INFO crossed) (RB-7.3; SEBoK v2.14, “Physical Architecture”, p. 598–599). The main FN → FN flows listed with their kind.`},{heading:`B4. N² and interfaces`,guidance:`N² with ≥ 5 IF typed physical / information / organisational (and external flagged), both ends, what each carries; counts by type and per element with the arithmetic check; one finding (RB-7.3).`},{heading:`B5. Information flows`,guidance:`≥ 3 INFO with producer, consumer and decision supported (with ID); data distinguished from information; for each flow, the information interface it crosses or the recorded relay path (an organisational agreement does not carry data) (RB-7.5; SEBoK v2.14, “Information Management”, p. 510–514).`},{heading:`B6. AI capabilities and architecture decisions`,guidance:`≥ 2 AI with inputs, outputs, human oversight and failure considerations (RB-7.6); ≥ 1 architecture DEC with alternatives considered and rationale (RB-7.4).`},{heading:`C. AI usage statement`,guidance:`Tool, purpose, example prompts, outputs, what you accepted or rejected and why; every AI-suggested element tagged AI-suggested-reviewed and checked by its owner (RB-12.1–12.3).`},{heading:`D. Graduate memo (individual)`,guidance:`Metric defined first (course-defined and own parts labelled); your own flow set stated; both alternatives computed with arithmetic (tool output or by hand); difference explained by named flows; one of the five limitations that could change the conclusion (formative RB-16.1; RB-7.3 for the N² content).`}],rubrics:[`RB-6`,`RB-7`,`RB-12`,`RB-16`],rubricScope:`CP3: RB-6.1–6.6 (45 %), RB-7.1–7.6 (45 %), RB-12.1–12.3 (10 %); the Week 9 defence informs RB-6.6 and RB-7.4. Graduate task: always read (RB-16 graduate-task rule) and scored formatively on RB-16.1 (engineering reasoning: metric defined, computed and interpreted, limits named) as the primary criterion, with RB-7.3 (typed interfaces, complete allocation) for the N² content of the comparison. The Week 7 memo Part 2 is read against RB-16.1 as stated in Week 7.`,aiUse:`AI tools may be used to brainstorm candidate functions, interfaces and information items, and to critique a draft view. Every AI-suggested element is tagged AI-suggested-reviewed, owned by a named team member and checked against your capabilities, requirements and the Data Sheet (RB-12.3). Allocation justifications and the architecture DEC must be the team’s own reasoning. Micro-lab 3 is closed-AI: explain the listing yourself.`,objectives:[`B8.1`,`B8.2`,`B8.3`,`B8.4`,`B8.5`]},quiz:[{id:`q8-1`,bloom:`Apply`,objective:`B8.1`,prompt:`AeroLink’s insurer (STK-012) asks: “If a battery catches fire on a pad, who is alerted, by what, and how quickly?” Which view should the team show first?`,options:[{id:`a`,text:`The physical view, listing PHY-008 and its attributes`,correct:!1,explanation:`It names the equipment but not the sequence of who is alerted and when, which is the insurer’s concern. It is the second view to show, to trace the scenario to the elements.`},{id:`b`,text:`An operational view of the pad-fire scenario: actors (vertiport staff, emergency services EXT-006), the alert sequence and its timing, then traced to the elements that implement it`,correct:!0,explanation:`Correct. A view exists to address a stakeholder’s issues, and should help that stakeholder conclude whether their objectives are met (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 341, 344). The insurer’s question is operational.`},{id:`c`,text:`The functional view only, because functions are solution-independent`,correct:!1,explanation:`FN-010 states what must be transformed, but not who is alerted or how quickly; it does not answer the stated concern.`},{id:`d`,text:`The complete architecture, because one model contains every view`,correct:!1,explanation:`MITRE’s first rule is that purpose is paramount: generate the views the purpose needs (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 344). A complete model is not a view for this stakeholder.`}],cite:{reading:`R62`,pages:`341, 344`}},{id:`q8-2`,bloom:`Analyse`,objective:`B8.1`,prompt:`A team’s CP3 “architecture” is one diagram with 31 boxes: passengers, “dispatch”, the booking app, “charge aircraft”, the ANSP, the chargers and “weather check”, joined by unlabelled lines. Which critique is best supported?`,options:[{id:`a`,text:`It is fine: one integrated picture is easier to keep consistent than three`,correct:!1,explanation:`Consistency comes from sharing identified data between views (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345), not from drawing everything once; the mixed diagram cannot answer any one stakeholder’s question.`},{id:`b`,text:`It mixes actors, functions and physical elements in one large node diagram; split it into operational, functional and physical views, each with its purpose, and replace the lines with typed, identified interfaces`,correct:!0,explanation:`Correct. MITRE warns against complicated node-connectivity diagrams and says to start from operational concepts (The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, p. 345); RB-7.1 and RB-7.3 ask for views with purposes and typed interfaces.`},{id:`c`,text:`Add colours for each kind of box and keep the single diagram`,correct:!1,explanation:`Colour does not separate concerns, and colour alone must not carry meaning; the problem is the mixture, not its styling.`},{id:`d`,text:`Remove the actors, because external elements do not belong in an architecture`,correct:!1,explanation:`External elements and their interfaces belong in the physical architecture model (SEBoK v2.14, “Physical Architecture”, p. 597); the problem is mixing viewpoints.`}],cite:{reading:`R62`,pages:`345`}},{id:`q8-3`,bloom:`Understand`,objective:`B8.2`,prompt:`Which candidate list for the functional view of AeroLink’s fleet-health capability (CAP-006) contains functions and no physical names?`,options:[{id:`a`,text:`“Maintenance facility”, “Battery workshop”, “Diagnostic tablet”`,correct:!1,explanation:`These are physical elements (things), not transformations.`},{id:`b`,text:`“Collect fault reports”, “Classify faults as go / no-go”, “Plan maintenance slot”, “Return aircraft to service”`,correct:!0,explanation:`Correct. Each is an input-to-output transformation stated as a verb and object, with no performer named (SEBoK v2.14, “System Architecture Design Definition”, p. 571).`},{id:`c`,text:`“Maintenance software flags faults”, “Technician repairs aircraft”`,correct:!1,explanation:`Each names its performer (software, technician): that is allocation mixed into the functional view (RB-7.2).`},{id:`d`,text:`“Faults”, “Work orders”, “Spare packs”`,correct:!1,explanation:`These are items that flow between functions — inputs and outputs — not functions.`}],cite:{reading:`R19`,pages:`571`}},{id:`q8-4`,bloom:`Analyse`,objective:`B8.2`,prompt:`A team adds a new function, “Monitor battery cell temperature during charging”, which must stop a charge within seconds of a thermal event (R-008). Which allocation and justification is best?`,options:[{id:`a`,text:`PHY-004 Operations Center, because it already hosts seven functions and should host all monitoring`,correct:!1,explanation:`Convenience is not an affinity criterion, and a seconds-critical safety loop would then depend on the charger-to-operations-centre data link (IF-010) and on the operations centre being up.`},{id:`b`,text:`PHY-003 Charging Systems, because the cell data arrive over the charger’s battery-management handshake (IF-005) and the response must be local and fast — same flows, close execution frequency and dependability`,correct:!0,explanation:`Correct. It names affinity criteria SEBoK lists for partitioning and allocation: the same flows, execution frequency and dependability (SEBoK v2.14, “Physical Architecture”, p. 598–599).`},{id:`c`,text:`PHY-005 Maintenance Facility, because battery health is a maintenance concern`,correct:!1,explanation:`Maintenance acts after the event; the function’s execution-frequency and dependability criteria point to the element in the charging loop.`},{id:`d`,text:`Leave it unallocated until the physical design is complete`,correct:!1,explanation:`Allocation is how candidate physical architectures are formed (SEBoK v2.14, “Physical Architecture”, p. 598); an unallocated function fails the L8 acceptance rule.`}],cite:{reading:`R20c`,pages:`598–599`}},{id:`q8-5`,bloom:`Apply`,objective:`B8.2`,prompt:`In Week 8 a team allocates “Match request to aircraft” to “a Python service on cloud VM 2” and “Charge aircraft” to “charger model X-350”. What is the main problem?`,options:[{id:`a`,text:`Nothing: specific products make the allocation more concrete`,correct:!1,explanation:`Concreteness at this level fixes technologies before the logical and physical levels have been worked out, which is the pitfall SEBoK names (SEBoK v2.14, “Physical Architecture”, p. 602).`},{id:`b`,text:`It allocates functions directly to technologies (a software service, a charger model) at a high level of abstraction, instead of alternating logical and physical levels before reaching the technology level`,correct:!0,explanation:`Correct. SEBoK’s pitfall “direct allocation on technologies”: at a high level of abstraction, allocating functions onto the lowest-level technologies does not reflect a system comprehension; the right practice alternates logical and physical levels before the technology level (SEBoK v2.14, “Physical Architecture”, p. 602). It is a different pitfall from having no logical architecture at all.`},{id:`c`,text:`Functions may only be allocated to people, not to software or hardware`,correct:!1,explanation:`System elements can be hardware, software, people, processes and facilities (SEBoK v2.14, “Physical Architecture”, p. 597).`},{id:`d`,text:`Two functions can never share a physical element`,correct:!1,explanation:`Many functions can be allocated to one element; PHY-004 hosts seven in the reference.`}],cite:{reading:`R20c`,pages:`602`}},{id:`q8-6`,bloom:`Apply`,objective:`B8.3`,prompt:`A vertiport ground segment (FICTIONAL) has elements A pad, B charger, C fire detection, D boarding gate and E site controller. Interfaces: A–B cable route (physical), A–C sensor mounting (physical), B–E session data (information), C–E alarm (information), D–E boarding status (information), C–D evacuation procedure (organisational), B–C charger trip signal (information). In the N², how many interfaces are there, of which types, and which element has the most interface partners?`,options:[{id:`a`,text:`7 interfaces: 2 physical, 4 information, 1 organisational; C has the most (4)`,correct:!0,explanation:`Correct. Degrees A 2, B 3, C 4, D 2, E 3 sum to 14 = 2 × 7, which checks the count; C (fire detection) is the most coupled element.`},{id:`b`,text:`14 interfaces: 4 physical, 8 information, 2 organisational; C has the most (8)`,correct:!1,explanation:`This counts each interface twice, once in each triangle; an interface has two ends but is one interface.`},{id:`c`,text:`7 interfaces: 3 physical, 3 information, 1 organisational; E has the most (3)`,correct:!1,explanation:`The charger trip signal is information, not physical; and C has four partners (A, B, D, E), more than E.`},{id:`d`,text:`7 interfaces: 2 physical, 4 information, 1 organisational; E has the most (3)`,correct:!1,explanation:`The type counts are right, but C’s degree is 4 (A, B, D, E), higher than E’s 3.`}],cite:{reading:`R22`,pages:`630–631`}},{id:`q8-7`,bloom:`Apply`,objective:`B8.3`,prompt:`Using the course’s interface types (physical / information / organisational), which typing of three AeroLink interfaces is correct? (1) insurer ↔ AeroLink incident-reporting procedure; (2) aircraft ↔ pad tie-down points; (3) operations centre ↔ weather-service forecast feed.`,options:[{id:`a`,text:`(1) information, (2) physical, (3) information — a report is data`,correct:!1,explanation:`The interface is the agreed procedure and responsibilities between two organisations. The reports produced under it are information items; under the course coverage rule they need an information interface (or a recorded relay) of their own — the procedure says who reports what and when, it does not carry the data.`},{id:`b`,text:`(1) organisational, (2) physical, (3) information`,correct:!0,explanation:`Correct under the course convention (RB-7.3), which types an interface by what it exchanges: an agreed procedure between organisations, mechanical loads, and data. The typing is the course’s; SEBoK’s own table already counts protocols, procedures and documents as interfaces (SEBoK v2.14, “Physical Architecture”, p. 597).`},{id:`c`,text:`(1) organisational, (2) organisational, (3) physical — the feed is a cable`,correct:!1,explanation:`The forecast feed exchanges data; its transport medium does not change what the interface carries.`},{id:`d`,text:`All three are physical, so no typing is needed`,correct:!1,explanation:`SEBoK does call any binding between elements a physical interface (SEBoK v2.14, “Physical Architecture”, p. 597), but the course types interfaces because each type is managed differently (RB-7.3).`}],cite:{reading:`R20c`,pages:`597`}},{id:`q8-8`,bloom:`Evaluate`,objective:`B8.3`,prompt:`Two allocations of the same 20 function-to-function flows: in Alt 1, 6 flows cross element boundaries over 4 element pairs; in Alt 2, 9 flows cross over 3 pairs. With the course metric κ = X / E and the pair count (element pairs joined by a crossing flow), what is the best conclusion?`,options:[{id:`a`,text:`Alt 2 is better on every count`,correct:!1,explanation:`Alt 2 has the higher κ (9/20 = 0.45 against 0.30).`},{id:`b`,text:`Alt 1 has the lower κ (0.30 against 0.45) but needs more element pairs connected (4 against 3). The metrics disagree, so the team must say whether boundary traffic or the number of interfaces matters more here, and why`,correct:!0,explanation:`Correct. SEBoK lists reducing the number of physical interfaces as one aim of a candidate architecture (SEBoK v2.14, “Physical Architecture”, p. 599), while κ measures traffic across boundaries; when they disagree the choice is a judgement to record, not a computation.`},{id:`c`,text:`Alt 1 is better on every count`,correct:!1,explanation:`Alt 1 connects four element pairs against Alt 2’s three.`},{id:`d`,text:`κ cannot be computed without weighting each flow`,correct:!1,explanation:`The course metric is unweighted by definition; weighting by criticality is a refinement worth discussing, not a precondition.`}],cite:{reading:`R20c`,pages:`599`}},{id:`q8-9`,bloom:`Analyse`,objective:`B8.4`,prompt:`A new information item, “Pad-edge noise recordings”, is produced by microphones at the vertiports (PHY-002) and consumed at the operations centre (PHY-004). Which “decision supported” entry meets the L8 rule and RB-7.5?`,options:[{id:`a`,text:`“Noise monitoring and monthly reporting.”`,correct:!1,explanation:`It describes a use, not a choice that the information changes.`},{id:`b`,text:`“Whether to switch a vertiport to the quieter departure procedure for the rest of the day (REQ-STK-002).”`,correct:!0,explanation:`Correct. It names a choice, who makes it implicitly (operations) and the requirement it protects, so the item supports decision-making as SEBoK v2.14, “Information Management”, p. 511 describes.`},{id:`c`,text:`“Stored for future analysis.”`,correct:!1,explanation:`Retention is an information-management activity, not a decision; an item with no decision is a candidate for removal.`},{id:`d`,text:`“Supports good community relations.”`,correct:!1,explanation:`A goal, not a decision; nothing in it says what changes when the recordings arrive.`}],cite:{reading:`R21`,pages:`511`}},{id:`q8-10`,bloom:`Apply`,objective:`B8.4`,prompt:`Classify, using SEBoK’s synthesised definition: (1) “Charger 4 power readings every 15 min: 212.4, 215.0, 219.8 kW …”; (2) “Peak power at hub 2 will exceed the connection limit at about 17:30 unless one charge is deferred.”`,options:[{id:`a`,text:`(1) data, (2) information`,correct:!0,explanation:`Correct. Data are raw unstructured values; information is structured data in context that has been analysed and interpreted (SEBoK v2.14, “Information Management”, p. 512).`},{id:`b`,text:`Both data, because both contain numbers`,correct:!1,explanation:`Numbers are not the test; (2) is an interpretation of the readings against a limit, addressed to a decision.`},{id:`c`,text:`Both information, because both concern the chargers`,correct:!1,explanation:`Subject matter is not the test; (1) has not been analysed or put in context.`},{id:`d`,text:`(1) information, (2) data`,correct:!1,explanation:`Reversed: the forecast and recommendation are the interpreted product of the readings.`}],cite:{reading:`R21`,pages:`512`}},{id:`q8-11`,bloom:`Apply`,objective:`B8.4`,prompt:`A team records “Pad thermal alarm”, produced by the fire detection system (PHY-008) and consumed by the vertiport (PHY-002), supporting “Whether to evacuate the pad and stop charging (REQ-SYS-009)”. Its only interface between the two is IF-120 “Fire-system maintenance contract” (organisational). The tracer still flags the flow. What is the best response?`,options:[{id:`a`,text:`Ignore the advisory: an interface between PHY-008 and PHY-002 is declared, so the flow is covered`,correct:!1,explanation:`A maintenance contract fixes who services the detectors; it does not carry an alarm. Under the course coverage rule an information flow needs an information interface.`},{id:`b`,text:`Keep IF-120 as the organisational interface it is, and declare an information interface PHY-008 ↔ PHY-002 for the alarm signal (or record the relay path the alarm actually takes)`,correct:!0,explanation:`Correct. A physical interface in SEBoK’s sense can be a procedure or a document (SEBoK v2.14, “Physical Architecture”, p. 597), so the contract is a legitimate interface — but of a different kind. The course types interfaces by what they exchange, and the alarm is data that needs its own information interface or a recorded route.`},{id:`c`,text:`Retype IF-120 as an information interface so that the tracer passes`,correct:!1,explanation:`That makes the check pass while the model now says the contract carries the alarm. The agreement still needs an owner on each side, and the alarm still needs a carrier.`},{id:`d`,text:`Delete the information item, because pad safety is handled by the emergency services over IF-007`,correct:!1,explanation:`IF-007 joins PHY-008 to EXT-006; the vertiport’s own evacuate-and-stop decision still needs the alarm.`}],cite:{reading:`R20c`,pages:`597`}},{id:`q8-12`,bloom:`Understand`,objective:`B8.5`,prompt:`A listing declares requirement <'REQ-SYS-002'> with subject aircraft : EVTOLAircraft; attribute noiseLimit = 65 [dB]; require constraint { aircraft.padEdgeNoise <= noiseLimit }, and later satisfy 'REQ-SYS-002' by aeroLink.'PHY-001'; where PHY-001 binds padEdgeNoise = 63.5 [dB]. In the satisfy, what is bound to the subject, and what does the constraint then compare with 65 dB?`,options:[{id:`a`,text:`The definition EVTOLAircraft is bound to the subject, so the constraint compares every possible aircraft`,correct:!1,explanation:`The subject is bound to a feature (a usage) in the satisfy, not to a definition.`},{id:`b`,text:`The satisfying feature aeroLink.PHY-001 is bound to the subject aircraft, so the constraint compares PHY-001’s padEdgeNoise (63.5 dB) with 65 dB`,correct:!0,explanation:`Correct. A satisfy requirement usage binds its subject to the satisfying feature and asserts the requirement is satisfied for it (OMG SysML v2.1 Beta 2, Part 1, p. 168).`},{id:`c`,text:`noiseLimit is bound to the subject, so 65 dB is compared with itself`,correct:!1,explanation:`noiseLimit is a requirement parameter; the subject is the first, distinguished parameter (OMG SysML v2.1 Beta 2, Part 1, p. 166).`},{id:`d`,text:`Nothing is bound; satisfy only links the two names for traceability`,correct:!1,explanation:`satisfy is more than a trace link: it binds the subject and asserts the constraint holds (OMG SysML v2.1 Beta 2, Part 1, p. 168).`}],cite:{reading:`R83`,pages:`166–168`}},{id:`q8-13`,bloom:`Apply`,objective:`B8.5`,prompt:`In the same listing a student argues that noise is measured at the pad edge, so the vertiports should satisfy the noise requirement, and writes satisfy 'REQ-SYS-002' by aeroLink.'PHY-002'; where PHY-002 is typed VertiportNetwork, which also declares padEdgeNoise. The subject of REQ-SYS-002 is still aircraft : EVTOLAircraft. The course checker reports PASS with one warning, “Bound features should have conforming types”. Which statement is correct?`,options:[{id:`a`,text:`PASS means the model is correct; the warning is cosmetic`,correct:!1,explanation:`The checker resolved every name, which is all a PASS shows. The warning says the subject, typed EVTOLAircraft, has been bound to a VertiportNetwork: the satisfy asserts the requirement about the wrong kind of thing.`},{id:`b`,text:`The satisfy binds the requirement’s subject to the vertiports, whose type does not conform to EVTOLAircraft; the model now claims the noise requirement for the wrong element. Either satisfy it by the aircraft (the noise source), or, if the team really means a site limit, rewrite the requirement with the vertiports as subject — and explain the warning in review`,correct:!0,explanation:`Correct. A satisfy requirement usage binds its subject parameter to the satisfying feature and asserts the requirement holds for it (OMG SysML v2.1 Beta 2, Part 1, p. 168). The checker only warns about the type mismatch, so the choice of satisfier is a design decision that review must check.`},{id:`c`,text:`The checker evaluated the constraint and found that the vertiports meet 65 dB`,correct:!1,explanation:`The checker does not evaluate constraints; the warning is about types, not values.`},{id:`d`,text:`The warning means the requirement is not satisfied, so the line is equivalent to not satisfy`,correct:!1,explanation:`not satisfy is a different assertion that must be written explicitly (OMG SysML v2.1 Beta 2, Part 1, p. 168); a type warning does not negate the claim.`}],cite:{reading:`R83`,pages:`168`}},{id:`q8-14`,bloom:`Apply`,objective:`B8.5`,prompt:`A draft of REQ-SYS-002 declares subject vertiports : VertiportNetwork; attribute noiseLimit = 65 [dB]; and require constraint { vertiports.padEdgeNoise <= noiseLimit }, but padEdgeNoise is declared only in EVTOLAircraft. The checker reports that it cannot resolve padEdgeNoise. What is the best fix?`,options:[{id:`a`,text:`Add an import so that padEdgeNoise is found`,correct:!1,explanation:`The feature exists; it belongs to another type. An import does not make an aircraft feature a feature of the vertiport network.`},{id:`b`,text:`Make the subject the aircraft (subject aircraft : EVTOLAircraft), because the requirement is about the noise source; the constraint then reads a feature its subject actually has, so a satisfy by an aircraft means something`,correct:!0,explanation:`Correct. The error is name resolution: vertiports.padEdgeNoise does not resolve because VertiportNetwork has no such feature. Features of the subject can be used in the requirement (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87), and REQ-SYS-002 allocates the noise limit to the aircraft.`},{id:`c`,text:`Move noiseLimit into VertiportNetwork, because a requirement’s constraint may use only features of its subject`,correct:!1,explanation:`There is no such rule: Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87 says features of the subject can be used, a permission, and requirement parameters such as noiseLimit (or massReqd in the slide’s own example) are used too. Moving noiseLimit would not resolve padEdgeNoise either.`},{id:`d`,text:`Replace require constraint with assume constraint`,correct:!1,explanation:`An assumption would still refer to a feature the subject does not have, and would change the meaning of the requirement.`}],cite:{reading:`R74`,pages:`87`}},{id:`q8-15`,bloom:`Apply`,objective:`B8.5`,prompt:`To record that FN-008 is allocated to the maintenance facility, a student writes satisfy 'FN-008' by aeroLink.'PHY-005'; where FN-008 is an action. The checker rejects it with “Must reference a requirement.” Why?`,options:[{id:`a`,text:`Short names cannot be used after satisfy`,correct:!1,explanation:`The validated listing uses satisfy 'REQ-SYS-001' with a short name; the problem is what the name refers to.`},{id:`b`,text:`satisfy relates a requirement to a satisfying feature and asserts the requirement holds; an action is not a requirement. An allocation is recorded with allocate`,correct:!0,explanation:`Correct. A satisfy requirement usage asserts that a requirement is satisfied when its subject is bound to the feature (OMG SysML v2.1 Beta 2, Part 1, p. 168); allocating a function uses a different relationship (listing 2).`},{id:`c`,text:`PHY-005 must be a requirement as well`,correct:!1,explanation:`The satisfying feature is a design element; only the satisfied element must be a requirement.`},{id:`d`,text:`FN-008 must first be performed by a logical element`,correct:!1,explanation:`perform is unrelated to the error; the checker objects that the satisfied element is not a requirement.`}],cite:{reading:`R83`,pages:`168`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class: Session 1 concept studio (75 min) and Session 2 Lab L8 + micro-lab 3 (75 min)`,hours:2.5},{activity:`Readings SEBoK v2.14, “System Architecture Design Definition”, The MITRE Systems Engineering Guide, “Architectural Frameworks, Models, and Views”, The MITRE Systems Engineering Guide, “Interface Management”, SEBoK v2.14, “Information Management”, p. 510–514 (27 pp) plus the required extracts SEBoK v2.14, “Physical Architecture”, p. 598–599 and SEBoK v2.14, “System Integration”, p. 630–631 (4 pp) at ≈ 15 pp/h`,hours:2},{activity:`Micro-lab 3 SysML extract: Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–91 and OMG SysML v2.1 Beta 2, Part 1, p. 168 (6 slides + 1 page)`,hours:.2},{activity:`Online lesson and the four interactive activities (budgeted; realistic ≈ 1.4 h — see cautions)`,hours:.7},{activity:`Readiness quiz Q7 (knowledge check; budgeted; realistic ≈ 0.3 h)`,hours:.2},{activity:`L8 architecture concept (team share, out of class; lab plan figure)`,hours:3.5},{activity:`CP3 assembly (revise L7, integrate L8, AI statement) and defence preparation (budgeted; realistic ≥ 1.5 h)`,hours:.4},{activity:`Graduate coupling memo (individual; N² tool in workspace mode; budgeted; realistic ≈ 1.2 h)`,hours:.4},{activity:`Graduate: Week 7 memo Part 2, set-based comparison (SEBoK v2.14, “Set-Based Design”, p. 1396–1399, 4 pp, and writing), moved into Week 8 (budgeted; realistic ≈ 1.1 h)`,hours:.6}],references:[{reading:`R20a`},{reading:`R20b`},{reading:`R20c`},{reading:`R22`},{reading:`R35`,pages:`1396–1399`},{reading:`R71`},{reading:`R72`},{reading:`R74`,pages:`86–91`},{reading:`R83`,pages:`168`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},y=e({default:()=>b}),b={week:9,drivingQuestion:`AeroLink’s Part I baseline lives in tables, matrices and documents, and in the reference baseline its 20-minute charge is written into at least nine of them. What changes when it becomes one model — and can your team write that model so that the course-designated checker accepts it and a reviewer can trust what it says?`,blocks:[{id:`w9-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to B-CLO4 (a SysML v2 model that is valid in the course-designated checker and semantically correct), B-CLO5 (the digital thread kept by ID) and B-CLO6 (decisions defended in review). From this week your team’s Part I artefacts become elements of one model, written in the SysML v2 textual notation and checked by the OMG pilot implementation, release 2026-08 (the course-designated checker). The week opens with the CP3 defences, because the decisions you defend there are what the model must now carry.`],bullets:[`B9.1 (Understand) Explain what MBSE changes relative to document-based systems engineering, and the difference between a model and a view.`,`B9.2 (Understand) Explain definition versus usage, specialization, subsetting and redefinition, and read them correctly in a listing.`,`B9.3 (Apply) Create a package structure and part definitions and usages with ISQ/SI-typed attributes, accepted by the course-designated checker with zero errors.`,`B9.4 (Apply) Map the CP1–CP3 artefacts, by ID, to model packages, writing each ID as a correctly quoted short name.`,`B9.5 (Evaluate) Defend the CP3 trade and architecture decisions: the recommendation, the conditions that would reverse it, and the alternatives considered.`,`Graduate expectation (the memo is optional this week under course workload option B; the two graduate quiz items are not): apply the KerML semantics of specialization, subsetting and redefinition (OMG KerML v1.1 Beta 2, “7.3 Core”) to an AeroLink fragment, and separate what the checker enforces from what the semantics require.`],citations:[],provenance:`instructor-authored`},{id:`w9-intuition`,kind:`intuition`,title:`Intuition: a recipe card, tonight’s dinner, and one kitchen ledger`,paragraphs:[`A recipe card says what flatbread is. Tonight you use it twice — six small flatbreads for the soup, one large one with garlic for the table — and the card does not change. Each use lives in a context and adjusts the recipe, and neither use is a flatbread you could eat: they are roles flatbreads play in tonight’s meal. The card is a definition, each use a usage, and what comes out of the pan are instances. Mixing the three up is the commonest mistake in a first SysML model: a usage is not an instance.`,`Now suppose the kitchen keeps its shopping list, menu and allergy sheet as separate documents. Switch the flour and you must edit every document — and you will miss one. A kitchen that keeps one ledger and prints the sheets from it changes the recipe once; the sheets are views of the ledger. That is the change MBSE asks for. AeroLink’s 20-minute charge is written into at least nine Part I artefacts; this week you see what it takes to make it appear once.`],citations:[],provenance:`instructor-authored`},{id:`w9-mbse`,kind:`concept`,title:`What MBSE changes: models, modelling languages, tools — and model versus view`,paragraphs:[`SEBoK’s definitions of a model all treat it as a representation of selected aspects of a domain, chosen for a set of concerns and related to the system by a mapping; many models may be needed for one system of interest (SEBoK v2.14, “What is a Model?”, p. 290). Abstract models rely on a modelling language with an abstract syntax (constructs and rules), a concrete syntax (symbols or text) and semantics (meaning), and a modelling tool typically checks whether a model conforms to the language’s rules (SEBoK v2.14, “What is a Model?”, p. 291–292). That is exactly what the course-designated checker does, and nothing more.`,`In the INCOSE definition SEBoK quotes, MBSE is the formalized application of modelling to support requirements, design, analysis, verification and validation from the conceptual phase onward, with models as the primary, controlled artefacts where a document-centric approach manages documents (SEBoK v2.14, “What is a Model?”, p. 292). The main system model can serve as a single source of truth in a standardised language such as SysML (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 370); formality and abstraction matter most among model properties, and an effective model complies strictly with its language and describes at least the functional and structural architecture (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 370–371).`,`SEBoK credits MBSE with surfacing inconsistencies while the model is built, reducing miscommunication through one source, and letting verification and validation start earlier; digital models can also propagate change and generate documents — “if implemented appropriately” (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 373). The benefits shrink when the model falls out of date (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 373), and where stakeholders expect documents, these are generated from the model as static representations at milestones (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 374).`,`Model versus view. A system model may comprise multiple views (SEBoK v2.14, “Types of Models”, p. 300). In SysML v2 a viewpoint specifies information of interest to stakeholders, and a view specifies a query of the model and a rendering of the results to satisfy a viewpoint (OMG SysML v2.1 Beta 2, Part 1, p. 48); SysML v2 offers graphical, tabular and textual visualisations and a standardised API for other tools (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 7, sl.9). Your N² and allocation matrices and context diagram are views, produced from the model rather than kept beside it; the textual notation is one concrete syntax, and a diagram a rendering.`,`Two cautions. SEBoK’s MBSE article describes SysML as a graphical language with nine diagram types (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 372): that is SysML v1; SysML v2 has a new metamodel, formal semantics, and textual, graphical and tabular notations (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 7). And a high-quality model of a flawed chair accurately represents a chair that falls apart (SEBoK v2.14, “Why Model?”, p. 296).`],quote:{text:`The quality of a model should not be confused with the quality of the design that the model represents.`,cite:{reading:`R33b`,pages:`296`}},citations:[{reading:`R33a`,pages:`290–292`},{reading:`R28`,pages:`370–374`},{reading:`R33c`,pages:`300`},{reading:`R80`,pages:`48`},{reading:`R90`,pages:`7`},{reading:`R90`,pages:`9`},{reading:`R33b`,pages:`296`}],provenance:`mixed`},{id:`w9-worked-model-view`,kind:`worked-example`,title:`Worked example (a): one number in nine places — the 20-minute charge as a document set and as a model`,paragraphs:[`Suppose the charger supplier reports that charging from the 20 % reserve to the dispatch threshold will take 24 min, not 20 (a FICTIONAL what-if). The 20 min sits in at least nine reference artefacts (table): as the value itself, in values computed from it (REQ-STK-005’s 25 min turnaround = 20 + 5 min handling; A-007’s 48 charges per charger per day = 960 ÷ 20), and in conclusions resting on it (TECH-001; DEC-001).`,`The turnaround becomes 29 min, so REQ-STK-005 is missed. The aircraft cycle grows from 43 to 47 min (16 block + 29 turnaround + 2 positioning), so an aircraft flies 960 ÷ 47 × 0.90 ≈ 18.4 trips a day, and a charger manages 960 ÷ 24 = 40 charges. For ALT-004 (16 aircraft, 8 turnaround chargers) capacity is min(16 × 18.4, 8 × 40) ≈ 294 trips/day, below REQ-STK-004’s 300; DEC-001 rested on ALT-004 meeting it, so the trade study must be reopened.`,`In documents this impact analysis is a text search, and the risk is the place you do not find. In a model, chargeTimeToDispatch is one attribute of ChargingSystems (PHY-003); REQ-SYS-001 constrains it, MOP-002 is it, the other artefacts are related to it by relationships you can follow (Week 13), and each table is a view (OMG SysML v2.1 Beta 2, Part 1, p. 48). The checker does not recompute the 294: recomputing consequences needs an analysis in the model, the analytical side of a hybrid model (SEBoK v2.14, “Types of Models”, p. 299–300). That is the honest version of “MBSE propagates change” (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 373).`],table:{caption:`Where the 20-min charge lives in the reference baseline (FICTIONAL values), and what a 24-min charge does to each`,header:[`Artefact`,`How it depends on the 20 min`,`With 24 min`],rows:[[`REQ-SYS-001`,`The requirement value (≤ 20 min)`,`Not met by the supplier’s design`],[`MOP-002 / TPM-001`,`The measured quantity and its tracked estimate (18 min)`,`Estimate exceeds threshold`],[`VER-001`,`Test: restore within 20 min`,`Would fail`],[`REQ-STK-005`,`Turnaround 25 min = 20 min charge + 5 min handling`,`29 min: missed`],[`A-007`,`48 charges per charger per day = 960 ÷ 20`,`40 charges per day`],[`SCN-003`,`Main flow step 3: charge within 20 min`,`Scenario timing changes`],[`TECH-001`,`Benefit: sets the 25 min turnaround`,`Benefit claim no longer holds`],[`DEC-001 (ALT-004)`,`Capacity min(16 × 20, 8 × 48) = 320 ≥ 300`,`min(16 × 18.4, 8 × 40) ≈ 294 < 300`],[`REQ-STK-004`,`≥ 300 trips/day by month 24`,`Not met by the recommended alternative`]]},citations:[{reading:`R80`,pages:`48`},{reading:`R33c`,pages:`299–300`},{reading:`R28`,pages:`373`}],provenance:`mixed`},{id:`w9-language`,kind:`concept`,title:`The SysML v2 language: architecture, packages, names, and definition versus usage`,paragraphs:[`Language architecture. SysML v2 is built in four layers (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slides 3–4; Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 8). Root holds syntactic elements without model-level semantics (element, namespace, relationship, import). Core adds type, classifier, feature and multiplicity and relationships such as specialization, with a direct mapping to formal logic. Kernel completes the Kernel Modeling Language (KerML) with classes, data types, behaviours and connectors. Systems is SysML proper — definitions and usages of attributes, parts, ports, actions, requirements, views and more — with libraries that include ISQ, SI and ScalarValues (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 17). Most SysML elements specialize KerML elements (OMG SysML v2.1 Beta 2, Part 1, p. 47), which is why specialization, subsetting and redefinition are defined in KerML.`,`Packages and imports. A package is a namespace and a container for its owned members; an import adds one member or all members of another package; a name with spaces is quoted; a qualified name joins names with “::” (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 5; Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 17, sl.21). Members are public by default; a public import re-exports what it imports, a private one does not. In the 2026-08 notation every import’s visibility is written explicitly, and private is advised unless re-export is required (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 6), so the course model starts with private import ISQ::*; private import SI::*; private import ScalarValues::*;.`,`Names, short names and IDs. The tool’s element ID cannot be written in the notation; instead an element has a name and a short name, the short name between < and > before the name (OMG SysML v2.1 Beta 2, Part 1, p. 49; Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 22), described as “a user or tool selected id” (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 22). The course uses it for its IDs. A basic name starts with a letter or underscore, continues with letters, digits or underscores, and is not a reserved word; any other name is an unrestricted name in single quotes (OMG SysML v2.1 Beta 2, Part 1, p. 49–50). PHY-003 has hyphens, so its short name is <'PHY-003'>, and every reference quotes it too: Physical::aeroLink.'PHY-003'.`,`Definition and usage. A definition classifies a kind of element; a usage uses a definition in a context and is always defined by at least one definition of its kind, or implicitly by the most general one (OMG SysML v2.1 Beta 2, Part 1, p. 63). One definition can be used in many contexts (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 12). Usages nested in a definition are its features: a feature relates each instance of its featuring definition to values of its own definition, as a mass feature relates each vehicle to its mass (OMG SysML v2.1 Beta 2, Part 1, p. 63); a usage directly in a package is a generic feature that can be specialized in context (OMG SysML v2.1 Beta 2, Part 1, p. 64). So part aircraft : EVTOLAircraft[12] says that any AeroLink system has twelve aircraft values; it creates no aircraft. A part definition defines things that exist in space and time; an attribute definition defines data, may not have composite features, and its usages are referential (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 9; OMG SysML v2.1 Beta 2, Part 1, p. 77).`,`SysML v2 has no system, subsystem, assembly or component constructs: an entity with structure and behaviour is a part (OMG SysML v2.1 Beta 2, Part 1, p. 48). SysML v1’s blocks and value properties become part definitions and attribute usages; whether the checker tolerates the v1 words is one of your predictions two blocks below.`],citations:[{reading:`R70`,pages:`3–6`},{reading:`R70`,pages:`9`},{reading:`R90`,pages:`7–8`},{reading:`R90`,pages:`12`},{reading:`R90`,pages:`17–22`},{reading:`R80`,pages:`47–50`},{reading:`R80`,pages:`63–64`},{reading:`R80`,pages:`77`}],provenance:`mixed`},{id:`w9-relationships`,kind:`concept`,title:`Specialization, subsetting and redefinition — three relationships that look alike`,paragraphs:[`Specialization (subclassification). A specialized definition classifies a subset of what its general definition classifies, inherits its features and can add its own; a definition can specialize several; :> means specializes (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 10; OMG SysML v2.1 Beta 2, Part 1, p. 64, p.72). An abstract definition’s instances must also be instances of a concrete specialization (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 10; OMG SysML v2.1 Beta 2, Part 1, p. 72). In KerML terms, the extent of the specific type is a subset of the extent of the general one (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 53).`,`Subsetting. Subsetting asserts that, in any common context, the values of one feature are a subset of the values of another, written subsets or :> (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 11). The subsetting usage may constrain definition and multiplicity — OMG SysML v2.1 Beta 2, Part 1’s truck subsets its wheels with four named wheels — and it is an additional feature: the subsetted one is still there (OMG SysML v2.1 Beta 2, Part 1, p. 64).`,`Redefinition. Redefinition is a kind of subsetting in which the redefining usage replaces the redefined one in its context (OMG SysML v2.1 Beta 2, Part 1, p. 65). It can change the name, specialize the type or constrain the multiplicity of an inherited feature; :>> means redefines, and part redefines cyl[4] keeps the name (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 12). Usages can redefine inherited features “to any level of nesting” (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 15) and can be specialized by other usages, as smallVehicle :> vehicle (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 16). OMG SysML v2.1 Beta 2, Part 1’s truck redefines its fuel as DieselFuel, so its fuel must be diesel (OMG SysML v2.1 Beta 2, Part 1, p. 65); Seidewitz, Intro to the SysML v2 Language: Textual Notation binds a value to an inherited attribute by redefining it (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 13).`,`One symbol, two meanings. After a definition’s name, :> is specialization; after a usage’s name, it is subsetting, so what follows must be a feature. A usage’s three owned specializations are feature typing (:), subsetting (:>) and redefinition (:>>) (OMG SysML v2.1 Beta 2, Part 1, p. 72). An attribute, item, part or port usage owned by a definition or usage, with no explicit subsetting or redefinition, defaults to exactly one value; a package-level usage does not (OMG SysML v2.1 Beta 2, Part 1, p. 73). A redefinition restricts what it inherits — an engine with four to six cylinders redefined to four, or six (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 12); what goes wrong when one does not is for the graduate reading (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 61–62) and the advanced block.`],citations:[{reading:`R70`,pages:`10–13`},{reading:`R70`,pages:`15–16`},{reading:`R80`,pages:`64–65`},{reading:`R80`,pages:`72–73`},{reading:`R87`,pages:`53`},{reading:`R87`,pages:`61–62`}],provenance:`mixed`},{id:`w9-checker`,kind:`concept`,title:`What the course-designated checker decides — and what it cannot`,paragraphs:[`The course-designated checker is the OMG SysML v2 Pilot Implementation, release 2026-08 (Jupyter kernel 0.62.0, Java 21), published alongside the 2.1 Beta 2 texts this course cites; it is a pilot, not the formal SysML 2.0 specification. For each file it parses the text, resolves every name against the file and the standard library, and runs its validation rules. An ERROR fails the file; a WARNING does not, but RB-8.1 level 4 asks for zero warnings or warnings explained.`,`This app cannot run the checker. Each lesson listing was run by the course’s validation script and its result stored with the file’s SHA-256, so the app shows a recorded result for exactly the text on screen, never a simulated one. Your own model is checked only by the checker, in your installation and in the instructor’s grading run.`,`Calibrate your expectations now, before the worked examples: predict whether the checker passes each of eight short listings, and why, then reveal the recorded result. Note which files passed with a real modelling problem — they are what you must check yourself.`],citations:[],provenance:`instructor-authored`},{id:`w9-worked-semantics`,kind:`worked-example`,title:`Worked example (b): the vertiport network — definitions, usages, and ALT-004 as a configuration`,paragraphs:[`aerolink_def_usage.sysml models the vertiport network of PHY-002 so that the CP3 decision (DEC-001: convert a spoke into a fourth hub, ALT-004) is a configuration, not a new model. It is adapted from the reference skeleton; its values, including the charger ratings, are FICTIONAL. The checker accepted it with no messages.`,`Definitions (lines 11–36). Charger is abstract. HighPowerCharger and StandardCharger specialize it, and each redefines ratedPower to bind it for every charger of that kind (350 kW, 150 kW): the rating defines the kind, so it belongs in the definition. Vertiport is abstract and owns chargers : Charger[1..*]. HubVertiport adds turnaroundChargers : HighPowerCharger[2] subsets chargers — two of its chargers are turnaround chargers, still among its chargers. SpokeVertiport redefines chargers with type StandardCharger, so every charger at a spoke is standard. VertiportNetwork owns sites, and hubs and spokes that each subset sites.`,`Usages (lines 38–51). vertiportNetwork is a package-level usage: a generic network feature, not a network. baselineNetwork and alt004Network both subset it and redefine the multiplicities of their configuration — 6 sites, 3 hubs, 3 spokes; and 6, 4, 2 for ALT-004 — as smallVehicle and bigVehicle specialize vehicle (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 16). They are siblings: neither changes the other or the definitions (OMG SysML v2.1 Beta 2, Part 1, p. 65). Configuration values belong in usages; a value that defines a kind belongs in its definition.`,`Do the activity before reading the commentary: classify each marked token, and decide which of six statements the listing guarantees.`],sysml:[{file:`week09/aerolink_def_usage.sysml`,caption:`The AeroLink vertiport network: definitions, specialization, subsetting, redefinition, and two configurations as sibling usages (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R70`,pages:`10–16`},{reading:`R80`,pages:`64–65`}],provenance:`mixed`},{id:`w9-worked-semantics-commentary`,kind:`worked-example`,title:`Commentary on worked example (b): what the listing states, what it only entails, and how to state it`,paragraphs:[`First, :> on lines 14–28 follows a definition, so it is specialization; on lines 40 and 46 it follows a usage, so it is subsetting (OMG SysML v2.1 Beta 2, Part 1, p. 72). Second, the redefinitions on line 29 (type Charger to StandardCharger) and on lines 43 and 49 (multiplicity 1..* to 3 or 4) both restrict what they inherit.`,`Third, separate what the listing states from what it entails. It never states that no site is both a hub and a spoke, yet it entails it. Lines 15 and 18 bind different ratings, so nothing is both a HighPowerCharger and a StandardCharger; every charger at a spoke is a StandardCharger (line 29) and every hub has two HighPowerChargers among its chargers (line 26); so a site that were both would need chargers rated 350 kW and 150 kW at once. In each configuration the counts then do the rest: three hubs and three spokes, none shared, are all six sites (likewise 4 + 2). The definition alone gives no coverage — six sites, one hub and no spokes satisfies lines 32–36 — and the disjointness hangs on two instructor ratings: delete the bindings on lines 15 and 18 and it is gone. The checker reasons about neither: a probe declaring a part definition that specializes both HubVertiport and SpokeVertiport, which nothing can instantiate under this listing, passed with no message.`,`A property the design relies on should be stated, not left to an entailment a later edit can remove. KerML has disjoining and unioning for this (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 55–57), but the SysML notation the checker accepts has no such clause on definitions or usages: probes with disjoint … from …, unions … and a standalone disjoining were rejected as syntax errors. In SysML, state it as an asserted constraint over the features, as the standard library does for causes and effects: aerolink_network_stated.sysml asserts isEmpty(intersection(hubs, spokes)) and includesOnly(sites, union(hubs, spokes)). The checker resolves the names in such expressions (a probe with a misspelt feature failed) but does not evaluate them (a probe asserting more hubs than sites passed): the constraint records the assumption where reviewers and analysis tools find it; it does not prove it. Predict item pc4 is the alternative this listing avoids; the advanced block explains what is wrong with it.`],sysml:[{file:`week09/aerolink_network_stated.sysml`,caption:`Stating what the vertiport listing only entails, as asserted constraints (accepted by the checker, which does not evaluate them)`,intent:`conformant`}],citations:[{reading:`R80`,pages:`72`},{reading:`R87`,pages:`55–57`}],provenance:`mixed`},{id:`w9-worked-skeleton`,kind:`worked-example`,title:`Worked example (c): the L9 package structure and eight PHY part definitions and usages with ISQ/SI-typed attributes`,paragraphs:[`aerolink_l9_skeleton.sysml is the L9 deliverable in miniature, adapted from the reference skeleton (aerolink_v01_skeleton.sysml). The root package 'AeroLink L9 Model' — quoted, because its name has spaces — holds the nine L9 packages in lab-plan order with three private imports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 6). Packages L9 does not yet populate carry a doc comment saying when they will be: RB-8.2 asks for a structure that mirrors the artifact map.`,`Physical holds eight part definitions and the usage aeroLink, whose part usages carry the PHY IDs: part <'PHY-001'> aircraft : EVTOLAircraft[12]. Quantities use ISQ types (SpeedValue, DurationValue, PowerValue, SoundPressureLevelValue) because only the kind of unit belongs to the attribute’s definition and the unit comes with the value, so 18 [min] and 1080 [s] are both acceptable (OMG SysML v2.1 Beta 2, Part 1, p. 77); the Quantities and Units Domain Library specifies the standard quantity kinds and units (OMG SysML v2.1 Beta 2, Part 1, p. 77), and ISQ and SI are among the SysML standard libraries (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 17). Counts use Natural and flags Boolean from ScalarValues (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 17): plain values, so the course gives them no unit.`,`Definitions declare attributes; usages bind values. AeroLink’s configuration (12 chargers, 3 hubs) and current estimates (63.5 dB(A), 18 min) are bound under aeroLink — attribute :>> hubs = 3; — because they belong to AeroLink’s baseline, not to every vertiport network. ALT-004 can then be a second usage of the same definitions binding four hubs, with no definition edited. The grid connection limit is declared unbound, its doc pointing to TBD-02 and U-002. Note the two models of PHY-002 this week: here VertiportNetwork records counts, as reference v0.1 does; worked example (b) uses part features so that it can say what a hub is. Your model needs one of the two; the part form can carry hub-specific structure later. Outside Physical, one element each of STK, CON, MGO, NEED, CAP and SCN shows each kind’s construct. dB(A) is written in dB with the A-weighting in a doc comment, because ISO 80000 forbids decorating unit symbols.`,`Zero errors and zero warnings establish that the file parses, every name resolves and no rule fires — not that units are of the right kind (in Week 6 the pilot accepted an energy unit on a power attribute silently), nor that the model suits its purpose (SEBoK v2.14, “Why Model?”, p. 296).`],sysml:[{file:`week09/aerolink_l9_skeleton.sysml`,caption:`AeroLink L9 skeleton: nine packages, private imports, one example each of ENT, EXT, STK, CON, MGO, NEED, CAP and SCN, and eight PHY part definitions and usages with ISQ/SI-typed attributes, values bound in the usages (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R70`,pages:`6`},{reading:`R80`,pages:`77`},{reading:`R90`,pages:`17`},{reading:`R33b`,pages:`296`}],provenance:`mixed`},{id:`w9-worked-mapping`,kind:`worked-example`,title:`Worked example (d): the artifact-to-package mapping table, IDs as short names, and the quoting rule`,paragraphs:[`The second L9 deliverable places every Part I artefact, by ID, in a package and names the construct it becomes, following the reference; the mapper below applies it to your workspace. MOE, MOP, TPM, TECH, ALT, CRIT and DEC have no L9 package by design: an MOE or MOP is an attribute of what it measures, and the trade study becomes an analysis. Your team decides and records where they go.`,`The quoting rule applies wherever an ID is written: part <'PHY-003'> chargingSystems : ChargingSystems; Physical::aeroLink.'PHY-003'. A declared name is quoted only when it is not a basic name — aeroLink is bare, 'Vertiport Operators' quoted — and a quote or backslash inside it is escaped (OMG SysML v2.1 Beta 2, Part 1, p. 50). Every character inside the quotes counts: <' PHY-003'> begins with a space.`,`invalid_unquoted_short_name.sysml breaks the rule on one line; find it before reading on. The checker rejects line 15, part <PHY-003> chargingSystems, with “mismatched input ‘-’ expecting ‘>’”: unquoted, PHY is read as a basic name and the hyphen is unexpected. The second message follows from the first: fix the first error first, then re-run.`],table:{caption:`L9 mapping by kind (course proposal; reference examples)`,header:[`Kind (week)`,`Package`,`Construct`,`Example short name and declaration`],rows:[[`ENT (1)`,`Context`,`part def (system of interest)`,`part def <'ENT-001'> AeroLinkEnterprise`],[`EXT (1)`,`Context`,`part usage in the context part`,`part <'EXT-001'> ansp : AirNavigationServiceProvider`],[`STK (2)`,`Stakeholders`,`part def, used in stakeholder declarations`,`part def <'STK-005'> 'Vertiport Operators'`],[`CON (2)`,`Stakeholders`,`concern with subject and stakeholder`,`concern <'CON-006'> 'Pad throughput and charging capacity'`],[`MGO, NEED (3)`,`Needs`,`requirement`,`requirement <'NEED-004'> 'Pads not limited by turnaround'`],[`CAP (3)`,`Needs`,`action def (or part def: team decision)`,`action def <'CAP-003'> 'Fleet charging management'`],[`SCN (3)`,`Behavior`,`use case (action flow from L11)`,`use case <'SCN-003'> 'Aircraft Charging'`],[`REQ (4)`,`Requirements`,`requirement with subject (L10); its short name is its requirement ID (OMG SysML v2.1 Beta 2, Part 1, p. 165, Week 10)`,`requirement <'REQ-SYS-001'> …`],[`MOE, MOP, TPM (5)`,`none at L9`,`attributes of what they measure; TPM in a Measures package (reference)`,`attribute chargeTimeToDispatch (MOP-002) on ChargingSystems`],[`TECH (6); A, R, O, U (2–6)`,`none at L9; AROU`,`part def with TRL (Analysis package, reference); metadata`,`From L12`],[`ALT, CRIT, DEC (7)`,`none at L9`,`analysis (trade study) in an Analysis package (reference)`,`From L12`],[`FN, LOG, AI (8)`,`Logical`,`action usage; part usages`,`From L10`],[`PHY (8)`,`Physical`,`part usage of a part def`,`part <'PHY-003'> chargingSystems : ChargingSystems`],[`IF, INFO (8)`,`Physical (external IF in Context)`,`interface usage; item def`,`From L10`]]},sysml:[{file:`week09/invalid_unquoted_short_name.sysml`,caption:`Teaching listing: find the line that breaks the quoting rule for course IDs`,intent:`intentionally-invalid`}],citations:[{reading:`R80`,pages:`49–50`},{reading:`R90`,pages:`22`}],provenance:`mixed`},{id:`w9-advanced`,kind:`advanced`,title:`Advanced analysis: KerML semantics behind the keywords, and the gap between valid and correct`,paragraphs:[`Classification and extents. A KerML type classifies things; the set it classifies is its extent; and it gives conditions for what must be in or not in that extent (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 51–52). These conditions are necessary by default: a Car type requiring four wheels excludes everything without four wheels but does not make every four-wheeled thing a car; only a type declared sufficient, with the KerML keyword all, does that (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 52–53). The SysML notation the checker accepts has no such declaration on a definition (a probe with part def all … was a syntax error), so every condition a course definition states is necessary only. Applied to the vertiport listing (instructor reasoning): hubs (line 34) says each hub of a network is a HubVertiport among its sites; it does not make a site with two high-power chargers one of the hubs. Being a hub is stated, not inferred from equipment.`,`Subsetting and redefinition as statements about values. On each instance of the domain, separately, the values of a subsetting feature are values of the subsetted one, and it may restrict type and multiplicity (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 61). Redefinition also requires the two features to have the same values on each instance, so a restriction on one applies to both, and a redefining multiplicity must only allow cardinalities consistent with the redefined one (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 62); a redefined feature is not inherited (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 63). Keep two defects apart. A redefinition that only widens — 2..4 as 2..6 — breaks that well-formedness rule, yet instances with two to four values satisfy both features. One whose range does not overlap — pc4, exactly 3 as exactly 4 — is also unsatisfiable: no network has three and four hubs. The pilot reports both with one warning, “Subsetting/redefining feature should not have larger multiplicity upper bound” (course probes). A redefinition with an unrelated type adds a second typing every value must satisfy (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 62).`,`Valid is not correct. In the course’s probes (release 2026-08), redefining an inherited Charger[*] with an unrelated Pack[2] passed silently, although every charger would then also be a battery pack, and lowering a lower bound drew only a warning. That is why RB-8.1 (validity) and RB-8.3 (structure semantics) are separate criteria; Week 13 returns to it.`,`Usage-based modelling (instructor guidance, not a rubric rule). Structure can be specified entirely on parts, without definitions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, slide 16): right for one-off configurations, wrong for anything reused, because untyped nested parts cannot say that PHY-003’s chargers and the ALT-004 hub’s chargers are the same kind of thing. The instructor’s rule of thumb, offered as guidance for RB-8.3 (relationships used correctly and purposefully): a definition for every kind that occurs more than once or that a requirement constrains, a usage for every position in the architecture, and a subsetting usage for every configuration.`],citations:[{reading:`R87`,pages:`51–53`},{reading:`R87`,pages:`61–63`},{reading:`R70`,pages:`16`}],provenance:`mixed`},{id:`w9-defence`,kind:`concept`,title:`The CP3 defence: defending a decision by its conditions, not by its score`,paragraphs:[`The DoD guidebook describes decision analysis as turning a broadly stated decision opportunity into a traceable, defendable and actionable plan — from problem, requirements and assumptions through criteria, weights and alternatives to sensitivity analysis and a decision briefing — with the decision maker keeping full responsibility, authority and accountability (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 109–110). A defence is that briefing under questioning, scored against RB-6.6 (recommendation with its conditions, residual risk and what would change it) and RB-7.4 (architecture decisions with the alternatives considered).`,`Format (Session 1, eight teams × 5 min): 2 min on the recommendation and what would reverse it; 2 min on the architecture — one view, the N² finding, one architecture decision (DEC); 1 min of questions. For the reference baseline, a strong trade defence says: ALT-004 scores 0.670 against 0.489 for ALT-002 and alone meets REQ-STK-004; the ranking reverses if the capital weight exceeds 0.478 or the wait weight falls below 0.226, both amounting to abandoning MGO-007; it also changes if planning demand falls to 192 trips/day or less, or if the grid connection limit (TBD-02) rules out a fourth hub. Residual risk: R-001 (charging capacity) reduced but not removed, R-005 (grid connection) at the converted hub, and R-002 (battery capacity fade) rising with more high-power cycles. A strong architecture minute names DEC-002 — dispatch on one operations platform with an automatic hot standby — its rejected alternatives (distributed dispatch; no standby) and its rationale: one network-wide assignment for REQ-SYS-005, the standby mitigating R-007.`,`Why in an MBSE week (instructor reasoning): a defence that names its reversal conditions has assumptions (A-006, A-007, U-002) that can become model elements related to the decision, so “what if …” is answered by following relationships, not by searching documents.`],citations:[{reading:`R43`,pages:`109–110`}],provenance:`mixed`},{id:`w9-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`SEBoK lists what system models are used for across the life cycle — from characterising a system and exploring the trade space to verification, training and capturing knowledge — and insists that a model’s purpose be defined first (SEBoK v2.14, “Why Model?”, p. 295–296); the descriptive, analytical and executable models of one system must be integrated, which needs semantic interoperability and standards (SEBoK v2.14, “Types of Models”, p. 301–302). For AeroLink (instructor application): the regulator’s documents can be generated from the model at milestones (SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, p. 374), and the OEM, charger supplier and utility could exchange model data rather than documents through the standardised SysML v2 API (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 9).`],citations:[{reading:`R33b`,pages:`295–296`},{reading:`R33c`,pages:`301–302`},{reading:`R28`,pages:`374`},{reading:`R90`,pages:`9`}],provenance:`mixed`},{id:`w9-lab`,kind:`lab`,title:`Lab L9 — tool onboarding and model skeleton (model v0.1)`,paragraphs:[`The checker is installed in the pre-course Week 0 task; in Week 9 you only verify it before Session 2 (≈ 15 min), and on a lab machine the instructor prepared you do the same. The install route is repeated here for anyone who has to reinstall. The release’s guide (SysML-v2-Release, tag 2026-08, install/jupyter) needs Java 21 or later (java -version) and Miniconda with Python 3 (conda --version; on Windows tick “Add Anaconda to my PATH”). From that directory run install.bat (Windows) or chmod +x ./install.sh then ./install.sh (macOS, Linux), then start jupyter lab. Know what the script does: it installs the kernel, JupyterLab, Graphviz and Node.js from conda-forge into the active conda environment (base, unless you activate another first), fetches the JupyterLab SysML extension from the npm registry, and stops at the first step that fails. It needs network access to conda-forge and npm, which managed machines may block, and disk space. If it stops, record the step and message and tell the instructor rather than improvising; the fallback is a prepared lab machine, or submitting your file to the instructor’s run of the same release. A working install lists a kernel “sysml” in jupyter kernelspec list, whose folder holds jupyter-sysml-kernel-0.62.0-all.jar.`,`Prove it can pass and fail: in a SysML notebook, run aerolink_def_usage.sysml (no error expected), then invalid_unquoted_short_name.sysml (an error at the short name expected), and record both outputs. If either differs, stop and tell the instructor: grades follow the instructor’s run. Then build model v0.1 and the mapping table in class, run the file until it reports zero errors, and save that output as your checker log.`],citations:[],provenance:`instructor-authored`},{id:`w9-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: the CP3 defence in Session 1 (part of CP3, 9 % of the course grade; the defence informs RB-6.6 and RB-7.4); and L9 model v0.1 with its checker log, tool-verification record and the artifact-to-package mapping table, scored formatively on RB-8.1–8.2 now and summatively on RB-8 at CP4. Individual: readiness quiz Q8, the review-notebook entry with a time log, and, for graduate students who choose it, the optional KerML memo (course workload option B; read when submitted; formative feedback on RB-8.3; informs RB-16.1).`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w9-act-semantics`,title:`Definition, usage, specialization, subsetting, redefinition: read the vertiport network`,component:`w09-semantics-classifier`,purpose:`Classify the role of fifteen marked tokens in the validated listing aerolink_def_usage.sysml, and decide which of six statements the listing guarantees.`,instructions:[`Select each highlighted token and choose its role; watch the symbol in front of it, because “:>” means different things after a definition and after a usage.`,`Judge each statement in Part 2: guaranteed by the listing (true of everything the listing describes), or not. Some concern things the listing leaves open.`,`Check your answers; read the explanation for every item you missed, then read the commentary block.`],objectives:[`B9.2`],inBlock:`w9-worked-semantics`},{id:`w9-act-mapper`,title:`Artifact-to-package mapper (L9)`,component:`w09-package-mapper`,purpose:`Map your workspace’s Part I artefacts, by ID, to the nine L9 packages; see the proposed construct and short-name form; record and justify any different placement; practise the quoting rule; and export the mapping table.`,instructions:[`If your workspace is empty, tick the preview to see the reference baseline (read-only; nothing is written).`,`Review the placement of each kind; for kinds with no L9 package (MOE, MOP, TPM, TECH, ALT, CRIT, DEC) choose a package and record why. The tool records your reason; it does not judge it.`,`Practise writing short names and references; the tool checks the quoting rule and that the short name is exactly the ID. It does not check SysML: only the checker does.`,`Copy the Markdown table into your L9 deliverable and complete the owner column for any element without one.`],objectives:[`B9.4`],inBlock:`w9-worked-mapping`},{id:`w9-act-predict`,title:`Predict the checker`,component:`w09-predict-checker`,purpose:`Predict the outcome of eight pre-validated listings (PASS clean, PASS with a warning, or FAIL by syntax, name resolution or a validation rule), then compare with the result recorded by the course-designated checker.`,instructions:[`Read each listing and choose your prediction before revealing; a revealed item is locked.`,`Compare with the recorded result and its messages. The app shows only results recorded for exactly the text on screen; it never simulates the checker.`,`Write down which items passed with a real modelling problem: that is your personal list of things to review by hand.`],objectives:[`B9.2`,`B9.3`],inBlock:`w9-checker`}],lab:{id:`L9`,title:`Tool onboarding; model skeleton (model v0.1)`,setting:`team`,durationMinutes:75,objectives:[`B9.1`,`B9.3`,`B9.4`],inputs:[`CP1–CP3 artefacts with their IDs (workspace and CP packages)`,`The pilot implementation release 2026-08 (Jupyter route), or a lab machine prepared by the instructor`,`Listings aerolink_l9_skeleton.sysml, aerolink_def_usage.sysml and invalid_unquoted_short_name.sysml (this week)`,`Instructor reference skeleton sysml/reference/aerolink_v01_skeleton.sysml (recovery input)`,`The mapper activity (this week)`],steps:[{title:`Before class — verify the tool (installed in the pre-course Week 0 task)`,detail:`java -version shows 21 or later; conda --version works; jupyter kernelspec list shows the sysml kernel, whose folder contains jupyter-sysml-kernel-0.62.0-all.jar. Record the outputs in the tool-verification record. If the pre-course install was not done or no longer works, follow the release’s Jupyter route (lesson block L9: install.bat or install.sh installs into the active conda environment, needs conda-forge and the npm registry, and stops at the first failing step); if it stops, record the step and its message and tell the instructor, and use the prepared lab machine or the instructor’s run instead.`},{title:`Before class — prove it can pass and fail`,detail:`Run aerolink_def_usage.sysml (expect no error) and invalid_unquoted_short_name.sysml (expect an error at the short name, line 15) in a SysML notebook cell. Record both outputs. If either differs, stop and tell the instructor.`},{title:`In class — model purpose and views (5 min)`,detail:`Before writing any SysML, state the model’s purpose in three sentences (who uses it, for which decisions, at which fidelity: SEBoK v2.14, “Why Model?”, p. 295–296), and list which Part I tables and diagrams will become views of the model rather than separate documents (OMG SysML v2.1 Beta 2, Part 1, p. 48). Put the statement in the root package’s doc comment.`},{title:`In class — package structure (brief 5 + team work)`,detail:`Create the root package for your team’s model with private imports of ISQ, SI and ScalarValues, and the nine L9 packages in order: Context, Stakeholders, Needs, Requirements, Logical, Physical, Behavior, Verification, AROU. Each package gets a doc comment saying what it holds and when it is populated.`},{title:`In class — mapping table`,detail:`Use the mapper on your workspace; decide where each unmapped kind goes and record why; copy the table into the deliverable. Every CP1–CP3 ID appears exactly once, with its package, construct, short-name form and owner.`},{title:`In class — PHY definitions and usages`,detail:`For at least six PHY elements: a part definition with typed attributes (ISQ quantity types with SI units for quantities; Natural, Boolean or String otherwise) and a part usage in the system-of-interest part carrying the PHY ID as a quoted short name. Bind AeroLink’s configuration values and current estimates in the usages, not in the definitions; leave TBDs unbound with a doc comment pointing to the U item. Beyond the lab-plan L9 minimum, also declare one element each of STK, CON, MGO or NEED, CAP and SCN, as worked example (c) does, to rehearse each kind’s construct and quoting.`},{title:`Instructor checkpoint (10 min)`,detail:`Show the instructor a run with its output. Typical findings: unquoted IDs in references; imports without visibility; IDs on definitions where the course puts them on usages; attributes typed Real where a quantity type exists.`},{title:`In class — check to zero errors, then record`,detail:`Run the whole file until the checker reports zero errors; explain or remove every warning. Save the output as the checker log. Lab record (5 min): file, log, mapping table and verification record committed to the team repository.`}],artefacts:[{idPrefix:`Model v0.1`,description:`Team SysML v2 file: root package, nine L9 packages, private imports, ≥ 6 PHY part definitions and usages with typed attributes and units, values bound in the usages; beyond the lab-plan minimum, one declared element each of STK, CON, MGO or NEED, CAP and SCN`,minimum:`Accepted by the course-designated checker with zero errors; IDs present as quoted short names`},{idPrefix:`Mapping table`,description:`Every CP1–CP3 ID with package, construct, short-name form, declared name and owner; placement reasons for kinds without an L9 package`,minimum:`Every ID once; every undecided kind decided with a reason`},{idPrefix:`Checker log`,description:`Kernel output for the final model file, plus the tool-verification record (versions, pass and fail smoke tests)`,minimum:`Zero errors; every warning explained`}],continuity:`Model v0.1 is the file every later lab extends. L10 fills Requirements (every CP2 REQ with subject and its ID as short name), Logical and the ports, interfaces and allocations of Physical (model v0.2, CP4). L11 adds behaviour; L12 adds verification cases, MOE/MOP, TPM and AROU metadata, completing the packages left empty today. The mapping table becomes the checklist for those labs: every row must end as a model element, and Week 12’s trace audit counts against it. The CP3 decisions defended in Session 1 return as model elements (DEC-001 as a trade-study analysis in v0.4) and as the starting point of the Week 13 impact analysis.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`L9`,title:`L9 model v0.1, mapping table and checker log; CP3 defence`,mode:`team`,due:`CP3 defence: Week 9 Session 1 (5 min per team). Model v0.1, checker log, tool-verification record and mapping table: end of Week 9. Optional graduate KerML memo: end of Week 9.`,weight:`L9 is formative: model v0.1 is scored on RB-8.1–8.2 now and summatively on RB-8 at CP4 (10 % of the course grade). The CP3 defence is part of CP3 (9 % of the course grade: RB-6 45 · RB-7 45 · RB-12 10) and informs RB-6.6 and RB-7.4. Optional graduate memo: review notebook (RB-16, 5 %), read when submitted.`,instructions:[`Defend CP3 in five minutes: 2 min on the recommendation and the condition that would reverse it; 2 min on the architecture (one view, the N² finding, one architecture DEC with the alternatives considered); 1 min of questions. Record the questions you received and your answers.`,`Build model v0.1 as in lab L9 and check it with the course-designated checker until it reports zero errors; explain every remaining warning.`,`Complete the mapping table with the mapper: every CP1–CP3 ID once, with package, construct, short-name form, declared name and owner; decide and justify the placement of MOE, MOP, TPM, TECH, ALT, CRIT and DEC.`,`Graduate students (individually, optional this week under course workload option B): the KerML memo (template section 7) on aerolink_def_usage.sysml, aerolink_network_stated.sysml and the predict item pc4 (predict_pc4_conflicting_multiplicity.sysml). Any SysML you write must be run through the checker, and you report what it said.`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Tool-verification record`,guidance:`Outputs of java -version, conda --version and jupyter kernelspec list; the kernel jar name; the output of the pass smoke test (aerolink_def_usage.sysml) and of the fail smoke test (invalid_unquoted_short_name.sysml). Note any difference from the expected results and what the instructor said.`},{heading:`2. Model v0.1 and checker log (RB-8.1)`,guidance:`The .sysml file and the kernel output for the whole file. Zero errors; for every warning, the line, the message and either the fix or why it is acceptable.`},{heading:`3. Package structure and conventions (RB-8.2)`,guidance:`The model’s purpose statement (three sentences) and the Part I tables and diagrams that will become views of it (B9.1). Then One paragraph per package: what it holds now and when it will be populated. State the import visibility you used and why; state where IDs sit (definition or usage) for each kind and why.`},{heading:`4. Artifact-to-package mapping table (B9.4)`,guidance:`The mapper’s Markdown table, completed: every CP1–CP3 ID once, package, construct, short-name form, declared name, owner. Then the placement decisions for kinds without an L9 package, each with its reason.`},{heading:`5. PHY definitions and usages (B9.3)`,guidance:`For ≥ 6 PHY: the definition’s attributes with their types and why each type (quantity type, Natural, Boolean, String); the usage with its short name; which values are bound, where, and why; which are TBD and which U item they point to.`},{heading:`6. CP3 defence record (B9.5)`,guidance:`The slides or notes you used; the reversal conditions you stated; the architecture DEC with its alternatives; the panel’s questions and your answers; what you changed in CP3 afterwards.`},{heading:`7. Optional graduate extension: KerML memo (individual, 1–2 pages)`,guidance:`Using OMG KerML v1.1 Beta 2, “7.3 Core”, p. 51–53 and 61–63: (a) state, in KerML terms (types, extents, necessary conditions), what HubVertiport, VertiportNetwork::hubs and alt004Network’s redefined hubs assert; (b) explain the difference between turnaroundChargers (subsetting) and SpokeVertiport’s chargers (redefinition) in terms of the values on each instance; (c) pc4 has two defects: name the KerML rule it breaks, explain why, in addition, no instance can satisfy it, quote what the checker reported, say whether that report would differ for a widening that some instances can satisfy, and propose the corrected structure; (d) stated versus entailed: give the step-by-step argument, line by line, that no site of aerolink_def_usage.sysml can be both a hub and a spoke; change one line so that this is no longer entailed; state it instead with an asserted constraint (as in aerolink_network_stated.sysml); run both files through the checker and report what it said and what that does and does not show.`},{heading:`8. AI usage statement (RB-12)`,guidance:`Tool, purpose, prompts, outputs and your evaluation. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner in the notebook; unexplained AI syntax counts as a defect (syllabus §AI rules; RB-12.3).`}],rubrics:[`RB-8`,`RB-6`,`RB-7`,`RB-12`,`RB-16`],rubricScope:`Model v0.1: RB-8.1 (validity) and RB-8.2 (organisation and conventions), formative; summative RB-8 at CP4. CP3 defence: informs RB-6.6 (recommendation with conditions, residual risk and what would change it) and RB-7.4 (architecture decisions with alternatives) of CP3. Graduate KerML memo: optional this week under the course workload option B (graduate tasks in alternate weeks; Week 10’s graduate memo is required); when submitted it is read (RB-16 graduate-task rule), with formative feedback on RB-8.3 (structure semantics: definition/usage, specialization, subsetting and redefinition used correctly and purposefully), and informing RB-16.1 (engineering reasoning). AI statement: RB-12.1–12.3.`,aiUse:`AI tools may explain error messages or suggest SysML syntax. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner in the notebook; unexplained AI syntax is a defect (RB-12.3). AI output may not be used as evidence of what the checker accepts: only a recorded run counts. The CP3 defence and the KerML memo are the students’ own reasoning.`,objectives:[`B9.1`,`B9.3`,`B9.4`,`B9.5`]},quiz:[{id:`q9-1`,bloom:`Apply`,objective:`B9.1`,prompt:`A team uploads a photo of its whiteboard architecture sketch — boxes and arrows, no legend — to the repository and labels it “AeroLink system model v1”. Using the SEBoK model classification, which description fits the artefact best?`,options:[{id:`a`,text:`A formal descriptive model, because it shows the parts of the system and exactly how they connect`,correct:!1,explanation:`Showing parts makes it descriptive in content, but formality needs a language with defined syntax and semantics; boxes and arrows with no agreed meaning are informal.`},{id:`b`,text:`An analytical model, because an architecture is in the end a quantitative description`,correct:!1,explanation:`Analytical models describe mathematical relationships (e.g. differential equations); a sketch of parts and connections is descriptive, and informal.`},{id:`c`,text:`An informal representation: with no agreed language, what its boxes and arrows mean is imprecise`,correct:!0,explanation:`Correct. SEBoK distinguishes informal from formal models by whether a well-defined language with syntax and semantics supports them; a picture or text without agreed meaning risks ambiguity, and the sketch falls outside what SEBoK treats as MBSE until it is expressed in a modelling language (SEBoK v2.14, “Types of Models”, p. 298).`},{id:`d`,text:`A view of the system model, because every architecture diagram is a view of some model`,correct:!1,explanation:`A view is a query of a model and a rendering of the result (OMG SysML v2.1 Beta 2, Part 1, p. 48). There is no underlying model here for the photo to be a view of.`}],cite:{reading:`R33c`,pages:`298`}},{id:`q9-2`,bloom:`Analyse`,objective:`B9.1`,prompt:`The maintenance lead wants a table of every PHY element with its fault-report-to-flag time; the operations lead wants a diagram of the same elements and their interfaces. A teammate proposes keeping a spreadsheet for maintenance and a diagram file for operations, “so each lead gets exactly what they need”. In an MBSE workflow, what should exist instead?`,options:[{id:`a`,text:`One model, and a table view and a diagram view of it, both regenerated after any change`,correct:!0,explanation:`Correct. A view specifies a query of the model and a rendering of the results for a viewpoint (OMG SysML v2.1 Beta 2, Part 1, p. 48), and a system model may comprise multiple views (SEBoK v2.14, “Types of Models”, p. 300): each lead gets a rendering for their concern, and both come from the same elements.`},{id:`b`,text:`Both files plus the model, so that each audience keeps and edits its own master copy`,correct:!1,explanation:`Three masters is the document-based problem: every change must be synchronised by hand, and one copy will be missed.`},{id:`c`,text:`Only the diagram, because SysML is a graphical language and its diagrams are the model`,correct:!1,explanation:`SysML v2 has graphical, tabular and textual visualisations (Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language”, slide 7); and the diagram is a rendering, not the model.`},{id:`d`,text:`Only the spreadsheet, because a table is more precise than a diagram for maintenance data`,correct:!1,explanation:`The format of a view is not what makes it precise; what matters is that both views come from one model.`}],cite:{reading:`R80`,pages:`48`}},{id:`q9-3`,bloom:`Evaluate`,objective:`B9.1`,prompt:`A team’s model v0.1 passes the checker with zero errors and zero warnings. Its root package has no doc comment, Physical holds forty part definitions copied from a supplier’s catalogue, and no one on the team can say which decisions the model is meant to support. The team asks for the top level on RB-8 “because the model is valid”. Which reply is best?`,options:[{id:`a`,text:`Agree: zero errors and zero warnings is the top level of every RB-8 criterion, structure included`,correct:!1,explanation:`Zero errors and zero warnings speak to RB-8.1 (validity) only; organisation, conventions and structure semantics are separate criteria, and none of them is decided by the checker.`},{id:`b`,text:`Disagree: forty part definitions are too many for a v0.1 model, so the model cannot be valid`,correct:!1,explanation:`The number of definitions has nothing to do with validity; the model is valid. The problem is that its content cannot be judged without a stated purpose.`},{id:`c`,text:`Agree, once the team also adds a diagram of all forty parts so that the reviewers can see the content`,correct:!1,explanation:`A diagram is a view of the model (OMG SysML v2.1 Beta 2, Part 1, p. 48); it adds no purpose and no evidence that the content is right.`},{id:`d`,text:`Validity is one criterion; with no stated purpose, nobody can judge if forty catalogue parts are right`,correct:!0,explanation:`Correct. SEBoK asks that a model’s purpose be defined first, because a model is judged by how well it supports that purpose (SEBoK v2.14, “Why Model?”, p. 295–296). Until the team says who uses the model for which decisions, nobody — the checker included — can judge its content; the checker only tests conformance to the language’s rules.`}],cite:{reading:`R33b`,pages:`295–296`}},{id:`q9-4`,bloom:`Apply`,objective:`B9.2`,prompt:`Read: part def OperationsCenter { part consoles : Console[6]; }  part def Console;  part def DispatchConsole :> Console;  part opsCenter : OperationsCenter { part dispatchConsoles : DispatchConsole[2] subsets consoles; }. Which statement does this fragment assert?`,options:[{id:`a`,text:`opsCenter has eight consoles in total: its six consoles plus two further dispatch consoles`,correct:!1,explanation:`Subsetting does not add values: the dispatch consoles are among the six consoles.`},{id:`b`,text:`In opsCenter, consoles is replaced by dispatchConsoles, so opsCenter has only two consoles`,correct:!1,explanation:`That would be redefinition. A subsetting feature is an additional feature; consoles[6] is still there.`},{id:`c`,text:`In opsCenter, two of its six consoles are dispatch consoles, and it still has six in all`,correct:!0,explanation:`Correct. Subsetting asserts that the values of one feature are among the values of another in any common context (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 11), so every value of dispatchConsoles is also a value of consoles; the subsetting usage may restrict type and multiplicity (OMG SysML v2.1 Beta 2, Part 1, p. 64).`},{id:`d`,text:`Every OperationsCenter, not only opsCenter, has two of its six consoles as dispatch consoles`,correct:!1,explanation:`The subsetting is declared in the usage opsCenter, not in the definition OperationsCenter.`}],cite:{reading:`R70`,pages:`11`}},{id:`q9-5`,bloom:`Analyse`,objective:`B9.2`,prompt:`Graduate (KerML). part def Aircraft { part rotors : Rotor[4..8]; }  part def AeroLinkEVTOL :> Aircraft { part redefines rotors[6]; }  part demo : AeroLinkEVTOL { part liftRotors : Rotor[8] subsets rotors; }. A teammate reads demo as “six rotors plus eight lift rotors”. What does KerML say about demo?`,options:[{id:`a`,text:`The teammate is right: a subsetting feature adds its values to those of the feature it subsets`,correct:!1,explanation:`Subsetting never adds values: on each instance, the values of the subsetting feature are also values of the subsetted feature (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 61).`},{id:`b`,text:`No demo can exist: its eight lift rotors must all be among its rotors, of which it has exactly six`,correct:!0,explanation:`Correct. On each instance the values of a subsetting feature are also values of the subsetted one, and a subsetting feature may restrict the multiplicity only to smaller cardinalities (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 61). In demo, rotors is AeroLinkEVTOL’s redefinition, exactly 6; both features are unique by default (OMG SysML v2.1 Beta 2, Part 1, p. 73), so eight distinct values cannot be among six. Model the demonstrator from Aircraft, or as a sibling of AeroLinkEVTOL.`},{id:`c`,text:`It is fine: 8 lies inside the 4..8 range that Aircraft declares for the rotors of any aircraft`,correct:!1,explanation:`AeroLinkEVTOL redefines rotors as exactly 6, and the redefinition has the same values as the original on each instance (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 62); in demo the 4..8 range is no longer the binding constraint.`},{id:`d`,text:`It is ill-formed syntax: a usage may only redefine a feature it inherits, never subset that feature`,correct:!1,explanation:`A usage may subset an inherited feature (:> or subsets after a usage, OMG SysML v2.1 Beta 2, Part 1, p. 72), as dispatchConsoles does in q9-4. The problem is semantic, not syntactic.`}],cite:{reading:`R87`,pages:`61–62`}},{id:`q9-6`,bloom:`Analyse`,objective:`B9.2`,prompt:`In a review a student says: “part spareBatteries : BatteryPack[30]; in our MaintenanceFacility definition creates thirty battery packs in the model, so the model is the inventory.” Which correction is right?`,options:[{id:`a`,text:`None needed: a part usage with multiplicity 30 stands for thirty battery-pack instances`,correct:!1,explanation:`This is the “usage = instance” misconception the course targets.`},{id:`b`,text:`spareBatteries is a definition, because only definitions can carry a multiplicity like [30]`,correct:!1,explanation:`It has no def keyword; multiplicity is a property of usages (features).`},{id:`c`,text:`The declaration is invalid, since a part usage cannot have a multiplicity greater than one`,correct:!1,explanation:`Multiplicity ranges with any natural bounds are allowed, e.g. a vehicle with 4..8 wheels (OMG SysML v2.1 Beta 2, Part 1, p. 64).`},{id:`d`,text:`It is a feature: every facility must have thirty packs, but no specific pack is named`,correct:!0,explanation:`Correct. A feature relates instances of its featuring definition to instances of its own definition, and multiplicity constrains how many values it has for each featuring instance (OMG SysML v2.1 Beta 2, Part 1, p. 63–64). It describes what any facility must have, not which packs exist; an inventory of specific packs is a different kind of record.`}],cite:{reading:`R80`,pages:`63–64`}},{id:`q9-7`,bloom:`Apply`,objective:`B9.2`,prompt:`Two lines from a team model: (1) part def CargoPod :> Payload;  (2) part cargo : CargoPod :> payloads;  (Payload is a part def; payloads is a part usage inherited from the aircraft definition.) What relationship does :> denote in each line?`,options:[{id:`a`,text:`(1) specialization: CargoPod inherits from Payload; (2) subsetting: cargo is among payloads`,correct:!0,explanation:`Correct. For definitions :> is the specializes keyword (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 10), so CargoPod inherits Payload’s features; for usages :> is subsets (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 11; OMG SysML v2.1 Beta 2, Part 1, p. 72), so the cargo values are among the aircraft’s payloads, and : gives cargo’s defining definition.`},{id:`b`,text:`Specialization in both lines: each name inherits every feature of the name after :>`,correct:!1,explanation:`In line 2 :> follows a usage, where it means subsetting.`},{id:`c`,text:`(1) subsetting of Payload’s values; (2) specialization, so that cargo inherits from payloads`,correct:!1,explanation:`Reversed: definitions are specialized; features are subsetted.`},{id:`d`,text:`Redefinition in both lines: each declaration replaces the element named after :>`,correct:!1,explanation:`Redefinition is written redefines or :>>.`}],cite:{reading:`R70`,pages:`10–11`}},{id:`q9-8`,bloom:`Apply`,objective:`B9.3`,prompt:`MaintenanceFacility must record the time from a fault report to the aircraft being flagged unavailable (FICTIONAL current estimate 90 s). The file has private import ISQ::*; private import SI::*;. Which pair of lines is best (definition first, then AeroLink’s facility usage)?`,options:[{id:`a`,text:`attribute faultReportToFlagTime : Real;  then  attribute :>> faultReportToFlagTime = 90; // s`,correct:!1,explanation:`A duration with its unit in a comment cannot be converted or checked; ISQ provides a duration type.`},{id:`b`,text:`attribute faultReportToFlagTime : DurationValue = 90 [s];  then nothing in the usage`,correct:!1,explanation:`This binds the estimate for every MaintenanceFacility; a current estimate is a property of AeroLink’s facility, so it belongs in the usage.`},{id:`c`,text:`attribute faultReportToFlagTime : DurationValue;  then  attribute :>> faultReportToFlagTime = 90 [s];`,correct:!0,explanation:`Correct. The type fixes only the kind of quantity, and the specific unit comes with the value (OMG SysML v2.1 Beta 2, Part 1, p. 77); the estimate belongs to AeroLink’s facility usage, not to every facility.`},{id:`d`,text:`part faultReportToFlagTime : DurationValue;  then  part :>> faultReportToFlagTime = 90 [s];`,correct:!1,explanation:`A duration is data, so it is an attribute; a part must be typed by a part (occurrence) definition (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 9).`}],cite:{reading:`R80`,pages:`77`}},{id:`q9-9`,bloom:`Apply`,objective:`B9.3`,prompt:`Your team keeps shared unit definitions in a package AeroLinkUnits that imports ISQ, and wants every package that imports AeroLinkUnits to see the ISQ quantity types without importing ISQ itself. Which import should AeroLinkUnits declare?`,options:[{id:`a`,text:`private import ISQ::*;`,correct:!1,explanation:`Members from a private import are not visible outside the importing package.`},{id:`b`,text:`public import ISQ::*;`,correct:!0,explanation:`Correct. All members from a public import are visible (re-exported) from the importing package (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 6). Re-export is the case in which Seidewitz, Intro to the SysML v2 Language: Textual Notation says public visibility is appropriate.`},{id:`c`,text:`import ISQ::*; (defaults to public)`,correct:!1,explanation:`In the 2026-08 notation the visibility of an import must be shown explicitly (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 6).`},{id:`d`,text:`public import ISQ;`,correct:!1,explanation:`Importing the package itself, not its members, does not make the quantity types visible by their simple names in the packages that import AeroLinkUnits.`}],cite:{reading:`R70`,pages:`6`}},{id:`q9-10`,bloom:`Apply`,objective:`B9.4`,prompt:`A team adds a concern CON-017 named Operator’s duty-time limits (with an apostrophe). Which declaration follows the course conventions and the SysML naming rules?`,options:[{id:`a`,text:`concern <CON-017> Operator's duty-time limits {`,correct:!1,explanation:`CON-017 is not a basic name, so its short name must be quoted; and a name with spaces and an apostrophe must be an unrestricted name.`},{id:`b`,text:`concern 'CON-017' <Operator's duty-time limits> {`,correct:!1,explanation:`Reversed: the short name comes first, in angle brackets; the name follows (OMG SysML v2.1 Beta 2, Part 1, p. 49).`},{id:`c`,text:`concern <"CON-017"> "Operator's duty-time limits" {`,correct:!1,explanation:`Unrestricted names use single quotes, not double quotes (OMG SysML v2.1 Beta 2, Part 1, p. 50).`},{id:`d`,text:`concern <'CON-017'> 'Operator\\'s duty-time limits' {`,correct:!0,explanation:`Correct. The hyphenated ID is quoted as a short name, the descriptive name is an unrestricted name, and the single quote inside it is escaped with a backslash (OMG SysML v2.1 Beta 2, Part 1, p. 49–50).`}],cite:{reading:`R80`,pages:`49–50`}},{id:`q9-11`,bloom:`Analyse`,objective:`B9.4`,prompt:`To keep “what runs where” together, a team declares its functions FN-006 and FN-007 as owned members inside the PHY-003 chargingSystems usage in the Physical package, “because they are allocated to PHY-003”. In the CP5 trade-off, PHY-003 may be replaced by a different charging concept. What is the main modelling problem?`,options:[{id:`a`,text:`Replacing PHY-003 would delete the functions it owns; keep FN in Logical and allocate them`,correct:!0,explanation:`Correct. When a namespace is deleted, all its owned members are deleted too (OMG SysML v2.1 Beta 2, Part 1, p. 55), and the functional viewpoint disappears into the physical one. The L9 package structure keeps Logical and Physical separate so that the allocation (allocate … to …, from L10) can change without losing the functions.`},{id:`b`,text:`None: allocation and ownership are one relationship in SysML, written in two different ways`,correct:!1,explanation:`Allocation is a relationship between elements (allocate … to …); ownership is membership in a namespace. They have different consequences.`},{id:`c`,text:`Only that FN IDs must be quoted when they are declared inside a part rather than a package`,correct:!1,explanation:`The quoting rule applies everywhere; it is not the issue raised by the scenario.`},{id:`d`,text:`Functions cannot be declared inside a part in SysML v2, so the file will fail the checker`,correct:!1,explanation:`Definitions and usages are namespaces and can own other elements (OMG SysML v2.1 Beta 2, Part 1, p. 56); the problem is the consequence, not legality.`}],cite:{reading:`R80`,pages:`55–56`}},{id:`q9-12`,bloom:`Evaluate`,objective:`B9.5`,prompt:`In a CP3 defence (a different team, FICTIONAL numbers), the team recommends adding vertiports (score 0.58 against 0.55 for adding aircraft; cost weight 0.30; the seventh site needs a city licence, assumption A-109). A panelist asks: “What would make you change this recommendation?” Which answer best meets RB-6.6?`,options:[{id:`a`,text:`“Nothing: our model shows that adding vertiports scores highest, so the case is closed.”`,correct:!1,explanation:`A defence that cannot name the conditions of its recommendation fails RB-6.6’s “what would change it”.`},{id:`b`,text:`“The gap is only 0.03, so the two options are equally good and the board should choose.”`,correct:!1,explanation:`Close scores call for sensitivity and conditions, not for abandoning the recommendation; the decision maker still needs a defendable basis (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110).`},{id:`c`,text:`“A cost weight above 0.41, or no licence by month 9; licensing is our residual risk.”`,correct:!0,explanation:`Correct. It states the reversal point from the sensitivity analysis (above 0.41 adding aircraft ranks first), the assumption the recommendation rests on (without the licence the alternative cannot meet the capacity requirement), and the residual risk to watch — the conditions RB-6.6 asks for and the traceable, defendable plan the guidebook describes (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 109).`},{id:`d`,text:`“We would change it if the professor or the panel disagreed with our scores.”`,correct:!1,explanation:`A recommendation’s conditions are engineering conditions, not authority.`}],cite:{reading:`R43`,pages:`109–110`}},{id:`q9-13`,bloom:`Evaluate`,objective:`B9.5`,prompt:`For RB-7.4, a team presents its architecture decision: “DEC-102: dispatch runs on the booking platform.” Which addition would most strengthen it in the defence?`,options:[{id:`a`,text:`A more detailed diagram of the booking platform and of all its interfaces`,correct:!1,explanation:`A view of the chosen solution does not show that alternatives were considered.`},{id:`b`,text:`The alternatives, the criterion that decided, and what would reopen it`,correct:!0,explanation:`Correct. RB-7.4 level 4 asks for key architecture decisions recorded with the alternatives considered (e.g. dispatch in the operations centre; a separate dispatch service), linked by ID to the requirements and risks they affect; reviewing assumptions, criteria and alternatives is part of the decision-analysis steps (OUSD(R&E) Systems Engineering Guidebook, “Decision Analysis Process”, p. 110).`},{id:`c`,text:`A statement that the team and the client agreed on it unanimously`,correct:!1,explanation:`Agreement is not rationale; the criterion and alternatives are.`},{id:`d`,text:`The technology readiness level of the booking platform today`,correct:!1,explanation:`Maturity may be a criterion, but by itself it does not record the decision’s rationale or alternatives.`}],cite:{reading:`R43`,pages:`110`}},{id:`q9-14`,bloom:`Analyse`,objective:`B9.2`,prompt:`Graduate (KerML). part def EVTOLAircraft { attribute openNoGoFaults : Natural; }  part def DispatchReadyAircraft :> EVTOLAircraft { attribute :>> openNoGoFaults = 0; }  part def AircraftUnderRepair :> EVTOLAircraft { attribute :>> openNoGoFaults = 2; }. Which conclusion follows from these three definitions alone?`,options:[{id:`a`,text:`No aircraft is both dispatch-ready and under repair: one value cannot be both 0 and 2`,correct:!0,explanation:`Correct, and it is entailed, not stated. openNoGoFaults is an owned attribute usage, so it has exactly one value by default (OMG SysML v2.1 Beta 2, Part 1, p. 73); each specialization binds that value, and an instance of both would need it to equal 0 and 2. The conditions are necessary ones (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 52–53): they exclude, they do not classify.`},{id:`b`,text:`Every EVTOLAircraft whose openNoGoFaults is 0 is classified as a DispatchReadyAircraft`,correct:!1,explanation:`The binding is a necessary condition: it excludes aircraft with open faults from DispatchReadyAircraft but does not put every fault-free aircraft in it; only a sufficient type (KerML keyword all) would (OMG KerML v1.1 Beta 2, “7.3 Core”, p. 52–53), and the course checker’s SysML notation has no such declaration on a part definition.`},{id:`c`,text:`Every EVTOLAircraft is either a DispatchReadyAircraft or an AircraftUnderRepair`,correct:!1,explanation:`Nothing states coverage: an aircraft with one open no-go fault is neither, and a fault-free aircraft need not be either (necessary conditions only).`},{id:`d`,text:`The two definitions conflict, since sibling definitions may not redefine the same feature`,correct:!1,explanation:`Sibling definitions may each redefine an inherited feature, as HubVertiport and SpokeVertiport do with chargers in aerolink_def_usage.sysml; the conflict matters only for something that would be both.`}],cite:{reading:`R87`,pages:`52–53`}},{id:`q9-15`,bloom:`Apply`,objective:`B9.3`,prompt:`Which declaration correctly models AeroLink’s pad fire detection (PHY-008) as a usage in the system-of-interest part, with 18 flame detectors of one type in it?`,options:[{id:`a`,text:`part def <'PHY-008'> padFireDetection { part detectors : FlameDetector[18]; }`,correct:!1,explanation:`This declares a definition with the PHY ID; in the course convention PHY IDs sit on usages (positions in the architecture), typed by a part def.`},{id:`b`,text:`part <'PHY-008'> padFireDetection : PadFireDetectionSystem { part detectors : FlameDetector[18]; }`,correct:!0,explanation:`Correct. A part usage with the quoted ID as short name, defined by a part definition, owning a nested part usage with multiplicity 18 (OMG SysML v2.1 Beta 2, Part 1, p. 49–50, p.73).`},{id:`c`,text:`part <PHY-008> padFireDetection : PadFireDetectionSystem { attribute detectors : FlameDetector = 18; }`,correct:!1,explanation:`The ID is unquoted, and a detector is a part, not an attribute value.`},{id:`d`,text:`part 'PHY-008' : PadFireDetectionSystem[18] { part detector : FlameDetector; }`,correct:!1,explanation:`This uses the ID as the name and gives the whole system a multiplicity of 18; the detectors are what there are 18 of.`}],cite:{reading:`R80`,pages:`72–73`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min: CP3 defences and concept studio; lab L9)`,hours:2.5},{activity:`Core readings SEBoK v2.14, “Model-Based Systems Engineering (MBSE)”, SEBoK v2.14, “What is a Model?”, “Why Model?” and “Types of Models” (16 pp at ≈ 15 pp/h) and Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Introduction to the SysML v2 Language”, Friedenthal, Intro to the SysML v2 Language: Graphical Notation, “Systems Modeling Language” (35 slides at ≈ 30 sl/h)`,hours:2.3},{activity:`Essential OMG SysML v2.1 Beta 2, Part 1 extracts p.47–50, 55–56, 63–65, 72–73, 77 (OMG SysML v2.1 Beta 2, Part 1, “7.1 Language Overview”; 12 pp at ≈ 15 pp/h)`,hours:.8},{activity:`Online lesson (≈ 4,800 words, ≈ 1 h) and the three activities (classifier, predict the checker, mapper; ≈ 0.5 h)`,hours:1.5},{activity:`Readiness quiz Q8 / knowledge check (15 items)`,hours:.3},{activity:`CP3 defence final rehearsal (main preparation budgeted in Week 8)`,hours:.2},{activity:`Review notebook entry, time log and AI statement`,hours:.2},{activity:`L9 out of class: 15-min tool check (installed in the pre-course Week 0 task), smoke tests, model v0.1 completion, mapping table (team share; budgeted at what remains of the 9 h, realistic ≈ 1.5 h — see cautions)`,hours:1.2}],references:[{reading:`R87`,pages:`51–53`},{reading:`R87`,pages:`55–57`},{reading:`R87`,pages:`61–63`},{reading:`R80`,pages:`47–50`},{reading:`R80`,pages:`55–56`},{reading:`R80`,pages:`63–65`},{reading:`R80`,pages:`72–73`},{reading:`R80`,pages:`77`},{reading:`R43`,pages:`109–110`},{reading:`R83`,pages:`165`}],review:{status:`self-checked`,openIssues:[`Lead: align sysml/reference/aerolink_v01_skeleton.sysml with the Week 9 rule (configuration values bound in usages, not definitions); exact change in the Week 9 revision report and notes.`,`Lead: add the install/jupyter README.adoc, install.bat, install.sh and conda-forge recipe evidence to tools/sysml-pilot-2026-08/PROVENANCE.txt (text in the notes).`,`Lead: option E is adopted, but no pre-course Week 0 task exists in the app yet. Create it (a course-level page or announcement) with the install route and checklist now in the L9 block, plus the Week 8 reminder; until then the L9 block is the only place the steps are written.`,`Lead: option B scheduling. Week 9’s graduate memo is now optional (Week 12’s already is), and Weeks 8 and 10 carry required graduate tasks. Week 11 still carries a required one, so Weeks 10 and 11 are consecutive required weeks; confirm or adjust the alternation.`,`Lead: OMG SysML v2.1 Beta 2, Part 1, p. 197 (reserved words) is outside the register; the block/value claim rests on OMG SysML v2.1 Beta 2, Part 1, p. 48 and the probes.`]}},x=e({default:()=>S}),S={week:10,drivingQuestion:`AeroLink’s requirements, architecture and allocation exist as tables and matrices with stable IDs. When they become requirements, ports, interfaces, satisfy and allocate in one model, which of those relationships are claims about the system — and can your team make only the claims it can defend, and record the rest?`,blocks:[{id:`w10-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to B-CLO4 (a SysML v2 model that is valid in the course-designated checker and semantically correct) and B-CLO5 (the digital thread intact by ID). Model v0.2, built in lab L10, adds to v0.1 what CP4 (Week 11) assesses: every CP2 requirement, the logical and physical structure with ports and interfaces, a satisfy for every system requirement or an honestly recorded gap, and the FN → PHY allocation of CP3. One idea is at the centre. Some relationships are claims about the system: a satisfy asserts that a requirement is met. Others assign responsibility or record a dependency. A model is only as trustworthy as its claims, and the checker judges few of them.`],bullets:[`B10.1 (Apply) Model requirements with a subject, a doc statement, a required constraint and the requirement ID as short name; use requirement definitions, parameters and groups correctly.`,`B10.2 (Apply) Model logical and physical structure with ports, port conjugation, interface definitions and interface usages that connect compatible ports, with item flows.`,`B10.3 (Analyse) Relate design to requirements with satisfy and logical to physical elements with allocate; explain what each asserts, what the checker does and does not check, and record a satisfy gap honestly.`,`Graduate expectation: model assumed and required constraints for one AeroLink requirement and explain their semantics (OMG SysML v2.1 Beta 2, Part 1 §7.21), including what a satisfy then asserts.`],citations:[],provenance:`instructor-authored`},{id:`w10-intuition`,kind:`intuition`,title:`Intuition: a socket, a cable standard, and a signed declaration`,paragraphs:[`Look at the charging socket on an electric car. The socket is a port: the one place where the car lets the outside world reach part of its inside, and only in a limited way. Power goes in, status messages go out, and nobody plugs into the battery itself. The charging standard printed on the cable says what each end must offer — this pin supplies, that pin receives — and therefore which two sockets may be joined. The standard is an interface definition, and plugging one cable into one car at one charger is a connection that conforms to it. A cable with two supply ends charges nothing, whatever its label says.`,`Then look at the paperwork. A declaration of conformity says “this charger meets standard X”: a signed claim, which can be false. The laboratory’s test report is the evidence that it is true. In SysML v2, satisfy is the signed declaration, verification is the test report, and allocation is the work assignment that says which department builds the charger. This week you write all three into the AeroLink model, and learn to leave a declaration unsigned, and say so, when the evidence points the other way.`],citations:[],provenance:`instructor-authored`},{id:`w10-requirements`,kind:`concept`,title:`Requirements as constraints: definition and usage, subject, ID, parameters, groups`,paragraphs:[`A requirement definition is a special kind of constraint definition. Its textual statement is written as a documentation comment, and it can be formalised by one or more required constraints. Like a constraint definition, it can be parameterised using features (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 86). OMG SysML v2.1 Beta 2, Part 1 states the purpose: a requirement definition specifies stakeholder-imposed constraints that a design solution must satisfy to be a valid solution. The required constraints may be informal “shall” text or formal constraint expressions (OMG SysML v2.1 Beta 2, Part 1, p. 161). A requirement usage is a usage of a requirement definition in a context — a package, a part or another requirement — and a usage will often bind the definition’s parameters to specific values (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 89; OMG SysML v2.1 Beta 2, Part 1, p. 161). OMG SysML v2.1 Beta 2, Part 1’s example is a MaximumMass definition whose constraint compares massActual with massRequired. A usage restricts the subject to a vehicle, redefines massActual as the vehicle’s mass and binds massRequired to 2000 kg (OMG SysML v2.1 Beta 2, Part 1, p. 161). A requirement usage must be defined by a single requirement definition (OMG SysML v2.1 Beta 2, Part 1, p. 165). In the course model most requirements are usages written directly in the Requirements package, as in the reference model.`,`The subject. A requirement definition is always about some subject, which may be implicit or specified explicitly, and features of the subject can be used in the requirement (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87). Formally, the subject is a distinguished parameter, declared before any other parameter (OMG SysML v2.1 Beta 2, Part 1, p. 166). A requirement can only be satisfied by an entity that conforms to the subject’s definition: if the subject is a Vehicle, any usage defined by Vehicle or a specialisation of it may satisfy it (OMG SysML v2.1 Beta 2, Part 1, p. 161, p.166). If no subject is declared, it is implicitly Anything (OMG SysML v2.1 Beta 2, Part 1, p. 162). Seidewitz, Intro to the SysML v2 Language: Textual Notation shows subjects that are a port and an action (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 88). The checker enforces subject-first for directed parameters and actors (“Subject must be first parameter.”). A plain attribute declared before the subject passes: Seidewitz, Intro to the SysML v2 Language: Textual Notation calls such attributes parameters (sl.86, as worked example (a) does), but they have no direction, and the checker applies the rule only to directed ones. The course writes the subject first in every case. For AeroLink the subject is the allocation decision you made in Week 8, now in the model: REQ-SYS-001 is about ChargingSystems, REQ-SYS-005 about the Scheduling logical element. By course convention, taken from the reference model, a stakeholder requirement’s subject is the enterprise, because it constrains the service as a whole.`,`The ID and the statement. Any element can have a short name, an alternate name chosen by the modeller (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87). For a requirement, the short name is also its requirement ID (OMG SysML v2.1 Beta 2, Part 1, p. 165). The course writes the ID as a quoted short name, <'REQ-SYS-001'> (Week 9), and the requirement’s informal text is its doc comment (OMG SysML v2.1 Beta 2, Part 1, p. 165). A requirement whose only content is a doc comment is still a constraint with nothing to evaluate. RB-8.4 calls that “requirements as comments” and scores it at level 1. Write the measurable criterion of Week 4 as the required constraint.`,`Assumptions and groups. A requirement may also have assumed constraints (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 87). Its required constraints only apply if all the assumed constraints hold. Formally, the requirement’s effective constraint is an implication: if all assumptions are true, all required constraints must be true (OMG SysML v2.1 Beta 2, Part 1, p. 161, p.165). A requirement can also group other requirements, by reference (require …) or by composition (a nested requirement usage). By default the grouped requirements take the group’s subject, which can be bound explicitly instead, and they are treated as required constraints of the group (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90; OMG SysML v2.1 Beta 2, Part 1, p. 167). So satisfying a group means satisfying every member (OMG SysML v2.1 Beta 2, Part 1, p. 161) on the one subject the satisfy binds. Members may keep different subjects and the group still be satisfiable, when each member’s subject is bound to a feature of the group’s subject (OMG SysML v2.1 Beta 2, Part 1, p. 167: subject engine = vehicle.engine; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90). A group whose members keep independently typed subjects of their own, bound neither to the group’s subject nor to its features, is a collection for organisation: no single satisfy binding reaches all of them, and it cannot be satisfied as a whole. The reference model has two groups: stakeholderRequirements and systemRequirements.`],citations:[{reading:`R74`,pages:`86–90`},{reading:`R83`,pages:`161–162`},{reading:`R83`,pages:`165–167`}],provenance:`mixed`},{id:`w10-worked-req`,kind:`worked-example`,title:`Worked example (a): three latency requirements from one requirement definition`,paragraphs:[`REQ-SYS-005 (aircraft assignment within 60 s), REQ-SYS-008 (no-go flag within 2 min) and REQ-SYS-009 (fire alarm transmitted within 30 s) share one form: a measured latency shall not exceed a limit. The listing aerolink_requirement_def_usage.sysml factors that form into a requirement definition, LatencyLimit (lines 16–21). It has two parameters, latency and latencyLimit, its doc statement, and one required constraint, latency <= latencyLimit. It has no subject of its own, so its subject is implicitly Anything.`,`Each usage then does four things, following the pattern of Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 89, with the doc comment added from OMG SysML v2.1 Beta 2, Part 1, p. 165 (the slide has none). It declares the course ID as its short name and the reference title as its declared name: requirement <'REQ-SYS-005'> 'Aircraft assignment time' : LatencyLimit. It carries the Week 4 statement as its doc comment, word for word, so that the model and the requirements table cannot drift apart. It declares its subject, scheduling : Scheduling, which narrows Anything to the element the “shall” is about. And it binds both parameters: latency is redefined as a feature of the subject, scheduling.assignmentLatencyP99, and latencyLimit is bound to 60 [s]. The group latencyRequirements (lines 47–54) collects the three by reference. It declares no subject and each member keeps its own, as in the reference’s systemRequirements group. Grouped requirements take the group’s subject by default (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90), but no one element is a Scheduling, a MaintenanceManagement and a PadFireDetectionSystem at once, so this group organises and is never satisfied as a whole. The checker accepted the listing with no errors and no warnings.`,`Two cautions. A requirement definition is worth writing only when several requirements share a form; the reference writes all twenty as plain usages, which is equally correct. And the redefinition of latency is not decoration: without it, latency would be a free parameter, and a satisfy could not connect the constraint to anything the design element has. The translator below checks each field you type against a cited criterion. It is a teaching aid, not a SysML parser; only the checker decides whether the assembled text is valid.`],sysml:[{file:`week10/aerolink_requirement_def_usage.sysml`,caption:`REQ-SYS-005, -008 and -009 as usages of one requirement definition, with subject, doc, bound parameters, short-name IDs and a group (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R74`,pages:`86–90`},{reading:`R83`,pages:`161`},{reading:`R83`,pages:`165`}],provenance:`mixed`},{id:`w10-structure`,kind:`concept`,title:`Structure: ports, conjugation, interfaces, connections, bindings and flows`,paragraphs:[`Ports. A port definition defines features that can be made available through ports. It replaces SysML v1’s interface blocks. A port is a connection point through which a part definition makes some of its features available in a limited way, like a v1 proxy port (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20). A port is not a part: it does not own the battery or the software it gives access to. Ports may have attribute and reference features. A feature with a direction (in, out or inout) is a directed feature, and directed features are always referential. Two ports are compatible for connection if they have directed features that match with inverse directions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20). Every port definition has an implicit conjugate that reverses its inputs and outputs, written with ~: port chargeInlet : ~ChargingPort (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 21). The reference model’s convention is to write each port definition from the producing side and to type the consuming side’s port with ~.`,`Connections and interfaces. A connection definition is a part definition whose usages are connections between its ends. A connection is a usage that connects two other features, and dot notation, a feature chain such as 'PHY-003'.chargerOutlet, reaches a nested feature in context (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 18–19). An interface definition is a connection definition whose ends are ports. An interface usage is a connection usage defined by an interface definition, and it connects two compatible ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22). Multiplicities written on the ends are cross multiplicities: they constrain how many connections each participant has, not how many participants there are. The ends themselves always have multiplicity 1..1 relative to the connection definition, and the default cross multiplicity of an interface is 0..* (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 18, sl.22–23).`,`Bindings and flows. A binding connection asserts that two features are equivalent, that is, have equal values in the same context. The feature value notation, attribute :>> chargeTimeToDispatch = 18 [min], combines a feature with a binding: it is a binding, not an initial or default value (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 24–25). A flow transfers a payload from an output of a source to an input of a target. It is actually a connection between the source and target ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 26–27). Flows can be defined inside an interface definition, and they are established whenever the interface is used (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 28).`,`Logical and physical structure (course convention). SysML v2 has no separate “logical” and “physical” kinds of part. The distinction is the course’s viewpoint convention from Week 8 (RB-7.1), and it is realised by packages. Logical holds the FN actions and the LOG and AI parts that perform them. Physical holds the item defs, port defs, interface defs and PHY parts, and the IF interface usages between PHY ports. Keeping them apart is what makes allocation meaningful: you can reallocate a function without deleting it (Week 9, q9-11).`],citations:[{reading:`R71`,pages:`18–29`}],provenance:`mixed`},{id:`w10-worked-ports`,kind:`worked-example`,title:`Worked example (b): IF-005 (power) and IF-010 (data) as ports, interface definitions and connections`,paragraphs:[`The listing aerolink_ports_interfaces.sysml takes two of the reference model’s fourteen interfaces. IF-005 is the physical aircraft ↔ charger power interface; IF-010 is the information interface between the chargers and the operations centre. ChargingPort (line 24) has one directed feature, out item energy : ElectricalEnergy. The charger’s chargerOutlet is a ChargingPort; the aircraft’s chargeInlet is a ~ChargingPort, whose energy is therefore an input. The two ports have matching features with inverse directions, so they are compatible (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 20–21). MaintenanceDataPort does the same for the INFO-003 item: the item definition the Week 8 information view called Maintenance Data is now what the port carries.`,`AircraftChargerPower (lines 27–31) is an interface definition with a charger end and an aircraft end. It also contains a flow from the charger’s energy to the aircraft’s, so every IF-005 usage establishes that flow (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 28). The usage on lines 49–52 carries the ID as its short name and connects the ends explicitly with reference subsetting, chargerSide ::> 'PHY-003'.chargerOutlet, in the form of Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22. IF-010 (lines 53–57) uses the shorthand connect a to b, in which the ends are taken in order. Its INFO-003 flow is a separate flow usage from an output of one port to an input of the other (lines 58–59; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 27). Both forms are accepted, and the reference model uses the shorthand. Lab L10 asks for at least three such port and interface definitions with connections. Take the third from your own CP3 N² matrix.`,`The teaching listing invalid_port_typed_by_item.sysml is a draft of the same model with one line changed. The team wanted “the charger has a port for the maintenance data” and typed the port with the item it carries, port sessionDataOut : 'INFO-003'. The checker rejects line 12 with “A port must be typed by port definitions.” The fix is the pair you have just read. An item definition says what flows. A port definition says which directed features a part exposes, and so which item goes in or out. The checker enforces this rule, but many other port and interface mistakes pass without a message.`],sysml:[{file:`week10/aerolink_ports_interfaces.sysml`,caption:`IF-005 and IF-010: port definitions, conjugate ports, interface definitions (one with a flow), interface usages and the INFO-003 item flow (FICTIONAL values)`,intent:`conformant`},{file:`week10/invalid_port_typed_by_item.sysml`,caption:`Teaching listing: a port typed by the item it carries — rejected by the checker`,intent:`intentionally-invalid`}],citations:[{reading:`R71`,pages:`20–22`},{reading:`R71`,pages:`27–28`}],provenance:`mixed`},{id:`w10-relationships`,kind:`concept`,title:`satisfy, allocate, perform and dependency: what each relationship asserts`,paragraphs:[`satisfy is an assertion. A satisfy requirement usage is a requirement usage whose subject parameter must be bound to a satisfying feature, and it is a kind of assert constraint usage. Together, these mean that it asserts the requirement is satisfied — that it always evaluates to true — when its subject is bound to the satisfying feature (OMG SysML v2.1 Beta 2, Part 1, p. 168). Seidewitz, Intro to the SysML v2 Language: Textual Notation gives the formal reading: a requirement is satisfied for a subject if, when all its assumed constraints are true, all its required constraints are true (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 91). A satisfy is therefore not a trace link, a plan or a wish. It is the model claiming that the design meets the requirement. If the model’s own values contradict the claim, the model is inconsistent. Verification is separate: it supplies the evidence that the real system makes the claim true, and Week 12 models it. OMG SysML v2.1 Beta 2, Part 1 also defines the negated form, not satisfy, which asserts that the given feature does not satisfy the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 168). Nested in a definition or usage, a satisfy may leave the satisfying feature implicit; it is then the containing definition or usage (OMG SysML v2.1 Beta 2, Part 1, p. 168–169).`,`allocate assigns responsibility. An allocation specifies that some or all of the responsibility for realising the intent of the source is allocated to the target. Allocations define traceable links across the structures and hierarchies of a model, perhaps as a precursor to more rigorous specifications and implementations, and an allocation can be refined by nested allocations (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106). In SysML v2 an allocation is not a dependency, as it was in v1, but an instantiable connection across model features. An allocation definition can restrict which kinds of feature it connects through the types of its ends (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 107). An allocation asserts nothing about performance. FN-006 allocated to PHY-003 says the chargers are responsible for charging; it does not say they charge in 20 min. The satisfy says that.`,`perform and dependency. perform, written inside a part, identifies the owning part as the performer of an action owned elsewhere (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 41); the reference uses it for “LOG performs FN”. A dependency indicates that client elements require supplier elements for their complete specification; it is entirely a model-level relationship without instance-level semantics (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 105). The course realises traceability-only links such as derives-from as dependencies or the library derivation connection, because SysML has no derive keyword. Nor is allocation decomposition: decomposition is composition within one structure, while allocation maps across structures and leaves both intact.`,`The classifier below gives ten engineering statements. For each, decide which relationship expresses it, or whether the model should assert nothing yet. Read the explanation for every item you miss.`],citations:[{reading:`R83`,pages:`168–169`},{reading:`R74`,pages:`91`},{reading:`R76`,pages:`105–107`},{reading:`R72`,pages:`41`}],provenance:`mixed`},{id:`w10-worked-satisfy`,kind:`worked-example`,title:`Worked example (c): satisfy and allocate side by side on the charging thread`,paragraphs:[`aerolink_satisfy_allocate.sysml puts four packages around one thread of the reference model: REQ-SYS-001 → FN-006 → LOG-002 → PHY-003. Logical holds three FN actions and LOG-002, which performs all three. Physical holds PHY-003, whose chargeTimeToDispatch is bound to the current estimate of 18 [min] (TPM-001), and PHY-004. Requirements holds REQ-SYS-001 (subject ChargingSystems) and REQ-SYS-006 (fleet availability ≥ 90 %, subject FleetManagement). Traceability holds the relationships, each named as the reference names them.`,`Read each relationship as a sentence, and say what it claims. Line 57, satisfy Requirements::'REQ-SYS-001' by Physical::aeroLink.'PHY-003', binds the subject chargingSystem to PHY-003 and asserts that PHY-003’s charge time is at most 20 min. The model can support that claim, because PHY-003’s bound estimate is 18 min. Line 58 binds REQ-SYS-006’s subject to LOG-002 and asserts that its availability is at least 90 %. Note what that claim rests on: LOG-002 binds no availability value, so the claim is the design team’s judgement, and only verification can confirm it. Lines 60–65 are allocations. REQ-SYS-001 is allocated to FN-006 (the function responsible for its intent). FN-006 and FN-007 are allocated to PHY-003, FN-009 to PHY-004. LOG-002 is allocated to both PHY-003 and PHY-004, because fleet management is split between the chargers’ control software and the operations centre.`,`Two consistency checks follow from reading the chains; they are review questions, not checker rules, and the CP4 RID review will ask them. First, the satisfy and the allocation chain should agree: REQ-SYS-001 → FN-006 → PHY-003, and the satisfier is PHY-003. A requirement allocated to a function on one element but satisfied by another needs a reason. Second, each satisfier must conform to the subject’s definition (OMG SysML v2.1 Beta 2, Part 1, p. 161): PHY-003 is a ChargingSystems and LOG-002 a FleetManagement.`],sysml:[{file:`week10/aerolink_satisfy_allocate.sysml`,caption:`The charging thread: two satisfy usages and six allocations, read as claims (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R83`,pages:`161`},{reading:`R83`,pages:`168`},{reading:`R76`,pages:`106`}],provenance:`mixed`},{id:`w10-checker`,kind:`concept`,title:`Predict the checker: ports, interfaces, satisfy and allocate`,paragraphs:[`The app cannot run the course-designated checker (Week 9). The activity below shows nine short listings, each a decision a team makes this week, with the result the course’s validation script recorded for exactly that text. Predict each outcome before you reveal it. Some listings break a rule in this week’s readings and pass silently; others are rejected for a reason you may not expect. Keep a list of the silent passes: it is your checklist for reviewing your own model and for the CP4 RID review.`],citations:[],provenance:`instructor-authored`},{id:`w10-checker-commentary`,kind:`worked-example`,title:`Worked example (c), continued: what the checker checked — read after the activity`,paragraphs:[`The table summarises the recorded runs of this week’s listings and of the course’s scratch probes (release 2026-08, 2026-10-11; the probe files are listed in the authoring notes). The checker enforces kinds: a port must be typed by a port definition, an interface end must be a port, the target of satisfy must be a requirement usage, a group may only require constraints, and the subject must come before any directed parameter or actor. It also refuses to override a bound value. It does not enforce compatibility, conformance of an interface’s connected ports to the definition’s ends, allocation directions, a group’s members sharing a subject that one satisfier can conform to, or the truth of a satisfy. A satisfy whose satisfier violates the requirement passes with no message, because the tool evaluates no constraints. A satisfy by the wrong kind of element passes with a warning.`,`This matters for CP4. RB-8.1 rewards zero errors and zero warnings, or warnings explained; RB-8.3 and RB-8.4 reward correct semantics, and the silent rows are where a model scores 4 on the first and 2 on the others. Review each connect line against its interface definition’s ends and each port pair for inverse directions, read each allocation in the course direction (REQ → FN, FN/LOG/AI → PHY), and check each satisfy against its satisfier’s bound values. These results describe release 2026-08 only.`],table:{caption:`Recorded checker behaviour on this week’s constructs (release 2026-08; listings in sysml/week10, probes in the notes)`,header:[`Construct`,`Rule in the readings`,`Recorded result`],rows:[[`Port typed by an item definition`,`A port is typed by a port definition (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20)`,`FAIL: “A port must be typed by port definitions.”`],[`Interface usage connecting two parts`,`Interface ends are ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22)`,`FAIL: same typing rule, once per end`],[`Interface between two ports with the same directions`,`Compatible ports have inverse directions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20)`,`PASS, no message`],[`Interface end connected to a port of another definition`,`An interface connects two compatible ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22)`,`PASS, no message`],[`Flow from an input to an output (probe)`,`A flow goes from an output to an input (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 27)`,`PASS, no message`],[`satisfy by a port of the right element`,`Subject bound to the satisfier (OMG SysML v2.1 Beta 2, Part 1, p. 168)`,`PASS with WARNING “Bound features should have conforming types”`],[`satisfy with requirement and satisfier swapped`,`satisfy <requirement> by <feature> (OMG SysML v2.1 Beta 2, Part 1, p. 168)`,`FAIL: three errors, “Must reference a requirement.”, “Must reference a constraint.” and “A requirement must be typed by one requirement definition.” (their order varies between runs)`],[`satisfy naming a requirement definition`,`The satisfied requirement is a feature (OMG SysML v2.1 Beta 2, Part 1, p. 168)`,`FAIL: name does not resolve as a Feature`],[`satisfy body rebinding the bound limit`,`A feature value is a binding (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 25)`,`FAIL: “Cannot override a binding feature value”`],[`satisfy whose satisfier’s value violates the limit (probe)`,`satisfy asserts the requirement is true (OMG SysML v2.1 Beta 2, Part 1, p. 168)`,`PASS, no message`],[`Allocation against its definition’s end types; FN → PHY written PHY → FN (probe)`,`Allocated features conform to the ends (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 107)`,`PASS, no message`],[`allocate … by …`,`allocate … to … (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106)`,`FAIL: syntax, “mismatched input ‘by’ expecting ‘to’”`],[`Group that requires an action (probe)`,`Grouped requirements are required constraints (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90)`,`FAIL: “A constraint must be typed by one constraint definition.”`],[`Requirement usage defined by two requirement definitions (probe)`,`Defined by a single requirement definition (OMG SysML v2.1 Beta 2, Part 1, p. 165)`,`FAIL: “A requirement must be typed by one requirement definition.”`],[`Directed parameter (in attribute) or actor declared before the subject (probe)`,`The subject comes before any other parameter (OMG SysML v2.1 Beta 2, Part 1, p. 166)`,`FAIL: “Subject must be first parameter.” (a plain attribute before the subject passes: Seidewitz, Intro to the SysML v2 Language: Textual Notation calls it a parameter, but it has no direction)`],[`Group whose members have different subjects, satisfied by one element (probe)`,`A group is satisfied only if all its members are (OMG SysML v2.1 Beta 2, Part 1, p. 161)`,`PASS, no message`]]},citations:[{reading:`R71`,pages:`20–27`},{reading:`R76`,pages:`106–107`},{reading:`R83`,pages:`161`},{reading:`R83`,pages:`165–166`},{reading:`R83`,pages:`168`},{reading:`R74`,pages:`90`}],provenance:`mixed`},{id:`w10-worked-gap`,kind:`worked-example`,title:`Worked example (d): recording a satisfy gap honestly`,paragraphs:[`L10 and CP4 ask for a satisfy for every REQ-SYS “or a recorded gap”. A gap is not a failure of the lab. It is information the model must carry. There are two common gaps, and the listing aerolink_satisfy_gap.sysml shows both in a what-if variant of the reference design. In the first, the candidate satisfier exists but the evidence is against it. The charger supplier’s estimate has risen to 24 min, the Week 9 what-if. Writing satisfy 'REQ-SYS-001' by PHY-003 would assert that 24 ≤ 20. The checker would accept it, but the model would contradict itself. In the second, no candidate exists: this team’s CP3 architecture has no fire-detection element, so nothing in the model conforms to REQ-SYS-009’s subject.`,`The course convention (Week 10, adopted by the course and not prescribed by the SysML texts) is to record a gap in three places. In the model: no satisfy for that requirement, and an @Issue annotation in the requirement whose text starts “SATISFY GAP” and names the candidate, the evidence, the action and the owner, with @StatusInfo set to open. Both are standard-library metadata (ModelingMetadata); the reference model already uses @StatusInfo for its TBDs. In the L10 gap table: one row per gap with the same content. And in the AROU register, when the gap is a risk, as here with R-001. The checker accepted the listing with no errors and no warnings.`,`When is not satisfy the right record instead? A negated satisfy asserts that the feature does not satisfy the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 168). That is a claim, just as strong as satisfy. It fits a case the team has decided on evidence — a rejected alternative, or a certified test result — not an open question. And when the requirement’s limit is TBD? The reference model asserts satisfy for REQ-SYS-010 although TBD-02 is open. The intent, to limit power to whatever limit is configured, is defensible, but the model does not say it. connectionLimit is a requirement attribute that nothing binds, and an assertion over an unbound feature does not mean “for every value”: it constrains the feature to values that make the assertion true, which a large enough limit always does. To say “the configured limit”, bind it to the satisfier’s value, attribute connectionLimit : PowerValue = chargingSystem.connectionLimit; (accepted in a course probe). Until the reference does that, read its REQ-SYS-010 satisfy as an intent the model does not yet express. Verification stays inconclusive until U-002 closes (Week 12). The test for every satisfy is the same: could you defend it at a review today, from what the model says?`],sysml:[{file:`week10/aerolink_satisfy_gap.sysml`,caption:`What-if variant: two satisfy gaps recorded with @Issue and @StatusInfo instead of false or unsupported satisfy claims (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R83`,pages:`168`}],provenance:`mixed`},{id:`w10-advanced`,kind:`advanced`,title:`Advanced analysis: assumptions, actors, and what a satisfy then claims`,paragraphs:[`Read REQ-SYS-007 in the reference: the eVTOL aircraft shall complete the 25 km design trip within 16 min block time “in still air”. The last three words are a condition on the environment, not on the aircraft. The listing aerolink_assume_still_air.sysml models them as a gate on the requirement. The weather, the type of EXT-003, is declared as an actor. An actor parameter represents a role played by an entity external to the subject but necessary for the satisfaction of the requirement, and its features may be used in the assumed constraints to constrain the environment in which the required constraints apply (OMG SysML v2.1 Beta 2, Part 1, p. 162). The assumption stillAir (weather.windSpeed <= 0.5 [m/s], a FICTIONAL tolerance, since an exact equality would almost never hold) and the requirement withinBlockTime (aircraft.designTripBlockTime <= maxBlockTime) are both named. The checker accepted it with no messages.`,`Now apply the formal reading. The effective constraint is: if stillAir, then withinBlockTime (OMG SysML v2.1 Beta 2, Part 1, p. 165). In a 10 m/s headwind the assumption is false, and the requirement is satisfied whatever the block time. Logically, “if A then R” is weaker than R alone: it demands exactly R where A holds and nothing elsewhere. Two consequences follow for engineering, and they come from the course, not the source. First, every assumption marks a region the requirement deliberately does not cover. Someone must decide whether another requirement covers it. AeroLink’s capacity analysis (REQ-STK-004) uses the 16 min block time on every trip, windy or not, which a reviewer should challenge. Second, a satisfy of REQ-SYS-007 by the aircraft now claims performance only in still air. VER-007’s flight test must either fly in still air or correct for wind, or it does not test the claim.`,`Gate or reference condition? The listing reads “in still air” as a gate. In a performance requirement the phrase is more often a reference condition: it says under which conditions the quantity is defined, not when the requirement applies. And the gate scopes nothing here: designTripBlockTime is one design value, a still-air estimate in the reference, that does not vary with weather.windSpeed, so the assumption only makes the requirement vacuously true whenever the wind exceeds the tolerance, which is most real flights. The reference-condition reading keeps the condition with the quantity: name the feature for it (stillAirBlockTime), state the condition in its doc, and have verification correct measured times to still air. The course recommends that reading for “in still air” (a course choice; the source gives the semantics, not the choice). Use an assumption when the condition really bounds where the requirement applies and the required quantity depends on what it constrains, like q10-4’s gust limit.`,`Satisfy, consistency and evidence. A model in which PHY-003 binds 24 min and asserts satisfy of a 20 min requirement says something false about itself (OMG SysML v2.1 Beta 2, Part 1, p. 168), and the release 2026-08 checker reports nothing. Consistency is established by review and, from Week 12, by analysis and verification cases. An allocation without a satisfy says who is responsible, not what has been achieved (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106): a CP4 model in which every REQ-SYS is allocated but few are satisfied has a thread that stops halfway, and RB-9.2 counts exactly that at CP5.`],sysml:[{file:`week10/aerolink_assume_still_air.sysml`,caption:`REQ-SYS-007 with the weather as actor, an assumed constraint (still air) and a required constraint (FICTIONAL values)`,intent:`conformant`}],citations:[{reading:`R83`,pages:`162`},{reading:`R83`,pages:`165`},{reading:`R83`,pages:`168`},{reading:`R76`,pages:`106`}],provenance:`mixed`},{id:`w10-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`Three industry practices map directly onto this week’s constructs (instructor application; the SysML statements are cited). Interface control documents agreed between an aircraft OEM and a charger supplier become interface definitions owned by neither party’s design. The port definition replaces v1’s interface block as the thing each side exposes (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20). Requirement specifications become requirement usages whose short name is the requirement ID that contracts and test plans quote (OMG SysML v2.1 Beta 2, Part 1, p. 165). A design review’s compliance matrix is a view of the satisfy relationships, and an honest one shows the gaps.`,`The third practice concerns assumptions. Certification and operational approvals are always conditional — on weather, on procedures, on maintenance. A requirement that states its applicability conditions as assumptions, and keeps its reference conditions with the quantity, makes the operating envelope part of the model rather than a sentence in a report (OMG SysML v2.1 Beta 2, Part 1, p. 162, p.165).`],citations:[{reading:`R71`,pages:`20`},{reading:`R83`,pages:`162`},{reading:`R83`,pages:`165`}],provenance:`mixed`},{id:`w10-lab`,kind:`lab`,title:`Lab L10 — requirements and structure (model v0.2)`,paragraphs:[`Start from your model v0.1 and its checker log. In class you build the REQ-SYS part of the Requirements package and the ports and interfaces; out of class you complete the requirement set, the satisfy usages and gap records, and the allocations. Every CP2 requirement becomes a requirement usage with its ID as quoted short name, its Week 4 statement as doc, the element the “shall” is about as subject, and its criterion as a required constraint (TBD values unbound, with a doc pointer and @StatusInfo). Add the CP3 functions and logical elements with perform; at least three port and interface definitions with connected interface usages and their item flows; a satisfy for every REQ-SYS or a recorded gap; and allocate FN → PHY as in your CP3 matrix, or a recorded change. Run the file until the checker reports zero errors, and explain every warning.`],citations:[],provenance:`instructor-authored`},{id:`w10-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: L10 model v0.2 with checker log, satisfy-and-allocation table and gap table, end of Week 10. It is scored formatively on RB-8 now and becomes the core of CP4, due in Week 11 (10 % of the course grade: RB-8 75 · RB-17 15 · RB-12 10). Individual: readiness quiz Q9, a review-notebook entry with a time log and, for graduate students, the assume/require memo (always read; formative feedback on RB-8.4; informs RB-16.1).`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w10-act-translator`,title:`Requirement-to-SysML translator`,component:`w10-req-translator`,purpose:`Map one of your workspace requirements to the parts of a SysML v2 requirement usage — short name, declared name, doc, subject, parameter and value, required constraint — and get cited feedback on each field. A teaching aid, not a SysML parser.`,instructions:[`Choose a requirement from your workspace, or tick the practice box to use the instructor reference requirements (read-only).`,`Fill each field as you would write it in your model; read every ✗ and ? message and its source.`,`Copy the assembled text into your model and run the checker. The tool does not validate SysML; only the checker does.`],objectives:[`B10.1`],inBlock:`w10-worked-req`},{id:`w10-act-relations`,title:`satisfy, allocate, perform, dependency — or nothing yet?`,component:`w10-relation-classifier`,purpose:`Classify ten engineering statements by the SysML v2 relationship that expresses them, with an explanation of what each relationship asserts and its source.`,instructions:[`Decide each statement before checking; two of them are not claims the model should make yet.`,`Check, and read the explanation for every item you missed.`],objectives:[`B10.3`],inBlock:`w10-relationships`},{id:`w10-act-predict`,title:`Predict the checker: ports, interfaces, satisfy and allocate`,component:`w10-predict-checker`,purpose:`Predict the outcome of nine pre-validated listings, then compare with the result recorded by the course-designated checker.`,instructions:[`Read each listing and choose your prediction before revealing; a revealed item is locked.`,`Compare with the recorded result. The app shows only results recorded for exactly the text on screen and never simulates the checker.`,`List the items that passed although they break a rule in the readings: these are your review checklist for L10 and CP4.`],objectives:[`B10.2`,`B10.3`],inBlock:`w10-checker`}],lab:{id:`L10`,title:`Requirements and structure (model v0.2)`,setting:`team`,durationMinutes:75,objectives:[`B10.1`,`B10.2`,`B10.3`],inputs:[`Model v0.1 and its checker log (L9)`,`CP2 requirements with IDs, statements, criteria, TBDs and parents (workspace)`,`CP3 functions, logical and physical elements, interfaces (N²), information items and the FN → PHY allocation matrix`,`Listings of worked examples (a)–(d) in sysml/week10; the instructor reference model v0.2 (sysml/reference/aerolink_v02_req_structure.sysml) as recovery input`,`The translator activity (this week)`],steps:[{title:`Before class — translate three requirements`,detail:`Use the translator on three of your CP2 requirements (at least one REQ-STK and one REQ-SYS with a TBD if you have one). Bring the assembled text and the open ✗ and ? items.`},{title:`In class — brief (5 min)`,detail:`Deliverables; the four L10 minimums; the gap convention; zero errors and warnings explained.`},{title:`In class — Requirements package (25 min)`,detail:`In class, at least the REQ-SYS set (or six requirements, if your team has fewer REQ-SYS); the rest out of class, as the lab introduction says. Each requirement as a usage: <'ID'> short name, quoted declared name, doc statement verbatim from the workspace, subject (REQ-STK: the enterprise; REQ-SYS: the element the “shall” is about), the criterion as a required constraint over a feature of the subject with a named, bound parameter. TBD values unbound with a doc pointer to the U item and @StatusInfo { status = StatusKind::tbd; }. Add the stakeholder and system requirement groups. Use a requirement definition only where several requirements share a form.`},{title:`In class — ports and interfaces (20 min)`,detail:`From your N² matrix choose at least three interfaces, at least one physical and one information. For each: a port definition written from the producing side; ports on both part definitions (consumer side with ~); an interface definition with two port ends; an IF usage in the system-of-interest part connecting the two PHY ports, with its ID as short name and its type and carried items in doc; and an item flow for each INFO it carries.`},{title:`Instructor checkpoint (10 min)`,detail:`Show one requirement, one interface and one run. Typical findings: requirements with doc but no constraint; enterprise subjects on REQ-SYS; ports typed by items; two ports with the same direction; unquoted IDs in connect lines.`},{title:`In class — check, then plan satisfy and allocate (10 min)`,detail:`Run the file until it reports zero errors. Then draft the satisfy-and-allocation table: for each REQ-SYS, the satisfier (an element whose definition is the subject’s) and its basis (bound value, TPM estimate or design rationale), or the gap; for each FN, its PHY from the CP3 matrix.`},{title:`Out of class — logical structure, satisfy, allocate, gaps`,detail:`Logical package: FN actions, LOG and AI parts with perform. Traceability: a satisfy for every REQ-SYS you can defend; for every other REQ-SYS a recorded gap (no satisfy; @Issue “SATISFY GAP …” with candidate, evidence, action, owner; @StatusInfo open; a gap-table row). allocation … allocate for every FN → PHY of CP3 (and REQ → FN, LOG → PHY as in the reference), or a recorded change with its reason. Review every connect, flow and allocation against the silent-pass list from the predict activity.`},{title:`Lab record (5 min in class; final run out of class)`,detail:`Model v0.2, the checker log of the final run (zero errors; each warning explained), the satisfy-and-allocation table and the gap table, committed to the team repository.`}],artefacts:[{idPrefix:`Model v0.2`,description:`Team SysML v2 file: v0.1 plus all CP2 REQ as requirement usages; Logical (FN, LOG, AI with perform); ≥ 3 port/interface definitions with IF usages and item flows; satisfy and allocation relationships`,minimum:`Accepted by the course-designated checker with zero errors; every CP2 REQ with subject and quoted short-name ID; every REQ-SYS satisfied or a recorded gap; every CP3 FN allocated to a PHY`},{idPrefix:`Satisfy-and-allocation table`,description:`Per REQ-SYS: satisfier and its basis, or gap; per FN: PHY, with any change from CP3 and its reason`,minimum:`Every REQ-SYS and every FN appears once`},{idPrefix:`Gap table`,description:`Per satisfy gap: requirement, candidate (or none), evidence, action, owner, related AROU item`,minimum:`Matches the @Issue annotations in the model one to one`},{idPrefix:`Checker log`,description:`Kernel or validation-script output for the final model file`,minimum:`Zero errors; every warning explained`}],continuity:`Model v0.2 is the CP4 submission in all but behaviour: in Week 11 you add the L11 behaviour (formative), submit CP4, and a peer team reviews it asynchronously with RIDs in days 1–3 of Week 12, many of which will target the checks the tool does not make (interface compatibility, satisfy claims, allocation direction). Week 12 adds verification cases whose objectives verify the requirements you modelled today, MOE/MOP attributes on the subjects, and the trace audit that counts satisfy and allocate hop by hop; every gap recorded today must then be closed, justified or carried as a risk. The satisfy and allocation chains are the middle of the 11-link threads of CP5.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`L10`,title:`L10 model v0.2, satisfy-and-allocation table, gap table and checker log`,mode:`team`,due:`Model v0.2 with tables and checker log: end of Week 10 (it becomes CP4, due Week 11). Graduate assume/require memo: end of Week 10.`,weight:`L10 is formative: model v0.2 receives feedback on RB-8 now and is assessed summatively as CP4 in Week 11 (10 % of the course grade: RB-8 75 · RB-17 15 · RB-12 10). Graduate memo: review notebook (RB-16, 5 %), always read.`,instructions:[`Build model v0.2 as in lab L10 and check it with the course-designated checker until it reports zero errors; explain every remaining warning.`,`Complete the satisfy-and-allocation table and the gap table; every gap in the table has its @Issue in the model and vice versa.`,`Review your own model against the silent-pass list from the predict activity (port directions, interface ends, flow directions, allocation directions, satisfy claims against bound values) and record what you checked.`,`Graduate students (individually): write the assume/require memo (template section 6). Any SysML you write must be run through the checker, and you report what it said.`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Model v0.2 and checker log (RB-8.1)`,guidance:`The .sysml file and the checker output for the whole file. Zero errors; for each warning, the line, the message and the fix or the reason it is acceptable. A “Bound features should have conforming types” warning on a satisfy is not acceptable: fix the satisfier.`},{heading:`2. Requirements (RB-8.4, B10.1)`,guidance:`Count of CP2 requirements modelled (must be all). For three requirements of your choice: the subject and why it is the element the “shall” is about; the parameter and bound value against the statement; how a TBD is represented. Where you used a requirement definition, say which requirements share it and why. Name the groups.`},{heading:`3. Structure: ports and interfaces (RB-8.3, B10.2)`,guidance:`For each of ≥ 3 interfaces: IF ID and type; the port definition and its directed features; which side is conjugated and why; the interface definition’s ends; the connect line; the item flows it carries. State how you checked compatibility and end conformance, since the checker does not.`},{heading:`4. Satisfy, allocate and gaps (RB-8.4, B10.3)`,guidance:`The satisfy-and-allocation table: each REQ-SYS with its satisfier and the basis of the claim (bound value, TPM estimate or rationale), or its gap; each FN with its PHY and any change from CP3 with the reason. The gap table. For one satisfy, write in one sentence what it asserts and what evidence will confirm it in Week 12.`},{heading:`5. Self-review against the silent passes`,guidance:`A checklist of the constructs the checker did not check in the predict activity, with what you found in your own model and what you changed. This is the start of your CP4 review readiness.`},{heading:`6. Graduate: assume/require memo (individual, ≈ 1 page plus listing)`,guidance:`Using OMG SysML v2.1 Beta 2, Part 1 §7.21 (p.161–162 and 165; p.161, 165 and 168 are already read with the lesson, so only p.162 is new): choose REQ-SYS-001 (“from any landing state of charge at or above the 20 % reserve”), REQ-SYS-002 (“on the published vertiport procedures”) or a requirement of your own team that states a condition. (a) Identify the condition and decide whether it is an assumption that narrows the requirement’s scope or a requirement on another element, and why. (b) Model it: subject, an actor or parameter for the condition if needed, a named assume constraint and a named require constraint; run it through the checker and report the result. (c) Explain the semantics: the effective constraint as an implication; what the requirement says when the assumption is false; what a satisfy of your requirement then asserts. (d) Name the case your assumption excludes and say which requirement, decision or risk covers it, or record that nothing does, and state the conditions under which verification must be run for its result to bear on the claim.`},{heading:`7. AI usage statement (RB-12)`,guidance:`Tool, purpose, prompts, outputs and your evaluation. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner; unexplained AI syntax counts as a defect (RB-12.3). AI output is never evidence of what the checker accepts.`}],rubrics:[`RB-8`,`RB-12`,`RB-16`],rubricScope:`Model v0.2: formative feedback on RB-8.1 (validity), RB-8.3 (structure semantics: ports and interfaces typed; definition/usage) and RB-8.4 (requirements semantics: requirements with subject and ID; satisfy relates appropriate design elements), with RB-8.6 checked against the L10 minimums; summative RB-8 at CP4 (Week 11). Graduate assume/require memo: a required review-notebook entry that is always read (RB-16 graduate-task rule), given formative feedback on RB-8.4 (requirements semantics), and informing RB-16.1 (engineering reasoning). AI statement: RB-12.1–12.3.`,aiUse:`AI tools may explain checker messages, suggest SysML syntax or draft doc text. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner; unexplained AI syntax is a defect (RB-12.3). AI output may not be used as evidence of what the checker accepts or of what a satisfy asserts: only a recorded run and the cited specification count. The satisfy-and-gap decisions and the graduate memo are the students’ own reasoning.`,objectives:[`B10.1`,`B10.2`,`B10.3`]},quiz:[{id:`q10-1`,bloom:`Apply`,objective:`B10.1`,prompt:`A new FICTIONAL requirement reads: “REQ-SYS-021: The booking platform shall return a fare quote within 3 s of a ride request.” PassengerBookingPlatform (PHY-007’s definition) has an attribute requestToQuoteTime : DurationValue. Which declaration follows the course conventions and gives a constraint that can be evaluated?`,options:[{id:`a`,text:`requirement <'REQ-SYS-021'> 'Fare quote time' { doc /* The booking platform shall … */ subject booking : PassengerBookingPlatform; attribute maxQuoteTime : DurationValue = 3 [s]; require constraint { booking.requestToQuoteTime <= maxQuoteTime } }`,correct:!0,explanation:`Correct. The short name is the requirement ID, quoted because it contains hyphens (OMG SysML v2.1 Beta 2, Part 1, p. 165, p.49–50); the statement is the doc; the subject is the element the “shall” is about; the parameter is bound to the value of the text; the required constraint reads a feature of the subject (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–89).`},{id:`b`,text:`requirement <'REQ-SYS-021'> 'Fare quote time' { doc /* The booking platform shall return a fare quote within 3 s of a ride request. */ subject enterprise : AeroLinkEnterprise; attribute maxQuoteTime : DurationValue = 3 [s]; }`,correct:!1,explanation:`Two defects: the subject is the enterprise, so no single design element can satisfy it, and the requirement has no required constraint — only a comment and an unused parameter (RB-8.4 level 1).`},{id:`c`,text:`requirement <REQ-SYS-021> FareQuoteTime { doc /* The booking platform shall … */ subject booking : PassengerBookingPlatform; require constraint { booking.requestToQuoteTime <= 3 [s] } }`,correct:!1,explanation:`The hyphenated ID is unquoted, so the short name does not parse (OMG SysML v2.1 Beta 2, Part 1, p. 49–50). The literal limit is legal, but the course binds it as a named parameter so that a satisfy or verification case can refer to it.`},{id:`d`,text:`requirement def <'REQ-SYS-021'> 'Fare quote time' { doc /* The booking platform shall … */ subject booking : PassengerBookingPlatform; attribute maxQuoteTime : DurationValue = 3 [s]; require constraint { booking.requestToQuoteTime <= maxQuoteTime } }`,correct:!1,explanation:`This declares a requirement definition (a template) with the ID. The course puts requirement IDs on usages, which are what satisfy and verify refer to; a satisfy of a definition does not resolve.`}],cite:{reading:`R74`,pages:`86–89`}},{id:`q10-2`,bloom:`Analyse`,objective:`B10.1`,prompt:`A team reuses a definition requirement def TimeLimit { attribute measured : DurationValue; attribute limit : DurationValue; require constraint { measured <= limit } } for a new FICTIONAL requirement: requirement <'REQ-SYS-022'> 'Pad clearance time' : TimeLimit { subject vertiports : VertiportNetwork; attribute :>> limit = 90 [s]; }. The checker accepts the file. What is wrong with the requirement?`,options:[{id:`a`,text:`Nothing: the subject restricts which elements may satisfy it, and the bound limit gives the constraint its value, which is all a usage needs`,correct:!1,explanation:`The constraint compares measured with limit, and measured is never connected to anything.`},{id:`b`,text:`A requirement usage may not declare a subject when its definition declares none, so the subject must be moved into TimeLimit`,correct:!1,explanation:`A definition without a subject has the implicit subject Anything, which a usage may narrow (OMG SysML v2.1 Beta 2, Part 1, p. 162, p.166).`},{id:`c`,text:`The limit must be bound in the definition TimeLimit rather than in the usage, because a usage may only narrow the subject`,correct:!1,explanation:`The reverse: a usage will often bind the definition’s parameters to specific values (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 89).`},{id:`d`,text:`measured is never redefined as a feature of the subject, so the constraint never reads the vertiports and a satisfy asserts nothing`,correct:!0,explanation:`Correct. The template pattern works by restricting the subject and redefining the definition’s parameters in terms of it, as OMG SysML v2.1 Beta 2, Part 1’s MaximumMass example redefines massActual as the vehicle’s mass (OMG SysML v2.1 Beta 2, Part 1, p. 161). Redefine measured as the vertiports’ clearance time; a free parameter leaves the requirement unconnected to its subject.`}],cite:{reading:`R83`,pages:`161`}},{id:`q10-3`,bloom:`Apply`,objective:`B10.1`,prompt:`A team writes: requirement chargingSpecification { subject cs : ChargingSystems; requirement chargeTime : ChargeTimeRequirement; requirement outletPower : OutletPowerRequirement { subject outlet = cs.chargerOutlet; } } and later satisfy chargingSpecification by aeroLink.'PHY-003';. What does the satisfy assert?`,options:[{id:`a`,text:`Only chargeTime: outletPower declares its own subject, so it is a separate requirement outside the group`,correct:!1,explanation:`A composite requirement usage nested in a requirement is a subrequirement and a required constraint of its container whatever its subject (OMG SysML v2.1 Beta 2, Part 1, p. 167); declaring a subject only changes what it is about.`},{id:`b`,text:`That PHY-003 meets chargeTime, and that PHY-003 as a whole, not its outlet, meets outletPower`,correct:!1,explanation:`outletPower’s subject is bound explicitly to cs.chargerOutlet, so once the satisfy binds cs to PHY-003, outletPower is about PHY-003’s charger outlet (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90).`},{id:`c`,text:`That PHY-003 meets chargeTime, and that PHY-003’s chargerOutlet port meets outletPower`,correct:!0,explanation:`Correct. Both nested usages are required constraints of the group (OMG SysML v2.1 Beta 2, Part 1, p. 167). chargeTime declares no subject, so its subject is bound to the group’s cs; outletPower’s subject is bound explicitly to a feature of cs, as Seidewitz, Intro to the SysML v2 Language: Textual Notation does for engine.clutchPort (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 90). Binding cs to PHY-003 therefore claims both.`},{id:`d`,text:`Nothing yet: each nested requirement needs a satisfy of its own before anything is claimed`,correct:!1,explanation:`Subrequirements are required constraints of the containing requirement (OMG SysML v2.1 Beta 2, Part 1, p. 167), so satisfying the group claims every member.`}],cite:{reading:`R83`,pages:`167`}},{id:`q10-4`,bloom:`Analyse`,objective:`B10.1`,prompt:`A FICTIONAL requirement on the aircraft has assume constraint { weather.gustSpeed <= 10 [m/s] } and require constraint { aircraft.landingDispersion <= 3 [m] }. In a flight test with 14 m/s gusts the aircraft lands 5 m off the pad centre. What does SysML v2 say about the requirement on that flight?`,options:[{id:`a`,text:`It is violated, because the required constraint (5 m against a 3 m limit) is false on that flight`,correct:!1,explanation:`The required constraint only applies when the assumed constraints hold (OMG SysML v2.1 Beta 2, Part 1, p. 161).`},{id:`b`,text:`It is undefined, because SysML v2 cannot evaluate a requirement whose assumption is false on that flight`,correct:!1,explanation:`An implication with a false premise has a defined value: true.`},{id:`c`,text:`It is violated, because an assumption is a required constraint on the weather, and the 14 m/s gusts broke that constraint`,correct:!1,explanation:`An assumption is not required of anyone; it limits when the required constraints apply (OMG SysML v2.1 Beta 2, Part 1, p. 161).`},{id:`d`,text:`It is satisfied: the effective constraint is an implication, its assumption is false, so the flight is out of scope`,correct:!0,explanation:`Correct. The effective constraint of a requirement is the logical implication from its assumed to its required constraints (OMG SysML v2.1 Beta 2, Part 1, p. 165); with a false assumption the implication holds. Whether 5 m in strong gusts is acceptable is a question for another requirement or a decision.`}],cite:{reading:`R83`,pages:`165`}},{id:`q10-5`,bloom:`Apply`,objective:`B10.2`,prompt:`The reference defines port def WeatherDataPort { out item weather : 'INFO-004'; }. The operations centre must receive weather data from the weather service, whose port is typed WeatherDataPort. Which declaration in OperationsCenter makes the two ports compatible?`,options:[{id:`a`,text:`port weatherIn : WeatherDataPort;`,correct:!1,explanation:`Both ports would offer weather as an output; compatible ports need matching directed features with inverse directions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20).`},{id:`b`,text:`port weatherIn : ~WeatherDataPort;`,correct:!0,explanation:`Correct. The conjugate port definition reverses inputs and outputs, so weather is an input here and matches the service’s output (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 20–21).`},{id:`c`,text:`port weatherIn : 'INFO-004'; (the item it carries)`,correct:!1,explanation:`A port is typed by a port definition, not by the item it carries; the course checker rejects this typing.`},{id:`d`,text:`part weatherIn : WeatherDataPort;`,correct:!1,explanation:`A port is a connection point that exposes features in a limited way; it is not a part (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 20).`}],cite:{reading:`R71`,pages:`20–21`}},{id:`q10-6`,bloom:`Apply`,objective:`B10.2`,prompt:`For IF-013 the reference has interface def AircraftHealthDataLink { end aircraftSide : FlightDataPort; end maintenanceSide : ~FlightDataPort; }, EVTOLAircraft has port healthDataOut : FlightDataPort, and MaintenanceFacility has port flightDataIn : ~FlightDataPort. Which interface usage in aeroLink is right?`,options:[{id:`a`,text:`interface <'IF-013'> aircraftMaintenanceHealthDataLink : AircraftHealthDataLink connect 'PHY-005'.flightDataIn to 'PHY-001'.healthDataOut;`,correct:!1,explanation:`The ends are taken in order, so the aircraftSide end (FlightDataPort) would be the facility’s ~FlightDataPort and vice versa. The course checker did not compare connected ports with end types in its probes, so this kind of slip has to be caught in review.`},{id:`b`,text:`flow <'IF-013'> of 'INFO-002' from 'PHY-001' to 'PHY-005';`,correct:!1,explanation:`A flow transfers a payload from an output to an input (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 27); it does not replace the interface, and it runs between port features, not whole parts.`},{id:`c`,text:`interface <'IF-013'> aircraftMaintenanceHealthDataLink : AircraftHealthDataLink connect 'PHY-001'.healthDataOut to 'PHY-005'.flightDataIn;`,correct:!0,explanation:`Correct. An interface usage defined by an interface definition connects two compatible ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22); in the shorthand the ends are taken in order, so aircraftSide is the aircraft’s FlightDataPort and maintenanceSide the facility’s conjugate.`},{id:`d`,text:`interface <IF-013> aircraftMaintenanceHealthDataLink : AircraftHealthDataLink connect aeroLink.PHY-001.healthDataOut to aeroLink.PHY-005.flightDataIn;`,correct:!1,explanation:`IDs with hyphens must be quoted in declarations and in references (OMG SysML v2.1 Beta 2, Part 1, p. 49–50).`}],cite:{reading:`R71`,pages:`22`}},{id:`q10-7`,bloom:`Analyse`,objective:`B10.2`,prompt:`PHY-005 binds attribute :>> faultReportToFlagTime = 90 [s]; (FICTIONAL). For a what-if, a teammate adds part upgradedFacility :> aeroLink.'PHY-005' { attribute :>> faultReportToFlagTime = 60 [s]; } “so the upgrade starts from PHY-005 and improves on its value”. What does the model now say?`,options:[{id:`a`,text:`That the upgrade’s flag time is 60 s while PHY-005 keeps 90 s, as the later binding replaces the inherited one`,correct:!1,explanation:`A redefinition does not replace values: on each instance the redefining feature has the same values as the one it redefines (Week 9). upgradedFacility is among PHY-005’s values, and there the flag time is bound to 90 s.`},{id:`b`,text:`That an upgradedFacility’s flag time equals both 90 s and 60 s, so no upgradedFacility can exist`,correct:!0,explanation:`Correct. The feature value notation is a binding, which asserts equal values in the same context, not an initial or default value (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 24–25). upgradedFacility subsets PHY-005, so the 90 s binding holds for it too, and its own binding says 60 s. Model the what-if as a sibling usage of MaintenanceFacility with its own binding, or re-baseline PHY-005. The checker refused to override a bound value in a satisfy body (pc5); this subsetting form was not probed.`},{id:`c`,text:`That 90 s was PHY-005’s starting value, which becomes 60 s once the upgraded facility enters service`,correct:!1,explanation:`Neither line is time-dependent: both are bindings (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 25). The language has separate forms for initial and default values, outside the course register.`},{id:`d`,text:`That every MaintenanceFacility in the model now has a flag time of 60 s instead of 90 s`,correct:!1,explanation:`Both bindings are in usages, not in the definition MaintenanceFacility, so neither applies to every facility (Week 9).`}],cite:{reading:`R71`,pages:`24–25`}},{id:`q10-8`,bloom:`Evaluate`,objective:`B10.3`,prompt:`Before CP4 a team proposes to delete all ten satisfy usages “until verification is finished, so the model never claims anything it cannot prove”. Which response is best?`,options:[{id:`a`,text:`Agree: a satisfy without test evidence is always false, so deleting all ten of them until Week 12 keeps the model honest`,correct:!1,explanation:`A satisfy is a claim; it is not false for lack of evidence, it is unverified. Verification supplies evidence later.`},{id:`b`,text:`Agree, and replace them with dependencies, which record the same link to each requirement more cautiously`,correct:!1,explanation:`A dependency is model-level and has no instance-level semantics (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 105); it does not claim that the requirement is met.`},{id:`c`,text:`Disagree: keep all ten as written, because the checker would reject the file if any of the claims were false`,correct:!1,explanation:`The checker evaluates no constraints; a false satisfy passes silently.`},{id:`d`,text:`Disagree: keep each satisfy you can defend, replace the rest by recorded gaps, and let verification test the claims`,correct:!0,explanation:`Correct. A satisfy asserts the requirement is satisfied by the bound feature (OMG SysML v2.1 Beta 2, Part 1, p. 168), and CP4 asks for one per REQ-SYS or a recorded gap; a design solution must satisfy its requirements to be valid (OMG SysML v2.1 Beta 2, Part 1, p. 161). The honest model asserts what it can defend and records the rest.`}],cite:{reading:`R83`,pages:`168`}},{id:`q10-9`,bloom:`Analyse`,objective:`B10.3`,prompt:`In a model, REQ-SYS-009 (alarm transmitted within 30 s) is allocated to FN-010, LOG-007 performs FN-010, and allocation 'LOG-007 allocated-to PHY-008' allocate logicalArchitecture.'LOG-007' to aeroLink.'PHY-008'; is present. There is no satisfy for REQ-SYS-009. A reviewer asks: “Does the model claim that PHY-008 transmits the alarm within 30 s?” Which answer is correct?`,options:[{id:`a`,text:`No: the allocations say who is responsible for the intent, not that the 30 s limit holds; that needs a satisfy or a gap`,correct:!0,explanation:`Correct. Allocation is a precursor to more rigorous specification (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106); only a satisfy asserts that the requirement is satisfied by the bound feature (OMG SysML v2.1 Beta 2, Part 1, p. 168). The claim would be satisfy 'REQ-SYS-009' by aeroLink.'PHY-008', with evidence from VER-009. Here the thread stops halfway, which is what RB-8.4 and RB-9.2 look for.`},{id:`b`,text:`Yes: the allocation chain REQ → FN → LOG → PHY carries the requirement down to PHY-008, which amounts to satisfying it`,correct:!1,explanation:`Allocation assigns responsibility for realising the source’s intent (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106); a chain of responsibilities is not a claim about performance.`},{id:`c`,text:`Yes: in SysML v2 an allocation is an instantiable connection, not a dependency, so it carries the requirement’s constraint`,correct:!1,explanation:`Being an instantiable connection across features (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 107) gives an allocation instance-level meaning as a connection; it does not make it an assertion of a constraint.`},{id:`d`,text:`No, because allocations in SysML v2 are dependencies without instance-level semantics, so they claim nothing`,correct:!1,explanation:`The conclusion is right but the reason is wrong: unlike SysML v1, a v2 allocation is not a dependency (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 107).`}],cite:{reading:`R76`,pages:`106–107`}},{id:`q10-10`,bloom:`Analyse`,objective:`B10.3`,prompt:`The reference has allocation 'LOG-003 allocated-to PHY-005' (maintenance management to the maintenance facility). A team adds a part diagnostics : DiagnosticWorkstation inside PHY-005 that performs FN-008 (FICTIONAL), and wants the model to say that LOG-003’s FN-008 is realised by that workstation in particular. Which addition says that?`,options:[{id:`a`,text:`allocation 'PHY-005 allocated-to LOG-003' allocate aeroLink.'PHY-005' to logicalArchitecture.'LOG-003' { allocate aeroLink.'PHY-005'.diagnostics.'FN-008' to logicalArchitecture.'LOG-003'.'FN-008'; }`,correct:!1,explanation:`Both allocations run from physical to logical, so they say the workstation’s intent is realised by maintenance management. The source of an allocation is the element whose intent is realised (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106). The checker accepted this form in a course probe; the direction is yours to check.`},{id:`b`,text:`Inside allocation 'LOG-003 allocated-to PHY-005': allocate logicalArchitecture.'LOG-003'.'FN-008' to aeroLink.'PHY-005'.diagnostics.'FN-008';`,correct:!0,explanation:`Correct. An allocation can be refined by nested allocations that give a finer-grained mapping (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106), here from the performed action on the logical side to the one on the workstation, in the course direction LOG → PHY. The checker accepted this form in a course probe.`},{id:`c`,text:`Move part diagnostics : DiagnosticWorkstation into LOG-003, so that the logical element owns the workstation that realises its function`,correct:!1,explanation:`That decomposes a logical element into a physical part. Allocation maps across structures and leaves both intact (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 106); ownership would delete the workstation with LOG-003.`},{id:`d`,text:`satisfy 'REQ-SYS-008' by aeroLink.'PHY-005'.diagnostics; because the workstation is what actually performs FN-008`,correct:!1,explanation:`A satisfy is a claim about the requirement, not an assignment of responsibility (OMG SysML v2.1 Beta 2, Part 1, p. 168), and REQ-SYS-008’s subject is MaintenanceManagement, which a DiagnosticWorkstation does not conform to.`}],cite:{reading:`R76`,pages:`106–107`}},{id:`q10-11`,bloom:`Evaluate`,objective:`B10.3`,prompt:`A team’s model v0.2 contains not satisfy 'REQ-SYS-008' by logicalArchitecture.'LOG-003'; with the doc comment “diagnostic software not yet specified; flag latency unknown”. REQ-SYS-008 requires the no-go flag within 2 min. Which review comment is right?`,options:[{id:`a`,text:`Keep it: not satisfy is the cautious form, and it claims nothing until verification has run`,correct:!1,explanation:`A negated satisfy asserts that the feature does not satisfy the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 168): a claim as strong as satisfy, not a placeholder.`},{id:`b`,text:`Replace it by a satisfy, since the software supplier will be bound by contract to meet 2 min`,correct:!1,explanation:`A satisfy asserts that the requirement holds (OMG SysML v2.1 Beta 2, Part 1, p. 168); a contract to be signed is not something the model can defend today.`},{id:`c`,text:`Replace it by a gap record: not satisfy says LOG-003 fails REQ-SYS-008, which nobody knows`,correct:!0,explanation:`Correct. A negated satisfy is a decided claim (OMG SysML v2.1 Beta 2, Part 1, p. 168) and fits a case settled on evidence. Here the question is open, so the course convention is a gap record: an @Issue “SATISFY GAP” naming the candidate, the missing evidence, the action and the owner, @StatusInfo open, and a gap-table row (worked example d).`},{id:`d`,text:`Delete it and record nothing: a requirement without a satisfy needs no record until CP5`,correct:!1,explanation:`CP4 asks for a satisfy for every REQ-SYS or a recorded gap (lab L10); silence hides the open question from the reviewers.`}],cite:{reading:`R83`,pages:`168`}},{id:`q10-12`,bloom:`Apply`,objective:`B10.2`,prompt:`At a hub, each turnaround charger serves at most one aircraft at a time, and an aircraft on the pad is connected to at most one charger. Which interface definition expresses this with cross multiplicities?`,options:[{id:`a`,text:`interface def ChargingSession { end [0..1] port chargerSide : ChargingPort; end [0..1] port aircraftSide : ~ChargingPort; }`,correct:!0,explanation:`Correct. Multiplicities on connection ends are cross multiplicities: they constrain how many connections a participant at the other end has to this end, e.g. at most one charger per aircraft and at most one aircraft per charger (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 18, sl.23).`},{id:`b`,text:`interface def ChargingSession { end [1] port chargerSide : ChargingPort; end [1] port aircraftSide : ~ChargingPort; }`,correct:!1,explanation:`Exactly one would require every aircraft always to be connected to a charger, and every charger always to an aircraft.`},{id:`c`,text:`interface def ChargingSession { end port chargerSide : ChargingPort; end port aircraftSide : ~ChargingPort; } with the default multiplicities`,correct:!1,explanation:`The default cross multiplicity of an interface is 0..* (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 22), which allows a charger to serve many aircraft at once.`},{id:`d`,text:`part <'PHY-001'> aircraft : EVTOLAircraft[0..1]; inside aeroLink, so that only one aircraft is present at the hub at a time`,correct:!1,explanation:`This changes how many aircraft the fleet has, not how many connections each has; connection ends always have multiplicity 1..1 relative to the connection definition (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 23).`}],cite:{reading:`R71`,pages:`18–23`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min: concept studio; lab L10)`,hours:2.5},{activity:`Core readings Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Requirement Definitions” (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 86–91), Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Connections” (sl.18–29), Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Use Case Definition” (sl.105–107): 21 slides at ≈ 30 sl/h`,hours:.7},{activity:`Lesson-cited OMG SysML v2.1 Beta 2, Part 1 extracts p.161, 165, 168 (OMG SysML v2.1 Beta 2, Part 1, “7.21 Requirements”, extension reading in the register; 3 pp of specification, read against the lesson)`,hours:.2},{activity:`Online lesson and the three activities (translator, classifier, predict the checker)`,hours:1},{activity:`Readiness quiz Q9 / knowledge check (12 items)`,hours:.3},{activity:`L10 out of class: requirements set, logical structure, satisfy and gap records, allocations, final checker run and tables (team share)`,hours:3.5},{activity:`Graduate assume/require memo: OMG SysML v2.1 Beta 2, Part 1, p. 162 (p.161 and 165 already read), adapting the still-air listing with a checker run, and a 1-page memo answering (a)–(d)`,hours:1},{activity:`Review notebook entry, time log and AI statement`,hours:.3}],references:[{reading:`R83`,pages:`161–169`},{reading:`R72`,pages:`41`},{reading:`R80`,pages:`49–50`}],review:{status:`independently-reviewed`,reviewer:`Independent AI reviewer (Claude): review and sign-off passes`,date:`2026-10-11`,report:``,openIssues:[]}},C=e({default:()=>w}),w={week:11,drivingQuestion:`SCN-002 is a page of numbered steps and alternates; the aircraft’s operating condition is a set of states and events. Can your team turn both into SysML v2 behaviour that the checker accepts and that a reviewer, comparing it with the ConOps, cannot fault — and can you review another team’s model with findings it can act on?`,blocks:[{id:`w11-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to B-CLO4 (represent requirements, structure and behaviour in a SysML v2 model that the course-designated checker accepts and that is semantically correct), B-CLO5 (keep the thread from scenario to function to element intact) and B-CLO6 (justify engineering judgements in a technical review). Your team submits CP4, the SysML model baseline of requirements, structure and allocation, at the end of the week. The behaviour you add in L11 is formative now and is graded at CP5. CP4 is then reviewed asynchronously: one peer team and the instructor each return review item discrepancies (RIDs) within days 1–3 of Week 12, and you write RIDs on another team’s model. This lesson teaches you to write the behaviour and to review a model, because the two skills check each other.`],bullets:[`B11.1 (Apply) Model a ConOps scenario as an action flow with successions, at least one decision and an item flow.`,`B11.2 (Apply) Model the aircraft operating states with an initial state in the current form, transitions with triggers and guards, and entry/do actions.`,`B11.3 (Evaluate) Check the behaviour against the ConOps and link it to structure with perform and exhibit, separating what the checker confirms from what a reviewer must confirm.`,`B11.4 (Evaluate) Write actionable review findings (RIDs): location, violated criterion or source, severity and a concrete fix.`,`Graduate expectation: build an interaction view of one scenario step that crosses an interface, and state what it asserts about ordering that the action flow does not.`],citations:[],provenance:`instructor-authored`},{id:`w11-intuition`,kind:`intuition`,title:`Intuition: a checklist, a status board, and a reviewer’s note`,paragraphs:[`A dispatcher works from two artefacts. The mission checklist says what happens and in which order: plan, file, board, take off, and what to do if the ANSP refuses the flight plan or a passenger does not show. The status board says what condition each aircraft is in right now — on a pad, charging, ready, flying, out of service — and which event moves it to the next condition. The checklist answers “what happens next in this mission?”; the board answers “what can happen to this aircraft now?”. Both describe behaviour, but they are not interchangeable: the checklist has no notion of “the aircraft is charging”, and the board has no notion of “after boarding comes take-off”. In SysML v2 the checklist becomes an action flow and the board a state definition.`,`Now give the checklist to a colleague who knows the operating manual. A useful reply is not “looks a bit thin”. It is: “Page 2, step 4: the no-show case continues to take-off, but the manual (section 3.2) says the party is re-booked; change step 4 to branch to re-booking.” That reply names where, against what, how bad and what to do. It is a review item discrepancy, and writing one well is this week’s fourth skill.`],citations:[],provenance:`instructor-authored`},{id:`w11-actions`,kind:`concept`,title:`Action flows: actions, successions, control nodes, item flows — and use cases`,paragraphs:[`An action definition defines an action to be performed, and its directed features (in, out) are its parameters; an action usage is the use of an action definition in a context, and a flow transfers items from one action’s output to another’s input (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slide 30). A succession asserts that the first action must complete before the second can begin (sl.31). A succession flow combines the two: the first action must finish producing its output before the second can begin consuming it (sl.32). The keyword then after an action is shorthand for a succession from the lexically previous action (sl.33), and an action usage can be decomposed directly into other actions (sl.34).`,`Choices are made with conditional successions and control nodes. A conditional succession asserts that the second action follows the first only if its guard is true, and if the guard is false the succession is not possible; the slides warn that its target must currently be named explicitly — the shorthand that declares the target in place is not available (sl.35–36). A decision node, decide, chooses exactly one successor and is typically followed by conditional successions, the last of which can be else; a merge node waits for exactly one predecessor; start and done refer to the start and end of the containing action (sl.37–38). Loop and if actions are a structured alternative to control nodes (sl.39). A fork enables all its successors and a join waits for all its predecessors (sl.40). The specification adds two details that matter in review: else is taken when the guards of the immediately preceding conditional successions are all false (OMG SysML v2.1 Beta 2, Part 1, p. 136), and when the successions out of a decision have no guards, one of them is chosen non-deterministically (OMG SysML v2.1 Beta 2, Part 1, p. 134; extension reading OMG SysML v2.1 Beta 2, Part 1, “7.17 Actions”).`,`Actions are performed by structure. perform identifies the owner of the perform as the performer of an action defined elsewhere (sl.41), and a perform inside another action acts like a call (OMG SysML v2.1 Beta 2, Part 1, p. 136). Send and accept actions model asynchronous transfers, optionally through ports: an accept action receives a transfer, a send action sends one to a target or via a port, and a transfer sent via a port goes to whatever the port is connected to (sl.45–46).`,`Use cases sit above the flow. A use case definition defines a required interaction between its subject and external actors; actors are parameters that represent roles played by external entities, they are referential part usages and so need part definitions, and the objective states the result of value (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Use Case Definition”, slide 100). The required behaviour of a use case can be specified as for an action; a use case can include another use case, and the subject of an included use case is bound implicitly to that of its container, while actors must be bound explicitly; the traditional extend relationship is not supported yet, and the subject must be declared before any actor (sl.101). This is why the AeroLink reference keeps SCN-002 as a use case and writes its flow inside it.`],citations:[{reading:`R72`,pages:`30–41`},{reading:`R72`,pages:`45–46`},{reading:`R76`,pages:`100–101`},{reading:`R82`,pages:`134–136`}],provenance:`source-paraphrase`},{id:`w11-worked-flow`,kind:`worked-example`,title:`Worked example (a): SCN-002 Passenger Transport Mission as an action flow`,paragraphs:[`aerolink_scn002_action_flow.sysml is the SCN-002 flow of the instructor reference model (v0.3), cut down to what it needs so the file stands alone; the course-designated checker accepts it with no messages. It adds one thing the reference does not have: an item flow of the flight intent from planFlight to fileFlightIntent (lines 32–34), which B11.1 asks for. Read the table against the listing; it is the mapping you will build for SCN-001 in the lab.`,`Four design decisions are worth copying. First, step 3 is performed by an external actor (EXT-001 accepts the flight intent), so it is not an AeroLink action: it is a decision, intentCheck, on a Boolean attribute the use case owns. Second, every alternate flow is a guarded branch out of a decision at the step where it starts, and it ends the way the ConOps says: A3 ends the scenario (holdAndRefile then done), A2 rejoins at step 5 through the merge departureReady, A1 rejoins at step 7 through the merge arrived. Third, A1 has two outcomes — hold or divert — so padCheck has three branches, the second guarded by (not destinationPadFree) and holdWithinReserve and the last by else, and the hold loops back through the merge approachAgain to a new approach. Fourth, the steps AeroLink itself performs (1, 2) and two others (4, 5) are written as action x :> Logical::'FN-nnn': each step subsets the function it is an occurrence of. That ties the flow to the functional architecture (functions are behaviour too); the link to structure comes next, when a logical part performs the function (worked example c).`,`What the listing leaves open is as instructive. Nothing in the model sets flightIntentAccepted, allPassengersPresent or the pad attributes: the guards are named conditions, not computed ones, and the checker evaluates no guard. Steps 6 and 7 subset no function, and step 5 is split across takeOff and cruise. Those are modelling choices to state in your notes, not errors; whether they are acceptable depends on the purpose of the model. Practise the method on the activity below: load the worked flow for SCN-002 and confirm every check passes, then choose SCN-005 and draft the weather-disruption branch yourself.`],table:{caption:`SCN-002 ConOps items mapped to the flow (reference v0.3; FICTIONAL values)`,header:[`ConOps item`,`Flow node(s)`,`Construct`],rows:[[`Step 1 Plan the flight (AeroLink)`,`planFlight :> FN-003`,`action subsetting a function; out intent`],[`Step 2 File the flight intent (AeroLink)`,`fileFlightIntent :> FN-012`,`action; in intent; item flow from planFlight`],[`Step 3 ANSP accepts (EXT-001)`,`intentCheck`,`decide on flightIntentAccepted`],[`A3 (step 3) not accepted: hold, re-file, else cancel; ends`,`holdAndRefile`,`else branch, then done`],[`Step 4 Board step-free (STK-005)`,`boardPassengers :> FN-014; partyCheck`,`action; decide on allPassengersPresent`],[`A2 (step 4) no-show: depart with the rest; rejoin 5`,`departWithRemainingParty`,`else branch to the merge departureReady`],[`Step 5 Take off and cruise (STK-008)`,`takeOff; cruise :> FN-005`,`two actions in succession`],[`Step 6 Approach and land (STK-008)`,`approach; padCheck; landAtDestination`,`decide with three branches`],[`A1 (step 6) pad occupied: hold or divert; rejoin 7`,`holdForPad; divertToAlternate`,`loop through the merge approachAgain; branch to the merge arrived`],[`Step 7 Deplane; aircraft to charging (SCN-003)`,`deplanePassengers; handOverToCharging`,`actions, then done`]]},sysml:[{file:`week11/aerolink_scn002_action_flow.sysml`,caption:`SCN-002 as an action flow: successions, three decisions, three merges, an item flow, and steps that subset functions (adapted from the reference model v0.3; FICTIONAL values)`,intent:`conformant`},{file:`week11/invalid_decide_target_declared.sysml`,caption:`Teaching listing: a decision branch written the way many first drafts write it. Find the line the checker rejects before reading the block on the checker below.`,intent:`intentionally-invalid`}],citations:[{reading:`R72`,pages:`30–38`},{reading:`R76`,pages:`101`}],provenance:`mixed`},{id:`w11-states`,kind:`concept`,title:`States: state definitions, the current initial-state form, transitions, guards and effects`,paragraphs:[`A state definition is like a state machine in UML and SysML v1: it defines a behavioural state that a system can exhibit, it can specify a set of discrete nested states, and the states are connected by transitions that fire on acceptance of item transfers, like accept actions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “State Definitions”, slide 48). The initial state is written first start then off; — the slides record that this form replaced the earlier entry form in 2026-03 (sl.48–50). The 2.1 Beta 2 specification text still shows the earlier form, entry; then off; (OMG SysML v2.1 Beta 2, Part 1, p. 150–151), and the course’s probe found that the 2026-08 checker accepts both. The course uses the current form, as the weekly plan requires; if you meet the older form in a source, read it as the same statement.`,`A transition is written transition name first source accept Trigger if guard do effect then target; and has a shorthand that omits the name and takes the lexically previous state as its source (sl.48–49). The guard is a condition that must be true for the transition to fire; the effect action is performed when the transition fires, before entry to the target (sl.53). Besides accepting a transfer, a transition can fire on a change trigger (accept when a Boolean expression becomes true), an absolute time trigger (accept at an instant) or a relative time trigger (accept after a duration) (sl.54). A state can have entry, do and exit actions, either referencing an action defined elsewhere or defining one in place, and states, like actions, can have parameters (sl.52). When a transition fires, the source’s do action is interrupted, then its exit action, the effect and the target’s entry action are performed in that order, and then the target’s do action starts (OMG SysML v2.1 Beta 2, Part 1, p. 153–154). OMG SysML v2.1 Beta 2, Part 1 is an extension reading, so this paragraph is the course’s statement of that order: the quiz relies on it, not on reading OMG SysML v2.1 Beta 2, Part 1, “7.17 Actions”.`,`Two structural rules matter for AeroLink. A parallel state has concurrent nested states, and transitions between those concurrent states are not allowed (sl.51). In a non-parallel state with substates, exactly one substate is active at any time after entry (OMG SysML v2.1 Beta 2, Part 1, p. 146). A state definition is a kind of action definition (OMG SysML v2.1 Beta 2, Part 1, p. 145), which is why a state can do actions and a part can exhibit it the way it performs an action. exhibit identifies the part that exhibits states defined elsewhere, and parameters of the exhibited state are bound as for an action (sl.56).`],citations:[{reading:`R73`,pages:`48–56`},{reading:`R82`,pages:`145–146`},{reading:`R82`,pages:`150–151`},{reading:`R82`,pages:`153–154`}],provenance:`mixed`},{id:`w11-worked-states`,kind:`worked-example`,title:`Worked example (b): the aircraft operating states`,paragraphs:[`aerolink_operating_states.sysml holds AircraftOperatingStates from the reference model: five states, eight transitions and one guard, which exceeds the L11 minimum of four states and five transitions. The checker accepts it with no messages. Each transition is written in the full form with a name, because the names become the vocabulary of the review: “transition dispatch” is easier to point at than “the third arrow”. The triggers are attribute definitions (ChargerConnected, DispatchRelease, …) — the reference’s choice; OMG SysML v2.1 Beta 2, Part 1 uses an item definition (TurnOn) in the same role (OMG SysML v2.1 Beta 2, Part 1, p. 151–152).`,`Read the guard on dispatch: accept DispatchRelease if not noGoFaultOpen then inFlight. It is the model’s expression of REQ-STK-006 (no dispatch with an open no-go fault): a release is accepted from dispatchReady only while no no-go fault is open. charging does FN-006 and inFlight does FN-005 for as long as the aircraft is in them; outOfService performs FN-008 on entry (sl.52). Use the walker activity: fire events, toggle noGoFaultOpen, and run the four ConOps traces. Three behave as the ConOps implies; one does not. Decide whether that is a defect before you read the advanced block.`],table:{caption:`Transitions of AircraftOperatingStates (reference v0.3)`,header:[`Transition`,`From`,`Trigger [guard]`,`To`,`ConOps source`],rows:[[`connectCharger`,`onPad`,`ChargerConnected`,`charging`,`SCN-003 step 1`],[`chargeComplete`,`charging`,`DispatchThresholdReached`,`dispatchReady`,`SCN-003 steps 3–6`],[`dispatch`,`dispatchReady`,`DispatchRelease [not noGoFaultOpen]`,`inFlight`,`SCN-002 step 5; REQ-STK-006`],[`land`,`inFlight`,`LandedOnPad`,`onPad`,`SCN-002 step 6`],[`overTemperature`,`charging`,`CellOverTemperature`,`outOfService`,`SCN-003 A3`],[`faultBeforeDispatch`,`dispatchReady`,`NoGoFaultReported`,`outOfService`,`SCN-004 step 2`],[`faultOnPad`,`onPad`,`NoGoFaultReported`,`outOfService`,`SCN-004 step 2`],[`returnToService`,`outOfService`,`ReturnedToService`,`onPad`,`SCN-004 step 6`]]},sysml:[{file:`week11/aerolink_operating_states.sysml`,caption:`AircraftOperatingStates with entry/do functions, exhibited by PHY-001, and the functions performed by LOG parts (adapted from the reference model v0.3)`,intent:`conformant`}],citations:[{reading:`R73`,pages:`48`},{reading:`R73`,pages:`52–53`},{reading:`R82`,pages:`151–152`}],provenance:`mixed`},{id:`w11-links`,kind:`worked-example`,title:`Worked example (c): linking behaviour to structure, and what each link asserts`,paragraphs:[`RB-8.5 asks for actions and states that are consistent with the scenarios and linked to structure through perform and exhibit. The two listings use four links, each with a different meaning. A step that subsets a function (action cruise :> Logical::'FN-005') says that this step is an occurrence of that function. perform Logical::'FN-005'; inside LOG-001 says that flight operations is the performer of the function (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slide 41). do Logical::'FN-005'; inside inFlight says that the function is performed while the aircraft is in that state (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “State Definitions”, slide 52). exhibit Behavior::aircraftOperatingStates; inside PHY-001 says that each aircraft exhibits these states (sl.56); exhibited states are referential, not composite features of the part (sl.56).`,`Follow one function through all four links. FN-005 Fly passenger trip is a step of SCN-002 (cruise), is performed by LOG-001, is the do action of inFlight, and inFlight belongs to the states that PHY-001 exhibits. In the reference model LOG-001 is allocated to PHY-001 and PHY-004 (Week 10). The chain is consistent: the aircraft that is in flight is an element to which the performer of flying is allocated. Now try FN-006 Charge aircraft: it is the do action of charging, exhibited by the aircraft, but it is performed by LOG-002 and allocated to PHY-003 (charging systems). Is that a contradiction? No — read the do action as “while the aircraft is charging, the charging function is being performed”, and the perform and allocation as “by whom”. But that reading is a judgement the reviewer makes; no link says it. This is the pattern of B11.3: the checker confirms that every link resolves to an element of the right kind; a reviewer confirms that the links say something true about AeroLink.`],citations:[{reading:`R72`,pages:`41`},{reading:`R73`,pages:`52`},{reading:`R73`,pages:`56`}],provenance:`mixed`},{id:`w11-checker`,kind:`concept`,title:`What the checker confirms, and what a reviewer must confirm`,paragraphs:[`The course-designated checker (OMG SysML v2 Pilot Implementation, release 2026-08) parses the file, resolves every name and runs the pilot’s validation rules; it does not evaluate guards or constraints and does not judge whether behaviour matches the ConOps. The course probed behaviour constructs on 2026-10-11 to find where that boundary lies; the table gives the results that this lesson relies on. Several real behaviour defects pass without any message.`,`The teaching listing invalid_decide_target_declared.sysml fails at line 10: if flightIntentAccepted then action boardPassengers; declares the target in the branch. The checker reports “no viable alternative at input ‘if’” and then a cascade of messages caused by the first. The slides say why: the target of a conditional succession must currently be named, not declared in place (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slide 35). Declare action boardPassengers; on its own line and name it in the branch, as worked example (a) does.`,`The right-hand cases are your review checklist for behaviour. The flow-coverage activity checks some of them on a graph you type in: every node reachable from start and with a path to done; decisions with guarded branches (and, as advice, an else); a node for every ConOps step and alternate; the main steps in ConOps order on the main path, with the alternate-flow nodes left out; each alternate entered from the step the ConOps names; and each alternate either reaching done without a later main step, or first meeting the main flow at the rejoin step (a loop back to its own branching step counts as a retry). The walker checks reachability, exits and competing transitions in a state table. Neither reads SysML. Neither can tell whether a guard is the right condition, whether an alternate’s own steps are all there, or whether a node does what its name says. Everything else is reading.`],table:{caption:`Course probes of behaviour constructs, release 2026-08, 2026-10-11 (scratch files; see the notes)`,header:[`Construct in a file`,`Recorded result`,`Who must catch it`],rows:[[`accept of a signal that is not declared`,`FAIL: “Couldn’t resolve reference to Type …”`,`Checker`],[`then to an action that does not exist`,`FAIL: “Couldn’t resolve reference to Feature …”`,`Checker`],[`exhibit naming an action, not a state`,`FAIL: “Must reference a state.”`,`Checker`],[`two entry actions in one state`,`FAIL: “A state may have at most one entry action.”`,`Checker`],[`decision branch that declares its target`,`FAIL: syntax (“no viable alternative at input ‘if’”)`,`Checker`],[`a state that no transition enters`,`PASS, no message`,`Reviewer`],[`a state definition with no initial state`,`PASS, no message`,`Reviewer`],[`decide with no else and guards that do not cover every case`,`PASS, no message`,`Reviewer`],[`decide whose guards can both be true`,`PASS, no message`,`Reviewer`],[`an action with no successor inside a flow (a dead end)`,`PASS, no message`,`Reviewer`],[`a merge with one incoming succession`,`PASS, no message`,`Reviewer`]]},citations:[{reading:`R72`,pages:`35`}],provenance:`mixed`},{id:`w11-advanced`,kind:`advanced`,title:`Advanced analysis: cross-checking the flow and the states, and the semantics of choice`,paragraphs:[`An action flow and a state machine describe the same system from two sides, so each can check the other (instructor method). For every flow step that changes the condition of the aircraft there should be an event the state machine accepts in the state the aircraft is in at that step; for every transition there should be a step, in some scenario, that causes its trigger. Apply it to SCN-002 and the operating states: landAtDestination corresponds to LandedOnPad (inFlight → onPad), and handOverToCharging leads to ChargerConnected in SCN-003. Now SCN-004. Its trigger is “aircraft health monitoring reports a fault”, with the precondition that the aircraft is in service — the ConOps does not limit the fault to the pad. The state machine accepts NoGoFaultReported only in onPad and dispatchReady. Fire it while the aircraft is charging and no transition accepts it (walker trace T4); if charging then completes, the aircraft reaches dispatchReady, whose doc says “no open no-go fault”, with a fault open. The guard on dispatch still blocks the release, so REQ-STK-006 holds, but the model now contradicts its own documentation, and it does not say who sets noGoFaultOpen. That is a reviewer’s finding on the reference model, recorded for the lead. A fix is a design choice: add faultWhileCharging from charging to outOfService and decide what an in-flight fault means (land, then out of service), or move fault handling into a parallel health region (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “State Definitions”, slide 51). The second choice raises its own question, because no transition may cross between concurrent regions (sl.51): the regions then have to be coordinated some other way. Remember, when you weigh the options, that a checker PASS shows only that a form parses and resolves; it is not evidence of what the form means.`,`The semantics of choice deserve the same care. The slides state two facts: a decision chooses exactly one successor (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slide 38), and a conditional succession whose guard is false is not possible (sl.35); OMG SysML v2.1 Beta 2, Part 1 adds that unguarded successions out of a decision are chosen non-deterministically (p.134). Two consequences follow, and they are instructor reasoning from those statements, not sentences of either source: if two guards can be true at once, the model says only that one of the possible successions is taken, not which; if every guard can be false and there is no else, no succession out of the decision is possible. The reference padCheck is written so that its first two guards exclude each other and else covers the rest; that is a property the modeller establishes, because the checker evaluates no guard. Transitions raise the same issue (again instructor reasoning): a guard must be true for a transition to fire (sl.53), but nothing in the slides says which of two enabled transitions on the same trigger fires, so a reviewer asks for guards that exclude each other. That is what the walker’s determinism advisory looks for.`,`Finally, ordering across participants. An action flow orders the steps of one behaviour. When the operations centre files a flight intent and the ANSP answers, two performers act, and the only ordering between them comes from the transfer: the ANSP cannot accept an intent that has not been sent (Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slides 45–46; OMG SysML v2.1 Beta 2, Part 1, p. 137–140). The graduate task makes that explicit as an interaction view, and asks you to say what it asserts that the flow did not.`],citations:[{reading:`R72`,pages:`35`},{reading:`R72`,pages:`38`},{reading:`R72`,pages:`45–46`},{reading:`R73`,pages:`51`},{reading:`R73`,pages:`53`},{reading:`R82`,pages:`134`},{reading:`R82`,pages:`137–140`}],provenance:`mixed`},{id:`w11-rids`,kind:`concept`,title:`Reviewing a model: review item discrepancies (RIDs) that an owner can act on`,paragraphs:[`SEBoK describes technical reviews and audits as a mechanism by which sufficiently independent and knowledgeable stakeholders analyse the current state of a system or work product against pre-established criteria, to support technical and programmatic decisions; entry and exit criteria should be defined before the review, and the information assessed may be documents, models, simulations or prototypes; participants analyse it from their own perspectives and identify actions, and once the exit criteria are met the actions are implemented (SEBoK v2.14, “Technical Reviews and Audits”, p. 386–388). CP4 is the course’s PDR-style review. In the DoD guidebook the PDR establishes the allocated baseline — functional and interface requirements decomposed and allocated, internal interfaces documented (OUSD(R&E) Systems Engineering Guidebook, “3.4 Preliminary Design Review”, p. 76–77). That is close to the CP4 scope of requirements, structure and allocation; the allocated baseline also documents the verification required, which the course adds in Week 12.`,`A RID is the unit of such a review. The course form (a course convention, scored by RB-17) has seven fields. The ID (RID-<your team>-<nn>) lets the owner disposition each finding in CP5, where “every CP4 RID has a disposition” is an entry criterion of the final review. The location names an element by ID or qualified name, with a line if useful. The criterion or source names what the model violates: an RB-8 criterion, a page or slide, a ConOps item, a requirement or a lab rule (RB-17.1). The category says what kind of finding it is; RB-17.2 asks for at least two on semantics or traceability. The severity uses the course scale: major (wrong, inconsistent with its sources, below a checkpoint minimum, or breaking a thread — fixed by the CP5 submission), minor (valid and consistent but incomplete or weak where a later checkpoint depends on it) or editorial (names, layout, documentation). The discrepancy says what is there and what is wrong. The fix proposes a concrete change (RB-17.3).`,`Severity and fix are where most RIDs fail. Rate the consequence, not your annoyance: an inconsistent name is editorial unless it breaks a reference; a decision that can stall the flow is major. A fix is concrete when the owner could make it without asking you a question: it names the construct (transition, decide, else, exhibit, perform) and the elements. “Consider improving the behaviour model” is neither a discrepancy nor a fix.`],citations:[{reading:`R06c`,pages:`386–388`},{reading:`R41`,pages:`76–77`}],provenance:`mixed`},{id:`w11-worked-rids`,kind:`worked-example`,title:`Worked example (d): writing RIDs on a seeded model fragment`,paragraphs:[`aerolink_review_fragment_team_k.sysml is a FICTIONAL team’s whole L11 behaviour draft so far: SCN-005 Weather Disruption as a flow and a vertiport weather-hold state machine. The checker accepts it with no messages. It contains at least nine defects. Some are of kinds the checker table lists (an unreachable state, a dead end, a decision without else); others show only when you compare the model with the ConOps and the L11 minimums (steps in the wrong order, an alternate that rejoins instead of ending, a missing alternate, a missing perform or exhibit, a hold lifted too early). One of them is worked here, three ways.`,`Weak: “The weather state machine needs more work.” It has no location, no criterion, no severity, and nothing the owner can do. Better but not actionable: “VertiportWeatherStates: closedForDay is wrong (RB-8.5). Fix it.” The owner still has to rediscover what is wrong. Actionable: RID-IN-05. Location: Behavior::VertiportWeatherStates, lines 54–57 (state hold, state closedForDay). Criterion: OMG SysML v2.1 Beta 2, Part 1, p. 146 (transitions activate states); SCN-005 A3. Category: semantics. Severity: major. Discrepancy: no transition enters closedForDay and it is not the initial state, so it can never be active and the A3 case (hold longer than 2 h) is not modelled; and the one transition out of closedForDay (line 57, accept ForecastClear then open) contradicts its doc, which says bookings are cancelled for the rest of the day. Fix: add private import SI::*; (the file imports only ScalarValues, and without SI the unit h does not resolve); add accept after 2 [h] then closedForDay; directly after line 55, so that its source is hold (a relative time trigger, Seidewitz, Intro to the SysML v2 Language: Textual Notation, “State Definitions”, slide 54); replace line 57 with accept OperatingDayStart then open; and declare attribute def OperatingDayStart;. The course probed this fix: with the import the file passes; without it the checker reports “Couldn’t resolve reference to Element ‘h’”. That is the test of an actionable fix: the owner can apply it as written.`,`Now write your own RIDs in the RID writer below: three in the Session 2 practice round, at least two on semantics or traceability. Find them by reading the listing against the ConOps; the coverage tool’s and the walker’s results on Team K’s draft, and the instructor’s RIDs, open once you have saved three distinct RIDs that pass the screens. Then compare: the tools report symptoms of six of the nine instructor RIDs, and the other three are found only by reading.`],sysml:[{file:`week11/aerolink_review_fragment_team_k.sysml`,caption:`Team K’s draft (FICTIONAL, seeded with defects for the RID exercise): accepted by the checker, not correct`,intent:`conformant`}],citations:[{reading:`R82`,pages:`146`},{reading:`R73`,pages:`54`},{reading:`R82`,pages:`140`}],provenance:`mixed`},{id:`w11-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`SEBoK notes that reviews can be schedule-based, event-based or evidence-based, each with its own risk — insufficient information, insufficient analysis, or late feedback on latent defects — and that a review team works best when it combines people close enough to the project to see what matters with people far enough away to be independent (SEBoK v2.14, “Technical Reviews and Audits”, p. 387–388). An asynchronous written review of a model by a peer team is an event-based review with an independent reviewer, which is why the course pairs it with an instructor review.`,`For an operator such as AeroLink (instructor application), behaviour models earn their keep where documents struggle: an operations manual describes the weather-hold procedure, but only a model can be checked mechanically for an unreachable state or a branch that never ends, and only a model makes the link from “hold longer than 2 h” to the function and the element responsible for cancelling bookings explicit enough for a reviewer to test it. The same discipline carries into later life-cycle reviews: findings that name a location, a criterion and a fix can be dispositioned, tracked and closed; findings that do not are re-discovered at the next review.`],citations:[{reading:`R06c`,pages:`387–388`}],provenance:`mixed`},{id:`w11-lab`,kind:`lab`,title:`Lab L11 — behaviour (formative) and the RID review kick-off`,paragraphs:[`In Session 2 your team adds behaviour to the model that becomes v0.3: SCN-001 Passenger Ride Request as an action flow with at least one decision, its alternates A1–A3 handled as the ConOps says; an operating-state definition for the aircraft with at least four states and five transitions; and perform and exhibit links to your logical and physical parts. Class time goes into the decisions, not the typing: start from the starter listing below (the six SCN-001 steps in succession, no decisions) and the matching skeleton in the coverage tool. What must be finished in class: the SCN-001 decisions and alternates mapped in the coverage tool with no error left, and the list of states and named transitions walked against the traces. The SysML for both, the links and the checker runs are finished out of class (the 2 h of L11 in the workload). The last 30 minutes kick off the asynchronous CP4 review: the RID form, a practice round on Team K’s fragment, and your review assignment.`],sysml:[{file:`week11/aerolink_l11_starter_scn001.sysml`,caption:`L11 starter: the six SCN-001 main steps in succession inside the use case — no decisions, alternates, item flow or FN subsetting yet (those are the lab task; FICTIONAL)`,intent:`conformant`}],citations:[],provenance:`instructor-authored`},{id:`w11-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: CP4 SysML Model Baseline (10 % of the course grade: RB-8 75 · RB-17 15 · RB-12 10) at the end of Week 11 — the model accepted by the checker with requirements, structure and allocation, the checker log, the completeness table and the AI usage statement. The L11 behaviour draft is included for formative feedback only: RB-8.5 (behaviour) is not scored at CP4 and is graded at CP5. RIDs on your assigned team’s CP4 model are written in Week 12, days 1–3 (budgeted in the Week 12 workload), and are scored under RB-17 as part of your CP4 grade. Individual: readiness quiz Q10, the review-notebook entry with a time log, and, for graduate students, the interaction view (always read; formative feedback on RB-8.5; informs RB-16.1).`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w11-act-flow`,title:`ConOps-to-action-flow coverage checker`,component:`w11-flow-coverage`,purpose:`Map every step and alternate flow of a ConOps scenario to the nodes and successions of an action flow, and check coverage, main-path order, reachability, termination, decisions, and where each alternate branches and ends or rejoins, against cited criteria. A teaching aid over a typed graph; it does not read SysML and cannot judge guards.`,instructions:[`Choose SCN-002 and load the worked flow; confirm every check passes and read why each does.`,`Choose SCN-005 and draft the weather-disruption branch (steps 1–3, A1, A2) yourself under “My draft” (Session 1 practice). Team K’s draft is kept in a separate copy, so viewing it never changes yours; its check results open after the RID practice round.`,`For the lab, choose SCN-001 and load the L11 skeleton (the six steps in succession); add the decisions, alternates and merges until no error remains, and copy the mapping table into your L11 notes. Write the SysML yourself and check it with the checker: passing these checks does not make a file valid.`],objectives:[`B11.1`,`B11.3`],inBlock:`w11-worked-flow`},{id:`w11-act-walker`,title:`State-machine walker`,component:`w11-state-walker`,purpose:`Fire events at the reference operating states, set guard values, run four ConOps traces, analyse reachability, exits and competing transitions, and edit a copy to repair what you find.`,instructions:[`Fire ChargerConnected, DispatchThresholdReached and DispatchRelease with noGoFaultOpen off and on; explain the difference.`,`Run the traces. One stops before the state the ConOps implies: decide whether it is a defect and, if so, repair it in your copy.`,`Fire events at Team K’s weather states and decide what you would report; the walker’s analysis of that machine opens after your three practice RIDs, so you can check what you missed.`],objectives:[`B11.2`,`B11.3`],inBlock:`w11-worked-states`},{id:`w11-act-rids`,title:`RID writer`,component:`w11-rid-writer`,purpose:`Write review item discrepancies with location, criterion or source, category, severity, discrepancy and fix; get screen messages for each field and for the set (RB-17), with your initials and provenance recorded on each RID. Practice RIDs and Week 12 review RIDs are kept in separate lists with separate exports.`,instructions:[`Enter your initials and provenance (tag a RID AI-suggested-reviewed if a tool proposed it and you checked it).`,`Practice (Session 2): write three RIDs on Team K’s fragment, at least two on semantics or traceability, by reading the listing. Clear every screen message; the screens check form, not truth.`,`Once you have three distinct RIDs, compare them with the tools’ results on Team K’s draft and with the instructor’s RIDs. In Week 12, switch to the review list for your assigned team’s CP4 model (at least five RIDs) and submit that list’s table.`],objectives:[`B11.4`],inBlock:`w11-worked-rids`}],lab:{id:`L11`,title:`Behaviour in the model (formative) and the CP4 RID review kick-off`,setting:`team`,durationMinutes:75,objectives:[`B11.1`,`B11.2`,`B11.3`,`B11.4`],inputs:[`Team model v0.2 accepted by the checker (L10), with FN, LOG and PHY elements, allocations and the SCN use cases`,`SCN-001 Passenger Ride Request (ConOps, Week 3) and the team’s scenarios`,`The L11 starter listing aerolink_l11_starter_scn001.sysml and the matching skeleton in the coverage tool`,`Listings aerolink_scn002_action_flow.sysml and aerolink_operating_states.sysml (this week)`,`Instructor reference sysml/reference/aerolink_v03_behavior.sysml (recovery input)`,`The three Week 11 activities; Team K’s fragment for the RID practice round`],steps:[{title:`Brief (5 min)`,detail:`Today’s behaviour is formative feedback only and graded at CP5 (RB-8.5). Scope: SCN-001 flow, operating states, perform/exhibit. The current initial-state form is first start then <state>. What must be finished in class: the SCN-001 decisions mapped in the coverage tool, and the state list walked; the SysML is finished out of class.`},{title:`SCN-001 decisions and alternates (15 min)`,detail:`Load the L11 skeleton in the coverage tool (the six steps in succession, already mapped). Add the decisions with guarded branches and else, the alternate actions and the merges — A1 rejoins at step 3, A2 ends the scenario, A3 rejoins at step 5 — until no error remains (about six nodes and ten successions). Out of class: write it in SysML in your SCN-001 use case from the starter listing, with AeroLink’s steps subsetting their FN and one item flow.`},{title:`Operating states (15 min)`,detail:`In the walker’s editable copy, list the aircraft states and named transitions (≥ 4 states, ≥ 5 transitions, each with a trigger, at least one guard) and run the T1–T4 traces. Out of class: write the state definition in SysML with do or entry actions that reference FN usages.`},{title:`Links and check (10 min)`,detail:`Write the perform lines in the LOG parts (if not done in L10) and the exhibit line in the aircraft PHY part; run whatever compiles through the checker and note the first error. Out of class: fix to zero errors and save the log.`},{title:`RID review kick-off (30 min)`,detail:`Instructor: RB-17 and the course RID form (10 min). Pairs: three RIDs each on Team K’s fragment in the RID writer’s practice list, found by reading, then compared aloud with a neighbour and with the tools’ results, which open after three (15 min). Logistics (5 min): review assignments, the Week 12 deadline (end of day 3), the submission format (the Week 12 list’s Markdown table), the late-RID fallback and the missing-CP4 rule.`}],artefacts:[{idPrefix:`Model v0.3 (behaviour draft)`,description:`SCN-001 action flow inside its use case; aircraft operating-state definition and usage; perform and exhibit links`,minimum:`≥ 1 decision; ≥ 4 states and ≥ 5 transitions; every state usage exhibited by a part; zero checker errors`},{idPrefix:`CP4 package`,description:`Model file (requirements, structure, allocation), checker log, completeness table, AI usage statement`,minimum:`Accepted by the checker with zero errors; CP4 minimum scope (syllabus §11)`},{idPrefix:`RID-<team>-nn`,description:`RIDs on the assigned team’s CP4 model (written in Week 12, days 1–3)`,minimum:`≥ 5 RIDs, each with location, criterion or source, severity and fix; ≥ 2 on semantics or traceability`}],continuity:`The behaviour drafted today is finalised for CP5 (RB-8.5), where the workload-pilot trigger can reduce it to the action flow only. The RIDs you receive on CP4 are dispositioned in L12 (Week 12, objective B12.5), and “every CP4 RID has a disposition” is an entry criterion of the CP5 review. The perform and exhibit links become hops of the three complete threads audited in Week 12, and the Week 13 impact analysis traverses them: a scenario step that subsets no function is a thread that cannot be followed.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`CP4`,title:`CP4 SysML Model Baseline; L11 behaviour draft; RIDs on a peer model; graduate interaction view`,mode:`team`,due:`CP4 package and L11 behaviour draft: end of Week 11. RIDs on the assigned team’s CP4 model: end of day 3 of Week 12. Graduate interaction view: end of Week 11.`,weight:`CP4: 10 % of the course grade (RB-8 75 · RB-17 15 · RB-12 10). RB-8.5 (behaviour) gives formative feedback only at CP4 and is graded at CP5, so at CP4 RB-8 is scored on 8.1–8.4 and 8.6, with 8.6 measured against the syllabus §11 CP4 scope. Keep the behaviour draft in a separate file: its checker errors and warnings then do not count toward RB-8.1. Graduate interaction view: review notebook (RB-16, 5 %), always read.`,instructions:[`Finalise the CP4 model: all CP2 requirements as SysML requirements with subject and short-name ID; logical and physical structure with ports and interfaces; satisfy for every REQ-SYS (or a recorded gap); allocate FN → PHY. Run the whole file through the checker until it reports zero errors and explain every warning.`,`Submit the L11 behaviour (SCN-001 flow, operating states, perform/exhibit) as a separate file that imports the CP4 model, with the coverage-tool mapping table, for formative feedback only. It is not scored at CP4 (RB-8.5 is graded at CP5), and its checker messages do not count toward RB-8.1.`,`Submit the CP4 package by the end of Week 11.`,`Review your assigned team’s CP4 model (released at the start of Week 12) and submit at least five RIDs, from the RID writer’s Week 12 list (not the practice list), by the end of day 3 of Week 12. The instructor also reviews every model. Late-RID fallback: if your peer reviewers’ RIDs are late, your team works from the instructor’s RIDs alone, and RIDs submitted late score 0 on RB-17.3. If your assigned team’s CP4 is missing at the start of Week 12, review team k+2 instead.`,`Graduate students (individually): build the interaction view in template section 8; run it through the checker and report what it said.`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Model file and checker log (RB-8.1)`,guidance:`The .sysml file and the checker output for the whole file. Zero errors; every warning listed with its line, the message and either the fix or why it is acceptable. The behaviour file’s log goes in section 7, not here.`},{heading:`2. Package structure and conventions (RB-8.2)`,guidance:`The L9 mapping table updated for v0.2/v0.3: every CP1–CP3 ID once, with package, construct and owner; changes since L9 and why; import visibility.`},{heading:`3. Requirements (RB-8.4)`,guidance:`Count of CP2 requirements modelled (all of them), each with subject, short-name ID, doc text and constraint; derivations and dependencies; any requirement not modelled, with the reason.`},{heading:`4. Logical and physical structure (RB-8.3)`,guidance:`LOG and PHY parts; at least three port and interface definitions and their connections; for each interface, the items it carries and their direction.`},{heading:`5. satisfy and allocate (RB-8.4)`,guidance:`One row per REQ-SYS: the satisfying element (or the recorded gap). One row per FN: the PHY it is allocated to, matching CP3, or the change and its reason.`},{heading:`6. Completeness against the CP4 minimums (RB-8.6)`,guidance:`A table of the CP4 minimum scope (syllabus §11) with the count in your model and the IDs of anything missing. Behaviour is not part of the CP4 scope for 8.6.`},{heading:`7. Behaviour draft (formative only; RB-8.5 feedback, graded at CP5)`,guidance:`The separate behaviour file and its checker log: the SCN-001 flow, the operating states and the perform/exhibit links; the coverage-tool mapping table; the walker traces you ran and any gap you found, with what you did about it.`},{heading:`8. Graduate: interaction view of one scenario step (individual, ≈ 1.25 h)`,guidance:`Choose one ConOps step in which AeroLink and another party exchange an item across an interface (e.g. SCN-002 steps 2–3 over IF-003; SCN-003 A2 curtailment from EXT-002; the SCN-004 trigger, the health report over IF-013). Reuse the port and interface definitions already in your CP4 model for that interface; add only the item direction you need. Model each party’s behaviour as a performed action that sends and accepts the items via the ports (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 45–46; OMG SysML v2.1 Beta 2, Part 1, p. 137–138). Run it through the checker. Then, in about ½ page: (a) what ordering the view asserts across the participants and what it leaves unordered; (b) what it adds to the action flow of the same scenario; (c) one finding about the interface or port definitions the exercise exposed, written as a RID.`},{heading:`9. AI usage statement (RB-12)`,guidance:`Tool, purpose, prompts, outputs and your evaluation. AI-generated SysML must be accepted by the checker and explained by its owner; AI-suggested RIDs are tagged AI-suggested-reviewed in the RID writer and checked against the model by the writer.`},{heading:`10. RID set given (RB-17; Week 12 days 1–3)`,guidance:`The RID writer’s Week 12 Markdown table (not the practice list): ≥ 5 RIDs on the assigned model, each with ID, location, criterion or source, category, severity, discrepancy, fix and the writer’s initials.`}],rubrics:[`RB-8`,`RB-17`,`RB-12`,`RB-16`],rubricScope:`CP4 (team): RB-8 at 75 % — RB-8.1 validity (of the CP4 model file; the separate behaviour file is excluded), 8.2 organisation and conventions, 8.3 structure semantics, 8.4 requirements semantics and 8.6 completeness against the syllabus §11 CP4 scope. RB-8.5 (behaviour semantics) gives formative feedback only at CP4 and is graded at CP5; by default its 15 points are redistributed over the other five RB-8 criteria in proportion to their points. RB-17.1–17.3 at 15 % on the RIDs the team gives (scored after Week 12 day 3; late RIDs score 0 on 17.3). RB-12.1–12.3 at 10 % on the AI usage statement. Graduate interaction view: a required review-notebook entry that is always read (RB-16 graduate-task rule), given formative feedback on RB-8.5 (behaviour consistent with the scenario and linked to structure) and informing RB-16.1 (engineering reasoning).`,aiUse:`AI tools may explain checker messages or propose SysML and RIDs. Any AI-generated SysML must be accepted by the checker and explained by its owner (RB-12.3). An AI-suggested RID must be checked against the model by its writer and tagged AI-suggested-reviewed; a RID that names a defect the model does not have counts against RB-17.1. AI output is never evidence of what the checker accepts: only a recorded run counts.`,objectives:[`B11.1`,`B11.2`,`B11.3`,`B11.4`]},quiz:[{id:`q11-1`,bloom:`Apply`,objective:`B11.1`,prompt:`SCN-003 Aircraft Charging, A1 (step 1): both hub chargers are occupied — queue the aircraft or reposition it, then rejoin at step 1. Which fragment models this branch in an action flow?`,options:[{id:`a`,text:`first start; then merge awaitCharger; then decide chargerCheck; if chargerFree then action connectCharger; else action queueOrReposition; then awaitCharger;`,correct:!1,explanation:`The targets are declared inside the branches; the target of a conditional succession must be named, not declared in place (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 35), so the checker rejects it (course probe of this pattern).`},{id:`b`,text:`first start; then merge awaitCharger; then fork f; then connectCharger; then queueOrReposition; action queueOrReposition; then awaitCharger; action connectCharger;`,correct:!1,explanation:`A fork enables all its successors (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 40): this says the aircraft is connected and queued at the same time, every time.`},{id:`c`,text:`first start; then merge awaitCharger; then decide chargerCheck; if chargerFree then connectCharger; else queueOrReposition; action queueOrReposition; then awaitCharger; action connectCharger;`,correct:!0,explanation:`Correct. The decision chooses exactly one branch, else covers the occupied case, and the merge lets the queued aircraft return to the check before step 1 (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 37–38). A course probe of this fragment passed the checker; that shows it is well formed, and the reading above is what makes it right.`},{id:`d`,text:`first start; then merge awaitCharger; then decide chargerCheck; if chargerFree then connectCharger; if not chargerFree then awaitCharger; action queueOrReposition; then awaitCharger; action connectCharger;`,correct:!1,explanation:`The occupied branch loops straight back to the merge: queueOrReposition is the target of no succession, so the queue-or-reposition step never happens.`}],cite:{reading:`R72`,pages:`37–38`}},{id:`q11-2`,bloom:`Analyse`,objective:`B11.1`,prompt:`A team’s dispatch flow contains: then decide energyCheck; if stateOfCharge >= 0.9 then releaseAircraft; if stateOfCharge >= 0.8 and stateOfCharge < 0.9 then topUpCharge; if stateOfCharge < 0.7 then reassignBooking; (no else; stateOfCharge is a Real fraction from 0 to 1; FICTIONAL thresholds). What does a reviewer report?`,options:[{id:`a`,text:`No guards overlap, but for 0.7 ≤ stateOfCharge < 0.8 none holds and there is no else, so no succession out of energyCheck is possible`,correct:!0,explanation:`Correct. The guards cover [0.9, 1], [0.8, 0.9) and [0, 0.7): they do not overlap, and [0.7, 0.8) is left out. A succession whose guard is false is not possible (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 35), and else is the branch taken when all the guards are false (OMG SysML v2.1 Beta 2, Part 1, p. 136). The checker evaluates no guard, so it accepts the file either way (course probe).`},{id:`b`,text:`At 0.95 the first and the second guard both hold, so the model does not determine which branch is taken; every value below 0.8 has its own branch`,correct:!1,explanation:`The second guard also requires stateOfCharge < 0.9, so at 0.95 only the first guard holds; and values from 0.7 up to 0.8 have no branch.`},{id:`c`,text:`Every value from 0 to 1 satisfies exactly one guard, so the decision is complete as written and an else branch would never be taken`,correct:!1,explanation:`Values from 0.7 up to 0.8 satisfy none of the guards; that band is the gap a reviewer reports.`},{id:`d`,text:`Values of 0.9 and above satisfy two guards and values below 0.7 satisfy none, so the decision has both an overlap and a gap`,correct:!1,explanation:`Values below 0.7 satisfy the third guard, and values of 0.9 and above satisfy only the first; the only gap is [0.7, 0.8).`}],cite:{reading:`R72`,pages:`35–38`}},{id:`q11-3`,bloom:`Apply`,objective:`B11.1`,prompt:`Inside an action def a team writes, in this order: action classifyFault { out classification : FaultClass; } · succession flow classifyFault.classification to flagAircraft.classification; · action flagAircraft { in classification : FaultClass; } · then action reassignBookings; · action notifyMaintenance; — Which ordering does the fragment assert?`,options:[{id:`a`,text:`classifyFault, flagAircraft, reassignBookings, then notifyMaintenance: the actions happen in the order in which the file declares them`,correct:!1,explanation:`Lexical order alone asserts nothing; only successions, including the then shorthand, order actions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 31, sl.33).`},{id:`b`,text:`Only that a classification is transferred; nothing says which action finishes first, and reassignBookings follows classifyFault`,correct:!1,explanation:`A succession flow does order the two actions (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 32), and then takes the lexically previous action, flagAircraft, as its source (sl.33), not classifyFault.`},{id:`c`,text:`flagAircraft completes before classifyFault starts, because the succession flow points into the input of flagAircraft`,correct:!1,explanation:`The order runs the other way: the first action must finish producing its output before the second can begin consuming it (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 32).`},{id:`d`,text:`classifyFault finishes producing before flagAircraft consumes; reassignBookings follows flagAircraft; notifyMaintenance is unordered`,correct:!0,explanation:`Correct. A succession flow requires the first action to finish producing its output before the second can begin consuming it (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 32); then is a succession from the lexically previous action, flagAircraft (sl.33); notifyMaintenance is in no succession at all. The fragment passes the checker (course probe).`}],cite:{reading:`R72`,pages:`31–33`}},{id:`q11-4`,bloom:`Apply`,objective:`B11.2`,prompt:`From charging, a CellOverTemperature transfer must move the aircraft to outOfService only while it is still connected (attribute connected : Boolean), and the transition must send a FireAlarm to the operations centre (parameter opsCentre). Which transition is written correctly for the 2026-08 notation?`,options:[{id:`a`,text:`transition overTemp first charging if connected accept CellOverTemperature do send new FireAlarm() to opsCentre then outOfService;`,correct:!1,explanation:`Guard before trigger. One OMG SysML v2.1 Beta 2, Part 1 example prints this order, but OMG SysML v2.1 Beta 2, Part 1 says the guard comes after the accepter, and the 2026-08 checker rejected this order with a syntax error (course probe; see the cautions).`},{id:`b`,text:`transition overTemp first charging accept CellOverTemperature if connected do send new FireAlarm() to opsCentre then outOfService;`,correct:!0,explanation:`Correct: source, trigger, guard, effect, target — the order of Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 53 and OMG SysML v2.1 Beta 2, Part 1, p. 152. A course probe of this transition passed the checker.`},{id:`c`,text:`transition overTemp first charging accept CellOverTemperature then outOfService do send new FireAlarm() to opsCentre if connected;`,correct:!1,explanation:`Effect and guard after the target are not in the notation; the target ends the transition (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 53).`},{id:`d`,text:`transition overTemp first charging accept CellOverTemperature then outOfService; state charging { entry send new FireAlarm() to opsCentre; }`,correct:!1,explanation:`The alarm would be sent on every entry to charging, not when the transition fires, and the guard is missing.`}],cite:{reading:`R73`,pages:`53`}},{id:`q11-5`,bloom:`Evaluate`,objective:`B11.3`,prompt:`A team’s VertiportStates contains first start then open; and, a few lines later, first start then limited; (both open and limited are substates; the state is not parallel). The checker log shows PASS with no messages. As the reviewer, what do you write?`,options:[{id:`a`,text:`No RID: the log shows PASS with no messages, so the state definition is valid and therefore also correct`,correct:!1,explanation:`PASS establishes parsing, name resolution and the pilot’s rules; the course probe of two initial successions passed without a message, yet the model contradicts itself.`},{id:`b`,text:`An editorial RID: the second first start line is a duplicate line that affects the layout of the file only, not its meaning`,correct:!1,explanation:`It changes what the model asserts (which substate is active after entry), so it is a semantic finding.`},{id:`c`,text:`A major semantics RID: a non-parallel state has exactly one active substate; keep one initial state or guard both exclusively`,correct:!0,explanation:`Correct. In a non-parallel state exactly one substate is active after entry (OMG SysML v2.1 Beta 2, Part 1, p. 146, stated in this week’s lesson), and the initial state is the one after first start (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 48). OMG SysML v2.1 Beta 2, Part 1 also allows conditional initial successions with exclusive guards (p.150).`},{id:`d`,text:`A RID asking the team to make VertiportStates a parallel state, so that open and limited can both be its initial states`,correct:!1,explanation:`That changes the meaning: in a parallel state open and limited would be concurrent, not alternatives (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 51).`}],cite:{reading:`R82`,pages:`146`}},{id:`q11-6`,bloom:`Analyse`,objective:`B11.2`,prompt:`A team models aircraftStates as parallel with two regions, operational (… inFlight …) and health (normal, degraded), and adds transition first operational.inFlight accept CellOverTemperature then health.degraded; . Which change keeps both regions, removes the problem, and rests only on what the course sources establish?`,options:[{id:`a`,text:`health accepts CellOverTemperature and enters degraded, whose entry sets an attribute; operational reacts with accept when on that attribute`,correct:!0,explanation:`Correct. Transitions between concurrent states are not allowed (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 51), so each region must react on its own. A change trigger fires when its Boolean expression becomes true (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 54; OMG SysML v2.1 Beta 2, Part 1, p. 139), and an entry action can assign a value (sl.54; OMG SysML v2.1 Beta 2, Part 1, p. 150). A course probe of this form passed the checker, which shows only that it is well formed.`},{id:`b`,text:`Both regions accept the same CellOverTemperature transfer, since the course sources establish that one transfer triggers an accepter in each region`,correct:!1,explanation:`Plausible, and it passes the checker (course probe), but a PASS is not semantic evidence. OMG SysML v2.1 Beta 2, Part 1 speaks of an accepter accepting a transfer (p.139, p.146); no course source says that one transfer triggers accepters in two concurrent regions.`},{id:`c`,text:`Replace the transition with a fork from inFlight to degraded, so that both regions move on the same over-temperature event`,correct:!1,explanation:`Fork is an action-flow control node (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 40), not a way to cross between concurrent states.`},{id:`d`,text:`Remove parallel and keep the transition, so that at any moment the aircraft is in exactly one state of one of the two regions`,correct:!1,explanation:`Then the aircraft could not be in flight and degraded at the same time, which is what the regions were meant to express.`}],cite:{reading:`R73`,pages:`51–54`}},{id:`q11-7`,bloom:`Apply`,objective:`B11.3`,prompt:`In your model, charging systems (PHY-003) must be the element that carries out FN-007 Control vertiport charging power, and the vertiports (PHY-002) must have the weather-hold states vertiportWeatherStates. Which pair of lines, inside the two part usages, expresses this?`,options:[{id:`a`,text:`In PHY-003: exhibit Logical::'FN-007';   In PHY-002: perform Behavior::vertiportWeatherStates;`,correct:!1,explanation:`exhibit must reference a state; the checker rejected exhibit of a function with “Must reference a state.” (course probe). Performing a state usage passed the checker but does not say that the vertiports are in those states.`},{id:`b`,text:`In PHY-003: satisfy Logical::'FN-007';   In PHY-002: allocate vertiportWeatherStates;`,correct:!1,explanation:`satisfy relates a design element to a requirement, not a function; allocate is a separate relationship with two ends.`},{id:`c`,text:`In PHY-003: action :> Logical::'FN-007';   In PHY-002: state :> vertiportWeatherStates;`,correct:!1,explanation:`These declare new composite behaviour features of the parts that subset the originals; they do not say that the part performs FN-007 or exhibits the states defined in Behavior.`},{id:`d`,text:`In PHY-003: perform Logical::'FN-007';   In PHY-002: exhibit Behavior::vertiportWeatherStates;`,correct:!0,explanation:`Correct. perform makes the owner the performer of an action (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 41); exhibit identifies the part that exhibits states (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 56). A course probe of this pair passed the checker.`}],cite:{reading:`R72`,pages:`41`}},{id:`q11-8`,bloom:`Evaluate`,objective:`B11.3`,prompt:`SCN-001 A2: the destination vertiport is under a weather hold — offer the nearest open vertiport, or decline with the reason recorded; scenario ends. A team’s flow has: then decide weatherCheck; if destinationOnHold then offerAlternative; else quoteFare; action offerAlternative; then quoteFare; (quoteFare is step 3). The checker passes the file. Evaluate it.`,options:[{id:`a`,text:`Consistent: A2 is guarded, and after the offer the flow rejoins the main flow at step 3, which is what alternate flows do`,correct:!1,explanation:`Some alternates rejoin; this one ends the scenario. The flow goes on to step 3 and quotes a fare to a held destination, which the ConOps excludes.`},{id:`b`,text:`Inconsistent: A2 ends the scenario, so after the offer or the recorded decline the flow must reach done, not quoteFare`,correct:!0,explanation:`Correct. A2 ends the scenario: after the offer (or the decline with the reason recorded) the flow goes to done. A passenger who takes the alternative makes a new request, a new run of SCN-001, not a rejoin. Behaviour must be consistent with the scenarios (RB-8.5); the checker passes the file because it does not compare flows with the ConOps, and the coverage tool reports this flow as an alt-outcome error.`},{id:`c`,text:`Invalid SysML: a succession from an alternate-flow action into a main-flow action is rejected by the checker`,correct:!1,explanation:`Nothing forbids a succession to an existing action, and the prompt says the checker passed; the problem is that the ConOps says this branch ends.`},{id:`d`,text:`Consistent, but offerAlternative should be renamed declineRequest so that the branch reads as the ConOps does`,correct:!1,explanation:`Renaming does not change what the flow asserts: it still continues to step 3.`}],cite:{reading:`R72`,pages:`38`}},{id:`q11-9`,bloom:`Evaluate`,objective:`B11.3`,prompt:`A team writes transition dispatch first dispatchReady accept DispatchRelease if remainingEnergy then inFlight; where remainingEnergy is an attribute of type Real. Their checker log is clean. Which assessment is right?`,options:[{id:`a`,text:`Correct: any non-zero remainingEnergy makes the guard true, so dispatch needs at least some energy`,correct:!1,explanation:`A guard is a Boolean condition (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 53); SysML does not convert a Real into a truth value by being non-zero.`},{id:`b`,text:`Correct: remainingEnergy is an attribute of the state definition, so the guard resolves, and a resolved guard is valid`,correct:!1,explanation:`Being visible makes the name resolve; it does not make a Real a condition.`},{id:`c`,text:`Wrong but undetected: a guard must be a Boolean condition (e.g. remainingEnergy >= threshold); the checker missed it`,correct:!0,explanation:`Correct. The guard must be true for the transition to fire (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 53), so it must be a condition. The pilot accepted the Real-typed guard silently (course probe, 2026-10-11): this is the reviewer’s finding, not the checker’s.`},{id:`d`,text:`Wrong, and the log must come from an old file, because the checker rejects every non-Boolean guard`,correct:!1,explanation:`The course probe shows the 2026-08 checker accepts it; do not assume the checker checks guard types.`}],cite:{reading:`R73`,pages:`53`}},{id:`q11-10`,bloom:`Evaluate`,objective:`B11.4`,prompt:`Reviewing another team’s SCN-003 flow, you find that step 4 (record the charge session) has no action and no other node. Which RID is the most actionable?`,options:[{id:`a`,text:`RID-T5-03 | Behavior::'SCN-003' between chargeBattery and disconnectCharger | SCN-003 step 4; RB-8.5 | major | chargeBattery leads straight to disconnectCharger, so step 4 is missing | Fix: add then action recordChargeSession; between the two`,correct:!0,explanation:`Correct. It locates the gap by element and position, names the ConOps step and a rubric criterion, rates a missing ConOps step major (inconsistent with its source on the course severity scale) and gives a change the owner can make as written (RB-17.1–17.3). The fields and the scale are the course RID convention; SEBoK supports only the idea of analysing against pre-established criteria and identifying actions (SEBoK v2.14, “Technical Reviews and Audits”, p. 388).`},{id:`b`,text:`RID-T5-03 | Behavior::'SCN-003' between chargeBattery and disconnectCharger | SCN-003 step 4; RB-8.5 | editorial | chargeBattery leads straight to disconnectCharger, so step 4 is missing | Fix: add then action recordChargeSession; between the two`,correct:!1,explanation:`Identical except the severity. A missing ConOps step changes what the model asserts and makes it inconsistent with its source, so on the course scale it is major, not editorial.`},{id:`c`,text:`RID-T5-03 | the charging behaviour in the Behavior package | good modelling practice | major | the charging flow could be more complete than it is at the moment | Fix: add the missing steps to the flow where they belong in the scenario`,correct:!1,explanation:`No findable location, no criterion, a vague discrepancy and a fix the owner cannot act on without asking (RB-17.1, 17.3).`},{id:`d`,text:`RID-T5-03 | Behavior::'SCN-003' | RB-8 | major | step 4 of SCN-003 is not modelled anywhere in the charging flow | Fix: model step 4 so that the flow matches the text of the ConOps scenario`,correct:!1,explanation:`Better located, but RB-8 is a rubric, not a criterion (RB-17.1 asks for the violated criterion), the location does not say where in the flow, and “model step 4” leaves the construct and the position open (RB-17.3).`}],cite:{reading:`R06c`,pages:`388`}},{id:`q11-11`,bloom:`Evaluate`,objective:`B11.4`,prompt:`Your team drafts five RIDs on a peer model: (1) package names use underscores; (2) a doc comment has a typo; (3) the operating-state machine is exhibited by no part; (4) a doc comment writes a requirement title in lower case; (5) the import of ISQ has no visibility (the file therefore fails the checker). What is the main weakness of the set against RB-17?`,options:[{id:`a`,text:`None: five RIDs meet the count, and the count is the first thing RB-17 checks`,correct:!1,explanation:`Five is the count the course form asks for; RB-17.2 also asks for sensible severities and at least two RIDs on semantics or traceability.`},{id:`b`,text:`RIDs on checker errors are out of scope here, because the instructor checks model validity separately anyway`,correct:!1,explanation:`A failing model is a real defect with a clear criterion (RB-8.1); reporting it is correct.`},{id:`c`,text:`The set is too short: RB-17 rewards volume, so add five more editorial RIDs to it`,correct:!1,explanation:`RB-17 scores correctness, significance and actionability, not volume.`},{id:`d`,text:`Only (3) is semantics or traceability; RB-17.2 level 4 needs two: find a second one, and rate (5) major`,correct:!0,explanation:`Correct. RB-17.2 asks for sensible severities and at least 2 RIDs on semantics or traceability; (1), (2) and (4) are editorial, (3) is traceability, and (5) blocks acceptance, so it is major (RB-8.1). A second candidate: an action that subsets no function, or a satisfy targeting the wrong kind of element.`}],cite:{reading:`R06c`,pages:`386–388`}},{id:`q11-12`,bloom:`Apply`,objective:`B11.4`,prompt:`A reviewer writes: RID-T2-04 | Location: Behavior::'SCN-005' | Criterion: SCN-005 A1 | Severity: major | A1 is not modelled. | Fix: model A1. Which revision makes it actionable without changing its finding?`,options:[{id:`a`,text:`Raise the severity to critical and add “urgent” to the discrepancy, so that the owner deals with this RID first`,correct:!1,explanation:`Severity does not make a RID actionable, and the course scale has no “critical”.`},{id:`b`,text:`Name where A1 branches (after divertFlights) and the change: decide alternateCheck, exclusive guards, else declarePriorityLanding`,correct:!0,explanation:`Correct. The discrepancy now points at the element and position, and the fix names the constructs and targets (if alternateOpen then acceptRevisedIntents; if (not alternateOpen) and alternateWithinReserve then divertNearest; else declarePriorityLanding; with both new actions leading to notifyPassengers, step 5), so the owner can make the change as written (RB-17.3, course RID convention).`},{id:`c`,text:`Add “see SCN-005 A1 in the ConOps” to the fix, so that the owner can look up exactly what the alternate flow requires there`,correct:!1,explanation:`Pointing to the source again does not tell the owner what to change.`},{id:`d`,text:`Split it into two RIDs, one on the flow and one on the ConOps text, so that each of the two parts can be dispositioned separately`,correct:!1,explanation:`The ConOps is the criterion, not a second defect.`}],cite:{reading:`R06c`,pages:`388`}},{id:`q11-13`,bloom:`Analyse`,objective:`B11.3`,prompt:`Cross-check the reference behaviour: the operating states accept DispatchRelease (dispatchReady → inFlight), and FN-011 Dispatch aircraft is derived from SCN-002 and performed by LOG-005. In the SCN-002 action flow, boarding is followed by takeOff. What does a reviewer conclude?`,options:[{id:`a`,text:`Nothing to report: the dispatch transition already shows that dispatch happens during SCN-002`,correct:!1,explanation:`A transition says what the aircraft does if a release arrives; it does not say which scenario step sends it.`},{id:`b`,text:`The state machine is wrong: dispatchReady should move to inFlight without any trigger at all`,correct:!1,explanation:`Removing the trigger removes the interlock point where REQ-STK-006 is enforced.`},{id:`c`,text:`A traceability gap: no SCN-002 step subsets FN-011 or causes DispatchRelease; add a dispatch step before takeOff`,correct:!0,explanation:`Correct. Each transition’s trigger should be caused by some scenario step, and the functions derived from a scenario should appear in it (instructor cross-check method; perform and subsetting links, Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 41). The fix: action dispatchAircraft :> FN-011 between boarding and takeOff, or a recorded reason why dispatch belongs to another scenario. The checker cannot see the gap.`},{id:`d`,text:`The flow is wrong: takeOff should be removed, because FN-005 already covers the whole of step 5`,correct:!1,explanation:`That deletes a ConOps step; the missing element is the dispatch step, not take-off.`}],cite:{reading:`R72`,pages:`41`}},{id:`q11-14`,bloom:`Apply`,objective:`B11.1`,prompt:`A team defines use case def 'Assist Passenger' { subject enterprise : AeroLinkEnterprise; actor agent : CustomerServicesAgent; actor passenger : 'STK-001'; } and, inside use case <'SCN-001'> (subject enterprise; actor passengers : 'STK-001'; actor agent : CustomerServicesAgent;), writes: then include use case assist : 'Assist Passenger' { subject enterprise; actor :>> agent = 'SCN-001'::agent; } The checker passes the file. What does the include assert about who takes part in assist?`,options:[{id:`a`,text:`Its enterprise and agent are those of SCN-001, but its passenger is unbound: add actor :>> passenger = 'SCN-001'::passengers;`,correct:!0,explanation:`Correct (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 101). The subject of a nested use case is bound to its container’s, and the agent is bound explicitly, but actors are never bound implicitly, so nothing says that the assisted passenger is one of the ride request’s passengers. The listing passed the checker with and without the added binding (course probes).`},{id:`b`,text:`subject enterprise; declares a second, unbound subject inside the include, so the assisted enterprise is a different one`,correct:!1,explanation:`The subject of a nested use case is bound implicitly to that of its container (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 101); the slide’s own example repeats subject vehicle; in the same way.`},{id:`c`,text:`Both actors are bound, because an included use case takes every actor whose type matches an actor of its container`,correct:!1,explanation:`Actors need to be bound explicitly (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 101); matching types bind nothing.`},{id:`d`,text:`Nothing is bound until an extend relationship from 'Assist Passenger' to SCN-001 is added to the model`,correct:!1,explanation:`The traditional extend relationship is not supported yet (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 101); include with explicit actor bindings is the supported form.`}],cite:{reading:`R76`,pages:`101`}},{id:`q11-15`,bloom:`Apply`,objective:`B11.2`,prompt:`charging has do chargeBattery; and exit logSession;. The transition overTemperature from charging accepts CellOverTemperature, has the effect do send new FireAlarm() via opsPort and the target outOfService, which has entry isolateAircraft; and do awaitInspection;. Which statement holds at the moment the FireAlarm is sent?`,options:[{id:`a`,text:`isolateAircraft has completed, and chargeBattery keeps running until awaitInspection starts in outOfService`,correct:!1,explanation:`The target’s entry action follows the effect, so isolateAircraft has not started; and the source’s do action is interrupted before its exit action.`},{id:`b`,text:`chargeBattery has been interrupted and logSession has completed; isolateAircraft has not started yet`,correct:!0,explanation:`Correct. When a transition fires, the source’s do action is interrupted, then its exit action is performed, then the effect, then the target’s entry action, then its do action (OMG SysML v2.1 Beta 2, Part 1, p. 153–154, as this week’s lesson states it); the effect precedes entry to the target (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 53).`},{id:`c`,text:`logSession has not started yet: the exit action runs after the effect, once outOfService has been entered`,correct:!1,explanation:`The exit action of the source is performed before the effect (OMG SysML v2.1 Beta 2, Part 1, p. 153).`},{id:`d`,text:`Nothing is ordered: the effect, the exit action and the entry action all start together when the transition fires`,correct:!1,explanation:`Firing a transition is an ordered sequence: interrupt the do action, exit, effect, entry, do (OMG SysML v2.1 Beta 2, Part 1, p. 153–154).`}],cite:{reading:`R82`,pages:`153–154`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min: concept studio; lab L11 and the RID kick-off)`,hours:2.5},{activity:`Core readings narrowed to what the lesson uses: Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Action Definition”, slides 30–41 and 45–46, Seidewitz, Intro to the SysML v2 Language: Textual Notation, “State Definitions”, slides 48–54 and 56, Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Use Case Definition”, slides 100–101 (24 slides at ≈ 30 sl/h)`,hours:.8},{activity:`Online lesson (≈ 4,700 words) and the out-of-class part of the three activities`,hours:1.4},{activity:`Readiness quiz Q10 / knowledge check (15 items)`,hours:.3},{activity:`L11 out of class: SCN-001 flow and operating states in SysML from the in-class maps, links, checker runs (team share)`,hours:2},{activity:`CP4 finalisation: zero checker errors, completeness table, package and AI statement (team share; assumes v0.2 passed in Week 10, see cautions)`,hours:2},{activity:`Graduate interaction view: OMG SysML v2.1 Beta 2, Part 1, p. 137–138, model reusing the CP4 ports, checker run, ½ page and one RID`,hours:1.25},{activity:`Review notebook entry, time log, AI statement contribution`,hours:.25}],references:[{reading:`R82`,pages:`134–140`},{reading:`R82`,pages:`145–154`},{reading:`R06c`,pages:`386–388`},{reading:`R41`,pages:`76–77`}],review:{status:`self-checked`,openIssues:[]}},T=e({default:()=>E}),E={week:12,drivingQuestion:`Your CP4 model claims that AeroLink’s design meets its requirements. How will each claim be checked, what result counts as success, which needs can only be judged in service — and can you show, from the model alone, that every requirement is connected to the evidence that will settle it?`,blocks:[{id:`w12-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to B-CLO5 (analyse model-based traceability to assess verification coverage) and B-CLO6 (justify engineering decisions in a technical review). It also touches B-CLO2 through the measures. Your CP4 model asserts that the design meets its requirements: every satisfy is a claim. This week adds the other half: verification cases that say how each claim will be checked, MOE and MOP attributes for the Week 5 measures, and a trace audit computed from the model. In days 1–3 you also write RIDs on another team’s CP4 model (the Week 11 assignment); then you answer the RIDs on yours and finish the behaviour for CP5. The lab output is model v0.4, an audit report and a disposition log; all three feed CP5.`],bullets:[`B12.1 (Understand) Distinguish verification from validation on AeroLink, and select a verification method for each requirement with a stated reason.`,`B12.2 (Apply) Define verification cases for at least three requirements: subject, objective with verify, method, and verdict logic (pass, fail, inconclusive, error).`,`B12.3 (Apply) Represent MOE and MOP in the model and link them to the requirements they measure and to the verification or validation activity that assesses them.`,`B12.4 (Evaluate) Audit trace coverage with reproducible numbers (parent, satisfy, verify; orphans; childless parents) and complete at least three 11-step threads.`,`B12.5 (Evaluate) Disposition every RID received on the CP4 model: accept, modify, reject or defer, with a reason, the fix reference and the closure evidence.`,`Graduate extension (optional this week, course workload option B): a model-credibility argument for one analysis that a verification case relies on (The MITRE Systems Engineering Guide, “Verification and Validation of Simulation Models”).`],citations:[],provenance:`instructor-authored`},{id:`w12-intuition`,kind:`intuition`,title:`Intuition: the factory test and the first winter`,paragraphs:[`A city buys a fleet of electric buses. Each bus passes its factory acceptance test: the battery delivers the rated energy on the test cycle, the doors open in under two seconds, the heater reaches its set point. In the first winter, the buses on the longest route run out of charge before the end of the evening service, because the heater draws far more power on real streets than on the test cycle. Nothing in the factory report was false; the specification was not what the city needed.`,`The two questions need different evidence. “Did we build it as specified?” is answered against the specification, element by element, often with a yes or no. “Does it do the job in service?” is answered against the users’ needs, in the operating environment, and often needs judgement. For AeroLink, a hub charger can pass every charge-time test while passengers still wait too long. This week makes both questions explicit in the model, and audits whether every requirement is connected to the activity that will answer it.`],citations:[],provenance:`instructor-authored`},{id:`w12-vv`,kind:`concept`,title:`Verification and validation: what each compares, and with what`,paragraphs:[`SEBoK defines verification as confirmation, through objective evidence, that specified requirements have been fulfilled. Its purpose is to find the faults introduced whenever inputs are transformed into outputs, and it is performed together with validation, though separate from it (SEBoK v2.14, “System Verification”, p. 634). A verification action has a definition and a performance. The definition identifies the element to be verified and the reference that defines the expected result. The performance obtains a result, compares it with the expected result and deduces how correct the element is (SEBoK v2.14, “System Verification”, p. 635). Any engineering element can be verified: verifying a requirement means checking that it is well formed (singular, verifiable and so on) (SEBoK v2.14, “System Verification”, p. 635).`,`The DoD Guidebook puts the two questions plainly. Verification provides evidence that the system or element performs its intended functions and meets the performance requirements of the system performance specification and the functional and allocated baselines; it answers “Did you build the system correctly?” (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149). Validation provides objective evidence that the system capability complies with stakeholder performance requirements in the intended operational environment; it answers “Is it the right solution to the problem?”, under operationally realistic conditions, often with independent testers and end users (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150). Verification starts during requirements analysis, when the program decides how and when each requirement will be verified. The resulting verification matrix becomes part of the baseline (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149).`,`MITRE’s definitions draw the line in a different place. Verification determines whether the products of a phase fulfil the requirements set in the previous phase. Validation evaluates whether the delivered system meets the customer’s operational need in the most realistic environment achievable (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433). MITRE adds that V&V are integrated activities throughout the life cycle, not separate stages (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 434). SEBoK lists the main differences. A verification comparison is generally binary, whereas a validation result may need a value judgement against a threshold. Verification concerns one element, validation a set of elements taken as a whole. And validation presupposes that verification has been done (SEBoK v2.14, “System Verification”, p. 636).`,`The course convention, which RB-10.1 grades, follows MITRE’s wording (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433). Verification of AeroLink compares a system or element with its specified requirements, REQ-SYS and REQ-STK alike: built right. Validation compares the service with the stakeholders’ needs, using the MOEs and scenarios, in the intended operational environment: the right system. DoD does not say this. It validates against stakeholder performance requirements (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150), which in course terms are REQ-STK, so putting REQ-STK under verification is the course’s choice. The advanced section shows that SEBoK sits closer to DoD. Name the convention you use, and do not merge the sources’ wordings.`],quote:{text:`Verification answers the question, “Did you build the system correctly?”`,cite:{reading:`R49`,pages:`149`}},citations:[{reading:`R23a`,pages:`634–636`},{reading:`R49`,pages:`149–150`},{reading:`R58`,pages:`433–434`}],provenance:`mixed`},{id:`w12-methods`,kind:`concept`,title:`Verification methods, and how to choose one`,paragraphs:[`Three sources name the methods, and they do not use quite the same terms. The DoD Guidebook has four. Demonstration relies on visual observation and is used when quantitative assurance is not required. Examination is visual inspection of equipment and design data, for physical characteristics, marking and workmanship. Analysis uses recognised analytic techniques, including computer models and analysis of test data. Test provides data under fully controlled and traceable conditions, used to evaluate quantitative characteristics (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150). The program combines them cost-effectively at every level (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150).`,`SEBoK’s table adds analogy and sampling. Inspection relies on the senses or simple measurement and needs no stimuli. Analysis is used mainly where testing under realistic conditions cannot be achieved or is not cost-effective. Demonstration shows correct operation against observable characteristics with no or minimal instrumentation; SEBoK adds that it may suit requirements stated in statistical terms, such as a mean time to repair. Test quantitatively verifies measurable characteristics under controlled conditions, real or simulated (SEBoK v2.14, “System Verification”, p. 639). SysML v2 fixes four values in its library: the VerificationMethod metadata annotates a verification case with inspect, analyze, demo or test (OMG SysML v2.1 Beta 2, Part 1, p. 176). Note the mismatches: “examination” (DoD) and “inspect” (SysML) are close but not identical, and SEBoK’s analogy, sampling and simulation (SEBoK v2.14, “System Verification”, p. 637) have no SysML value of their own. A simulation is recorded in SysML as analyze, with the simulation described in the doc.`,`Choosing a method is a decision with reasons, not a default. SEBoK names “use only testing” as a pitfall: testing needs the implemented product, while analysis and inspection find errors earlier and more cheaply. It also calls for a verification strategy, a justified selection of verification actions against risks (SEBoK v2.14, “System Verification”, p. 640). RB-10.2 scores the same thing: a method per requirement, justified, with level and environment, where “default test everywhere” is level 2. Four questions decide most cases (instructor heuristic). What evidence does the criterion need: a measured quantity, an observable yes or no, or a physical property? Can the real conditions be produced, or only modelled? At which level does the requirement apply? What does a wrong answer cost? Worked example (a) applies them to AeroLink.`],citations:[{reading:`R49`,pages:`149–150`},{reading:`R23a`,pages:`637`},{reading:`R23a`,pages:`639–640`},{reading:`R84`,pages:`176`}],provenance:`mixed`},{id:`w12-worked-methods`,kind:`worked-example`,title:`Worked example (a): verification or validation, and which method, on AeroLink`,paragraphs:[`The table takes seven items from the instructor reference. For each, it asks two things: is the activity verification or validation, and what method fits, for which reason? Read the reasons, not only the answers. The reference’s VER-004 is a demonstration although its criterion counts 20 injected forecasts. The count is of observed holds, not a measured quantity, so the DoD condition, that quantitative assurance is not required, still holds. VER-003 is an analysis because no test campaign can fly every vertiport pair in every wind case at end-of-life battery capacity. Its inconclusive condition is that the energy model has not been validated against flight data.`,`The last two rows are the ones teams get wrong. REQ-SYS-002 has a predicted noise level, TPM-002 at 63.5 dBA (FICTIONAL). A prediction is analysis evidence that tracks the design, but the requirement is closed by measuring real movements on the published procedures (VER-002), which is also how R-003 is mitigated. MOE-001, the 90th-percentile passenger wait, is validated in operation, because it depends on the fleet, the chargers, the schedule and the demand together. The same booking and boarding data do a second job. REQ-STK-001 sets a 15 min limit on that same quantity and records analysis as its method, so comparing the data with that limit verifies REQ-STK-001 under the course convention. The reference has not recorded a VER for it yet; worked example (d) shows how the audit counts that.`],table:{caption:`AeroLink items, V or V, and method (reference IDs; values FICTIONAL)`,header:[`Item`,`V or V`,`Method and activity`,`Reason`],rows:[[`REQ-SYS-001 charge to dispatch threshold ≤ 20 min`,`Verification`,`Test (VER-001): 30 timed charges at a hub`,`A quantitative characteristic under controlled, traceable conditions (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150)`],[`REQ-SYS-003 planned landing energy ≥ 20 % on every plan`,`Verification`,`Analysis (VER-003): energy model over all pairs and wind cases`,`Every case cannot be flown; analysis where realistic testing is not achievable (SEBoK v2.14, “System Verification”, p. 639)`],[`REQ-SYS-004 weather dispatch hold`,`Verification`,`Demonstration (VER-004): 20 injected exceedances, 20 in-limit forecasts`,`Observed yes/no response; no quantitative assurance needed (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149); inconclusive until U-001 closes`],[`REQ-STK-007 step-free boarding at all vertiports`,`Verification`,`Inspection (VER-011) at 6 of 6 vertiports`,`A physical property found by observation, no stimulus (SEBoK v2.14, “System Verification”, p. 639)`],[`REQ-SYS-006 availability ≥ 90 % per month`,`Verification`,`Analysis (VER-006) of 3 months of maintenance records`,`A monthly ratio from recorded data, not a controlled trial`],[`REQ-SYS-002 pad-edge noise ≤ 65 dBA`,`Verification`,`Test (VER-002); the TPM-002 prediction is tracking evidence only`,`Closure needs measurement on the published procedures; mitigates R-003`],[`MOE-001 passenger wait (P90) for NEED-001`,`Validation`,`Analysis of operational data (INFO-001), first months of service`,`Effectiveness in the intended environment, for the users (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150)`]]},citations:[{reading:`R49`,pages:`149–150`},{reading:`R23a`,pages:`639`}],provenance:`mixed`},{id:`w12-vercase`,kind:`concept`,title:`Verification cases in SysML v2: subject, objective, verify, verdict`,paragraphs:[`A verification case definition defines a process for verifying whether a subject satisfies one or more requirements. It always returns a verdict of type VerdictKind, an enumeration with the values pass, fail, inconclusive and error. The requirements to be verified are declared in the case’s objective, and the subject of the verification case is automatically bound to the subject of the verified requirements (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96). OMG SysML v2.1 Beta 2, Part 1 gives the meanings. Pass: the subject has been determined to satisfy the requirements. Fail: it has been determined not to satisfy them. Inconclusive: no determination could be made. Error: an error occurred while the verification was being performed (OMG SysML v2.1 Beta 2, Part 1, p. 173). The subject, the “unit under test”, may be general in the definition and specific in usages (OMG SysML v2.1 Beta 2, Part 1, p. 173).`,`Formally, a verify inside the objective is a requirement verification usage. It is a subrequirement of the objective, so it is a required constraint of the objective, and its subject is bound by default to the objective’s subject, which is bound to the case’s subject (OMG SysML v2.1 Beta 2, Part 1, p. 176). This is the difference from Week 10. A satisfy asserts, in the design model, that the requirement holds for a design element (OMG SysML v2.1 Beta 2, Part 1, p. 168). A verify states what a verification case sets out to show about its subject; the verdict it returns is the evidence. A satisfy next to a fail verdict is a contradiction that the team must resolve.`,`The steps of a verification case are actions that together determine the verdict. Seidewitz, Intro to the SysML v2 Language: Textual Notation’s example parameterises the requirement with an in parameter for the measured value and asserts, inside the requirement, that this value equals the subject’s own feature. The last step calls PassIf, a utility function that returns pass or fail depending on whether its argument is true. Its argument is the requirement itself, invoked with the subject and the processed measurement: a check of whether the requirement is satisfied for those values (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 96–97). OMG SysML v2.1 Beta 2, Part 1 describes the typical steps: collect data about the subject; analyse it, for example a mean and standard deviation over several measurements; then evaluate the result against the objective (OMG SysML v2.1 Beta 2, Part 1, p. 173–174). A usage can restrict the subject to a test configuration, and individuals can model the actual tests (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 98–99).`],citations:[{reading:`R75`,pages:`96–99`},{reading:`R84`,pages:`173–176`},{reading:`R83`,pages:`168`}],provenance:`mixed`},{id:`w12-worked-vercase`,kind:`worked-example`,title:`Worked example (b): VER-001 for REQ-SYS-001, and what the checker checks`,paragraphs:[`The listing aerolink_ver001_charge_time.sysml adapts the reference model’s VER-001 to Seidewitz, Intro to the SysML v2 Language: Textual Notation’s pattern. REQ-SYS-001 (lines 23–29) has a ChargingSystems subject, binds 20 [min] to maxChargeTime, and takes the measured value as an in parameter, chargeTimeActual (line 26). Its constraint (line 28) asserts that chargeTimeActual equals the subject’s chargeTimeToDispatch, which carries MOP-002 as its short name, and is at most maxChargeTime. The verification definition ChargeTimeTest (lines 33–50) holds the procedure. Line 35 annotates it with @VerificationMethod { kind = VerificationMethodKind::test; }. Its subject, testCharger, has the requirement’s subject definition, and the objective has a doc statement and verify Requirements::'REQ-SYS-001' (lines 37–40).`,`The verdict logic is the heart of the case (lines 46–49). If the procedure was not followed, the verdict is error. If fewer valid charges were recorded than planned, it is inconclusive. Otherwise PassIf calls REQ-SYS-001 with the charger under test and the largest measured charge time, so the limit and the comparison are written once, in the requirement, and the measurement is tied to MOP-002 by the requirement’s own assertion. The reference model writes the comparison again inside PassIf, which is what lets a reversed comparison pass silently (table). The sample size is bound only in the usage (line 57), as a configuration value (Week 9), and the usage narrows the subject to the test configuration (line 56; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 98). The checker accepted the file with no errors and no warnings.`,`The table records the course’s probes (release 2026-08, 2026-10-11; files in the authoring notes). As in Week 10, the checker enforces names and kinds, and evaluates nothing. A case whose subject cannot be the requirement’s subject passes, and so do a Boolean verdict, a reversed comparison, a requirement call without the measured value, two verifies whose requirements have different subjects, a case with no objective or verdict, and an objective that asserts satisfy instead of verify. Put these silent passes on your L12 self-review list.`,`The teaching listing invalid_method_kind_simulation.sysml shows a real team decision. VER-003 is a simulation, and SEBoK lists simulation as a technique, so the team wrote VerificationMethodKind::simulation. The checker rejects line 34 because the library enumeration has no such value. The fix is VerificationMethodKind::analyze, with the simulation described in the doc.`],sysml:[{file:`week12/aerolink_ver001_charge_time.sysml`,caption:`VER-001 as a verification definition and usage for REQ-SYS-001: the requirement takes the measured value as an in parameter, and the computed verdict calls the requirement in PassIf (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 96–97) (FICTIONAL values)`,intent:`conformant`},{file:`week12/invalid_method_kind_simulation.sysml`,caption:`Teaching listing: VER-003 recorded with a method kind that the library does not define — rejected by the checker`,intent:`intentionally-invalid`}],table:{caption:`Recorded checker behaviour on verification-case constructs (release 2026-08, 2026-10-11; probes in the notes)`,header:[`Construct`,`Rule in the readings`,`Recorded result`],rows:[[`VER-001 listing: requirement call in PassIf, four verdicts`,`—`,`PASS, no message`],[`verify naming a part usage; verify naming a requirement definition`,`A verify is a requirement usage, declared in the objective (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96; OMG SysML v2.1 Beta 2, Part 1, p. 176)`,`FAIL: “A requirement must be typed by one requirement definition.”; FAIL: name does not resolve`],[`verify written outside the objective`,`Declared in the objective (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96)`,`FAIL: syntax error`],[`Method kind “simulation”; verdict literal not in VerdictKind`,`inspect, analyze, demo or test (OMG SysML v2.1 Beta 2, Part 1, p. 176); pass, fail, inconclusive, error (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96)`,`FAIL: reference does not resolve (both)`],[`Case subject a ChargingSystems verifying a requirement about the aircraft; usage restricting the subject to another definition`,`Case subject bound to the requirement’s subject (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96)`,`PASS, no message (both)`],[`Boolean comparison bound to verdict : VerdictKind; verdict declared Boolean`,`Always returns a VerdictKind (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96)`,`PASS with WARNING “Bound features should have conforming types”; PASS, no message`],[`Comparison re-written inside PassIf, reversed (>= for a maximum)`,`PassIf checks the requirement for the given values (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 97)`,`PASS, no message`],[`Requirement call in PassIf: parameter name misspelt; measured value omitted; comparison reversed inside the requirement`,`As above`,`FAIL: name does not resolve, “Must correspond to one input parameter”; PASS; PASS`],[`Case with no objective or no verdict; objective with satisfy … by … instead of verify`,`Objective declares the verified requirements (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 96); satisfy asserts (OMG SysML v2.1 Beta 2, Part 1, p. 168)`,`PASS, no message (all)`],[`#moe on a part definition; #moe on a part usage`,`#moe annotates a usage, as an MOE attribute (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 149)`,`FAIL: “Cannot annotate PartDefinition”; typing error on the part usage`]]},citations:[{reading:`R75`,pages:`96–98`},{reading:`R84`,pages:`176`},{reading:`R83`,pages:`168`},{reading:`R78`,pages:`149`},{reading:`R23a`,pages:`637`}],provenance:`mixed`},{id:`w12-measures`,kind:`worked-example`,title:`Worked example (c): MOE and MOP in the model, and where each is assessed`,paragraphs:[`Week 5 defined the measures and linked them: an MOE measures mission or user effectiveness, an MOP measures a system characteristic that contributes to an MOE, and a TPM is a tracked design parameter with a threshold and a margin (RB-4.1, the course definitions). In SysML v2 the library package ParametersOfInterestMetadata provides two semantic metadata definitions, #moe and #mop, each identifying an attribute usage as a measure of effectiveness or of performance (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 149, a Week 13 slide read ahead). It records nothing about what a measure measures, and it has no TPM metadata, so the reference adds two course conventions: a dependency tagged #measures, and a TPM attribute with threshold, objective, estimate and margin (section 5).`,`The listing aerolink_moe_mop.sysml shows the placement rule the reference uses. MOE-001 (line 24) is an attribute of the enterprise, AeroLinkEnterprise, because passenger wait is a property of the whole service. MOP-001 (line 32) is an attribute of Scheduling, the logical element whose behaviour it measures. Each measure is also the attribute that a requirement constrains: REQ-STK-001 reads enterprise.passengerWaitP90 (line 43), and REQ-SYS-005 asserts that its measured value, latencyActual, equals scheduling.assignmentLatencyP99 (line 50). VER-005 (line 55) passes its measured 99th percentile to REQ-SYS-005 in PassIf (line 65; Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 96–97), so the measure, the requirement and the verification refer to one feature, and the 60 s limit is written once. Two #measures dependencies (lines 72–73) record that MOP-001 measures REQ-SYS-005 and contributes to MOE-001. The checker accepted the file with no messages; whether an attribute marked #moe really measures effectiveness is a judgement that RB-4.1 grades.`,`RB-10.4 asks you to map each measure to the activity that assesses it. The rule follows from the V&V convention. An MOP with a requirement threshold is verified, by the VER that verifies that requirement. An MOE is validated, in operation or in an operationally realistic setting. A TPM is tracked by analysis until a verification replaces its estimate with a measurement: for REQ-SYS-001, VER-001’s maximum measured charge time replaces TPM-001’s estimate of 18 min (FICTIONAL).`],sysml:[{file:`week12/aerolink_moe_mop.sysml`,caption:`MOE-001 on the enterprise, MOP-001 on Scheduling, the requirements that read them, VER-005 calling REQ-SYS-005 in PassIf, and #measures dependencies (FICTIONAL values)`,intent:`conformant`}],table:{caption:`Measures mapped to V&V activities (reference IDs; RB-10.4)`,header:[`Measure`,`Owned by`,`Constrained by`,`Assessed by`],rows:[[`MOE-001 passenger wait P90`,`AeroLinkEnterprise`,`REQ-STK-001 (15 min)`,`Validation: analysis of operational booking and boarding data`],[`MOP-001 assignment latency P99`,`Scheduling (LOG-005)`,`REQ-SYS-005 (60 s)`,`Verification: VER-005 test; contributes to MOE-001`],[`MOP-002 charge time to dispatch`,`ChargingSystems (PHY-003)`,`REQ-SYS-001 (20 min)`,`Verification: VER-001 test; contributes to MOE-001`],[`TPM-001 charge time (estimate 18 min)`,`Measures package`,`Tracks REQ-SYS-001`,`Analysis until VER-001 measures it`]]},citations:[{reading:`R78`,pages:`149`},{reading:`R75`,pages:`96–97`}],provenance:`mixed`},{id:`w12-thread`,kind:`concept`,title:`The digital thread and the trace audit`,paragraphs:[`SEBoK describes digital engineering as computer-readable models of all aspects of a system, on shared data schemata, with MBSE as a subset. An ontology that defines the entities and the relationships between them is needed to link the models into a cohesive and useful digital thread, which would become the authoritative source of truth about the system data (SEBoK v2.14, “Digital Engineering”, p. 1394). AeroLink’s thread is small, but it works the same way. The course’s element kinds and ten link types are its ontology, and the required thread has 11 steps: stakeholder, need, capability, requirement, behaviour, logical element, physical element, information flow, verification, MOE/MOP and associated risk. What counts as each step is the course’s convention, stated in the explorer. The lab plan calls it the “11-link thread”: it has 11 elements, and its last three steps attach to earlier elements, not to their neighbour.`,`The audit turns the thread into numbers. The DoD Guidebook asks for bidirectional traceability, so that no approved change leaves an orphaned lower-level requirement and no higher-level requirement is a childless parent, one not addressed by lower-level requirements and system element designs (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 118). The audit applies that definition to REQ-STK and, as a course extension, to needs and capabilities. RB-9 sets the targets: upward trace to a need or capability and from needs to stakeholders (9.1); a satisfy and a verification method for every REQ-SYS (9.2); three complete threads shown live (9.3); reproducible coverage metrics, orphans and childless parents, and a disposition for each gap (9.4). “Reproducible” is the demanding word: someone else must reach the same numbers from the same model, so the report states the population, the counting rule for every number, and a digest of the model it counted. SEBoK gives the same advice for verification itself: end it on criteria such as coverage rates, not when the budget runs out (SEBoK v2.14, “System Verification”, p. 640).`,`Before you read worked example (d), predict the reference’s satisfy and verify coverage in the audit activity, then compute it.`],citations:[{reading:`R30`,pages:`1394`},{reading:`R45`,pages:`118`},{reading:`R23a`,pages:`640`}],provenance:`mixed`},{id:`w12-worked-audit`,kind:`worked-example`,title:`Worked example (d): auditing the reference and walking one thread hop by hop`,paragraphs:[`The instructor reference at Week 12 has 204 active elements and 381 links. All 20 requirements have a parent and reach a need or capability, and all 11 needs derive from a stakeholder. Satisfied: 12 of 20 (60 %), that is 10 of 10 REQ-SYS and 2 of 10 REQ-STK (REQ-STK-007 by PHY-002, REQ-STK-009 by the interface IF-003). Verified, meaning “has a VER”: 11 of 20 (55 %), that is 10 of 10 REQ-SYS and 1 of 10 REQ-STK (REQ-STK-007, by the inspection VER-011). RB-9.2 is at 100 %. There are no orphans. NEED-011 (disruption notice) is a childless need: CAP-005 meets it, but no requirement derives from it, the reference’s deliberate gap. There are 26 complete threads from 10 stakeholders; four stakeholders (STK-008, STK-011, STK-012, STK-013) have no need, so their threads stop at step 1.`,`Read the 55 % before you grade it. Under the course convention REQ-STK are verified too, and the reference records a method for every one of them: test for four, demonstration for three, analysis for two, inspection for one. Only REQ-STK-007 has a VER of its own. Eight of the other nine have a verified child requirement. That is evidence towards the parent, not proof: REQ-STK-005 allows 25 min from pad arrival to dispatch-ready, and VER-001, through REQ-SYS-001, times only the 20 min charge, not the 5 min of pad work. Counted through children, 9 of 10 REQ-STK have verification evidence. REQ-STK-009, the flight-intent exchange with the air navigation service provider, has none: it records demonstration but has no VER and no child, so the audit lists it as a gap for the lead, who owns the reference. Satisfaction needs a rule too: REQ-STK-009’s satisfier is an interface, a #satisfies dependency in the SysML model rather than a satisfy (README, section 5), so counting satisfy usages gives 10, not 12. Neither number is wrong; an unstated rule is.`,`The table walks demonstration thread 1, the charging thread, as the explorer shows it. At step 4, REQ-SYS-001 reaches CAP-003 through its parent REQ-STK-005, so this one step takes two links. Steps 9–11 do not continue from step 8: VER-001 verifies the requirement, MOP-002 measures the requirement, and R-001 affects the capability. The SysML column comes from the reference model’s mapping (README, section 4).`],table:{caption:`Thread 1 (reference), hop by hop: STK-005 > NEED-004 > CAP-003 > REQ-SYS-001 > FN-006 > LOG-002 > PHY-003 > INFO-003 > VER-001 > MOP-002 > R-001`,header:[`Step`,`Element`,`Link (workspace)`,`In the SysML v0.4 model`],rows:[[`1 Stakeholder`,`STK-005 Vertiport Operators`,`—`,`part def; stakeholder usage`],[`2 Need`,`NEED-004 Pads not limited by turnaround`,`NEED-004 derives-from STK-005`,`stakeholder STK-005 in NEED-004`],[`3 Capability`,`CAP-003 Fleet charging management`,`CAP-003 derives-from NEED-004`,`#derivesFrom dependency`],[`4 Requirement`,`REQ-SYS-001 Charge to dispatch threshold in 20 min`,`REQ-SYS-001 derives-from REQ-STK-005 derives-from CAP-003`,`#derivation connection, then #derivesFrom dependency`],[`5 Function`,`FN-006 Charge aircraft`,`REQ-SYS-001 allocated-to FN-006`,`allocation … allocate`],[`6 Logical element`,`LOG-002 Fleet Management`,`LOG-002 performs FN-006`,`perform in LOG-002`],[`7 Physical element`,`PHY-003 Charging Systems`,`LOG-002 allocated-to PHY-003`,`allocation … allocate`],[`8 Information flow`,`INFO-003 Maintenance Data`,`PHY-003 flows-to INFO-003`,`item flow`],[`9 Verification`,`VER-001 Turnaround charge-time test`,`VER-001 verifies REQ-SYS-001`,`verify in the objective`],[`10 MOE/MOP`,`MOP-002 Charge time to dispatch threshold`,`MOP-002 measures REQ-SYS-001`,`#measures dependency`],[`11 Associated risk`,`R-001 Charging capacity lags fleet growth`,`R-001 affects CAP-003`,`R-001 metadata about CAP-003`]]},citations:[{reading:`R45`,pages:`118`}],provenance:`mixed`},{id:`w12-worked-rids`,kind:`worked-example`,title:`Worked example (e): dispositioning the RIDs received on CP4`,paragraphs:[`The reviewers’ RIDs arrive in days 1–3. Every one of them needs a disposition before CP5: “every CP4 RID has a disposition” is an entry criterion of the final review, and RB-11.6 scores whether peer findings were dispositioned. The course form (a convention, not a source rule) has four outcomes. Accept: the fix is made. Accept with modification: the fix differs, and you say why. Reject: the RID names no real defect or misreads its criterion, and you cite what shows it. Defer: the fix comes later, with a checkpoint, an owner and a tracking item. An accepted RID is closed by evidence, not by a promise: the element changed, and the checker run, audit number, link ID or verdict that shows the fix is in. SEBoK lists issue reports and change requests on the design among the outputs of verification (SEBoK v2.14, “System Verification”, p. 638); a RID log is the review’s version.`,`Team Kestrel (FICTIONAL) received five RIDs from Team T4. RID-T4-01 (major) found satisfy 'REQ-SYS-001' by PHY-003 asserted although PHY-003 binds 24 [min]. The team removed the satisfy, recorded the gap as in Week 10, and closed the RID with “Checker run after the change: 0 errors, 0 warnings. Audit: REQ-SYS satisfied 9 of 10.” RID-T4-02 (major) read RB-9.2 as requiring a VER on REQ-STK-004. The team rejected it: RB-9.2 counts REQ-SYS, and two requirements derived from REQ-STK-004 are verified (VER-006, VER-007). Because the RID was major, the instructor confirmed the rejection, and the log says so. RID-T4-03 (a reversed connect line in IF-010, also in IF-013) was accepted with modification; RID-T4-04 (minor, no A3 branch in SCN-005) was deferred to the CP5 submission with an owner and an @Issue. The log checks the form of each entry, not whether the decision is right.`],citations:[{reading:`R23a`,pages:`638`}],provenance:`mixed`},{id:`w12-advanced`,kind:`advanced`,title:`Advanced analysis: complete is not correct, inconclusive is honest, and the sources draw the line differently`,paragraphs:[`A complete thread is complete by a rule. The explorer counts the PHY-004 variant of thread 1 as complete: STK-005 > … > REQ-SYS-001 > FN-006 > LOG-002 > PHY-004 > INFO-001 > VER-001 > MOP-002 > R-001. LOG-002 is allocated to the operations centre as well as to the chargers, and the rule then picks an information item linked to PHY-004, here INFO-001, passenger information. Every hop exists, but a charge-time requirement now reaches a passenger-information step. And all ten REQ-SYS can pass verification while MOE-001 fails in service. The digital thread would be the authoritative source of truth (SEBoK v2.14, “Digital Engineering”, p. 1394); it follows, by the instructor’s reasoning, that it is only as true as its links, and a weak hop is the first thing a panel will question (RB-9.3).`,`Inconclusive is a result, not a failure to report one. VER-004 cannot reach pass or fail while TBD-01 is open: correct holds at a placeholder limit show that the logic works, but say nothing about the approved limit. OMG SysML v2.1 Beta 2, Part 1 separates the outcomes precisely: inconclusive means no determination could be made, and error means the performance of the verification went wrong (OMG SysML v2.1 Beta 2, Part 1, p. 173). The DoD Guidebook adds that each design change must be assessed against the qualified baseline and may require parts of the verification to be repeated (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150). A verdict is therefore tied to a configuration, which Week 13’s impact analysis will use.`,`The sources do not draw the V&V line in the same place. MITRE verifies against the requirements of the previous phase and validates against the customer’s operational need (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433). DoD verifies against the specification and baselines but validates against stakeholder performance requirements in the operational environment (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150). SEBoK’s System Verification article says that verification detects faults while validation “provide[s] evidence for the satisfaction of (system and/or stakeholder) requirements” (SEBoK v2.14, “System Verification”, p. 634, p.639), and its System Validation article (extension reading) compares verification with the system design and validation with the system and stakeholder requirements (SEBoK v2.14, “System Validation”, p. 648). So DoD and SEBoK put stakeholder requirements on the validation side; MITRE and the course put them on the verification side and keep validation for the need. These are differences of baseline, not mistakes; merging them produces the confusion SEBoK lists as its first pitfall, the wrong baseline for the activity (SEBoK v2.14, “System Verification”, p. 640). Name the course convention in your V&V table, and say which baseline a cited source uses.`],citations:[{reading:`R30`,pages:`1394`},{reading:`R84`,pages:`173`},{reading:`R49`,pages:`149–150`},{reading:`R58`,pages:`433`},{reading:`R23a`,pages:`634`},{reading:`R23a`,pages:`639–640`},{reading:`R23b`,pages:`648`}],provenance:`mixed`},{id:`w12-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`Two practices from the sources map onto this week’s artefacts (instructor application; the practices are cited). First, the verification matrix. In DoD programs it is produced during requirements analysis and becomes part of the functional and allocated baselines (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149); SEBoK lists the same matrix, with the action, the element, the technique, the expected and the obtained result, among the artefacts of verification (SEBoK v2.14, “System Verification”, p. 638). In a model-based program the matrix is a view of the verification cases, not a spreadsheet that drifts. Second, the review record. Verification activities and results are documented for the functional configuration audit and the system verification review (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150). Your L12 audit report and RID log are small versions of that record, and the CP5 panel will read them.`],citations:[{reading:`R49`,pages:`149–150`},{reading:`R23a`,pages:`638`}],provenance:`mixed`},{id:`w12-lab`,kind:`lab`,title:`Lab L12 — verification and thread audit (model v0.4)`,paragraphs:[`Start from your CP4 model, its checker log and the RIDs you received. In class you triage the RIDs, plan three verification cases and model one, and run the first audit. Out of class you model the other cases, add the MOEs and the MOPs of the verified requirements, disposition every RID, finish the behaviour for CP5 and complete the audit report with three threads. Every case is checked with the checker, and every audit number states its counting rule.`],citations:[],provenance:`instructor-authored`},{id:`w12-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: L12 model v0.4 with checker log, V&V table, audit report (with thread table and gap dispositions) and the RID disposition log, end of Week 12. L12 is formative now. It is assessed summatively in CP5 (Week 14; 14 % of the course grade: RB-8 25 · RB-9 30 · RB-10 15 · RB-11 30), where a disposition for every CP4 RID and the trace audit are entry criteria and RB-11.6 scores the dispositions. The RIDs you write on another team’s model (days 1–3) count under RB-17 in CP4. Individual: readiness quiz Q11 and a review-notebook entry with a time log; graduate students may add the optional model-credibility argument.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w12-act-planner`,title:`Verification planner`,component:`w12-ver-planner`,purpose:`Plan VER items (method, objective, subject, level, environment, success criterion, verdict logic) for your requirements and save them to the workspace with owner and provenance; cited checks flag untestable criteria, limits and verdict thresholds that differ from the requirement, reversed comparisons, subjects that are not the requirement’s satisfier, and method–requirement mismatches.`,instructions:[`Enter your initials and provenance; tick the practice box to try the reference requirements first (nothing is saved).`,`Plan one VER for each of three requirements with at least two different methods; clear every ✗ and answer every ? in your V&V table. This is L12 work, done in class (see the lab).`,`Compare with the reference VER where one exists, then model each saved plan as a SysML verification case and run the checker.`],objectives:[`B12.1`,`B12.2`],inBlock:`w12-worked-methods`},{id:`w12-act-audit`,title:`Trace audit: coverage, orphans and childless parents`,component:`w12-trace-audit`,purpose:`Predict, then compute parent, satisfy and verify coverage (all, REQ-STK, REQ-SYS), RB-9.1/9.2 measures, orphans, childless parents (OUSD(R&E) Systems Engineering Guidebook, “Requirements Management Process”, p. 118, and needs by course extension), stakeholder requirements without verification evidence and complete threads; record a disposition per gap and export a reproducible report with the counting rules, a per-requirement table and a digest of the model counted.`,instructions:[`Choose the reference (practice) or your workspace model; predict % satisfied and % verified before computing.`,`Read each gap; write its disposition (action and owner, or why it is accepted and where it is tracked).`,`Copy the Markdown report, with the counting rules and the digest, into your L12 audit report.`],objectives:[`B12.4`],inBlock:`w12-thread`},{id:`w12-act-threads`,title:`Digital-thread explorer`,component:`w12-thread-explorer`,purpose:`Pick a stakeholder and see every thread with the step reached and the missing link named; walk a complete thread hop by hop with the links that justify each step.`,instructions:[`Explore STK-005 in the reference and walk thread 1; then switch to your workspace.`,`For each incomplete thread you need, decide whether the missing link is a real gap in the model or a link nobody recorded; never add a link that is not true.`,`Walk your three complete threads and check that every hop means what a reviewer would expect.`],objectives:[`B12.4`],inBlock:`w12-worked-audit`},{id:`w12-act-dispositions`,title:`RID disposition log`,component:`w12-rid-dispositions`,purpose:`Record a disposition for every RID received on CP4 — accept, accept with modification, reject or defer — with the reason, the fix reference and the closure evidence, with owner and provenance; screens reject promises as closure evidence, uncited or unconfirmed rejections and conditional deferrals; export the log.`,instructions:[`Enter how many RIDs your team received, your initials and provenance.`,`Log each RID as received, choose the disposition and clear every screen message. This is the L12 disposition log.`,`Compare with the worked log after two entries; export the table for L12.`],objectives:[`B12.5`],inBlock:`w12-worked-rids`}],lab:{id:`L12`,title:`Verification and thread audit (model v0.4); RID dispositions`,setting:`team`,durationMinutes:75,objectives:[`B12.1`,`B12.2`,`B12.3`,`B12.4`,`B12.5`],inputs:[`CP4 model (v0.3 with the L11 behaviour draft), its checker log and the workspace model`,`RIDs received from the peer team (two teams under the k+2 rule) and the instructor (Week 12, days 1–3)`,`CP2 requirements with recorded methods; Week 5 MOE, MOP and TPM set`,`Listings of worked examples (b) and (c) in sysml/week12; the instructor reference v0.4 (sysml/reference/aerolink_v04_full.sysml) as recovery input`,`This week’s four activities`],steps:[{title:`Days 1–3 — review another team’s CP4 model (Week 11 assignment)`,detail:`Read your assigned team’s CP4 model and checker log, and write and screen at least five RIDs in the RID writer’s Week 12 list (not the practice list), due at the end of day 3. If that team’s CP4 is missing, review team k+2 (Week 11 missing-CP4 rule). The RIDs are scored under RB-17 in your CP4 grade and budgeted in this week’s hours (≈ 1.5 h per student).`},{title:`Before class — triage the RIDs you received`,detail:`Read every RID received. Mark each as likely accept, modify, reject or defer, and assign an owner, normally the owner of the element named in the RID. Bring the list and the questions you need to ask the reviewers.`},{title:`In class — brief (5 min)`,detail:`Deliverables; the L12 minimums (≥ 3 verification cases; every MOE and the MOPs of the verified requirements in the model; reproducible audit; ≥ 3 complete threads; every RID dispositioned); the counting rules.`},{title:`In class — verification cases (25 min)`,detail:`Choose at least three requirements, at least two of them REQ-SYS, using at least two different methods. Plan all three in the planner and clear every ✗. Then model one as a verification case in class: @VerificationMethod, a subject whose definition is the requirement’s subject, an objective with doc and verify, recorded-result attributes, and verdict logic that returns pass, fail and inconclusive (and error if you compute it), calling the requirement in PassIf. Run the checker. Model the other two out of class.`},{title:`In class — measures and audit (15 min)`,detail:`Mark the MOE attributes on the enterprise (#moe) and the MOP attributes on the definitions whose values they measure (#mop), starting with the MOPs of the requirements you verify. Tie each to the requirement that constrains it, and add the #measures dependencies. Run the audit on your workspace and write the first gap dispositions.`},{title:`In class — threads (10 min)`,detail:`Use the explorer to find three complete threads from at least two stakeholders, walk each hop by hop, and note every hop that is complete by the rule but weak in meaning.`},{title:`In class — RID dispositions (15 min)`,detail:`Agree the dispositions of the major RIDs as a team. Make or schedule each fix, and ask the reviewer or the instructor to confirm any major RID you intend to reject.`},{title:`Lab record (5 min in class; final run out of class)`,detail:`Out of class: the other two verification cases, the remaining measures, the accepted RID fixes with a checker run after each, the behaviour finalised for CP5 (L11 feedback and behaviour RIDs applied; workload-pilot trigger: action flow only), the audit report and the disposition log. Record model v0.4 and the checker log (zero errors; each warning explained), the V&V table, the audit report with thread table and gap dispositions, and the disposition log in the team repository.`}],artefacts:[{idPrefix:`VER`,description:`Verification cases in the model, each with method, subject, objective with verify and verdict logic, and the matching workspace VER items with owner and provenance`,minimum:`≥ 3 requirements verified, ≥ 2 methods; every case accepted by the checker`},{idPrefix:`MOE / MOP`,description:`#moe and #mop attributes on their owning definitions, each constrained by a requirement or measuring one (#measures); the V&V table maps each to the activity that assesses it`,minimum:`Every MOE of the Week 5 set and the MOP of every requirement with a verification case; each such MOP is the attribute its requirement constrains`},{idPrefix:`Audit report`,description:`Coverage (parent, satisfy, verify) for all REQ, REQ-STK and REQ-SYS; RB-9.1 and 9.2 measures; orphans; childless parents; stakeholder requirements without verification evidence; counting rules and model digest; a disposition for every gap; thread table`,minimum:`Numbers reproducible from the model by the stated rules; ≥ 3 complete 11-step threads, each walked hop by hop`},{idPrefix:`RID-<team>-nn dispositions`,description:`Disposition log: RID, severity, summary, disposition, reason, change (fix reference), closure evidence, owner`,minimum:`Every RID received has a disposition; every accepted RID has a change made and evidence of a run; every rejection cites a criterion or source`}],continuity:`Model v0.4 is the CP5 model without the impact analysis: the behaviour is finalised this week, as the weekly plan sets out. In Week 13 the impact analysis traverses the same links the audit counted. Every verdict is tied to the configuration it was obtained on, so a change re-opens the verification cases it reaches (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150). The three threads walked here are the ones demonstrated live at CP5 (RB-9.3), and the disposition log is a CP5 entry criterion scored by RB-11.6. Gaps and RIDs deferred today must be closed, or carried as risks, by the CP5 submission.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`L12`,title:`L12 model v0.4, V&V table, audit report, RID disposition log; optional graduate model-credibility argument`,mode:`team`,due:`Model v0.4, V&V table, audit report and disposition log: end of Week 12 (they carry into CP5, due Week 14). RIDs on the assigned team’s CP4 model: end of day 3 of Week 12 (Week 11 assignment). Optional graduate argument: end of Week 12.`,weight:`L12 is formative: feedback now on RB-9, RB-10 and the disposition log, with summative assessment in CP5 (14 % of the course grade: RB-8 25 · RB-9 30 · RB-10 15 · RB-11 30; RB-11.6 scores the dispositions). Optional graduate argument: review notebook (RB-16, 5 %), read when submitted.`,instructions:[`Build model v0.4 as in lab L12 and check it with the course-designated checker until it reports zero errors; explain every warning.`,`Complete the V&V table, the audit report (from the audit activity, with your counting rules, digest and a disposition for every gap) and the thread table for three complete threads.`,`Disposition every RID your team received; make the accepted fixes, run the checker after them, and record the evidence.`,`Finalise the behaviour for CP5: apply the L11 feedback and the behaviour fixes from the RIDs, then run the checker.`,`Review your verification cases against the silent passes of worked example (b): subject conformance, verdict type and logic, the requirement called in PassIf with the measured value, objective with verify (not satisfy).`,`Graduate students (optional extension this week): the model-credibility argument (template section 6).`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Model v0.4 and checker log (RB-8.1)`,guidance:`The .sysml file and the checker output for the whole file after the last change. Zero errors; for each warning, the line, the message and the fix or the reason it is acceptable.`},{heading:`2. V&V table (RB-10.1, 10.2, 10.4; B12.1, B12.3)`,guidance:`One row per requirement and per MOE: V or V; method and activity ID; level and environment; the reason for the method (cite OUSD(R&E) Systems Engineering Guidebook, “Verification Process” or SEBoK v2.14, “System Verification”); for measures, the activity that assesses them. Name the convention you use for verification and validation (the course convention, following MITRE p.433; DoD p.150 and SEBoK validate against stakeholder requirements).`},{heading:`3. Verification cases (RB-10.3; B12.2)`,guidance:`For each of ≥ 3 cases: the requirement, subject, objective, method, success criterion and verdict logic (pass, fail, inconclusive; error if computed), with the listing lines. State what the checker does not check in your case and how you checked it yourself.`},{heading:`4. Trace audit and threads (RB-9.1–9.4; B12.4)`,guidance:`The coverage table (all, REQ-STK, REQ-SYS) with the counting rules and the model digest; orphans and childless parents; stakeholder requirements without verification evidence; a disposition for every gap. The thread table: three complete threads, each walked hop by hop, with any weak hop named and its fix or reason.`},{heading:`5. RID disposition log (B12.5; RB-11.6 at CP5)`,guidance:`Every RID received: disposition, reason, change made (fix reference) and closure evidence (checker run with its counts, audit number, link ID or verdict); for every rejection the criterion or source, and for a major one who confirmed it; for every deferral the checkpoint, owner and tracking item.`},{heading:`6. Optional graduate extension: model-credibility argument (individual, ½–1 page)`,guidance:`Using The MITRE Systems Engineering Guide, “Verification and Validation of Simulation Models”, p. 475–477, 479 and 481: choose one analysis a verification case relies on — the energy model behind VER-003 (recommended), the availability analysis of VER-006, or the Week 1 dynamics model used for the capacity of REQ-STK-004. (a) State its intended use, in one sentence, and what it must predict. (b) Model validation: choose one method from The MITRE Systems Engineering Guide, “Verification and Validation of Simulation Models” Table 1, justify it for this use, and say what data it needs. (c) Set a quantitative validation requirement (a confidence interval width and level, or Type I and II risks), and state what you would report if the data cover only part of the range (partial validation). (d) Say what verdict the verification case may return until the model is accredited for this use.`},{heading:`7. AI usage statement (RB-12)`,guidance:`Tool, purpose, prompts, outputs and your evaluation. AI-generated SysML must be accepted by the checker and explained line by line by its owner. AI output is not evidence of what the checker accepts or of what a verdict is.`}],rubrics:[`RB-9`,`RB-10`,`RB-11`,`RB-17`,`RB-12`,`RB-16`],rubricScope:`L12 (formative now, summative in CP5): RB-9.1–9.4 on the audit report and threads (RB-9.5 is Week 13), RB-10.1–10.4 on the V&V table, the verification cases and the measures mapping. RID dispositions: RB-11.6 (review conduct: “peer findings dispositioned”) scores them at CP5, and every CP4 RID needs a disposition to enter the review. L12 feedback on the log is formative against RB-11.6, using the course form, which reads RB-17 from the owner’s side (17.1: a rejection shows that the RID misreads its criterion, with a citation; 17.3: an acceptance names the change made and its closure evidence). The RIDs the team gives on another model (days 1–3) are scored under RB-17 in CP4. Graduate model-credibility argument: optional this week under the course workload option B (graduate tasks in alternate weeks); when submitted it is read (RB-16 graduate-task rule), with formative feedback on RB-10.2 (is analysis by this model a justified method, at this level and in this environment?), informing RB-16.1. AI statement: RB-12.1–12.3.`,aiUse:`AI tools may explain checker messages, suggest SysML syntax, draft doc text or critique a disposition. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner (RB-12.3). AI output is never evidence of a verdict, of a coverage number or of what the checker accepts: only the model, a recorded run and the cited sources count. Dispositions and the graduate argument are the students’ own reasoning; tag any AI-suggested planner entry or disposition AI-suggested-reviewed.`,objectives:[`B12.1`,`B12.2`,`B12.3`,`B12.4`,`B12.5`]},quiz:[{id:`q12-1`,bloom:`Understand`,objective:`B12.1`,prompt:`Three AeroLink activities on noise: (i) 50 take-offs and landings measured at a pad edge against the 65 dBA limit; (ii) a three-month survey of residents near a spoke vertiport asking whether the operation is acceptable to live with; (iii) a check that the noise requirement is singular, unambiguous and verifiable. How are they classified?`,options:[{id:`a`,text:`All three are validation, because each of them gathers evidence about the same community concern, aircraft noise near the vertiports`,correct:!1,explanation:`The concern is the same, but the reference each one uses differs: a specified limit in (i), the stakeholders’ judgement in (ii), drafting characteristics in (iii) (SEBoK v2.14, “System Verification”, p. 635).`},{id:`b`,text:`(i) validation, because it happens at the real vertiports; (ii) verification, because the survey has a pass mark; (iii) validation of the requirement set`,correct:!1,explanation:`This reverses the terms: measuring against a specified limit is verification (“built right”), and assessing acceptability in service is validation (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150).`},{id:`c`,text:`Only (i) is V&V; (iii) is requirements management done before design starts, and (ii) is community relations rather than engineering evidence`,correct:!1,explanation:`Any engineering element can be verified, including a requirement (SEBoK v2.14, “System Verification”, p. 635), and (ii) is the kind of operational evidence validation relies on.`},{id:`d`,text:`(i) verification against the requirement; (ii) validation against the community’s need; (iii) verification of the requirement itself`,correct:!0,explanation:`Correct. (i) compares realised characteristics with the specified requirement; (ii) asks whether the service is right for its stakeholders in its operating environment, which needs a value judgement; and SEBoK lists checking a requirement against characteristics such as singular and verifiable as verifying that requirement (SEBoK v2.14, “System Verification”, p. 635–636).`}],cite:{reading:`R23a`,pages:`635–636`}},{id:`q12-2`,bloom:`Analyse`,objective:`B12.1`,prompt:`A team measures pad-edge LAmax on every movement in the first three months of revenue service and compares the results with REQ-STK-002 (every movement ≤ 65 dBA at the pad edge). One member files this under verification, another under validation. What should the team’s V&V table say?`,options:[{id:`a`,text:`Validation, because the data come from revenue service with real passengers, and every source treats evidence gathered in the operational environment as validation`,correct:!1,explanation:`Where the evidence is gathered does not decide it. Under the course convention the comparison with a specified REQ-STK limit is verification; and not every source agrees, which is the point of the item (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433; OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150).`},{id:`b`,text:`Neither: V&V both end at delivery, so a check made in revenue service is a post-delivery audit`,correct:!1,explanation:`MITRE describes V&V as integrated activities throughout the life cycle, not stages that end at delivery (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 434).`},{id:`c`,text:`Verification by the course convention, with the convention named, because DoD would call this validation`,correct:!0,explanation:`Correct. The course follows MITRE: verification compares with requirements set earlier, REQ-STK included; validation compares with the operational need (The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433). DoD validates against stakeholder performance requirements in the operational environment (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150), so a reader using DoD terms would file it the other way. Naming the convention removes the ambiguity (rule against merging the sources’ terms).`},{id:`d`,text:`Validation, because stakeholder requirements are validated against the MOEs by design, and only the system requirements are verified under the course convention`,correct:!1,explanation:`The course convention verifies REQ-STK as well as REQ-SYS. The reference records test as REQ-STK-002’s method, and no MOE measures a REQ-STK (worked example d).`}],cite:{reading:`R58`,pages:`433`}},{id:`q12-3`,bloom:`Analyse`,objective:`B12.1`,prompt:`A new FICTIONAL requirement: “The battery pack shall retain at least 80 % of its usable capacity after 2,000 charges at the turnaround charge rate.” Packs reach 2,000 charges after about three years of service. Which verification approach is best justified?`,options:[{id:`a`,text:`Accelerated cycling tests on sample packs under controlled conditions, analysed to 2,000 charges with the uncertainty stated; fleet data later`,correct:!0,explanation:`Correct. Test supplies quantitative data under controlled conditions, and analysis of test data is a recognised method where the full condition cannot be reached in time (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150; SEBoK v2.14, “System Verification”, p. 639). Fleet data later strengthens the evidence.`},{id:`b`,text:`Inspection of the supplier datasheet, which states a cycle life of 2,500 charges at a comparable charge rate, filed as the verification record for the pack`,correct:!1,explanation:`A datasheet claim is not evidence about this pack under this charge rate; inspection suits properties determined by observation, not degradation under load (SEBoK v2.14, “System Verification”, p. 639).`},{id:`c`,text:`A demonstration: charge one aircraft repeatedly and observe that it still flies the design trip`,correct:!1,explanation:`The criterion is a measured 80 % capacity, not an observable yes or no; DoD uses demonstration when quantitative assurance is not required (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149).`},{id:`d`,text:`Nothing until year 3, then analyse fleet data: only real operation is valid evidence`,correct:!1,explanation:`That defers the evidence past every decision it should inform; SEBoK advises starting verification early (SEBoK v2.14, “System Verification”, p. 640).`}],cite:{reading:`R49`,pages:`149–150`}},{id:`q12-4`,bloom:`Apply`,objective:`B12.2`,prompt:`In the course listing for VER-001 (verdict: error if the procedure was not followed; otherwise inconclusive if validCharges < plannedCharges; otherwise PassIf on REQ-SYS-001 with the largest measured charge time), a run records procedureFollowed = true, plannedCharges = 30, validCharges = 28 and maxMeasuredChargeTime = 19.2 [min]. What verdict does the case return, and what should the team do?`,options:[{id:`a`,text:`pass: every one of the 28 valid charges was within the 20 min limit, and two missing charges cannot change that`,correct:!1,explanation:`The pass branch is reached only when at least the planned number of valid charges exists; 28 < 30.`},{id:`b`,text:`inconclusive: 28 valid charges are fewer than the planned 30; run more valid charges before claiming a verdict`,correct:!0,explanation:`Correct. Inconclusive means a determination could not be made (OMG SysML v2.1 Beta 2, Part 1, p. 173), and the expression returns it before PassIf is evaluated. A smaller sample would have to be justified in the plan first.`},{id:`c`,text:`fail: two of the thirty planned charges are missing from the record, so the test did not meet its own plan and the requirement is not shown`,correct:!1,explanation:`Fail means the subject has been determined not to satisfy the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 173); missing data determines nothing.`},{id:`d`,text:`error: the procedure did not produce the 30 charges it planned, which is an error in the performance of the verification, so the run is repeated`,correct:!1,explanation:`The procedure was followed (procedureFollowed = true); error is for a verification whose performance went wrong (OMG SysML v2.1 Beta 2, Part 1, p. 173), not for a short sample.`}],cite:{reading:`R84`,pages:`173`}},{id:`q12-5`,bloom:`Evaluate`,objective:`B12.2`,prompt:`U-002 has closed and TBD-02 is signed at 400 kW (FICTIONAL). VER-010 is run at the hub. Afterwards the team finds that the power meter on IF-006 was set to the wrong current-transformer ratio, so every recorded value is off by an unknown factor. All recorded 1-minute averages are below 400 kW. The project manager proposes “inconclusive, because the data are uncertain”. Which verdict should the case return, and what next?`,options:[{id:`a`,text:`pass: every recorded 1-minute average is below the signed 400 kW limit, and the meter setting is a calibration matter for the next campaign`,correct:!1,explanation:`Values off by an unknown factor cannot show that the subject satisfies the requirement; recording pass claims a determination that was never made.`},{id:`b`,text:`inconclusive: the recorded values cannot be trusted, so no determination could be made; keep the data on file and re-run whenever the hub is free`,correct:!1,explanation:`Inconclusive fits a verification performed as planned that could not decide, such as an open TBD or a short sample. Here the performance itself went wrong, which OMG SysML v2.1 Beta 2, Part 1 calls error, and the course’s verdict logic ties error to instrumentation not executed as planned.`},{id:`c`,text:`fail: with the instrumentation set up wrongly, the requirement cannot be shown to be met, so it is not met`,correct:!1,explanation:`Fail is a determination that the subject does not satisfy the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 173); nothing about the chargers has been shown.`},{id:`d`,text:`error: the run was not performed as planned (wrong meter set-up); correct the meter and repeat VER-010`,correct:!0,explanation:`Correct. Error means an error occurred during the performance of the verification (OMG SysML v2.1 Beta 2, Part 1, p. 173); the course reads that as a procedure or instrumentation not executed as planned, which calls for a repeat run. TBD-02 is closed, so the old inconclusive condition no longer applies.`}],cite:{reading:`R84`,pages:`173`}},{id:`q12-6`,bloom:`Evaluate`,objective:`B12.2`,prompt:`In VER-002’s data, 6 of 50 pad-edge measurements were taken while a delivery truck idled nearby; for those 6, background noise is within 10 dB of the event. The 44 clean movements are all ≤ 65 dBA; one of the 6 contaminated readings shows 66 dBA. What should the analyse-and-evaluate steps conclude?`,options:[{id:`a`,text:`inconclusive: exclude the 6 contaminated readings in the analysis step; 44 valid of 50 planned; measure at least 6 more clean movements`,correct:!0,explanation:`Correct. A verification case collects data, analyses it and then evaluates it against the objective (OMG SysML v2.1 Beta 2, Part 1, p. 173–174); the analysis step decides which data are valid, and the planned sample size governs the verdict.`},{id:`b`,text:`fail: one reading exceeds 65 dBA, and a verification that observes any exceedance of the limit must return fail whatever the conditions of the measurement were`,correct:!1,explanation:`The 66 dBA reading is contaminated by background noise, so it does not show that the aircraft exceeded the limit.`},{id:`c`,text:`pass: discard the 6 and evaluate the 44 clean readings, all ≤ 65 dBA`,correct:!1,explanation:`Discarding is right, but 44 clean movements are fewer than the 50 the plan requires, so the evaluation cannot reach pass under the stated logic.`},{id:`d`,text:`error: the measurement environment was not controlled, so the run is an error`,correct:!1,explanation:`The procedure was carried out; some data are unusable. VER-002 names background noise as an inconclusive condition, an analysis outcome, not an error in performing the verification.`}],cite:{reading:`R84`,pages:`173–174`}},{id:`q12-7`,bloom:`Apply`,objective:`B12.3`,prompt:`A team writes #moe attribute chargerUtilisation : Real; inside ChargingSystems, and #mop attribute passengerSatisfaction : Real; inside AeroLinkEnterprise. The checker accepts both. What is the problem?`,options:[{id:`a`,text:`None: the checker accepted both, so the classification is right`,correct:!1,explanation:`The library marks a usage as an MOE or MOP (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 149); the checker cannot judge whether the marking is right.`},{id:`b`,text:`#moe and #mop may annotate only requirement usages, so both attributes must be rewritten as requirements that carry the metadata instead`,correct:!1,explanation:`The metadata identifies an attribute as a measure (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 149); a course probe of #moe on a requirement was rejected by the checker.`},{id:`c`,text:`The labels are reversed: passenger satisfaction is a user-effectiveness MOE; charger utilisation is a system-characteristic MOP`,correct:!0,explanation:`Correct. An MOE measures mission or user effectiveness and an MOP a system characteristic that may contribute to an MOE (RB-4.1, the course definitions); #moe and #mop only label the usage (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 149).`},{id:`d`,text:`An MOE must always be a time quantity, such as a DurationValue`,correct:!1,explanation:`Measures can be any quantity; MOE-003 in the reference is a fraction.`}],cite:{reading:`R78`,pages:`149`}},{id:`q12-8`,bloom:`Apply`,objective:`B12.3`,prompt:`A team’s REQ-SYS-008 constrains maintenance.noGoFlagLatency <= maxFlagLatency. Its VER-008 declares attribute <'MOP-007'> measuredFlagTime with #mop inside the verification case, and the verdict is PassIf(measuredFlagTime >= Requirements::'REQ-SYS-008'.maxFlagLatency). The checker reports nothing. What should change?`,options:[{id:`a`,text:`Nothing needs to change: a #measures dependency from MOP-007 to REQ-SYS-008 would already state that the case’s attribute is the quantity the requirement constrains`,correct:!1,explanation:`A #measures dependency is traceability only; nothing in it says that measuredFlagTime and noGoFlagLatency are the same quantity, and it would not catch the reversed comparison.`},{id:`b`,text:`MOP-007 should be #moe, because a late no-go flag affects safety`,correct:!1,explanation:`Flag latency is a system characteristic; its contribution to safety is through MOE-004, which it measures.`},{id:`c`,text:`MOPs may not be declared inside a verification case or used in one, so the case has to be deleted and VER-008 recorded only as a workspace item`,correct:!1,explanation:`Verifying an MOP against its requirement’s threshold is exactly how MOPs are assessed (RB-10.4); the problem is where the MOP lives and how the case compares it.`},{id:`d`,text:`Pass the measured value to REQ-SYS-008 as an in parameter tied to noGoFlagLatency, and call the requirement in PassIf`,correct:!0,explanation:`Correct. The comparison is reversed (>= for a maximum), which the checker cannot see, and the measured value is never tied to the constrained attribute. With Seidewitz, Intro to the SysML v2 Language: Textual Notation’s pattern the requirement asserts that its in parameter equals the subject’s feature, and PassIf checks the requirement for the measured value, so the comparison is written once (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 96–97). The MOP then belongs on the definition whose value it measures (course convention).`}],cite:{reading:`R75`,pages:`96–97`}},{id:`q12-9`,bloom:`Evaluate`,objective:`B12.4`,prompt:`A team’s audit reports: parent 100 %, satisfied 100 %, verified 100 %, no orphans, no childless parents, five complete threads. Every VER in the model is planned and none has been run. The team concludes: “The design is verified.” What is the best evaluation?`,options:[{id:`a`,text:`Agree: 100 % verified coverage with no orphans and no childless parents is exactly what RB-9 asks for, so the design can be called verified`,correct:!1,explanation:`The audit counts verifies links, that is planned activities; none has produced evidence.`},{id:`b`,text:`Disagree: the audit shows planned verification activities, not verdicts; report the verification status separately`,correct:!0,explanation:`Correct. Verification is confirmation through objective evidence (SEBoK v2.14, “System Verification”, p. 634); the results must be obtained and compared with the expected results before a status is recorded (SEBoK v2.14, “System Verification”, p. 638). Coverage of links is a different number.`},{id:`c`,text:`Disagree: an audit with no gaps at all is statistically implausible for a model of this size and probably hides a counting error somewhere`,correct:!1,explanation:`Full coverage is possible and is RB-9’s target; the problem is what the number is claimed to mean.`},{id:`d`,text:`Agree, provided the checker reports zero errors on the model, because the checker evaluates the verification cases when it validates the file`,correct:!1,explanation:`The checker evaluates no verdicts or constraints; zero errors says nothing about verification results.`}],cite:{reading:`R23a`,pages:`634`}},{id:`q12-10`,bloom:`Analyse`,objective:`B12.4`,prompt:`In a team model, the thread STK-006 > NEED-006 > CAP-009 > REQ-SYS-009 > FN-010 > LOG-007 > PHY-008 stops at step 7: “No information item flows to or from this physical element.” PHY-008 sends the fire alarm to the emergency services dispatch centre over IF-007. What is the right fix?`,options:[{id:`a`,text:`Model the alarm message as a new INFO item flowing from PHY-008 over IF-007, the exchange REQ-SYS-009 constrains`,correct:!0,explanation:`Correct. The missing link points at a real gap: the alarm exchange exists but is not represented. SEBoK calls for an ontology that links the models in a cohesive and useful manner (SEBoK v2.14, “Digital Engineering”, p. 1394); that a thread is only useful if its links are the real ones is the instructor’s reasoning from that page.`},{id:`b`,text:`Add a flows-to link from PHY-008 to INFO-001 (passenger information), the only information item in the model, so that the thread completes today`,correct:!1,explanation:`The link would be false: PHY-008 does not produce passenger information. The thread would count as complete but make the trace lie.`},{id:`c`,text:`Choose another stakeholder whose thread is already complete, because CP5 asks for three complete threads and this one is not needed for that count`,correct:!1,explanation:`This may meet the count of three threads, but it leaves a real gap in the fire-safety thread undisposed (RB-9.4).`},{id:`d`,text:`Add a VER for REQ-SYS-009 first; the explorer will then skip the missing information step and carry on from step 9`,correct:!1,explanation:`Steps are not skipped: the thread needs an information step before verification is considered.`}],cite:{reading:`R30`,pages:`1394`}},{id:`q12-11`,bloom:`Apply`,objective:`B12.4`,prompt:`A team model has 16 requirements (8 REQ-STK, 8 REQ-SYS). All 8 REQ-SYS and 2 REQ-STK have a verifies link. One team member reports “62.5 % verified”, another “100 % verified”. Which statement is right?`,options:[{id:`a`,text:`Only 62.5 % is right, because any figure that leaves out the stakeholder requirements hides gaps and cannot be used for RB-9 at all`,correct:!1,explanation:`The REQ-SYS figure is what RB-9.2 asks for; neither figure is wrong if its population is stated.`},{id:`b`,text:`Only 100 % is right, because stakeholder requirements are never verified: under the course convention they are validated against the MOEs`,correct:!1,explanation:`The course convention verifies REQ-STK too; the reference has VER-011 on REQ-STK-007 and records test, demonstration or analysis for the others. Whether a REQ-STK also counts through its verified children is a rule you state.`},{id:`c`,text:`Both, for different populations: 10 of 16 requirements, or 8 of 8 REQ-SYS; state the population and the rule`,correct:!0,explanation:`Correct. 10/16 = 62.5 %; 8/8 = 100 %. A coverage rate is only useful as an end criterion when its definition is stated (SEBoK v2.14, “System Verification”, p. 640); RB-9.4 asks for reproducible metrics.`},{id:`d`,text:`50 %, that is 8 of 16 verified requirements`,correct:!1,explanation:`Any requirement usage can be verified; the two verified REQ-STK count in the all-requirements figure.`}],cite:{reading:`R23a`,pages:`640`}},{id:`q12-12`,bloom:`Evaluate`,objective:`B12.5`,prompt:`Your team receives: “RID-T2-03 | major | VER-006 records pass for REQ-SYS-006 (availability ≥ 90 % in each month) after one month of trial-operation records, but its criterion asks for three consecutive months.” A teammate drafts: “Reject, citing SEBoK v2.14, “System Verification”, p. 639: analysis is a recognised method where testing is not cost-effective.” Which disposition is best?`,options:[{id:`a`,text:`The drafted rejection: analysis is a recognised verification method where testing to realistic conditions is not cost-effective, so the RID misreads the method`,correct:!1,explanation:`The RID does not dispute the method; it says the recorded verdict claims more than the data support. A rejection has to show that the RID misreads its criterion, and this one reads VER-006’s criterion correctly.`},{id:`b`,text:`Accept: one month cannot meet a three-month criterion; record VER-006 as inconclusive until three months of records exist, with a checker run`,correct:!0,explanation:`Correct. The RID names a real defect: pass claims a determination the data cannot make, so the honest verdict is inconclusive (OMG SysML v2.1 Beta 2, Part 1, p. 173) until the criterion’s three months exist. The closure evidence is the changed verdict and a checker run (SEBoK v2.14, “System Verification”, p. 638).`},{id:`c`,text:`Defer to the CP5 submission: by then three months of data will exist and the verdict will be pass anyway, so nothing in the model needs to change now`,correct:!1,explanation:`A deferral is for a valid fix made later; this one changes nothing and assumes the outcome, while the model keeps an unsupported pass.`},{id:`d`,text:`Reject without comment: the reviewer has misunderstood analysis`,correct:!1,explanation:`A disposition without a reason or citation cannot be checked by the reviewer or the panel, and this RID is right.`}],cite:{reading:`R84`,pages:`173`}},{id:`q12-13`,bloom:`Evaluate`,objective:`B12.5`,prompt:`Your team receives RID-T1-02 (major, traceability): “In SCN-004, AI-001’s prediction withdraws an aircraft from service with no technician decision step, contrary to AI-001’s own human-oversight statement (a certifying technician decides every withdrawal).” The team agrees, but proposes: “Defer — to be handled in the autonomy evolution increment after the course.” What should the log say?`,options:[{id:`a`,text:`Keep the proposed deferral: autonomy belongs to the evolution increment after the course, and the human-oversight statement can be revised at that time as well`,correct:!1,explanation:`Under the course severity scale a major RID is fixed by the CP5 submission (Week 11); a deferral past CP5 leaves a known inconsistency in the model the panel will review.`},{id:`b`,text:`Reject: AI oversight is taught at awareness level in this course, so a missing technician step is outside the CP4 review scope and need not be fixed`,correct:!1,explanation:`The RID names a real contradiction between the model’s flow and its own AI-001 statement; a rejection has to show the RID misreads its criterion, and this one does not.`},{id:`c`,text:`Accept, noted for later: the team agrees with the reviewer, and the log records that agreement so that the panel can see the finding was taken seriously`,correct:!1,explanation:`No change, no owner, no evidence and no checkpoint: the reviewer cannot tell whether the defect will ever be fixed.`},{id:`d`,text:`Accept, with an owner: add the technician’s decision step to SCN-004 and record a checker run; if not this week, defer it to the CP5 submission with an @Issue`,correct:!0,explanation:`Correct. The disposition names the change (a decision step performed by a person, not AI-001), the owner and the evidence, and keeps a major finding inside the CP5 window; SEBoK records such outcomes as issue reports and change requests on the design (SEBoK v2.14, “System Verification”, p. 638).`}],cite:{reading:`R23a`,pages:`638`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (2 × 75 min: concept studio; lab L12)`,hours:2.5},{activity:`Core readings, narrowed to the pages the lesson depends on: Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Analysis Case Definitions” (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 96–99), OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 149–150, The MITRE Systems Engineering Guide, “Verification and Validation”, p. 433–434, SEBoK v2.14, “System Verification”, p. 634–640, SEBoK v2.14, “Digital Engineering”, p. 1394 (12 pp + 4 slides at ≈ 15 pp/h, 30 sl/h)`,hours:.9},{activity:`OMG SysML v2.1 Beta 2, Part 1 extract p.173–176 (OMG SysML v2.1 Beta 2, Part 1, “7.23 Analysis Cases”, §7.24 Verification Cases, a Week 12 reading; 4 pp at ≈ 15 pp/h) and Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Standard View Definitions and Domain Libraries (metadata, analysis, cause and effect, requirements derivation)”, slide 149 (one Week 13 slide read ahead)`,hours:.3},{activity:`Online lesson (≈ 4,900 words), thread explorer and trace-audit practice (planner and disposition log are used inside L12)`,hours:1},{activity:`Readiness quiz Q11 / knowledge check (13 items)`,hours:.3},{activity:`RIDs on the assigned team’s CP4 model (Week 12 days 1–3): read the model and its checker log, write and screen ≥ 5 RIDs in the RID writer’s Week 12 list (individual share of the team set)`,hours:1.5},{activity:`L12 out of class: two more verification cases, measures, V&V table, audit report, threads, RID disposition log and the accepted RID fixes with checker runs (team share)`,hours:3},{activity:`Behaviour finalisation for CP5: L11 feedback and behaviour RIDs applied, checker run (team share; workload-pilot trigger: action flow only)`,hours:.3},{activity:`Review notebook entry, time log and AI statement`,hours:.2}],references:[{reading:`R84`,pages:`173–176`},{reading:`R83`,pages:`168`},{reading:`R78`,pages:`149`},{reading:`R45`,pages:`118`},{reading:`R58`,pages:`437`},{reading:`R23b`,pages:`646–648`},{reading:`R64`,pages:`475–483`}],review:{status:`self-checked`,openIssues:[]}},D=e({default:()=>O}),O={week:13,drivingQuestion:`The city wants faster turnarounds and the battery supplier revises its fade data. Starting from one changed number, can you show from the model — not from memory — what else must be re-examined, which margins break, which verdicts no longer hold and which risks re-open, and can you tell a model that merely parses from one that is consistent?`,blocks:[{id:`w13-outcomes`,kind:`outcomes`,title:`Learning outcomes for this week`,paragraphs:[`This week contributes to B-CLO5 (use model-based traceability to analyse change), B-CLO4 (model correctly in SysML v2) and B-CLO3 (risk). Your model v0.4 now holds requirements, design, verification, measures and risks joined by links. This week you use those links to answer an engineering question: if one value changes, what else must be re-examined, which margins break, which verdicts no longer hold and which risks re-open? You also learn to tell a model that parses from a model that is consistent, and to record risk and cause–effect with the library metadata. Session 2 is Exam 2, a practical model examination (RB-14), whose T4 task is exactly this week’s impact analysis. The L13 impact report and its decision record feed CP5.`],bullets:[`B13.1 (Analyse) Determine the impact set of a proposed change by traversing the model’s relationships, show the method, and separate first-order from second-order effects.`,`B13.2 (Evaluate) Check model consistency and distinguish “the checker accepts it” from “it is consistent” and from “it is correct”.`,`B13.3 (Apply) Represent a risk with the library Risk metadata and its cause–effect chain with causation connections.`,`B13.4 (Understand) Explain resilience (avoid, withstand, recover) and the verification and validation challenges of AI-enabled functions, for the change you analyse.`,`Graduate task (required this week): commit-based change analysis with the Systems Modeling API versioning model (OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”).`],citations:[],provenance:`instructor-authored`},{id:`w13-intuition`,kind:`intuition`,title:`Intuition: one number, five places`,paragraphs:[`A building services engineer is told that the fire code now requires a 90 s alarm instead of 120 s. She changes the number in the specification. Three months later the commissioning test passes against the old 120 s procedure, the sensor supplier’s margin calculation still uses 120 s, and nobody re-assessed the evacuation risk. Nothing was hidden: every one of those documents named the alarm requirement. What was missing was a method that, starting from the changed number, walked to every place that depended on it and asked a specific question there.`,`A model makes that walk mechanical, but not automatic. AeroLink’s REQ-SYS-001 is linked to a charger that satisfies it, a test that verifies it, a TPM that tracks it, a parent it derives from and the risks about it. Each link tells you what kind of question to ask. Some answers are “still fine”, and the walk stops there; some are “this must change too”, and the walk continues. This week turns that judgement into a repeatable method, and shows what the checker can and cannot tell you along the way.`],citations:[],provenance:`instructor-authored`},{id:`w13-analysis`,kind:`concept`,title:`Analysis cases and calculations in SysML v2`,paragraphs:[`An analysis case definition defines how the result of analysing some subject is computed, to meet an objective. The subject is declared as for a requirement, the result is declared as a return result, as for a calculation definition, and the objective is a requirement on the result of the analysis, which may contain assumed and required constraints (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 92). The steps of an analysis case are actions that together compute the result; Seidewitz, Intro to the SysML v2 Language: Textual Notation’s example first solves for the power needed on a scenario and then computes fuel economy from that power profile, and further parameters can be declared in the case body (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 93). A usage carries out the analysis for a specific configuration: the subject and parameters are redefined automatically, and if the configuration’s attribute is set to the analysis result, the configuration is asserted to satisfy the requirement (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 94).`,`A trade-off study is an analysis whose objective is to select the best alternative from a set. The TradeStudies library provides a TradeStudy analysis definition: bind its subject to the alternatives, choose MinimizeObjective or MaximizeObjective, and redefine the evaluation function that scores each alternative (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 95). The library defines the objective as a requirement that the selected alternative has the best evaluation, and the result as the alternative that satisfies it (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 152). AeroLink’s DEC-001 in the reference model is such a study (Week 7’s scores, carried into v0.4).`,`Two consequences shape how the course uses analysis cases (instructor reasoning from these slides). First, an analysis case says how a number is obtained, so a TPM estimate can be a result with its inputs in the model instead of a number typed in by hand. Second, the objective is a requirement on the result, which makes it a place where a limit can be duplicated. If the objective repeats “0.20” while the requirement says “0.20”, the two can drift apart in the next change; binding the objective’s limit to the requirement’s attribute keeps one fact in one place.`],citations:[{reading:`R75`,pages:`92–95`},{reading:`R78`,pages:`152`}],provenance:`mixed`},{id:`w13-worked-analysis`,kind:`worked-example`,title:`Worked example (a): an analysis case for TPM-003, compared with REQ-SYS-003`,paragraphs:[`The listing aerolink_tpm003_landing_reserve_analysis.sysml computes TPM-003, the landing energy reserve on the 25 km design trip, which the reference records as a typed-in 23 % (FICTIONAL). Two calculation definitions hold the physics: TripEnergy adds terminal-phase and cruise energy (power × time), and LandingEnergyFraction returns the share of usable energy left after the trip (lines 30–41). The analysis definition LandingReserveAnalysis (lines 42–64) has the flight-planning function as its subject, an objective with an assumed constraint (capacity retained between 0 and 1) and a required constraint on the result, input parameters for the energy figures, and returns landingFraction (line 63).`,`The usage designTripAnalysis (lines 71–80) binds the configuration. Its minimumFraction is bound to REQ-SYS-003’s own attribute (line 73), so the limit is written once. The flight-operations part sets MOP-005 to the analysis result (line 69), as on Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 94, and the context asserts satisfy REQ-SYS-003 (line 82). TPM-003’s margin is an expression (line 81), not a stored number. The inputs are new FICTIONAL teaching values chosen to reproduce the reference estimate; the table shows the computation, which you can repeat by hand or in the what-if analyser.`,`The comparison with the requirement is the point of the analysis. 23.0 % against a 20 % minimum is a margin of 3.0 percentage points on the estimate; with Week 5’s 1.5-point contingency the worst case is 21.5 %, still above 20 %. The same model also answers the reverse question: the reserve is lost once end-of-life capacity falls below 88.5 % of the beginning-of-life value (106.25 kWh), which is about the “more than 10 % fade” of R-002’s statement.`,`The checker accepted the listing with no messages. The probes in the second table show what that acceptance covers (release 2026-08, 2026-10-11; files in the notes). Names, references and some typing are checked; no expression is evaluated, no unit is checked for its kind, and no result is compared with any requirement. The satisfy on line 82 is an assertion the checker does not test: the model would pass just as well with a result of 9 %.`],sysml:[{file:`week13/aerolink_tpm003_landing_reserve_analysis.sysml`,caption:`An analysis case that computes TPM-003 from energy inputs, binds its objective to REQ-SYS-003 and asserts the requirement on the result (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 92–94) (FICTIONAL values)`,intent:`conformant`}],table:{caption:`The analysis by hand (FICTIONAL inputs; reproduced by src/activities/week13/logic.test.ts)`,header:[`Step`,`Expression`,`Value`],rows:[[`Trip energy`,`400 kW × 6 min + 270 kW × 10 min`,`40 + 45 = 85 kWh`],[`Usable energy at end of life`,`120 kWh × 0.92`,`110.4 kWh`],[`Landing fraction (TPM-003 estimate)`,`(110.4 − 85) / 110.4`,`0.230 = 23.0 %`],[`Margin on the estimate; worst case`,`23.0 − 20; (23.0 − 1.5) − 20`,`3.0 points; 1.5 points`],[`Capacity retained at which the reserve is lost`,`85 / (1 − 0.20) / 120`,`0.885 (88.5 %)`]]},citations:[{reading:`R75`,pages:`92–94`}],provenance:`mixed`},{id:`w13-probes`,kind:`concept`,title:`What the checker does with analysis constructs`,paragraphs:[`Read the table as evidence about one release of one tool, not as a rule of the language. Three patterns matter for your L13 model. A name that does not resolve fails: a misspelt result, an undefined unit such as kWh (write kW * h), or an enumeration value copied from a slide’s abbreviation. Some type mismatches give a warning but still pass: a number with no unit bound to a quantity, a result declared with the wrong type, a subject of the wrong definition. And everything about meaning passes in silence: a dimensionally wrong formula, a value in a unit of the wrong kind, a violated assumption, a reversed objective, a missing calculation argument, a literal limit that differs from the requirement, and a satisfy whose bound value violates the requirement.`],table:{caption:`Recorded checker behaviour (release 2026-08, 2026-10-11; probe files a01–a14 and c01–c13 in the notes)`,header:[`Construct in an analysis listing`,`Recorded result`],rows:[[`Worked example (a) as written`,`PASS, no message`],[`Objective names a misspelt result; no return result declared but used`,`FAIL: “Couldn’t resolve reference to Element …”`],[`Input written as 130 [kWh]`,`FAIL: “Couldn’t resolve reference to Element ‘kWh’”`],[`Unitless 18 bound to a DurationValue; result declared EnergyValue for a Real; subject bound to a part of another definition`,`PASS with WARNING “Bound features should have conforming types” (each)`],[`Power + energy in one sum; 6 [kW] passed as a duration; capacity retained 8.5 against its assumption; objective reversed`,`PASS, no message (each)`],[`Calculation called with one argument missing; objective with a literal 0.18 instead of the requirement’s 0.20`,`PASS, no message (each)`],[`MOP-005 bound to 0.18 and satisfy REQ-SYS-003 (≥ 0.20) asserted`,`PASS, no message`]]},citations:[],provenance:`instructor-authored`},{id:`w13-impact`,kind:`concept`,title:`Impact analysis by traversal: direction, order and stopping rules`,paragraphs:[`An impact analysis starts from a changed element and asks which other elements must be re-examined. The naive method follows every link, in both directions, a fixed number of hops; the app’s engineering model offers that as impactSet. On the reference, REQ-SYS-001 reaches 9 elements in one hop, 28 in two and 63 in three, nearly a third of the 203 other elements. A set that large is not wrong so much as useless: it does not say what to do with each element, and the reviewer cannot tell which entries matter.`,`The course method (a convention, not taken from a reading) uses the meaning of each link type. For each link it asks whether the element at the other end depends on the changed element. A child requirement depends on its parent (derives-from, refines); both ends of satisfies, allocated-to, verifies, measures and performs depend on each other; a risk depends on its mitigator; the target of an affects link depends on its source, and a risk or technology assessment about the changed element is re-opened; a consumer depends on its producer (flows-to). Dependents form the first-order set, each with the question the link implies. An upstream element, such as the parent of a changed child or an assumption about it, is reviewed for consistency, but the walk does not continue through it.`,`Second order is a decision, not a hop count. Each first-order element is re-checked; if the check passes, nothing propagates from it. Only the elements that must change in response open a second hop. This is where the traversal meets engineering judgement, and it is what RB-9.5 rewards: an impact set derived from relationships with the method shown, second-order effects, consequences for verification and risk, and a recommendation.`,`Verification is the consequence most often missed. A verdict was obtained for a stated criterion on a stated configuration; DoD guidance asks that each design change be assessed against the qualified baseline and may require parts of the verification to be repeated (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150, a Week 12 reading). In the model this is a verifies link, so every VER that reaches the changed requirement goes on the re-run list.`],citations:[{reading:`R49`,pages:`150`}],provenance:`mixed`},{id:`w13-worked-impact`,kind:`worked-example`,title:`Worked example (b): REQ-SYS-001 tightened from 20 to 18 min, hop by hop`,paragraphs:[`Suppose the city asks AeroLink to shorten the hub turnaround, and the team proposes tightening REQ-SYS-001 from 20 to 18 min (FICTIONAL). The explorer, run on the reference, gives 8 dependents at hop 1 and one upstream element. REQ-STK-005 is upstream: the child still contributes to the 25 min turnaround (5 + 18 ≤ 25), but the parent’s rationale, “25 min is the 20 min charge plus 5 min”, is now stale and should be corrected; nothing propagates through it.`,`The decisive first-order check is TPM-001. Its threshold becomes 18 min against an estimate of 18 min, so the margin on the estimate falls from 2 to 0 min; with Week 5’s month-9 contingency of 0.6 min the worst case is 18.6 min, a margin of −0.6 min, a breach under Week 5’s rule R1. The current charger design therefore cannot be shown to meet the new value, so PHY-003 must change (or the change is refused). Ticking PHY-003 opens six second-order elements. The most consequential is REQ-SYS-010, the vertiport charging power limit: a faster charge draws more power, and that limit is still TBD-02, pending U-002. R-005 (grid connection below hub demand) and R-001 re-open with it.`,`The recommendation follows from the numbers, not from the size of the set. Do not accept 18 min now; keep 20 min unless the charger supplier shows an estimated charge time of 17.4 min or less (so that the worst case, with the 0.6 min contingency, stays within 18 min; 16.4 min would be needed to sit at TPM-001’s 1 min alert floor), and unless the grid limit closes with headroom for the higher power. Record the decision as a DEC that affects the impacted elements, so the next reviewer can see why the requirement did not change.`],table:{caption:`Impact of REQ-SYS-001 20 → 18 min on the reference model (course method; computed by the explorer and asserted in logic.test.ts)`,header:[`Hop`,`Element`,`Reached by`,`Question and result`],rows:[[`1`,`TPM-001, MOP-002`,`measures REQ-SYS-001`,`Threshold 20 → 18 min; margin on the estimate 2 → 0 min, worst case −0.6 min: breach (Week 5 rule R1)`],[`1`,`VER-001`,`verifies REQ-SYS-001`,`Criterion “all 30 charges ≤ 20.0 min” must become 18.0; a charge of 19.2 min passed before and fails now: re-run`],[`1`,`PHY-003, IF-005`,`satisfies REQ-SYS-001`,`Can the charger and the power interface deliver 18 min? Not shown (TPM-001): PHY-003 must change`],[`1`,`FN-006`,`REQ-SYS-001 allocated to FN-006`,`Charge-aircraft function: still allocated correctly; re-check its timing`],[`1`,`TECH-001, R-008`,`affect REQ-SYS-001`,`TRL 6 evidence was for 20 min; faster charging heats cells more (thermal runaway): re-assess`],[`up`,`REQ-STK-005`,`REQ-SYS-001 derives from it`,`Still consistent (5 + 18 ≤ 25); rationale text stale: correct it`],[`2`,`REQ-SYS-010, R-005, R-001`,`from PHY-003 (satisfies; affects)`,`Higher charge power against the unagreed grid limit (TBD-02, U-002)`],[`2`,`LOG-002, FN-007, INFO-003`,`from PHY-003 (allocated-to; flows-to)`,`Fleet management, power sharing and charge-session data: re-check`],[`—`,`Naive reach`,`impactSet, both directions`,`9 / 28 / 63 elements within 1 / 2 / 3 hops, with no action attached`]]},citations:[],provenance:`instructor-authored`},{id:`w13-consistency`,kind:`concept`,title:`Parses, consistent, correct: three different claims`,paragraphs:[`Three claims are easy to merge. “The checker accepts it” means the text conforms to the language as this tool implements it: syntax, name resolution against the library, and the implementation’s own validation rules. “The model is consistent” means its facts do not contradict one another: the same quantity has one value wherever it appears, units fit their quantities, references point at the intended elements, and stated text agrees with modelled values. “The model is correct” means it matches the system and the stakeholders’ intent, which only verification and validation can support. Each claim needs different evidence, and a PASS supplies only the first.`,`The probes show where the line falls for the 2026-08 release. A satisfy usage asserts that the requirement is satisfied by the given feature (OMG SysML v2.1 Beta 2, Part 1, p. 168, a Week 8 reading), so a model whose own values violate it is inconsistent; the checker does not notice, because it evaluates no constraint. It also does not compare a TPM threshold with the limit of the requirement it measures, recompute a stored margin, read doc comments, or check that a unit belongs to the declared quantity kind. It does report a reference that no longer resolves, and it warns when two members of one package share a name or short name.`,`Two design habits shift work from the reviewer to the model (course practice). Write a derived value as an expression or a binding to its source, as worked example (a) does for the objective’s limit and the TPM-003 margin, so a change cannot leave a stale copy. And give every element one course ID that is never reused; a renumbered requirement then breaks loudly, as a dangling reference, instead of silently changing what an old ID means.`],citations:[{reading:`R83`,pages:`168`}],provenance:`mixed`},{id:`w13-worked-consistency`,kind:`worked-example`,title:`Worked example (c): a seeded fragment that passes, and one that fails`,paragraphs:[`The listing aerolink_consistency_seeded.sysml is the change of worked example (b) applied badly: the team changed REQ-SYS-001’s value to 18 min and nothing else. It contains six seeded defects. The checker accepts it, with two warnings that point at one of them, the duplicated ID. A reviewer with the fragment table finds the rest. Load the fragment into the consistency review activity, count the defects you see before running the checks, and then compare.`,`The listing invalid_dangling_requirement_id.sysml shows the opposite case. The team issued a new ID, REQ-SYS-011, for the changed requirement (IDs are never reused), but left a satisfy naming REQ-SYS-001. The checker rejects line 23 because the short name no longer resolves. This is the only inconsistency in this week’s examples that the checker reports as an error, and it is reported only because a name stopped resolving, not because the tool understood the change.`],sysml:[{file:`week13/aerolink_consistency_seeded.sysml`,caption:`Seeded fragment: REQ-SYS-001 changed to 18 min and nothing else; six defects for review practice (accepted by the checker with two warnings) (FICTIONAL values)`,intent:`conformant`},{file:`week13/invalid_dangling_requirement_id.sysml`,caption:`Teaching listing: a satisfy still names the old ID after the requirement was renumbered — rejected by the checker`,intent:`intentionally-invalid`}],table:{caption:`The six seeded defects: what the checker did (release 2026-08) and what a reviewer sees`,header:[`Defect`,`Checker`,`Reviewer’s evidence`],rows:[[`REQ-SYS-001 value 18 min, but its name and doc still say 20 min`,`Silent`,`Statement and value disagree: which is the requirement?`],[`TPM-001 threshold still 20 min`,`Silent`,`Threshold ≠ the limit of the requirement it measures`],[`TPM-001 margin stored as 2 min`,`Silent`,`18 − 18 = 0: the margin was computed against the old threshold`],[`A new requirement given the ID REQ-SYS-001 in the same package`,`WARNING “Duplicate of other owned member name” (×2); silent if the two sit in different packages`,`Every reference to REQ-SYS-001 is now ambiguous`],[`ratedPower : PowerValue = 400 [kW * h]`,`Silent`,`An energy unit on a power: kW and kWh confused`],[`padWorkTime = 5 [s] while the doc says 5 min`,`Silent`,`Unit of the right kind, wrong scale; the 25 min arithmetic no longer adds up`]]},citations:[],provenance:`instructor-authored`},{id:`w13-risk`,kind:`worked-example`,title:`Worked example (d): R-002 as risk metadata and a cause–effect chain`,paragraphs:[`Metadata is additional data that annotates model elements. It is defined with a metadata definition and applied to one or more elements; at its simplest it tags elements so that tools can group them, and subsetting annotatedElement restricts what may be annotated (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 108). Nested features of a metadata definition must be bound to values in the annotation, an annotation in a namespace body is about that namespace by default, and @ is shorthand for the metadata keyword (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 109). The RiskMetadata library defines a Level as a Real from 0.0 to 1.0, standard low, medium and high levels of 0.25, 0.50 and 0.75, a RiskLevel with a probability and an optional impact, and a Risk metadata with total, technical, schedule and cost risk (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 147). ModelingMetadata adds StatusInfo (originator, owner, status such as tbd, tbr or tbc, and a risk), Rationale, Issue and Refinement (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 148).`,`Cause and effect has its own domain library. A Multicausation connects one or more cause occurrences to one or more effect occurrences, and a Causation is the binary case, one cause and one effect, although a cause can separately have several effects (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 158). #cause and #effect tag the ends of a multicausation, and CausationMetadata records whether the causation is necessary or sufficient and a probability (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 159).`,`The listing aerolink_r002_risk_causation.sysml applies both to R-002. The Risk annotation is about REQ-SYS-003, TPM-003 and the flight-operations part, which is RB-5.5’s linkage in the model. Its totalRisk carries the reference’s values, probability 0.6 and impact 0.8: the course 5 × 5 rating (likelihood 3, consequence 4) divided by 5. That mapping is the course’s; the library’s own medium level is 0.50, so do not present one scale as the other. The condition–if–then statement becomes two causations: capacity fade beyond 10 % causes a reserve shortfall, which causes shortened or cancelled flights. The first is marked sufficient but not necessary, because a strong headwind can also cause the shortfall. The checker accepted it with no messages, but it also accepts a probability of 1.5 and a reversed causation (probes r03, r05): the direction of cause and effect is the modeller’s claim.`,`The teaching listing invalid_risk_level_slide_abbreviation.sysml copies sl.147’s abbreviation LevelEnum::M. The checker rejects line 15, because the enumeration it loads defines medium, not M. Copying a slide literally is not the same as checking it.`],sysml:[{file:`week13/aerolink_r002_risk_causation.sysml`,caption:`R-002 with the library Risk metadata about the elements it threatens, and its chain as causation connections with CausationMetadata and StatusInfo (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 147–148, 158–159) (FICTIONAL values)`,intent:`conformant`},{file:`week13/invalid_risk_level_slide_abbreviation.sysml`,caption:`Teaching listing: a risk level copied from the slide’s abbreviation LevelEnum::M — rejected by the checker`,intent:`intentionally-invalid`}],citations:[{reading:`R77`,pages:`108–109`},{reading:`R78`,pages:`147–148`},{reading:`R78`,pages:`158–159`}],provenance:`mixed`},{id:`w13-resilience-ai`,kind:`concept`,title:`Resilience and AI-enabled functions: what a change can break`,paragraphs:[`SEBoK works with the INCOSE Resilient Systems Working Group definition: resilience is the ability to provide required capability when facing adversity, in both the reactive and the proactive perspective (SEBoK v2.14, “System Resilience”, p. 1203). Adversity is any condition that could degrade delivered capability, from inside the system or its environment; the proximate adversities are stresses and their effects on the system are strains (SEBoK v2.14, “System Resilience”, p. 1204). The taxonomy has three layers. The fundamental objectives are to avoid, withstand and recover from adversity (SEBoK v2.14, “System Resilience”, p. 1204). Means objectives, such as anticipate, constrain, degrade gracefully, monitor and tolerate, serve them (SEBoK v2.14, “System Resilience”, p. 1205–1206). Architecture, design and operational techniques, such as loss margins, modularity and loose coupling, realise the means; modularity is defined as composing a system so that a change to one component has minimal impact on the others (SEBoK v2.14, “System Resilience”, p. 1207).`,`Resilience is considered throughout the life cycle and, once its requirements exist, managed with the other requirements in the trade space (SEBoK v2.14, “System Resilience”, p. 1208). Candidate metrics include maximum outage period and depth and the expected availability of the required capability, and resilience requirements are often written as scenarios with a stated adversity, stress, capability, timeframe and target (SEBoK v2.14, “System Resilience”, p. 1209–1210). Applied to AeroLink (instructor reasoning): TPM-003’s margin is a loss margin against capacity fade; shortening or cancelling flights is graceful degradation; R-002’s trigger on the TPM-003 margin is monitoring. An impact analysis that removes a margin also removes resilience, which is worth one line in the recommendation.`,`SEBoK separates AI for SE (AI4SE), which uses AI to improve engineering practice, from SE for AI (SE4AI), which applies SE to intelligent systems (SEBoK v2.14, “Artificial Intelligence”, p. 1369–1370). It names three challenges for engineering intelligent systems: new failure modes (negative side effects, reward hacking, scalable oversight, unsafe exploration and distributional shift), unpredictable performance on unseen data in future operation, and a lack of trust because results must be explainable for expert judgement of compliance (SEBoK v2.14, “Artificial Intelligence”, p. 1371). The system’s intelligence is only as good as its training data (SEBoK v2.14, “Artificial Intelligence”, p. 1370). AeroLink’s AI-001 predictive maintenance is R-002’s treatment and learns from charge-session data; if the turnaround change raises charging power, its future inputs come from a duty it was not trained on, a distributional shift in the source’s terms, so its re-validation belongs in the impact set.`],citations:[{reading:`R24`,pages:`1203–1210`},{reading:`R31`,pages:`1369–1371`}],provenance:`mixed`},{id:`w13-advanced`,kind:`advanced`,title:`Advanced analysis: baselines, commits, and why a diff is not an impact set`,paragraphs:[`Model repositories record change as commits. In the Systems Modeling API and Services versioning model, a Commit lists the data created, updated or deleted in it as data versions, with a deletion recorded as a version with no payload, and its versioned data is the cumulative state of the project at that commit (OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”, p. 33). The versioned data is computed from the change set and from what the previous commits retained, and a commit with two parents must resolve every identity whose versions differ between them by listing it in its own change (OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”, p. 34). Commits are immutable and cannot be deleted in normal use; a branch is a mutable pointer to its head commit; a tag is an immutable pointer used for milestones, releases or baselines (OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”, p. 34–36).`,`Three consequences follow for impact analysis (instructor reasoning from these pages). First, a tag gives the baseline that a verdict refers to: VER-001’s pass was obtained on the model tagged at CP4, and an impact analysis compares the proposed state with that tag. Second, the difference between two commits is the seed of an impact analysis, not its result. In the worked history (commits.ts) the difference between the CP4 tag and the merged head is REQ-SYS-001, TPM-001 and TPM-003; VER-001 does not appear, because nobody edited it, yet the traversal puts it on the re-run list. Third, the merge rule is stricter than intuition suggests: a merge that lists only the identity both branches edited violates the rule for every other identity whose versions differ, so each must be decided, which is a small impact analysis in itself.`,`Impact sets also have errors in both directions (instructor reasoning). The naive traversal has high recall and low precision; the directed method raises precision but can miss a dependency the model never recorded, for example a charger power that is only described in a doc comment. A missing link is a modelling defect that the impact analysis exposes, not a reason to fall back on the naive set.`],citations:[{reading:`R88`,pages:`33–36`}],provenance:`mixed`},{id:`w13-application`,kind:`application`,title:`Aerospace and industry application`,paragraphs:[`In a program, an impact analysis is the engineering content of a change request: what changes, what must be re-verified, which margins and risks move, and what the decision is conditioned on. Exam 2’s T4 asks for exactly this on an unseen model, and the CP5 panel will ask you to show your impact result live (B.6). The habit worth building is to state the method before the list, so that a reviewer can repeat it, and to state which re-checks passed, because a passed re-check is why the set stops.`],citations:[],provenance:`instructor-authored`},{id:`w13-lab`,kind:`lab`,title:`Lab L13 — impact analysis (out of class; kick-off in Session 1)`,paragraphs:[`Choose one S04 Lab 13 question (battery range decreases, demand doubles, or a regulation changes) or an approved alternative. Start from your model v0.4 and its CP4 tag. Derive the impact set with the explorer on your workspace, decide which first-order elements must change, quantify the TPM consequences with the what-if analyser, review the changed fragment for consistency, write a recommendation, record it as a DEC and add a short evolution note on autonomous operations.`],citations:[],provenance:`instructor-authored`},{id:`w13-deliverable`,kind:`deliverable`,title:`Deliverable and assessment`,paragraphs:[`Team: the L13 impact report (method, impact table, TPM what-if, verification re-run list, risk re-assessment, consistency review, recommendation, evolution note) and the DEC in the model, end of Week 13. L13 is formative now and assessed in CP5 under RB-9.5 (impact analysis, 25 points of RB-9). Individual: Exam 2 in Session 2 (RB-14, practical, closed-AI), the knowledge check, and a review-notebook entry with a time log. Graduate students: the commit-based change analysis (template section 7), read and scored formatively on RB-9.5.`],citations:[],provenance:`instructor-authored`}],activities:[{id:`w13-act-impact`,title:`Change-impact explorer`,component:`w13-impact-explorer`,purpose:`State a change, predict, then derive its impact set from the model: hop 1 by the course dependency table with the question each link implies, upstream elements for review, hop 2 only from the elements you decide must change, TPM margin consequences and the naive undirected reach for comparison; screen the recommendation, export the report and record the decision as a DEC with owner and provenance.`,instructions:[`Practice on the reference: REQ-SYS-001 20 → 18 min. Predict the hop-1 count, derive, and tick PHY-003 as must-change.`,`Then switch off practice and run your L13 question on your own workspace; tick only the elements whose re-check fails, and say why in the report.`,`Write the recommendation until the screen shows ✓, export the report into L13 and record the DEC (initials and provenance required).`],objectives:[`B13.1`],inBlock:`w13-worked-impact`},{id:`w13-act-whatif`,title:`TPM margin what-if analyser`,component:`w13-margin-whatif`,purpose:`Edit TPM-001..003 thresholds, estimates and contingencies, or recompute TPM-003 from the analysis case’s energy inputs (S04 Lab 13 battery scenario included), and see margins on the estimate and the worst case, status by the Week 5 rules, the requirement tracked, the verification to re-run and the risks whose trigger fires. Teaching values, labelled analysis-computed.`,instructions:[`Set TPM-001’s threshold to 18 and read the status; then load the battery scenario and read TPM-003 and R-002.`,`For your L13 question, change only what the question changes, and export the table into your report.`],objectives:[`B13.1`,`B13.3`],inBlock:`w13-worked-analysis`},{id:`w13-act-consistency`,title:`Consistency review of a model fragment`,component:`w13-consistency-review`,purpose:`Inspect a fragment table (one row per value-bearing feature), count the inconsistencies yourself, then run cited checks for dangling and duplicated IDs, units of the wrong kind or missing, statements that disagree with values, thresholds and criteria that differ from the requirement, stale margins and satisfied requirements the design values violate — each shown beside what the checker did with the same defect.`,instructions:[`Load the seeded fragment, list the defects you find in your notes, enter your count and run the checks; compare item by item.`,`Load the reference TPM rows (they pass) and the repaired fragment; then enter the rows your L13 change touches and review them.`],objectives:[`B13.2`],inBlock:`w13-worked-consistency`}],lab:{id:`L13`,title:`Impact analysis: use the model to answer a change question`,setting:`team`,durationMinutes:25,objectives:[`B13.1`,`B13.2`,`B13.3`,`B13.4`],inputs:[`Model v0.4 (L12), its checker log and its CP4 tag in the team repository; the workspace model`,`One S04 Lab 13 question: battery range decreases (TECH-002, R-002, REQ-SYS-003, TPM-003), demand doubles (A-006, MGO-007, REQ-STK-004, DEC-001) or a regulation changes (U-001, REQ-STK-003); or an approved alternative`,`Week 5 TPM contingencies and alert floors; the L12 verification cases`,`The listings of worked examples (a), (c) and (d) in sysml/week13; this week’s three activities`],steps:[{title:`In class — kick-off (25 min, Session 1)`,detail:`Choose the question and state the change as “element, value from → to” in one line. Run the explorer on your workspace and save the first-order table. Assign one owner per consequence class: verification, measures, risks, design.`},{title:`Out of class — impact set (method shown)`,detail:`Re-check every first-order element and record the result. Tick as must-change only the elements whose re-check fails, and give the reason. Export the impact report with the method, both hops, the upstream list and the naive reach.`},{title:`Out of class — consequences`,detail:`Quantify each TPM with the what-if analyser (CBE and worst-case margins, status, triggered risks). List the VERs to re-run with the criterion that changes. Re-assess each risk reached (likelihood, consequence, trigger), using library Risk metadata and a causation for the main chain. Review the changed fragment with the consistency activity.`},{title:`Out of class — model update and checker run`,detail:`If the decision changes the model, apply it completely (values, docs, TPM, VER criteria, rationale) and run the checker: zero errors, every warning explained. If the decision is to refuse or defer, change nothing except the DEC and the rationale.`},{title:`Out of class — recommendation and DEC`,detail:`Write the recommendation (decision, affected IDs, condition or reason, one line on resilience) and record it as a DEC in the workspace with owner and provenance; add it to the SysML model as a @Rationale on the affected requirement or as an analysis with a doc.`},{title:`Out of class — evolution note (awareness, ≤ ½ page)`,detail:`Which elements would autonomous operation (TECH-003) touch, by the same traversal from TECH-003? Name one AI V&V challenge it raises (SEBoK v2.14, “Artificial Intelligence”, p. 1371) and one resilience means it needs (SEBoK v2.14, “System Resilience”, p. 1205–1206). This note feeds Week 14’s evolution increment (B14.1).`}],artefacts:[{idPrefix:`Impact report`,description:`Change statement; method; first-order, upstream and second-order tables with the re-check result per element; TPM what-if; VER re-run list; risk re-assessment; consistency review; recommendation; evolution note`,minimum:`Impact set derived from model relationships with the method stated (RB-9.5); every first-order element has a recorded re-check; at least one second-order effect analysed or a reason why none`},{idPrefix:`DEC`,description:`The decision on the change, in the workspace with owner and provenance and affects links to the impacted elements, and as a rationale or analysis in the SysML model`,minimum:`One DEC whose text states the decision, the affected IDs and its condition`},{idPrefix:`R (metadata)`,description:`Library Risk metadata and at least one causation connection for the main cause–effect chain of the change`,minimum:`Accepted by the checker; the probability scale named (course mapping or library level)`}],continuity:`The impact report is the CP5 impact-analysis result that the panel asks to see live (B.6), scored by RB-9.5. The DEC and any model update become part of the CP5 model; a refused or deferred change leaves the model unchanged but adds the decision and its condition. The evolution note seeds Week 14’s evolution increment (B14.1), and Exam 2’s T4 uses the same method on an unseen model.`,tools:[{label:`AeroLink engineering model (workspace)`,to:`/workspace/model`},{label:`Case brief and Data Sheet (FICTIONAL values)`,to:`/workspace/aerolink`}]},assignment:{id:`L13`,title:`L13 impact report and DEC; graduate commit-based change analysis`,mode:`team`,due:`Impact report, DEC and any model update: end of Week 13 (they carry into CP5, due Week 14). Graduate commit-based change analysis: end of Week 13.`,weight:`L13 is formative now; it is assessed summatively in CP5 (14 % of the course grade) under RB-9.5 (impact analysis, 25 points of RB-9). Graduate analysis: review notebook (RB-16, 5 %), always read, with formative feedback on RB-9.5.`,instructions:[`State the change in one line (element, value from → to) and the question it answers.`,`Derive the impact set with the explorer on your own model and record a re-check result for every first-order element.`,`Quantify the TPM, verification and risk consequences; review the changed fragment for consistency.`,`Recommend, record the DEC, and if the model changes, apply the change completely and run the checker (zero errors, warnings explained).`,`Add the evolution note on autonomous operations (≤ ½ page).`,`Graduate students: the commit-based change analysis (template section 7).`,`Log your hours in the review notebook (workload pilot) and attach the team’s AI usage statement.`],template:[{heading:`1. Change and question (B13.1)`,guidance:`One line: element, value from → to, and the S04 Lab 13 question it answers. Name the baseline (the CP4 tag or commit) that the analysis compares against.`},{heading:`2. Method and impact set (RB-9.5; B13.1)`,guidance:`The method in two sentences (dependency table; second hop only from must-change elements). The exported tables: hop 1 with the re-check result per element, upstream list, hop 2 with the reason each source must change, and the naive reach for comparison.`},{heading:`3. Consequences for measures, verification and risk (RB-9.5; B13.3)`,guidance:`The what-if table (margins on the estimate and the worst case, status, rule). The VERs to re-run with the criterion that changes. Each risk reached: likelihood, consequence and trigger before and after; the library Risk annotation and one causation, with the listing lines.`},{heading:`4. Consistency review (B13.2)`,guidance:`The changed fragment’s rows and the findings, your own count first. For each finding, the fix. State in one sentence what the checker run does and does not show for this change.`},{heading:`5. Recommendation and DEC (RB-9.5)`,guidance:`Decision, affected IDs, condition or reason, and one line on what the change does to resilience (SEBoK v2.14, “System Resilience”, p. 1204–1207). The DEC ID and where its rationale sits in the SysML model.`},{heading:`6. Evolution note: autonomous operations (awareness, B13.4)`,guidance:`≤ ½ page: the first-order set from TECH-003, one AI V&V challenge (SEBoK v2.14, “Artificial Intelligence”, p. 1371) and one resilience means (SEBoK v2.14, “System Resilience”, p. 1205–1206).`},{heading:`7. Graduate task: commit-based change analysis (individual, ½–1 page; OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”, p. 32–36)`,guidance:`Using the worked history (C1 tagged cp4-baseline; C2 on main; C3 on a branch; C4 merge) or your team’s own repository: (a) compute the versioned data at C4 by the p.34 rule and the difference from the CP4 tag; (b) say which identities the merge must list in its change set, and why the draft C4 violates the rule; (c) compare the difference with your traversal impact set: which elements appear only in the impact set, and why; (d) explain, with the p.36 table, why the baseline a verdict refers to is a tag and not a branch.`},{heading:`8. AI usage statement (RB-12)`,guidance:`Tool, purpose, prompts, outputs and your evaluation. AI output is never evidence of an impact set, a margin or what the checker accepts; only the model, a recorded run and the cited sources count.`}],rubrics:[`RB-9`,`RB-5`,`RB-12`,`RB-16`],rubricScope:`L13 (formative now, summative in CP5): RB-9.5 on the impact report and DEC (impact set derived by traversal with the method shown; second-order effects; consequences for verification and risk; recommendation). RB-5.5 (linkage of risks to affected elements in the model) as formative feedback on the risk annotations. Graduate commit-based change analysis: required this week (course workload option B: Week 12’s task was optional), read every time under the RB-16 graduate-task rule, with formative feedback on RB-9.5 (does the analysis separate the change seed from the impact set and handle the merge correctly?), informing RB-16.1. Exam 2 is scored separately with RB-14. AI statement: RB-12.1–12.3.`,aiUse:`AI tools may explain link types, critique a recommendation or suggest SysML syntax for metadata. Any AI-generated SysML must be accepted by the checker and explained line by line by its owner (RB-12.3). AI output is never evidence of an impact set, a margin, a verdict or what the checker accepts. Exam 2 is closed-AI. Tag any AI-suggested DEC AI-suggested-reviewed in the recorder.`,objectives:[`B13.1`,`B13.2`,`B13.3`,`B13.4`]},quiz:[{id:`q13-1`,bloom:`Apply`,objective:`B13.1`,prompt:`The city tightens the pad-edge limit: REQ-SYS-002 changes from 65 to 63 dBA. Using the course dependency table on the reference model, which first-order set is right?`,options:[{id:`a`,text:`The 18 elements within two hops in either direction, because noise touches the whole network`,correct:!1,explanation:`That is the naive undirected reach; it attaches no question to any element and includes elements that do not depend on the limit.`},{id:`b`,text:`REQ-STK-002 first, then the design, because a child change must be re-derived from its parent`,correct:!1,explanation:`The parent is upstream of the changed child: it is reviewed for consistency, but the change does not propagate through it.`},{id:`c`,text:`FN-005, MOP-004, PHY-001, R-003, TPM-002 and VER-002; REQ-STK-002 reviewed only`,correct:!0,explanation:`Correct. Satisfies, allocated-to, measures and verifies make both ends dependent, and the risk about the requirement re-opens; the parent is upstream. The same verification logic applies as in Week 12: VER-002’s criterion was set for 65 dBA (OUSD(R&E) Systems Engineering Guidebook, “Verification Process”, p. 150).`},{id:`d`,text:`Only TPM-002 and VER-002, since those are the only elements that hold the number 65`,correct:!1,explanation:`PHY-001 is asserted to satisfy the requirement, so it must be re-checked against the new limit, and R-003 is about it.`}],cite:{reading:`R49`,pages:`150`}},{id:`q13-2`,bloom:`Analyse`,objective:`B13.1`,prompt:`For the 63 dBA change, TPM-002’s estimate is 63.5 dBA with a 1.0 dBA contingency, so the team decides the aircraft (PHY-001) must change. Which second-order element deserves the first check, and why?`,options:[{id:`a`,text:`REQ-SYS-007 block time: a quieter procedure or rotor can change trip time and energy`,correct:!0,explanation:`Correct. From PHY-001 the second hop reaches REQ-SYS-007 (it satisfies it), TECH-002, TECH-003, R-002, LOG-001 and INFO-002; a noise fix that slows or changes the aircraft acts on block time and energy first. How far a change spreads depends on how coupled the elements are (SEBoK’s modularity and loose coupling, SEBoK v2.14, “System Resilience”, p. 1207).`},{id:`b`,text:`None: a second hop is opened only for verification elements, never for design elements like PHY-001`,correct:!1,explanation:`The course rule opens a second hop from any first-order element that must change; PHY-001 must, because TPM-002 is in breach.`},{id:`c`,text:`STK-004 and REQ-STK-002, since the community and its requirement are the source of the change`,correct:!1,explanation:`Both are upstream of REQ-SYS-002; the question is what the aircraft change does to other requirements it satisfies.`},{id:`d`,text:`All 47 elements within three hops, checked in ID order`,correct:!1,explanation:`The undirected three-hop reach has no order of importance and no reason attached to any entry.`}],cite:{reading:`R24`,pages:`1207`}},{id:`q13-3`,bloom:`Evaluate`,objective:`B13.1`,prompt:`A team answers “demand doubles” (A-006: 240 → 480 trips/day). Its report lists CRIT-001 and DEC-001 as the impact set and concludes: “two elements affected; no requirement changes.” Evaluate the report.`,options:[{id:`a`,text:`Sound: the traversal from A-006 gives exactly two dependents, and a derived set needs no further judgement`,correct:!1,explanation:`The first hop is right, but the report never asks whether DEC-001 still holds; a derived first order is not the whole analysis.`},{id:`b`,text:`Too small: list every element within three hops of A-006 so that nothing is missed`,correct:!1,explanation:`A larger undirected set is not more correct; it replaces the decision about DEC-001 with volume.`},{id:`c`,text:`Wrong start: a demand change should start from the stakeholders, not from an assumption`,correct:!1,explanation:`A-006 is where the model records the planning demand, so it is the right seed.`},{id:`d`,text:`Incomplete: DEC-001 must change, which opens REQ-STK-004, ALT-004 and R-001`,correct:!0,explanation:`Correct. DEC-001 states it is valid only near 240 trips/day, so the re-check fails; from DEC-001 the second hop reaches REQ-STK-004 (its capacity value derives from MGO-007’s 80 % rule), ALT-004 and R-001. Resilience requirements belong in the same trade space (SEBoK v2.14, “System Resilience”, p. 1208).`}],cite:{reading:`R24`,pages:`1208`}},{id:`q13-4`,bloom:`Apply`,objective:`B13.2`,prompt:`After a change, a team’s file has REQ-SYS-005 with maxLatency = 45 [s] (was 60), a doc that still says “within 60 s”, and MOP-001 described as “threshold 60 s”. The checker reports zero errors and zero warnings. What should the team conclude?`,options:[{id:`a`,text:`The change is complete, because the checker compares doc text with attribute values when it validates`,correct:!1,explanation:`Doc text is a comment; the course probes found no comparison of text with values.`},{id:`b`,text:`The file parses, but its stated 60 s copies are inconsistent and only review finds them`,correct:!0,explanation:`Correct. A PASS covers syntax, name resolution and the tool’s rules; agreement between statements and values is a consistency check a reviewer makes. Left as it is, a satisfy would assert the 45 s constraint (OMG SysML v2.1 Beta 2, Part 1, p. 168) while the agreed statement says 60 s.`},{id:`c`,text:`The value conflict would have produced the warning “Bound features should have conforming types”`,correct:!1,explanation:`That warning concerns types, such as a unitless number bound to a quantity; 45 [s] and 60 [s] are both durations.`},{id:`d`,text:`Nothing is wrong: docs and measure descriptions are informal and need not match the model`,correct:!1,explanation:`The requirement statement is what stakeholders agreed; if it says 60 s and the constraint says 45 s, the model contradicts itself.`}],cite:{reading:`R83`,pages:`168`}},{id:`q13-5`,bloom:`Analyse`,objective:`B13.2`,prompt:`Four edits are made to a passing model, one at a time. Based on the course probes of release 2026-08, which one makes the checker FAIL the file?`,options:[{id:`a`,text:`attribute maxPower : PowerValue = 350; (no unit)`,correct:!1,explanation:`A unitless number bound to a quantity gave a warning, “Bound features should have conforming types”, and the file still passed.`},{id:`b`,text:`attribute maxPower : PowerValue = 350 [kW * h]; (an energy unit)`,correct:!1,explanation:`A unit of the wrong kind passed with no message in the probes; only a reviewer catches it.`},{id:`c`,text:`satisfy Requirements::'REQ-SYS-010' after REQ-SYS-010 was renumbered REQ-SYS-013`,correct:!0,explanation:`Correct. The short name no longer resolves, so the checker reports an error and the file fails, as with the dangling-reference listing; a satisfy must name a requirement (OMG SysML v2.1 Beta 2, Part 1, p. 168).`},{id:`d`,text:`A second requirement with the short name REQ-SYS-010 added in the same package as the first`,correct:!1,explanation:`This gave the warning “Duplicate of other owned member name”; the file still passed.`}],cite:{reading:`R83`,pages:`168`}},{id:`q13-6`,bloom:`Evaluate`,objective:`B13.2`,prompt:`A team’s analysis case for TPM-002 binds in rotorTipSpeed = 140 [kW], returns 63.1 dBA (its doc says), binds MOP-004 to the result and asserts satisfy REQ-SYS-002. The checker reports PASS with no messages. What does this evidence support?`,options:[{id:`a`,text:`That REQ-SYS-002 is verified, since the analysis result is bound and the satisfy was accepted`,correct:!1,explanation:`A satisfy asserts; verification needs evidence that the real system meets the requirement (OMG SysML v2.1 Beta 2, Part 1, p. 168, Week 12).`},{id:`b`,text:`That 63.1 ≤ 65 dBA holds, because the checker evaluates the calculation when it validates the usage`,correct:!1,explanation:`The checker evaluates no expression; 63.1 dBA is the team’s claim, not the tool’s result.`},{id:`c`,text:`Nothing at all: a file with a power unit on a speed could not have passed, so the run was wrong`,correct:!1,explanation:`The probes show exactly that: a unit of the wrong kind on a quantity input passes silently.`},{id:`d`,text:`Only that it resolves and types; the [kW] input and the 63.1 dBA still need review and a hand check`,correct:!0,explanation:`Correct. The PASS says the text conforms; the wrong-kind input went undetected, and the result must be computed and reviewed before the satisfy is credible (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slides 92–94 define what the case computes, not that a tool computed it).`}],cite:{reading:`R75`,pages:`92–94`}},{id:`q13-7`,bloom:`Apply`,objective:`B13.3`,prompt:`R-005 (grid connection below hub demand) is rated likelihood 2, consequence 4 on the course 5 × 5 scale. Following the reference’s mapping, which library Risk annotation is right?`,options:[{id:`a`,text:`totalRisk = new RiskLevel(probability = 0.4, impact = 0.8);`,correct:!0,explanation:`Correct. The reference divides the 5 × 5 ratings by 5 (a course mapping); a Level must lie between 0.0 and 1.0 (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 147).`},{id:`b`,text:`totalRisk = new RiskLevel(probability = 2, impact = 4);`,correct:!1,explanation:`A Level is a Real from 0.0 to 1.0 (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 147); the checker does not evaluate that constraint, so it would pass silently and be wrong.`},{id:`c`,text:`totalRisk = RiskLevelEnum::L;`,correct:!1,explanation:`L is the slide’s abbreviation; the checker rejected LevelEnum::M for the same reason, and the library values are low, medium and high.`},{id:`d`,text:`technicalRisk = LevelEnum::medium;`,correct:!1,explanation:`technicalRisk is a RiskLevel (probability and impact), not a Level, and medium (0.50) is not the 0.4 the mapping gives.`}],cite:{reading:`R78`,pages:`147`}},{id:`q13-8`,bloom:`Analyse`,objective:`B13.3`,prompt:`A team models R-005 as a causation “connection curtailed → turnaround over 25 min”. R-005 says a curtailed connection does push turnaround over 25 min; a charger fault can do the same. How should its CausationMetadata be set?`,options:[{id:`a`,text:`isNecessary = true; isSufficient = false: long turnarounds need a curtailed connection`,correct:!1,explanation:`A charger fault also causes long turnarounds, so curtailment is not necessary for them.`},{id:`b`,text:`probability = 0.4, copied from the 5 × 5 likelihood of R-005 divided by 5`,correct:!1,explanation:`The likelihood is the chance the risk occurs; that is not the same quantity as the probability attached to the causation. Do not merge the two.`},{id:`c`,text:`isNecessary = false; isSufficient = true`,correct:!0,explanation:`Correct. Curtailment alone produces the effect (sufficient), and another cause can produce it too (not necessary); CausationMetadata records both flags (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 159).`},{id:`d`,text:`No metadata: a causation connection already states whether the cause is necessary`,correct:!1,explanation:`A Causation only connects a cause to an effect (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 158); necessity and sufficiency are recorded by the metadata.`}],cite:{reading:`R78`,pages:`158–159`}},{id:`q13-9`,bloom:`Understand`,objective:`B13.4`,prompt:`When a hub closes for weather, AeroLink keeps running a reduced timetable from the spokes instead of stopping service. Which fundamental objective and means objective of SEBoK’s resilience taxonomy does this serve?`,options:[{id:`a`,text:`Avoid, by evade: the network steers its aircraft away from the closed hub`,correct:!1,explanation:`Evading avoids the adversity through design or action; here the closure has happened and capability is reduced.`},{id:`b`,text:`Recover, by repair: the hub is fixed and capability is replenished`,correct:!1,explanation:`Nothing is repaired; recovery comes later, when the hub reopens.`},{id:`c`,text:`Avoid, by prevent: backup power keeps the hub open in bad weather`,correct:!1,explanation:`Prevent precludes the strain; the hub is closed, so the strain is present.`},{id:`d`,text:`Withstand, by degrade gracefully: partial useful service instead of none`,correct:!0,explanation:`Correct. Withstanding resists capability degradation under stress, and degrading gracefully moves to a desirable degraded state with partial useful function (SEBoK v2.14, “System Resilience”, p. 1204–1205).`}],cite:{reading:`R24`,pages:`1204–1205`}},{id:`q13-10`,bloom:`Understand`,objective:`B13.4`,prompt:`AI-002 forecasts demand from Year-1 bookings. In Year 2 an employer moves next to a spoke and demand on two vertiport pairs doubles. Which challenge from SEBoK’s AI article does this illustrate, and what does it imply for V&V?`,options:[{id:`a`,text:`Distributional shift: validation on past data cannot vouch for unseen future data; re-validate`,correct:!0,explanation:`Correct. SEBoK lists distributional shift among the new failure modes and notes that ML performance on unseen future data is hard to predict, which challenges validation before operation (SEBoK v2.14, “Artificial Intelligence”, p. 1371).`},{id:`b`,text:`Reward hacking: the forecaster has learned to game the reward function it was trained against, inflating demand`,correct:!1,explanation:`A supervised forecaster has no reward function to game; the inputs have changed, not the objective.`},{id:`c`,text:`Unsafe exploration: the model tries risky forecasts in operation to learn faster`,correct:!1,explanation:`Exploration concerns learning by trial in operation, as in reinforcement learning; AI-002 does not act on the world.`},{id:`d`,text:`None: a forecast that was validated once is valid for the rest of the life cycle`,correct:!1,explanation:`SEBoK’s point is the opposite: performance on future, unseen data is the hard part (SEBoK v2.14, “Artificial Intelligence”, p. 1371).`}],cite:{reading:`R31`,pages:`1371`}},{id:`q13-11`,bloom:`Evaluate`,objective:`B13.2`,prompt:`A team’s charge-time analysis case has an objective with require constraint { chargeTime <= 20 [min] }. Last week REQ-SYS-001 was changed to 18 min. The team computes the analysis by hand and gets 19 min, then records “analysis objective met; satisfy REQ-SYS-001 holds”. Which judgement is right?`,options:[{id:`a`,text:`Right: the objective is the requirement on the analysis, and it is met at 19 min`,correct:!1,explanation:`The objective is a requirement on the result of the analysis (Seidewitz, Intro to the SysML v2 Language: Textual Notation, slide 92), but this one still holds the old limit, so meeting it shows nothing about 18 min.`},{id:`b`,text:`Wrong: the objective’s literal limit drifted; REQ-SYS-001 is not met at 19 min`,correct:!0,explanation:`Correct. A duplicated literal drifted from the requirement, so the satisfy now asserts something the team’s own number contradicts. Bind the objective’s limit to the requirement’s attribute.`},{id:`c`,text:`Right, provided the checker accepts the file, since it compares objectives with requirements`,correct:!1,explanation:`The probes found a literal limit that differs from the requirement passing silently.`},{id:`d`,text:`Undecidable until VER-001 is re-run, because analyses cannot contradict requirements`,correct:!1,explanation:`A computed 19 min against an 18 min limit is already a contradiction in the model; VER-001 must be re-run as well.`}],cite:{reading:`R75`,pages:`92`}},{id:`q13-12`,bloom:`Apply`,objective:`B13.1`,prompt:`The battery supplier lowers end-of-life capacity retained from 92 % to 88 %; nothing else changes. With worked example (a)’s energy model (120 kWh usable new, 85 kWh trip) and Week 5’s TPM-003 contingency of 1.5 points and alert floor of 1 point, what is TPM-003’s estimate and status?`,options:[{id:`a`,text:`23.0 %, on track: the trip energy is unchanged, so the landing reserve is unchanged`,correct:!1,explanation:`The reserve is a share of end-of-life usable energy, which falls to 105.6 kWh.`},{id:`b`,text:`19.5 %, breach: margin −0.5 points on the estimate, −2.0 on the worst case`,correct:!0,explanation:`Correct. (105.6 − 85) / 105.6 = 0.195; the worst case 18.0 % is below 20 %, so Week 5 rule R1 applies, and R-002’s trigger (margin below 1 point) fires.`},{id:`c`,text:`19.0 %, breach: a 4-point fall in capacity is a 4-point fall in the reserve`,correct:!1,explanation:`The relation is not one-to-one: the fraction is (E − 85) / E, which gives 19.5 %.`},{id:`d`,text:`19.5 %, at risk: the shortfall is within the contingency, so it is not yet a breach`,correct:!1,explanation:`The estimate itself is below 20 %; the contingency makes the worst case lower still, not higher.`}],cite:{reading:`R75`,pages:`93`}}],instructorNotes:{sessions:[],misconceptions:[],facilitation:[],answerKey:[],cautions:[]},workload:[{activity:`In-class sessions (Session 1: worked impact example and L13 kick-off; Session 2: Exam 2)`,hours:2.5},{activity:`Core readings narrowed to the pages the lesson uses: Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Analysis Case Definitions”, slides 92–95, Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Metadata”, slides 108–109, Seidewitz, Intro to the SysML v2 Language: Textual Notation, “Standard View Definitions and Domain Libraries (metadata, analysis, cause and effect, requirements derivation)”, slides 147–148, 152, 158–159 (11 slides at ≈ 30 sl/h); SEBoK v2.14, “System Resilience”, p. 1203–1205, 1208–1210 and SEBoK v2.14, “Artificial Intelligence”, p. 1368–1371 (10 pp at ≈ 15 pp/h)`,hours:1},{activity:`Online lesson and the three activities (explorer and analyser practice on the reference; consistency review of the seeded fragment)`,hours:1},{activity:`Knowledge check (12 items)`,hours:.3},{activity:`Exam 2 preparation: review of Weeks 9–12 model skills (realistic ≥ 1 h; see cautions)`,hours:.5},{activity:`L13 out of class: impact set with re-checks, consequences, risk metadata, consistency review, recommendation and DEC, evolution note (team share)`,hours:2.5},{activity:`Graduate commit-based change analysis: OMG Systems Modeling API and Services v1.1 Beta 2, “7.1 API Model”, p. 33–36 (4 pp) and ½–1 page answering (a)–(d)`,hours:1},{activity:`Review notebook entry, time log and AI statement`,hours:.2}],references:[{reading:`R88`,pages:`32–36`},{reading:`R83`,pages:`168`},{reading:`R49`,pages:`150`},{reading:`R32`,pages:`1374–1375`}],review:{status:`self-checked`,openIssues:[]}},k=Object.fromEntries(Object.entries(Object.assign({"./week01.ts":n,"./week02.ts":r,"./week03.ts":a,"./week04.ts":l,"./week05.ts":d,"./week06.ts":p,"./week07.ts":h,"./week08.ts":_,"./week09.ts":y,"./week10.ts":x,"./week11.ts":C,"./week12.ts":T,"./week13.ts":D})).map(([e,t])=>{let n=parseInt(e.match(/week(\d\d)\.ts$/)[1],10);if(t.default.week!==n)throw Error(`${e} declares week ${t.default.week}`);return[n,t.default]})),A=e=>t(e)?.status===`template`,j=Object.fromEntries(Object.entries(k).filter(([e])=>A(Number(e))));function M(e){return j[e]}var N=new Set([1]);function P(e){return N.has(e)?void 0:k[e]}export{c as a,s as i,P as n,M as r,j as t};